__AGENT_VERSION__ = "v1.6.1"
INSPIRE_VERSION_TAGS = {"inspire_version": __AGENT_VERSION__, "dbx_inspire_ai_version": __AGENT_VERSION__}
INSPIRE_TEST_TAG = "dbx_inspire_ai_test"


def inspire_test_tags() -> dict:
    try:
        value = dbutils.widgets.get(INSPIRE_TEST_TAG)
    except Exception:
        value = ""
    value = str(value or "").strip()
    value = JobLauncher._sanitize_tag(value) if value else ""
    return {INSPIRE_TEST_TAG: value} if value else {}


def inspire_run_tags() -> dict:
    return {**INSPIRE_VERSION_TAGS, **inspire_test_tags()}


def inspire_identity_tags(business, session_id, launcher_source: str) -> dict:
    session = str(session_id)
    return {"dbx_inspire_ai_business": str(business or ""), "dbx_inspire_ai_session": session,
            "dbx_inspire_ai_session_id": session, "dbx_inspire_ai_launcher_source": launcher_source, **inspire_run_tags()}

def inspire_usecase_name_tag(name, limit=None) -> str:
    """The use case NAME tag value: the full name in lower snake_case. Python mirror of useCaseNameTag in app/backend/lib/inspireJobParams.js."""
    import unicodedata
    limit = int(limit or JobLauncher.tag_value_max())
    folded = "".join(" " if ord(ch) >= 128 else ch for ch in unicodedata.normalize("NFKD", str(name or ""))
                     if not 0x300 <= ord(ch) <= 0x36F)
    slug = re.sub(r"[^a-z0-9]+", "_", folded.lower()).strip("_")
    if len(slug) <= limit:
        return slug
    boundary = slug[: limit + 1].rfind("_")
    return (slug[:boundary] if boundary > 0 else slug[:limit]).rstrip("_")


def inspire_usecase_name_tags(name) -> dict:
    value = inspire_usecase_name_tag(name)
    return {"dbx_inspire_ai_usecase": value, "dbx_inspire_ai_usecase_name": value} if value else {}


