def inspire_uc_display_name(uc) -> str:
    user_named = " ".join(str(uc.get("user_use_case_name") or "").split())
    return user_named or uc.get("Name", "")


def inspire_title_case(text) -> str:
    """REQ-182: the one title-case rule for a use case name. Each word is capitalised except the small words, which stay lower
    case after the first word. A word that is all capitals (KPI, UAE) or has inner capitals (eBay, iPhone) keeps its spelling. A
    Data Filter label keeps the spelling it was typed with. The name writer and the title normaliser
    both call this, so the stored name and every title derived from it use the same casing."""
    def cased(index, word):
        if word.isupper() or any(ch.isupper() for ch in word[1:]):
            return word
        if word.lower() in ("to", "by", "and", "or", "the", "of", "in", "on", "for", "from", "with", "through", "via", "without") and index:
            return word.lower()
        return word.capitalize()
    source = " ".join(cased(i, w) for i, w in enumerate(str(text or "").split()))
    return restore_label_text(source, DATA_FILTER_LABEL["text"])


def set_use_case_name(uc, text, typed: bool = False) -> None:
    """REQ-182: the one writer of a use case's name. Every pass that changes the name calls this. Name and usecase take the same
    text, cleaned by the rule that derives name_with_technique (backticks and em dashes out, whitespace collapsed). A generated
    name takes the title-case rule (typed=False). A name the person typed, pinned or requested is kept word for word (typed=True).
    The tracking use_case column, Name and name_with_technique therefore always read one value."""
    name = DatabricksInspire._doc_display(text)
    uc["Name"] = uc["usecase"] = name if typed else inspire_title_case(name)


def inspire_apply_user_use_case_name(uc: dict) -> bool:
    """REQ-175 / 10B: the name the person typed is the use case name on every surface. Name, usecase and user_named take it and the
    generated name is kept as original_name. Idempotent: a row that already carries it is left as it is (one field, one value)."""
    override = DatabricksInspire._doc_display(" ".join(str(uc.get("user_use_case_name") or "").split()))
    if not override or uc.get("Name") == override:
        return False
    uc["original_name"] = uc.get("Name") or uc.get("usecase") or ""
    set_use_case_name(uc, override, typed=True)
    uc["user_named"] = uc["Name"]
    return True


def compute_result_table_name(use_case_id: str, use_case_name: str, tables_involved: str, inspire_database: str = "",
                              session_id=None, business_name=None, clash: int = 0) -> str:
    """
    Compute the Unity Catalog result table name for a use case.
    
    Format: `<catalog>`.`<schema>`.`_inspire_<id>_<name>`, every part backtick-quoted.
    
    Rules:
        - Catalog and schema come from the user-provided inspire_database (catalog.schema format,
          backticks optional); without one the documented placeholder `main`.`_inspire` is used
        - Prefix is always '_inspire_'
        - Use case ID and name are lowercased with every run of non [a-z0-9] characters turned into one underscore
        - With a session id the name ends with _s<session id>, so the same use case id of two Discover sessions in one
          Inspire Database never shares a table
        - Table part capped at 200 chars (Unity Catalog allows 255 per identifier)
        - With business_name set, the App wizard's rule: `<catalog>`.`_inspire_<business>_<id>`.`<id>_results`, and
          `_inspire_<business>_<id>__<clash>` when that schema already belongs to something else
    """
    def _snake(value):
        return re.sub(r'[^a-z0-9]+', '_', str(value or '').lower()).strip('_')

    if business_name is not None:
        catalog, _schema = parse_two_level_name(inspire_database) if inspire_database else (None, None)
        if not catalog:
            raise ValueError("the Inspire database names the catalog of the use case schema")
        uc = _snake(use_case_id)[:40]
        tail = f"{USE_CASE_SCHEMA_CLASH_MARK}{int(clash)}" if clash and int(clash) > 1 else ""
        return build_fqn(catalog, inspire_use_case_schema_name(use_case_id, business_name, session_id, tail), f"{uc}_results")

    sid = str(session_id).strip() if session_id is not None else ""
    suffix = f"_s{sid}" if sid.isdigit() else ""
    table_name = "_".join(part for part in ("_inspire", _snake(use_case_id), _snake(use_case_name)) if part)[:200 - len(suffix)] + suffix
    catalog, schema = parse_two_level_name(inspire_database) if inspire_database else (None, None)
    if not catalog or not schema:
        catalog, schema = "main", "_inspire"
    return build_fqn(catalog, schema, table_name)

USE_CASE_SCHEMA_PREFIX = "_inspire"
USE_CASE_SCHEMA_CLASH_MARK = "__"
USE_CASE_SCHEMA_OLD_SID_DIGITS = 5


def inspire_use_case_schema_name(use_case_id, business_name, session_id, tail: str = "") -> str:
    sid = str(session_id).strip() if session_id is not None else ""
    if not re.fullmatch(r"[0-9]+", sid):
        raise ValueError("a numeric session id is needed to name the use case schema")
    uc = re.sub(r'[^a-z0-9]+', '_', str(use_case_id or '').lower()).strip('_')[:40]
    if not uc:
        raise ValueError("a use case id is needed to name the use case schema")
    tail = f"{uc}{tail}"
    room = max(0, 255 - len(USE_CASE_SCHEMA_PREFIX) - len(tail) - 2)
    business = re.sub(r'[^a-z0-9]+', '_', str(business_name or '').lower()).strip('_')[:room].rstrip('_')
    return "_".join(part for part in (USE_CASE_SCHEMA_PREFIX, business, tail) if part)


def parse_three_level_name(name: str) -> tuple:
    """
    Parse a three-level name (catalog.schema.table or catalog.schema.column) into parts.
    Handles names with or without backticks at any level.
    
    Args:
        name: A three-level name like "catalog.schema.table" or "`cat`.`sch`.`tbl`"
        
    Returns:
        Tuple of (part1, part2, part3) with backticks stripped from each part,
        or (None, None, None) if parsing fails
        
    Examples:
        parse_three_level_name("cat.schema.table") -> ("cat", "schema", "table")
        parse_three_level_name("`cat`.`my-schema`.`table`") -> ("cat", "my-schema", "table")
        parse_three_level_name("invalid") -> (None, None, None)
    """
    if not name:
        return (None, None, None)

    clean_name = name.replace('`', '')
    parts = clean_name.split('.')

    if len(parts) == 3:
        return (parts[0].strip(), parts[1].strip(), parts[2].strip())
    return (None, None, None)

def parse_two_level_name(name: str) -> tuple:
    """
    Parse a two-level name (catalog.schema) into parts.
    Handles names with or without backticks.
    
    Args:
        name: A two-level name like "catalog.schema" or "`cat`.`my-schema`"
        
    Returns:
        Tuple of (part1, part2) with backticks stripped from each part,
        or (None, None) if parsing fails
        
    Examples:
        parse_two_level_name("cat.schema") -> ("cat", "schema")
        parse_two_level_name("`cat`.`my-schema`") -> ("cat", "my-schema")
    """
    if not name:
        return (None, None)

    clean_name = name.replace('`', '')
    parts = clean_name.split('.', 1)

    if len(parts) == 2:
        return (parts[0].strip(), parts[1].strip())
    return (None, None)

def build_fqn(catalog: str, schema: str, table: str = None) -> str:
    """
    Build a fully qualified name with proper backtick quoting.
    
    Args:
        catalog: Catalog name (will be normalized and quoted)
        schema: Schema name (will be normalized and quoted)
        table: Optional table name (will be normalized and quoted if provided)
        
    Returns:
        Properly quoted FQN like `catalog`.`schema` or `catalog`.`schema`.`table`
        
    Examples:
        build_fqn("cat", "my-schema") -> "`cat`.`my-schema`"
        build_fqn("cat", "schema", "table") -> "`cat`.`schema`.`table`"
    """
    cat_quoted = inspire_quote_identifier(catalog)
    schema_quoted = inspire_quote_identifier(schema)

    if table:
        table_quoted = inspire_quote_identifier(table)
        return f"{cat_quoted}.{schema_quoted}.{table_quoted}"
    return f"{cat_quoted}.{schema_quoted}"

