def name_verb_share_flags(names, bar=USE_CASE_NAME_VERB_SHARE_BAR) -> set:
    """REQ-414: positions of names led by a top-five verb, when those five start at least `bar` of 10+ names."""
    firsts = []
    for name in names:
        words = re.findall(r"[A-Za-z]+", str(name or ""))
        firsts.append(words[0].lower() if words else "")
    counts = {}
    for verb in firsts:
        if verb:
            counts[verb] = counts.get(verb, 0) + 1
    if len(firsts) < 10 or not counts:
        return set()
    top = {verb for verb, _n in sorted(counts.items(), key=lambda item: (-item[1], item[0]))[:5]}
    if sum(counts[verb] for verb in top) / len(firsts) < bar:
        return set()
    return {pos for pos, verb in enumerate(firsts) if verb in top}
