# --- Custom Exceptions ---
class InputTooLongError(RuntimeError):
    """Raised when input exceeds the model's context limit."""
    pass

class CascadeRebatchError(RuntimeError):
    """Raised when a model in the cascade timed out and the prompt is too large for remaining models.
    Signals the caller to re-batch with smaller chunks that fit the target model's context window."""
    def __init__(self, message, target_model_name=None, target_model_endpoint=None,
                 target_context_limit_chars=None, failed_model_name=None):
        super().__init__(message)
        self.target_model_name = target_model_name
        self.target_model_endpoint = target_model_endpoint
        self.target_context_limit_chars = target_context_limit_chars
        self.failed_model_name = failed_model_name

class TruncatedResponseError(RuntimeError):
    """Raised when an LLM answer came back empty or cut off. A reasoning model that spends its whole output
    budget before writing any text returns an empty answer, so a batched caller retries the request in
    smaller pieces instead of resending the same batch."""
    pass


def inspire_llm_answer(response, label: str):
    if response is None or not str(response).strip():
        raise TruncatedResponseError(f"{label}: the model returned an empty answer, which it does when it uses its "
                                     f"whole output budget before writing any text")
    return response

class LLMEndpointUnusableError(RuntimeError):
    pass


class NoUsableModelError(LLMEndpointUnusableError):
    pass


class NothingToDiscoverError(RuntimeError):
    pass


class NoUseCasesError(RuntimeError):
    pass


def inspire_failure_kind(error) -> str:
    for kind, cls in (("no_model", NoUsableModelError), ("no_tables", NothingToDiscoverError), ("no_use_cases", NoUseCasesError)):
        if isinstance(error, cls):
            return kind
    return "error"

