def deep_signal_date_sql(column_sql, date_format):
    if date_format is None:
        return f"CAST(try_cast({column_sql} AS TIMESTAMP) AS DATE)"
    return f"CAST(try_to_timestamp({column_sql}, '{date_format}') AS DATE)"


