def implement_named_entity(subject, columns) -> str:
    """The key column the use case names in its own words (franchiseID in \"Coach franchises by franchiseID\"), by the whole-word rule the
    wizard profile uses. A peer comparison's entity is that key when no entity_key role is set (REQ-293)."""
    said = " ".join(str(subject or "").lower().split())
    for name in columns or {}:
        low = str(name).lower()
        if re.search(r"(id|key)$", low) and any(re.search(rf"(^|[^a-z0-9]){re.escape(word)}([^a-z0-9]|$)", said) for word in {low, low.replace("_", " ")}):
            return str(name)
    return ""


def deep_grouping_suggestion(technique, table, profiles, join_matches=(), personal=None, proposed=(), text_tokens=(), sample_rows=None, kind="",
                             entity_key="", subject=""):
    if not inspire_grouping_applies(technique) or inspire_grouping_fits_one_model(technique, kind):
        return None
    main_ref = str(table or "").replace("`", "").strip().lower()
    main = (profiles or {}).get(main_ref) or {}
    entity = implement_peer_entity(technique, kind, entity_key or implement_named_entity(subject, main.get("columns")))
    rows = int(main.get("rows") or 0)
    if rows <= 0 or not main.get("columns"):
        return None
    personal = personal or (lambda _table, _column: False)
    asked = {str(name).replace("`", "").split(".")[-1].strip().lower() for name in proposed or () if str(name or "").strip()}

    def usable_name(table_ref, name, info, numeric_ok):
        low = str(name).lower()
        if entity and low == entity.lower():
            return False
        if personal(table_ref, name) or INSPIRE_TIME_NAME.search(low) or any(token in low for token in text_tokens or ()):
            return False
        family = info.get("type_family")
        if family not in ("string", "boolean", "numeric") or (family == "numeric" and not (numeric_ok or low in asked)):
            return False
        share = info.get("null_share")
        return share is None or float(share) <= INSPIRE_GROUP_MAX_NULL_SHARE

    def candidate(column, info, records):
        values = [v for v in info.get("top_values") or [] if v.get("value") is not None]
        groups = int(info.get("distinct") or 0)
        if values and len(info.get("top_values") or []) >= groups:
            big = sum(1 for v in values if float(v.get("share") or 0) * records >= INSPIRE_GROUP_MIN_RECORDS)
            if big < INSPIRE_GROUP_MIN_GROUPS:
                return None
        profile = {"column": column, "groups": groups, "records": int(records)}
        return profile if inspire_group_column_usable(profile) else None

    joins = [m for m in join_matches or () if str(m.get("child_table") or "").lower() == main_ref and float(m.get("rate") or 0) > 0]
    keys = {str(m.get("child_column") or "").lower() for m in joins}
    found, nests, links = [], [], {}
    own = {str(name).lower(): (name, info) for name, info in main["columns"].items() if isinstance(info, dict)}
    for low, (name, info) in sorted(own.items()):
        if usable_name(main_ref, name, info, low in keys or _is_key_like_column(name)):
            hit = candidate(str(name), info, rows * (1.0 - float(info.get("null_share") or 0)))
            if hit:
                found.append(hit)
    for match in sorted(joins, key=lambda m: (str(m.get("parent_table")), str(m.get("child_column")))):
        parent_ref = str(match.get("parent_table") or "").lower()
        parent = (profiles or {}).get(parent_ref) or {}
        key_name, key_info = own.get(str(match.get("child_column") or "").lower(), (None, {}))
        if not key_name or personal(main_ref, key_name):
            continue
        matched = rows * (1.0 - float(key_info.get("null_share") or 0)) * float(match["rate"])
        key_groups = int(key_info.get("distinct") or 0)
        key_found = str(key_name).lower() in {f["column"].lower() for f in found}
        for name, info in sorted((parent.get("columns") or {}).items()):
            if not isinstance(info, dict) or str(name).lower() == str(match.get("parent_column") or "").lower():
                continue
            if usable_name(parent_ref, name, info, False):
                column = f"{parent_ref.split('.')[-1]}.{name}"
                hit = candidate(column, info, matched * (1.0 - float(info.get("null_share") or 0)))
                if hit and key_found and hit["groups"] >= key_groups:
                    continue
                if hit and column.lower() not in {f["column"].lower() for f in found}:
                    found.append(hit)
                    nests.append((column, str(key_name), hit["groups"] < key_groups))
                    links[column.lower()] = {"table": main_ref, "column": str(key_name), "ref_table": parent_ref,
                                             "ref_column": str(match.get("parent_column") or ""), "source": "deep_discovery",
                                             "confidence": round(float(match["rate"]), 3)}
    named = [f for f in found if f["column"].split(".")[-1].lower() in asked]
    group_by = inspire_group_recommendation(named or found, nests)
    seen = min(rows, int(sample_rows)) if main.get("sampled") and sample_rows else rows
    unique = sorted((str(name) for low, (name, info) in own.items()
                     if info.get("type_family") in ("string", "numeric") and not personal(main_ref, name)
                     and not any(token in low for token in text_tokens or ())
                     and int(info.get("distinct") or 0) >= DEEP_RECORD_UNIQUE_SHARE * seen),
                    key=lambda name: (not _is_key_like_column(name), name.lower()))
    return {"group_by": group_by, "record_level": unique[0] if unique else main_ref.split(".")[-1],
            "joins": [links[name.lower()] for name in group_by if name.lower() in links]}


class DeepEvidence:
    """The only code that reads customer data: aggregates only, every statement logged and counted
    for data_access. Whether the AI may read what it measures is decided by discovery_ai_sees_aggregates."""

    def __init__(self, spark_session, discovery_type, logger, runtime=None, identity=None, metric_views=None, policied=None):
        rt = dict(TECHNICAL_CONTEXT["runtime"]) if runtime is None else dict(runtime)
        self.metric_views = {str(fqn).replace("`", "").lower() for fqn in metric_views or ()}
        self.policied = {str(fqn).replace("`", "").lower() for fqn in policied or ()}
        self.spark = spark_session
        self.discovery_type = canonical_discovery_type(discovery_type)
        self.logger = logger
        self.budget_seconds = float(rt["deep_evidence_budget_seconds"])
        self.statement_timeout_seconds = float(rt["deep_statement_timeout_seconds"])
        self.max_tables = int(rt["deep_max_tables"])
        self.max_columns = int(rt["deep_max_columns_per_table"])
        self.max_value_columns = int(rt["deep_max_value_columns_per_table"])
        self.max_joins = int(rt["deep_max_joins"])
        self.sample_rows = int(rt["deep_sample_rows"])
        self.history_days = int(rt["deep_history_days"])
        self.history_rows = int(rt["deep_history_rows"])
        self.max_kpi_baselines = int(rt["deep_max_kpi_baselines"])
        self.signal_budget_seconds = float(rt.get("deep_signal_budget_seconds",
                                                  TECHNICAL_CONTEXT["runtime"]["deep_signal_budget_seconds"]))
        self.signal_spent_seconds = 0.0
        self.spent_seconds = 0.0
        self.statements = []
        self.skipped_tables = {}
        self.identity = identity
        self._who = None
        self.pii_excluded = set()
        self.date_key_counts = {}
        self._lock = threading.Lock()

    def budget_left(self, budget="evidence") -> float:
        if budget == "signal":
            return self.signal_budget_seconds - self.signal_spent_seconds
        return self.budget_seconds - self.spent_seconds

    @staticmethod
    def value_counts_sql(table: str, column: str) -> str:
        """Distinct values and row counts of one column: aggregates only, the row-level read the Data Filters value picker makes."""
        quoted = inspire_quote_identifier(column)
        return (f"SELECT CAST({quoted} AS STRING) AS v, COUNT(*) AS n FROM {inspire_scoped_read_source(table)} "
                f"GROUP BY {quoted} LIMIT 5000")

    def value_counts(self, table: str, column: str) -> list:
        if self.is_policied(table):
            return []
        return self._read("key_measure", table, self.value_counts_sql(table, column))

    def _read(self, kind, table, sql, args=None, budget="evidence", scopes=None):
        held = [t for t in (table if isinstance(table, (list, tuple)) else [table]) if self.is_policied(t)]
        if held:
            raise DeepEvidencePolicied(f"{held[0]} has a row filter or column mask, so Discover reads its metadata only")
        assert_scoped_reads(sql, f"{kind} on {table}", scopes)
        left = self.budget_left(budget)
        if left <= 0:
            if budget == "signal":
                raise DeepEvidenceBudgetSpent(f"the data signal check budget of {self.signal_budget_seconds:.0f}s is spent")
            raise DeepEvidenceBudgetSpent(f"the data evidence budget of {self.budget_seconds:.0f}s is spent")
        started = time.time()
        status = "ok"
        rows = None
        try:
            if args:
                work = lambda: self.spark.sql(sql, args=args).collect()
            else:
                work = lambda: self.spark.sql(sql).collect()
            rows = _run_tagged_spark_work(self.spark, work,
                                          timeout_seconds=max(5.0, min(self.statement_timeout_seconds, left)),
                                          tag_prefix="deep_evidence", label=f"DeepEvidence {kind}", logger=self.logger)
            return rows
        except Exception as error:
            status = _evidence_error_status(error)
            raise
        finally:
            seconds = round(time.time() - started, 2)
            tables = [str(t) for t in table] if isinstance(table, (list, tuple)) else [str(table)]
            with self._lock:
                if budget == "signal":
                    self.signal_spent_seconds += time.time() - started
                else:
                    self.spent_seconds += time.time() - started
                self.statements.append({"kind": kind, "tables": tables, "status": status, "seconds": seconds,
                                        "rows": len(rows) if rows is not None else 0})
            self.logger.info(f"[DEEP-EVIDENCE] {kind} on {' & '.join(tables)}: {status} in {seconds}s | {sql[:400]}")

    def unreadable_text(self, tables) -> str:
        if self._who is None:
            try:
                self._who = tuple(self.identity()) if self.identity else (inspire_current_user(), "")
            except Exception as error:
                self.logger.warning(f"[DEEP-EVIDENCE] the identity Discover reads as could not be read: {redact_error(error, max_chars=200)}")
                self._who = ("", "")
        return inspire_unreadable_text(tables, self._who[0], self._who[1], reads="Discover reads source tables", per_schema=True)

    def is_policied(self, table_label) -> bool:
        return str(table_label or "").replace("`", "").lower() in (getattr(self, "policied", None) or ())

    def is_metric_view(self, table_label) -> bool:
        return str(table_label or "").replace("`", "").lower() in (getattr(self, "metric_views", None) or ())

    def _plain_table(self, table_label):
        if self.is_metric_view(table_label):
            raise ValueError("this table is a metric view: its rows are not read, only its measures with MEASURE()")

    def _source(self, table_sql, row_count):
        if row_count is not None and row_count > self.sample_rows:
            return f"(SELECT * FROM {table_sql} LIMIT {self.sample_rows}) AS sampled", True
        return table_sql, False

    def count_join(self, anchor_source, joined_sql, label):
        """REQ-373: the guard counts of one joined group in one read: the anchor's rows and the join's rows."""
        rows = self._read("joined_guard", label,
                          f"SELECT (SELECT COUNT(*) FROM {anchor_source}) AS a, (SELECT COUNT(*) FROM ({joined_sql}) AS joined_rows) AS j")
        return int(rows[0]["a"]), int(rows[0]["j"])

    def profile_table(self, table_sql, table_label, columns, column_tags=None, known_rows=None):
        """columns: [(name, data_type)]. Returns aggregates only; values only for non-PII columns
        with at most DEEP_LOW_CARDINALITY_MAX distinct values."""
        column_tags = {str(name).lower(): tags for name, tags in (column_tags or {}).items()}
        profiled = [(name, dtype) for name, dtype in columns
                    if _metadata_type_family(dtype) in DEEP_PROFILED_FAMILIES][:self.max_columns]
        if self.is_metric_view(table_label):
            self.logger.info(f"[METRIC-VIEW FIRED] {table_label} is a metric view, so Discover reads its measures with MEASURE() "
                             "and never counts its rows")
            return None
        if self.is_policied(table_label):
            self.logger.info(f"[POLICIED] {table_label} has a row filter or column mask, so Discover keeps it to metadata and reads no rows")
            return None
        try:
            count_rows = [{"n": known_rows}] if known_rows is not None else self._read("row_count", table_label, f"SELECT COUNT(*) AS n FROM {table_sql}")
        except (DeepEvidenceBudgetSpent, SparkWorkCancelled):
            raise
        except Exception as error:
            self.skipped_tables[table_label] = _evidence_error_status(error)
            named = f": {self.unreadable_text([table_label])}" if self.skipped_tables[table_label] == "denied" else ""
            self.logger.warning(f"[DEEP-EVIDENCE SKIPPED] {table_label}: {self.skipped_tables[table_label]} "
                                f"({redact_error(error, max_chars=200)}); this table stays Standard{named}")
            return None
        row_count = int(count_rows[0]["n"] or 0) if count_rows else 0
        profile = {"rows": row_count, "sampled": False, "columns": {}}
        if row_count == 0 or not profiled:
            return profile
        source, sampled = self._source(table_sql, row_count)
        profile["sampled"] = sampled
        parts = ["COUNT(*) AS `__n`"]
        for index, (name, dtype) in enumerate(profiled):
            column = inspire_quote_identifier(name)
            parts.append(f"COUNT({column}) AS `nn{index}`")
            parts.append(f"approx_count_distinct({column}) AS `dc{index}`")
        try:
            stats = self._read("column_stats", table_label, f"SELECT {', '.join(parts)} FROM {source}")
        except (DeepEvidenceBudgetSpent, SparkWorkCancelled):
            raise
        except Exception as error:
            self.logger.warning(f"[DEEP-EVIDENCE] column stats unavailable for {table_label}: "
                                f"{redact_error(error, max_chars=200)}")
            return profile
        row = stats[0] if stats else None
        sample_n = int(row["__n"] or 0) if row is not None else 0
        temporal = []
        for index, (name, dtype) in enumerate(profiled):
            non_null = int(row[f"nn{index}"] or 0) if row is not None else 0
            distinct = int(row[f"dc{index}"] or 0) if row is not None else 0
            profile["columns"][name] = {"null_share": round(1.0 - (non_null / sample_n), 4) if sample_n else None,
                                        "distinct": distinct, "type_family": _metadata_type_family(dtype)}
            if _metadata_type_family(dtype) == "temporal":
                if deep_column_is_pii(name, column_tags.get(str(name).lower())):
                    self.pii_excluded.add(f"{table_label}.{name}")
                else:
                    temporal.append((index, name))
        if temporal:
            ranges = ", ".join(f"MIN({inspire_quote_identifier(name)}) AS `lo{index}`, MAX({inspire_quote_identifier(name)}) AS `hi{index}`"
                               for index, name in temporal)
            try:
                bounds = self._read("date_range", table_label, f"SELECT {ranges} FROM {table_sql}")
                if bounds:
                    for index, name in temporal:
                        lo, hi = bounds[0][f"lo{index}"], bounds[0][f"hi{index}"]
                        profile["columns"][name]["min"] = str(lo)[:32] if lo is not None else None
                        profile["columns"][name]["max"] = str(hi)[:32] if hi is not None else None
            except (DeepEvidenceBudgetSpent, SparkWorkCancelled):
                raise
            except Exception as error:
                self.logger.warning(f"[DEEP-EVIDENCE] date range unavailable for {table_label}: "
                                    f"{redact_error(error, max_chars=200)}")
        value_columns = []
        for name, dtype in profiled:
            info = profile["columns"].get(name) or {}
            if _metadata_type_family(dtype) not in ("string", "boolean"):
                continue
            if not 0 < (info.get("distinct") or 0) <= DEEP_LOW_CARDINALITY_MAX:
                continue
            if deep_column_is_pii(name, column_tags.get(str(name).lower())):
                self.pii_excluded.add(f"{table_label}.{name}")
                continue
            value_columns.append(name)
        for name in value_columns[:self.max_value_columns]:
            column = inspire_quote_identifier(name)
            try:
                values = self._read("top_values", table_label,
                                    f"SELECT {column} AS v, COUNT(*) AS c FROM {source} GROUP BY {column} "
                                    f"ORDER BY c DESC LIMIT {DEEP_TOP_VALUES}")
            except (DeepEvidenceBudgetSpent, SparkWorkCancelled):
                raise
            except Exception as error:
                self.logger.warning(f"[DEEP-EVIDENCE] top values unavailable for {table_label}.{name}: "
                                    f"{redact_error(error, max_chars=200)}")
                continue
            total = sum(int(r["c"] or 0) for r in values) or 1
            profile["columns"][name]["top_values"] = [
                {"value": None if r["v"] is None else str(r["v"])[:DEEP_VALUE_MAX_CHARS],
                 "share": round(int(r["c"] or 0) / total, 4)} for r in values]
        return profile

    def join_match_rate(self, child_sql, child_label, child_col, parent_sql, parent_label, parent_col):
        if self.is_metric_view(child_label) or self.is_metric_view(parent_label):
            return None
        child_column, parent_column = inspire_quote_identifier(child_col), inspire_quote_identifier(parent_col)
        sql = (f"SELECT COUNT(*) AS n, COUNT(p.k) AS m FROM "
               f"(SELECT {child_column} AS k FROM {child_sql} WHERE {child_column} IS NOT NULL LIMIT {self.sample_rows}) c "
               f"LEFT JOIN (SELECT DISTINCT {parent_column} AS k FROM {parent_sql}) p ON c.k = p.k")
        rows = self._read("join_match", (child_label, parent_label), sql)
        if not rows:
            return None
        n, m = int(rows[0]["n"] or 0), int(rows[0]["m"] or 0)
        return round(m / n, 4) if n else None

    def query_history_statements(self, catalogs=None):
        names = sorted({str(c).replace("`", "").strip().lower() for c in catalogs or [] if str(c).strip()})
        args = {f"c{index}": f"%{name}.%" for index, name in enumerate(names)}
        scope = " OR ".join(f"lower(statement_text) LIKE :c{index}" for index in range(len(names)))
        sql = ("SELECT substring(statement_text, 1, 16000) AS statement_text FROM system.query.history "
               f"WHERE start_time >= current_timestamp() - INTERVAL {int(self.history_days)} DAYS "
               "AND execution_status = 'FINISHED' AND statement_type = 'SELECT' "
               + (f"AND ({scope}) " if scope else "")
               + f"ORDER BY start_time DESC LIMIT {int(self.history_rows)}")
        rows = self._read("query_history", "system.query.history", sql, args=args or None)
        return [str(r["statement_text"] or "") for r in rows or []]

    def deep_calculate(self, plans, on_card, today, scopes=None, concurrency=None) -> dict:
        """REQ-573 R13.2: one `deep_scan` read per pool table (through _read: timeout, scope gate, budget, statement log), at most
        `concurrency` at once. Each table's cards go to on_card as soon as that table finishes."""
        workers = max(1, int(concurrency or TECHNICAL_CONTEXT["runtime"].get("deep_scan_concurrency") or 4))
        spent = threading.Event()
        cards, skipped = [], []

        def scan(plan):
            if spent.is_set():
                return "budget_spent", None
            if self.is_policied(plan["table"]):
                return "policied", None
            try:
                found = self._read("deep_scan", plan["table"], inspire_deep_scan_sql(plan, scopes), scopes=scopes)
                return "ok", [row.asDict() if hasattr(row, "asDict") else dict(row) for row in found or []]
            except DeepEvidenceBudgetSpent:
                spent.set()
                return "budget_spent", None
            except DeepEvidencePolicied:
                return "policied", None
            except SparkWorkTimeout:
                return "timeout", None
            except SparkWorkCancelled:
                raise
            except Exception as error:
                self.logger.warning(f"[DEEP-CALC] the scan of {plan['table']} failed: {redact_error(error, max_chars=200)}")
                return "failed", None

        def deliver(plan, status, found):
            elsewhere = [{"No": item["No"], "rows": None, "share": None, "reason": "different_table"}
                         for other in plans if other is not plan for item in other["use_cases"]]
            if status == "ok":
                try:
                    parsed = inspire_deep_scan_parse(plan, found, today)
                except Exception as error:
                    self.logger.warning(f"[DEEP-CALC] the scan of {plan['table']} could not be read: {redact_error(error, max_chars=200)}")
                    status = "failed"
            if status == "ok":
                out = [{**parsed[item["No"]], "overlap": parsed[item["No"]]["overlap"] + elsewhere} for item in plan["use_cases"]]
            else:
                skipped.append({"table": plan["table"], "reason": status, "use_cases": [item["No"] for item in plan["use_cases"]]})
                out = [{"No": item["No"], "table": plan["table"], "scan_id": plan.get("scan_id"), "status": status, "currencies": [],
                        "overlap": list(elsewhere), "readiness": None, "sensitivity": None} for item in plan["use_cases"]]
            for card in out:
                cards.append(card)
                try:
                    on_card(card)
                except Exception as error:
                    self.logger.warning(f"[DEEP-CALC] delivering the card of {card['No']} failed: {redact_error(error, max_chars=200)}")

        with _SafeExecutorContext(max_workers=workers, thread_name_prefix="DeepScan", logger=self.logger, name="DeepCalculate") as pool:
            futures = {pool.submit(scan, plan): plan for plan in plans}
            try:
                for future in pool.completed(futures):
                    status, found = future.result()
                    deliver(futures[future], status, found)
            except BaseException:
                for future in futures:
                    future.cancel()
                raise
        return {"cards": cards, "skipped": skipped}

    @staticmethod
    def canonical_aggregate(aggregate) -> str:
        aggregate = str(aggregate or "").strip().upper().replace(" ", "_")
        if aggregate not in DEEP_KPI_AGGREGATES:
            raise ValueError(f"Unsupported KPI aggregate {aggregate!r}; valid: {', '.join(DEEP_KPI_AGGREGATES)}")
        return aggregate

    @staticmethod
    def kpi_sql(spec: dict, scopes=None) -> str:
        """The only builder of KPI SQL: a read-only aggregate from a validated spec. Standard mode
        emits this text without running it; the LLM never writes SQL that Inspire executes."""
        if spec.get("metric_view"):
            view_sql = inspire_quote_qualified_name(spec["metric_view"])
            return f"SELECT CAST(MEASURE({inspire_quote_identifier(spec['measure'])}) AS DOUBLE) AS v FROM {view_sql}"
        assert_scope_columns(spec["table"], [spec.get("column"), spec.get("time_column"), spec.get("filter_column"),
                                             (spec.get("denominator") or {}).get("column")], scopes)
        table_sql = inspire_scoped_read_source(spec["table"], scopes)
        denominator = spec.get("denominator")
        conditions = []
        if denominator:
            numerator_sql = DeepEvidence._kpi_aggregate(spec.get("aggregation"), spec.get("column"), spec)
            denominator_sql = DeepEvidence._kpi_aggregate(denominator.get("aggregation"), denominator.get("column"), denominator)
            scale = " * 100" if str(spec.get("unit") or "").strip().lower() in ("%", "percent") else ""
            expression = f"CAST({numerator_sql} AS DOUBLE) / NULLIF(CAST({denominator_sql} AS DOUBLE), 0){scale}"
        else:
            expression = DeepEvidence._kpi_aggregate(spec.get("aggregation"), spec.get("column"), None)
            if DeepEvidence.canonical_aggregate(spec.get("aggregation")) in DEEP_KPI_VALUE_AGGREGATES:
                expression = f"CAST({expression} AS DOUBLE)"
            conditions += [condition for condition in (kpi_filter_sql(spec),) if condition]
        conditions += DeepEvidence._kpi_window_conditions(spec, table_sql)
        if _inspire_value_rate_wanted(spec) and isinstance(spec.get("rate"), dict):
            return DeepEvidence._kpi_rated_sql(spec, table_sql, conditions, scopes)
        where = f" WHERE {' AND '.join(conditions)}" if conditions else ""
        return f"SELECT {expression} AS v FROM {table_sql}{where}"

    @staticmethod
    def _kpi_window_conditions(spec: dict, table_sql: str) -> list:
        if not (spec.get("time_column") and spec.get("window_days")):
            return []
        column = inspire_quote_identifier(spec["time_column"])
        return [f"{column} >= LEAST(current_date(), (SELECT CAST(MAX({column}) AS DATE) FROM {table_sql})) - INTERVAL "
                f"{int(spec['window_days'])} DAYS"]

    @staticmethod
    def _kpi_rate_join(spec: dict, table_sql: str, conditions: list, scopes=None) -> tuple:
        """(FROM text, priced expression): each KPI row joined to the rate with the latest date on or before the row's date, for
        the row's currency and the base currency. A row already in the base currency is priced at 1; a row with no rate has no
        price (NULL). Each rate holds from its date up to the next distinct date, so two rates on one date match one row twice."""
        rate, quote = spec["rate"], inspire_quote_identifier
        assert_scope_columns(spec["table"], [spec.get("currency_column")], scopes)
        assert_scope_columns(rate["table"], [rate[key] for key in INSPIRE_VALUE_RATE_TABLE_KEYS[1:]], scopes)
        rates = inspire_scoped_read_source(rate["table"], scopes)
        base = inspire_sql_literal(rate["base"])
        code, base_column, dated, price = (quote(rate[key]) for key in INSPIRE_VALUE_RATE_TABLE_KEYS[1:])
        currency, day = f"o.{quote(spec['currency_column'])}", f"o.{quote(spec['time_column'])}"
        where = f" WHERE {' AND '.join(conditions)}" if conditions else ""
        spans = (f"SELECT x.{code} AS rc, x.{dated} AS rd0, n.rd1 AS rd1, x.{price} AS rv FROM {rates} AS x JOIN "
                 f"(SELECT {code} AS rc, {dated} AS rd0, LEAD({dated}) OVER (PARTITION BY {code} ORDER BY {dated}) AS rd1 "
                 f"FROM (SELECT DISTINCT {code}, {dated} FROM {rates} WHERE {base_column} = {base}) AS d) AS n "
                 f"ON n.rc = x.{code} AND n.rd0 = x.{dated} WHERE x.{base_column} = {base}")
        joined = (f"(SELECT * FROM {table_sql}{where}) AS o LEFT JOIN ({spans}) AS r ON r.rc = {currency} AND {currency} <> {base} "
                  f"AND {day} >= r.rd0 AND (r.rd1 IS NULL OR {day} < r.rd1)")
        return joined, f"CASE WHEN {currency} = {base} THEN 1 ELSE r.rv END", f"({currency} = {base} OR r.rv IS NOT NULL)"

    @staticmethod
    def _kpi_rated_sql(spec: dict, table_sql: str, conditions: list, scopes=None) -> str:
        joined, priced, _in_base = DeepEvidence._kpi_rate_join(spec, table_sql, conditions, scopes)
        return f"SELECT CAST(SUM(o.{inspire_quote_identifier(spec['column'])} * {priced}) AS DOUBLE) AS v FROM {joined}"

    @staticmethod
    def kpi_guard_sql(spec: dict, scopes=None) -> str:
        """One read-only aggregate over exactly the KPI's rows (its filter and window): the counts the value guards need.
        Never a LIMIT or a sample: a guard measured on a sample guards nothing."""
        if spec.get("metric_view"):
            raise ValueError("a metric view has no rows to guard")
        aggregate = DeepEvidence.canonical_aggregate(spec.get("aggregation"))
        column, time, grain = (spec.get(key) for key in ("column", "time_column", "grain_key"))
        assert_scope_columns(spec["table"], [column, time, spec.get("filter_column"), grain], scopes)
        table_sql = inspire_scoped_read_source(spec["table"], scopes)
        conditions = [] if spec.get("denominator") else [condition for condition in (kpi_filter_sql(spec),) if condition]
        conditions += DeepEvidence._kpi_window_conditions(spec, table_sql)
        quote = inspire_quote_identifier
        none = "CAST(NULL AS BIGINT)"
        measure = quote(column) if column and aggregate in ("SUM", "AVG") else None
        day = quote(time) if time else None
        parts = [
            "COUNT(*) AS n",
            f"COUNT(DISTINCT {quote(grain)}) AS k" if grain else f"{none} AS k",
            f"COUNT(*) FILTER (WHERE {measure} < 0) AS neg_n" if measure and aggregate == "SUM" else f"{none} AS neg_n",
            f"CAST(SUM({measure}) FILTER (WHERE {measure} < 0) AS DOUBLE) AS neg_v" if measure and aggregate == "SUM" else f"{none} AS neg_v",
            f"CAST(SUM({measure}) FILTER (WHERE {measure} >= 0) AS DOUBLE) AS pos_v" if measure and aggregate == "SUM" else f"{none} AS pos_v",
            f"CAST(MIN({day}) AS DATE) AS first_day" if day else "CAST(NULL AS DATE) AS first_day",
            f"CAST(MAX({day}) AS DATE) AS last_day" if day else "CAST(NULL AS DATE) AS last_day",
            f"COUNT(DISTINCT DATE_TRUNC('MONTH', {day})) AS months" if day else f"{none} AS months",
            f"COUNT(DISTINCT {measure}) AS distinct_v" if measure else f"{none} AS distinct_v"]
        where = f" WHERE {' AND '.join(conditions)}" if conditions else ""
        return f"SELECT {', '.join(parts)} FROM {table_sql}{where}"

    @staticmethod
    def kpi_rate_guard_sql(spec: dict, scopes=None) -> str:
        """For a KPI priced through a rate table: n rows, j rows after the as-of rate join (a row already in the base currency counts
        once, a row with no rate counts 0), u rows with no rate on or before their date."""
        table_sql = inspire_scoped_read_source(spec["table"], scopes)
        conditions = [] if spec.get("denominator") else [condition for condition in (kpi_filter_sql(spec),) if condition]
        conditions += DeepEvidence._kpi_window_conditions(spec, table_sql)
        joined, _priced, in_base = DeepEvidence._kpi_rate_join(spec, table_sql, conditions, scopes)
        where = f" WHERE {' AND '.join(conditions)}" if conditions else ""
        return (f"SELECT (SELECT COUNT(*) FROM {table_sql}{where}) AS n, COUNT(CASE WHEN {in_base} THEN 1 END) AS j, "
                f"COUNT(CASE WHEN {in_base} THEN NULL ELSE 1 END) AS u FROM {joined}")

    @staticmethod
    def _kpi_aggregate(aggregation, column, part) -> str:
        aggregate = DeepEvidence.canonical_aggregate(aggregation)
        if not column:
            if aggregate != "COUNT":
                raise ValueError(f"KPI aggregate {aggregate} needs a column")
            expression = "COUNT(*)"
        elif aggregate == "COUNT_DISTINCT":
            expression = f"COUNT(DISTINCT {inspire_quote_identifier(column)})"
        elif aggregate in ("MIN", "MAX") and deep_column_is_pii(column):
            raise ValueError(f"KPI {aggregate} of the personal column {column!r} is never measured")
        else:
            expression = f"{aggregate}({inspire_quote_identifier(column)})"
        condition = kpi_filter_sql(part)
        if condition:
            expression += f" FILTER (WHERE {condition})"
        return expression

    def measure_kpi(self, spec: dict, scopes=None):
        if not spec.get("metric_view"):
            self._plain_table(spec.get("table"))
        sql = DeepEvidence.kpi_sql(spec, scopes)
        if not spec.get("metric_view"):
            scope = {key: part for key, part in spec.items()
                     if key not in ("denominator", "column", "aggregation") and not str(key).startswith("filter_")}
            sql = f"SELECT ({sql}) AS v, ({DeepEvidence.kpi_sql(dict(scope, aggregation='COUNT'), scopes)}) AS n"
        rows = self._read("kpi_baseline", spec.get("metric_view") or spec.get("table"), sql, scopes=scopes)
        value = rows[0]["v"] if rows else None
        try:
            in_scope = rows[0]["n"] if rows else None
        except (KeyError, IndexError, ValueError, TypeError):
            in_scope = None
        if in_scope is not None and int(in_scope) == 0:
            raise DeepEvidenceNoRows("the KPI table holds no rows" + (" in the KPI window" if spec.get("window_days") else ""))
        try:
            number = None if value is None else float(value)
        except (TypeError, ValueError, OverflowError):
            return None
        return number if number is not None and number == number and abs(number) != float("inf") else None

    def measure_kpi_guards(self, spec: dict, scopes=None) -> dict:
        """The facts inspire_value_guards reads, from one aggregate read (plus one rate read for a rated KPI). A statement timeout
        is {"status": "timeout"}: missing evidence, never retried and never on a sample. Any other read error is "failed"."""
        blank = dict.fromkeys(("rows", "grain_keys", "negative_rows", "negative_total", "positive_total", "first_day", "last_day",
                               "months", "distinct_values", "joined_rows", "unpriced_rows"))
        facts = dict(blank)

        def held(row, key, cast):
            try:
                return None if row[key] is None else cast(row[key])
            except (KeyError, IndexError, ValueError, TypeError):
                return None
        try:
            if not spec.get("metric_view"):
                self._plain_table(spec.get("table"))
            rows = self._read("kpi_guard", spec.get("table"), DeepEvidence.kpi_guard_sql(spec, scopes), scopes=scopes)
            row = rows[0] if rows else None
            if row is None:
                return {**blank, "status": "failed"}
            day = lambda value: str(value)[:10]
            facts.update(status="ok", rows=held(row, "n", int), grain_keys=held(row, "k", int), negative_rows=held(row, "neg_n", int),
                         negative_total=held(row, "neg_v", float), positive_total=held(row, "pos_v", float),
                         first_day=held(row, "first_day", day), last_day=held(row, "last_day", day), months=held(row, "months", int),
                         distinct_values=held(row, "distinct_v", int))
            if _inspire_value_rate_wanted(spec) and isinstance(spec.get("rate"), dict):
                rate_rows = self._read("kpi_rate_guard", [spec.get("table"), spec["rate"]["table"]],
                                       DeepEvidence.kpi_rate_guard_sql(spec, scopes), scopes=scopes)
                rate_row = rate_rows[0] if rate_rows else None
                facts.update(joined_rows=held(rate_row, "j", int) if rate_row is not None else None,
                             unpriced_rows=held(rate_row, "u", int) if rate_row is not None else None)
                if facts["joined_rows"] is None or facts["unpriced_rows"] is None:
                    return {**blank, "status": "failed"}
            return facts
        except SparkWorkTimeout:
            return {**blank, "status": "timeout"}
        except (DeepEvidenceBudgetSpent, SparkWorkCancelled):
            raise
        except Exception as error:
            self.logger.warning(f"[DEEP-EVIDENCE] the value guards for {spec.get('name')!r} could not be read: {redact_error(error, max_chars=200)}")
            return {**blank, "status": "failed"}

    @staticmethod
    def signal_sql(check, table_sql, spec, sample_cut=None, group_rows=DEEP_SIGNAL_GROUP_ROWS, scopes=None):
        roles = spec["roles"]
        col = {role: inspire_quote_identifier(name) for role, name in roles.items() if role not in DEEP_SIGNAL_LIST_ROLES and name}
        joins = sorted((spec.get("date_joins") or {}).items())
        if joins:
            col.update({role: inspire_quote_identifier(join["alias"]) for role, join in joins})
            dates = ", ".join(f"j{index}.{inspire_quote_identifier(join['date'])} AS {inspire_quote_identifier(join['alias'])}"
                              for index, (_role, join) in enumerate(joins))
            tables = " ".join(f"LEFT JOIN {scoped_source(*parse_three_level_name(join['table']), alias=f'j{index}', scopes=scopes)} "
                              f"ON f.{inspire_quote_identifier(join['key'])} = j{index}.{inspire_quote_identifier(join['ref_column'])}"
                              for index, (_role, join) in enumerate(joins))
            table_sql = f"(SELECT f.*, {dates} FROM (SELECT * FROM {table_sql}) AS f {tables}) AS joined"
        signals = [inspire_quote_identifier(name) for name in roles.get("signals") or []]
        levers = [inspire_quote_identifier(name) for name in roles.get("levers") or []]
        lapse = check == "outcome" and spec.get("outcome_kind") == "lapse"
        if check == "basket":
            hashed = [col["basket"]]
        elif check == "features" or lapse:
            hashed = [col["entity_key"]]
        elif check == "process":
            hashed = [col["case_key"]]
        else:
            hashed = list(col.values()) + signals + levers
        formats = spec.get("date_formats") or {}

        def day(role):
            if role not in formats:
                return f"CAST({col[role]} AS DATE)"
            return deep_signal_date_sql(col[role], formats[role])

        where = [f"{day(role) if role in formats else col[role]} IS NOT NULL"
                 for role in DEEP_SIGNAL_REQUIRED_VALUES["lapse" if lapse else check]]
        if sample_cut is not None:
            where.append(f"pmod(xxhash64({', '.join(hashed)}), {DEEP_SIGNAL_HASH_BUCKETS}) < {int(sample_cut)}")
        condition = (" WHERE " + " AND ".join(where)) if where else ""

        def source(columns):
            return f"SELECT {', '.join(columns)} FROM {table_sql}{condition}"

        if lapse:
            days = int(spec["lapse_days"])
            return (f"WITH s AS ({source([col['entity_key'] + ' AS e', day('time') + ' AS d'])}), "
                    "m AS (SELECT MAX(d) AS last FROM s), "
                    f"w AS (SELECT DISTINCT s.e, CAST(FLOOR(DATEDIFF(m.last, s.d) / {days}) AS INT) AS k FROM s CROSS JOIN m) "
                    "SELECT (SELECT COUNT(*) FROM s) AS n, (SELECT COALESCE(MAX(k), 0) FROM w) AS windows, "
                    "(SELECT COUNT(*) FROM w WHERE k >= 1) AS cases, "
                    "(SELECT COUNT(*) FROM w a LEFT JOIN w b ON a.e = b.e AND b.k = a.k - 1 WHERE a.k >= 1 AND b.e IS NULL) "
                    "AS positives"), None
        if check == "outcome":
            kind = spec.get("outcome_kind")
            args = None
            if kind == "value":
                positive, args = "CAST(o AS STRING) = :positive", {"positive": str(spec.get("outcome_value") or "")}
            elif kind == "boolean":
                positive = "o"
            else:
                positive = "CAST(o AS DOUBLE) > 0"
            parts = ["COUNT(*) AS n", "approx_count_distinct(o) AS outcome_values",
                     f"SUM(CASE WHEN {positive} THEN 1 ELSE 0 END) AS positives"]
            for index in range(len(signals)):
                parts += [f"stddev(s{index}) AS sd{index}", f"AVG(CASE WHEN {positive} THEN s{index} END) AS p{index}",
                          f"AVG(CASE WHEN NOT ({positive}) THEN s{index} END) AS q{index}"]
                if kind != "value":
                    parts.append(f"corr(s{index}, CAST(o AS DOUBLE)) AS c{index}")
            columns = [col["outcome"] + " AS o"] + [f"CAST({name} AS DOUBLE) AS s{index}" for index, name in enumerate(signals)]
            return f"SELECT {', '.join(parts)} FROM ({source(columns)}) AS src", args
        if check == "lever":
            columns = [f"CAST({col['lever']} AS DOUBLE) AS l", f"CAST({col['outcome']} AS DOUBLE) AS o"]
            if "group" not in col:
                return (f"SELECT COUNT(*) AS n, approx_count_distinct(l) AS lever_values, corr(l, o) AS pooled "
                        f"FROM ({source(columns)}) AS src"), None
            columns.append(col["group"] + " AS g")
            return (f"WITH s AS ({source(columns)}), w AS (SELECT g, COUNT(*) AS k, corr(l, o) AS c FROM s GROUP BY g "
                    f"HAVING COUNT(*) >= {int(group_rows)}) "
                    "SELECT (SELECT COUNT(*) FROM s) AS n, (SELECT approx_count_distinct(l) FROM s) AS lever_values, "
                    "(SELECT corr(l, o) FROM s) AS pooled, SUM(CASE WHEN c IS NOT NULL THEN k * c END) / "
                    "SUM(CASE WHEN c IS NOT NULL THEN k END) AS within, COUNT(c) AS groups FROM w"), None
        if check == "scenario":
            columns = [f"CAST({col['outcome']} AS DOUBLE) AS o"] + [f"CAST({name} AS DOUBLE) AS l{index}"
                                                                    for index, name in enumerate(levers)]
            parts = ["COUNT(*) AS n"] + [f"corr(l{index}, o) AS c{index}, approx_count_distinct(l{index}) AS v{index}"
                                         for index in range(len(levers))]
            return f"SELECT {', '.join(parts)} FROM ({source(columns)}) AS src", None
        if check == "impact":
            columns = [col["group"] + " AS g", f"{day('time')} AS d"]
            return (f"WITH s AS ({source(columns)}), c AS (SELECT g, COUNT(*) AS k, DATEDIFF(MAX(d), MIN(d)) AS span FROM s "
                    "GROUP BY g), q AS (SELECT g, percentile(gap, 0.5) AS gap FROM (SELECT g, DATEDIFF(d, LAG(d) OVER "
                    "(PARTITION BY g ORDER BY d)) AS gap FROM (SELECT DISTINCT g, d FROM s) AS sd) AS sg GROUP BY g), "
                    f"t AS (SELECT c.k, c.span, q.gap FROM c LEFT JOIN q ON c.g = q.g WHERE c.k >= {int(group_rows)} "
                    "ORDER BY c.k DESC LIMIT 2) "
                    "SELECT (SELECT COUNT(*) FROM s) AS n, (SELECT COUNT(*) FROM t) AS compared_groups, "
                    "(SELECT MIN(k) FROM t) AS control_rows, (SELECT MIN(span) FROM t) AS span_days, "
                    "(SELECT gap FROM t ORDER BY span ASC, k DESC LIMIT 1) AS span_gap, "
                    "(SELECT COUNT(DISTINCT d) FROM s) AS periods"), None
        if check == "process":
            columns = [col["case_key"] + " AS c", col["step"] + " AS st", f"{day('time')} AS d"]
            return (f"WITH s AS ({source(columns)}), k AS (SELECT c, COUNT(DISTINCT st) AS steps FROM s GROUP BY c) "
                    "SELECT (SELECT COUNT(*) FROM s) AS n, (SELECT COUNT(DISTINCT st) FROM s) AS steps, "
                    "(SELECT COUNT(*) FROM k WHERE steps >= 2) AS cases, (SELECT COUNT(DISTINCT d) FROM s) AS periods"), None
        if check == "basket":
            top, pairs = int(DEEP_SIGNAL_TOP_ITEMS), int(DEEP_SIGNAL_PAIR_BASKETS)
            columns = [col["basket"] + " AS b", col["item"] + " AS i"]
            return (f"WITH s AS (SELECT DISTINCT b, i FROM ({source(columns)}) AS src), "
                    "c AS (SELECT i, COUNT(*) AS k FROM s GROUP BY i), "
                    f"ti AS (SELECT i, k FROM c ORDER BY k DESC, i LIMIT {top}), "
                    "st AS (SELECT s.b, s.i FROM s JOIN ti ON s.i = ti.i), "
                    "p AS (SELECT x.i AS a, y.i AS z, COUNT(*) AS together FROM st x JOIN st y ON x.b = y.b AND x.i < y.i "
                    "GROUP BY x.i, y.i), "
                    "tot AS (SELECT COUNT(DISTINCT b) AS baskets, COUNT(*) AS interactions, COUNT(DISTINCT i) AS items FROM s), "
                    "m AS (SELECT COUNT(*) AS multi FROM (SELECT b FROM s GROUP BY b HAVING COUNT(*) >= 2) AS mb) "
                    "SELECT tot.baskets, tot.interactions, tot.items, m.multi AS multi_item_baskets, "
                    f"(SELECT COUNT(*) FROM p WHERE together >= {pairs}) AS supported_pairs, "
                    "(SELECT MAX(CAST(p.together AS DOUBLE) * t2.baskets / (CAST(ka.k AS DOUBLE) * kz.k)) FROM p "
                    f"JOIN ti ka ON ka.i = p.a JOIN ti kz ON kz.i = p.z CROSS JOIN tot t2 WHERE p.together >= {pairs}) AS pair_lift "
                    "FROM tot CROSS JOIN m"), None
        if check in ("series", "lead"):
            value = f"CAST({col['measure']} AS DOUBLE)" if "measure" in col else "1.0"
            columns = [f"{day('time')} AS d", value + " AS v"] + ([col["series_key"] + " AS k"] if "series_key" in col else [])
            lags = ", ".join(f"LAG(y, {lag}) OVER (ORDER BY d) AS y{lag}" for lag in DEEP_SIGNAL_LAGS)
            corrs = ", ".join(f"corr(y, y{lag}) AS lag{lag}" for lag in DEEP_SIGNAL_LAGS)
            series = ("" if "series_key" not in col else
                      ", (SELECT percentile(n, 0.5) FROM (SELECT k, COUNT(DISTINCT d) AS n FROM s GROUP BY k) AS ks) "
                      "AS median_series_periods, (SELECT COUNT(DISTINCT k) FROM s) AS series")
            return (f"WITH s AS ({source(columns)}), p AS (SELECT d, SUM(v) AS y FROM s GROUP BY d), "
                    f"l AS (SELECT d, y, DATEDIFF(d, LAG(d) OVER (ORDER BY d)) AS gap, {lags} FROM p) "
                    f"SELECT COUNT(*) AS periods, MIN(d) AS first_period, MAX(d) AS last_period, percentile(gap, 0.5) AS median_gap, "
                    f"{corrs}{series} FROM l"), None
        if check == "features":
            columns = [col["entity_key"] + " AS e"] + [f"CAST({name} AS DOUBLE) AS s{index}" for index, name in enumerate(signals)]
            parts = ["COUNT(*) AS n", "COUNT(DISTINCT e) AS entities"] + [f"stddev(s{index}) AS sd{index}" for index in range(len(signals))]
            return f"SELECT {', '.join(parts)} FROM ({source(columns)}) AS src", None
        if check == "groups":
            columns = [col["group"] + " AS g"] + ([f"{day('time')} AS d"] if "time" in col else [])
            periods = ", (SELECT COUNT(DISTINCT d) FROM s) AS periods" if "time" in col else ""
            return (f"WITH s AS ({source(columns)}), c AS (SELECT g, COUNT(*) AS k FROM s GROUP BY g) "
                    f"SELECT (SELECT COUNT(*) FROM s) AS n, COUNT(*) AS groups, "
                    f"SUM(CASE WHEN k >= {int(group_rows)} THEN 1 ELSE 0 END) AS reportable_groups{periods} FROM c"), None
        if check == "text":
            columns = ["CAST(" + col["text"] + " AS STRING) AS x"]
            return ("SELECT COUNT(*) AS n, COUNT(NULLIF(TRIM(x), '')) AS filled, percentile(length(x), 0.5) AS median_length "
                    f"FROM ({source(columns)}) AS src"), None
        if check == "measure":
            columns = ["CAST(" + col["measure"] + " AS DOUBLE) AS m"]
            return ("SELECT COUNT(*) AS n, COUNT(m) AS filled, approx_count_distinct(m) AS measure_values "
                    f"FROM ({source(columns)}) AS src"), None
        raise ValueError(f"unknown signal check {check!r}")

    def signal_date_join_problem(self, date_joins, scopes=None) -> str:
        for _role, join in sorted(date_joins.items()):
            scope = inspire_scopes_in_force(scopes).get(inspire_table_scope_key(join["table"])) or {}
            counted = (join["table"], join["ref_column"], scope.get("source", ""))
            if counted not in self.date_key_counts:
                key = inspire_quote_identifier(join["ref_column"])
                rows = self._read("signal_date_key", join["table"],
                                  f"SELECT COUNT({key}) AS n, COUNT(DISTINCT {key}) AS k "
                                  f"FROM {inspire_scoped_read_source(join['table'], scopes)}", budget="signal", scopes=scopes)
                first = rows[0] if rows else None
                row = first.asDict() if hasattr(first, "asDict") else dict(first or {})
                self.date_key_counts[counted] = (int(_deep_signal_number(row.get("n")) or 0),
                                                 int(_deep_signal_number(row.get("k")) or 0))
            filled, distinct = self.date_key_counts[counted]
            if not filled:
                return f"the date table {join['table']} holds no {join['ref_column']} values to join {join['key']} to"
            if distinct != filled:
                return (f"the date table {join['table']} holds {inspire_plural(filled, join['ref_column'] + ' value')} for "
                        f"{inspire_plural(distinct, 'distinct key')}, so joining {join['key']} to it would repeat rows")
        return ""

    def signal_date_formats(self, table_sql, table_label, spec, scopes=None) -> tuple:
        self._plain_table(table_label)
        formats = {}
        for role in spec.get("text_dates") or ():
            column = inspire_quote_identifier(spec["roles"][role])
            parts = ["COUNT(v) AS filled"] + [f"COUNT({deep_signal_date_sql('v', fmt)}) AS f{index}"
                                              for index, fmt in enumerate(DEEP_SIGNAL_DATE_FORMATS)]
            sql = (f"SELECT {', '.join(parts)} FROM (SELECT CAST({column} AS STRING) AS v FROM {table_sql} "
                   f"WHERE {column} IS NOT NULL LIMIT {int(DEEP_SIGNAL_DATE_PROBE_ROWS)}) AS src")
            rows = self._read("signal_dates", table_label, sql, budget="signal", scopes=scopes)
            first = rows[0] if rows else None
            row = first.asDict() if hasattr(first, "asDict") else dict(first or {})
            filled = int(_deep_signal_number(row.get("filled")) or 0)
            counts = [int(_deep_signal_number(row.get(f"f{index}")) or 0) for index in range(len(DEEP_SIGNAL_DATE_FORMATS))]
            best = max(range(len(counts)), key=lambda index: (counts[index], -index)) if counts else 0
            if not filled or counts[best] < filled * DEEP_SIGNAL_DATE_PARSE_SHARE:
                return formats, (f"the {role.replace('_', ' ')} column {spec['roles'][role]} is text and only "
                                 f"{implement_number_text(counts[best] if counts else 0)} of {inspire_plural(filled, 'value')} read as dates")
            formats[role] = DEEP_SIGNAL_DATE_FORMATS[best]
        return formats, ""

    def signal_measures(self, check, table_sql, table_label, spec, row_count=None, scopes=None):
        self._plain_table(table_label)
        if row_count is None:
            counted = self._read("signal_rows", table_label, f"SELECT COUNT(*) AS n FROM {table_sql}", budget="signal", scopes=scopes)
            row_count = int(counted[0]["n"] or 0) if counted else 0
        cut, fraction = None, 1.0
        if row_count > self.sample_rows:
            cut = max(1, int(DEEP_SIGNAL_HASH_BUCKETS * self.sample_rows / row_count))
            fraction = cut / DEEP_SIGNAL_HASH_BUCKETS
        base_rows = GENIE_READINESS_THRESHOLDS["F"]["min_group_rows"] if check == "groups" else DEEP_SIGNAL_GROUP_ROWS
        sql, args = self.signal_sql(check, table_sql, spec, cut, max(1, int(round(base_rows * fraction))), scopes)
        rows = self._read(f"signal_{check}", table_label, sql, args, budget="signal", scopes=scopes)
        first = rows[0] if rows else None
        row = first.asDict() if hasattr(first, "asDict") else dict(first or {})
        measures = deep_signal_measures(check, row, spec, fraction)
        measures["sampled"] = cut is not None
        return measures

    def value_count(self, table, column, scopes=None):
        """Distinct non-null values of one column in the rows the signal check reads; None when the read returns no row."""
        if self.is_policied(table):
            return None
        sql = f"SELECT COUNT(DISTINCT {inspire_quote_identifier(column)}) AS k FROM {inspire_scoped_read_source(table, scopes)}"
        rows = self._read("signal_values", table, sql, budget="signal", scopes=scopes)
        first = rows[0] if rows else None
        row = first.asDict() if hasattr(first, "asDict") else dict(first or {})
        return None if row.get("k") is None else int(_deep_signal_number(row.get("k")) or 0)

    @staticmethod
    def _loss_row(row) -> dict:
        return row.asDict() if hasattr(row, "asDict") else dict(row or {})

    @staticmethod
    def _loss_number(value):
        try:
            number = None if value is None else float(value)
        except (TypeError, ValueError, OverflowError):
            return None
        return number if number is not None and number == number and abs(number) != float("inf") else None

    @staticmethod
    def _loss_pool(table, money, split, kind, currency, source, flow, unit, values, amounts, rows, measured, total) -> dict:
        known = [a for a in amounts if a is not None]
        amount = sum(known) if known else None
        share = None if amount is None or not total else abs(amount) / abs(total)
        digest = hashlib.sha256("|".join([table, money, split or "", kind, currency or ""]).encode("utf-8")).hexdigest()[:12]
        return {"pool_id": f"lp{digest}", "table": table, "money_column": money, "split_column": split, "split_values": sorted(values),
                "loss_kind": kind, "source": source, "flow": flow, "currency": currency, "unit": unit, "amount": amount,
                "rows": rows, "measured_rows": measured, "share": share,
                "material": None if share is None else share >= INSPIRE_LOSS_POOL_MATERIAL_SHARE,
                "flags": ["measure_partly_missing"] if 0 < measured < rows else []}

    def _loss_pool_table(self, item, scopes, pools, skipped):
        """Reads one table's aggregates and appends its pools and skipped rows as they are measured; a read error propagates."""
        table, cur_col, quote = item["table"], item.get("currency_column"), inspire_quote_identifier
        source = inspire_scoped_read_source(table, scopes)
        money, flow = list(item.get("money_columns") or []), item.get("flow") or "other"
        number = DeepEvidence._loss_number

        def currency(row, column):
            if not cur_col:
                return _inspire_column_currency(column) or None
            return (str(row["cur"]).strip() or None) if row.get("cur") is not None else None

        def read(sql):
            return [DeepEvidence._loss_row(r) for r in self._read("loss_pool", table, sql, budget="signal", scopes=scopes)]

        for status in item.get("status_columns") or []:
            if not money:
                break
            counted = read(f"SELECT COUNT(*) AS k FROM (SELECT {quote(status)} AS v FROM {source} GROUP BY {quote(status)}) AS distinct_values")
            if int(number((counted[0] if counted else {}).get("k")) or 0) > INSPIRE_LOSS_POOL_MAX_VALUES:
                skipped.append({"table": table, "column": status, "reason": "too_many_values"})
                continue
            parts = [f"{quote(status)} AS v"] + ([f"{quote(cur_col)} AS cur"] if cur_col else []) + ["COUNT(*) AS n"]
            for i, column in enumerate(money):
                parts += [f"SUM({quote(column)}) AS s{i}", f"COUNT({quote(column)}) AS c{i}"]
            rows = read(f"SELECT {', '.join(parts)} FROM {source} GROUP BY {quote(status)}" + (f", {quote(cur_col)}" if cur_col else ""))
            kinds = {str(r["v"]): _inspire_loss_value_kind(r["v"]) for r in rows if r.get("v") is not None}
            loss_values = {v for v, kind in kinds.items() if kind not in ("", "neutral")}
            unmapped = [v for v, kind in kinds.items() if kind == ""]
            if unmapped:
                skipped.append({"table": table, "column": status, "reason": "status_values_unmapped", "distinct_values": len(unmapped)})
            if not loss_values:
                if not unmapped:
                    skipped.append({"table": table, "column": status, "reason": "no_loss_values"})
                continue
            totals, grouped = {}, {}
            for r in rows:
                for i, column in enumerate(money):
                    cur, amount = currency(r, column), number(r.get(f"s{i}"))
                    if amount is not None:
                        totals[(i, cur)] = totals.get((i, cur), 0.0) + amount
                    if r.get("v") is not None and str(r["v"]) in loss_values:
                        entry = grouped.setdefault((i, kinds[str(r["v"])], cur), {"values": set(), "amounts": [], "rows": 0, "measured": 0})
                        entry["values"].add(str(r["v"]))
                        entry["amounts"].append(amount)
                        entry["rows"] += int(number(r.get("n")) or 0)
                        entry["measured"] += int(number(r.get(f"c{i}")) or 0)
            for (i, kind, cur), entry in grouped.items():
                pools.append(DeepEvidence._loss_pool(table, money[i], status, kind, cur, "status_split", flow, "money", entry["values"],
                                             entry["amounts"], entry["rows"], entry["measured"], totals.get((i, cur))))
        losses = list(item.get("loss_columns") or [])
        if losses:
            parts = ([f"{quote(cur_col)} AS cur"] if cur_col else []) + ["COUNT(*) AS n"]
            for i, loss in enumerate(losses):
                parts += [f"SUM({quote(loss['column'])}) AS a{i}", f"COUNT({quote(loss['column'])}) AS m{i}"]
            parts += [f"SUM({quote(column)}) AS t{j}" for j, column in enumerate(money)]
            for r in read(f"SELECT {', '.join(parts)} FROM {source}" + (f" GROUP BY {quote(cur_col)}" if cur_col else "")):
                sizes = [abs(t) for t in (number(r.get(f"t{j}")) for j in range(len(money))) if t is not None]
                for i, loss in enumerate(losses):
                    pools.append(DeepEvidence._loss_pool(table, loss["column"], None, loss["kind"], currency(r, loss["column"]), "loss_column",
                                                 flow, loss["unit"], [], [number(r.get(f"a{i}"))], int(number(r.get("n")) or 0),
                                                 int(number(r.get(f"m{i}")) or 0), max(sizes) if sizes and loss["unit"] == "money" else None))

    def measure_loss_pools(self, plan, scopes=None) -> dict:
        """REQ-573 R10.4: each table's money columns split by their loss status values, and its loss columns, as aggregates only
        (never a LIMIT or a sample), per currency. A table that cannot be read gives a skipped row, never a 0 pool."""
        pools, skipped = [], []
        items = list(plan or [])
        for index, item in enumerate(items):
            table, found, spent = item["table"], [], False
            if self.is_policied(table) or self.is_metric_view(table):
                skipped.append({"table": table, "column": None, "reason": "policied" if self.is_policied(table) else "metric_view"})
                continue
            try:
                DeepEvidence._loss_pool_table(self, item, scopes, found, skipped)
            except DeepEvidenceBudgetSpent:
                skipped.extend({"table": rest["table"], "column": None, "reason": "budget_spent"} for rest in items[index:])
                spent = True
            except SparkWorkCancelled:
                raise
            except SparkWorkTimeout:
                skipped.append({"table": table, "column": None, "reason": "timeout"})
            except Exception as error:
                skipped.append({"table": table, "column": None, "reason": "failed", "error": redact_error(error, max_chars=200)})
            pools.extend(sorted(found, key=lambda p: (p["money_column"], p["split_column"] or "", p["loss_kind"], p["currency"] or "")))
            if spent:
                break
        return {"pools": pools, "skipped": skipped}

    def _unreadable_summary(self) -> dict:
        denied = sorted(t for t, status in self.skipped_tables.items() if status == "denied")
        if not denied:
            return {}
        reason = self.unreadable_text(denied)
        who = self._who[0] if self._who else ""
        grants = inspire_read_grants(denied, who, per_schema=True)
        out = {"tables_unreadable": denied, "unreadable_reason": reason}
        if grants:
            out["permissions"] = [implement_permission_entry(who, grants, "Discover reads these tables with your own access.")]
        return out

    def summary(self) -> dict:
        tables = sorted({t for s in self.statements if s["status"] == "ok" for t in s["tables"]
                         if t != "system.query.history"})
        return {"discovery_type": self.discovery_type, "tables_read": tables, "tables_read_count": len(tables),
                "statements": len(self.statements),
                "statements_by_status": dict(Counter(s["status"] for s in self.statements)),
                "tables_skipped": dict(self.skipped_tables),
                **self._unreadable_summary(),
                "pii_columns_excluded": len(self.pii_excluded),
                "seconds": round(sum(s["seconds"] for s in self.statements), 1),
                "rows_sent_to_ai": 0, "aggregates_sent_to_ai": discovery_ai_sees_aggregates(self.discovery_type)}


def _deep_signal_number(value):
    try:
        number = float(value)
    except (TypeError, ValueError):
        return None
    return number if number == number and abs(number) != float("inf") else None


def _deep_signal_day(value):
    if isinstance(value, datetime.datetime):
        return value.date()
    if isinstance(value, datetime.date):
        return value
    try:
        return inspire_parse_time(str(value or "")[:10]).date()
    except ValueError:
        return None


def deep_signal_measures(check, row, spec, fraction=1.0):
    row = dict(row or {})
    roles = spec["roles"]
    signals = list(roles.get("signals") or [])

    def count(key):
        return int(_deep_signal_number(row.get(key)) or 0)

    def scaled(key):
        return int(round(count(key) / fraction)) if fraction else count(key)

    if check == "outcome" and spec.get("outcome_kind") == "lapse":
        cases = count("cases")
        return {"row_count": scaled("n"), "positives": scaled("positives"), "outcome_windows": count("windows"),
                "class_rate": round(count("positives") / cases, 6) if cases else 0.0}
    if check == "outcome":
        rows = count("n")
        out = {"row_count": scaled("n")}
        best, best_name = None, ""
        binary = spec.get("outcome_kind") in ("value", "boolean") or count("outcome_values") <= 2
        if binary:
            out["positives"] = scaled("positives")
            out["class_rate"] = round(count("positives") / rows, 6) if rows else 0.0
            for index, name in enumerate(signals):
                sd, hit, miss = (_deep_signal_number(row.get(f"{key}{index}")) for key in ("sd", "p", "q"))
                if sd and hit is not None and miss is not None and (best is None or abs(hit - miss) / sd > best):
                    best, best_name = abs(hit - miss) / sd, name
            out["separation"] = round(best or 0.0, 4)
        else:
            for index, name in enumerate(signals):
                value = _deep_signal_number(row.get(f"c{index}"))
                if value is not None and (best is None or abs(value) > best):
                    best, best_name = abs(value), name
            out["correlation"] = round(best or 0.0, 4)
        out["signal"] = best_name or ", ".join(signals)
        return out
    if check == "scenario":
        effects = [abs(_deep_signal_number(row.get(f"c{index}")) or 0.0) if count(f"v{index}") >= DEEP_SIGNAL_LEVER_VALUES else 0.0
                   for index in range(len(roles.get("levers") or []))]
        return {"row_count": scaled("n"), "moving_levers": sum(1 for effect in effects if effect >= DEEP_SIGNAL_LEVER_EFFECT),
                "strongest_lever_effect": round(max(effects), 4) if effects else 0.0}
    if check == "impact":
        compared = count("compared_groups")
        out = {"row_count": scaled("n"), "compared_groups": compared, "periods": count("periods")}
        if compared >= 2:
            out.update(control_rows=scaled("control_rows"),
                       history_weeks=round(((_deep_signal_number(row.get("span_days")) or 0.0)
                                            + (_deep_signal_number(row.get("span_gap")) or 1)) / 7, 1))
        return out
    if check == "process":
        return {"row_count": scaled("n"), "steps": count("steps"), "cases": scaled("cases"), "periods": count("periods")}
    if check == "lever":
        effects = [abs(v) for v in (_deep_signal_number(row.get("pooled")), _deep_signal_number(row.get("within"))) if v is not None]
        return {"row_count": scaled("n"), "lever_values": count("lever_values"), "lever_effect": round(max(effects), 4) if effects else 0.0}
    if check == "basket":
        out = {"row_count": scaled("interactions"), "interactions": scaled("interactions"), "users": scaled("baskets"),
               "items": count("items"), "multi_item_baskets": count("multi_item_baskets"), "supported_pairs": count("supported_pairs")}
        lift = _deep_signal_number(row.get("pair_lift"))
        if lift is not None:
            out["pair_lift"] = round(lift, 4)
        return out
    if check in ("series", "lead"):
        periods = count("periods")
        gap = _deep_signal_number(row.get("median_gap"))
        out = {"row_count": periods, "periods": periods, "cadence": "period"}
        season = next(((name, length) for limit, name, length in DEEP_SIGNAL_SEASONS if gap is not None and gap <= limit), None)
        lags = [_deep_signal_number(row.get("lag1"))]
        if season:
            out["cadence"], out["season"] = season
            out["seasonal_cycles"] = round(periods / season[1], 2)
            lags.append(_deep_signal_number(row.get(f"lag{season[1]}")))
            first, last = _deep_signal_day(row.get("first_period")), _deep_signal_day(row.get("last_period"))
            if first and last and gap:
                expected = (last - first).days / gap + 1
                out["missing_period_rate"] = round(max(0.0, 1.0 - periods / expected), 4) if expected > 0 else 0.0
        elif periods < 3:
            out["seasonal_cycles"] = 0.0
        found = [value for value in lags if value is not None]
        out["autocorrelation"] = round(max(found), 4) if found else 0.0
        if check == "lead":
            first, last = _deep_signal_day(row.get("first_period")), _deep_signal_day(row.get("last_period"))
            out["lead_weeks"] = round(((last - first).days + (gap or 1)) / 7, 1) if first and last else 0.0
        if row.get("median_series_periods") is not None:
            out["median_series_periods"] = int(_deep_signal_number(row.get("median_series_periods")) or 0)
            out["series"] = count("series")
        return out
    if check == "features":
        deviations = [_deep_signal_number(row.get(f"sd{index}")) for index in range(len(signals))]
        return {"row_count": scaled("n"), "entities": scaled("entities"), "numeric_features": sum(1 for sd in deviations if sd)}
    if check == "groups":
        out = {"row_count": scaled("n"), "reportable_groups": count("reportable_groups")}
        if "periods" in row:
            out["periods"] = count("periods")
        return out
    if check == "text":
        rows = count("n")
        return {"row_count": scaled("n"), "text_non_null_rate": round(count("filled") / rows, 4) if rows else 0.0,
                "median_text_length": count("median_length")}
    if check == "measure":
        rows = count("n")
        return {"row_count": scaled("n"), "reference_rows": scaled("n"),
                "key_signal_null_rate": round(1.0 - count("filled") / rows, 4) if rows else 1.0, "measure_values": count("measure_values")}
    raise ValueError(f"unknown signal check {check!r}")


def analysis_minimum_rows(technique, family):
    wanted = " ".join(str(technique or "").split()).lower()
    named = next((name for name in TECHNIQUE_MIN_ROWS if name.lower() == wanted), None)
    if named is not None:
        return TECHNIQUE_MIN_ROWS[named]
    return (GENIE_READINESS_THRESHOLDS.get(family) or {}).get("min_rows")


def deep_signal_verdict(family, measures, names=None, thresholds=None, check=None, technique=None):
    th = dict(GENIE_READINESS_THRESHOLDS.get(family) or {})
    th["min_rows"] = analysis_minimum_rows(technique, family)
    th.update(thresholds or {})
    for _name, key, op, th_key, message in INSPIRE_READINESS_RULES["common"] + INSPIRE_READINESS_RULES.get(family, ()):
        observed = measures.get(key)
        if op == "is_true" or INSPIRE_FLAG_ONLY_READINESS.get(key) or observed is None:
            continue
        required = th.get("min_entities_per_k", 0) * 2 if th_key == "min_entities_per_k*k" else th.get(th_key)
        if required is None:
            continue
        if not (observed >= required if op == ">=" else observed <= required):
            return False, message.format(observed=observed, required=required)
    values = {"group": "group", **(names or {}), **measures, "top_items": DEEP_SIGNAL_TOP_ITEMS,
              "pair_baskets": DEEP_SIGNAL_PAIR_BASKETS}
    runtime = TECHNICAL_CONTEXT["runtime"]
    tests = [(key, runtime[minimum] if isinstance(minimum, str) else minimum, message)
             for key, minimum, message in DEEP_SIGNAL_CHECK_TESTS.get(check, ())] + list(DEEP_SIGNAL_TESTS.get(family, ()))
    for key, minimum, message in tests:
        observed = measures.get(key)
        if observed is not None and observed < minimum:
            return False, message.format(**{**values, "observed": observed, "required": minimum})
    for key in DEEP_SIGNAL_CHECK_PASS_KEYS.get(check, ()) + DEEP_SIGNAL_PASS_KEYS.get(family, ()):
        if measures.get(key) is not None:
            return True, DEEP_SIGNAL_PASS_TEXT[key].format(**values)
    return True, "The data holds what this use case needs."


_HISTORY_TABLE_REF_RE = re.compile(r"\b(?:FROM|JOIN)\s+([`\w.]+)(?:\s+(?:AS\s+)?([A-Za-z_]\w*))?", re.IGNORECASE)
_HISTORY_EQ_RE = re.compile(r"([`\w]+)\s*\.\s*([`\w]+)\s*=\s*([`\w]+)\s*\.\s*([`\w]+)")
_HISTORY_RESERVED = {"on", "where", "join", "left", "right", "inner", "outer", "full", "cross", "group", "order",
                     "limit", "union", "select", "using", "natural", "lateral", "having", "qualify", "window"}


def mine_history_join_edges(statements, known_tables) -> list:
    """Join edges between known tables from query text. The text never leaves this function:
    only (table.column, table.column, count) edges are returned."""
    known = {str(t).replace("`", "").lower(): str(t).replace("`", "") for t in known_tables or []}
    by_short = defaultdict(set)
    for low, original in known.items():
        by_short[low.split(".")[-1]].add(original)
    counts = Counter()
    for text in statements or []:
        aliases = {}
        for ref, alias in _HISTORY_TABLE_REF_RE.findall(text or ""):
            name = ref.replace("`", "").lower()
            table = known.get(name)
            if table is None and len(by_short.get(name.split(".")[-1], ())) == 1:
                table = next(iter(by_short[name.split(".")[-1]]))
            if table is None:
                continue
            aliases[name.split(".")[-1]] = table
            if alias and alias.lower() not in _HISTORY_RESERVED:
                aliases[alias.lower()] = table
        if len(set(aliases.values())) < 2:
            continue
        for left_alias, left_col, right_alias, right_col in _HISTORY_EQ_RE.findall(text or ""):
            left_table = aliases.get(left_alias.replace("`", "").lower())
            right_table = aliases.get(right_alias.replace("`", "").lower())
            if not left_table or not right_table or left_table == right_table:
                continue
            edge = tuple(sorted([(left_table, left_col.replace("`", "")), (right_table, right_col.replace("`", ""))]))
            counts[edge] += 1
    return [{"left": f"{a[0]}.{a[1]}", "right": f"{b[0]}.{b[1]}", "count": n}
            for (a, b), n in counts.most_common()]


def _parse_metric_view_definition(text) -> dict:
    payload = None
    try:
        import yaml as _yaml
        payload = _yaml.safe_load(text)
    except Exception:
        payload = None
    if not isinstance(payload, dict):
        measures = [{"name": m.group(1).strip().strip("'\""), "expr": m.group(2).strip().strip("'\"")}
                    for m in re.finditer(r"-\s*name:\s*(.+)\n\s+expr:\s*(.+)", str(text or ""))]
        source = re.search(r"^\s*source:\s*(.+)$", str(text or ""), re.MULTILINE)
        return {"source": source.group(1).strip().strip("'\"") if source else "", "measures": measures}
    return {"source": str(payload.get("source") or ""),
            "measures": [{"name": str(m.get("name") or ""), "expr": str(m.get("expr") or "")}
                         for m in payload.get("measures") or [] if isinstance(m, dict) and m.get("name")]}


def collect_policied_tables(spark_session, schema_pairs, logger) -> list:
    """SEC-01 W8: fully qualified names of tables in the scanned schemas that carry a row filter or a column mask,
    read from the information_schema row_filters and column_masks views (metadata only)."""
    found = set()
    for catalog, schema in sorted({(str(c), str(s)) for c, s in schema_pairs or []}):
        for view in ("row_filters", "column_masks"):
            try:
                rows = _metadata_rows(
                    spark_session,
                    f"SELECT table_catalog, table_schema, table_name FROM {inspire_quote_identifier(catalog)}.`information_schema`.`{view}` "
                    "WHERE table_schema = :schema", args={"schema": schema.lower()}, logger=logger,
                    context=f"{view} {catalog}.{schema}")
            except Exception as error:
                logger.warning(f"[POLICIED] {view} of {catalog}.{schema} could not be read: {redact_error(error, max_chars=200)}")
                continue
            for row in rows:
                found.add(build_fqn(row.table_catalog or catalog, row.table_schema or schema, row.table_name).replace("`", "").lower())
    return sorted(found)


def collect_metric_views(spark_session, schema_pairs, logger) -> list:
    """Unity Catalog metric views in the scanned schemas, read from information_schema and DESCRIBE only."""
    views = []
    for catalog, schema in sorted({(str(c), str(s)) for c, s in schema_pairs or []}):
        try:
            rows = _metadata_rows(
                spark_session,
                f"SELECT table_catalog, table_schema, table_name, comment FROM {inspire_quote_identifier(catalog)}.`information_schema`.`tables` "
                f"WHERE table_schema = :schema AND table_type IN ('METRIC_VIEW', 'METRIC VIEW')",
                args={"schema": schema.lower()}, logger=logger, context=f"metric views {catalog}.{schema}")
        except Exception as error:
            logger.info(f"Metric views not listed for {catalog}.{schema}: {redact_error(error, max_chars=200)}")
            continue
        for row in rows:
            fqn = build_fqn(row.table_catalog or catalog, row.table_schema or schema, row.table_name)
            definition = {"source": "", "measures": []}
            try:
                described = _metadata_rows(spark_session, f"DESCRIBE TABLE EXTENDED {fqn} AS JSON", logger=logger,
                                           context=f"metric view {fqn}")
                raw = described[0][0] if described else ""
                meta = json.loads(raw) if isinstance(raw, str) and raw.strip().startswith("{") else {}
                definition = _parse_metric_view_definition(meta.get("view_text") or meta.get("view_definition") or "")
            except Exception as error:
                logger.info(f"Metric view {fqn} definition unreadable: {redact_error(error, max_chars=200)}")
            views.append({"fqn": f"{row.table_catalog or catalog}.{row.table_schema or schema}.{row.table_name}",
                          "comment": row.comment or "", "source": definition["source"],
                          "measures": definition["measures"]})
    return views


def collect_usage_signals(spark_session, table_fqns, logger, days=90) -> dict:
    """Read counts, distinct readers and co-use from system.access.table_lineage. Metadata only:
    no user identity and no query text is kept."""
    names = sorted({str(t).replace("`", "") for t in table_fqns or [] if str(t).strip()})
    result = {"available": False, "reason": "", "reads": {}, "readers": {}, "downstream": {}, "co_used": []}
    if not names:
        result["reason"] = "no tables"
        return result
    in_sql, params = _sql_in_list_params(names, "t")
    window = f"event_time >= current_timestamp() - INTERVAL {int(days)} DAYS"
    try:
        rows = _metadata_rows(
            spark_session,
            f"SELECT source_table_full_name AS t, COUNT(*) AS n, COUNT(DISTINCT created_by) AS u, "
            f"COLLECT_SET(entity_type) AS kinds FROM system.access.table_lineage "
            f"WHERE {window} AND source_table_full_name IN ({in_sql}) GROUP BY source_table_full_name",
            args=params, logger=logger, context="usage signals")
        for row in rows:
            result["reads"][row.t] = int(row.n or 0)
            result["readers"][row.t] = int(row.u or 0)
            result["downstream"][row.t] = sorted(str(k) for k in (row.kinds or []) if k)
        pairs = _metadata_rows(
            spark_session,
            f"SELECT a.source_table_full_name AS t1, b.source_table_full_name AS t2, COUNT(DISTINCT a.entity_run_id) AS runs "
            f"FROM system.access.table_lineage a JOIN system.access.table_lineage b "
            f"ON a.entity_run_id = b.entity_run_id AND a.source_table_full_name < b.source_table_full_name "
            f"WHERE a.{window} AND b.{window} AND a.entity_run_id IS NOT NULL "
            f"AND a.source_table_full_name IN ({in_sql}) AND b.source_table_full_name IN ({in_sql}) "
            f"GROUP BY 1, 2 ORDER BY runs DESC LIMIT 200",
            args=params, logger=logger, context="co-usage signals")
        result["co_used"] = [{"left": r.t1, "right": r.t2, "runs": int(r.runs or 0)} for r in pairs]
        result["available"] = True
    except Exception as error:
        result["reason"] = redact_error(error, max_chars=200)
        logger.info(f"Usage signals unavailable (system.access.table_lineage): {result['reason']}")
    return result


class TableSizeInfo:
    """Metadata about a table's size and structure."""
    UNKNOWN_SIZE_WEIGHT = 1250

    def __init__(self, catalog, schema, table, num_columns=0, estimated_row_count=0, size_category="unknown"):
        self.catalog = catalog
        self.schema = schema
        self.table = table
        self.num_columns = num_columns
        self.estimated_row_count = estimated_row_count
        self.size_category = size_category  # "small", "medium", "wide", "very_wide", "unknown"
        self.memory_weight = self._calculate_memory_weight()

    def _calculate_memory_weight(self):
        """Calculate memory weight for batching decisions."""
        if self.size_category == "unknown" and self.num_columns <= 0:
            return self.UNKNOWN_SIZE_WEIGHT
        if self.num_columns > 1000:
            return self.num_columns * 10  # Very heavy
        elif self.num_columns > 250:
            return self.num_columns * 5   # Heavy
        elif self.num_columns > 100:
            return self.num_columns * 2   # Medium
        else:
            return self.num_columns       # Light

    def __repr__(self):
        return f"{self.catalog}.{self.schema}.{self.table} ({inspire_plural(self.num_columns, 'col')}, {self.size_category})"


class TableSizeAnalyzer:
    """
    Two-pass analyzer: First pass collects table sizes, second pass uses this info for intelligent batching.
    """
    def __init__(self, spark, logger):
        self.spark = spark
        self.logger = logger
        self.size_cache = {}  # {(catalog, schema, table): TableSizeInfo}

    def analyze_table_sizes_batch(self, table_tuples, use_info_schema_map, max_parallelism=20):
        """
        Analyze sizes for a batch of tables efficiently using parallel queries.
        
        Args:
            table_tuples: List of (catalog, schema, table) tuples
            use_info_schema_map: Dict mapping catalog -> bool for information_schema support
            max_parallelism: Maximum number of parallel queries (default: 20)
            
        Returns:
            List of TableSizeInfo objects
        """
        results = []

        # Group by catalog.schema for efficient querying
        schema_groups = defaultdict(list)
        for cat, schema, table in table_tuples:
            schema_groups[(cat, schema)].append(table)

        # Process schemas in parallel for speed
        def analyze_schema_group(schema_key_and_tables):
            (catalog, schema), tables = schema_key_and_tables
            use_info_schema = use_info_schema_map.get(catalog, False)
            schema_results = []

            self.logger.debug(f"   Analyzing {inspire_plural(len(tables), 'table')} in {catalog}.{schema}...")

            column_counts = None
            if use_info_schema:
                try:
                    in_sql, params = _sql_in_list_params([str(t).lower() for t in tables], "t")
                    params["schema"] = str(schema).lower()
                    query = f"""
                        SELECT table_name, COUNT(*) as num_columns
                        FROM {inspire_quote_identifier(catalog)}.`information_schema`.`columns`
                        WHERE table_schema = :schema
                        AND table_name IN ({in_sql})
                        GROUP BY table_name
                    """
                    column_counts = {str(row.table_name).lower(): row.num_columns
                                     for row in _metadata_rows(self.spark, query, args=params, logger=self.logger,
                                                               context=f"column counts {catalog}.{schema}")}
                except SparkWorkCancelled:
                    raise
                except Exception as e:
                    self.logger.warning(f"Column-count query failed for {inspire_plural(len(tables), 'table')} in {catalog}.{schema}; "
                                        f"sizing each table with DESCRIBE instead: {redact_error(e)}")
            unknown_tables = []
            for table in tables:
                num_cols = (column_counts or {}).get(str(table).lower(), 0)
                if num_cols == 0:
                    num_cols = self._get_column_count_fallback(catalog, schema, table)
                    if num_cols and column_counts is not None:
                        self.logger.info(f"info_schema returned 0 for {catalog}.{schema}.{table}; DESCRIBE fallback found {inspire_plural(num_cols, 'column')}")
                if num_cols:
                    size_info = TableSizeInfo(catalog, schema, table, num_columns=num_cols,
                                              size_category=self._categorize_table(num_cols))
                else:
                    unknown_tables.append(table)
                    size_info = TableSizeInfo(catalog, schema, table, num_columns=0, size_category="unknown")
                schema_results.append(size_info)
                self.size_cache[(catalog, schema, table)] = size_info
            if unknown_tables:
                shown = ", ".join(f"{catalog}.{schema}.{t}" for t in unknown_tables[:10])
                more = f" (+{implement_number_text(len(unknown_tables) - 10)} more)" if len(unknown_tables) > 10 else ""
                self.logger.warning(f"Column count unknown for {inspire_plural(len(unknown_tables), 'table')} "
                                    f"(information_schema and DESCRIBE returned nothing): {shown}{more}; kept with size_category=unknown")
            return schema_results

        # Execute schema analysis - parallel or sequential based on max_parallelism
        if max_parallelism == 1:
            # Sequential execution when nested in another thread pool
            for item in schema_groups.items():
                try:
                    schema_results = analyze_schema_group(item)
                    results.extend(schema_results)
                except Exception as e:
                    schema_key = item[0]
                    self.logger.error(f"Failed to analyze schema {schema_key}: {redact_error(e)}")
        else:
            # Parallel execution for top-level calls
            by_schema = {}
            with _SafeExecutorContext(max_workers=max_parallelism, thread_name_prefix="SchemaAnalyzer", logger=self.logger, name="SchemaAnalyzer") as ctx:
                futures = {ctx.submit(analyze_schema_group, item): item[0]
                          for item in schema_groups.items()}

                total_timeout = len(futures) * 300
                try:
                    for future in ctx.completed(futures, timeout=total_timeout):
                        schema_key = futures[future]
                        try:
                            by_schema[schema_key] = future.result(timeout=300)
                        except concurrent.futures.TimeoutError:
                            self.logger.error(f"Schema analysis timed out for {schema_key} after 5 minutes")
                        except Exception as e:
                            self.logger.error(f"Failed to analyze schema {schema_key}: {redact_error(e)}")
                except concurrent.futures.TimeoutError:
                    ctx.mark_timed_out()
                    self.logger.error(f"Overall schema analysis timeout ({total_timeout}s). Proceeding with partial results.")
            results = [info for schema_key in schema_groups for info in by_schema.get(schema_key, [])]

        return results

    def _get_column_count_fallback(self, catalog, schema, table):
        """Fallback method to get column count using DESCRIBE."""
        try:
            rows = _metadata_rows(self.spark, f"DESCRIBE TABLE {build_fqn(catalog, schema, table)}", logger=self.logger,
                                  context=f"DESCRIBE {catalog}.{schema}.{table}")
            return len(_parse_describe_rows(rows))
        except SparkWorkCancelled:
            raise
        except Exception as e:
            self.logger.debug(f"DESCRIBE failed while sizing {catalog}.{schema}.{table}: {redact_error(e, max_chars=2000)}")
            return 0

    def _categorize_table(self, num_columns):
        """Categorize table based on column count."""
        if num_columns > 1000:
            return "very_wide"
        elif num_columns > 250:
            return "wide"
        elif num_columns > 100:
            return "medium"
        else:
            return "small"

    def get_cached_size(self, catalog, schema, table):
        """Get cached size info for a table."""
        return self.size_cache.get((catalog, schema, table))


class DynamicBatchOptimizer:
    """
    Intelligently groups tables into batches based on their size and memory requirements.
    
    Strategy:
    - Very wide tables (>1000 cols): 1-2 per batch
    - Wide tables (250-1000 cols): 5-10 per batch
    - Medium tables (100-250 cols): 20-50 per batch
    - Small tables (<100 cols): 100-500 per batch
    """

    # Memory weights for batching (in arbitrary units)
    MAX_BATCH_WEIGHT = 10000  # Adjust based on cluster memory
    MIN_BATCH_SIZE = 1
    MAX_BATCH_SIZE = 500

    def __init__(self, logger, max_batch_weight=None):
        self.logger = logger
        self.max_batch_weight = max_batch_weight or self.MAX_BATCH_WEIGHT

    def create_optimized_batches(self, table_size_infos, joined_groups=()):
        """
        Create optimized batches from table size information.
        
        Args:
            table_size_infos: List of TableSizeInfo objects
            joined_groups: REQ-373 joined groups (frozensets of lowercase (catalog, schema, table) keys). Each group is packed as ONE
                unit, so its tables are read together in one batch. Without groups every unit is one table and packing is unchanged.
            
        Returns:
            List of lists, where each inner list is a batch of (catalog, schema, table) tuples
        """
        if not table_size_infos:
            return []

        group_of = {key: index for index, group in enumerate(joined_groups or ()) for key in group}
        units, unit_by_group = [], {}
        for info in table_size_infos:
            index = group_of.get((str(info.catalog).lower(), str(info.schema).lower(), str(info.table).lower()))
            if index is None:
                units.append([info])
            elif index in unit_by_group:
                unit_by_group[index].append(info)
            else:
                unit_by_group[index] = [info]
                units.append(unit_by_group[index])

        # Sort units by weight (largest first for better packing)
        # REQ-373: a joined group heavier than the batch weight cap is split, so one group cannot push a batch past the cap.
        split_units = []
        for unit in units:
            if len(unit) > 1 and sum(t.memory_weight for t in unit) > self.max_batch_weight:
                chunks = split_unit_by_weight(unit, self.max_batch_weight)
                self.logger.info(f"[JOINED-GROUP SPLIT FIRED] a joined group of {inspire_plural(len(unit), 'table')} is heavier than the "
                                 f"batch cap; split into {inspire_plural(len(chunks), 'batch part')}")
                split_units.extend(chunks)
            else:
                split_units.append(unit)
        units = split_units
        sorted_units = sorted(units, key=lambda unit: sum(t.memory_weight for t in unit), reverse=True)

        batches = []
        current_batch = []
        current_weight = 0

        for unit in sorted_units:
            unit_weight = sum(t.memory_weight for t in unit)

            # Check if adding this unit would exceed batch weight
            if current_batch and (current_weight + unit_weight > self.max_batch_weight or
                                 len(current_batch) + len(unit) > self.MAX_BATCH_SIZE):
                # Start new batch
                batches.append(current_batch)
                self.logger.debug(f"Created batch with {inspire_plural(len(current_batch), 'table')}, weight={current_weight}")
                current_batch = []
                current_weight = 0

            # Add the unit to the current batch
            current_batch.extend((t.catalog, t.schema, t.table) for t in unit)
            current_weight += unit_weight

        # Add final batch
        if current_batch:
            batches.append(current_batch)
            self.logger.debug(f"Created final batch with {inspire_plural(len(current_batch), 'table')}, weight={current_weight}")

        # Log batch statistics
        self._log_batch_stats(batches, table_size_infos)

        return batches

    def _log_batch_stats(self, batches, table_size_infos):
        """Log statistics about the created batches."""
        total_tables = len(table_size_infos)
        num_batches = len(batches)

        size_categories = defaultdict(int)
        for table_info in table_size_infos:
            size_categories[table_info.size_category] += 1

        avg_batch_size = total_tables / num_batches if num_batches > 0 else 0

        self.logger.info(f"📊 Dynamic Batch Optimization Complete:")
        self.logger.info(f"   • Total tables: {total_tables}")
        self.logger.info(f"   • Created batches: {num_batches}")
        self.logger.info(f"   • Average batch size: {avg_batch_size:.1f} tables")
        self.logger.info(f"   • Table size distribution:")
        self.logger.info(f"      - Small (<100 cols): {size_categories['small']}")
        self.logger.info(f"      - Medium (100-250 cols): {size_categories['medium']}")
        self.logger.info(f"      - Wide (250-1000 cols): {size_categories['wide']}")
        self.logger.info(f"      - Very Wide (>1000 cols): {size_categories['very_wide']}")
        if size_categories['unknown']:
            self.logger.info(f"      - Unknown size: {size_categories['unknown']}")


class ColumnSampler:
    """
    Samples columns from very wide tables to reduce memory footprint.
    
    For tables with >250 columns, selects representative columns:
    - Evidence columns are never dropped: declared PK/FK, commented, numeric measure and date/timestamp columns
    - Key-like names that are not declared keys, capped at KEY_COLUMN_CAP
    - Columns with business-meaningful names
    - Evenly spaced sample of the remaining columns
    """

    WIDE_TABLE_THRESHOLD = 250
    TARGET_SAMPLE_SIZE = 200
    KEY_COLUMN_CAP = 50
    BUSINESS_KEYWORDS = (
        'name', 'date', 'time', 'amount', 'total', 'count', 'quantity',
        'price', 'cost', 'revenue', 'customer', 'order', 'product', 'status',
        'type', 'category', 'description', 'address', 'email', 'phone'
    )

    def __init__(self, logger):
        self.logger = logger

    def should_sample(self, num_columns):
        """Determine if column sampling is needed."""
        return num_columns > self.WIDE_TABLE_THRESHOLD

    @staticmethod
    def evidence_rank(column_name, data_type, comment, protected_columns=()):
        """0=declared PK/FK, 1=commented, 2=date/timestamp, 3=numeric measure, 4=key-like name, 5=other."""
        name = str(column_name or "")
        if name.lower() in protected_columns:
            return 0
        if comment is not None and str(comment).strip():
            return 1
        family = _metadata_type_family(data_type)
        if family == "temporal":
            return 2
        key_like = _is_key_like_column(name)
        if family == "numeric" and not key_like:
            return 3
        return 4 if key_like else 5

    def sample_columns(self, column_details, table_info, protected_columns=None):
        """
        Sample columns from a wide table.
        
        Args:
            column_details: List of (catalog, schema, table, col_name, data_type, comment) tuples
            table_info: TableSizeInfo object
            protected_columns: Column names (any case) of declared PK/FK columns that must be kept
            
        Returns:
            Sampled list of column details (original order) + flag indicating whether columns were dropped
        """
        if not self.should_sample(len(column_details)):
            return column_details, False  # No sampling needed

        protected = {str(c).lower() for c in (protected_columns or ())}
        must_keep, key_columns, business_columns, other_columns = [], [], [], []
        for idx, col_detail in enumerate(column_details):
            comment = col_detail[5] if len(col_detail) > 5 else None
            rank = self.evidence_rank(col_detail[3], col_detail[4], comment, protected)
            if rank <= 3:
                must_keep.append(idx)
            elif rank == 4:
                key_columns.append(idx)
            elif any(keyword in str(col_detail[3]).lower() for keyword in self.BUSINESS_KEYWORDS):
                business_columns.append(idx)
            else:
                other_columns.append(idx)

        selected = set(must_keep)
        remaining_slots = max(0, self.TARGET_SAMPLE_SIZE - len(selected))
        kept_keys = key_columns[:min(self.KEY_COLUMN_CAP, remaining_slots)]
        selected.update(kept_keys)
        remaining_slots -= len(kept_keys)
        kept_business = business_columns[:remaining_slots]
        selected.update(kept_business)
        remaining_slots -= len(kept_business)
        kept_other = []
        if remaining_slots > 0 and other_columns:
            step = max(1, len(other_columns) // remaining_slots)
            kept_other = other_columns[::step][:remaining_slots]
            selected.update(kept_other)

        sampled = [column_details[idx] for idx in sorted(selected)]
        was_sampled = len(sampled) < len(column_details)
        self.logger.info(
            f"🎯 Sampled wide table {table_info}: {implement_number_text(len(column_details))} -> {inspire_plural(len(sampled), 'col')} "
            f"({inspire_plural(len(must_keep), 'evidence col')} kept [PK/FK, commented, measure, date/timestamp], "
            f"{implement_number_text(len(kept_keys))}/{implement_number_text(len(key_columns))} key-like, {implement_number_text(len(kept_business))}/{implement_number_text(len(business_columns))} business, "
            f"{implement_number_text(len(kept_other))}/{implement_number_text(len(other_columns))} other)"
        )
        return sampled, was_sampled


