GENIE_OPTIONAL_WIDGETS = frozenset({"act_now_capacity"})


def _genie_number_text(value) -> str:
    return inspire_number_text(value)


GENIE_ALLOWED_FORMS = ("0 to 1", "at least 1", "at most 5", "above 0 and below 1", "whole number, 1 to 10")
GENIE_ALLOWED_FORMS_TEXT = ", ".join(f"'{form}'" for form in GENIE_ALLOWED_FORMS)
_GENIE_OPEN_WORDS = ("above", "greater than", "more than", "below", "less than")


def genie_rule_parts(rule):
    return (tuple(rule) + (False, False))[:5] if rule else (None, None, False, False, False)


def genie_allowed_text(rule) -> str:
    low, high, whole, low_open, high_open = genie_rule_parts(rule)
    if low is not None and high is not None and not low_open and not high_open:
        bounds = f"{_genie_number_text(low)} to {_genie_number_text(high)}"
    else:
        bounds = " and ".join(part for part in (
            "" if low is None else f"{'above' if low_open else 'at least'} {_genie_number_text(low)}",
            "" if high is None else f"{'below' if high_open else 'at most'} {_genie_number_text(high)}") if part)
    return ("whole number" + (f", {bounds}" if bounds else "")) if whole else bounds


_GENIE_ALLOWED_NUMBER = r"(-?[0-9]+(?:\.[0-9]+)?)"
_GENIE_ALLOWED_RE = re.compile(
    rf"(?:(whole number)(?:, |$))?(?:{_GENIE_ALLOWED_NUMBER} to {_GENIE_ALLOWED_NUMBER}"
    rf"|(at least|above|greater than|more than) {_GENIE_ALLOWED_NUMBER}(?: and (at most|below|less than) {_GENIE_ALLOWED_NUMBER})?"
    rf"|(at most|below|less than) {_GENIE_ALLOWED_NUMBER})?")


def genie_allowed_rule(text):
    text = str(text if text is not None else "").strip()
    match = _GENIE_ALLOWED_RE.fullmatch("" if text.lower() == "any" else text)
    if not match:
        return None
    whole, low, high, low_word, low_value, high_word, high_value, only_high_word, only_high_value = match.groups()
    low = low if low is not None else low_value
    high = high if high is not None else (high_value if high_value is not None else only_high_value)
    high_word = high_word or only_high_word
    return (float(low) if low is not None else None, float(high) if high is not None else None, bool(whole),
            low_word in _GENIE_OPEN_WORDS, high_word in _GENIE_OPEN_WORDS)


_GENIE_WIDGET_NUMBER_RE = re.compile(r"-?[0-9]+(?:\.[0-9]+)?")


def genie_setting_bounds(name: str, rule, **extra) -> dict:
    low, high, whole, low_open, high_open = genie_rule_parts(rule)
    return dict({"name": name, "low": low, "high": high, "whole": bool(whole), "low_open": bool(low_open), "high_open": bool(high_open),
                 "allowed": genie_allowed_text(rule)}, **extra)


def genie_widget_value_problem(name: str, value, allowed) -> str:
    rule = genie_allowed_rule(allowed)
    if not rule or tuple(rule[:3]) == (None, None, False):
        return ""
    return inspire_setting_problem(genie_setting_bounds(name, rule, **({"optional": True} if name in GENIE_OPTIONAL_WIDGETS else {})), value)


def genie_widget_set_problems(values: dict) -> list:
    def number(name):
        text = str(values.get(name) if values.get(name) is not None else "").strip()
        return float(text) if _GENIE_WIDGET_NUMBER_RE.fullmatch(text) else None

    problems = []
    act, review = number("act_now_share"), number("review_share")
    if act is not None and review is not None and act + review > 1 + 1e-9:
        problems.append(f"act_now_share + review_share is {_genie_number_text(act + review)}; allowed: at most 1")
    order = inspire_amount_order_problem(number("act_now_amount"), number("review_amount"))
    if order:
        problems.append(order)
    for low_name in sorted(values):
        high_name = "max_" + low_name[4:]
        if low_name.startswith("min_") and high_name in values:
            low, high = number(low_name), number(high_name)
            if low is not None and high is not None and low > high:
                problems.append(f"{low_name} is {_genie_number_text(low)}, above {high_name} {_genie_number_text(high)}")
    return problems

