GENIE_NUMBER_TEXT_SOURCE = '''import math as _inspire_math
import numbers as _inspire_numbers


def is_missing(x):
    if x is None or type(x).__name__ in ("NAType", "NaTType"):
        return True
    return isinstance(x, _inspire_numbers.Real) and not _inspire_math.isfinite(x)


def fmt_num(x, p_value=False):
    try:
        x = float(x)
    except (TypeError, ValueError):
        return "unknown"
    if not _inspire_math.isfinite(x):
        return "unknown"
    if p_value and x < 0.001:
        return "< 0.001"
    if x == 0:
        return "0"
    if x.is_integer():
        return f"{int(x):,}"
    x = round(x, 2 - _inspire_math.floor(_inspire_math.log10(abs(x))))
    suffix = ""
    for scale, unit in ((1e9, "B"), (1e6, "M"), (1e3, "K")):
        if abs(x) >= scale:
            x, suffix = x / scale, unit
            break
    if float(x).is_integer():
        return str(int(x)) + suffix
    text = f"{x:.{max(0, 2 - _inspire_math.floor(_inspire_math.log10(abs(x))))}f}"
    if "." in text:
        text = text.rstrip("0").rstrip(".")
    return text + suffix

def fmt_count(n, noun, plural=None):
    many = plural or f"{noun}s"
    if is_missing(n):
        return f"unknown {many}"
    if float(n) < 0:
        raise ValueError(f"fmt_count got the negative count {n}: write a difference from its sign and pass its absolute value")
    return f"{fmt_num(n)} {noun if float(n) == 1 else many}"


def fmt_rank(r):
    if is_missing(r):
        return "unknown"
    value = float(r)
    if value < 1 or not value.is_integer():
        raise ValueError(f"fmt_rank got {r}, not a whole rank of at least 1: rank ties with method='min' or method='first'")
    rank = int(value)
    suffix = "th" if rank % 100 in (11, 12, 13) else {1: "st", 2: "nd", 3: "rd"}.get(rank % 10, "th")
    return f"{rank:,}{suffix}"


def keep_reasons(facts):
    kept = []
    for text, numbers in facts:
        if text not in kept and not any(is_missing(n) for n in numbers):
            kept.append(text)
    return kept[:3]
'''
