def genie_impact_is_money(impact) -> bool:
    return str((impact or INSPIRE_MONEY_IMPACT).get("kind") or "money") == "money"


def genie_value_at_stake_rule(basis: str, impact=None) -> str:
    if genie_impact_is_money(impact):
        texts = GENIE_VALUE_AT_STAKE_BASIS[basis]
        return GENIE_VALUE_AT_STAKE_RULE.format(stake=GENIE_MONEY_STAKE, measure="price", basis=texts[0],
                                                choices=": `currency` is the currency of the source amounts" + texts[1]
                                                + " Amounts in different currencies are never added together: each currency has "
                                                "its own total and the answer names it, and no total is given across currencies "
                                                "unless every row shares one currency. Answer within the page's default window, the closed periods of the last 12 months, say which window you used, and give all-time totals only when the question asks for them, saying so. When an answer gives a money total, say the one line the App gives under the total: how many rows without a date and from the running month were left out, and how many have no rate.")
    unit, kpi = inspire_stake_noun(impact), impact.get("kpi") or ""
    texts = GENIE_IMPACT_STAKE_BASIS[basis]
    stake = f"the {unit} each record puts at stake on this use case's target KPI" + (f", {kpi}," if kpi else "") + " never money"
    return GENIE_VALUE_AT_STAKE_RULE.format(stake=stake, measure="measure", basis=texts[0].format(unit=unit),
                                            choices=texts[1].format(unit=unit))


def genie_stake_meaning(impact=None) -> str:
    if genie_impact_is_money(impact):
        return ("the money this record puts at stake in the `currency` widget's currency, from the formula the value_at_stake rule "
                "above describes: 0 when nothing is at stake, NULL when the formula cannot price the record, never negative")
    return (f"the {inspire_stake_noun(impact)} this record puts at stake on the target KPI, never money, from the formula the "
            "value_at_stake rule above describes: 0 when nothing is at stake, NULL when the formula cannot measure the record, never "
            "negative")


