class InspireAssetError(RuntimeError):
    pass


def inspire_assets_build_id(pins=None) -> str:
    """The id of this notebook's build: a short sha256 of the notebook pins it reads its assets by.

    The installer names a build's assets folder with the same id (assets_build_id in installer/inspire_setup.py), so an
    install of one build never writes into the folder another build's notebook reads.
    """
    pins = INSPIRE_NOTEBOOK_ASSETS if pins is None else pins
    canonical = {str(name): {"file": pin["file"], "sha256": pin["sha256"], "size": pin["size"]} for name, pin in pins.items()}
    return hashlib.sha256(json.dumps(canonical, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()[:12]


def inspire_environment_problem(environ=None) -> str:
    environ = os.environ if environ is None else environ
    runtime = re.fullmatch(r"client\.(\d+)(?:\.\d+)*", str(environ.get("DATABRICKS_RUNTIME_VERSION") or "").strip())
    stated = re.fullmatch(r"\d+", str(environ.get("DATABRICKS_ENV_VERSION") or "").strip())
    version = runtime.group(1) if runtime else stated.group(0) if stated else ""
    if not version or version == GENIE_NOTEBOOK_ENV_VERSION:
        return ""
    return (f"Inspire runs on serverless environment {GENIE_NOTEBOOK_ENV_VERSION}, and this run is on serverless environment "
            f"{version}, which lacks libraries the Inspire assets are built on. Set the environment version to "
            f"{GENIE_NOTEBOOK_ENV_VERSION} in the notebook's Environment panel, or in the job task's environment, and run Inspire "
            "again.")


def inspire_asset_machine(machine: str = "") -> str:
    import platform
    raw = str(machine or platform.machine()).strip().lower()
    return INSPIRE_ASSET_MACHINES.get(raw, raw)


def inspire_asset_slug(name: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", str(name).lower()).strip("-")


def inspire_asset_file(kind: str, name: str, machine: str = "any", python: str = "any", weight=None) -> str:
    slug = inspire_asset_slug(name)
    if kind == "font":
        return f"fonts/{slug}-{int(weight)}.ttf"
    if kind == "cli":
        return f"cli/{slug}-{machine}{INSPIRE_ASSET_CLIS[name][1]}"
    if kind == "license":
        return f"licenses/{slug}.txt"
    return f"python/{slug}.whl" if machine == "any" else f"python/{slug}-cp{python.replace('.', '')}-{machine}.whl"


def inspire_cli_release_file(name: str, version: str, machine: str) -> str:
    source = INSPIRE_ASSET_CLI_SOURCES[name]
    return source["asset"].format(target=source["targets"][machine], version=version)


def inspire_cli_release_url(name: str, file: str, version: str) -> str:
    return INSPIRE_ASSET_CLI_RELEASE.format(repo=INSPIRE_ASSET_CLI_SOURCES[name]["repo"], version=version, name=file)


def inspire_trusted_download_url(url, repo: str) -> str:
    import urllib.parse
    text = str(url)
    parts = urllib.parse.urlsplit(text)
    host = (parts.hostname or "").lower()
    try:
        port = parts.port
    except ValueError:
        port = -1
    if parts.scheme != "https" or host not in INSPIRE_ASSET_DOWNLOAD_HOSTS or parts.username or parts.password \
            or port not in (None, 443) or ".." in parts.path.split("/") \
            or (host == "github.com" and not parts.path.startswith(INSPIRE_ASSET_RELEASE_PATH.format(repo=repo))):
        raise InspireAssetError(f"{inspire_redact_text(text, set(), '')[:200]} is not an HTTPS release file of {repo} on github.com or "
                                "its download host, so Inspire refuses it")
    return text


def inspire_open_release_file(url: str, repo: str, timeout: float):
    import ssl
    import urllib.parse
    import urllib.request

    class TrustedRedirects(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, req, fp, code, msg, headers, newurl):
            inspire_trusted_download_url(urllib.parse.urljoin(req.full_url, newurl), repo)
            return super().redirect_request(req, fp, code, msg, headers, newurl)

    opener = urllib.request.build_opener(TrustedRedirects(), urllib.request.HTTPSHandler(context=ssl.create_default_context()))
    request = urllib.request.Request(inspire_trusted_download_url(url, repo), headers={"User-Agent": "inspire-agent"})
    return opener.open(request, timeout=timeout)


def inspire_drop_loaded(top: str) -> None:
    for name in [n for n in sys.modules if n == top or n.startswith(top + ".")]:
        del sys.modules[name]


def inspire_wheel_packages(names) -> list:
    tops = {str(name).split("/", 1)[0] for name in names}
    return sorted(top[:-3] if top.endswith(".py") else top for top in tops
                  if top and not top.endswith((".dist-info", ".data", ".libs", ".pth")))


def inspire_assets_path_setting() -> str:
    """The assets folder the App passes a job (inspire_assets_path), read through inspire_widget so an applied setting wins.

    D-SIZE2 (REQ-298): the first read of the assets is the result-history source, the code that defines inspire_widget, so that
    read takes the job parameter the way inspire_widget does, with no applied settings (none exist before the run starts)."""
    if "inspire_widget" in globals():
        return inspire_widget("inspire_assets_path")
    try:
        return str(dbutils.widgets.get("inspire_assets_path")).strip()
    except Exception:
        return ""


class InspireAssets:
    _SHARED = {}
    _SHARED_LOCK = threading.Lock()

    def __init__(self, root: str = "", local: str = "", machine: str = "", opener=None):
        self.root = str(root or inspire_assets_path_setting() or f"{INSPIRE_ASSETS_FOLDER}/{__AGENT_VERSION__}/{inspire_assets_build_id()}").rstrip("/")
        self.local = local or os.path.join(tempfile.gettempdir(), "inspire_assets",
                                           hashlib.sha256(self.root.encode("utf-8")).hexdigest()[:16])
        self.machine = inspire_asset_machine(machine)
        self._manifest = None
        self._checked = {}
        self._extracted = set()
        self._lock = threading.RLock()
        self._open = opener or inspire_open_release_file
        self.cli_from = {}

    @classmethod
    def shared(cls, root: str = "") -> "InspireAssets":
        with cls._SHARED_LOCK:
            if root not in cls._SHARED:
                cls._SHARED[root] = cls(root)
            return cls._SHARED[root]

    def problem(self, file: str, what: str) -> InspireAssetError:
        return InspireAssetError(f"The Inspire assets file {self.root}/{file} {what}. "
                                 + INSPIRE_ASSETS_INSTALL_STEP.format(version=__AGENT_VERSION__, root=self.root))

    def manifest(self) -> dict:
        with self._lock:
            if self._manifest is None:
                try:
                    with open(f"{self.root}/{INSPIRE_ASSETS_MANIFEST}", encoding="utf-8") as handle:
                        data = json.load(handle)
                except FileNotFoundError:
                    raise self.problem(INSPIRE_ASSETS_MANIFEST, "is missing") from None
                except (OSError, ValueError) as error:
                    raise self.problem(INSPIRE_ASSETS_MANIFEST, f"cannot be read: {redact_error(error, max_chars=200)}") from None
                if not isinstance(data, dict) or data.get("format") != INSPIRE_ASSETS_FORMAT or not isinstance(data.get("files"), list):
                    raise self.problem(INSPIRE_ASSETS_MANIFEST, "is not an assets manifest this Inspire reads")
                if data.get("inspire_version") != __AGENT_VERSION__:
                    held = inspire_redact_text(str(data.get("inspire_version")), set(), "")[:40]
                    raise self.problem(INSPIRE_ASSETS_MANIFEST, f"is for Inspire {held}, not {__AGENT_VERSION__}")
                self._manifest = data
            return self._manifest

    def entries(self, kind: str, name: str) -> list:
        return [e for e in self.manifest()["files"] if isinstance(e, dict) and e.get("kind") == kind and e.get("name") == name]

    def entry(self, kind: str, name: str, version: str = "", weight=None, python: str = "any", machine: str = "") -> dict:
        machine = machine or self.machine
        found = [e for e in self.entries(kind, name) if (weight is None or e.get("weight") == weight)
                 and e.get("machine", "any") in (machine, "any") and e.get("python", "any") in (python, "any")]
        if not found:
            wanted = (f"{name} {weight}" if kind == "font" else f"{name} for {machine}" if kind == "cli"
                      else f"{name} for {machine} and Python {python}")
            raise self.problem(INSPIRE_ASSETS_MANIFEST, f"lists no {wanted}")
        held = str(found[0].get("version"))
        if version and held != version:
            raise self.problem(str(found[0].get("file")), f"holds {name} {inspire_redact_text(held, set(), '')[:40]}, and this "
                                                          f"Inspire needs {name} {version}")
        return found[0]

    def _verify_file(self, entry: dict, sink=None) -> None:
        file = str(entry.get("file") or "")
        digest, size = hashlib.sha256(), 0
        try:
            with open(f"{self.root}/{file}", "rb") as handle:
                for block in iter(lambda: handle.read(1 << 20), b""):
                    digest.update(block)
                    size += len(block)
                    if sink is not None:
                        sink.write(block)
        except FileNotFoundError:
            raise self.problem(file, "is missing") from None
        except OSError as error:
            raise self.problem(file, f"cannot be read: {redact_error(error, max_chars=200)}") from None
        if size != entry.get("size") or digest.hexdigest() != entry.get("sha256"):
            raise self.problem(file, "does not match its size and sha256 in manifest.json, so it is damaged or was changed")

    def _download_cli(self, name: str, entry: dict, sink, installed: str) -> None:
        why = self._fetch_cli(name, entry, sink)
        if why:
            version = str(entry.get("version"))
            raise InspireAssetError(f"Databricks AI needs {name} {version} built for the {self.machine} CPU this run landed on. The "
                                    f"installed copy {self.root}/{entry.get('file')} {installed}, and {why}. Run the Inspire "
                                    f"installer again so it installs the Inspire {__AGENT_VERSION__} assets into {self.root}, then "
                                    "run this again.")

    def _fetch_cli(self, name: str, entry: dict, sink) -> str:
        import http.client
        import urllib.error
        repo = INSPIRE_ASSET_CLI_SOURCES[name]["repo"]
        expected, sha = entry.get("size"), str(entry.get("sha256") or "")
        if self.machine not in INSPIRE_ASSET_CLI_SOURCES[name]["targets"]:
            return f"{name} publishes no build for {self.machine} to download"
        if not isinstance(expected, int) or isinstance(expected, bool) or not re.fullmatch(r"[0-9a-f]{64}", sha):
            return "manifest.json lists no size and sha256 to check a download against"
        version = str(entry.get("version"))
        url = inspire_cli_release_url(name, inspire_cli_release_file(name, version, self.machine), version)
        try:
            with self._open(url, repo, INSPIRE_ASSET_REACH_TIMEOUT_S):
                pass
        except InspireAssetError as error:
            return redact_error(error, max_chars=400)
        except urllib.error.HTTPError as error:
            return f"{url} answered HTTP {int(error.code)}"
        except (OSError, ValueError, http.client.HTTPException) as error:
            return (f"this run cannot reach github.com within {INSPIRE_ASSET_REACH_TIMEOUT_S} seconds to download it "
                    f"({redact_error(error, max_chars=160)})")
        digest, size = hashlib.sha256(), 0
        try:
            with self._open(url, repo, INSPIRE_ASSET_READ_TIMEOUT_S) as response:
                inspire_trusted_download_url(response.geturl(), repo)
                for block in iter(lambda: response.read(1 << 20), b""):
                    size += len(block)
                    if size > expected:
                        break
                    digest.update(block)
                    sink.write(block)
        except InspireAssetError as error:
            return redact_error(error, max_chars=400)
        except (OSError, ValueError, http.client.HTTPException) as error:
            return f"the download from {url} failed ({redact_error(error, max_chars=160)})"
        if size != expected or digest.hexdigest() != sha:
            return f"the download from {url} does not match its size and sha256 in manifest.json, so Inspire refuses it"
        return ""

    def path(self, entry: dict) -> str:
        path = f"{self.root}/{entry.get('file')}"
        with self._lock:
            if path not in self._checked:
                self._verify_file(entry)
                self._checked[path] = path
        return path

    def local_copy(self, entry: dict, fill=None) -> str:
        target = os.path.join(self.local, f"{str(entry.get('sha256'))[:16]}-{os.path.basename(str(entry.get('file')))}")
        with self._lock:
            if target not in self._checked:
                os.makedirs(self.local, exist_ok=True)
                partial = f"{target}.part"
                try:
                    with open(partial, "wb") as sink:
                        (fill or self._verify_file)(entry, sink)
                except BaseException:
                    if os.path.exists(partial):
                        os.remove(partial)
                    raise
                os.replace(partial, target)
                self._checked[target] = target
        return target

    def cli(self, name: str) -> str:
        entry = self.entry("cli", name, INSPIRE_ASSET_CLIS[name][0])
        try:
            path = self.local_copy(entry)
            how = self.cli_from.get(name, "installed")
        except InspireAssetError:
            installed = ("is missing" if not os.path.exists(f"{self.root}/{entry.get('file')}")
                         else "does not match its size and sha256 in manifest.json or cannot be read")
            path = self.local_copy(entry, lambda e, sink: self._download_cli(name, e, sink, installed))
            how = "downloaded"
        self.cli_from[name] = how
        return path

    def python(self, module: str, python: str = INSPIRE_ASSETS_PYTHON) -> str:
        import importlib
        import zipfile
        site = os.path.join(self.local, f"python{python}")
        with self._lock:
            for dist in INSPIRE_ASSET_MODULES[module]:
                if dist in self._extracted:
                    continue
                version = INSPIRE_ASSET_WHEELS[dist]
                with zipfile.ZipFile(self.local_copy(self.entry("python", dist, version, python=python))) as archive:
                    native = any(n.endswith((".so", ".pyd")) for n in archive.namelist())
                    for top in inspire_wheel_packages(archive.namelist()):
                        held = sys.modules.get(top)
                        where = os.path.realpath(str(getattr(held, "__file__", "") or "")) if held is not None else ""
                        if held is not None and not where.startswith(os.path.realpath(site) + os.sep):
                            if native or not where:
                                raise InspireAssetError(f"{top} is already loaded in this Python process from {where or 'a built-in module'}, "
                                                        f"so Inspire cannot load {dist} {version} from its assets; restart Python and run "
                                                        "again")
                            inspire_drop_loaded(top)
                    archive.extractall(site)
                self._extracted.add(dist)
            if site in sys.path:
                sys.path.remove(site)
            sys.path.insert(0, site)
            importlib.invalidate_caches()
        return site

    def app_files(self) -> dict:
        import zipfile
        files = {}
        for dist in INSPIRE_APP_ASSET_WHEELS:
            version = INSPIRE_ASSET_WHEELS[dist]
            found = [e for e in self.entries("python", dist) if e.get("python", "any") in (INSPIRE_APP_ASSETS_PYTHON, "any")]
            if not found:
                raise self.problem(INSPIRE_ASSETS_MANIFEST, f"lists no {dist} for Python {INSPIRE_APP_ASSETS_PYTHON}, which an App on "
                                                            "Lakebase runs")
            for entry in found:
                held = str(entry.get("version"))
                if held != version:
                    raise self.problem(str(entry.get("file")), f"holds {dist} {inspire_redact_text(held, set(), '')[:40]}, and this "
                                                               f"Inspire needs {dist} {version}")
                with zipfile.ZipFile(self.local_copy(entry)) as archive:
                    for info in archive.infolist():
                        if not info.is_dir():
                            files[info.filename] = archive.read(info)
        return files

    def notebook_file(self, name: str) -> bytes:
        pin = INSPIRE_NOTEBOOK_ASSETS[name]
        found = [e for e in self.entries("notebook", name) if e.get("file") == pin["file"]]
        if not found:
            raise self.problem(INSPIRE_ASSETS_MANIFEST, f"lists no {pin['file']}")
        if (found[0].get("sha256"), found[0].get("size")) != (pin["sha256"], pin["size"]):
            raise self.problem(pin["file"], "is from another Inspire build than this notebook")
        sink = io.BytesIO()
        self._verify_file(found[0], sink)
        return sink.getvalue()


_INSPIRE_NOTEBOOK_ASSET_TEXT = {}


def inspire_repo_assets_root() -> str:
    if os.environ.get("DATABRICKS_RUNTIME_VERSION"):
        return ""
    return os.environ.get(INSPIRE_REPO_ASSETS_ENV, "")


def inspire_repo_asset(root: str, name: str) -> bytes:
    pin = INSPIRE_NOTEBOOK_ASSETS[name]
    path = os.path.join(root, pin["repo"])
    try:
        with open(path, "rb") as handle:
            data = handle.read()
    except OSError as error:
        raise InspireAssetError(f"{path} cannot be read ({redact_error(error, max_chars=200)}); run "
                                "`python3 agent/app_shell/embed.py write` in the repo") from None
    if (hashlib.sha256(data).hexdigest(), len(data)) != (pin["sha256"], pin["size"]):
        raise InspireAssetError(f"{path} is not the build this notebook pins; run `python3 agent/app_shell/embed.py write` in the repo")
    return data


def inspire_notebook_asset(name: str) -> str:
    if name not in _INSPIRE_NOTEBOOK_ASSET_TEXT:
        repo = inspire_repo_assets_root()
        data = inspire_repo_asset(repo, name) if repo else InspireAssets.shared().notebook_file(name)
        _INSPIRE_NOTEBOOK_ASSET_TEXT[name] = data.decode("utf-8")
    return _INSPIRE_NOTEBOOK_ASSET_TEXT[name]


