# REQ-587 G1 (T-587-A-01): the domain-name limits are the pinned shared asset (app/shared/domain_rules.json), the same file the App reads.
INSPIRE_DOMAIN_RULES = json.loads(inspire_notebook_asset("domain_rules"))
INSPIRE_DOMAIN_KINDS = ("domain", "subdomain")


def inspire_domain_name_check(name, kind, user_named=False) -> dict:
    """Check a domain or subdomain name against INSPIRE_DOMAIN_RULES. Codes: empty, spacing, characters, case, word_count, plural,
    user_kept. A user-named name is kept verbatim (valid, repaired None) and carries user_kept when it breaks any other code."""
    if kind not in INSPIRE_DOMAIN_KINDS:
        raise ValueError(f"unknown name kind {kind!r}, expected one of {INSPIRE_DOMAIN_KINDS}")
    rules = INSPIRE_DOMAIN_RULES[kind]
    text = str(name or "")
    if not text.strip():
        return {"valid": False, "repaired": None, "problems": ["empty"]}
    found = set()
    if text != " ".join(text.split()):
        found.add("spacing")
    chars = []
    for i, ch in enumerate(text):
        if ch.isalnum() or ch.isspace():
            chars.append(ch)
        elif ch == "&" and 0 < i < len(text) - 1 and text[i - 1].isalpha() and text[i + 1].isalpha():
            chars.append(ch)
        else:
            found.add("characters")
            chars.append(" ")
    words = "".join(chars).split()
    if any(w != w.capitalize() and not w.isupper() for w in words):
        found.add("case")
        words = [w if w.isupper() else w.capitalize() for w in words]
    if len(words) != rules["words"]:
        found.add("word_count")
    elif kind == "domain" and rules.get("singular") and len(words) == 1:
        word = words[0]
        keep = {k.lower() for k in rules.get("keep_as_is", ())}
        singular = _singular_token(word)
        if word.lower() not in keep and singular != word.lower():
            found.add("plural")
            words = [singular.upper() if word.isupper() else singular.capitalize()]
    repaired = " ".join(words)
    if "word_count" in found or user_named or repaired == text:
        repaired = None
    order = ("spacing", "characters", "case", "word_count", "plural")
    problems = [c for c in order if c in found]
    if user_named:
        return {"valid": True, "repaired": None, "problems": problems + (["user_kept"] if problems else [])}
    return {"valid": not problems, "repaired": repaired, "problems": problems}


# REQ-573 R13.1, R13.2: deep calculation on the shortlist. It names the agent (DeepEvidence, DatabricksInspire), so it lives here,
# not in the result_history source that every generated notebook inlines.
import statistics as _deep_statistics


# REQ-573 R13.1, R13.2: deep calculation on the shortlist, one shared GROUPING SETS scan per pool table.
_DEEP_SEGMENT_ROLES = ("region_code", "label_column", "action_target", "entity_name")
_DEEP_CURRENCY_TOKENS = frozenset({"currency", "ccy", "curr"})
_DEEP_SCAN_COLUMNS = ("grouping_set", "uc", "other_uc", "currency", "month", "segment_column", "segment_value", "decile", "rows",
                      "outcome_rows", "measured_rows", "pool", "entities", "first_day", "last_day", "null_entity")
_DEEP_SCAN_TYPES = {"decile": "INT", "rows": "BIGINT", "outcome_rows": "BIGINT", "measured_rows": "BIGINT", "pool": "DOUBLE",
                    "entities": "BIGINT", "null_entity": "BIGINT"}


def _deep_num(value):
    try:
        number = float(value)
    except (TypeError, ValueError):
        return None
    return None if number != number else number


def _deep_int(value):
    number = _deep_num(value)
    return 0 if number is None else int(number)


def _deep_pool_kpi(uc: dict):
    for kpi in (uc.get("KPIs") or []) if isinstance(uc, dict) else []:
        if not isinstance(kpi, dict) or not (kpi.get("table") and kpi.get("column")) or kpi.get("metric_view") or kpi.get("denominator"):
            continue
        try:
            aggregate = DeepEvidence.canonical_aggregate(kpi.get("aggregation"))
        except ValueError:
            continue
        if aggregate in ("SUM", "COUNT"):
            return kpi
    return None


def inspire_deep_scan_plan(use_cases, metadata) -> dict:
    """One scan plan per pool table (a use case's pool KPI: SUM or COUNT of a column, no metric view, no ratio). Pure."""
    plans, unplanned, by_table = [], [], {}
    for uc in use_cases or []:
        kpi = _deep_pool_kpi(uc)
        if kpi is None:
            unplanned.append({"No": uc.get("No"), "reason": "no_pool_kpi"})
            continue
        table = str(kpi["table"])
        if table not in by_table:
            by_table[table] = []
            plans.append({"table": table, "use_cases": by_table[table]})
        spec = (uc.get("Value Estimate") or {}).get("value_spec") if isinstance(uc.get("Value Estimate"), dict) else None
        by_table[table].append({"No": uc.get("No"), "kpi": kpi, "direction": kpi.get("direction") or "decrease",
                                "value_spec": spec if isinstance(spec, dict) else None})
    out = []
    for plan in plans:
        items = plan["use_cases"]
        entry = (metadata or {}).get(plan["table"].replace("`", "").lower()) or {}
        columns = (entry.get("columns") or {}) if isinstance(entry, dict) else {}
        types = {name: (info or {}).get("type") or "" for name, info in columns.items()}
        comments = {name: (info or {}).get("comment") or "" for name, info in columns.items()}
        kpis = [item["kpi"] for item in items]
        time_column = next((kpi["time_column"] for kpi in kpis if kpi.get("time_column")), None) \
            or next((name for name, kind in types.items() if _metadata_type_family(kind) == "temporal"), None)
        currency_column = next((name for name, kind in types.items() if _metadata_type_family(kind) == "string"
                                and set(DatabricksInspire._role_tokens(name)) & _DEEP_CURRENCY_TOKENS), None)
        grains = {kpi.get("grain_key") for kpi in kpis if kpi.get("grain_key")}
        first = next(iter(columns), None)
        entity_column = next((kpi["entity_column"] for kpi in kpis if kpi.get("entity_column")), None) or next(
            (name for name in columns if _is_key_like_column(name) and name not in grains and name != first
             and name not in (time_column, currency_column)), None)
        skip = {time_column, currency_column, entity_column, *(kpi.get("filter_column") for kpi in kpis)}
        roles = DatabricksInspire._column_roles(types, comments)[0] if types else {}
        strings = [name for name, kind in types.items() if _metadata_type_family(kind) == "string" and name not in skip
                   and not _is_key_like_column(name) and name not in (roles.get("free_text") or [])]
        by_role = [name for role in _DEEP_SEGMENT_ROLES for name in strings if name in (roles.get(role) or [])]
        segments = list(dict.fromkeys(by_role + strings))[:3]
        out.append({"table": plan["table"], "scan_id": "ds" + hashlib.sha256(plan["table"].encode("utf-8")).hexdigest()[:12],
                    "time_column": time_column, "currency_column": currency_column, "entity_column": entity_column,
                    "segment_columns": segments, "window_days": 730, "use_cases": items})
    return {"plans": out, "unplanned": unplanned}


def inspire_deep_scan_sql(plan: dict, scopes=None) -> str:
    """ONE read-only statement for a pool table: its rows are read once into a CTE; the totals, months and segments of every
    use case come from one GROUPING SETS aggregate, the deciles from NTILE(10) over per-entity pools, the pair overlaps from
    one more aggregate. Never a LIMIT or a sample (R12.8)."""
    quote, literal = inspire_quote_identifier, inspire_sql_literal
    items = plan["use_cases"]
    time_column, currency, entity = plan.get("time_column"), plan.get("currency_column"), plan.get("entity_column")
    segments = list(plan.get("segment_columns") or [])[:3]
    assert_scope_columns(plan["table"], [time_column, currency, entity, *segments,
                                         *(name for item in items for name in (item["kpi"].get("column"), item["kpi"].get("filter_column")))], scopes)
    source = inspire_scoped_read_source(plan["table"], scopes)
    window = DeepEvidence._kpi_window_conditions({"time_column": time_column, "window_days": plan.get("window_days") or 730}, source) \
        if time_column else []
    base = [f"CAST({quote(currency)} AS STRING) AS ds_ccy" if currency else "CAST(NULL AS STRING) AS ds_ccy",
            f"CAST({quote(time_column)} AS DATE) AS ds_day" if time_column else "CAST(NULL AS DATE) AS ds_day",
            f"CAST(DATE_TRUNC('MONTH', {quote(time_column)}) AS DATE) AS ds_mo" if time_column else "CAST(NULL AS DATE) AS ds_mo",
            f"CAST({quote(entity)} AS STRING) AS ds_ent" if entity else "CAST(NULL AS STRING) AS ds_ent"]
    base += [f"CAST({quote(name)} AS STRING) AS ds_s{index}" for index, name in enumerate(segments)]
    stack = []
    for index, item in enumerate(items):
        kpi = item["kpi"]
        condition = kpi_filter_sql(kpi)
        measure = quote(kpi["column"])
        value = f"CAST({measure} AS DOUBLE)" if DeepEvidence.canonical_aggregate(kpi.get("aggregation")) == "SUM" \
            else f"CASE WHEN {measure} IS NOT NULL THEN 1.0 END"
        base += [f"COALESCE(({condition}), FALSE) AS ds_h{index}" if condition else f"TRUE AS ds_h{index}", f"{value} AS ds_m{index}"]
        stack += [literal(item["No"]), f"ds_h{index}", f"ds_m{index}"]
    where = f" WHERE {' AND '.join(window)}" if window else ""
    keep = ", ".join(["ds_ccy", "ds_day", "ds_mo", "ds_ent", *(f"ds_s{index}" for index in range(len(segments)))])
    ctes = [f"base AS (SELECT {', '.join(base)} FROM {source}{where})",
            f"e AS (SELECT {keep}, x.ds_uc, x.ds_hit, x.ds_val FROM base LATERAL VIEW STACK({len(items)}, {', '.join(stack)}) x "
            f"AS ds_uc, ds_hit, ds_val)"]

    def select(overrides: dict, source_sql: str, tail: str = "") -> str:
        cells = [f"{overrides.get(name) or 'CAST(NULL AS ' + _DEEP_SCAN_TYPES.get(name, 'STRING') + ')'} AS `{name}`"
                 for name in _DEEP_SCAN_COLUMNS]
        return f"SELECT {', '.join(cells)} FROM {source_sql}{tail}"

    seg_group = [f"g{index} = 0" for index in range(len(segments))]
    sets = ["(ds_uc, ds_ccy)", "(ds_uc, ds_ccy, ds_mo)"] + [f"(ds_uc, ds_ccy, ds_s{index})" for index in range(len(segments))]
    grouping = ", ".join(["GROUPING(ds_mo) AS g_mo"] + [f"GROUPING(ds_s{index}) AS g{index}" for index in range(len(segments))])
    ctes.append(
        f"agg AS (SELECT ds_uc, ds_ccy, ds_mo, {', '.join(f'ds_s{index}' for index in range(len(segments)))}{', ' if segments else ''}{grouping}, "
        "COUNT(*) AS n_rows, SUM(CASE WHEN ds_hit THEN 1 ELSE 0 END) AS n_hit, "
        "SUM(CASE WHEN ds_hit AND ds_val IS NOT NULL THEN 1 ELSE 0 END) AS n_measured, SUM(CASE WHEN ds_hit THEN ds_val END) AS v_pool, "
        "COUNT(DISTINCT CASE WHEN ds_hit THEN ds_ent END) AS n_ent, CAST(MIN(CASE WHEN ds_hit THEN ds_day END) AS STRING) AS d_first, "
        "CAST(MAX(CASE WHEN ds_hit THEN ds_day END) AS STRING) AS d_last, "
        "SUM(CASE WHEN ds_hit AND ds_ent IS NULL THEN 1 ELSE 0 END) AS n_null_ent "
        f"FROM e GROUP BY GROUPING SETS ({', '.join(sets)}))")
    segment_label = "CASE " + " ".join(f"WHEN g{index} = 0 THEN {literal(name)}" for index, name in enumerate(segments)) + " END" if segments else None
    segment_value = "CASE " + " ".join(f"WHEN g{index} = 0 THEN ds_s{index}" for index in range(len(segments))) + " END" if segments else None
    kind = ("CASE WHEN g_mo = 0 THEN 'month' " + (f"WHEN {' OR '.join(seg_group)} THEN 'segment' " if segments else "") + "ELSE 'total' END")
    selects = [select({"grouping_set": kind, "uc": "ds_uc", "currency": "ds_ccy", "month": "CAST(ds_mo AS STRING)",
                       "segment_column": segment_label, "segment_value": segment_value, "rows": "n_rows", "outcome_rows": "n_hit",
                       "measured_rows": "n_measured", "pool": "CASE WHEN n_measured > 0 THEN v_pool END", "entities": "n_ent",
                       "first_day": "d_first", "last_day": "d_last", "null_entity": "n_null_ent"}, "agg")]
    if entity:
        ctes.append("ep AS (SELECT ds_uc, ds_ccy, ds_ent, SUM(ds_val) AS v_pool FROM e WHERE ds_hit AND ds_ent IS NOT NULL "
                    "GROUP BY ds_uc, ds_ccy, ds_ent)")
        ctes.append("dc AS (SELECT ds_uc, ds_ccy, v_pool, NTILE(10) OVER (PARTITION BY ds_uc, ds_ccy ORDER BY v_pool DESC NULLS LAST) "
                    "AS ds_dec FROM ep)")
        selects.append(select({"grouping_set": "'decile'", "uc": "ds_uc", "currency": "ds_ccy", "decile": "ds_dec", "pool": "SUM(v_pool)",
                               "entities": "COUNT(*)"}, "dc", " GROUP BY ds_uc, ds_ccy, ds_dec"))
    if len(items) > 1:
        pairs = [(a, b) for a in range(len(items)) for b in range(a + 1, len(items))]
        ctes.append(f"ov AS (SELECT {', '.join(f'SUM(CASE WHEN ds_h{a} AND ds_h{b} THEN 1 ELSE 0 END) AS p{k}' for k, (a, b) in enumerate(pairs))} FROM base)")
        flat = ", ".join(f"{literal(items[a]['No'])}, {literal(items[b]['No'])}, p{k}" for k, (a, b) in enumerate(pairs))
        selects.append(select({"grouping_set": "'overlap'", "uc": "o.ds_a", "other_uc": "o.ds_b", "outcome_rows": "o.ds_n"},
                              f"ov LATERAL VIEW STACK({len(pairs)}, {flat}) o AS ds_a, ds_b, ds_n"))
    return "WITH " + ", ".join(ctes) + " " + " UNION ALL ".join(selects)


def inspire_deep_sensitivity(value_spec):
    """The sourced range that moves the value most, one at a time, through inspire_value_calculate (the one calculator)."""
    if not isinstance(value_spec, dict) or not isinstance(value_spec.get("sourced"), dict):
        return None
    sourced = {name: rng for name, rng in value_spec["sourced"].items()
               if isinstance(rng, dict) and all(_inspire_value_num(rng.get(key)) for key in INSPIRE_VALUE_SCENARIOS)}
    if not sourced or not inspire_value_calculate(value_spec).get("ok"):
        return None

    def priced(name, pick):
        flat = {key: {**rng, **dict.fromkeys(INSPIRE_VALUE_SCENARIOS, rng[pick] if key == name else rng["base"])}
                for key, rng in sourced.items()}
        out = inspire_value_calculate({**value_spec, "sourced": {**value_spec["sourced"], **flat}})
        if not out.get("ok"):
            return None, None
        row = out["scenarios"]["base"]
        return (row["change"] if row.get("gross_annual") is None else row["gross_annual"]), out.get("unit")

    best = None
    for name, rng in sourced.items():
        (low, unit), (high, _unit) = priced(name, "low"), priced(name, "high")
        if low is None or high is None:
            continue
        swing = abs(high - low)
        if best is None or swing > best["swing"]:
            best = {"assumption": name, "low": rng["low"], "high": rng["high"], "swing": swing, "unit": unit}
    return best


def _deep_month_ordinal(key):
    return int(key[:4]) * 12 + int(key[5:7])


def _deep_trend(points):
    known = [(x, y) for x, y in points if y is not None]
    if len(known) < 3:
        return None
    mean_x, mean_y = sum(x for x, _y in known) / len(known), sum(y for _x, y in known) / len(known)
    spread = sum((x - mean_x) ** 2 for x, _y in known)
    slope = sum((x - mean_x) * (y - mean_y) for x, y in known) / spread if spread else 0.0
    flat = slope == 0 or abs(slope) < 0.01 * abs(mean_y)
    return {"slope_per_month": slope, "direction": "flat" if flat else "rising" if slope > 0 else "falling"}


def _deep_seasonality(months):
    last = months[-24:]
    if len(months) < 24 or any(item["pool"] is None for item in last) \
            or _deep_month_ordinal(last[-1]["month"]) - _deep_month_ordinal(last[0]["month"]) != 23:
        return None
    averages = {}
    for item in last:
        averages.setdefault(item["month"][5:7], []).append(item["pool"])
    means = [sum(values) / len(values) for values in averages.values()]
    mean = sum(means) / len(means)
    peaks = [max(year, key=lambda item: item["pool"])["month"][5:7] for year in (last[:12], last[12:])]
    return bool(mean > 0 and (max(means) - min(means)) / mean >= 0.5 and peaks[0] == peaks[1])


def _deep_benchmark(segments, direction):
    values = [(item["value"], item["pool"] / item["rows"], item["rows"]) for item in segments
              if item["value"] is not None and item["pool"] is not None and item["rows"]]
    values.sort(key=lambda item: str(item[0]))
    if len(values) < 3:
        return {"label": "descriptive", "reason": "too_few_segments"}
    metrics = [metric for _value, metric, _rows in values]
    median = _deep_statistics.median(metrics)
    quartiles = _deep_statistics.quantiles(metrics, n=4, method="inclusive")
    down = not re.search(r"increase|up|higher|grow", str(direction or ""), re.IGNORECASE)
    best = quartiles[0] if down else quartiles[2]
    worse = lambda reference: [item for item in values if (item[1] > reference if down else item[1] < reference)]
    gap = lambda reference: sum(rows * abs(metric - reference) for _value, metric, rows in worse(reference))
    return {"label": "descriptive", "median": median, "best_quartile": best, "worse_segments": [item[0] for item in worse(median)],
            "gap_to_median": gap(median), "gap_to_best_quartile": gap(best)}


def _deep_block(plan, item, currency, slot, filtered):
    total = slot["total"] or {}
    rows, outcome, measured = (_deep_int(total.get(key)) for key in ("rows", "outcome_rows", "measured_rows"))
    flags = []
    pool = _deep_num(total.get("pool")) if measured else None
    if not measured:
        flags.append("measure_missing")
    elif measured < outcome:
        flags.append("measure_partly_missing")
    rate = lambda hit, all_rows: (hit / all_rows if all_rows else None) if filtered else None
    by_month = {}
    for row in slot["month"]:
        key = str(row.get("month"))[:7]
        month_rows, month_hit = _deep_int(row.get("rows")), _deep_int(row.get("outcome_rows"))
        by_month[key] = {"month": key, "pool": _deep_num(row.get("pool")) if _deep_int(row.get("measured_rows")) else None,
                         "rows": month_rows, "outcome_rows": month_hit, "outcome_rate": rate(month_hit, month_rows)}
    months = [by_month[key] for key in sorted(by_month)]
    short = len(months) < 12
    if short:
        flags.append("short_history")
    last = months[-12:]
    annualised = sum(m["pool"] for m in last) if not short and all(m["pool"] is not None for m in last) \
        and _deep_month_ordinal(last[-1]["month"]) - _deep_month_ordinal(last[0]["month"]) == 11 else None
    population = deciles = top = None
    if plan.get("entity_column"):
        population = None if total.get("entities") is None else _deep_int(total.get("entities"))
        parts = sorted((_deep_int(row.get("decile")), _deep_num(row.get("pool"))) for row in slot["decile"])
        whole = sum(p for _d, p in parts if p is not None)
        if parts and whole:
            deciles = [(p or 0.0) / whole for _d, p in parts]
            top = deciles[0] if parts[0][0] == 1 else None
    else:
        flags.append("no_entity_column")
    by_segment, spread_segment = {}, {}
    for row in slot["segment"]:
        seg_rows, seg_hit = _deep_int(row.get("rows")), _deep_int(row.get("outcome_rows"))
        by_segment.setdefault(row.get("segment_column"), []).append(
            {"value": row.get("segment_value"), "pool": _deep_num(row.get("pool")) if _deep_int(row.get("measured_rows")) else None,
             "rows": seg_rows, "outcome_rows": seg_hit, "outcome_rate": rate(seg_hit, seg_rows)})
    for column, entries in by_segment.items():
        entries.sort(key=lambda entry: (entry["value"] is None, str(entry["value"])))
        rates = [entry["outcome_rate"] for entry in entries if entry["outcome_rate"] is not None]
        if rates:
            spread_segment[column] = max(rates) - min(rates)
    month_rates = [m["outcome_rate"] for m in months if m["outcome_rate"] is not None]
    return {"currency": currency, "pool": pool, "rows": rows, "outcome_rows": outcome, "measured_rows": measured, "flags": flags,
            "by_month": months, "history_months": len(months), "short_history": short, "annualised": annualised,
            "trend": _deep_trend([(_deep_month_ordinal(m["month"]), m["pool"]) for m in months]),
            "seasonality": _deep_seasonality(months), "population": population, "deciles": deciles, "top10_share": top,
            "by_segment": by_segment, "outcome_rate": rate(outcome, rows),
            "outcome_rate_spread": {"segment": spread_segment, "month": (max(month_rates) - min(month_rates)) if month_rates else None},
            "benchmark": {column: _deep_benchmark(entries, item.get("direction")) for column, entries in by_segment.items()}}


def inspire_deep_scan_parse(plan: dict, rows, today) -> dict:
    """The cards of one scan from its long-format rows. Unknown is None, never 0; blocks stay per currency, never added."""
    rows = [dict(row) for row in rows or []]
    pairs = {(str(row["uc"]), str(row["other_uc"])): _deep_int(row.get("outcome_rows")) for row in rows
             if row.get("grouping_set") == "overlap" and row.get("uc") is not None and row.get("other_uc") is not None}
    cards = {}
    for item in plan["use_cases"]:
        no = str(item["No"])
        slots = {}
        for row in rows:
            kind = row.get("grouping_set")
            if str(row.get("uc")) != no or kind not in ("total", "month", "segment", "decile"):
                continue
            slot = slots.setdefault(row.get("currency"), {"total": None, "month": [], "segment": [], "decile": []})
            if kind == "total":
                slot["total"] = row
            else:
                slot[kind].append(row)
        filtered = bool(kpi_filter_sql(item["kpi"]))
        blocks = [_deep_block(plan, item, currency, slots[currency], filtered)
                  for currency in sorted(slots, key=lambda value: (value is not None, str(value)))]
        outcome = sum(block["outcome_rows"] for block in blocks)
        overlap = []
        for other in plan["use_cases"]:
            hit = pairs.get((no, str(other["No"])), pairs.get((str(other["No"]), no)))
            if other is not item and hit is not None:
                overlap.append({"No": other["No"], "rows": hit, "share": hit / outcome if outcome else None})
        totals = [slot["total"] for slot in slots.values() if slot["total"]]
        days = lambda key: [str(total[key])[:10] for total in totals if total.get(key)]
        first, last = (min(days("first_day")) if days("first_day") else None), (max(days("last_day")) if days("last_day") else None)
        nulls = {}
        share = lambda count: (count / outcome if outcome else None)
        nulls[str(item["kpi"]["column"])] = share(outcome - sum(block["measured_rows"] for block in blocks)) if outcome else None
        if plan.get("entity_column"):
            nulls[plan["entity_column"]] = share(sum(_deep_int(total.get("null_entity")) for total in totals))
        for column in plan.get("segment_columns") or []:
            nulls[column] = share(sum(_deep_int(row.get("outcome_rows")) for slot in slots.values() for row in slot["segment"]
                                      if row.get("segment_column") == column and row.get("segment_value") is None))
        cards[item["No"]] = {
            "No": item["No"], "table": plan["table"], "scan_id": plan.get("scan_id"), "status": "ok", "currencies": blocks,
            "overlap": overlap,
            "readiness": {"history_months": len({m["month"] for block in blocks for m in block["by_month"]}), "first_day": first,
                          "last_day": last,
                          "freshness_days": (today - _inspire_datetime.date.fromisoformat(last)).days if last else None,
                          "key_column_nulls": nulls},
            "sensitivity": inspire_deep_sensitivity(item.get("value_spec")), "segment_columns": list(plan.get("segment_columns") or [])}
    return cards
INSPIRE_THRESHOLD_LABELS.update({name: label for name, label in GENIE_WIDGET_LABELS.items() if name.startswith(INSPIRE_THRESHOLD_PREFIXES)})
_INSPIRE_ROW_CONCURRENCY_WARNED = set()


def _inspire_row_concurrency_warn(logger, table, message):
    if table in _INSPIRE_ROW_CONCURRENCY_WARNED:
        return
    _INSPIRE_ROW_CONCURRENCY_WARNED.add(table)
    if logger is not None:
        logger.warning(f"[ROW-CONCURRENCY] {table} keeps file-level conflict checks: {message}; runs still write it, and a conflict "
                       "with another run is retried")


def _inspire_row_concurrency_alter(spark, tracking_table, alter_sql, logger, done) -> bool:
    try:
        inspire_retry_write_conflicts(lambda: spark.sql(alter_sql), f"turning on row-level concurrency for {tracking_table}")
    except Exception as error:
        _inspire_row_concurrency_warn(logger, tracking_table,
                                      f"this identity could not change it ({inspire_redact_text(str(error), set(), '')[:200]})")
        return False
    done.append(alter_sql)
    return True


def inspire_ensure_row_concurrency(spark, tracking_table, cluster_by, logger=None) -> bool:
    try:
        rows = spark.sql(f"DESCRIBE DETAIL {tracking_table}").collect()
        detail = rows[0].asDict() if hasattr(rows[0], "asDict") else dict(rows[0])
    except Exception as error:
        _inspire_row_concurrency_warn(logger, tracking_table,
                                      f"its details could not be read ({inspire_redact_text(str(error), set(), '')[:200]})")
        return False
    properties = {str(k).lower(): str(v).lower() for k, v in (detail.get("properties") or {}).items()}
    missing = ", ".join(f"'{name}' = '{value}'" for name, value in INSPIRE_ROW_CONCURRENCY_PROPERTIES
                        if properties.get(name.lower()) != value)
    done = []
    if missing and not _inspire_row_concurrency_alter(spark, tracking_table, f"ALTER TABLE {tracking_table} SET TBLPROPERTIES ({missing})",
                                                      logger, done):
        return False
    if not (detail.get("clusteringColumns") or []) and not (detail.get("partitionColumns") or []) and \
            not _inspire_row_concurrency_alter(spark, tracking_table, f"ALTER TABLE {tracking_table} CLUSTER BY ({', '.join(cluster_by)})",
                                               logger, done):
        return False
    if done and logger is not None:
        logger.info(f"[ROW-CONCURRENCY FIRED] {tracking_table} now detects conflicts per row ({'; '.join(done)})")
    return True


INSPIRE_SETTING_GROUPS = ("impact", "flagging", "scope", "alerts")
INSPIRE_SETTING_KINDS = ("money", "number", "integer", "percent", "choice", "days")
INSPIRE_SETTING_SOURCES = ("widget", "assumption", "alert")
INSPIRE_SETTING_APPLIES = ("run", "app_and_run", "alert")
INSPIRE_ALERT_THRESHOLD_SETTING = "alert_threshold"
INSPIRE_NOT_SETTINGS = ("result_table", "model_name", "ai_endpoint", "as_of_date", "currency", "run_profile")
INSPIRE_TIER_SETTINGS = {"measured": INSPIRE_TIER_AMOUNTS, "predicted": ("act_now_share", "review_share")}
INSPIRE_FAMILY_FLAGGING = {"A": ("min_probability",), "B": ("alert_quantile", "max_alerts_per_run"), "C": ("flag_segments",),
                           "D": ("min_score", "items_per_entity"), "E": ("min_deviation",), "F": (), "G": (), "H": ()}
INSPIRE_FLAGGING_DEFAULTS = {"flag_segments": INSPIRE_SETTING_ALL, "min_probability": "0", "min_score": "0", "min_deviation": "0",
                             "items_per_entity": "10"}
INSPIRE_FLAGGING_RULES = {
    "min_probability": "a row passes the decision test only when its predicted probability is at least `min_probability`",
    "flag_segments": ("only rows whose segment_or_item is one of the segments `flag_segments` names, a comma-separated list, or "
                      f"every row when it is `{INSPIRE_SETTING_ALL}`, can be 'Act now' or 'Review', and every other row is 'Monitor'"),
    "min_score": "a row passes the decision test only when its recommendation score is at least `min_score`",
    "items_per_entity": "the run writes at most `items_per_entity` recommendations per entity, its highest-scored ones",
    "min_deviation": ("a row passes the decision test only when its forecast differs from the baseline by at least `min_deviation`, "
                      "a share of the baseline"),
}
INSPIRE_SETTING_HELP = {
    "act_now_amount": "A record whose {impact} is at least this is Act now.",
    "review_amount": "A record whose {impact} is at least this, and below the Act now cutoff, is Review.",
    "act_now_share": "The share of the records that pass the decision test, the highest ranked, that are Act now.",
    "review_share": "The share of those records, the next ones by rank, that are Review.",
    "alert_quantile": "How unusual a record must be to count as an anomaly: the anomaly score quantile of the reference window.",
    "max_alerts_per_run": "The most anomalies one run raises, the review budget of the team.",
}
INSPIRE_IMPACT_SETTING_KINDS = {"money": "money", "percent": "percent"}
INSPIRE_GROUP_HELP = ("Which records are compared with each other. A record is compared only with the records of its own group, so a "
                      "sale in a small country is never judged against the sales of a large one. Name columns coarse to fine, such "
                      f"as region, country; a group with fewer than {INSPIRE_GROUP_MIN_RECORDS} records moves up a level. "
                      f"{INSPIRE_SETTING_ALL} compares every record with every other record.")


def inspire_group_choices(spec: dict) -> list:
    columns = [str(c) for c in ((spec or {}).get("grouping") or {}).get("columns") or []]
    return columns


def inspire_setting_kind(name: str, widget: dict, rule, impact_kind: str = "money") -> str:
    if name in INSPIRE_TIER_AMOUNTS:
        return INSPIRE_IMPACT_SETTING_KINDS.get(impact_kind, "number")
    if name in ("flag_segments", INSPIRE_GROUP_BY, INSPIRE_SCOPE_SETTINGS[0]) or str(widget.get("type") or "") == "dropdown":
        return "choice"
    low, high, whole, low_open, high_open = genie_rule_parts(rule)
    if whole:
        return "days" if name.endswith("_days") else "integer"
    if low == 0 and high == 1 and not low_open and not high_open:
        return "percent"
    return "number"


def inspire_setting_reason(name: str, family: str, basis: str) -> str:
    if name in INSPIRE_TIER_AMOUNTS:
        return "Databricks AI set it from the first full test run, at the 95th and 80th percentiles of the records' impact"
    if name in INSPIRE_TIER_SETTINGS["predicted"]:
        return (f"Inspire's default: the top {INSPIRE_TIER_SHARES['act_now']:.0%} of the records that pass the decision test are Act "
                f"now and the next {INSPIRE_TIER_SHARES['review']:.0%} Review")
    if name in GENIE_READINESS_THRESHOLDS.get(family, {}):
        return f"Inspire's default for {GENIE_FAMILY_SPECS[family]['label'].lower()} use cases"
    if name in INSPIRE_FLAGGING_DEFAULTS:
        return "Inspire's default, which adds no cutoff of its own until an owner sets one" if INSPIRE_FLAGGING_DEFAULTS[name] in (
            "0", INSPIRE_SETTING_ALL) else "Inspire's default for this kind of use case"
    return "Databricks AI chose it when it built the notebook"


def inspire_settings_model(spec: dict, widgets, assumptions=(), impact=None, alert=None) -> list:
    family, basis = str(spec.get("family") or ""), str(spec.get("decision_basis") or "")
    impact = impact or {}
    impact_kind = str(impact.get("kind") or "money")
    unit = str(impact.get("unit") or impact.get("currency") or "")
    flagging = set(INSPIRE_TIER_SETTINGS.get(basis, ())) | set(INSPIRE_FAMILY_FLAGGING.get(family, ()))
    scope = inspire_scope_settings(spec.get("first_run"))
    model, seen = [], {s["name"] for s in scope} | {INSPIRE_CAPACITY_SETTING, INSPIRE_ALERT_THRESHOLD_SETTING}
    for item in assumptions or []:
        name, kind = str((item or {}).get("name") or ""), str((item or {}).get("kind") or "number")
        if not name or name in seen:
            continue
        seen.add(name)
        bounds = inspire_assumption_setting(name, kind, item.get("low"), item.get("high"))
        model.append(dict(bounds, label=name.replace("_", " ").strip().capitalize(), group="impact", unit=unit if bounds["kind"] == "money" else "%" if bounds["kind"] == "percent" else "",
                          whole=False, low_open=False, high_open=False, choices=[], many=False, default=item.get("value"),
                          reason="the value the notebook defines", help=f"An assumption of the {impact.get('label') or inspire_stake_words(impact)} formula.",
                          applies="app_and_run", source="assumption"))
    for widget in widgets or []:
        name = str((widget or {}).get("name") or "")
        if not name or name in seen or name in INSPIRE_NOT_SETTINGS or name in (INSPIRE_CHILD_MARKER, INSPIRE_REQUESTED_BY):
            continue
        seen.add(name)
        rule = genie_allowed_rule(widget.get("allowed")) or (None, None, False, False, False)
        kind = inspire_setting_kind(name, widget, rule, impact_kind)
        label = GENIE_WIDGET_LABELS.get(name) or str(widget.get("label") or name)
        help_text = INSPIRE_SETTING_HELP.get(name, label + ".").format(impact=impact.get("label") or inspire_stake_words(impact))
        rule_text = INSPIRE_FLAGGING_RULES.get(name)
        group = "flagging" if name in flagging else "scope"
        grouping = name == INSPIRE_GROUP_BY
        if grouping:
            label, help_text = INSPIRE_GROUP_LABEL, INSPIRE_GROUP_HELP
        model.append(genie_setting_bounds(
            name, rule, label=label, group=group, kind=kind,
            unit=unit if name in INSPIRE_TIER_AMOUNTS else "%" if kind == "percent" else "days" if kind == "days" else "",
            choices=(inspire_group_choices(spec) if grouping else list(INSPIRE_SCOPES) if name == INSPIRE_SCOPE_SETTINGS[0]
                     else [str(c) for c in widget.get("choices") or []]),
            many=name in ("flag_segments", INSPIRE_GROUP_BY), **({"solo": [INSPIRE_SETTING_ALL]} if grouping else {}),
            default=str(widget.get("default") if widget.get("default") is not None else ""),
            reason=inspire_setting_reason(name, family, basis), help=help_text + (f" The run reads it so that {rule_text}." if rule_text else ""),
            applies="run", source="widget"))
    if isinstance(alert, dict) and alert.get("alert"):
        model.append({"name": INSPIRE_ALERT_THRESHOLD_SETTING, "label": "Alert threshold", "group": "alerts", "kind": "number", "unit": "records",
                      "low": 0, "high": None, "whole": False, "low_open": False, "high_open": False, "allowed": "at least 0",
                      "choices": [], "many": False, "default": str(alert.get("alert_threshold") if alert.get("alert_threshold") is not None else ""),
                      "reason": "set when the use case was built", "applies": "alert", "source": "alert",
                      "reads_setting": bool(alert.get("reads_setting")),
                      "help": (f"The alert emails when the number of {str(alert.get('alert_tiers') or 'act_now').replace('_', ' ')} records "
                               f"is {alert.get('alert_operator') or '>'} this; the alert reads the saved value each time it checks.")})
    capacity = spec.get("act_now_capacity")
    model.append({"name": INSPIRE_CAPACITY_SETTING, "label": "Team capacity", "group": "flagging", "kind": "integer", "unit": "records",
                  "low": 1, "high": None, "whole": True, "low_open": False, "high_open": False,
                  "allowed": "a whole number, at least 1, or empty for no cap", "choices": [], "many": False, "optional": True,
                  "default": str(capacity) if isinstance(capacity, int) and not isinstance(capacity, bool) and capacity >= 1 else "",
                  "reason": "chosen when the use case was built" if capacity else "Inspire's default, no cap",
                  "help": ("How many records your team can act on each run. Inspire keeps the most important ones to act on now and marks "
                           "the rest to check later. Leave it empty for no cap. The next run uses it."),
                  "applies": "run", "source": "widget"})
    model += scope
    order = {group: at for at, group in enumerate(INSPIRE_SETTING_GROUPS)}
    return sorted(model, key=lambda s: order[s["group"]])


def inspire_metadata_rows(spark, table):
    if spark is None or not str(table or "").strip():
        return None
    name = inspire_table_name(table)
    try:
        for row in inspire_rows(spark.sql(f"DESCRIBE TABLE EXTENDED {name}")):
            if str(row.get("col_name") or "").strip().lower() == "statistics":
                found = re.search(r"([0-9]+) rows", str(row.get("data_type") or ""))
                if found:
                    return int(found.group(1))
        return inspire_history_rows(inspire_rows(spark.sql(f"DESCRIBE HISTORY {name} LIMIT {INSPIRE_HISTORY_ROWS_LIMIT}")))
    except Exception:
        return None


def inspire_history_rows(history):
    total = 0
    for version in history or []:
        operation = str(version.get("operation") or "").upper()
        metrics, parameters = version.get("operationMetrics") or {}, version.get("operationParameters") or {}
        written = metrics.get("numOutputRows")
        mode = str(parameters.get("mode") or "").lower()
        if operation == "CREATE TABLE":
            return total
        if operation.endswith(INSPIRE_HISTORY_REPLACES) or (operation == "WRITE" and mode == "overwrite"):
            return None if written is None else total + int(written)
        if operation in ("WRITE", "STREAMING UPDATE") and mode in ("append", "") and written is not None:
            total += int(written)
        elif operation not in INSPIRE_HISTORY_KEEPS:
            return None
    return None


INSPIRE_HISTORY_ROWS_LIMIT = 100
INSPIRE_HISTORY_REPLACES = "TABLE AS SELECT"
INSPIRE_HISTORY_KEEPS = ("OPTIMIZE", "VACUUM START", "VACUUM END", "SET TBLPROPERTIES", "UNSET TBLPROPERTIES", "ADD COLUMNS",
                         "CHANGE COLUMN", "UPGRADE PROTOCOL", "ANALYZE", "COMPUTE STATISTICS", "ADD CONSTRAINT", "DROP CONSTRAINT",
                         "SET COLUMN TAGS", "UNSET COLUMN TAGS", "SET TAGS", "UNSET TAGS")


INSPIRE_TIME_TYPES = ("date", "timestamp")
INSPIRE_TIME_NAME = re.compile(r"(date|time|day)|_at$|_ts$", re.I)


def inspire_own_column(reference, table) -> str:
    parts = [p.strip("`") for p in str(reference or "").split(".") if p.strip("`")]
    held = [p.strip().lower() for p in str(table or "").replace("`", "").split(".")]
    named = [p.lower() for p in parts[:-1]]
    return parts[-1] if 1 <= len(named) <= 3 and held[len(held) - len(named):] == named else ""


def inspire_named_time_column(roles, assessment, table) -> str:
    via = (assessment or {}).get("time_via_join")
    return (inspire_own_column((roles or {}).get("event_date"), table) or inspire_own_column(via.get("key") if isinstance(via, dict) else "", table)
            or inspire_own_column((assessment or {}).get("time_column"), table))


def inspire_time_source(named, columns, joins, ref_columns):
    columns = [c for c in columns or [] if str(c.get("column_name") or "")]
    if not columns:
        return {"column": named, "via": None} if named else None
    dated = lambda c: str(c.get("data_type") or "").lower().startswith(INSPIRE_TIME_TYPES)

    def via_of(column):
        for join in joins or []:
            if str(join.get("column") or "").lower() != column.lower() or not join.get("ref_column"):
                continue
            ref = inspire_join_ref(join)
            found = [str(c.get("column_name")) for c in (ref_columns or {}).get(ref.lower()) or [] if dated(c)] if ref else []
            date = next((n for n in found if INSPIRE_TIME_NAME.search(n)), found[0] if found else "")
            if date:
                return {"table": ref, "key": str(join["ref_column"]), "date": date}
        return None

    def source_of(column):
        if column is None:
            return None
        name = str(column["column_name"])
        via = None if dated(column) else via_of(name)
        return {"column": name, "via": via} if dated(column) or via else None
    hit = source_of(next((c for c in columns if named and str(c["column_name"]).lower() == str(named).lower()), None))
    if hit:
        return hit
    timed = [c for c in columns if dated(c)]
    direct = next((c for c in timed if INSPIRE_TIME_NAME.search(str(c["column_name"]))), timed[0] if timed else None)
    if direct is not None:
        return source_of(direct)
    return next((s for s in (source_of(c) for c in columns if INSPIRE_TIME_NAME.search(str(c["column_name"]))) if s), None)


def inspire_time_refs(named, columns, joins) -> list:
    asked = {str(c.get("column_name") or "").lower() for c in columns or []
             if INSPIRE_TIME_NAME.search(str(c.get("column_name") or "")) or str(c.get("column_name") or "").lower() == str(named or "").lower()}
    return sorted({inspire_join_ref(j) for j in joins or [] if str(j.get("column") or "").lower() in asked and inspire_join_ref(j)})


def inspire_join_ref(join) -> str:
    parts = [p.strip() for p in str((join or {}).get("ref_table") or "").replace("`", "").split(".")]
    return ".".join(parts) if len(parts) == 3 and all(parts) else ""


def inspire_scope_reason(first_run) -> str:
    records = first_run.get("records")
    held = f"the main table holds {inspire_plural(records, 'record', grouped=True)}"
    goal = inspire_plural(INSPIRE_SCOPE_DEFAULTS['scope_records'], 'record', grouped=True)
    technique, column = str(first_run.get("technique") or "this technique"), str(first_run.get("group_column") or "")
    what = (f"{goal} {INSPIRE_SPREAD_WORDS}" if inspire_standalone(technique) else
            f"about {goal} in whole groups of {column}, so no group is cut" if column else
            f"{goal} {INSPIRE_SPREAD_WORDS}; {technique} reads records together and no column groups them, so a group may be cut")
    if records is None:
        return f"Inspire could not read from its metadata how many records the main table holds, so the First run covers {what}"
    if records <= INSPIRE_FIRST_RUN_RECORDS:
        return f"Inspire's default: {held}, so a First run of about {goal} covers all of it"
    return f"Inspire's default: {held}, more than {INSPIRE_FIRST_RUN_RECORDS:,}, so the First run covers {what}"


def inspire_scope_settings(first_run) -> list:
    if not first_run:
        return []
    common = {"group": "scope", "low_open": False, "high_open": False, "source": "widget", "applies": "run", "unit": ""}
    chosen, picked = inspire_scope_chosen(first_run), "chosen in the Start MVP wizard"
    return [
        dict(common, name="run_scope", label="First run", kind="choice", low=None, high=None, whole=False, allowed=", ".join(INSPIRE_SCOPES),
             choices=list(INSPIRE_SCOPES), many=False,
             default=inspire_scope_default(first_run),
             reason=picked if chosen.get("run_scope") in INSPIRE_SCOPES else inspire_scope_reason(first_run),
             help=("What the next runs cover: all the records, chosen groups, a recent period, about a number of records in whole groups "
                   f"(records {INSPIRE_SPREAD_WORDS} when each record stands alone). "
                   "Only the first run after you choose it covers this; every later run, scheduled or not, covers all the records in "
                   "the Data groups.")),
        dict(common, name="scope_groups", label="Groups to run on", kind="choice", low=None, high=None, whole=False, allowed="any text",
             choices=[], many=True, optional=True, default=str(chosen.get("scope_groups") or ""),
             reason=picked if chosen.get("scope_groups") else "Inspire's default, the largest groups when this is empty",
             help=(f"The groups a First run on groups covers: a comma-separated list of values of the finest grouping column, or a "
                   "JSON list of groups, each a list of {column, value} parts that must all hold; when "
                   f"empty, the {INSPIRE_SUGGESTED_GROUPS} largest groups.")),
        dict(common, name="scope_days", label="Days to run on", kind="days", low=1, high=None, whole=True, allowed="at least 1",
             choices=[], many=False, default=str(chosen.get("scope_days") or INSPIRE_SCOPE_DEFAULTS["scope_days"]), unit="days",
             reason=picked if chosen.get("scope_days") else "Inspire's default for a First run on a recent period",
             help=(f"How many days back from the newest date a First run on a recent period covers; a time series keeps at least "
                   f"{INSPIRE_GROUP_MIN_PERIODS} periods however few days this names.")),
        dict(common, name="scope_records", label="Records to run on", kind="integer", low=1, high=None, whole=True, allowed="at least 1",
             choices=[], many=False, default=str(chosen.get("scope_records") or INSPIRE_SCOPE_DEFAULTS["scope_records"]),
             reason=picked if chosen.get("scope_records") else "Inspire's default for a First run on a number of records",
             help=(f"How many records a First run on records covers: records {INSPIRE_SPREAD_WORDS} when each record stands alone, otherwise "
                   "whole groups of the finest grouping column that add up to about this many, so no group is cut.")),
    ]


def inspire_run_settings_model(model) -> list:
    keys = ("name", "kind", "low", "high", "whole", "low_open", "high_open", "allowed", "choices", "many")
    return [dict({key: s.get(key) for key in keys}, **({"solo": list(s["solo"])} if s.get("solo") else {}),
                 **({"optional": True} if s.get("optional") else {}))
            for s in model or [] if s.get("source") == "widget"]

