def inspire_plain_text(value, joiner: str = ", ") -> str:
    if value is None:
        return ""
    if isinstance(value, dict):
        parts = [(key, inspire_plain_text(item)) for key, item in value.items()]
        return "; ".join(f"{key}: {text}" for key, text in parts if text)
    if isinstance(value, (list, tuple, set)):
        return joiner.join(text for text in (inspire_plain_text(item) for item in value) if text)
    return str(value).strip()


INSPIRE_KIND_LINES = (("doc_what_we_serve", "serving_summary"), ("doc_how_it_works", "method_summary"), ("doc_value_source", "value_source"))
INSPIRE_KIND_LINE_FIELDS = tuple(field for _key, field in INSPIRE_KIND_LINES)
INSPIRE_KIND_DEFAULT_WORDS = {"owner": "the decision owner", "objects": "records", "object": "record", "kpi": "the KPI", "signal_columns": "the source columns",
                              "cadence": "cycle", "threshold": "the agreed threshold", "result_table": "the result table"}
INSPIRE_KIND_CADENCE_NOUNS = {"value_cadence_hourly": "hour", "value_cadence_daily": "day", "value_cadence_weekly": "week",
                              "value_cadence_biweekly": "fortnight", "value_cadence_monthly": "month", "value_cadence_quarterly": "quarter",
                              "value_cadence_yearly": "year", "value_cadence_real_time": "event", "value_cadence_per_event": "event"}
_INSPIRE_KIND_PLACEHOLDER = re.compile(r"\{([a-z_]+)\}")
_INSPIRE_KIND_KEY_SUFFIX = re.compile(r"_(id|sk|key|code|no|number|num)$")
_INSPIRE_IDENT = re.compile(r"[A-Za-z][A-Za-z0-9]*(?:_[A-Za-z0-9]+)+")


def _inspire_kind_key(value) -> str:
    return re.sub(r"[\s_-]+", " ", str(value if value is not None else "")).strip().casefold()


def inspire_use_case_kind(uc: dict):
    named = (_inspire_resolve_kind(value) for value in (uc.get("use_case_kind"), uc.get("Use Case Kind")))
    kind_id = next((kind_id for kind_id in named if kind_id), None)
    return _inspire_kind(kind_id or _inspire_resolve_kind(None, inspire_plain_text(uc.get("Analytics Technique"))))


def _inspire_kind_object(column) -> str:
    name = str(column or "").split(".")[-1].strip("` ").lower()
    parts = [part for part in _INSPIRE_KIND_KEY_SUFFIX.sub("", name).split("_") if part]
    if len(parts) > 1 and len(parts[0]) <= 3:
        parts = parts[1:]
    return " ".join(parts)


def _inspire_kind_plural(noun: str) -> str:
    if not noun or noun.endswith("s"):
        return noun
    if re.search(r"[^aeiou]y$", noun):
        return noun[:-1] + "ies"
    return noun + ("es" if re.search(r"(x|ch|sh)$", noun) else "s")


def inspire_kind_words(uc: dict) -> dict:
    assessment = uc.get("elite_assessment") if isinstance(uc.get("elite_assessment"), dict) else {}
    kpis = [spec for spec in uc.get("KPIs") or [] if isinstance(spec, dict)]
    signals = assessment.get("signal_columns")
    signals = signals if isinstance(signals, (list, tuple)) else [part for part in str(signals or "").split(",")]
    columns = [str(column).split(".")[-1].strip("` ") for column in signals if str(column or "").strip("` ")]
    cadence = inspire_plain_text(assessment.get("cadence")).lower()
    return {
        "owner": inspire_plain_text(assessment.get("decision_owner")) or inspire_plain_text(uc.get("Beneficiary"))
                 or inspire_plain_text(uc.get("Sponsor")),
        "objects": _inspire_kind_plural(_inspire_kind_object(assessment.get("entity_key_column"))),
        "object": _inspire_kind_object(assessment.get("entity_key_column")),
        "kpi": inspire_plain_text(assessment.get("kpi")) or (inspire_plain_text(kpis[0].get("name")) if kpis else ""),
        "signal_columns": ", ".join(f"`{column}`" for column in columns[:4]),
        "value_at_stake": inspire_plain_text(uc.get("value_at_stake")),
        "cadence": INSPIRE_KIND_CADENCE_NOUNS.get(TranslationService.cadence_label_key(cadence), cadence),
        "threshold": inspire_plain_text(uc.get("threshold")),
        "result_table": inspire_plain_text(uc.get("result_table")),
    }


def inspire_kind_fill(template, words: dict) -> str:
    parts = re.sub(r"\bper \{objects\}", "per {object}", str(template or "").strip()).split("; ")
    if not parts[0]:
        return ""
    known = lambda name: words.get(name) or name in INSPIRE_KIND_DEFAULT_WORDS
    kept = [parts[0]] + [part for part in parts[1:] if all(known(name) for name in _INSPIRE_KIND_PLACEHOLDER.findall(part))]
    text = _INSPIRE_KIND_PLACEHOLDER.sub(lambda match: str(words.get(match.group(1)) or INSPIRE_KIND_DEFAULT_WORDS.get(match.group(1), "")),
                                         "; ".join(kept))
    text = re.sub(r"\s+([,.;:])", r"\1", re.sub(r"\s{2,}", " ", text))
    text = re.sub(r"\bthe the\b", "the", re.sub(r"\b(?:each|per) (?=(?:each|per|every)\b)", "", text, flags=re.I), flags=re.I).strip()
    return text[:1].upper() + text[1:] + ("" if text[-1:] in ".!?" else ".")


def inspire_kind_lines(uc: dict, kind: dict = None) -> dict:
    kind = kind or inspire_use_case_kind(uc)
    if not kind:
        return {field: "" for field in INSPIRE_KIND_LINE_FIELDS}
    words = inspire_kind_words(uc)
    layout = _inspire_layout(kind.get("layout")) or {}
    technique = inspire_plain_text(uc.get("Analytics Technique"))
    methods = kind.get("method_plain") or {}
    method_key = _technique_registry_key(technique, methods)
    method = methods[method_key] if method_key is not None else next(iter(methods.values()), "")
    serving = (inspire_kind_fill(kind.get("serving_template"), words)
               or inspire_kind_fill(f"{layout.get('label') or kind.get('label')} for {{owner}}: app, dashboard, Genie room, alert.", words))
    how = inspire_kind_fill(method, words) or inspire_kind_fill(f"{technique}: {kind.get('question') or ''}" if technique else kind.get("question"), words)
    value = (inspire_kind_fill(kind.get("value_formula"), words)
             or inspire_kind_fill((uc.get("elite_assessment") or {}).get("value_driver") if isinstance(uc.get("elite_assessment"), dict) else "", words))
    return {"serving_summary": serving, "method_summary": how, "value_source": value}


def inspire_kind_about(uc: dict) -> list:
    lines = {field: inspire_plain_text(uc.get(field)) for field in INSPIRE_KIND_LINE_FIELDS}
    if not all(lines.values()):
        built = inspire_kind_lines(uc)
        lines = {field: lines[field] or built[field] for field in lines}
    labels = TranslationService.ENGLISH_TRANSLATIONS
    return [f"{labels[key]}: {lines[field]}" for key, field in INSPIRE_KIND_LINES if lines[field]]


def inspire_kind_about_text(text, uc: dict) -> str:
    text = str(text or "").rstrip()
    about = [line for line in inspire_kind_about(uc) if line not in text]
    return "\n".join(([text] if text else []) + about)


def inspire_apply_use_case_kind(uc: dict) -> bool:
    kind = inspire_use_case_kind(uc)
    if not kind:
        return False
    family = next((item for item in _inspire_kinds()["families"] if item.get("id") == kind.get("family")), {})
    keep = uc.get("use_case_kind") in (None, "", kind["id"])
    uc["use_case_kind"], uc["kind_family"] = kind["id"], kind.get("family") or ""
    uc["app_layout"] = (uc.get("app_layout") if keep else "") or kind.get("layout") or ""
    uc["kind_label"] = (uc.get("kind_label") if keep else "") or kind.get("label") or ""
    uc["kind_family_label"] = (uc.get("kind_family_label") if keep else "") or family.get("label") or ""
    lines = inspire_kind_lines(uc, kind)
    for field in INSPIRE_KIND_LINE_FIELDS:
        if not (keep and inspire_plain_text(uc.get(field))):
            uc[field] = lines[field]
    return True


INSPIRE_VALUE_UPLIFT = {"measure_explain": (0.01, 0.03), "predict": (0.02, 0.05), "decide_optimize": (0.03, 0.08),
                        "simulate_plan": (0.02, 0.05), "measure_impact": (0.01, 0.04), "detect_protect": (0.05, 0.15),
                        "know_entities": (0.01, 0.03), "run_processes": (0.03, 0.08), "place_relationships": (0.01, 0.03),
                        "text_agents": (0.01, 0.03)}
INSPIRE_VALUE_UPLIFT_DEFAULT = (0.01, 0.03)
INSPIRE_VALUE_NOT_MEASURED = "not measured yet"
INSPIRE_VALUE_COUNT_AGGREGATIONS = ("COUNT",)


def inspire_kind_values_from_kpi(kind) -> bool:
    return bool(kind) and kind.get("value_from_kpi") is True


_INSPIRE_KPI_HELD_RE = re.compile(r"^\s*(?:maintain|keep|hold|stable|steady)\b", re.I)
_INSPIRE_RANGE_COVERS = {
    (">", ">"): lambda unit, count: count >= unit, (">", ">="): lambda unit, count: count > unit,
    (">=", ">"): lambda unit, count: count >= unit, (">=", ">="): lambda unit, count: count >= unit,
    ("<", "<"): lambda unit, count: count <= unit, ("<", "<="): lambda unit, count: count < unit,
    ("<=", "<"): lambda unit, count: count <= unit, ("<=", "<="): lambda unit, count: count <= unit,
}
INSPIRE_CURRENCY_UNKNOWN = "currency not known"
INSPIRE_VALUE_WINDOW = "12 months, assumed"
INSPIRE_VALUE_TARGET_UNMEASURED = "a target set once the current value is measured (not measured yet)"
INSPIRE_VALUE_WINDOW_UNMEASURED = "a time frame set with that target"
_INSPIRE_USER_UPLIFT_RE = re.compile(r"\b(?:uplift|improv\w*|lift|gain|saving\w*|reduc\w*|increas\w*|cut)\b\D{0,30}?"
                                     r"(\d+(?:\.\d+)?)\s*%?\s*(?:-|\u2013|to)\s*(\d+(?:\.\d+)?)\s*%", re.I)
_INSPIRE_WORD_RE = re.compile(r"[A-Za-z]+")
_INSPIRE_CODE_WORDS = frozenset(("ALL", "TOP", "CUP", "SOS", "MOP", "PEN", "BOB", "TRY", "MAD", "GEL", "LAK"))
_INSPIRE_KPI_DOWN_RE = re.compile(r"\b(decrease|decreasing|down|lower|minimi[sz]e|reduce|reduction|cut|decline)\b", re.I)


def inspire_money_range(low, high) -> str:
    """`low-high` with one precision for both ends: when an end has three digits (103K), neither end shows a decimal."""
    ends = [inspire_money_short(low), inspire_money_short(high)]
    if any(re.match(r"-?\d{3}", end) and end[-1] in "KMB" for end in ends):
        ends = []
        for amount in (float(low), float(high)):
            size, suffix = next(((size, suffix) for size, suffix in ((1e9, "B"), (1e6, "M"), (1e3, "K")) if abs(amount) >= size), (1, ""))
            ends.append(f"{amount / size:,.0f}{suffix}")
    return "-".join(ends)


def _inspire_percent(share) -> str:
    return inspire_number_text(share * 100)


def inspire_text_currency(text) -> str:
    text = str(text or "")
    found = {match.group(0) for match in _INSPIRE_WORD_RE.finditer(text) if match.group(0).isupper() and match.group(0) in INSPIRE_CURRENCY_CODES
             and match.group(0) not in _INSPIRE_CODE_WORDS
             and re.search(r"\d|currenc|money|value|amount|report", text[max(0, match.start() - 16):match.end() + 16], re.I)}
    found |= {code for sign, code in IMPLEMENT_IMPACT_CURRENCY_SIGNS.items() if re.search(re.escape(sign) + r"\s?\d", text)}
    return next(iter(found)) if len(found) == 1 else ""


def _inspire_column_currency(column) -> str:
    codes = {part.upper() for part in re.split(r"[^A-Za-z]+", str(column or "")) if part.upper() in INSPIRE_CURRENCY_CODES}
    return next(iter(codes)) if len(codes) == 1 else ""


def _inspire_reporting_currency() -> str:
    """The `currency` widget is the run's reporting currency; it counts only when it is a real ISO 4217 code."""
    code = str(inspire_widget("currency", "") or "").strip().upper()
    return code if code in INSPIRE_CURRENCY_CODES else ""


def _inspire_kpi_is_money(spec: dict) -> bool:
    return spec.get("impact_kind") == "money" or _kpi_impact_guess(inspire_plain_text(spec.get("name")),
                                                                    inspire_plain_text(spec.get("unit"))) == "money"


def _inspire_kpi_down(spec: dict) -> bool:
    return bool(_INSPIRE_KPI_DOWN_RE.search(str((spec or {}).get("direction") or "")))


def _inspire_kpi_measured_value(spec: dict):
    baseline = kpi_baseline_shown((spec or {}).get("baseline"), spec) if spec else None
    try:
        value = float((baseline or {}).get("value"))
    except (TypeError, ValueError):
        return None, None
    return (value, baseline) if value == value and abs(value) != float("inf") else (None, None)


def _inspire_uplift(user_text: str, family: str) -> tuple:
    match = _INSPIRE_USER_UPLIFT_RE.search(str(user_text or ""))
    if match:
        low, high = sorted(float(part) / 100 for part in match.groups())
        if 0 < high <= 1:
            return low, high, "instructions"
    low, high = INSPIRE_VALUE_UPLIFT.get(family or "", INSPIRE_VALUE_UPLIFT_DEFAULT)
    return low, high, "kind default"


def _inspire_kpi_window(baseline: dict) -> int:
    try:
        return max(int((baseline or {}).get("window_days") or 0), 0)
    except (TypeError, ValueError):
        return 0


def _inspire_kpi_plain(spec: dict, aggregations: tuple):
    value, baseline = _inspire_kpi_measured_value(spec)
    if value is None or value == 0 or spec.get("denominator") or spec.get("metric_view") \
            or str(spec.get("aggregation") or "").strip().upper() not in aggregations:
        return None, None
    return value, baseline


def _inspire_filter_parts(spec: dict):
    try:
        clause = kpi_filter_clause(spec)
    except ValueError:
        return False
    if clause is None:
        return None
    kind = spec.get("filter_type")
    typed, problem = kpi_filter_typed(kind, spec.get("filter_value")) if kind else (None, "has no type")
    return clause[0].lower(), clause[1], clause[2], kind, None if problem else typed


def _inspire_population_covers(unit_spec: dict, unit_baseline: dict, count_spec: dict, count_baseline: dict) -> bool:
    unit, count = _inspire_filter_parts(unit_spec), _inspire_filter_parts(count_spec)
    if unit is False or count is False:
        return False
    if unit is not None:
        if count is None or unit[0] != count[0]:
            return False
        if unit[1:3] != count[1:3]:
            if unit[3] != count[3] or unit[4] is None or count[4] is None:
                return False
            if unit[1:2] + count[1:2] == ("!=", "="):
                same = (unit[4].casefold() == count[4].casefold()) if unit[3] == "text" else unit[4] == count[4]
                if same:
                    return False
            else:
                rule = _INSPIRE_RANGE_COVERS.get((unit[1], count[1]))
                if unit[3] not in KPI_FILTER_ORDERED_KINDS or rule is None or not rule(unit[4], count[4]):
                    return False
    unit_window, count_window = _inspire_kpi_window(unit_baseline), _inspire_kpi_window(count_baseline)
    if unit_window:
        same_clock = (inspire_plain_text(unit_spec.get("time_column")).lower() == inspire_plain_text(count_spec.get("time_column")).lower()
                      and unit_baseline.get("window_anchor") == count_baseline.get("window_anchor"))
        if not count_window or unit_window < count_window or not same_clock:
            return False
    return True


def _inspire_per_unit_money(spec: dict, baseline: dict, money: list):
    table = inspire_plain_text(spec.get("table")).lower()
    for unit_spec in money:
        if table and inspire_plain_text(unit_spec.get("table")).lower() == table:
            unit_value, unit_baseline = _inspire_kpi_plain(unit_spec, ("AVG",))
            if unit_value is not None and _inspire_population_covers(unit_spec, unit_baseline, spec, baseline):
                return unit_spec, unit_value, unit_baseline
    return None


def _inspire_measured_text(spec: dict, value: float, baseline: dict, currency) -> str:
    name, column, table = (inspire_plain_text(spec.get(key)) for key in ("name", "column", "table"))
    window = f" in the {DatabricksInspire._kpi_baseline_window(baseline)}" if _inspire_kpi_window(baseline) else " across all data"
    return (f"{DatabricksInspire._format_baseline(value)}{' ' + currency if currency else ''} {name}{window}, "
            f"from {column or 'rows'} in {table}")


_INSPIRE_RATE_PHRASES = {"live": "converted at today's rate", "saved": "converted at saved average rate",
                         "typed": "converted at the rate you set", "table": "converted at the rate in your rate table"}


def _inspire_saved_rates_to(reporting: str) -> dict:
    """The saved ECB averages and pegs (bundled with this notebook as fx_averages), turned into units of the reporting
    currency per 1 unit of each currency. Empty when the bundled table cannot be read: nothing is guessed."""
    try:
        table = _inspire_json.loads(inspire_notebook_asset("fx_averages"))
        per_usd = {**(table.get("per_usd") or {}), **((table.get("pegged") or {}).get("per_usd") or {})}
    except Exception:
        return {}
    base = per_usd.get(reporting)
    if not base or base <= 0:
        return {}
    return {code: base / float(rate) for code, rate in per_usd.items() if code != reporting and float(rate) > 0}


def _inspire_reporting_is_default() -> bool:
    """True when the App's Discover run took the reporting currency as the default (nothing was chosen)."""
    return str(inspire_widget("currency_default", "") or "").strip().lower() == "true"


def _inspire_rate_phrase(source: str, column: str = "") -> str:
    """How a conversion was made. A column rate names the column the rate was read from, on each row."""
    if source == "column":
        return f"converted with the rate in {column}"
    return _INSPIRE_RATE_PHRASES[source]


def _inspire_reporting_rate_feed() -> tuple:
    """(rates, source, column) for the reporting currency. The `currency_rates` widget is {"source": live|saved|typed|table|column,
    "rates": {...}, "column": ...} as the App sends it. source column means each row was converted with the rate in `column`,
    so there are no per-currency rates. An empty widget falls back to the saved averages bundled with the notebook; an
    unreadable widget gives no rates. A rate that is not a positive number for an ISO code is dropped, never guessed."""
    raw = str(inspire_widget("currency_rates", "") or "").strip()
    reporting = _inspire_reporting_currency()
    if not raw:
        return (_inspire_saved_rates_to(reporting), "saved", "") if reporting else ({}, "", "")
    try:
        parsed = _inspire_json.loads(raw)
    except ValueError:
        return {}, "", ""
    if not isinstance(parsed, dict) or not isinstance(parsed.get("rates"), dict):
        return {}, "", ""
    source = str(parsed.get("source") or "typed")
    source = source if source in _INSPIRE_RATE_PHRASES or source == "column" else "typed"
    if source == "column":
        column = str(parsed.get("column") or "").strip()
        return {}, ("column" if column else "typed"), column
    rates = {}
    for code, rate in parsed["rates"].items():
        code = str(code).strip().upper()
        try:
            rate = float(rate)
        except (TypeError, ValueError):
            continue
        if code in INSPIRE_CURRENCY_CODES and _inspire_math.isfinite(rate) and rate > 0:
            rates[code] = rate
    return rates, source, ""


INSPIRE_VALUE_DEV_MIN_ROWS = 100
INSPIRE_VALUE_STALE_DAYS = 180
INSPIRE_VALUE_SHORT_HISTORY = 0.8
INSPIRE_VALUE_RATE_TABLE_KEYS = ("table", "currency_column", "base_column", "date_column", "rate_column")


def inspire_value_rate_table():
    """The money rule's rate table (the `currency_rates` widget, source table) with `base` = the reporting currency, or None.
    A KPI that holds it is priced in SQL, each row at the rate valid on its own date."""
    try:
        parsed = _inspire_json.loads(str(inspire_widget("currency_rates", "") or "").strip())
    except ValueError:
        return None
    table = parsed.get("rate_table") if isinstance(parsed, dict) and parsed.get("source") == "table" else None
    base = _inspire_reporting_currency()
    if not base or not isinstance(table, dict) or not all(isinstance(table.get(key), str) and table[key].strip()
                                                         for key in INSPIRE_VALUE_RATE_TABLE_KEYS):
        return None
    return {**{key: table[key].strip() for key in INSPIRE_VALUE_RATE_TABLE_KEYS}, "base": base}


def _inspire_value_rate_wanted(spec: dict) -> bool:
    """A plain SUM over a money column with a currency and a date column can be priced per row through a rate table."""
    return (isinstance(spec, dict) and bool(spec.get("column") and spec.get("currency_column") and spec.get("time_column"))
            and not spec.get("denominator") and not spec.get("metric_view")
            and str(spec.get("aggregation") or "").strip().upper() == "SUM")


def _inspire_value_guard_day(text):
    try:
        return datetime.date.fromisoformat(str(text)[:10])
    except ValueError:
        return None


def _inspire_value_guard_count(item):
    return int(item) if _inspire_value_num(item) else None


def _inspire_value_guard_drops_refunds(spec: dict) -> bool:
    """A filter on the measure's own column that keeps only values at or above zero removes the refunds from the sum."""
    column = str(spec.get("filter_column") or "").strip().lower()
    if spec.get("denominator") or not column or column != str(spec.get("column") or "").strip().lower():
        return False
    if str(spec.get("filter_op") or "=").strip() not in (">", ">="):
        return False
    number, problem = kpi_filter_typed("decimal", spec.get("filter_value"))
    return not problem and number >= 0


def inspire_value_guards(facts: dict, spec: dict, today) -> dict:
    """The value guards, pure. facts come from DeepEvidence.measure_kpi_guards. A problem leaves the value not measured; a flag keeps
    the number and shows on the card. A read that timed out or failed is missing evidence, never a guess."""
    facts, spec = facts if isinstance(facts, dict) else {}, spec if isinstance(spec, dict) else {}
    out = {"ok": True, "problems": [], "flags": [], "period_days": None, "refunds": None, "missing_months": 0, "dev_data": []}
    rows = _inspire_value_guard_count(facts.get("rows"))
    if facts.get("status") != "ok" or rows is None:
        out["problems"] = ["evidence_timeout" if facts.get("status") == "timeout" else "evidence_missing"]
        return {**out, "ok": False}
    problems, flags, dev = set(), set(), set()
    keys, joined, unpriced = (_inspire_value_guard_count(facts.get(key)) for key in ("grain_keys", "joined_rows", "unpriced_rows"))
    if spec.get("grain_key") and keys is not None:
        if keys < rows:
            problems.add("grain_duplicate")
    else:
        flags.add("grain_unchecked")
    if joined is not None and joined > rows - (unpriced or 0):
        problems.add("join_fanout")
    if unpriced:
        problems.add("rate_missing")
    negative = _inspire_value_guard_count(facts.get("negative_rows"))
    if negative:
        flags.add("refunds_netted")
        out["refunds"] = {"rows": negative, "amount": facts.get("negative_total"), "gross": facts.get("positive_total")}
    if _inspire_value_guard_drops_refunds(spec):
        problems.add("refunds_excluded")
    first, last = _inspire_value_guard_day(facts.get("first_day")), _inspire_value_guard_day(facts.get("last_day"))
    window = _inspire_kpi_window(spec.get("baseline")) or _inspire_kpi_window({"window_days": spec.get("window_days")})
    out["period_days"] = window or None
    if first and last:
        expected, months = (last.year - first.year) * 12 + last.month - first.month + 1, _inspire_value_guard_count(facts.get("months"))
        if months is not None and months < expected:
            flags.add("periods_missing")
            out["missing_months"] = expected - months
        span = (last - first).days + 1
        if window and span < INSPIRE_VALUE_SHORT_HISTORY * window:
            out["period_days"] = span
            flags.add("history_shorter_than_window")
        if window > 1 and first == last:
            dev.add("synthetic")
        reference = _inspire_value_guard_day(today)
        if reference and (reference - last).days > INSPIRE_VALUE_STALE_DAYS:
            dev.add("stale")
    if rows < INSPIRE_VALUE_DEV_MIN_ROWS:
        dev.add("tiny")
    if rows >= 2 and _inspire_value_guard_count(facts.get("distinct_values")) == 1:
        dev.add("synthetic")
    if dev:
        flags.add("dev_data")
    return {**out, "ok": not problems, "problems": sorted(problems), "flags": sorted(flags), "dev_data": sorted(dev)}


_INSPIRE_VALUE_GUARD_PROBLEMS = {
    "grain_duplicate": "its rows hold duplicates of the grain key, which would inflate the total",
    "join_fanout": "the rate join repeats rows (two rates on one date), which would inflate the total",
    "rate_missing": "some rows have no rate on or before their date",
    "refunds_excluded": "its filter drops the negative rows (refunds) of its own measure",
    "evidence_timeout": "the guard query timed out, so the evidence is missing",
    "evidence_missing": "the guard query could not be read, so the evidence is missing"}
_INSPIRE_VALUE_GUARD_FLAGS = {
    "grain_unchecked": "row uniqueness was not checked (no grain key)",
    "history_shorter_than_window": "the data covers fewer days than the window, so the value is annualised over the days it covers",
    "periods_missing": "some months in the window have no rows"}


def _inspire_value_guard_card(base: dict, spec: dict, baseline: dict, window: int) -> dict:
    """What the card takes from the guards in its baseline: the period to annualise over, the reason it is not measured, or the flags."""
    held = baseline.get("guards") if isinstance(baseline, dict) else None
    card = {"period": window, "blocked": None, "fields": {}, "note": ""}
    if not isinstance(held, dict):
        return card
    problems = [_INSPIRE_VALUE_GUARD_PROBLEMS.get(item, item.replace("_", " ")) for item in held.get("problems") or []]
    if problems:
        name, reason = inspire_plain_text(spec.get("name")), "; ".join(problems)
        card["blocked"] = {**base, "status": INSPIRE_VALUE_NOT_MEASURED, "measure": f"{name} ({reason})",
                           "text": f"Value not measured yet: {name} cannot be priced because {reason}."}
        return card
    if _inspire_value_num(held.get("period_days")) and held["period_days"] > 0:
        card["period"] = held["period_days"]
    flags, notes = sorted(held.get("flags") or []), []
    for flag in flags:
        if flag == "dev_data":
            notes.append(f"this looks like development data ({', '.join(held.get('dev_data') or []) or 'unverified'})")
        elif flag == "refunds_netted" and isinstance(held.get("refunds"), dict):
            refunds = held["refunds"]
            notes.append(f"{refunds.get('rows')} refund rows are netted ({DatabricksInspire._format_baseline(refunds.get('amount') or 0)} "
                         f"against {DatabricksInspire._format_baseline(refunds.get('gross') or 0)} gross)")
        elif flag == "periods_missing":
            notes.append(f"{inspire_plural(held.get('missing_months') or 0, 'month')} in the window have no rows")
        else:
            notes.append(_INSPIRE_VALUE_GUARD_FLAGS.get(flag, flag.replace("_", " ")))
    if flags:
        card["fields"], card["note"] = {"guard_flags": flags}, f" Data checks: {'; '.join(notes)}."
    return card


def _inspire_value_missing_reason(spec: dict) -> str:
    return "this run ran it and the query timed out, so its evidence is missing" if spec.get("baseline_missing") == "timeout" else ""


_INSPIRE_VALUE_RANGE = {"type": "object", "required": ["low", "base", "high", "source"],
                        "properties": {"low": {"type": "number", "minimum": 0, "maximum": 1},
                                       "base": {"type": "number", "minimum": 0, "maximum": 1},
                                       "high": {"type": "number", "minimum": 0, "maximum": 1},
                                       "source": {"enum": list(INSPIRE_VALUE_SOURCES)}}}
INSPIRE_VALUE_SPEC_SCHEMA = {
    "type": "object",
    "required": ["mechanism", "currency", "flow_or_stock", "horizon_years", "measured", "sourced"],
    "properties": {
        "mechanism": {"enum": list(INSPIRE_VALUE_MECHANISM_BUCKET)},
        "currency": {"type": ["string", "null"]},
        "flow_or_stock": {"enum": ["flow", "stock"]},
        "horizon_years": {"type": "integer", "minimum": 1, "maximum": 10},
        "measured": {"type": "object", "required": ["exposure"],
                     "properties": {"exposure": {"type": "number", "minimum": 0}, "period_days": {"type": "number"},
                                    "population": {}, "baseline": {}, "unit": {"type": "string"}}},
        "sourced": {"type": "object", "required": ["effect"],
                    "properties": {name: _INSPIRE_VALUE_RANGE
                                   for name in ("effect", "adoption", "realization", "margin", "carrying_cost_rate")}},
        "cost": {"type": "object", "required": ["source", "tiers"],
                 "properties": {"source": {"enum": list(INSPIRE_VALUE_SOURCES)},
                                "tiers": {"type": "object", "required": list(INSPIRE_VALUE_TIERS),
                                          "properties": {tier: {"type": "object", "required": ["implementation", "recurring_per_year"]}
                                                         for tier in INSPIRE_VALUE_TIERS}}}},
    },
}


def inspire_value_library() -> dict:
    return json.loads(inspire_notebook_asset("value_library"))


def _inspire_value_lib_trio(item):
    trio = tuple(item.get(key) for key in INSPIRE_VALUE_SCENARIOS) if isinstance(item, dict) else ()
    return trio if trio and all(_inspire_value_num(part) for part in trio) else None


def inspire_value_assumptions(picks: dict, mechanism: str, pattern: str, library: dict) -> dict:
    """Resolve each parameter from the first usable source: measured, then owner, then library (by id, never by number), then
    exploratory. A rejected value is flagged and the next source is tried; the inputs are never changed."""
    entries = {entry.get("id"): entry for entry in (library or {}).get("entries") or [] if isinstance(entry, dict)}
    sourced, flags = {}, set()
    for name in INSPIRE_VALUE_LIB_PARAMETERS:
        pick = (picks or {}).get(name)
        if not isinstance(pick, dict):
            continue
        entry = entries.get(pick.get("library_id")) if pick.get("library_id") is not None else None
        matches = [item for item in entries.values() if (item.get("lever"), item.get("pattern"), item.get("parameter")) == (mechanism, pattern, name)]
        picked_ok = entry is not None and entry in matches
        measured = _inspire_value_lib_trio(pick.get("measured"))
        if measured:
            sourced[name] = {**dict(zip(INSPIRE_VALUE_SCENARIOS, measured)), "source": "measured", "assumption": False}
            continue
        owner = pick.get("owner")
        if _inspire_value_lib_trio(owner):
            bounds = [item["bounds"] for item in ([entry] if picked_ok else matches)] or [{"min": 0, "max": 1}]
            low_bound, high_bound = min(item["min"] for item in bounds), max(item["max"] for item in bounds)
            trio = _inspire_value_lib_trio(owner)
            if owner.get("unit") != "share":
                flags.add(f"{name}_owner_unit_mismatch")
            elif trio[0] < low_bound or trio[2] > high_bound:
                flags.add(f"{name}_owner_out_of_bounds")
            else:
                sourced[name] = {**dict(zip(INSPIRE_VALUE_SCENARIOS, trio)), "source": "owner", "assumption": True, "unit": "share"}
                continue
        if pick.get("library_id") is not None:
            if entry is None or not _inspire_value_lib_trio(entry):
                flags.add(f"{name}_library_unknown")
            elif not picked_ok:
                flags.add(f"{name}_library_mismatch")
            else:
                sourced[name] = {**dict(zip(INSPIRE_VALUE_SCENARIOS, _inspire_value_lib_trio(entry))), "source": "library",
                                 "assumption": True, "unit": entry.get("unit"), "library_id": entry["id"],
                                 "library_version": entry.get("version"), "citation": dict(entry.get("citation") or {})}
                continue
        exploratory = _inspire_value_lib_trio(pick.get("exploratory"))
        if exploratory:
            sourced[name] = {**dict(zip(INSPIRE_VALUE_SCENARIOS, exploratory)), "source": "exploratory", "assumption": True}
    return {"sourced": sourced, "flags": sorted(flags)}


def inspire_value_default_cost(library: dict, currency, per_usd=None):
    """The library's default S/M/L tiers (USD, exploratory, editable) in `currency`; none without a rate, never a USD number in another currency."""
    held = (library or {}).get("cost_tiers")
    if not isinstance(held, dict) or not isinstance(currency, str) or not currency in INSPIRE_CURRENCY_CODES:
        return None
    tiers = held.get("tiers") or {}
    if currency == held.get("currency"):
        factor = None
    elif held.get("currency") == "USD" and _inspire_value_num(per_usd) and per_usd > 0:
        factor = float(per_usd)
    else:
        return None
    return {"source": "exploratory", "editable": True, "currency": currency,
            "tiers": {tier: {part: (amount if factor is None else amount * factor) for part, amount in values.items()}
                      for tier, values in tiers.items()}}


INSPIRE_VALUE_PROPOSAL_SCHEMA = {
    "type": "object",
    "required": ["mechanism", "flow_or_stock", "baseline_sql", "assumptions"],
    "properties": {
        "mechanism": {"type": "string", "enum": list(INSPIRE_VALUE_MECHANISM_BUCKET)},
        "flow_or_stock": {"type": "string", "enum": ["flow", "stock"]},
        "baseline_sql": {"type": "string"},
        "columns": {"type": "object",
                    "properties": {name: {"type": ["string", "null"]} for name in ("exposure", "period", "population")}},
        "unit": {"type": ["string", "null"]},
        "assumptions": {"type": "array", "items": {"type": "object", "required": ["slot", "entry"],
                                                   "properties": {"slot": {"type": "string"}, "entry": {"type": "string"}}}},
        "rationale": {"type": "string"},
    },
}
INSPIRE_VALUE_MODEL_METRIC_TOKENS = frozenset({"auc", "precision", "recall", "f1", "accuracy", "lift", "mase", "mape", "rmse", "cindex"})


def inspire_value_propose(uc: dict, call, columns: list, entries: dict) -> tuple:
    """One model call: the LLM proposes the value spec as text. Never raises; any problem gives (None, problems)."""
    held = uc if isinstance(uc, dict) else {}
    prompt = (
        "Propose how to value the use case below as a plain-text value spec. You choose names only. You never write a number: "
        "no amount, share, percentage, count or date arithmetic, because code measures every number from the data and takes the "
        "assumption ranges from the entries by id. If the user gave an explicit input (a mechanism, a unit, a range), the user's input wins.\n\n"
        f"Use case: {inspire_plain_text(held.get('Name'))}\n"
        f"Primary table: {inspire_plain_text(held.get('Primary Table'))}\n"
        f"Mechanism, one of: {', '.join(INSPIRE_VALUE_MECHANISM_BUCKET)}. Name the unit (for example hours or cases) for capacity and non_financial.\n"
        "flow_or_stock: flow for an amount per period, stock for a balance held at a point in time.\n"
        "baseline_sql: one read-only SELECT over the columns below that returns the total exposed to the value. No semicolon.\n"
        "columns: the qualified columns that hold the exposure, the date period and the population (or null).\n"
        f"Columns you may use:\n{chr(10).join('- ' + str(column) for column in columns or [])}\n"
        f"assumptions: pick entries by id for the slots {', '.join(INSPIRE_VALUE_LIB_PARAMETERS)}; the entries are:\n"
        + "\n".join(f"- {key}: {(entry or {}).get('label') or key}" for key, entry in (entries or {}).items()))
    try:
        answer = call(prompt=prompt, prompt_name="value_proposal", response_schema=INSPIRE_VALUE_PROPOSAL_SCHEMA,
                      display_name=f"Value proposal {held.get('No') or ''}".strip(), skip_cache=False)
    except Exception:
        return None, ["call_failed"]
    try:
        proposal = json.loads(re.sub(r"^\s*```(?:json)?\s*|\s*```\s*$", "", answer)) if isinstance(answer, str) else answer
    except (TypeError, ValueError):
        return None, ["answer_not_json"]
    problems = inspire_value_proposal_problems(proposal, columns, entries)
    return (None if problems else proposal), problems


def inspire_value_benefit_status(spec: dict, evidence=None) -> str:
    """proven only for a realized business outcome on a measured effect; a model-quality metric never counts."""
    effect = ((spec or {}).get("sourced") or {}).get("effect")
    source = effect.get("source") if isinstance(effect, dict) else None
    if source not in INSPIRE_VALUE_SOURCES or source == "exploratory":
        return "exploratory"

    def business(item) -> bool:
        metric = str(item.get("metric") or "").lower() if isinstance(item, dict) else ""
        tokens = set(re.split(r"[^a-z0-9]+", metric)) - {""}
        quality = bool(tokens & INSPIRE_VALUE_MODEL_METRIC_TOKENS) or "c_index" in metric or any(token.endswith("auc") for token in tokens)
        return isinstance(item, dict) and item.get("kind") == "realized_outcome" and bool(metric) and not quality
    return "proven" if source == "measured" and any(business(item) for item in evidence or []) else "estimated"


def _inspire_value_lib_per_usd(currency):
    try:
        table = _inspire_json.loads(inspire_notebook_asset("fx_averages"))
        rate = {**(table.get("per_usd") or {}), **((table.get("pegged") or {}).get("per_usd") or {})}.get(currency)
        return float(rate) if rate else None
    except Exception:
        return None


def _inspire_value_lib_net_text(calculated: dict, currency) -> str:
    net = ((calculated.get("scenarios") or {}).get("base") or {}).get("net")
    if not net:
        return ""
    shown = " / ".join(f"{'-' if net[tier] < 0 else ''}{currency + ' ' if currency else ''}{inspire_money_short(abs(net[tier]))}"
                       for tier in INSPIRE_VALUE_TIERS)
    return f"; net after the S/M/L cost tiers ({calculated['cost']['label']}, editable): {shown}"


def _inspire_value_measured(base: dict, spec: dict, value: float, baseline: dict, user_text: str, per_unit=None, uc=None, family: str = "") -> dict:
    low, high, uplift_source = base["uplift_low"], base["uplift_high"], base["uplift_source"]
    money_spec = per_unit[0] if per_unit else spec
    name, column, table = (inspire_plain_text(spec.get(key)) for key in ("name", "column", "table"))
    user_currency = inspire_text_currency(user_text)
    unit_currency = _kpi_impact_currency(inspire_plain_text(money_spec.get("unit")))
    column_currency = _inspire_column_currency(inspire_plain_text(money_spec.get("column")))
    reporting_currency = _inspire_reporting_currency()
    source_currency = user_currency or unit_currency or column_currency or ""
    currency = source_currency or reporting_currency or None
    currency_source = ("instructions" if user_currency else "KPI unit" if unit_currency else "column name" if column_currency
                       else "reporting currency" if reporting_currency else None)
    # The baseline is shown in the currency it was measured in; the money range is shown in the reporting currency.
    measured_in = currency
    feed_rates, rate_source, rate_column = _inspire_reporting_rate_feed() if reporting_currency else ({}, "", "")
    rate = feed_rates.get(source_currency) if source_currency != reporting_currency else None
    conversion = ""
    if rate_source == "column" and reporting_currency and source_currency in ("", reporting_currency):
        conversion = f" ({_inspire_rate_phrase('column', rate_column)})"
    elif rate is not None:
        currency, currency_source = reporting_currency, f"converted from {source_currency}"
        conversion = f" ({_inspire_rate_phrase(rate_source)}, from {source_currency} at {round(rate, 4):g})"
    elif reporting_currency and source_currency not in ("", reporting_currency):
        conversion = f" (not converted to {reporting_currency}: no rate for {source_currency})"
    window = _inspire_kpi_window(baseline)
    guard = _inspire_value_guard_card(base, spec, baseline, window)
    if guard["blocked"]:
        return guard["blocked"]
    if spec.get("rate"):
        rate, conversion, currency, measured_in = None, " (converted at the rate valid on each row's date)", reporting_currency, reporting_currency
    given = (uc or {}).get("Value Proposal")
    proposal_problems = inspire_value_proposal_problems(given) if given is not None else list((uc or {}).get("value_proposal_problems") or [])
    taken = given is not None and not proposal_problems
    proposal = {"mechanism": given["mechanism"] if taken else "cost" if _inspire_kpi_down(spec) else "revenue",
                "flow_or_stock": given["flow_or_stock"] if taken else "flow", "unit": given.get("unit") if taken else None,
                "assumptions": [{"slot": "effect", "entry": "effect"}]}
    mechanism = proposal["mechanism"]
    # R12.3: a capacity or non-financial change is counted in the proposal's unit: no currency, conversion or cost tiers.
    cash = INSPIRE_VALUE_MECHANISM_BUCKET.get(mechanism) == "cash"
    if not cash:
        rate, conversion, currency, currency_source, measured_in = None, "", None, None, None
    exposure = value * (per_unit[1] if per_unit else 1) * (rate if rate is not None else 1)
    held_currency = currency if isinstance(currency, str) and currency in INSPIRE_CURRENCY_CODES else None
    kind_low, kind_high = (_inspire_uplift("", family)[:2] if uplift_source == "instructions" else (low, high))
    effect_pick = {"exploratory": {"low": kind_low, "base": (kind_low + kind_high) / 2, "high": kind_high}}
    if uplift_source == "instructions":
        effect_pick["owner"] = {"low": low, "base": (low + high) / 2, "high": high, "unit": "share"}
    library = inspire_value_library()
    library_id = ((uc or {}).get("value_library_ids") or {}).get("effect")
    if library_id:
        effect_pick["library_id"] = library_id
    resolved = inspire_value_assumptions({"effect": effect_pick}, mechanism, family, library)
    effect = resolved["sourced"]["effect"]
    low, high = effect["low"], effect["high"]
    default_cost = None
    if held_currency:
        default_cost = inspire_value_default_cost(library, held_currency, None if held_currency == "USD" else _inspire_value_lib_per_usd(held_currency))
    built = inspire_value_spec_from_proposal(proposal, {"exposure": exposure, "period_days": guard["period"] or None}, {"effect": effect},
                                             held_currency, 1, default_cost and {"source": default_cost["source"], "tiers": default_cost["tiers"]})
    calculated = inspire_value_calculate(built)
    period = "a year" if window > 0 else "for the period the data covers"
    if not calculated["ok"]:
        reason = "its measured value is negative" if "exposure_invalid" in calculated["problems"] else "its value spec is incomplete"
        return {**base, "status": INSPIRE_VALUE_NOT_MEASURED, "measure": f"{name} ({reason})",
                "text": f"Value not measured yet: {name} cannot be priced because {reason} ({', '.join(calculated['problems'])})."}
    value_low, value_high = (calculated["scenarios"][key]["change"] for key in ("low", "high"))
    down = _inspire_kpi_down(spec)
    move = f"{'falls' if down else 'rises'} {_inspire_percent(low)}-{_inspire_percent(high)}%"
    amount = f"{currency + ' ' if currency else ''}{inspire_money_range(value_low, value_high)} {period}" if cash else \
        f"{inspire_money_range(value_low, value_high)} {calculated['unit']} {period}"
    if not cash or conversion:
        shown = f"{amount}{conversion}"
    elif currency_source == "reporting currency" and _inspire_reporting_is_default():
        shown = f"{amount} (currency {currency}, default)"
    elif currency_source == "reporting currency":
        shown = f"{amount} (currency assumed: {currency}, reporting currency)"
    else:
        shown = amount if currency else f"{amount} ({INSPIRE_CURRENCY_UNKNOWN})"
    where = {"owner": "the instructions", "library": f"the cited library entry {effect.get('library_id')}"}.get(
        effect["source"], "an assumption for this kind of use case")
    assumption = f"{name} {move}; the range comes from {where} and can be changed"
    measured = _inspire_measured_text(spec, value, baseline, None if per_unit else measured_in)
    measured_from = {"table": table, "column": column, "window_days": window or None,
                     "measured_on": baseline.get("measured_on"), "baseline": value}
    if per_unit:
        unit_spec, unit_value, unit_baseline = per_unit
        measured += f", each worth {_inspire_measured_text(unit_spec, unit_value, unit_baseline, measured_in)}"
        assumption += f"; each {name.lower()} is worth the measured {inspire_plain_text(unit_spec.get('name')).lower()}"
        measured_from["per_unit"] = {"kpi": inspire_plain_text(unit_spec.get("name")), "table": inspire_plain_text(unit_spec.get("table")),
                                     "column": inspire_plain_text(unit_spec.get("column")), "value": unit_value,
                                     "measured_on": unit_baseline.get("measured_on")}
    text = f"{shown}, if {name.lower()} {move} (measured: {measured}; the percentages are an assumption)" + guard["note"]
    text += _inspire_value_lib_net_text(calculated, currency)
    if "effect_owner_out_of_bounds" in resolved["flags"] or "effect_owner_unit_mismatch" in resolved["flags"]:
        text += "; the range in the instructions was not used because it is outside the allowed bounds"
    net = calculated["scenarios"]["base"]["net"]
    return {**base, **guard["fields"], "status": "measured", "value_low": round(value_low, 2), "value_high": round(value_high, 2),
            "net": dict(net) if net else None, "net_low": dict(calculated["scenarios"]["low"]["net"] or {}) or None, "net_negative": "net_negative" in calculated["flags"], "cost": calculated["cost"],
            "assumption_flags": list(resolved["flags"]), "benefit_status": inspire_value_benefit_status(built),
            **({"value_proposal_problems": proposal_problems} if proposal_problems else {}),
            "confidence": calculated["confidence"], "gate": calculated["gate"],
            "currency": currency, "currency_source": currency_source, "period": "year" if window > 0 else "data period",
            "kpi": name, "assumption": assumption, "short": shown, "text": text, "measured_from": measured_from,
            "value_spec": built}


INSPIRE_SELECTION_CAP = 20
INSPIRE_SELECTION_STOP_SHARE = 0.02
INSPIRE_SELECTION_REASONS = ("merged", "overlapping", "lacking_evidence", "lower_marginal_value")
INSPIRE_SELECTION_SECTIONS = ("must_have", "selected", "strategic", "left_out")


def _inspire_selection_card(uc: dict) -> dict:
    card = (uc or {}).get("Value Estimate")
    return card if isinstance(card, dict) and card.get("status") == "measured" else {}


def inspire_selection_fingerprints(uc: dict) -> list:
    """(entity, outcome, period) per measured table and column of the card, plus the per-unit one."""
    card = _inspire_selection_card(uc)
    source = card.get("measured_from")
    if not isinstance(source, dict):
        return []
    period = str(card.get("period") or "")
    entity = lambda value: str(value or "").replace("`", "").replace(" ", "").lower()
    out = [(entity(source.get("table")), str(source.get("column") or "").lower(), period)]
    unit = source.get("per_unit")
    if isinstance(unit, dict):
        out.append((entity(unit.get("table")), str(unit.get("column") or "").lower(), period))
    return out


def inspire_value_selection(use_cases, cap=INSPIRE_SELECTION_CAP, stop_share=INSPIRE_SELECTION_STOP_SHARE) -> dict:
    """R14.1-R14.3: deterministic greedy pick by conservative marginal net value. Pure, JSON-safe, never mutates its input."""
    def number(value):
        return float(value) if isinstance(value, (int, float)) and not isinstance(value, bool) and value == value and abs(value) != float("inf") else None

    def conservative_of(card):
        net_low = card.get("net_low")
        values = [number(v) for v in net_low.values()] if isinstance(net_low, dict) else []
        return min(values) if values and None not in values else None

    items = []
    for uc in use_cases or []:
        card = _inspire_selection_card(uc)
        currency = card.get("currency")
        items.append({"uc": uc, "card": card, "key": str(uc.get("use_case_key") or use_case_key(uc)), "no": str(uc.get("No", "")),
                      "currency": currency if isinstance(currency, str) and currency in INSPIRE_CURRENCY_CODES else None,
                      "must": bool(uc.get("user_named")) or uc.get("owner_must_have") is True})
    for item in items:
        item["sort"] = (item["key"], item["no"])
        item["fps"] = [list(fp) for fp in inspire_selection_fingerprints(item["uc"])]
        item["conservative"] = conservative_of(item["card"]) if item["card"] else None
    held = Counter(item["currency"] for item in items
                   if item["card"] and item["currency"] and isinstance(item["card"].get("net_low"), dict))
    currency = sorted(held.items(), key=lambda pair: (-pair[1], pair[0]))[0][0] if held else None
    cap = int(cap)

    def row(item, section, **fields):
        base = {"No": item["no"], "Name": str(item["uc"].get("Name", "")), "use_case_key": item["key"], "section": section,
                "rank": None, "label": None, "conservative": None, "marginal": None, "currency": None, "gate": None,
                "fingerprints": [], "reason": None, "merged_into": None, "overlaps_with": [], "note": None}
        base.update(fields)
        return base

    musts = [i for i in items if i["must"]]
    rest = [i for i in items if not i["must"]]
    candidates, strategic_items, lacking = [], [], []
    for item in rest:
        card = item["card"]
        if not card or not item["currency"]:
            item["note"] = "currency_unknown" if card else None
            strategic_items.append(item)
        elif item["currency"] != currency:
            item["note"] = "currency_not_comparable"
            strategic_items.append(item)
        elif item["conservative"] is None or (card.get("confidence") or {}).get("baseline") == "low":
            lacking.append(item)
        else:
            candidates.append(item)
    musts.sort(key=lambda i: ((0, -i["conservative"]) if i["conservative"] is not None and i["currency"] == currency else (1, 0), i["sort"]))
    money = lambda item: item["conservative"] is not None and item["currency"] == currency and bool(item["card"])
    claims, picks, rows_by_id = {}, [], {}

    def unclaimed_share(item):
        fps = [tuple(fp) for fp in item["fps"]]
        return 1.0 if not fps else sum(1 for fp in fps if fp not in claims) / len(fps)

    def pick(item, section, marginal, label=None):
        picks.append(item)
        for fp in item["fps"]:
            claims.setdefault(tuple(fp), item)
        gate = item["card"].get("gate") if money(item) else None
        rows_by_id[id(item)] = row(item, section, rank=len(picks), label=label,
                                   conservative=item["conservative"] if money(item) else None,
                                   marginal=marginal if money(item) else None, currency=currency if money(item) else None,
                                   gate=dict(gate) if isinstance(gate, dict) else None, fingerprints=item["fps"])

    for item in musts:
        pick(item, "must_have", item["conservative"], "Owner must-have" if item["uc"].get("owner_must_have") is True
             else "Named in the instructions")
    first_value = floor = None
    stop = None
    remaining = list(candidates)
    while True:
        if len(picks) >= cap:
            stop = "cap"
            break
        if not remaining:
            stop = "exhausted"
            break
        scored = sorted(((item["conservative"] * unclaimed_share(item), item) for item in remaining),
                        key=lambda pair: (-pair[0], pair[1]["sort"]))
        value, best = scored[0]
        if value <= 0 or (floor is not None and value < floor):
            stop = "marginal_floor"
            break
        if first_value is None:
            first_value, floor = value, stop_share * value
        remaining.remove(best)
        pick(best, "selected", value)
    for position, item in enumerate(picks):
        rows_by_id[id(item)]["rank"] = position + 1
    holder_order = {id(item): position for position, item in enumerate(picks)}
    left_rows, overlaps = [], []
    picked = {id(item) for item in picks}
    as_set = lambda item: {tuple(fp) for fp in item["fps"]}
    for item in sorted(candidates, key=lambda i: i["sort"]):
        fps = [tuple(fp) for fp in item["fps"]]
        for other in picks:
            if other is item or (id(item) in picked and holder_order[id(other)] > holder_order[id(item)]):
                continue
            shared = [list(fp) for fp in fps if fp in as_set(other)]
            if shared:
                overlaps.append({"use_case": item["no"], "with": other["no"], "fingerprints": shared, "share": len(shared) / len(fps)})
        if id(item) in picked:
            continue
        holders = [claims[fp] for fp in fps if fp in claims]
        marginal = item["conservative"] * unclaimed_share(item)
        gate = item["card"].get("gate")
        fields = {"conservative": item["conservative"], "currency": currency, "fingerprints": item["fps"],
                  "gate": dict(gate) if isinstance(gate, dict) else None}
        if holders and len(holders) == len(fps):
            left_rows.append(row(item, "left_out", reason="merged", marginal=0.0, **fields,
                                 merged_into=min(holders, key=lambda h: holder_order[id(h)])["no"]))
        elif holders:
            unique = sorted({id(h): h for h in holders}.values(), key=lambda h: holder_order[id(h)])
            left_rows.append(row(item, "left_out", reason="overlapping", marginal=marginal, overlaps_with=[h["no"] for h in unique], **fields))
        else:
            left_rows.append(row(item, "left_out", reason="lower_marginal_value", marginal=marginal, **fields))
    gaps = []
    for item in sorted(lacking, key=lambda i: i["sort"]):
        card = item["card"]
        why = ("no low-scenario net: the value could not be priced conservatively" if item["conservative"] is None
               else "the baseline behind the money figure has low confidence")
        left_rows.append(row(item, "left_out", reason="lacking_evidence", note=why))
        gaps.append({"No": item["no"], "Name": str(item["uc"].get("Name", "")), "reason": why,
                     "measure": str(card.get("kpi") or card.get("measure") or "")})
    strategic_items.sort(key=lambda i: (-(number(i["uc"].get("Inspire Score")) or 0.0), i["key"], i["no"]))
    strategic_rows = [row(item, "strategic", note=item.get("note")) for item in strategic_items]
    selected_rows = [rows_by_id[id(item)] for item in picks]
    left_rows.sort(key=lambda r: (-(r["marginal"] if r["marginal"] is not None else float("-inf")), r["use_case_key"], r["No"]))
    overlaps.sort(key=lambda o: (o["use_case"], o["with"]))
    return {"selected": selected_rows, "strategic": strategic_rows, "left_out": left_rows,
            "long_list": selected_rows + strategic_rows + left_rows, "overlaps": overlaps, "gaps": gaps,
            "stop": {"reason": stop, "cap": cap, "floor": floor, "first_value": first_value}, "currency": currency}


def _inspire_uc_tables(uc: dict) -> set:
    names = [uc.get("Primary Table"), *str(uc.get("Tables Involved") or "").split(",")]
    return {inspire_plain_text(name).lower() for name in names if inspire_plain_text(name)}


def inspire_value_metric_kpis(uc: dict, kpis: list, named, kind=None) -> list:
    chosen = [spec for spec in kpis if named(spec)]
    if chosen:
        return chosen
    tables = _inspire_uc_tables(uc)
    held = lambda spec: _INSPIRE_KPI_HELD_RE.search(str(spec.get("direction") or ""))
    own = [spec for spec in kpis if _inspire_kpi_is_money(spec) and not held(spec)
           and inspire_plain_text(spec.get("table")).lower() in tables]
    if not inspire_kind_values_from_kpi(kind):
        return own
    metric = inspire_kind_words(uc)["kpi"].lower()
    by_kind = [spec for spec in kpis if metric and inspire_plain_text(spec.get("name")).lower() == metric and not held(spec)]
    return by_kind + [spec for spec in own if spec not in by_kind]


_INSPIRE_BARE_IDENT = re.compile(r"(?<![`\w.])[A-Za-z][A-Za-z0-9]*(?:_[A-Za-z0-9]+)+(?![\w`]|\.[A-Za-z0-9])")


def inspire_ident_words(text) -> str:
    plain = re.sub(r"`([^`]*)`", lambda match: match.group(1).replace("_", " ") if _INSPIRE_IDENT.fullmatch(match.group(1)) else match.group(1),
                   str(text or "")).replace("`", "")
    return _INSPIRE_BARE_IDENT.sub(lambda match: match.group(0).replace("_", " "), plain)


def _inspire_value_quantity(uc: dict, kind) -> str:
    if not kind or inspire_kind_values_from_kpi(kind):
        return ""
    words = dict(inspire_kind_words(uc), value_at_stake="")
    text = inspire_ident_words(inspire_kind_fill(kind.get("value_formula"), words)).rstrip(".")
    return text[:1].lower() + text[1:]


def inspire_value_estimate(uc: dict, user_text: str = "", family: str = "", kind=None) -> dict:
    low, high, uplift_source = _inspire_uplift(user_text, family)
    base = {"uplift_low": low, "uplift_high": high, "uplift_source": uplift_source}
    lowered = str(user_text or "").lower()
    named = lambda spec: bool(inspire_plain_text(spec.get("name"))) and inspire_plain_text(spec.get("name")).lower() in lowered
    kpis = sorted((spec for spec in uc.get("KPIs") or [] if isinstance(spec, dict)), key=lambda spec: not named(spec))
    metric = inspire_value_metric_kpis(uc, kpis, named, kind)
    money = [spec for spec in kpis if _inspire_kpi_is_money(spec)]
    for spec in (spec for spec in metric if _inspire_kpi_is_money(spec)):
        value, baseline = _inspire_kpi_plain(spec, ("SUM",))
        if value is not None:
            return _inspire_value_measured(base, spec, value, baseline, user_text, None, uc, family)
    counts = [spec for spec in metric if not _inspire_kpi_is_money(spec)
              and _inspire_kpi_plain(spec, INSPIRE_VALUE_COUNT_AGGREGATIONS)[0] is not None]
    for spec in counts:
        value, baseline = _inspire_kpi_plain(spec, INSPIRE_VALUE_COUNT_AGGREGATIONS)
        per_unit = _inspire_per_unit_money(spec, baseline, money)
        if per_unit:
            return _inspire_value_measured(base, spec, value, baseline, user_text, per_unit, uc, family)
    first_table = next((inspire_plain_text(spec.get("table")) for spec in kpis if inspire_plain_text(spec.get("table"))), "") or \
        inspire_plain_text(str(uc.get("Tables Involved") or "").split(",")[0])
    unsummed = next((spec for spec in money if _inspire_kpi_measured_value(spec)[0] is not None
                 and (spec.get("denominator") or str(spec.get("aggregation") or "").strip().upper() != "SUM")), None)
    quantity = "" if any(named(spec) for spec in kpis) else _inspire_value_quantity(uc, kind)
    if quantity:
        measure = quantity
    elif kind and not metric and kpis:
        measure = f"the change in {inspire_kind_words(uc)['kpi'] or 'the KPI this use case moves'} as a money total over a time window"
    elif counts:
        count = counts[0]
        measure = (f"the money value per unit of {inspire_plain_text(count.get('name')).lower()}, for example the average of a price "
                   f"or amount column in {inspire_plain_text(count.get('table')) or first_table or 'the same table'} over the same rows")
    elif unsummed is not None:
        measure = (f"the total of {inspire_plain_text(unsummed.get('column')) or 'the money column'} over a time window, "
                   f"because {inspire_plain_text(unsummed.get('name'))} is measured as a {'ratio' if unsummed.get('denominator') else str(unsummed.get('aggregation') or 'value').lower()}, not a total")
    elif money:
        measure = (f"{inspire_plain_text(money[0].get('name'))} by running its KPI query ("
                   + (_inspire_value_missing_reason(money[0]) or "this run ran it and got no value" if "baseline" in money[0] else "this run did not read the data for it") + ")")
    else:
        measure = ("a money total this use case moves, for example the sum of a revenue or cost column"
                   + (f" in {first_table}" if first_table else ""))
    return {**base, "status": INSPIRE_VALUE_NOT_MEASURED, "measure": measure, "text": f"Value not measured yet: measure {inspire_ident_words(measure)}."}


def inspire_fill_key_result_targets(uc: dict, estimate: dict) -> None:
    kpis = [spec for spec in uc.get("KPIs") or [] if isinstance(spec, dict)]
    low, high = estimate["uplift_low"], estimate["uplift_high"]
    for key_result in uc.get("Expected Key Results") or []:
        if not isinstance(key_result, dict) or key_result.get("source") != "proposed":
            continue
        text = str(key_result.get("statement") or "")
        named = [spec for spec in kpis if inspire_plain_text(spec.get("name"))
                 and inspire_plain_text(spec.get("name")).lower() in text.lower()]
        spec = named[0] if named else (kpis[0] if len(kpis) == 1 else None)
        value, _baseline = _inspire_kpi_measured_value(spec)
        metric = estimate.get("status") == "measured" and spec is not None and inspire_plain_text(spec.get("name")) == estimate.get("kpi")
        if value and metric:
            down = _inspire_kpi_down(spec)
            ends = sorted(value * (1 - share if down else 1 + share) for share in (low, high))
            target = (f"between {DatabricksInspire._format_baseline(ends[0])} and {DatabricksInspire._format_baseline(ends[1])} "
                      f"(assumed {_inspire_percent(low)}-{_inspire_percent(high)}% {'lower' if down else 'higher'})")
            window = INSPIRE_VALUE_WINDOW
        else:
            target, window = INSPIRE_VALUE_TARGET_UNMEASURED, INSPIRE_VALUE_WINDOW_UNMEASURED
        text = _PLACEHOLDER_UNSET_TARGET_RE.sub(f"[TARGET: {target}]", text)
        key_result["statement"] = re.sub(r"\[\s*WINDOW\s*\]", f"[WINDOW: {window}]", text, flags=re.I)


