def implement_table_create_sql(implement_table: str) -> str:
    columns = ", ".join(f"`{name}` {kind} COMMENT {inspire_sql_literal(_semunity_column_comment(IMPLEMENT_TABLE, name))}"
                        for name, kind in IMPLEMENT_COLUMNS)
    return (f"CREATE TABLE IF NOT EXISTS {implement_table} ({columns}) USING DELTA "
            f"{inspire_row_concurrency_sql(['`session_id`', '`use_case_id`'])} COMMENT {inspire_sql_literal(IMPLEMENT_TABLE_COMMENT)}")


def implement_removed_table_problems(spec: dict, involved, primary: str = "") -> list:
    removed = [_implement_plain_table(t) for t in ((spec or {}).get("data") or {}).get("removed_tables") or []]
    if not removed:
        return []
    gone = {t.lower() for t in removed}
    known = {_implement_plain_table(t).lower() for t in involved or ()}
    primary = _implement_plain_table(primary)
    problems = []
    if primary and primary.lower() in gone:
        problems.append(f"{primary} is the primary table of this use case; swap it instead of removing it")
    strangers = [t for t in removed if t.lower() not in known]
    if strangers:
        problems.append(f"{', '.join(strangers)} {'is' if len(strangers) == 1 else 'are'} not among the tables of this use case")
    if known and known <= gone:
        problems.append("every table of this use case was removed; keep at least one")
    return problems


IMPLEMENT_PERSON_NAME_TOKENS = ("name", "email", "phone", "address")


def implement_column_role_problems(roles: dict, evidence: dict, dated: dict, trains_model: bool = True,
                                   free_text_tokens=()) -> list:
    evidence = {str(k).lower(): v for k, v in (evidence or {}).items() if isinstance(v, dict)}
    dated = {(str(t).lower(), str(c).lower()) for t, c in (dated or {})}
    text_tokens = set(free_text_tokens) | set(IMPLEMENT_PERSON_NAME_TOKENS)
    problems = []
    for role, ref in sorted((roles or {}).items()):
        parts = str(ref or "").strip().strip("`").split(".")
        if len(parts) != 4 or (role == "label" and not trains_model):
            continue
        table, column = ".".join(parts[:3]).lower(), parts[3].lower()
        if table not in evidence:
            continue
        columns = {str(k).lower(): v for k, v in (evidence[table].get("columns") or {}).items() if isinstance(v, dict)}
        if column not in columns:
            problems.append(f"{ref} is not a column of {'.'.join(parts[:3])}")
            continue
        kind = str(columns[column].get("type") or "unknown type").upper()
        family = _metadata_type_family(kind)
        date_key = (table, column) in dated
        key_like = _is_key_like_column(column)
        free_text = family == "string" and bool(text_tokens & set(_name_tokens(column)))
        shown = f"{ref} ({kind}{', a date key' if date_key else ''})"
        label = role.replace("_", " ")
        if role == "entity_id" and (date_key or family in ("temporal", "boolean") or (family == "numeric" and not key_like)):
            problems.append(f"{shown} cannot be the entity id: a date, a date key or a measure is not the entity the decision acts on")
        elif role == "event_date" and not (family == "temporal" or date_key):
            problems.append(f"{shown} cannot be the event date: it is neither a DATE or TIMESTAMP column nor a date key that joins "
                            "a date table")
        elif role == "measure" and (family != "numeric" or key_like or date_key):
            problems.append(f"{shown} cannot be the measure: a measure is a numeric column that is not a key")
        elif role == "label" and (family == "temporal" or date_key or key_like or free_text):
            problems.append(f"{shown} cannot be the {label}: an outcome is a flag, a number or a category, never a date, a key, "
                            "a name or free text")
        elif role == "segment" and (family in ("temporal", "other") or date_key or free_text):
            problems.append(f"{shown} cannot be the {label}: a segment is a category column, never a date or free text")
    return problems


def implement_build_stamp() -> dict:
    shell = INSPIRE_NOTEBOOK_ASSETS.get("app_shell") or {}
    return {"version": __AGENT_VERSION__, "shell": str(shell.get("sha256") or "")}


def implement_unread_outcome(outcome: dict) -> str:
    if outcome.get("status") != "unknown":
        return "no reason given"
    ended = "with output Inspire does not read as a result" if str(outcome.get("text") or "").strip() else "without saying what it wrote"
    return (f"the notebook ran but ended {ended}, so Inspire could not check its rows; its run step must return how many rows it wrote "
            "or why it stopped, and the notebook must not end itself before that")


def implement_stop_message(outcome: dict, spec: dict, trains_model: bool = True) -> str:
    outcome = outcome if isinstance(outcome, dict) else {}
    if outcome.get("denied"):
        return f"the preview run was denied a privilege Genie cannot fix in the notebook: {outcome['denied']}"
    reason = implement_brief_error(outcome.get("stop_reason") or outcome.get("error") or implement_unread_outcome(outcome))
    by_genie = outcome.get("status") == "stopped" and outcome.get("stopped_by") == "genie"
    text = f"{'Genie stopped the build' if by_genie else 'the preview run did not write usable rows'}: {reason}"
    built = " ".join(inspire_redact_text(implement_plain_change_text("; ".join(outcome.get("build_problems") or [])), set(), "").split()).strip("; ")
    if built:
        text = (f"Genie's last build round did not finish ({built[:600]}), so the notebook may not "
                f"hold the latest choices and asks, and {text}")
    if outcome.get("not_a_stop"):
        text = text.rstrip(".") + (f". {'Inspire sent it back to Genie, and it still stopped' if outcome.get('sent_back') else inspire_rebuild_action(first=True)}"
                                    f": {str(outcome['not_a_stop'])[:600]}")
    roles = [(role, ref) for role, ref in sorted((((spec or {}).get("data") or {}).get("column_roles") or {}).items())
             if ref and (role != "label" or trains_model)]
    for extra in ("ask_user", "buildable", "repair_note"):
        if outcome.get(extra):
            text = text.rstrip(".") + f". {outcome[extra]}"
    if outcome.get("status") == "stopped" and roles:
        chosen = ", ".join(f"{role.replace('_', ' ')} = {ref}" for role, ref in roles)
        text = text.rstrip(".") + (f". The run used the column roles set in the wizard ({chosen}) in place of the use case's own; "
                                    "if they do not fit, set them back with Reset roles to Inspire's choice in the Data step")
    return text


def _implement_count(value):
    text = str(value if value is not None else "").strip().replace(",", "")
    share = text.endswith("%")
    try:
        number = float(text.rstrip("%"))
    except ValueError:
        return None
    return number / 100 if share else number


def _implement_count_text(value) -> str:
    number = _implement_count(value)
    if number is None or str(value).strip().endswith("%"):
        return " ".join(str(value or "").split())
    return f"{int(number):,}" if float(number).is_integer() else implement_number_text(number)


def _implement_readiness_patterns() -> list:
    patterns = []
    for family, rules in INSPIRE_READINESS_RULES.items():
        for name, key, op, th_key, message in rules:
            if INSPIRE_FLAG_ONLY_READINESS.get(key):
                continue
            parts = re.split(r"(\{(?:observed|required)[^}]*\})", message)
            body = "".join(f"(?P<{part[1:9]}>[-+]?[\\d.,]*\\d%?)" if part.startswith("{") else re.escape(part).replace("\\ ", r"\s+")
                           for part in parts)
            patterns.append((family, name, key, op, "" if "*" in str(th_key) else str(th_key or ""), re.compile(body, re.I)))
    return patterns


IMPLEMENT_READINESS_PATTERNS = _implement_readiness_patterns()
_IMPLEMENT_SHORTFALL_RE = re.compile(r"too few\b[^.;]*?\((?P<observed>[\d.,]*\d)\)[^.;]*?[;,]\s*at least (?P<required>[\d.,]*\d)", re.I)


def implement_readiness_shortfall(reason, family: str = "") -> dict:
    text = " ".join(str(reason or "").split())
    for owner, name, key, op, setting, pattern in IMPLEMENT_READINESS_PATTERNS:
        if family and owner not in ("common", family):
            continue
        found = pattern.search(text)
        if found:
            values = found.groupdict()
            return {"check": key, "name": name, "op": op, "setting": setting, "observed": values.get("observed") or "",
                    "required": values.get("required") or "", "message": found.group(0)}
    found = _IMPLEMENT_SHORTFALL_RE.search(text)
    if found:
        return {"check": "", "name": "", "op": ">=", "setting": "", "observed": found.group("observed"),
                "required": found.group("required"), "message": found.group(0)}
    return {}


def implement_shortfall_noun(short: dict, count=None) -> str:
    name = short.get("name") or ""
    if count is not None and _implement_count(count) == 1:
        return IMPLEMENT_SHORTFALL_NOUN_ONE.get(name, name or "record")
    return IMPLEMENT_SHORTFALL_NOUNS.get(name, name or "records")


def implement_no_data(reason, family: str = "") -> bool:
    short = implement_readiness_shortfall(reason, family)
    if short and short.get("name") == "rows" and _implement_count(short.get("observed")) == 0:
        return True
    return inspire_no_data_reason(reason)


def implement_no_data_note(reason) -> str:
    return IMPLEMENT_NO_DATA_NOTE.format(reason=" ".join(str(reason or "").split()))


def implement_unreliable_note(reason, family: str) -> str:
    return IMPLEMENT_UNRELIABLE_NOTE.format(reason=" ".join(str(reason or "").split()),
                                            method=IMPLEMENT_DATA_SHORT_METHODS.get(family, "a simpler method"))


def implement_data_repair_text(short: dict, family: str, fill=None, lead: str = IMPLEMENT_DATA_REPAIR_AFTER) -> str:
    setting = short.get("setting") or ""
    allowed = next((str(w.get("allowed") or "") for w in (fill or {}).get("widgets") or []
                    if isinstance(w, dict) and str(w.get("name") or "") == setting), "")
    if not allowed and setting in GENIE_WIDGET_ALLOWED:
        low, high, whole = GENIE_WIDGET_ALLOWED[setting]
        allowed = ("whole number, " if whole else "") + (f"{low} to {high}" if high is not None else f"at least {low}")
    return IMPLEMENT_DATA_REPAIR.format(lead=lead, message=short.get("message") or "", observed=_implement_count_text(short.get("observed")) or "the measured",
                                        noun=implement_shortfall_noun(short, short.get("observed")), method=IMPLEMENT_DATA_SHORT_METHODS.get(family, "a simpler method"),
                                        setting=setting or "the minimum", allowed=allowed or "as declared")


def implement_data_minimum_choices(short: dict, family: str = "", undated=None) -> str:
    if undated:
        named = " or ".join(undated) if len(undated) < 3 else ", ".join(undated[:-1]) + ", or " + undated[-1]
        return (f"Your choices: add a date or timestamp column to {named}, or a key that joins {'it' if len(undated) == 1 else 'them'} "
                "to a table that has one, then rebuild, or build another use case the data supports.")
    short = short or {}
    setting = short.get("setting") or ""
    need = (f"at least {_implement_count_text(short['required'])} {implement_shortfall_noun(short, short['required'])}"
            if short.get("op") != "<=" and short.get("required") else "the minimum above")
    choices = ([f"lower {GENIE_WIDGET_LABELS.get(setting, setting)} in the build settings so Genie builds a simpler method"]
               if setting and setting in GENIE_READINESS_THRESHOLDS.get(family, {}) else [])
    choices += [f"Rebuild once the data has {need}", "build another use case the data supports"]
    return "Your choices: " + ", ".join(choices[:-1]) + ", or " + choices[-1] + "."


def implement_stop_extras(repair: dict, repaired: dict) -> dict:
    extras = {name: repair[name] for name in ("ask_user", "buildable") if (repair or {}).get(name)}
    if (repair or {}).get("kind") == "other" and (repaired or {}).get("other", 0) > 1:
        extras["repair_note"] = f"Inspire sent it back to Genie {inspire_plural(repaired['other'] - 1, 'time')} with the error, and it still stopped"
    return extras


def implement_repair_budget(kind: str, rounds: int, data_rounds: int) -> tuple:
    if kind == "data" and data_rounds:
        return rounds + 1, data_rounds - 1
    return rounds, data_rounds


def _implement_readiness_measured(fill) -> dict:
    measured = {}
    for item in (fill or {}).get("readiness") or []:
        if isinstance(item, dict) and _implement_count(item.get("measured")) is not None:
            measured[str(item.get("check") or "").strip().strip("`").lower()] = str(item.get("measured")).strip()
    return measured


def _implement_fails_minimum(op: str, have: float, limit: float) -> bool:
    return (op == ">=" and have < limit) or (op == "<=" and have > limit)


def implement_current_shortfall(shortfall, fills=()) -> dict:
    short = dict(shortfall or {})
    keys = [k for k in dict.fromkeys(str(short.get(name) or "").strip().lower() for name in ("check", "name")) if k]
    if not short.get("observed") or not keys:
        return short
    for fill in reversed([each for each in fills or () if isinstance(each, dict)]):
        measured = _implement_readiness_measured(fill)
        found = next((measured[k] for k in keys if k in measured), None)
        if found is None:
            continue
        limit = _implement_count(short.get("required"))
        if limit is not None and not _implement_fails_minimum(short.get("op") or ">=", _implement_count(found), limit):
            return {}
        return dict(short, observed=found)
    return short


def implement_declared_setting_problems(fill, family: str, user_widgets=None) -> list:
    measured = _implement_readiness_measured(fill)
    if not measured:
        return []
    declared = {str(w.get("name") or ""): w.get("default") for w in (fill or {}).get("widgets") or [] if isinstance(w, dict)}
    problems, user = [], user_widgets or {}
    for _name, key, op, th_key, _message in INSPIRE_READINESS_RULES["common"] + INSPIRE_READINESS_RULES.get(family, ()):
        if op not in (">=", "<=") or th_key not in declared or th_key in user or key not in measured or INSPIRE_FLAG_ONLY_READINESS.get(key):
            continue
        limit, have = _implement_count(declared[th_key]), _implement_count(measured[key])
        if limit is None or not _implement_fails_minimum(op, have, limit):
            continue
        problems.append(f"you declared `{th_key}` = {declared[th_key]}, and the readiness step measured `{key}` = {measured[key]}, so the run "
                        f"would stop at that check: never declare a setting the data is known to fail. Choose a method the data supports at "
                        f"that count, such as {IMPLEMENT_DATA_SHORT_METHODS.get(family, 'a simpler method')}, declare the minimum it truly "
                        "needs, and list the change in changes")
    return problems


IMPLEMENT_GENIE_CHANGES_PHASE = "Genie changes"


_IMPLEMENT_OBJECT_NAME_RE = re.compile(r"\b(\w+(?:\.\w+){2,})\b|\b\w*__([A-Za-z]\w*)")
_IMPLEMENT_COMPANION_RE = re.compile(r"\s*\bcompanions?\b", re.IGNORECASE)


def implement_plain_change_text(text) -> str:
    """A Genie change the person reads: an internal object name (__constraints) becomes its plain words, and the word
    companion, Inspire's name for the extra tables a part draws, is dropped. A fully qualified table name (catalog.schema.table)
    is kept exactly as written, because the person needs it to find the table."""
    text = _IMPLEMENT_OBJECT_NAME_RE.sub(
        lambda found: found.group(1) if found.group(1) else found.group(2).replace("_", " "), str(text or ""))
    return inspire_redact_text(" ".join(_IMPLEMENT_COMPANION_RE.sub("", text).split()), set(), "")


def implement_genie_rule_methods(fills) -> list:
    found = []
    for fill in fills or []:
        for change in (fill or {}).get("changes") or []:
            if not isinstance(change, dict) or str(change.get("cause") or "").strip().lower() != IMPLEMENT_GENIE_CHANGE_CAUSES[1]:
                continue
            was, now = (implement_plain_change_text(" ".join(str(change.get(name) or "").split())[:300]) for name in ("method_was", "method_now"))
            if now and now.lower() != was.lower():
                found.append(f"{now}" + (f" instead of {was}" if was else ""))
    return list(dict.fromkeys(found))


# REQ-346: a repair may not change the choices the person pinned in the spec: the grouping (group_by), the scope (run_scope and its
# limits) and the money measure (currency and the tier amounts). Each is compared by its widget name, the pinned value from the spec
# (before) against the widget value Genie filled (after). The text of a change is never read, so a method, technique or model change
# passes, while a change to a pinned choice is refused.
IMPLEMENT_CHOICE_KINDS = {INSPIRE_GROUP_BY: "grouping", "run_scope": "scope", "scope_days": "scope", "scope_records": "scope",
                          "scope_groups": "scope", "currency": "measure", **{name: "measure" for name in INSPIRE_TIER_AMOUNTS}}
IMPLEMENT_SCOPE_LIMIT_MODES = {"scope_days": "recent", "scope_records": "records", "scope_groups": "groups"}


def implement_choice_text(value) -> str:
    if isinstance(value, (list, tuple, set)):
        return ", ".join(sorted(" ".join(str(item).split()).lower() for item in value))
    return " ".join(str(value if value is not None else "").split()).lower()


def implement_choice_pinned(core_widgets, first_run=None, thresholds=None) -> dict:
    # The choices the spec pins, by widget name. A value the spec leaves empty is for Genie to fill, so it is not a choice.
    # REQ-396: the thresholds the person set (thresholds, from implement_user_thresholds) are pinned like the grouping. A family default
    # is not pinned: a repair that lowers it is named as a warning by implement_genie_change_notes instead.
    pinned = {str(w.get("name") or ""): w.get("default") for w in core_widgets or [] if isinstance(w, dict)}
    pinned.update({str(name): value for name, value in (thresholds or {}).items()})
    chosen = (first_run or {}).get("chosen") or {}
    mode = chosen.get("scope")
    if mode:
        pinned["run_scope"] = mode
    for field, name in (("days", "scope_days"), ("records", "scope_records"), ("groups", "scope_groups")):
        if chosen.get(field) and mode == IMPLEMENT_SCOPE_LIMIT_MODES[name]:
            pinned[name] = chosen[field]
    stated = {str(name) for name in (thresholds or {})}
    return {name: value for name, value in pinned.items() if (name in IMPLEMENT_CHOICE_KINDS or name in stated) and implement_choice_text(value)}


def implement_user_thresholds(thresholds, config_widgets) -> dict:
    # REQ-396: only a minimum the person set (a name in the spec's config widgets) is user input, so only it is pinned.
    user = config_widgets or {}
    return {str(name): value for name, value in (thresholds or {}).items() if name in user}


def implement_choice_same(now, was) -> bool:
    # REQ-396: 0.8 and "0.80" are the same threshold, so a number is compared as a number and anything else as text.
    if implement_choice_text(now) == implement_choice_text(was):
        return True
    try:
        return float(implement_choice_text(now)) == float(implement_choice_text(was))
    except ValueError:
        return False


def implement_choice_changes(fills, pinned) -> list:
    found = []
    for fill in fills or []:
        filled = {str(w.get("name") or ""): w.get("default") for w in (fill or {}).get("widgets") or [] if isinstance(w, dict)}
        for name, was in (pinned or {}).items():
            now = filled.get(name)
            if implement_choice_text(now) and not implement_choice_same(now, was):
                kind = IMPLEMENT_CHOICE_KINDS.get(name) or f"threshold {name}"
                found.append(implement_plain_change_text(f"the {kind} from "
                                                         f"{' '.join(str(was).split())[:120]} to {' '.join(str(now).split())[:120]}"))
    return list(dict.fromkeys(found))


def implement_default_restore_reason(unset) -> str:
    # REQ-349: why a pinned Grouping default that Genie wrote could not be put back into the notebook, for the refusal message.
    return "; ".join(f"the {w.get('name')} widget default is {str(held)[:60]}, and Inspire could not write {str(planned)[:60]} "
                     "back into the notebook" for w, held, planned in unset)


def implement_choice_refusal(grouping, moved) -> str:
    columns = ", ".join(str(c) for c in (grouping or {}).get("columns") or []) or "the records"
    if not any(str(item).startswith("the grouping") for item in moved):
        return (f"could not keep the thresholds you set: a repair tried to change them ({'; '.join(moved)[:300]}), and Inspire keeps "
                "every threshold the use case states; change the threshold on the Use case page, then build again")
    return (f"could not group by {columns}: a repair tried to change it ({'; '.join(moved)[:300]}), and Inspire keeps the grouping, "
            "scope and measure you chose; change the grouping on the Run page")



def implement_genie_change_notes(fill, shortfall=None, fills=None) -> list:
    short, notes, shortfall_noted = implement_current_shortfall(shortfall, fills or [fill]), [], False
    if short.get("observed"):
        found = f"Genie found {_implement_count_text(short['observed'])} {implement_shortfall_noun(short, short['observed'])}"
        fewer = f"{'fewer' if short.get('op') != '<=' else 'more'} than the {_implement_count_text(short.get('required'))}"
    for change in (fill or {}).get("changes") or []:
        if not isinstance(change, dict):
            continue
        c = {name: implement_plain_change_text(" ".join(str(change.get(name) or "").split())[:300]).rstrip(".") for name in IMPLEMENT_GENIE_CHANGE_FIELDS}
        cause = str(change.get("cause") or "").strip().lower()
        why = "" if re.search(r"(?i)\b(customer|user|you|your|explicit\w*|requested?|asked)\b", c["why"]) else (f": {c['why']}" if c["why"] else "")
        if c["method_now"] and c["method_now"].lower() != c["method_was"].lower():
            if short.get("observed") and c["method_was"] and cause == "data_shortfall":
                if not shortfall_noted:
                    notes.append(f"{found}, {fewer} the first method needs, so it used {c['method_now']} instead. Results will be less "
                                 f"precise; Rebuild once the data meets that minimum to use {c['method_was']}.")
                shortfall_noted = True
            else:
                notes.append(f"Genie used {c['method_now']}" + (f" instead of {c['method_was']}" if c["method_was"] else "") + f"{why}." + (IMPLEMENT_RULE_NOTE_TAIL if cause == "rule" else ""))
        elif c["setting"] and c["value_now"] and c["value_now"] != c["value_was"]:
            label = GENIE_WIDGET_LABELS.get(c["setting"], c["setting"])
            tied = (short.get("observed") and short.get("setting") and c["setting"].lower() == str(short["setting"]).lower()
                    and cause in ("data_shortfall", ""))
            lead = f"{found}, {fewer} the setting asked for, so it set" if tied else "Genie set"
            notes.append(f"{lead} {label} to {c['value_now']}" + (f", not {c['value_was']}" if c["value_was"] else "") + f"{why}.")
        elif c["what"]:
            notes.append(f"Genie changed {c['what']}{why}.")
    return list(dict.fromkeys(notes))


_IMPLEMENT_TABLE_GONE_RE = re.compile(r"\b(TABLE_OR_VIEW_NOT_FOUND|SCHEMA_NOT_FOUND|CATALOG_NOT_FOUND|NO_SUCH_CATALOG_EXCEPTION)\b"
                                      r"|cannot be found|was not found", re.IGNORECASE)
_IMPLEMENT_TABLE_DENIED_RE = re.compile(r"\b(INSUFFICIENT_PERMISSIONS|PERMISSION_DENIED)\b|does not have \w+( \w+)? (privilege )?on",
                                        re.IGNORECASE)


def implement_source_tables(spec: dict, involved) -> list:
    data = (spec or {}).get("data") or {}
    tables = data.get("tables") if isinstance(data.get("tables"), dict) else {}
    swaps = {_implement_plain_table(original).lower(): _implement_plain_table(chosen) for original, chosen in tables.items()}
    removed = data.get("removed_tables") if isinstance(data.get("removed_tables"), list) else []
    gone = {_implement_plain_table(t).lower() for t in removed}
    out = []
    for table in involved or ():
        key = _implement_plain_table(table).lower()
        if key in gone:
            continue
        chosen = swaps.get(key) or _implement_plain_table(table)
        if chosen.lower() not in {t.lower() for t in out}:
            out.append(chosen)
    return out


def implement_source_columns(tables, columns_of=None):
    """FX-93: the lower-case column names of the tables the build reads, for the row-filter guard. None when no table's columns can be
    read, so the guard keeps its old reach rather than waving every condition through."""
    read, names = columns_of or implement_scope_columns_of, set()
    for table in tables or ():
        try:
            names |= {str(c).lower() for c in read(table) if c}
        except Exception:
            continue
    return names or None


def _implement_lower_name(value) -> str:
    return ("" if value is None else str(value)).strip().lower()


def _implement_unique_names(names) -> list:
    out = []
    for raw in names:
        name = ("" if raw is None else str(raw)).strip()
        if name and _implement_lower_name(name) not in {_implement_lower_name(n) for n in out}:
            out.append(name)
    return out


def _implement_lower_keyed(mapping) -> dict:
    out = {}
    for name, value in (mapping if isinstance(mapping, dict) else {}).items():
        out.setdefault(_implement_lower_name(name), value)
    return out


def implement_table_swap_changes(previous, current) -> list:
    before = (previous or {}).get("tables") if isinstance((previous or {}).get("tables"), dict) else {}
    after = (current or {}).get("tables") if isinstance((current or {}).get("tables"), dict) else {}
    removed = (current or {}).get("removed_tables")
    gone = {_implement_lower_name(t) for t in removed} if isinstance(removed, list) else set()
    originals = {}
    for name in list(after) + list(before):
        originals.setdefault(_implement_lower_name(name), str(name).strip())

    def chosen_in(tables, key, original):
        hit = next((name for name in tables if _implement_lower_name(name) == key), None)
        return original if hit is None else ("" if tables[hit] is None else str(tables[hit])).strip()

    changes = [{"original": originals[key], "replaced": chosen_in(before, key, originals[key]), "chosen": chosen_in(after, key, originals[key])}
               for key in sorted(originals) if key not in gone]
    return [c for c in changes if _implement_lower_name(c["replaced"]) != _implement_lower_name(c["chosen"])]


def _implement_data_besides_tables(data) -> str:
    rest = {k: v for k, v in (data if isinstance(data, dict) else {}).items() if k not in ("tables", "removed_tables")}
    return json.dumps(rest, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def _implement_removed_tables_key(data) -> str:
    removed = data.get("removed_tables") if isinstance(data, dict) else None
    return json.dumps(sorted({_implement_lower_name(t) for t in removed} if isinstance(removed, list) else set()))


def _implement_table_change_used(change: dict, used, previous) -> list:
    on = {_implement_lower_name(change["original"]), _implement_lower_name(change["replaced"])}
    listed = _implement_lower_keyed(used).get(_implement_lower_name(change["original"]))
    names = list(listed) if isinstance(listed, list) else []
    roles = previous.get("column_roles") if isinstance(previous, dict) else None
    for ref in (roles.values() if isinstance(roles, dict) else ()):
        parts = ("" if ref is None else str(ref)).split(".")
        if len(parts) >= 4 and _implement_lower_name(".".join(parts[:3])) in on:
            names.append(".".join(parts[3:]))
    filters = previous.get("filters") if isinstance(previous, dict) else None
    for item in (filters if isinstance(filters, list) else ()):
        if isinstance(item, dict) and _implement_lower_name(item.get("table")) in on:
            names.append(item.get("column"))
    return _implement_unique_names(names)


def _implement_column_types(rows) -> dict:
    out = {}
    for row in (rows if isinstance(rows, list) else ()):
        name = row.get("column_name") if isinstance(row, dict) else None
        key = _implement_lower_name(name)
        if key and key not in out:
            out[key] = {"name": str(name).strip(), "type": ("" if row.get("data_type") is None else str(row.get("data_type"))).strip().upper()}
    return out


def implement_table_change(previous, current, used=None, columns=None) -> dict:
    changes = implement_table_swap_changes(previous, current)
    core = (_implement_data_besides_tables(previous) != _implement_data_besides_tables(current)
            or _implement_removed_tables_key(previous) != _implement_removed_tables_key(current))
    if not changes and not core:
        return {"class": None, "missing": []}
    known = _implement_lower_keyed(columns)
    missing, unproven = {}, False
    for change in changes:
        replaced = _implement_lower_name(change["replaced"])
        before = _implement_column_types(known[replaced]) if replaced in known else None
        after = _implement_column_types(known.get(_implement_lower_name(change["chosen"])))
        asked = [before.get(_implement_lower_name(name)) if before is not None else {"name": name, "type": None}
                 for name in _implement_table_change_used(change, used, previous)]
        asked = [item for item in asked if item]
        if not asked:
            unproven = True
            continue
        lost = [item["name"] for item in asked
                if item["type"] is None or item["type"] != (after.get(_implement_lower_name(item["name"])) or {}).get("type")]
        if not lost:
            continue
        key = _implement_lower_name(change["chosen"])
        entry = missing.get(key) or {"table": change["chosen"], "columns": []}
        entry["columns"] = _implement_unique_names(entry["columns"] + lost)
        missing[key] = entry
    listed = [{"table": missing[key]["table"], "columns": sorted(missing[key]["columns"], key=_implement_lower_name)} for key in sorted(missing)]
    return {"class": "data" if core or unproven or listed else "settings", "missing": listed}


_IMPLEMENT_RETABLE_USE_RE = re.compile(r"\bUSE\s+(?:CATALOG|SCHEMA|DATABASE)\b|\bsetCurrent(?:Catalog|Database)\s*\(", re.IGNORECASE)
_IMPLEMENT_ALL_COLUMNS_RE = re.compile(r"\bSELECT\s+(?:DISTINCT\s+)?(?:[\w`]+\.)?\*|\.select\(\s*['\"]\*['\"]|\bspark\.(?:read\.)?table\s*\(|"
                                       r"\.(?:columns|dtypes|schema)\b", re.IGNORECASE)
_IMPLEMENT_MISSING_COLUMN_RE = re.compile(r"\bUNRESOLVED_COLUMN\b|\bFIELD_NOT_FOUND\b|\bcannot resolve\b|\bColumn '[^']+' does not exist|"
                                          r"\bNo such struct field\b", re.IGNORECASE)


def _implement_table_named_re(table: str):
    catalog, schema, name = inspire_table_parts(table)
    part = lambda text: "`?" + re.escape(text) + "`?"
    return re.compile(r"(?<![\w.`])(?:" + part(catalog) + r"\s*\.\s*)?" + part(schema) + r"\s*\.\s*" + part(name) + r"(?![\w`])",
                      re.IGNORECASE)


def implement_retable_problems(text: str, swaps) -> list:
    problems = ["it still names the replaced table in a way Inspire cannot rewrite" for swap in swaps
                if _implement_table_named_re(swap["replaced"]).search(text)]
    return problems + ["it does not name the new table by its full name" for swap in swaps
                       if not _implement_table_named_re(swap["chosen"]).search(text)]


def _implement_artifact_texts(value):
    if isinstance(value, str):
        yield value
    elif isinstance(value, list):
        for item in value:
            yield from _implement_artifact_texts(item)
    elif isinstance(value, dict):
        for key, item in value.items():
            yield from _implement_artifact_texts(key)
            yield from _implement_artifact_texts(item)


def _implement_renamed_artifact(value, swap: dict):
    if isinstance(value, str):
        return implement_rename_table(value, swap["replaced"], swap["chosen"])
    if isinstance(value, list):
        return [_implement_renamed_artifact(item, swap) for item in value]
    if isinstance(value, dict):
        return {_implement_renamed_artifact(key, swap): _implement_renamed_artifact(item, swap) for key, item in value.items()}
    return value


def implement_retable_artifact(artifact, swaps) -> tuple:
    text = "\n".join(_implement_artifact_texts(artifact))
    named = [swap for swap in swaps if _implement_table_named_re(swap["replaced"]).search(text)]
    renamed = artifact
    for swap in named:
        renamed = _implement_renamed_artifact(renamed, swap)
    return renamed, named, implement_retable_problems("\n".join(_implement_artifact_texts(renamed)), named)


def implement_retable_cells(exported: str, swaps, owned_titles) -> tuple:
    notebook = json.loads(exported)
    code = []
    for cell in notebook.get("cells") or []:
        if cell.get("cell_type") != "code" or implement_cell_title(cell) in owned_titles:
            continue
        text = implement_cell_text(cell)
        for swap in swaps:
            text = implement_rename_table(text, swap["replaced"], swap["chosen"])
        cell["source"] = text.splitlines(keepends=True)
        code.append(text)
    joined = "\n\n".join(code)
    problems = implement_retable_problems(joined, swaps)
    if _IMPLEMENT_RETABLE_USE_RE.search(joined):
        problems.append("it picks its catalog or schema with USE, so a table name in it may stand for another table")
    return json.dumps(notebook), problems


def implement_notebook_reads(code, columns: dict) -> dict:
    text = None if code is None else str(code)
    whole = text is None or bool(_IMPLEMENT_ALL_COLUMNS_RE.search(text))
    lowered = (text or "").lower()
    words = set(re.findall(r"[a-z_][a-z0-9_]*", lowered))

    def read(name) -> bool:
        key = _implement_lower_name(name)
        return whole or key in words or (not re.fullmatch(r"\w+", key) and key in lowered)

    return {_implement_lower_name(table): [str(row["column_name"]) for row in rows or [] if read(row.get("column_name"))]
            for table, rows in columns.items()}


def implement_table_access_reason(table: str, message: str) -> str:
    text = str(message or "")
    catalog = _implement_plain_table(table).split(".")[0].lower()
    if not catalog or catalog not in re.sub(r"[`'\"]", "", text).lower():
        return ""
    if _IMPLEMENT_TABLE_GONE_RE.search(text):
        return "not found"
    if _IMPLEMENT_TABLE_DENIED_RE.search(text):
        return IMPLEMENT_NO_READ_ACCESS
    return ""


def implement_owned_objects(spec: dict, involved=()) -> set:
    config = (spec or {}).get("config") or {}
    result_table = str(config.get("result_table") or "")
    model = str((config.get("widgets") or {}).get("model_name") or "").strip()
    if not model and result_table:
        try:
            model = inspire_output_names(result_table)["model_name"]
        except ValueError:
            model = ""
    owned = set()
    for name in [result_table, model] + implement_source_tables(spec, involved):
        parts = [part.lower() for part in _implement_plain_table(name).split(".") if part]
        owned.update(".".join(parts[:size]) for size in range(1, len(parts) + 1))
    return owned


def _implement_privilege_parts(error, owned, owner=None, me: str = ""):
    text = str(error or "")
    found = _REDACT_DENIAL_RE.search(text) if _IMPLEMENT_TABLE_DENIED_RE.search(text) else None
    if not found:
        return None
    target = _implement_plain_table(found.group("quoted") or found.group("ticked") or found.group("plain").rstrip("."))
    if not implement_use_case_table(target, owned):
        return None
    who = found.group("who") or me or "the run identity"
    what = " ".join(found.group("what").upper().split())
    kind = found.group("kind").lower()
    statement = ""
    if owner is not None:
        statement = f"GRANT {what} ON {kind.upper()} {'.'.join(inspire_quote_identifier(p) for p in target.split('.'))} TO {inspire_quote_principal(who)}"
    return {"who": who, "what": what, "kind": kind, "target": target, "owner": owner, "statement": statement}


def implement_privilege_denial(error, owned, fixer: str = "the notebook", owner=None, me: str = "") -> str:
    parts = _implement_privilege_parts(error, owned, owner, me)
    if not parts:
        return ""
    who, what, kind, target = parts["who"], parts["what"], parts["kind"], parts["target"]
    if owner is None:
        grant = f"grant {what} on {kind} {target} to {who}"
    else:
        grant = (f"ask {implement_owner_label(owner)} to grant it: the exact command is in Permission Required" if owner else
                 f"ask your data owner of {kind} {target} or a metastore admin to grant it: the exact command is in Permission Required")
    return f"{who} does not have {what} on {kind} {target}, and no change to {fixer} can grant it: {grant}, then build again"


def implement_privilege_statement(error, owned, owner=None, me: str = "") -> tuple:
    """(who, GRANT statement) the Permission Required dialog copies, or ("", "") when the refusal names no grant (REQ-131, REQ-260)."""
    parts = _implement_privilege_parts(error, owned, owner, me)
    return (parts["who"], parts["statement"]) if parts and parts["statement"] else ("", "")


IMPLEMENT_NO_READ_ACCESS = "no read access"
_INSPIRE_APPLICATION_ID_RE = re.compile(r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}", re.IGNORECASE)


def inspire_identity_text(who, label="") -> str:
    who, label = " ".join(str(who or "").split()), " ".join(str(label or "").split())
    if not who:
        return "an identity Inspire could not read"
    if not _INSPIRE_APPLICATION_ID_RE.fullmatch(who):
        return who
    if label and label.lower() != who.lower():
        return f"the service principal {label} (application id {who})"
    return f"the service principal with application id {who}"


def inspire_read_grants(tables, who, per_schema: bool = False) -> list:
    who = " ".join(str(who or "").split())
    schemas = [tuple(parts[:2]) for parts in map(_implement_table_parts, tables or []) if parts]
    statements = []
    for table in tables or []:
        parts = _implement_table_parts(table)
        shared = per_schema and bool(parts) and schemas.count(tuple(parts[:2])) > 1
        for need in implement_access_plan(table, None, who)["grants"]:
            if shared and need["level"] != "catalog":
                need = {"privilege": "USE SCHEMA, SELECT", "level": "schema",
                        "object": f"{inspire_quote_identifier(parts[0])}.{inspire_quote_identifier(parts[1])}"}
            statement = implement_grant_sql(need, who)
            if statement not in statements:
                statements.append(statement)
    return statements


def inspire_unreadable_text(tables, who, label="", reads="this run reads source tables", per_schema: bool = False) -> str:
    names = [str(t) for t in tables or []]
    one = len(names) == 1
    head = f"{reads} as {inspire_identity_text(who, label)}, which cannot read {'this source table' if one else inspire_plural(len(names), 'source table')}"
    return (f"{head}. Ask your data owner of {'that table' if one else 'those tables'} to grant USE CATALOG, USE SCHEMA and SELECT "
            f"on {'it' if one else 'them'} to that identity")


def implement_missing_tables_permission(missing: list, who: str = ""):
    """The Permission Required entry for the tables the identity cannot read (REQ-131, REQ-260), or None when none needs a grant."""
    unreadable = [m["table"] for m in missing if m.get("reason") == IMPLEMENT_NO_READ_ACCESS]
    grants = inspire_read_grants(unreadable, who) if unreadable and who else []
    if not grants:
        return None
    return implement_permission_entry(who, grants, "Inspire reads these source tables with the identity it runs as.")


def implement_missing_tables_message(missing: list, who="", label="") -> str:
    gone = [m["table"] for m in missing if m.get("reason") != IMPLEMENT_NO_READ_ACCESS]
    unreadable = [m["table"] for m in missing if m.get("reason") == IMPLEMENT_NO_READ_ACCESS]
    parts = []
    first = [m["table"] for m in missing if m.get("primary") and m.get("reason") != IMPLEMENT_NO_READ_ACCESS]
    others = [t for t in gone if t not in first]
    if first:
        parts.append(f"the primary table is missing, so open Edit, Data step, and swap it for a table with the same role; "
                     f"the primary table can be swapped, not removed")
    if others:
        one = len(others) == 1
        parts.append(f"{'this source table is' if one else inspire_plural(len(others), 'source table') + ' are'} missing, so open Edit, Data step, "
                     f"and swap {'it' if one else 'each'} for a table with the same role or remove it")
    if unreadable:
        parts.append(inspire_unreadable_text(unreadable, who, label))
    return "the preview cannot run because " + ", and ".join(parts)


def implement_dropped_tables_note(missing: list) -> str:
    tables = [m["table"] for m in missing]
    one = len(tables) == 1
    return (f"{'this source table is' if one else inspire_plural(len(tables), 'source table') + ' are'} missing or unreadable, so the build leaves "
            f"{'it' if one else 'them'} out and keeps the primary table. Swap {'it' if one else 'each'} in the Data step to bring "
            f"{'it' if one else 'them'} back")


def implement_settled_message(row: dict) -> str:
    version, use_case, status = row.get("spec_version"), row.get("use_case_id"), row.get("status")
    if status == "failed":
        return (f"The use case MVP already ran spec version {version} of {use_case} and it failed: "
                f"{row.get('status_message') or 'no error was recorded'}. Submit the wizard again to build a new version.")
    return (f"Spec version {version} of {use_case} is {status}: another run is building it, or the run that was building it "
            "stopped before it finished. Submit the wizard again to build a new version.")


def implement_lock_key(session_id, use_case_id: str) -> str:
    return f"implement::{str(session_id or '').strip()}::{str(use_case_id or '').strip()}"


def implement_asset_lock_key(kind: str, asset: str) -> str:
    return f"implement-asset::{kind}::{str(asset or '').strip()}"


def implement_lock_holder_use_cases(notes) -> list:
    found = set()
    for note in notes or []:
        uc, sid = (re.search(rf"\b{name}=([^\s|]+)", str(note or "")) for name in ("uc", "session"))
        if uc:
            found.add(f"{uc.group(1)} of session {sid.group(1)}" if sid else uc.group(1))
    return sorted(found)


def implement_notebook_edited(modified_at, recorded, rewrite_ended_at=None) -> bool:
    if modified_at is None or not isinstance(recorded, dict) or recorded.get("modified_at") is None:
        return False
    if int(modified_at) == int(recorded["modified_at"]):
        return False
    return not (recorded.get("rewriting") and rewrite_ended_at is not None and int(modified_at) <= int(rewrite_ended_at))


def implement_notebook_edited_message(path: str, edited_at=None, agreed_at=None) -> str:
    if edited_at is not None and agreed_at is not None:
        shown = lambda at: time.strftime("%Y-%m-%d %H:%M UTC", time.gmtime(int(at) / 1000))
        return (f"the notebook {path} was edited again at {shown(edited_at)}, after the edit of {shown(agreed_at)} you agreed to "
                f"overwrite, so this version did not rebuild it: look at the new edit, then {IMPLEMENT_REBUILD_ACTION} to overwrite it, "
                "or keep it and change only the outputs or the schedule")
    return (f"the notebook {path} was edited after Inspire last built it, so this version did not rebuild it: {IMPLEMENT_REBUILD_ACTION} "
            "to overwrite those edits, or keep them and change only the outputs or the schedule")


IMPLEMENT_SPEC_SPACE = " \t\n\v\f\r\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000\ufeff"
IMPLEMENT_SAFE_WHOLE = 2 ** 53 - 1


def _implement_plain_table(name) -> str:
    return ".".join(part.strip(IMPLEMENT_SPEC_SPACE).strip("`") for part in str(name or "").split("."))


def _implement_js_number(value) -> str:
    try:
        number = float(value)
    except OverflowError:
        return "null"
    if number != number or number in (float("inf"), float("-inf")):
        return "null"
    if number == 0:
        return "0"
    _, digits, exponent = decimal.Decimal(repr(abs(number))).normalize().as_tuple()
    text, point = "".join(map(str, digits)), len(digits) + exponent
    if len(text) <= point <= 21:
        shown = text + "0" * (point - len(text))
    elif 0 < point <= 21:
        shown = f"{text[:point]}.{text[point:]}"
    elif -6 < point <= 0:
        shown = "0." + "0" * -point + text
    else:
        shown = text[0] + (f".{text[1:]}" if len(text) > 1 else "") + f"e{'+' if point > 0 else '-'}{abs(point - 1)}"
    return ("-" if number < 0 else "") + shown


def _implement_json_text(value) -> str:
    if value is None or isinstance(value, bool):
        return json.dumps(value)
    if isinstance(value, (int, float)):
        return _implement_js_number(value)
    if isinstance(value, (list, tuple)):
        return "[" + ",".join(_implement_json_text(v) for v in value) + "]"
    if isinstance(value, dict):
        items = sorted(((str(k), v) for k, v in value.items()), key=lambda kv: kv[0].encode("utf-16-be", "surrogatepass"))
        return "{" + ",".join(f"{json.dumps(k, ensure_ascii=False)}:{_implement_json_text(v)}" for k, v in items) + "}"
    return json.dumps(str(value), ensure_ascii=False)


def _implement_shown(value) -> str:
    return f"'{value}'" if isinstance(value, str) else _implement_json_text(value)


def _implement_text_value(value):
    if value is None:
        return ""
    return value.strip(IMPLEMENT_SPEC_SPACE) if isinstance(value, str) else None


def _implement_text(value, field: str, errors: list) -> str:
    text = _implement_text_value(value)
    if text is None:
        errors.append(f"{field} must be text, not {_implement_shown(value)}")
        return ""
    return text


def _implement_table_text(value):
    text = _implement_text_value(value)
    return None if text is None else _implement_plain_table(text)


def _implement_flag(value, field: str, errors: list, default: bool = False) -> bool:
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    errors.append(f"{field} must be true or false, not {_implement_shown(value)}")
    return default


def _implement_value_text(value):
    if isinstance(value, str):
        return value
    whole = implement_whole_number(value) if isinstance(value, (int, float)) else None
    return None if whole is None else str(whole)


def _implement_list(value, field: str, errors: list) -> list:
    if value is None or value == "":
        return []
    if isinstance(value, list):
        return value
    errors.append(f"{field} must be a list")
    return []


def _implement_mapping(value, field: str, errors: list) -> dict:
    if value is None or value == "":
        return {}
    if isinstance(value, dict):
        return value
    errors.append(f"{field} must be an object")
    return {}


_IMPLEMENT_DECIMAL_RE = re.compile(rf"[{IMPLEMENT_SPEC_SPACE}]*[-+]?([0-9]+(\.[0-9]*)?|\.[0-9]+)([eE][-+]?[0-9]+)?[{IMPLEMENT_SPEC_SPACE}]*")
_IMPLEMENT_WHOLE_RE = re.compile(rf"[{IMPLEMENT_SPEC_SPACE}]*[-+]?[0-9]+[{IMPLEMENT_SPEC_SPACE}]*")


def implement_whole_number(value):
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        number = value
    elif isinstance(value, float):
        number = int(value) if value.is_integer() else None
    else:
        text = value if isinstance(value, str) else ""
        number = int(text.strip(IMPLEMENT_SPEC_SPACE)) if _IMPLEMENT_WHOLE_RE.fullmatch(text) else None
    return number if number is not None and abs(number) <= IMPLEMENT_SAFE_WHOLE else None


def implement_decimal(value):
    if isinstance(value, bool):
        return None
    try:
        if isinstance(value, (int, float)):
            number = float(value)
        elif isinstance(value, str) and _IMPLEMENT_DECIMAL_RE.fullmatch(value):
            number = float(value.strip(IMPLEMENT_SPEC_SPACE))
        else:
            return None
    except OverflowError:
        return None
    return number if number == number and number not in (float("inf"), float("-inf")) else None


_IMPLEMENT_CRON_FIELDS = (("second", 0, 59, ()), ("minute", 0, 59, ()), ("hour", 0, 23, ()), ("day of month", 1, 31, ()),
                          ("month", 1, 12, ("JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC")),
                          ("day of week", 1, 7, ("SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT")), ("year", 1970, 2099, ()))


def _implement_cron_value_problem(part: str, label: str, low: int, high: int, names: tuple) -> str:
    if part in names or (re.fullmatch(r"[0-9]+", part) and low <= int(part) <= high):
        return ""
    return f"the {label} value '{part}' is not {low} to {high}" + (f" or {names[0]} to {names[-1]}" if names else "")


def implement_cron_problem(cron) -> str:
    fields = [part for part in re.split(f"[{IMPLEMENT_SPEC_SPACE}]+", str(cron or "").upper()) if part]
    if len(fields) not in (6, 7):
        return (f"it has {inspire_plural(len(fields), 'field')}; a Quartz cron has 6 or 7: second, minute, hour, day of month, month, day of week "
                "and an optional year")
    for text, (label, low, high, names) in zip(fields, _IMPLEMENT_CRON_FIELDS):
        if text == "?" and label in ("day of month", "day of week"):
            continue
        last = re.fullmatch(r"L(?:-([0-9]+))?|LW|([0-9]+)W", text) if label == "day of month" else None
        if last:
            if last.group(1) is not None and not 1 <= int(last.group(1)) <= 30:
                return f"the day of month offset '{last.group(1)}' is not 1 to 30"
            if last.group(2) is not None:
                problem = _implement_cron_value_problem(last.group(2), label, low, high, names)
                if problem:
                    return problem
            continue
        nth = re.fullmatch(r"L|([0-9]+|[A-Z]+)(?:L|#([0-9]+))", text) if label == "day of week" else None
        if nth:
            problem = _implement_cron_value_problem(nth.group(1), label, low, high, names) if nth.group(1) else ""
            if problem:
                return problem
            if nth.group(2) is not None and not 1 <= int(nth.group(2)) <= 5:
                return f"the day of week occurrence '{nth.group(2)}' is not 1 to 5"
            continue
        for item in text.split(","):
            base, slash, step = item.partition("/")
            top = 129 if label == "year" else high
            if slash and not (re.fullmatch(r"[0-9]+", step) and 1 <= int(step) <= top):
                return f"the {label} step '{step}' is not 1 to {top}"
            if base == "*":
                continue
            start, dash, end = base.partition("-")
            for part in (start, end) if dash else (start,):
                problem = _implement_cron_value_problem(part, label, low, high, names)
                if problem:
                    return problem
    if (fields[3] == "?") == (fields[5] == "?"):
        return "exactly one of day of month and day of week must be '?'"
    return ""


_IMPLEMENT_EMAIL_RE = re.compile(rf"[^@{IMPLEMENT_SPEC_SPACE}]+@[^@{IMPLEMENT_SPEC_SPACE}]+\.[^@{IMPLEMENT_SPEC_SPACE}]+")
_IMPLEMENT_ROLE_REF_RE = re.compile(rf"[^.{IMPLEMENT_SPEC_SPACE}`]+(\.[^.{IMPLEMENT_SPEC_SPACE}`]+){{3}}")
_IMPLEMENT_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


def _implement_texts(values, field: str, errors: list) -> list:
    texts = (_implement_text(item, f"each item of {field}", errors) for item in _implement_list(values, field, errors))
    return [text for text in texts if text]


def implement_holdout_setting(raw, errors: list) -> dict:
    holdout = _implement_mapping(raw, "holdout", errors)
    given = holdout.get("share")
    share = IMPLEMENT_HOLDOUT_SHARE if given is None or given == "" else implement_decimal(given)
    if share is None or not 0 < share <= INSPIRE_HOLDOUT_MAX_SHARE:
        errors.append(f"holdout share {_implement_shown(given)} must be a share above 0 and at most {INSPIRE_HOLDOUT_MAX_SHARE}, such as "
                      f"{IMPLEMENT_HOLDOUT_SHARE} for {int(IMPLEMENT_HOLDOUT_SHARE * 100)}% of the records")
        share = IMPLEMENT_HOLDOUT_SHARE
    return {"enabled": _implement_flag(holdout.get("enabled"), "holdout.enabled", errors), "share": float(share)}


def implement_holdout_share(holdout) -> float:
    holdout = holdout if isinstance(holdout, dict) else {}
    return float(holdout.get("share") or 0) if holdout.get("enabled") is True else 0.0


def implement_capacity_setting(raw, errors: list) -> dict:
    capacity = _implement_mapping(raw, "capacity", errors)
    given, limit = capacity.get("act_now"), None
    if given is not None and given != "":
        limit = implement_whole_number(given)
        if limit is None or not 1 <= limit <= IMPLEMENT_CAPACITY_MAX:
            errors.append(f"capacity act_now {_implement_shown(given)} must be a whole number of rows from 1 to {IMPLEMENT_CAPACITY_MAX}, "
                          "or empty for no cap")
            limit = None
    source = _implement_text_value(capacity.get("source"))
    source = (source or IMPLEMENT_CAPACITY_SOURCES[0]).lower() if source is not None else None
    if source not in IMPLEMENT_CAPACITY_SOURCES:
        errors.append(f"capacity source {_implement_shown(capacity.get('source'))} must be one of {', '.join(IMPLEMENT_CAPACITY_SOURCES)}")
        source = IMPLEMENT_CAPACITY_SOURCES[0]
    return {"act_now": limit, "source": source}


def implement_act_now_capacity(capacity):
    value = (capacity if isinstance(capacity, dict) else {}).get("act_now")
    return value if isinstance(value, int) and not isinstance(value, bool) and value >= 1 else None


def validate_implement_spec(spec, impact=None) -> tuple:
    errors = []
    if isinstance(spec, str):
        try:
            spec = json.loads(spec)
        except ValueError as e:
            return {}, [f"the spec is not valid JSON: {redact_error(e)}"]
    if not isinstance(spec, dict):
        return {}, ["the spec must be a JSON object"]
    out = {"use_case_id": _implement_text(spec.get("use_case_id"), "use_case_id", errors),
           "use_case_name": _implement_text(spec.get("use_case_name"), "use_case_name", errors),
           "confirm_notebook_overwrite": _implement_flag(spec.get("confirm_notebook_overwrite"), "confirm_notebook_overwrite", errors)}
    if _implement_text_value(spec.get("use_case_id")) == "":
        errors.append("use_case_id is required")
    based_on = spec.get("based_on_version")
    if based_on not in (None, ""):
        if implement_whole_number(based_on) is None:
            errors.append(f"based_on_version {_implement_shown(based_on)} must be an integer")
        else:
            out["based_on_version"] = implement_whole_number(based_on)
    framing = _implement_mapping(spec.get("use_case"), "use_case", errors)
    measures = _implement_texts(framing.get("success_measures"), "use_case.success_measures", errors)
    if len(measures) > 3:
        errors.append("at most 3 success measures are allowed")
    out["use_case"] = {"goal": _implement_text(framing.get("goal"), "use_case.goal", errors)[:500],
                       "decision_owner": _implement_text(framing.get("decision_owner"), "use_case.decision_owner", errors)[:200],
                       "success_measures": measures[:3]}
    data = _implement_mapping(spec.get("data"), "data", errors)
    tables = {}
    for original, chosen in _implement_mapping(data.get("tables"), "data.tables", errors).items():
        o, c = _implement_table_text(original), _implement_table_text(chosen)
        if o is None or c is None or not IMPLEMENT_TABLE_NAME_RE.fullmatch(o) or not IMPLEMENT_TABLE_NAME_RE.fullmatch(c):
            errors.append(f"table swap {_implement_shown(original)} -> {_implement_shown(chosen)} must name two catalog.schema.table tables")
            continue
        if o.lower() != c.lower():
            tables[o] = c
    filters = []
    for item in _implement_list(data.get("filters"), "data.filters", errors):
        if not isinstance(item, dict):
            errors.append("each data filter must be an object")
            continue
        table, column, op = _implement_table_text(item.get("table")), _implement_text_value(item.get("column")), _implement_text_value(item.get("op"))
        op = None if op is None else op.lower()
        raw_values = item.get("values")
        raw_values = raw_values if isinstance(raw_values, list) else ([] if raw_values is None or raw_values == "" else [raw_values])
        values = [_implement_value_text(v) for v in raw_values]
        bad = [raw for raw, value in zip(raw_values, values) if value is None]
        if (table is None or column is None or not IMPLEMENT_TABLE_NAME_RE.fullmatch(table)
                or not IMPLEMENT_WIDGET_NAME_RE.fullmatch(column.replace("-", "_"))):
            errors.append(f"filter on {_implement_shown(item.get('table'))}.{_implement_shown(item.get('column'))} must name a "
                          "catalog.schema.table table and a column")
        elif op not in IMPLEMENT_FILTER_OPS:
            errors.append(f"filter operator {_implement_shown(item.get('op'))} is not one of {', '.join(IMPLEMENT_FILTER_OPS)}")
        elif bad:
            errors.append(f"filter {table}.{column} value {_implement_shown(bad[0])} must be text or a whole number")
        elif not values or (op == "between" and len(values) != 2) or (op in ("=", "!=", ">", ">=", "<", "<=") and len(values) != 1):
            errors.append(f"filter {table}.{column} {op} needs " + ("two values" if op == "between" else "one value" if op not in ("in", "not in") else "at least one value"))
        else:
            filters.append({"table": table, "column": column, "op": op, "values": values})
    profile = _implement_text_value(data.get("run_profile"))
    profile = "" if profile is None else (profile or "preview").lower()
    if profile not in IMPLEMENT_RUN_PROFILES:
        errors.append(f"run_profile must be one of {', '.join(IMPLEMENT_RUN_PROFILES)}")
    roles = {}
    for role, raw in _implement_mapping(data.get("column_roles"), "data.column_roles", errors).items():
        ref = _implement_text_value(raw)
        ref = None if ref is None else ref.strip("`")
        if role not in IMPLEMENT_COLUMN_ROLES:
            errors.append(f"column role {_implement_shown(role)} is not one of {', '.join(IMPLEMENT_COLUMN_ROLES)}")
        elif ref is None or (ref and not _IMPLEMENT_ROLE_REF_RE.fullmatch(ref)):
            errors.append(f"column role {role} must name catalog.schema.table.column, not {_implement_shown(raw if ref is None else ref)}")
        elif ref:
            roles[role] = ref
    removed_tables = []
    for raw in _implement_list(data.get("removed_tables"), "data.removed_tables", errors):
        table = _implement_table_text(raw)
        if table is None or not IMPLEMENT_TABLE_NAME_RE.fullmatch(table):
            errors.append(f"removed table {_implement_shown(raw)} must be catalog.schema.table")
        elif any(table.lower() == o.lower() for o in tables):
            errors.append(f"{table} cannot be swapped and removed at once")
        elif table.lower() not in [r.lower() for r in removed_tables]:
            removed_tables.append(table)
    gone = {r.lower() for r in removed_tables}
    for role, ref in sorted(roles.items()):
        if ".".join(ref.split(".")[:3]).lower() in gone:
            errors.append(f"the {role.replace('_', ' ')} column {ref} is in a table you removed")
    for item in filters:
        if item["table"].lower() in gone:
            errors.append(f"the filter on {item['table']}.{item['column']} reads a table you removed")
    window = _implement_mapping(data.get("window"), "data.window", errors)
    dates = {}
    for label in ("start", "end"):
        raw = window.get(label)
        value = _implement_text_value(raw)
        if value is None or (value and not _IMPLEMENT_DATE_RE.fullmatch(value)):
            errors.append(f"the data window {label} {_implement_shown(raw if value is None else value)} must be a YYYY-MM-DD date")
        dates[label] = value or ""
    start, end = dates["start"], dates["end"]
    if start and end and _IMPLEMENT_DATE_RE.fullmatch(start) and _IMPLEMENT_DATE_RE.fullmatch(end) and start > end:
        errors.append(f"the data window starts ({start}) after it ends ({end})")
    out["data"] = {"tables": tables, "removed_tables": removed_tables, "filters": filters, "run_profile": profile, "column_roles": roles,
                   "window": {"start": start, "end": end},
                   "notes": _implement_vibes_text(data.get("notes"), "data.notes", IMPLEMENT_NOTEBOOK_LABEL, errors)}
    # REQ-389: the Table Scope the person chose on the Data step, the scope this build reads. Absent: the session's Table Scope stays.
    chosen_scope = data.get("table_scope")
    if chosen_scope is not None:
        if not isinstance(chosen_scope, dict):
            errors.append("table scope must be an object keyed by catalog.schema.table")
        else:
            try:
                parse_table_scopes(json.dumps(chosen_scope))
            except ValueError as error:
                errors.append(f"table scope: {redact_error(error, max_chars=200)}")
            else:
                out["data"]["table_scope"] = chosen_scope
    config = _implement_mapping(spec.get("config"), "config", errors)
    widgets = {}
    for name, value in _implement_mapping(config.get("widgets"), "config.widgets", errors).items():
        text = "" if value is None else _implement_value_text(value)
        if not IMPLEMENT_WIDGET_NAME_RE.fullmatch(str(name)):
            errors.append(f"widget name {_implement_shown(name)} is not a valid widget name")
        elif text is None:
            errors.append(f"widget {name} must be text or a whole number, not {_implement_shown(value)}")
        else:
            widgets[str(name)] = text
    assumptions = {}
    for name, value in _implement_mapping(config.get("assumptions"), "config.assumptions", errors).items():
        number = implement_decimal(value)
        if not IMPLEMENT_ASSUMPTION_NAME_RE.fullmatch(str(name)):
            errors.append(f"assumption name {_implement_shown(name)} is not a valid constant name")
        elif number is None or not _inspire_math.isfinite(number) or abs(number) >= IMPLEMENT_ASSUMPTION_LIMIT:
            errors.append(f"assumption {name} must be a number, not {_implement_shown(value)}")
        else:
            assumptions[str(name)] = number
    settings_note = _implement_text(config.get("settings_note"), "config.settings_note", errors)
    if len(settings_note) > IMPLEMENT_SETTINGS_NOTE_CHARS:
        errors.append(f"config.settings_note must be at most {implement_number_text(IMPLEMENT_SETTINGS_NOTE_CHARS)} characters, not {implement_number_text(len(settings_note))}")
        settings_note = ""
    raw_table = config.get("result_table")
    result_table = _implement_table_text(raw_table)
    if result_table is None or (result_table and not IMPLEMENT_TABLE_NAME_RE.fullmatch(result_table)):
        errors.append(f"result_table {_implement_shown(raw_table)} must be catalog.schema.table")
    profiles_in = _implement_mapping(config.get("profiles"), "config.profiles", errors)
    profiles = {}
    for name, fields in (("training", ("window_days", "sample_entities")), ("full_load", ("window_days",)),
                         ("preview", ("entity_cap",)), ("retrain", ("every_runs",))):
        section = _implement_mapping(profiles_in.get(name), f"config.profiles.{name}", errors)
        clean = {}
        for field in fields:
            value = section.get(field)
            if value is None or value == "":
                continue
            number = implement_whole_number(value)
            if number is None:
                errors.append(f"{name} {field} {_implement_shown(value)} must be a whole number")
            elif number < 1:
                errors.append(f"{name} {field} must be at least 1")
            else:
                clean[field] = number
        if name == "training":
            stratify = _implement_text(section.get("stratify_by"), "config.profiles.training.stratify_by", errors)
            if stratify:
                clean["stratify_by"] = stratify
        drift = section.get("drift_threshold")
        if name == "retrain" and drift is not None and drift != "":
            number = implement_decimal(drift)
            if number is None or not 0 < number <= 1:
                errors.append(f"retrain drift_threshold {_implement_shown(drift)} must be a number above 0 and at most 1")
            else:
                clean["drift_threshold"] = number
        profiles[name] = clean
    out["config"] = {"widgets": widgets, "assumptions": assumptions, "settings_note": settings_note, "result_table": result_table or "",
                     "ai_endpoint": _implement_text(config.get("ai_endpoint"), "config.ai_endpoint", errors),
                     "warehouse_id": _implement_text(config.get("warehouse_id"), "config.warehouse_id", errors), "profiles": profiles}
    schedule = _implement_mapping(spec.get("schedule"), "schedule", errors)
    cron = _implement_text(schedule.get("cron"), "schedule.cron", errors)
    enabled = _implement_flag(schedule.get("enabled"), "schedule.enabled", errors)
    cron_problem = implement_cron_problem(cron) if cron else ""
    if cron_problem:
        errors.append(f"schedule cron {_implement_shown(cron)} is not a valid Quartz cron: {cron_problem}")
    if enabled and not cron and _implement_text_value(schedule.get("cron")) is not None:
        errors.append("an enabled schedule needs a cron expression")
    emails = []
    for raw in _implement_list(schedule.get("failure_emails"), "schedule.failure_emails", errors):
        email = _implement_text_value(raw)
        if email is None or not _IMPLEMENT_EMAIL_RE.fullmatch(email):
            errors.append(f"failure email {_implement_shown(raw if email is None else email)} is not an email address")
        elif email.lower() not in [e.lower() for e in emails]:
            emails.append(email)
    out["schedule"] = {"enabled": enabled, "cron": cron, "timezone": _implement_text(schedule.get("timezone"), "schedule.timezone", errors) or "UTC",
                       "failure_emails": emails}
    if spec.get("holdout") is not None:
        out["holdout"] = implement_holdout_setting(spec["holdout"], errors)
    if spec.get("kpi") is not None:
        out["kpi"] = {"target": _implement_text(_implement_mapping(spec["kpi"], "kpi", errors).get("target"), "kpi.target", errors)[:200]}
    if spec.get("capacity") is not None:
        out["capacity"] = implement_capacity_setting(spec["capacity"], errors)
    outputs = _implement_mapping(spec.get("outputs"), "outputs", errors)
    chosen = {name: _implement_flag(outputs.get(name), f"outputs.{name}", errors) for name in IMPLEMENT_OUTPUTS}
    if "outputs" not in spec:
        chosen["dashboard"] = True
    notebook_only = _implement_flag(outputs.get("notebook"), "outputs.notebook", errors)
    if notebook_only and any(chosen.values()):
        errors.append(f"the {IMPLEMENT_OUTPUT_LABELS['notebook']} is written on its own: untick the other outputs or the {IMPLEMENT_OUTPUT_LABELS['notebook']}")
    merge, merge_errors = _implement_merge_targets(outputs, chosen)
    errors += merge_errors
    hosted = chosen["app"] and (_implement_text_value(outputs.get("app_placement")) or "").lower() == IMPLEMENT_APP_HOSTED
    app_name = "" if hosted else merge["app"] or (_implement_text_value(outputs.get("app_name")) or "").lower()
    if chosen["app"] and not hosted and not IMPLEMENT_APP_NAME_RE.fullmatch(app_name):
        errors.append(f"app_name {_implement_shown(outputs.get('app_name'))} must be 3-30 characters: lowercase letters, digits and dashes, "
                      "starting with a letter")
    if any(chosen.values()) and not out["config"]["warehouse_id"] and _implement_text_value(config.get("warehouse_id")) is not None:
        errors.append("a SQL warehouse is required to build a dashboard, a Genie Agent, an App or an alert")
    alert, alert_errors = _implement_alert_options(outputs, chosen["alert"])
    errors += alert_errors
    based = spec.get("based_on_version") not in (None, "")
    app_choices, app_errors = implement_app_choices(outputs, IMPLEMENT_APP_EXPERIENCE_CLASSIC if based else IMPLEMENT_APP_EXPERIENCE_DEFAULT) if chosen["app"] else ({"app_access": "", "app_look": {}, "app_options": {},
                                                                                    "app_backend": "", "app_charts": [],
                                                                                    "app_pages": {}, "app_placement": ""}, [])
    errors += app_errors
    removed = {}
    for name, action in _implement_mapping(spec.get("removed_outputs"), "removed_outputs", errors).items():
        action = _implement_text_value(action)
        if name in IMPLEMENT_OUTPUTS and action is not None and action.lower() in ("keep", "delete"):
            removed[name] = action.lower()
    questions = [q[:300] for q in _implement_texts(outputs.get("genie_questions"), "outputs.genie_questions", errors)]
    if len(questions) > 5:
        errors.append("at most 5 Genie Agent sample questions are allowed")
    filters_out = _implement_texts(outputs.get("dashboard_filters"), "outputs.dashboard_filters", errors)
    bad_filters = [w for w in filters_out if not IMPLEMENT_WIDGET_NAME_RE.fullmatch(w)]
    if bad_filters:
        errors.append(f"dashboard filters must be widget names: {', '.join(bad_filters)}")
    out["outputs"] = dict(chosen, app_name=app_name if chosen["app"] else "",
                          dashboard_name=_implement_text(outputs.get("dashboard_name"), "outputs.dashboard_name", errors)[:200]
                          if chosen["dashboard"] else "",
                          dashboard_filters=filters_out if chosen["dashboard"] else [],
                          genie_space_name=_implement_text(outputs.get("genie_space_name"), "outputs.genie_space_name", errors)[:200]
                          if chosen["genie_space"] else "",
                          genie_questions=questions[:5] if chosen["genie_space"] else [],
                          app_purpose=_implement_text(outputs.get("app_purpose"), "outputs.app_purpose", errors)[:1500] if chosen["app"] else "",
                          app_owners=_implement_app_owners(outputs, chosen["app"], errors, impact),
                          app_warehouse_id=_implement_app_warehouse_id(outputs, chosen["app"], errors),
                          inspire_url=implement_inspire_url(outputs, chosen["app"] or chosen["dashboard"], errors),
                          **({"notebook": True} if notebook_only else {}), **alert, merge=merge, **app_choices, **_implement_vibes(outputs, chosen, errors),
                          **_implement_asset_vibes(outputs, chosen, errors, impact))
    errors += implement_app_hosted_problems(out["outputs"], outputs)
    out["removed_outputs"] = removed
    retry = []
    for raw in _implement_list(spec.get("retry_outputs"), "retry_outputs", errors):
        name = _implement_text_value(raw)
        part = implement_part(name) if name is not None else None
        if part:
            if part[0] != IMPLEMENT_NOTEBOOK and not chosen[part[0]]:
                errors.append(f"the {part[1]} cannot be rebuilt: the {IMPLEMENT_OUTPUT_LABELS[part[0]]} is not selected")
            elif name not in retry:
                retry.append(name)
        elif name not in IMPLEMENT_RETRY_TARGETS:
            errors.append(f"retry output {_implement_shown(raw if name is None else name)} is not one of {', '.join(IMPLEMENT_RETRY_TARGETS)}")
        elif name != IMPLEMENT_NOTEBOOK and not chosen[name]:
            errors.append(f"the {IMPLEMENT_OUTPUT_LABELS[name]} cannot be retried: it is not selected")
        elif name not in retry:
            retry.append(name)
    out["retry_outputs"] = retry
    retry_asks = {}
    for asset, listed in _implement_mapping(spec.get("retry_asks"), "retry_asks", errors).items():
        before = len(errors)
        asks = _implement_texts(listed, f"retry_asks.{asset}", errors)
        label = (implement_part(asset, impact) or (None, IMPLEMENT_OUTPUT_LABELS.get(asset, asset)))[1]
        if asset not in retry:
            errors.append(f"retry_asks names {_implement_shown(asset)}, which this version does not rebuild; list it in retry_outputs too")
        elif len(errors) > before:
            continue
        elif not asks:
            errors.append(f"retry_asks.{asset} must list at least one ask to try again")
        elif any(len(ask) > IMPLEMENT_VIBES_MAX_CHARS for ask in asks):
            errors.append(f"each ask to try again on the {label} must be at most {implement_number_text(IMPLEMENT_VIBES_MAX_CHARS)} characters")
        else:
            retry_asks[asset] = asks
    if retry_asks:
        out["retry_asks"] = retry_asks
    rollback = {}
    for name, value in _implement_mapping(spec.get("rollback_outputs"), "rollback_outputs", errors).items():
        version = implement_whole_number(value)
        if name not in IMPLEMENT_OUTPUTS:
            errors.append(f"rollback output {_implement_shown(name)} is not one of {', '.join(IMPLEMENT_OUTPUTS)}")
        elif not chosen[name]:
            errors.append(f"the {IMPLEMENT_OUTPUT_LABELS[name]} cannot be rolled back: it is not selected")
        elif version is None or version < 1:
            errors.append(f"rollback_outputs.{name} {_implement_shown(value)} must be a version number, 1 or more")
        elif any(implement_asset_owner(r) == name for r in retry):
            errors.append(f"the {IMPLEMENT_OUTPUT_LABELS[name]} cannot be retried and rolled back in the same version")
        else:
            rollback[name] = version
    out["rollback_outputs"] = {name: rollback[name] for name in IMPLEMENT_OUTPUTS if name in rollback}
    vibe = _implement_vibes_text(spec.get("vibes"), "vibes", "MVP", errors) if spec.get("vibes") is not None else ""
    previous_text = _implement_text_value(spec.get("vibe_previous"))
    previous_choice = (previous_text or "").lower()
    if vibe.strip() and previous_text != "" and previous_choice not in IMPLEMENT_VIBE_PREVIOUS:
        errors.append(f"vibe_previous {_implement_shown(spec.get('vibe_previous'))} must be keep or remove: it says what happens to the "
                      "version before this vibe")
    elif vibe.strip():
        out.update(vibes=vibe, **({"vibe_previous": previous_choice} if previous_choice else {}))
        if out["rollback_outputs"]:
            errors.append("a vibe and a roll back cannot run in the same version")
    elif previous_choice:
        errors.append("vibe_previous needs vibes: it says what happens to the version before a vibe")
    kept_versions = []
    for raw in _implement_list(spec.get("remove_kept"), "remove_kept", errors):
        version = implement_whole_number(raw)
        if version is None or version < 1:
            errors.append(f"remove_kept {_implement_shown(raw)} must be a version number, 1 or more")
        elif version not in kept_versions:
            kept_versions.append(version)
    if kept_versions:
        out["remove_kept"] = kept_versions
    if _implement_flag(spec.get("uninstall"), "uninstall", errors):
        out["uninstall"] = True
        if out.get("vibes") or retry or out["rollback_outputs"] or kept_versions:
            errors.append("Uninstall All removes everything this use case built, so it cannot also rebuild, vibe, roll back or remove a "
                          "kept version in the same version")
    sharing = _implement_mapping(spec.get("sharing"), "sharing", errors)
    principals, seen = [], set()
    for item in _implement_list(sharing.get("principals"), "sharing.principals", errors):
        entry = item if isinstance(item, dict) else {}
        kind, name = _implement_text_value(entry.get("type")), _implement_text_value(entry.get("name"))
        kind = None if kind is None else kind.lower()
        if kind not in IMPLEMENT_PRINCIPAL_TYPES or not name:
            errors.append(f"principal {_implement_shown(item)} must have a type ({', '.join(IMPLEMENT_PRINCIPAL_TYPES)}) and a name")
        elif (kind, name.lower()) not in seen:
            seen.add((kind, name.lower()))
            principals.append({"type": kind, "name": name})
    out["sharing"] = {"principals": principals}
    return out, errors


def _implement_vibes_text(raw, field: str, label: str, errors: list) -> str:
    text = _implement_text(raw, field, errors)
    if len(text) > IMPLEMENT_VIBES_MAX_CHARS:
        errors.append(f"the {label} vibes are {inspire_plural(len(text), 'character')}; at most {implement_number_text(IMPLEMENT_VIBES_MAX_CHARS)} are allowed")
    return text


def _implement_vibes(outputs: dict, chosen: dict, errors: list) -> dict:
    return {f"{name}_vibes": _implement_vibes_text(outputs.get(f"{name}_vibes") if chosen[name] else None, f"outputs.{name}_vibes",
                                                   IMPLEMENT_OUTPUT_LABELS[name], errors) for name in IMPLEMENT_OUTPUTS}


def implement_part_what(asset: str, impact=None) -> str:
    return IMPLEMENT_PART_WHAT[asset].format(stake=inspire_stake_words(impact))


def implement_use_case_impact(use_case, target_kpi=None) -> dict:
    use_case = use_case if isinstance(use_case, dict) else {}
    return use_case.get("_implement_impact") or implement_record_impact(
        target_kpi or use_case.get("_implement_target_kpi") or implement_inspire_target_kpi(use_case))


def implement_notebook_impact(asset_status):
    notebook = asset_status.get(IMPLEMENT_NOTEBOOK) if isinstance(asset_status, dict) else None
    return notebook.get("impact") if isinstance(notebook, dict) else None


def implement_part(asset, impact=None) -> tuple:
    text = str(asset if asset is not None else "")
    if text in IMPLEMENT_ASSET_LABELS:
        return IMPLEMENT_NOTEBOOK, IMPLEMENT_ASSET_LABELS[text].format(stake=inspire_stake_words(impact))
    match = IMPLEMENT_PART_RE.fullmatch(text)
    if not match:
        return None
    return ("app", f"App page {match.group(2)}") if match.group(1) == "app:page" else ("dashboard", f"dashboard chart {match.group(2)}")


def implement_asset_owner(asset: str) -> str:
    return asset if asset in IMPLEMENT_OUTPUTS or asset == IMPLEMENT_NOTEBOOK else (implement_part(asset) or ("",))[0]


def implement_asset_entries(asset_status) -> list:
    status = asset_status if isinstance(asset_status, dict) else {}
    return [(name, entry) for name, entry in status.items() if name not in IMPLEMENT_STATUS_RECORDS and isinstance(entry, dict)]


def implement_notebook_only_spec(stored) -> bool:
    # REQ-578: a version whose only output is the Genie code notebook builds nothing else, so it is no built version to diff against.
    outputs = (implement_stored_spec(stored) or {}).get("outputs") if stored else None
    return isinstance(outputs, dict) and outputs.get("notebook") is True


def implement_asset_label(asset: str, impact=None) -> str:
    if asset in IMPLEMENT_OUTPUT_LABELS and asset != IMPLEMENT_NOTEBOOK:
        return IMPLEMENT_OUTPUT_LABELS[asset]
    return IMPLEMENT_NOTEBOOK_LABEL if asset == IMPLEMENT_NOTEBOOK else implement_part(asset, impact)[1]


def implement_asset_titles(asset_status) -> dict:
    # REQ-237 / D-NAMES: the person name of each built App page and chart, from the part record the build wrote.
    return {asset: " ".join(str(entry.get("title") or "").split()) for asset, entry in (asset_status or {}).items()
            if isinstance(entry, dict) and implement_part(asset)}


def implement_person_label(asset: str, impact=None, titles=None) -> str:
    # REQ-237 / D-NAMES: person copy names an App page or chart by its title, or by its kind when it has none. Never by its id.
    match = IMPLEMENT_PART_RE.fullmatch(str(asset or ""))
    if not match:
        return implement_asset_label(asset, impact)
    kind = "App page" if match.group(1) == "app:page" else "dashboard chart"
    title = " ".join(str((titles or {}).get(asset) or "").split())
    return f"{kind} {title}" if title else kind


def implement_asset_title_label(asset: str, artifact=None, impact=None) -> str:
    # REQ-237 / D-NAMES: person copy names an App page or a chart by its title. The internal id stays in Genie-facing and diagnostic text.
    label = implement_asset_label(asset, impact)
    match = IMPLEMENT_PART_RE.fullmatch(str(asset or ""))
    if not match or not isinstance(artifact, dict):
        return label
    ident = match.group(2)
    if match.group(1) == "app:page":
        if str(artifact.get("id")) != ident:
            return label
        name = inspire_shell_facts.page_names([artifact])[ident]
        return "App " + (name[len("the "):] if name.startswith("the ") else name)
    charts = [c for c in artifact.get("charts") or [] if isinstance(c, dict)]
    if not any(str(c.get("id")) == ident for c in charts):
        return label
    name = inspire_shell_facts.chart_names({"charts": charts})[ident]
    return "dashboard " + (name[len("the "):] if name.startswith("the ") else name)


def _implement_asset_vibes(outputs: dict, chosen: dict, errors: list, impact=None) -> dict:
    out = {}
    for key, raw in outputs.items():
        part = implement_part(key[:-len("_vibes")], impact) if isinstance(key, str) and key.endswith("_vibes") else None
        if part is None or (part[0] != IMPLEMENT_NOTEBOOK and not chosen[part[0]]):
            continue
        if _implement_vibes_text(raw, f"outputs.{key}", part[1], errors):
            out[key] = raw
    return out


def implement_asset_vibes(outputs, owner: str = "") -> dict:
    found = {}
    for key, value in sorted((outputs or {}).items()):
        part = implement_part(key[:-len("_vibes")]) if isinstance(key, str) and key.endswith("_vibes") else None
        if part and isinstance(value, str) and value.strip() and (not owner or part[0] == owner):
            found[key[:-len("_vibes")]] = value
    return found


def implement_notebook_asks(spec: dict) -> dict:
    asks = implement_asset_vibes((spec or {}).get("outputs"), IMPLEMENT_NOTEBOOK)
    notes = str(((spec or {}).get("data") or {}).get("notes") or "")
    return dict({IMPLEMENT_NOTEBOOK: notes}, **asks) if notes.strip() else asks


def implement_asset_vibes_shown(outputs, owner: str = "") -> dict:
    return {asset: text.strip() for asset, text in implement_asset_vibes(outputs, owner).items()}


def implement_vibed_parts(previous_spec, spec) -> list:
    before = implement_asset_vibes_shown((previous_spec or {}).get("outputs"))
    after = implement_asset_vibes_shown(spec.get("outputs"))
    ticked, rolling = spec.get("outputs") or {}, set(spec.get("rollback_outputs") or {})
    return [a for a in dict.fromkeys(list(before) + list(after)) if (implement_part(a)[0] == IMPLEMENT_NOTEBOOK
                                                                     or ticked.get(implement_part(a)[0]))
            and implement_part(a)[0] not in rolling and before.get(a, "") != after.get(a, "")]


def implement_part_built(asset_status, asset) -> bool:
    entry = (asset_status or {}).get(asset)
    return isinstance(entry, dict) and entry.get("state") in IMPLEMENT_PART_STATES


def implement_with_vibed_parts(asset_status, previous_spec, spec) -> dict:
    retry = [str(r) for r in spec.get("retry_outputs") or []]
    added = [a for a in implement_vibed_parts(previous_spec, spec) if implement_part_built(asset_status, a) and a not in retry]
    return dict(spec, retry_outputs=retry + added) if added else spec


def implement_part_problems(asset_status, previous_spec, spec) -> list:
    retry = [r for r in spec.get("retry_outputs") or [] if implement_part(r)]
    problems = []
    for asset in dict.fromkeys(retry + implement_vibed_parts(previous_spec, spec)):
        if not implement_part_built(asset_status, asset):
            label = implement_part(asset, implement_notebook_impact(asset_status))[1]
            problems.append(f"Inspire has not built the {label} on this MVP, so it cannot rebuild it with your vibes; pick one "
                            "this MVP built")
    return problems


def implement_output_title(context: dict, name: str, fields: dict) -> str:
    outputs = context["spec"]["outputs"]
    chosen = {"dashboard": outputs.get("dashboard_name"), "genie_space": outputs.get("genie_space_name"), "alert": outputs.get("alert_name"),
              "app": fields.get("app_name") or outputs.get("app_name")}[name]
    return " ".join(str(chosen or f"{context['uc_id']} {(context.get('use_case') or {}).get('Name') or ''}").split())[:250]


def implement_vibed_assets(outputs, name: str) -> dict:
    whole = implement_output_vibes(outputs, name) if name in IMPLEMENT_OUTPUTS else ""
    return dict(({name: whole} if whole else {}), **implement_asset_vibes(outputs, name))


def _implement_choice(outputs: dict, key: str, default: str, choices, separator: str, errors: list, lower: bool = False) -> str:
    raw = outputs.get(key)
    text = _implement_text_value(raw)
    if text is not None:
        text = (text.lower() if lower else text) or default
    if text is None or text not in choices:
        errors.append(f"{key} {_implement_shown(raw)} must be one of {separator.join(choices)}")
        return default
    return text


def _implement_alert_options(outputs: dict, on: bool) -> tuple:
    errors = []
    outputs = outputs if on else {}
    tiers = _implement_choice(outputs, "alert_tiers", "act_now", IMPLEMENT_ALERT_TIER_SETS, ", ", errors, lower=True)
    operator = _implement_choice(outputs, "alert_operator", ">=", IMPLEMENT_ALERT_OPERATORS, " ", errors)
    raw = outputs.get("alert_threshold")
    threshold = 1.0 if raw is None or raw == "" else implement_decimal(raw)
    if threshold is None or threshold < 0:
        errors.append(f"alert_threshold {_implement_shown(raw)} must be a number of rows, 0 or more")
        threshold = 1.0
    basis = _implement_choice(outputs, "alert_threshold_basis", "fixed", IMPLEMENT_ALERT_THRESHOLD_BASES, ", ", errors, lower=True)
    if basis == "baseline" and operator not in IMPLEMENT_ALERT_BASELINE_DIRECTIONS:
        errors.append(f"a baseline threshold fires on a rise or a fall against earlier runs, so alert_operator must be one of "
                      f"{' '.join(IMPLEMENT_ALERT_BASELINE_DIRECTIONS)}, not {_implement_shown(operator)}")
    recipients = []
    for raw_email in _implement_list(outputs.get("alert_recipients"), "outputs.alert_recipients", errors):
        email = _implement_text_value(raw_email)
        if email is None or not _IMPLEMENT_EMAIL_RE.fullmatch(email):
            errors.append(f"alert recipient {_implement_shown(raw_email if email is None else email)} is not an email address")
        elif email.lower() not in [e.lower() for e in recipients]:
            recipients.append(email)
    destinations, seen = [], set()
    for raw_item in _implement_list(outputs.get("alert_destinations"), "outputs.alert_destinations", errors):
        item = raw_item if isinstance(raw_item, dict) else {"id": raw_item}
        dest_id = _implement_text_value(item.get("id"))
        if dest_id is None or not re.fullmatch(r"[A-Za-z0-9-]{8,64}", dest_id):
            errors.append(f"alert destination {_implement_shown(raw_item)} needs the id of a workspace notification destination")
        elif dest_id not in seen:
            seen.add(dest_id)
            destinations.append({"id": dest_id, "name": _implement_text(item.get("name"), "the name of each alert destination", errors)[:200]})
    if on and not recipients and not destinations:
        errors.append("an alert needs at least one recipient email or notification destination")
    if len(recipients) + len(destinations) > IMPLEMENT_ALERT_MAX_SUBSCRIBERS:
        errors.append(f"an alert can notify at most {IMPLEMENT_ALERT_MAX_SUBSCRIBERS} recipients and destinations")
    return {"alert_name": _implement_text(outputs.get("alert_name"), "outputs.alert_name", errors)[:200] if on else "",
            "alert_tiers": tiers, "alert_operator": operator, "alert_threshold": threshold, "alert_threshold_basis": basis,
            "alert_condition_text": _implement_text(outputs.get("alert_condition_text"), "outputs.alert_condition_text", errors)[:500]
            if on else "",
            "alert_recipients": recipients, "alert_destinations": destinations,
            **({"alert_digest": _implement_flag(outputs["alert_digest"], "outputs.alert_digest", errors, True)}
               if "alert_digest" in outputs else {}),
            **({"alert_notify_on_ok": _implement_flag(outputs["alert_notify_on_ok"], "outputs.alert_notify_on_ok", errors, True)}
               if "alert_notify_on_ok" in outputs else {})}, errors


def implement_alert_digest(outputs) -> bool:
    return (outputs or {}).get("alert_digest") is not False


def implement_clears_wanted(value):
    return IMPLEMENT_CLEARS_WORDS.get(str(value or "").strip().lower())


def implement_alert_notify_on_ok(outputs, asks=()) -> bool:
    wanted = [implement_clears_wanted(c.get("value")) for a in asks or () for c in implement_vibes_checks_of(a) if c.get("kind") == "clears"]
    wanted = [w for w in wanted if w is not None]
    return wanted[-1] if wanted else (outputs or {}).get("alert_notify_on_ok") is not False


def _implement_app_owners(outputs: dict, on: bool, errors: list, impact=None) -> list:
    if not on:
        return []
    owners = []
    for raw in _implement_list(outputs.get("app_owners"), "outputs.app_owners", errors):
        email = _implement_text_value(raw)
        if (email is None or len(email.encode("utf-16-le", "surrogatepass")) // 2 > IMPLEMENT_EMAIL_MAX_CHARS
                or not _IMPLEMENT_EMAIL_RE.fullmatch(email)):
            errors.append(f"App owner {_implement_shown(raw if email is None else email)} is not an email address")
        elif email.lower() not in [o.lower() for o in owners]:
            owners.append(email)
    if len(owners) > IMPLEMENT_APP_OWNERS_MAX:
        errors.append(f"an App can name at most {IMPLEMENT_APP_OWNERS_MAX} owners, the people who may change its "
                      f"{inspire_stake_words(impact)} assumptions")
    return owners


def _implement_app_warehouse_id(outputs: dict, on: bool, errors: list) -> str:
    if not on:
        return ""
    raw = outputs.get("app_warehouse_id")
    text = _implement_text(raw, "outputs.app_warehouse_id", errors)
    if text and not IMPLEMENT_ASSET_ID_RE.fullmatch(text):
        errors.append(f"outputs.app_warehouse_id {_implement_shown(raw)} must be the id of a SQL warehouse: up to 64 letters, digits, "
                      "dashes and underscores, or empty for the SQL warehouse the build uses")
        return ""
    return text


def implement_app_hosted(outputs) -> bool:
    outputs = outputs if isinstance(outputs, dict) else {}
    return bool(outputs.get("app")) and outputs.get("app_placement") == IMPLEMENT_APP_HOSTED


def implement_app_hosted_problems(outputs: dict, raw: dict) -> list:
    if not implement_app_hosted(outputs):
        return []
    problems = []
    if outputs.get("app_backend") == IMPLEMENT_APP_BACKENDS[0]:
        problems.append(IMPLEMENT_APP_HOSTED_ERRORS["backend"])
    if implement_merge_target(outputs, "app"):
        problems.append(IMPLEMENT_APP_HOSTED_ERRORS["merge"])
    if not outputs.get("app_warehouse_id") and _implement_text_value((raw or {}).get("app_warehouse_id")) == "":
        problems.append(IMPLEMENT_APP_HOSTED_ERRORS["warehouse"])
    return problems


def implement_inspire_url(outputs: dict, needed: bool, errors: list) -> str:
    if not needed:
        return ""
    text = (_implement_text_value(outputs.get("inspire_url")) or "").lower()
    base = text[:-1] if text.endswith("/") else text
    if not IMPLEMENT_APP_HOSTED_URL_RE.fullmatch(base):
        errors.append(IMPLEMENT_APP_HOSTED_ERRORS["inspire_url"])
        return ""
    return base


def implement_app_moved(before: dict, after: dict) -> bool:
    return bool(before.get("app") and after.get("app")) and (before.get("app_name") != after.get("app_name")
                                                             or implement_app_hosted(before) != implement_app_hosted(after))


def implement_app_hosted_record(entry) -> dict:
    hosted = entry.get("hosted") if isinstance(entry, dict) and entry.get("placement") == IMPLEMENT_APP_HOSTED else None
    if not isinstance(hosted, dict) or not IMPLEMENT_APP_HOSTED_ID_RE.fullmatch(str(hosted.get("id") or "")):
        return {}
    return dict(hosted)


def implement_app_hosted_id(entry) -> str:
    return str(implement_app_hosted_record(entry).get("id") or "")


def implement_session_text(session_id) -> str:
    return session_id.strip() if isinstance(session_id, str) else inspire_session_id(session_id)


def implement_app_hosted_name(uc_id, session_id) -> str:
    plain = lambda text: re.sub(r"[^a-z0-9]+", "-", str(text if text is not None else "").lower()).strip("-")
    session = plain(implement_session_text(session_id))[:IMPLEMENT_APP_HOSTED_ID_CHARS].strip("-")
    room = IMPLEMENT_APP_HOSTED_ID_CHARS - (len(session) + 1 if session else 0)
    case = plain(uc_id)[:max(room, 0)].strip("-")
    name = "-".join(part for part in (case, session) if part)
    return name or hashlib.sha256(f"{uc_id}-{session_id}".encode()).hexdigest()[:12]


def implement_app_hosted_folder(hosted) -> str:
    hosted = hosted if isinstance(hosted, dict) else {}
    source = str(hosted.get("source") or "").rstrip("/")
    folder = os.path.dirname(source)
    if IMPLEMENT_APP_HOSTED_VERSION_RE.fullmatch(os.path.basename(source)) and os.path.basename(folder) == hosted.get("id"):
        return folder
    return ""


def implement_app_sync_pipeline(entry) -> str:
    return str(entry.get("sync_pipeline") or "") if isinstance(entry, dict) else ""


def implement_app_placed(settings: dict, outputs) -> dict:
    placed = {key: value for key, value in settings.items() if key != IMPLEMENT_APP_HOSTED_SETTING}
    return dict(placed, **{IMPLEMENT_APP_HOSTED_SETTING: IMPLEMENT_APP_HOSTED}) if implement_app_hosted(outputs) else placed


def implement_url_part(value) -> str:
    import urllib.parse
    return urllib.parse.quote(str(value), safe='')


def implement_link(base_url: str, **query) -> str:
    base = str(base_url or "").strip().rstrip("/")
    if not base:
        return ""
    parts = "&".join(f"{name}={implement_url_part(value)}" for name, value in query.items())
    return f"{base}/?{parts}" if parts else f"{base}/"


def implement_run_review_link(inspire_url: str, session_id) -> str:
    session = implement_session_text(session_id)
    return implement_link(inspire_url, review=session) if session else ""


def implement_review_link(inspire_url: str, session_id, uc_id) -> str:
    session = implement_session_text(session_id)
    case = str(uc_id if uc_id is not None else "").strip()
    return implement_link(inspire_url, review=session, uc=case) if session and case else ""


def implement_digest_page_line(app_url: str, hosted_id: str = "", inspire_url: str = "") -> str:
    link = implement_link(inspire_url, run=hosted_id) if hosted_id else implement_link(app_url, open="impact")
    return f"{IMPLEMENT_APP_HOSTED_EMAIL if hosted_id else IMPLEMENT_DIGEST_APP_LINE}: {link}" if link else ""


def implement_digest_relinked(text: str, line: str) -> str:
    prefixes = (f"{IMPLEMENT_DIGEST_APP_LINE}: ", IMPLEMENT_APP_HOSTED_EMAIL)
    lines = [kept for kept in str(text or "").split("\n") if not kept.startswith(prefixes)]
    if line and IMPLEMENT_DIGEST_RESULT in lines:
        lines.insert(lines.index(IMPLEMENT_DIGEST_RESULT), line)
    return "\n".join(lines)


def implement_app_shown(host: dict) -> tuple:
    return ("the page inside Inspire", "") if (host or {}).get("hosted") else (f"the App {host['name']}", host["name"])


def implement_app_hosted_asset(hosted: dict) -> dict:
    return {"placement": IMPLEMENT_APP_HOSTED, "hosted": dict(hosted), "app_name": "", "app_url": ""}


def implement_output_assets(carried: dict, asset_status) -> dict:
    assets = {name: (carried or {}).get(column) for name, column in IMPLEMENT_OUTPUT_ID_COLUMNS.items()}
    assets["app"] = assets["app"] or implement_app_hosted_id((asset_status or {}).get("app")) or None
    return assets


def implement_asset_tags(assets: dict, asset_status: dict, ai_endpoint: str = "", ids=None, warehouse: str = "", app_warehouse: str = "") -> dict:
    assets, status = assets if isinstance(assets, dict) else {}, asset_status if isinstance(asset_status, dict) else {}
    ids = ids if isinstance(ids, dict) else {}
    value = lambda text: JobLauncher._sanitize_tag(text, JobLauncher.TAG_ITEM_CHARS)
    entry = lambda name: status.get(name) if isinstance(status.get(name), dict) else {}
    live = lambda name: bool(value(assets.get(name) or "")) and entry(name).get("state") not in IMPLEMENT_STOPPED_STATES
    tags, kinds = {}, []
    if live("app") and entry("app").get("placement") != IMPLEMENT_APP_HOSTED:
        kinds.append("app")
        tags["dbx_inspire_ai_app_name"] = value(assets["app"])
        app_id = value(ids.get("dbx_inspire_ai_app_id") or entry("app").get("app_id") or "")
        if app_id:
            tags["dbx_inspire_ai_app_id"] = app_id
    if live("genie_space"):
        kinds.append("genie")
        tags["dbx_inspire_ai_genie_space_id"] = value(assets["genie_space"])
    if live("dashboard"):
        kinds.append("dashboard")
        tags["dbx_inspire_ai_dashboard_id"] = value(assets["dashboard"])
    if live("alert"):
        alert_ids = list(dict.fromkeys(i for i in (value(assets["alert"]), value(entry("alert").get("digest_id") or "")) if i))
        kinds.append("alert")
        tags["dbx_inspire_ai_alert_ids"] = JobLauncher.tag_list(alert_ids)
        tags["dbx_inspire_ai_alert_count"] = str(len(alert_ids))
    if value(ai_endpoint) and entry("ai_reasoning").get("state") == "ready":
        kinds.append("agent_endpoint")
        tags["dbx_inspire_ai_agent_endpoint"] = value(ai_endpoint)
        if value(ids.get("dbx_inspire_ai_agent_endpoint_id") or ""):
            tags["dbx_inspire_ai_agent_endpoint_id"] = value(ids["dbx_inspire_ai_agent_endpoint_id"])
    if live("app") and entry("app").get("backend") == IMPLEMENT_APP_BACKENDS[0]:
        kinds.append("lakebase")
        tags["dbx_inspire_ai_lakebase_project"] = value(IMPLEMENT_LAKEBASE_PROJECT)
        if value(ids.get("dbx_inspire_ai_lakebase_project_id") or ""):
            tags["dbx_inspire_ai_lakebase_project_id"] = value(ids["dbx_inspire_ai_lakebase_project_id"])
    if live("app") and value(entry("app").get("backend") or ""):
        tags["dbx_inspire_ai_backend"] = value(entry("app")["backend"])
    used = ([value(app_warehouse)] if live("app") else []) + ([value(warehouse)] if any(live(n) for n in ("dashboard", "genie_space", "alert")) else [])
    if any(used):
        tags["dbx_inspire_ai_warehouse_id"] = JobLauncher.tag_list(list(dict.fromkeys(w for w in used if w)))
    if kinds:
        tags["dbx_inspire_ai_assets"] = JobLauncher.tag_list(kinds)
    return tags


def implement_app_warehouse(spec) -> str:
    spec = spec if isinstance(spec, dict) else {}
    return (str((spec.get("outputs") or {}).get("app_warehouse_id") or "").strip()
            or str((spec.get("config") or {}).get("warehouse_id") or "").strip())


def implement_app_warehouse_of(resources) -> str:
    return next((str((r.get("sql_warehouse") or {}).get("id") or "") for r in resources or []
                 if isinstance(r, dict) and isinstance(r.get("sql_warehouse"), dict)), "")


def _implement_merge_targets(outputs: dict, chosen: dict) -> tuple:
    errors = []
    asked = _implement_mapping(outputs.get("merge"), "outputs.merge", errors)
    errors += [f"outputs.merge.{name} is not one of {', '.join(IMPLEMENT_MERGE_OUTPUTS)}" for name in asked
               if name not in IMPLEMENT_MERGE_OUTPUTS]
    merge = {}
    for name in IMPLEMENT_MERGE_OUTPUTS:
        if asked.get(name) is not None and not isinstance(asked.get(name), str):
            errors.append(f'outputs.merge.{name} must be text: the {IMPLEMENT_MERGE_LABELS[name]} to add to, or "" for a new one')
            merge[name] = ""
            continue
        target = _implement_text_value(asked.get(name)) if chosen[name] else ""
        target = target.lower() if name == "app" else target
        if target and not (IMPLEMENT_APP_NAME_RE if name == "app" else IMPLEMENT_ASSET_ID_RE).fullmatch(target):
            errors.append(f"outputs.merge.{name} {_implement_shown(asked.get(name))} must name an existing Inspire {IMPLEMENT_MERGE_LABELS[name]}")
            target = ""
        merge[name] = target
    return merge, errors



def implement_merge_target(outputs: dict, name: str) -> str:
    return str(((outputs or {}).get("merge") or {}).get(name) or "").strip()


def _implement_section(spec: dict, key: str):
    value = (spec or {}).get(key)
    return json.dumps(value if value is not None else {}, sort_keys=True, default=str)


def _implement_option_changes(before: dict, after: dict) -> list:
    return [name for name in IMPLEMENT_OUTPUTS if before.get(name) and after.get(name)
            and (any(before.get(o) != after.get(o) for o in IMPLEMENT_OUTPUT_OPTIONS[name])
                 or implement_asset_vibes_shown(before, name) != implement_asset_vibes_shown(after, name)
                 or (name == "alert" and (implement_alert_digest(before) != implement_alert_digest(after)
                                          or implement_alert_notify_on_ok(before) != implement_alert_notify_on_ok(after))))]


def _implement_config_rest(spec) -> dict:
    config = (spec or {}).get("config")
    return (dict(spec or {}, config={k: v for k, v in config.items() if k not in ("assumptions", "widgets", "settings_note")})
            if isinstance(config, dict)
            else (spec or {}))


def implement_built_settings(asset_status) -> list:
    held = (asset_status or {}).get("settings") if isinstance(asset_status, dict) else None
    return [str(s["name"]) for s in held or [] if isinstance(s, dict) and s.get("source") == "widget" and s.get("name")]


def implement_changed_widgets(previous, current) -> list:
    before = dict(((previous or {}).get("config") or {}).get("widgets") or {})
    after = dict(((current or {}).get("config") or {}).get("widgets") or {})
    return sorted(name for name in after if before.get(name) != after[name])


def implement_scope_stale(widgets) -> list:
    widgets = widgets if isinstance(widgets, dict) else {}
    scope_name, groups_name, days_name, records_name = INSPIRE_SCOPE_SETTINGS
    scope = str(widgets.get(scope_name) or "").strip().lower()
    if scope and scope not in INSPIRE_SCOPES:
        return []
    own = {"groups": groups_name, "recent": days_name, "records": records_name}
    return [name for owner, name in own.items() if owner != scope and str(widgets.get(name) if widgets.get(name) is not None else "").strip()]


def implement_scope_chosen(widgets) -> dict:
    widgets = widgets if isinstance(widgets, dict) else {}
    scope_name, groups_name, days_name, records_name = INSPIRE_SCOPE_SETTINGS
    stale = implement_scope_stale(widgets)
    chosen = {}
    scope = str(widgets.get(scope_name) or "").strip().lower()
    if scope in INSPIRE_SCOPES:
        chosen[scope_name] = scope
    groups = str(widgets.get(groups_name) or "").strip()
    if groups and groups_name not in stale:
        chosen[groups_name] = groups
    for name in (days_name, records_name):
        count = str(widgets.get(name) if widgets.get(name) is not None else "").strip()
        if count.isdigit() and int(count) >= 1 and name not in stale:
            chosen[name] = int(count)
    return chosen


def implement_scope_asked(previous_spec, spec) -> bool:
    if not previous_spec:
        return True
    return (implement_scope_chosen((previous_spec.get("config") or {}).get("widgets"))
            != implement_scope_chosen(((spec or {}).get("config") or {}).get("widgets")))


def implement_built_grouping(asset_status):
    held = (asset_status or {}).get("settings") if isinstance(asset_status, dict) else None
    found = next((s for s in held or [] if isinstance(s, dict) and s.get("name") == INSPIRE_GROUP_BY and s.get("source") == "widget"), None)
    return None if found is None else [str(c) for c in found.get("choices") or []]


def implement_grouping_unread(value, choices) -> list:
    if choices is None:
        return []
    mode, picked = inspire_group_by_mode(value)
    known = {str(c).lower() for c in choices}
    return [name for name in picked if name.lower() not in known] if mode == "columns" else []


def implement_widget_change_class(previous, current, built=None, grouping=None) -> str:
    before = dict(((previous or {}).get("config") or {}).get("widgets") or {})
    after = dict(((current or {}).get("config") or {}).get("widgets") or {})
    if before == after:
        return ""
    removed = [name for name in before if name not in after and name not in INSPIRE_SCOPE_SETTINGS[1:]]
    changed = set(implement_changed_widgets(previous, current))
    if INSPIRE_GROUP_BY in changed and implement_grouping_unread(after.get(INSPIRE_GROUP_BY), grouping):
        return "config"
    return "settings" if built and not removed and changed <= set(built) else "config"


def implement_setting_insert_sql(result_table, use_case_id, name, value, text, who, note) -> str:
    return (f"INSERT INTO {inspire_table_name(inspire_assumptions_table(result_table))} (use_case_id, name, value, changed_by, changed_at, note, "
            f"text_value) VALUES ({inspire_sql_literal(use_case_id)}, {inspire_sql_literal(name)}, {inspire_sql_number(value)}, "
            f"{inspire_sql_literal(who)}, current_timestamp(), {inspire_sql_literal(note)}, "
            f"{'NULL' if text is None else inspire_sql_literal(text)})")


def classify_implement_change(previous, current, built=None, table_change=None, grouping=None) -> list:
    if not previous:
        return ["initial"]
    classes = set()
    if _implement_section(previous, "data") != _implement_section(current, "data"):
        classes.add("settings" if (table_change or {}).get("class") == "settings" else "data")
    widgets = implement_widget_change_class(previous, current, built, grouping)
    if (_implement_section(_implement_config_rest(previous), "config") != _implement_section(_implement_config_rest(current), "config")
            or _implement_section(previous, "use_case") != _implement_section(current, "use_case") or widgets == "config"
            or implement_kpi_choice(previous) != implement_kpi_choice(current)):
        classes.add("config")
        widgets = "config"
    if (((previous or {}).get("config") or {}).get("assumptions") or {}) != (((current or {}).get("config") or {}).get("assumptions") or {}) \
            or widgets == "settings":
        classes.add("settings")
    if _implement_section(previous, "schedule") != _implement_section(current, "schedule"):
        classes.add("schedule")
    if implement_holdout_share(previous.get("holdout")) != implement_holdout_share(current.get("holdout")):
        classes.add("holdout")
    if implement_act_now_capacity(previous.get("capacity")) != implement_act_now_capacity(current.get("capacity")):
        classes.add("capacity")
    before, after = previous.get("outputs") or {}, current.get("outputs") or {}
    if any(after.get(n) and not before.get(n) for n in IMPLEMENT_OUTPUTS) or (
            implement_app_moved(before, after)) or _implement_option_changes(
            before, after) or any(after.get(n) and before.get(n) and implement_merge_target(before, n) != implement_merge_target(after, n)
                                  for n in IMPLEMENT_MERGE_OUTPUTS) or (
            implement_asset_vibes_shown(before, IMPLEMENT_NOTEBOOK) != implement_asset_vibes_shown(after, IMPLEMENT_NOTEBOOK)):
        classes.add("outputs")
    if any(before.get(n) and not after.get(n) for n in IMPLEMENT_OUTPUTS):
        classes.add("deselect")
    if _implement_section(previous, "sharing") != _implement_section(current, "sharing"):
        classes.add("sharing")
    if current.get("retry_outputs"):
        classes.add("retry")
    if current.get("rollback_outputs"):
        classes.add("rollback")
    for name, key in (("vibe", "vibes"), ("remove_kept", "remove_kept"), ("uninstall", "uninstall")):
        if current.get(key):
            classes.add(name)
    if str((previous or {}).get("use_case_name") or "").strip() != str((current or {}).get("use_case_name") or "").strip():
        classes.add("name")
    return [c for c in IMPLEMENT_CHANGE_CLASSES if c in classes]


IMPLEMENT_ROLLBACK_BUILT_REASONS = {"gone": "the {label} no longer exists", "new": "the version before had no {label}",
                                    "renamed": "the {label} now has a different name or target"}


def implement_rollback_built_warning(name: str, entry: dict) -> str:
    label = IMPLEMENT_OUTPUT_LABELS[name]
    why = IMPLEMENT_ROLLBACK_BUILT_REASONS[entry["why"]].format(label=label)
    return f"{label}: v{entry['version']} could not be put back because {why}, so Inspire builds a new {label} with Genie instead"


def implement_plan(previous, current, previous_assets=None, has_built_notebook=False, built=None, table_change=None,
                   grouping=None) -> dict:
    classes = classify_implement_change(previous, current, built if has_built_notebook else None, table_change, grouping)
    assets = previous_assets or {}
    outputs = current.get("outputs") or {}
    before = (previous or {}).get("outputs") or {}
    retry = list(current.get("retry_outputs") or [])
    retried = {implement_asset_owner(r) for r in retry}
    notebook_asks = ({a for a in IMPLEMENT_NOTEBOOK_ASSETS if implement_asset_vibes_shown(before, IMPLEMENT_NOTEBOOK).get(a)
                      != implement_asset_vibes_shown(outputs, IMPLEMENT_NOTEBOOK).get(a)} if previous else set()) | (
        set(retry) & set(IMPLEMENT_NOTEBOOK_ASSETS))
    swapped = (table_change or {}).get("class") == "settings" and _implement_section(previous, "data") != _implement_section(current, "data")
    refill = (bool({"initial", "data", "config"} & set(classes)) or not has_built_notebook
              or IMPLEMENT_NOTEBOOK in retry or "value_formula" in notebook_asks or swapped and not table_change.get("repoint", True))
    repointing = swapped and not refill
    build, refresh = [], []
    option_changes = _implement_option_changes(before, outputs) if previous else []
    asked_rollback = {name: int(version) for name, version in (current.get("rollback_outputs") or {}).items()}
    rollback, rollback_built = {}, {}
    for name in IMPLEMENT_OUTPUTS:
        if not outputs.get(name):
            continue
        renamed = (name == "app" and implement_app_moved(before, outputs)) or (
            before.get(name) and implement_merge_target(before, name) != implement_merge_target(outputs, name))
        if not assets.get(name) or not before.get(name) or renamed:
            build.append(name)
            if name in asked_rollback:
                rollback_built[name] = {"version": asked_rollback[name],
                                        "why": "gone" if not assets.get(name) else "new" if not before.get(name) else "renamed"}
        elif name in asked_rollback:
            rollback[name] = asked_rollback[name]
        elif (refill or name in option_changes or name in retried or (name == "alert" and "schedule" in classes)
              or (name == "app" and "name" in classes) or repointing and name in (table_change.get("refused") or {})):
            refresh.append(name)
    restyle = [n for n in refresh if n in IMPLEMENT_RESTYLE_OPTIONS and n in option_changes and not refill and n not in retried
               and all(before.get(o) == outputs.get(o) for o in IMPLEMENT_OUTPUT_OPTIONS[n] if o not in IMPLEMENT_RESTYLE_OPTIONS[n])
               and implement_asset_vibes_shown(before, n) == implement_asset_vibes_shown(outputs, n)]
    if ("name" in classes and "app" in refresh and "app" not in restyle and not refill
            and all(before.get(o) == outputs.get(o) for o in IMPLEMENT_OUTPUT_OPTIONS["app"] if o not in IMPLEMENT_RESTYLE_OPTIONS["app"])
            and implement_asset_vibes_shown(before, "app") == implement_asset_vibes_shown(outputs, "app")):
        restyle.append("app")
    deselected = [n for n in IMPLEMENT_OUTPUTS if before.get(n) and not outputs.get(n)]
    delete = [n for n in deselected if (current.get("removed_outputs") or {}).get(n) == "delete" and assets.get(n)]
    keep = [n for n in deselected if n not in delete and assets.get(n)]
    moved = bool(previous) and (_implement_plain_table(((previous or {}).get("config") or {}).get("result_table")).lower()
                                != _implement_plain_table((current.get("config") or {}).get("result_table")).lower())
    retable_outputs = {name: entry["version"] for name, entry in ((table_change or {}).get("outputs") or {}).items()
                       if repointing and name not in build and name not in refresh and name not in rollback}
    touched = set(build) | set(refresh) | set(rollback) | set(retable_outputs)
    repoint = ["app"] if outputs.get("app") and assets.get("app") and "app" not in touched and "genie_space" in touched else []
    relink = (["alert"] if before.get("alert") and outputs.get("alert") and implement_alert_digest(outputs) and "alert" not in touched
              and str(before.get("inspire_url") or "") != str(outputs.get("inspire_url") or "") else [])
    retable = implement_table_swap_changes((previous or {}).get("data"), current.get("data")) if repointing else []
    return {"classes": classes, "refill": refill, "retable": retable, "retable_outputs": retable_outputs,
            "preview": refill or bool(retable) or "ai_reasoning" in notebook_asks or bool(build) and not assets.get("preview_run_id"),
            "build": build, "refresh": refresh, "restyle": restyle, "repoint": repoint, "relink": relink, "rollback": rollback,
            "rollback_built": rollback_built,
            "delete": delete, "keep_unmanaged": keep,
            "schedule": bool({"initial", "schedule"} & set(classes)) or refill,
            "sharing": bool({"initial", "sharing", "outputs"} & set(classes)) or bool(build) or bool(rollback) or bool(retable_outputs) or moved}


def implement_version_parts(spec: dict) -> list:
    outputs = (spec or {}).get("outputs") or {}
    notes = str(((spec or {}).get("data") or {}).get("notes") or "").strip()
    return list(dict.fromkeys(([IMPLEMENT_NOTEBOOK] if notes else []) + list(implement_asset_vibes(outputs))
                              + [name for name in IMPLEMENT_OUTPUTS if outputs.get(name) and implement_output_vibes(outputs, name)]))


def implement_version_asks(spec: dict) -> bool:
    return bool(implement_version_parts(spec))


def implement_plan_rebuilds(plan: dict) -> set:
    return set(plan["build"]) | set(plan["refresh"]) | set(plan["rollback"]) | (
        {IMPLEMENT_NOTEBOOK} if plan["preview"] or plan["refill"] else set())


def implement_refill_refresh(plan: dict, outputs: dict, assets) -> list:
    added = [name for name in IMPLEMENT_OUTPUTS if (outputs or {}).get(name) and (assets or {}).get(name)
             and name not in plan["build"] + plan["refresh"] + list(plan["rollback"])]
    plan["refresh"] += added
    plan["repoint"] = [name for name in plan["repoint"] if name not in added]
    return added


def implement_retry_unmet(plan: dict, spec: dict, unmet: dict, assets) -> list:
    retried = []
    for name in sorted({implement_asset_owner(part) for part in unmet}):
        if name == IMPLEMENT_NOTEBOOK:
            plan["refill"] = plan["preview"] = True
            implement_refill_refresh(plan, spec["outputs"], assets)
            retried.append(name)
        elif name in IMPLEMENT_OUTPUTS and spec["outputs"].get(name) and name not in plan["build"] + plan["refresh"] + list(plan["rollback"]):
            plan["refresh"].append(name)
            plan["repoint"] = [other for other in plan["repoint"] if other != name]
            again = {part: asks for part, asks in unmet.items() if implement_asset_owner(part) == name}
            spec["retry_outputs"] = list(dict.fromkeys(list(spec.get("retry_outputs") or []) + [name] + list(again)))
            spec["retry_asks"] = dict(spec.get("retry_asks") or {}, **again)
            retried.append(name)
    return retried


def implement_build_unmet(unmet: list, spec: dict, previous_spec, asset_status, version) -> list:
    """c24_rc7mvp: an ask carried from an earlier version is not listed as unmet for a part that failed to build in this version: the part's
    own error already says what happened. Asks the build brought (a vibe of its own, a changed part ask, a retry) are always listed."""
    spec, status = spec or {}, (asset_status if isinstance(asset_status, dict) else {})
    if spec.get("vibes") or spec.get("retry_outputs") or spec.get("retry_asks"):
        return list(unmet)
    held, before = implement_held_vibes(spec), implement_held_vibes(previous_spec or {})
    own = {implement_checklist_part(asset) for asset in held if held[asset] != before.get(asset)}

    def failed(part):
        record = status.get(part)
        return isinstance(record, dict) and record.get("state") == "failed" and record.get("spec_version") == version

    return [entry for entry in unmet if entry.get("part") in own or not failed(entry.get("part"))]


def implement_unmet_asks(asset_status) -> list:
    listed = (asset_status if isinstance(asset_status, dict) else {}).get("checklist")
    return [dict(entry) for entry in (listed if isinstance(listed, list) else [])
            if isinstance(entry, dict) and entry.get("status") == "not_met"]


IMPLEMENT_PUBLISH_MISSED = "built and checked, but not published"


def implement_publish_missed(asset_status, name: str, version, reason: str) -> int:
    label, missed = IMPLEMENT_OUTPUT_LABELS[name], 0
    for asset, record in (asset_status if isinstance(asset_status, dict) else {}).items():
        if implement_asset_owner(asset) != name or not isinstance(record, dict):
            continue
        checks = [c for c in record.get("vibes_checks") or [] if isinstance(c, dict)]
        for check in checks:
            if check.get("status") == "done":
                check.update(status="missing", evidence=f"{IMPLEMENT_PUBLISH_MISSED}: Genie built it in v{version} and its checks passed, "
                                                         f"but publishing the {label} failed, so the live {label} does not have it and "
                                                         f"the ask waits for the next build: {reason}")
                missed += 1
        if checks and asset != name:
            record["state"] = "failed"
    return missed


def implement_live_unmet(asset_status, spec: dict) -> dict:
    status, unmet = (asset_status if isinstance(asset_status, dict) else {}), {}
    for part in implement_version_parts(spec):
        for check in ((status.get(part) or {}).get("vibes_checks") or []):
            if isinstance(check, dict) and check.get("status") != "done" and str(check.get("evidence") or "").startswith(IMPLEMENT_VIBES_UNCHECKED):
                unmet.setdefault(part, []).append(str(check.get("ask") or ""))
    return unmet


IMPLEMENT_SEND_VIBE_AGAIN = "send the vibe again from the vibe box on the Build page"
IMPLEMENT_TRY_AGAIN = "press Try again"
IMPLEMENT_SUBMIT_AGAIN = "submit again"


def implement_check_again(n: int = 1) -> str:
    return f"{IMPLEMENT_TRY_AGAIN} to check {'it' if n == 1 else 'them'} again"


IMPLEMENT_ENTRY_ACTIONS = (implement_check_again(1), IMPLEMENT_SEND_VIBE_AGAIN, IMPLEMENT_SUBMIT_AGAIN, IMPLEMENT_NO_DATA_CHOICES)


def implement_rebuild_target(text):
    head, tail = inspire_rebuild_action("\x00").split("\x00")
    text = str(text or "")
    if len(text) > len(head) + len(tail) and text.startswith(head) and text.endswith(tail):
        return text[len(head):-len(tail)]
    return None


def implement_entry_fact(text) -> tuple:
    text = str(text or "")
    for joint in ("; ", ": "):
        fact, cut, action = text.rpartition(joint)
        if cut and (action in IMPLEMENT_ENTRY_ACTIONS or implement_rebuild_target(action) is not None):
            return fact, action
    return text, ""


def implement_compose(lines) -> str:
    facts, actions, targets = [], [], []
    for line in lines:
        fact, action = implement_entry_fact(line)
        facts.append(fact)
        target = implement_rebuild_target(action)
        if target is not None:
            if not targets:
                actions.append(None)
            targets += [] if target in targets else [target]
        elif action and action not in actions:
            actions.append(action)
    return "; ".join(facts + [inspire_rebuild_action(" and ".join(targets)) if a is None else a for a in actions])


def implement_checklist_unchecked(evidence: str) -> str:
    return f"{evidence.rstrip('. ')}. Nothing shows the ask was missed: {implement_check_again(1)}"


def implement_checklist_texts(evidence, unchecked: bool = False) -> dict:
    shown = implement_checklist_unchecked(implement_plain_reason(evidence)) if unchecked else implement_plain_reason(evidence)
    if shown.startswith(IMPLEMENT_VIBES_NO_DATA) and not shown.endswith(IMPLEMENT_NO_DATA_CHOICES):
        shown = f"{shown.rstrip('. ')}: {IMPLEMENT_NO_DATA_CHOICES}"
    return {"evidence": shown, "fact": implement_entry_fact(shown)[0]}


def implement_unmet_published_text(unmet: list, version: int, published: bool = True, titles=None) -> str:
    listed = "; ".join(f"{implement_asset_heading(entry['part'], None, titles) if entry.get('part') else 'No part'}"
                       f"{' (' + entry['where'] + ')' if entry.get('where') else ''}: {entry.get('requirement')}: "
                       f"{implement_rounds_note(implement_entry_fact(entry.get('evidence'))[0], int(entry.get('rounds') or 0))}"
                       for entry in unmet)
    again = f". {IMPLEMENT_TRY_AGAIN[:1].upper() + IMPLEMENT_TRY_AGAIN[1:]} to check the unchecked asks again" if any(entry.get("unchecked") for entry in unmet) else ""
    if not published:
        return f"v{version} is not fully published, with {inspire_plural(len(unmet), 'unmet ask')} (not met or could not be checked): {listed}{again}"
    return f"v{version} is published with {inspire_plural(len(unmet), 'unmet ask')} (not met or could not be checked), the rest of the vibe is in place: {listed}{again}"

def implement_owners(row: dict) -> list:
    spec = row.get("spec_json") if isinstance(row.get("spec_json"), dict) else {}
    outputs = spec.get("outputs") if isinstance(spec.get("outputs"), dict) else {}
    named = [row.get("created_by")] + (outputs.get("app_owners") if isinstance(outputs.get("app_owners"), list) else [])
    return list(dict.fromkeys(key for key in (str(name if name is not None else "").strip().lower() for name in named) if key))


def implement_settings_refusal(previous: dict, requester, version: int) -> str:
    live = int(previous.get("spec_version") or 0)
    lead = IMPLEMENT_SETTINGS_OWNERS.format(live=live)
    kept = f"applied nothing of v{version}, and the version you have now stays as it is"
    who = str(requester if requester is not None else "").strip()
    if not who:
        return (f"{lead}, and this run does not name who asked for it, so Inspire cannot check that they are one of them; it {kept}. "
                "Submit the change again from the Inspire App, which records who asks")
    if who.lower() not in implement_owners(previous):
        return f"{lead}, and {who}, who asked for v{version}, is not one of them, so Inspire {kept}"
    return ""


def implement_settings_asked(previous, current) -> list:
    widgets = dict(((current or {}).get("config") or {}).get("widgets") or {})
    was = dict(((previous or {}).get("config") or {}).get("assumptions") or {})
    now = dict(((current or {}).get("config") or {}).get("assumptions") or {})
    return ([f"Set {name} to {widgets[name]}" for name in implement_changed_widgets(previous, current)]
            + [f"Set {name} to {inspire_number_text(now[name])}" for name in sorted(now) if was.get(name) != now[name]]
            + [f"Clear the value of {name}" for name in sorted(was) if name not in now])


def implement_settings_refused_entries(asked: list, refusal: str) -> list:
    return [{"n": n, "kind": IMPLEMENT_SETTINGS_REFUSED, "requirement": text, "part": "", "where": "Settings", "status": "refused",
             "evidence": refusal, "rounds": 0, "tried": [], "checks": [], "published_anyway": None} for n, text in enumerate(asked, 1)]



def implement_reusable_notebook(previous, notebook_record) -> bool:
    written_by = (notebook_record or {}).get("spec_version")
    if not previous or written_by is None:
        return False
    try:
        return int(written_by) <= int(previous["spec_version"])
    except (KeyError, TypeError, ValueError):
        return False


def implement_notebook_keeps_history(notebook_record) -> bool:
    return (notebook_record or {}).get("result_history") == IMPLEMENT_RESULT_HISTORY


def implement_notebook_reuse(previous, carried: dict, asset_status: dict) -> tuple:
    reusable = implement_reusable_notebook(previous, asset_status.get("notebook"))
    upgrade = bool(carried.get("notebook_path")) and reusable and not implement_notebook_keeps_history(asset_status.get("notebook"))
    return reusable, upgrade, bool(carried.get("notebook_path")) and reusable and not upgrade


def implement_replace_edits(spec: dict) -> bool:
    return bool((((spec or {}).get("outputs") or {}).get("app_options") or {}).get("replace_edits"))


def implement_replace_edits_sql(result_table: str, replace_edits: bool) -> str:
    return (f"ALTER TABLE {inspire_table_name(result_table)} SET TBLPROPERTIES ({inspire_sql_literal(INSPIRE_REPLACE_EDITS_PROPERTY)} = "
            f"{inspire_sql_literal('true' if replace_edits else 'false')})")


def implement_result_table_move(previous_spec, spec: dict, default_table: str):
    if not previous_spec:
        return None
    old = ".".join(inspire_table_parts((previous_spec.get("config") or {}).get("result_table") or default_table))
    new = ".".join(inspire_table_parts((spec.get("config") or {}).get("result_table") or default_table))
    return (old, new) if old.lower() != new.lower() else None


def implement_result_copy_sql(previous_result_table: str, result_table: str) -> str:
    return f"CREATE TABLE {inspire_table_name(result_table)} DEEP CLONE {inspire_table_name(previous_result_table)}"


def implement_dismissals_sql(result_table: str) -> str:
    return (f"SELECT reason, records, SUM(records) OVER () AS dismissed FROM (SELECT NULLIF(TRIM(dismiss_reason), '') AS reason, "
            f"COUNT(*) AS records FROM {inspire_table_name(result_table)} WHERE use_case_id = :uc AND {INSPIRE_CURRENT_ROWS} AND "
            f"action_status = 'Dismissed' GROUP BY 1) ORDER BY reason IS NULL, records DESC, reason LIMIT {IMPLEMENT_DISMISS_REASONS + 1}")


def implement_dismissal_lines(dismissed) -> list:
    total = int((dismissed or {}).get("dismissed") or 0)
    if total <= 0:
        return []
    reasons = "; ".join(f"\"{reason}\" ({implement_number_text(count)})" for reason, count in (dismissed.get("reasons") or [])[:IMPLEMENT_DISMISS_REASONS])
    return [f"- The customer's feedback from the {IMPLEMENT_OUTPUT_LABELS['app']}: people dismissed {implement_number_text(total)} of the current records"
            + (f", most often because: {reasons}" if reasons else ", without giving a reason")
            + ". Treat it as the customer's word on what the decision list gets wrong, and change the method where the data can tell "
              "such records apart. A dismissed record never goes back to Act now: inspire_write_result keeps it in Monitor on every "
              "run, so never work around that."]


def implement_preview_budget_rule(trains_model: bool = True) -> str:
    return (f"- A run with `run_profile` set to `preview` finishes within {IMPLEMENT_PREVIEW_BUDGET_MINUTES} minutes"
            + (", training included" if trains_model else "") + ". When your preview test run is still running at that budget, "
            "cancel it, find the slow step from the step times it printed, make that step fast and run the test again, never wait "
            "for the run to finish. Build features from history with Spark aggregations or vectorized pandas group operations, "
            "never a Python loop per entity or per transaction.")

def implement_aggregate_probe_sql(result_table: str, source_table: str, column: str, scopes=None) -> str:
    named = inspire_quote_identifier(column)
    return (f"SELECT COUNT(DISTINCT r.{named}) AS outside FROM {inspire_table_name(result_table)} AS r "
            f"LEFT ANTI JOIN {inspire_scoped_read_source(source_table, scopes, 's')} ON r.{named} = s.{named} WHERE r.{named} IS NOT NULL")


def implement_key_values(spark, key: dict):
    try:
        outside = int(spark.sql(implement_aggregate_probe_sql(key["result_table"], key["table"], key["column"], key.get("scopes"))).collect()[0]["outside"])
    except Exception as error:
        return ("missing", f"Inspire could not compare {key['column']} of {key['result_table']} with {key['table']}: "
                           f"{redact_error(error)[:200]}")
    if outside:
        return ("missing", f"{inspire_plural(outside, 'value')} of {key['column']} in {key['result_table']} "
                           f"{'is' if outside == 1 else 'are'} not values of {key['table']}")
    return None


def implement_key_presence(columns, key: dict):
    if key["column"].lower() in {str(c).lower() for c in columns or []}:
        return None
    return ("missing", f"{key['result_table']} has no {key['column']} column, so it cannot carry the row filter of {key['table']}")


def implement_key_asks(keys: list) -> list:
    return [f"the result table {key['result_table']} must carry the column {key['column']} from {key['table']} unchanged, with one "
            f"{key['column']} value for each row, because a row filter keeps each person to their rows through {key['column']}"
            for key in keys]


def implement_choices_markdown(spec: dict, previous=None, trains_model: bool = True, dismissed=None, asks=None, impact=None,
                               held=None, keys=()) -> str:
    stake = inspire_stake_words(impact)
    lines = ["## Implementation Choices",
             "The user made these choices in the Start Use Case MVP with Genie wizard. They win over anything above that conflicts with them."]
    choices = _implement_choice_lines(spec, trains_model, impact)
    lines += choices
    if keys:
        lines.append("- The result table must carry these columns unchanged, because a per-user App keeps each person to their rows "
                     "through them: " + "; ".join(implement_key_asks(keys)))
    formula = (asks or {}).get("value_formula")
    again = (spec.get("retry_asks") or {}).get("value_formula")
    if formula and implement_asset_vibes(spec.get("outputs"), IMPLEMENT_NOTEBOOK).get("value_formula"):
        lines.append(f"- Inspire split the asks for the {stake} formula into these, and checks each one in the "
                     f"value_at_stake_formula the run writes: " + "; ".join(f"{n}. {a}" for n, a in enumerate(formula, 1)))
    if again:
        lines.append(f"- Try again on only these asks for the {stake} formula, which the last build missed, and keep the "
                     "rest of the formula as it is: " + "; ".join(f"{n}. {a}" for n, a in enumerate(again, 1)))
    notes_again = (spec.get("retry_asks") or {}).get(IMPLEMENT_NOTEBOOK)
    if notes_again:
        lines.append("- Try again on only these of the customer's asks for this notebook, which the last build missed, and keep "
                     "every other cell as it is: " + "; ".join(f"{n}. {a}" for n, a in enumerate(notes_again, 1)))
    holding = implement_held_text(held, implement_notebook_asks(spec))
    if holding:
        lines.append(f"- {holding}")
    lines += implement_dismissal_lines(dismissed)
    changed = classify_implement_change(previous, spec) if previous else []
    if previous and {"data", "config"} & set(changed):
        lines.append("- The notebook was already built for an earlier version of these choices. Update the cells that the changed "
                     "choices affect; keep every cell that still holds.")
        for line in _implement_choice_lines(previous, trains_model, impact):
            if line not in choices:
                lines.append(f"- Withdrawn since the earlier version: {line[2:]} Take out what the cells do for it; where the "
                             "instruction above has its own choice, follow the instruction.")
    if previous and IMPLEMENT_NOTEBOOK in (spec.get("retry_outputs") or []):
        lines.append("- The user asked for the notebook to be built again. Check every cell against the instruction and the platform "
                     "rules above as they read now: rewrite each cell that does not follow them, and keep each cell that does.")
    return "\n".join(lines) + "\n"


IMPLEMENT_KPI_MAX = 3
IMPLEMENT_KPI_NOT_COMPUTABLE = "its definition names no measure, table or column Inspire can aggregate, so it is tracked as text"
IMPLEMENT_KPI_FILTER_OP = {"type": ["string", "null"], "enum": [*KPI_FILTER_OPERATORS, None]}
IMPLEMENT_KPI_SCHEMA = {"type": "object", "properties": {"kpis": {"type": "array", "items": {"type": "object", "properties": {
    "name": {"type": "string"}, "direction": {"type": "string"}, "unit": {"type": "string"},
    "impact_kind": {"type": "string", "enum": list(INSPIRE_IMPACT_KINDS)}, "filter_op": IMPLEMENT_KPI_FILTER_OP,
    "denominator": {"type": ["object", "null"], "properties": {"filter_op": IMPLEMENT_KPI_FILTER_OP}}},
    "required": ["name", "direction", "unit", "impact_kind"]}}}, "required": ["kpis"]}
IMPLEMENT_IMPACT_CURRENCY_SIGNS = {"$": "USD", "€": "EUR", "£": "GBP", "¥": "JPY", "₹": "INR"}
IMPLEMENT_IMPACT_PERCENT_UNITS = ("%", "percent", "percentage", "pct", "pp", "percentage points", "points")
IMPLEMENT_IMPACT_HOUR_UNITS = ("hour", "hours", "hr", "hrs", "h")
IMPLEMENT_IMPACT_TIME_UNITS = ("minute", "minutes", "min", "mins", "second", "seconds", "sec", "secs", "day", "days", "week", "weeks")
IMPLEMENT_IMPACT_COUNT_UNITS = ("count", "#", "number", "records", "units", "items", "cases")
IMPLEMENT_IMPACT_MONEY_WORDS = re.compile(r"\b(revenue|sales|cost|costs|spend|spending|margin|margins|profit|profits|price|prices|fee|fees|"
                                          r"income|expense|expenses|savings|cash|payment|payments|budget|money|dollars?|euros?)\b", re.I)
IMPLEMENT_IMPACT_COUNT_NAME = re.compile(r"^(?:number|count|total number|no\.?|#) of\s+", re.I)
_IMPLEMENT_TARGET_TO_RE = re.compile(r"\bto\s+(-?\d[\d,]*(?:\.\d+)?)\s*(?:%|percent)?(?![\w.])", re.I)
_IMPLEMENT_TARGET_BY_RE = re.compile(r"\bby\s+(\d+(?:\.\d+)?)\s*(?:%|percent)(?!\w)", re.I)
_IMPLEMENT_TARGET_DOWN_RE = re.compile(r"\b(?:reduce|cut|lower|decrease|drop|shrink)\b", re.I)


def _kpi_impact_currency(unit: str) -> str:
    return IMPLEMENT_IMPACT_CURRENCY_SIGNS.get(unit) or (unit if unit in INSPIRE_CURRENCY_CODES else "")


def _kpi_impact_guess(name: str, unit: str) -> str:
    lowered, counted = unit.lower(), IMPLEMENT_IMPACT_COUNT_NAME.sub("", name)
    if (_kpi_impact_currency(unit) or lowered in ("money", "currency", "currency units")
            or (not unit and counted == name and IMPLEMENT_IMPACT_MONEY_WORDS.search(name))):
        return "money"
    if lowered in IMPLEMENT_IMPACT_PERCENT_UNITS:
        return "percent"
    if lowered in IMPLEMENT_IMPACT_HOUR_UNITS:
        return "hours"
    if lowered in IMPLEMENT_IMPACT_TIME_UNITS:
        return "number"
    if lowered in IMPLEMENT_IMPACT_COUNT_UNITS or (not unit and counted != name) or re.fullmatch(r"[a-z][a-z ]*[a-z]s", lowered):
        return "count"
    return "number"


def _kpi_impact_label(kind: str, name: str, unit: str) -> str:
    lowered = unit.lower()
    if kind == "money":
        return _kpi_impact_currency(unit)
    if kind == "percent":
        return f"points of {name.lower()}" if name else "points"
    if kind == "hours":
        return "hours"
    if kind == "count":
        if lowered and lowered not in INSPIRE_IMPACT_KINDS and lowered not in IMPLEMENT_IMPACT_COUNT_UNITS:
            return lowered
        return re.sub(r"\s+count$", "", IMPLEMENT_IMPACT_COUNT_NAME.sub("", name), flags=re.I).strip().lower() or "records"
    if lowered in IMPLEMENT_IMPACT_TIME_UNITS:
        return lowered
    return unit if unit and lowered not in INSPIRE_IMPACT_KINDS else name.lower()


def kpi_impact(kpi) -> dict:
    kpi = kpi if isinstance(kpi, dict) else {}
    name, unit = " ".join(str(kpi.get("name") or "").split()), " ".join(str(kpi.get("unit") or "").split())
    declared = " ".join(str(kpi.get("impact_kind") or "").split()).lower()
    kind = declared if declared in INSPIRE_IMPACT_KINDS else unit.lower() if unit.lower() in INSPIRE_IMPACT_KINDS else ""
    if kind:
        source, reason = "definition", f"its definition gives its impact kind, {kind}" + ("" if kind == declared else ", as its unit")
    else:
        kind, source = _kpi_impact_guess(name, unit), "classifier"
        refused = (f" Inspire can use ({declared} is not {', '.join(INSPIRE_IMPACT_KINDS[:-1])} or {INSPIRE_IMPACT_KINDS[-1]})"
                   if declared else "")
        reason = (f"its definition gives no impact kind{refused}, so Inspire read {kind} from "
                  + (f"its unit {unit} and its name" if unit else "its name"))
    return {"kind": kind, "unit": _kpi_impact_label(kind, name, unit), "kpi": name, "from": source, "reason": reason}


def implement_record_impact(record) -> dict:
    if not isinstance(record, dict) or not " ".join(str(record.get("name") or "").split()):
        return dict(INSPIRE_MONEY_IMPACT)
    if record.get("impact_kind") in INSPIRE_IMPACT_KINDS:
        name, unit = " ".join(str(record["name"]).split()), str(record.get("impact_unit") or "")
        if not unit.strip() and record["impact_kind"] != "money":
            unit = _kpi_impact_label(record["impact_kind"], name, " ".join(str(record.get("unit") or "").split()))
        return {"kind": record["impact_kind"], "unit": unit, "kpi": name}
    impact = kpi_impact(record)
    return {key: impact[key] for key in INSPIRE_MONEY_IMPACT}


def implement_pick_kpi(kpis, chosen="") -> tuple:
    named = [k for k in kpis or [] if isinstance(k, dict) and " ".join(str(k.get("name") or "").split())]
    wanted = " ".join(str(chosen or "").split()).casefold()
    for kpi in named:
        if wanted and " ".join(str(kpi["name"]).split()).casefold() == wanted:
            return kpi, "user"
    for kpi in named:
        if kpi.get("kpi_id"):
            return kpi, "inspire"
    for kpi in named:
        if kpi.get("computable"):
            return kpi, "inspire"
    return (named[0], "inspire") if named else (None, "")


def implement_kpi_target(kpi: dict, key_results, baseline=None) -> tuple:
    name, kpi_id = " ".join(str(kpi.get("name") or "").split()).lower(), kpi.get("kpi_id")
    statements = [" ".join(str(kr.get("statement") or "").split()) for kr in key_results or [] if isinstance(kr, dict)
                  and ((kpi_id and kr.get("kpi_id") == kpi_id) or (name and name in str(kr.get("statement") or "").lower()))]
    if not statements:
        return None, ""
    text = statements[0]
    to = _IMPLEMENT_TARGET_TO_RE.search(text)
    if to:
        return float(to.group(1).replace(",", "")), text
    by = _IMPLEMENT_TARGET_BY_RE.search(text)
    if by and baseline is not None:
        down = kpi.get("direction") == "decrease" or (kpi.get("direction") != "increase" and any(
            not negation for _match, negation in inspire_polarity_hits(_IMPLEMENT_TARGET_DOWN_RE, text)))
        share = float(by.group(1)) / 100
        return round(float(baseline) * (1 - share if down else 1 + share), 6), text
    return None, "" if _PLACEHOLDER_UNSET_TARGET_RE.search(text) else text


def implement_text_kpi(raw) -> dict:
    raw = raw if isinstance(raw, dict) else {}
    direction = str(raw.get("direction") or "").strip().lower()
    return {"name": " ".join(str(raw.get("name") or "").split())[:200] or "Not assessed", "kpi_id": None,
            "direction": direction if direction in KPI_DIRECTIONS else "", "unit": str(raw.get("unit") or "")[:40],
            "computable": False, "query": None, "baseline": None, "reason": str(raw.get("reason") or IMPLEMENT_KPI_NOT_COMPUTABLE)}


def implement_assessed_kpi(use_case: dict) -> dict:
    assessment = use_case.get("elite_assessment") if isinstance(use_case.get("elite_assessment"), dict) else {}
    return {"name": assessment.get("kpi") or use_case.get("Name"), "direction": assessment.get("kpi_direction"),
            "reason": "no KPI of this use case could be evaluated from its tables, so the KPI its assessment names is tracked as text"}


def implement_scope_tag(use_case) -> str:
    # The tag of a use case's Table Scope views. The views share one schema per catalog, so the tag carries the session as well as the
    # use case number: two sessions that each have a use case AI04-UC01 never name the same view. A rewrite of a view by another session
    # (CREATE OR REPLACE VIEW) drops the grants the App reads it with (REQ-268).
    number = str((use_case or {}).get("No") or "")
    session = str((use_case or {}).get("_source_session_id") or "").strip()
    return f"{number}_s{session}" if session else number


def implement_use_case_scopes(use_case, involved, database="", columns_of=None) -> dict:
    data = (use_case or {}).get("_implement_data") or {}
    return implement_table_scopes(data, implement_source_tables({"data": data}, involved), database, implement_scope_tag(use_case),
                                  columns_of or implement_scope_columns_of)


def implement_tracked_kpi(kpi: dict, source: str, picked_by: str, key_results=None, use_case=None) -> dict:
    kpi, data = dict(kpi or {}), (use_case or {}).get("_implement_data") or {}
    impact, shown = kpi_impact(kpi), kpi_baseline_shown(kpi.get("baseline"), kpi)
    baseline = inspire_kpi_number((shown or {}).get("value"))
    target, target_text = implement_kpi_target(kpi, key_results, baseline)
    target_text = inspire_placeholder_words(kpi_without_stale_baselines(target_text, [kpi]))
    record = {"name": " ".join(str(kpi.get("name") or "").split()), "source": source, "picked_by": picked_by, "kpi_id": kpi.get("kpi_id"),
              "direction": kpi.get("direction") or "", "unit": str(kpi.get("unit") or ""), "impact_kind": impact["kind"],
              "impact_unit": impact["unit"], "impact_from": impact["from"], "impact_reason": impact["reason"], "computable": False,
              "query": None, "reason": "", "baseline": baseline, "baseline_on": (shown or {}).get("measured_on"), "baseline_reason": "",
              "prior_rows": False, "target": target, "target_text": target_text}
    table = _implement_plain_table(kpi.get("table") or "") if kpi.get("table") else ""
    removed = {_implement_plain_table(t).lower() for t in data.get("removed_tables") or []}
    swaps = {_implement_plain_table(o).lower(): _implement_plain_table(c) for o, c in (data.get("tables") or {}).items()}
    mismatch = kpi_filter_mismatch(kpi)
    if not kpi.get("computable"):
        record["reason"] = " ".join(str(kpi.get("reason") or "").split()) or IMPLEMENT_KPI_NOT_COMPUTABLE
    elif mismatch:
        record["reason"] = mismatch
    elif table and table.lower() in removed:
        record["reason"] = f"it reads {table}, which you removed from this use case"
    else:
        measured_on = swaps.get(table.lower(), table) if table else ""
        try:
            scopes = implement_use_case_scopes(use_case, [measured_on] if table else [])
            record.update(computable=True, query=DeepEvidence.kpi_sql(dict(kpi, table=measured_on) if table else kpi, scopes))
        except (ValueError, KeyError, TypeError) as error:
            record.update(computable=False, reason=f"Inspire cannot build its query: {redact_error(error)}")
        if record["computable"] and baseline is not None and measured_on.lower() != table.lower():
            record["baseline_reason"] = (f"its baseline was measured on {table}, but it is measured now on {measured_on}, which you chose "
                                         "in its place, so the baseline and the latest value come from different tables")
    return record


def implement_inspire_target_kpi(use_case: dict):
    kpi, picked_by = implement_pick_kpi(use_case.get("KPIs") or [])
    if kpi is None:
        return None
    return implement_tracked_kpi(kpi, "inspire", picked_by, use_case.get("Expected Key Results"), use_case)


def implement_run_kpi(record: dict) -> dict:
    return {key: record.get(key) for key in ("name", "source", "direction", "unit", "computable", "query", "reason", "baseline",
                                             "baseline_on", "baseline_reason", "prior_rows", "target", "target_text")}


def implement_kpi_prior_rows(prior, record) -> bool:
    if not (isinstance(prior, dict) and isinstance(record, dict) and prior.get("computable") and record.get("computable")
            and record.get("query")) or ("prior_rows" in prior and not prior["prior_rows"]):
        return False
    return all(" ".join(str(prior.get(key) or "").split()) == " ".join(str(record.get(key) or "").split())
               for key in ("name", "unit", "query"))


def implement_kpi_choice(spec) -> str:
    return " ".join(str(((spec or {}).get("kpi") or {}).get("target") or "").split()).casefold()


def implement_kpi_recorded(stored, record: dict, impact: dict):
    if not isinstance(stored, dict) or not isinstance(record, dict):
        return stored
    kept = stored.get("kpi") if isinstance(stored.get("kpi"), dict) else {}
    return dict(stored, kpi=dict(kept, target=str(kept.get("target") or ""), tracked=record["name"], source=record["source"],
                                 picked_by=record["picked_by"], computable=record["computable"], impact_kind=impact["kind"],
                                 impact_unit=impact["unit"]))


def implement_kpi_prompt(use_case: dict, tables: dict, spec: dict) -> str:
    framing, data = implement_build_framing(spec), (spec or {}).get("data") or {}
    directives = ([f"- Goal: {framing['goal']}"] if framing.get("goal") else []) + [
        f"- Success measure: {m}" for m in framing.get("success_measures") or []] + (
        [f'- The customer\'s asks for this notebook, word for word: """{data["notes"]}"""'] if data.get("notes") else [])
    lines = ["# TARGET KPI OF ONE USE CASE", "",
             "You are a principal business analyst. This use case has no KPI yet. Define the 1 to 3 KPIs that best measure whether "
             "its decision works, best first: the first one is the target KPI the use case's results are counted in, so it is the "
             "quantity the decision moves (money only when the decision moves money; hours saved, incidents avoided, records at risk "
             "or a rate otherwise).", "",
             "## USE CASE",
             f"Name: {inspire_plain_text(use_case.get('Name'))}",
             f"Statement: {inspire_plain_text(use_case.get('Statement'))[:600]}",
             f"Solution: {inspire_plain_text(use_case.get('Solution'))[:800]}",
             f"Business value: {inspire_plain_text(use_case.get('Business Value'))[:600]}",
             f"Analytics technique: {inspire_plain_text(use_case.get('Analytics Technique'))}", "",
             "## THE USER'S DIRECTIVES",
             *(directives or ["(none)"]),
             "When the user's directives name what this use case must improve, the first KPI measures exactly that, in its unit: the "
             "user's words win over every rule below.", "",
             "## TABLES"]
    lines += [f"- `{fqn}`: " + ", ".join(f"{column} {kind.lower()}" for column, kind in list(columns.items())[:60])
              for fqn, columns in list(tables.items())[:8]] or ["(none)"]
    lines += ["", "## METRIC VIEWS", "(none for this build: define every KPI from the tables above)", "",
              "## RULES", "1. " + KPI_DEFINITION_RULE,
              "2. This build has no strategy KPIs, so `kpi_id` is always null.",
              "3. **IMPACT KIND**: `impact_kind`: money, count, hours, percent or number, the kind of quantity the KPI counts, so each "
              "record's impact on the KPI is counted in that kind: money only when the KPI is money.",
              "4. **PUNCTUATION**: " + NO_EM_DASH_RULE, "",
              "## OUTPUT",
              'Return ONLY a JSON object: {"kpis": [{"name": "<KPI name>", "direction": "decrease", "unit": "hours", "impact_kind": "hours", '
              '"metric_view": '
              'null, "measure": null, "aggregation": "SUM", "table": "<catalog>.<schema>.<table>", "column": "<column>", '
              '"filter_column": null, "filter_op": null, "filter_value": null, "time_column": "<date column>", "window_days": 30}]}']
    return USER_DIRECTIVE_SUPREMACY_PREAMBLE + "\n".join(lines) + "\n"


IMPLEMENT_APP_TOUR_SCHEMA = {"type": "object", "properties": {"tours": {"type": "array", "items": {"type": "object", "properties": {
    "language": {"type": "string"}, "steps": {"type": "array", "items": {"type": "object", "properties": {
        "anchor": {"type": "string"}, "title": {"type": "string"}, "text": {"type": "string"}},
        "required": ["anchor", "title", "text"]}}}, "required": ["language", "steps"]}}}, "required": ["tours"]}


def implement_app_tour_prompt(use_case: dict, spec: dict, page: dict, registry: dict, anchors: list, languages: list) -> str:
    framing, data = implement_build_framing(spec), (spec or {}).get("data") or {}
    directives = ([f"- Goal: {framing['goal']}"] if framing.get("goal") else []) + [
        f"- Success measure: {m}" for m in framing.get("success_measures") or []] + (
        [f'- The customer\'s asks for this App, word for word: """{data["notes"]}"""'] if data.get("notes") else [])
    meanings = registry.get("anchors") or {}
    kpis = [k for k in (page.get("kpis") or []) if isinstance(k, dict) and k.get("id")]
    records = (page.get("records") or {}).get("label_title") if isinstance(page.get("records"), dict) else ""
    least, most = int(registry.get("least") or 5), int(registry.get("most") or 8)
    lines = ["# GUIDED TOUR OF ONE DECISION APP", "",
             f"You are a principal business analyst writing the {least} to {most} step guided tour a business user takes the first "
             "time they open this App. Each step points at one part of the page and says, in the business words of this use case, "
             "what it means for the decision and what to do there. Cover the decision the App supports, what the key numbers mean, "
             "where to start (the top record), how to act on a record and on many at once, the filters, Ask Genie and alerts, "
             "where this page shows them.", "",
             "## USE CASE",
             f"Name: {inspire_plain_text(use_case.get('Name'))}",
             f"Statement: {inspire_plain_text(use_case.get('Statement'))[:600]}",
             f"Solution: {inspire_plain_text(use_case.get('Solution'))[:600]}",
             f"Business value: {inspire_plain_text(use_case.get('Business Value'))[:600]}", "",
             "## THE USER'S DIRECTIVES",
             *(directives or ["(none)"]),
             "When the user's directives say what the App is for or how its people work, the tour says exactly that: the user's "
             "words win over every rule below.", "",
             "## THE PAGE",
             f"Title: {inspire_plain_text(page.get('title'))}",
             f"Question it answers: {inspire_plain_text(page.get('question'))}",
             f"Each record on its list is: {inspire_plain_text(records) or 'a record'}",
             "Key numbers: " + ("; ".join(f"`{k['id']}` shown as {inspire_plain_text(k.get('label'))}" for k in kpis) or "(none)"), "",
             "## PARTS THIS PAGE SHOWS (use only these anchors, at most one step each)"]
    lines += [f"- `{a}`: {meanings.get(a, a)}" for a in anchors]
    lines += ["", "## LIVE VALUES",
              "The text (never the title) may hold these placeholders, which the App fills from the data the viewer sees; a sentence "
              "whose value has not loaded is dropped, so each placeholder sits in a sentence that may go without breaking the step:",
              "- `{open_count}`: how many records are open now",
              "- `{top_record}`: the name of the first record on the list"]
    lines += [f"- `{{kpi:{k['id']}}}`: the value of {inspire_plain_text(k.get('label'))} now" for k in kpis]
    lines += ["", "## RULES",
              f"1. **LENGTH**: {least} to {most} steps; each title at most {registry.get('title_chars', 60)} characters, each text at "
              f"most {registry.get('text_chars', 220)} characters with the placeholders filled.",
              "2. **PLAIN WORDS**: business words only. Never a column id, a table name, a snake_case or camelCase word, code, "
              "backticks or SQL. Name the key numbers by their shown names.",
              "3. **PLACEHOLDERS**: only the ones listed above, written exactly so, and only in the text.",
              "4. **LANGUAGES**: write one tour per language, with the same anchors, each fully in that language: "
              + ", ".join(languages) + ".",
              "5. **PUNCTUATION**: " + NO_EM_DASH_RULE, "",
              "## OUTPUT",
              'Return ONLY a JSON object: {"tours": [{"language": "<language>", "steps": [{"anchor": "<anchor>", "title": "<title>", '
              '"text": "<text>"}]}]}']
    return USER_DIRECTIVE_SUPREMACY_PREAMBLE + "\n".join(lines) + "\n"


def implement_app_tour_written(reply: dict, languages: list) -> dict:
    wanted = {str(language).strip().lower(): language for language in languages}
    steps = {}
    for tour in (reply or {}).get("tours") or []:
        if not isinstance(tour, dict):
            continue
        language = wanted.get(str(tour.get("language") or "").strip().lower())
        if language and language not in steps and isinstance(tour.get("steps"), list):
            steps[language] = tour["steps"]
    if not steps:
        raise ValueError("the model wrote no tour in any output language")
    return {"languages": list(languages), "steps": steps}


