IMPLEMENT_FOCUS_DATA_FILES = ("focus_spec.py", "focus_spec.schema.json", "focus_defaults.json")
IMPLEMENT_FOCUS_NUMBER_FORMATS = ("number", "integer", "currency", "percent")
IMPLEMENT_FOCUS_KEY_ROLES = ("key", "label", "sublabel", "tier", "reasons", "action", "rank")


def implement_focus_kind(use_case: dict) -> str:
    """The technique kind id of a use case ('' when its technique maps to none), read from the kinds registry."""
    mapping = _inspire_kinds()["technique_kind"]
    technique = str((use_case or {}).get("Analytics Technique") or "")
    key = _technique_registry_key(technique, mapping) if technique else None
    return str(mapping[key]) if key is not None else ""


def implement_focus_columns(page: dict) -> list:
    """The columns a record of this page carries, as [{name, type, role}] with type number, string or date. The names are the select list
    of the page's records dataset; the type comes from the format the page shows the column in, or from an aggregate that reads it."""
    page = page if isinstance(page, dict) else {}
    records = page.get("records") if isinstance(page.get("records"), dict) else {}
    sql = next((str(d.get("sql") or "") for d in page.get("datasets") or [] if isinstance(d, dict) and d.get("name") == "records"), "")
    head = re.match(r"\s*SELECT\s+(.*?)\s+FROM\s", sql, flags=re.I | re.S)
    names, depth, item = [], 0, ""
    for char in (head.group(1) if head else "") + ",":
        if char == "," and depth == 0:
            found = re.findall(r"[A-Za-z_]\w*", re.sub(r"`", "", item))
            if found and "*" not in item:
                names.append(found[-1])
            item = ""
            continue
        depth += (char == "(") - (char == ")")
        item += char
    formats = {}
    for entry in list(records.get("columns") or []) + list(records.get("detail") or []):
        if isinstance(entry, dict) and entry.get("column"):
            formats.setdefault(str(entry["column"]), str(entry.get("format") or "text"))
    summed = {m.group(2) for k in page.get("kpis") or [] if isinstance(k, dict)
              for m in re.finditer(r"\b(SUM|AVG|MIN|MAX)\(\s*([A-Za-z_]\w*)\s*\)", str(k.get("expression") or ""), flags=re.I)}
    roles = {str(records[field]): field for field in IMPLEMENT_FOCUS_KEY_ROLES if isinstance(records.get(field), str)}
    out = []
    for name in dict.fromkeys(names):
        shown = formats.get(name)
        kind = ("number" if shown in IMPLEMENT_FOCUS_NUMBER_FORMATS or (shown is None and (name in summed or roles.get(name) == "rank"))
                else "string" if shown in (None, "text") else "date")
        out.append({"name": name, "type": kind, "role": roles.get(name) or {"number": "measure", "date": "date"}.get(kind, "category")})
    return out


def implement_focus_catalog(rules: dict, kind: str) -> dict:
    return {"kind": kind, "blocks": {b: (rules.get("block_use_when") or {}).get(b, "") for b in rules["blocks"]},
            "motions": {m: (rules.get("motion_use_when") or {}).get(m, "") for m in rules["motions"]},
            "block_roles": rules["block_roles"], "actions": list(rules["default_actions"]), "caps": rules["caps"]}


def implement_focus_examples(defaults: dict, kind: str, count: int = 3) -> list:
    """Worked examples from the shipped defaults: kinds other than this one, each with its own block sequence, in an order that depends on this kind."""
    others = sorted(k for k in defaults if k != kind)
    start = sum(ord(c) for c in kind) % len(others) if others else 0
    picked, seen = [], set()
    for other in others[start:] + others[:start]:
        sequence = tuple(s["visual"]["block"] for s in defaults[other]["steps"])
        if sequence not in seen:
            seen.add(sequence)
            picked.append({"kind": other, "spec": defaults[other]})
        if len(picked) == count:
            break
    return picked


def implement_focus_sequence(spec: dict) -> tuple:
    return tuple(str((s.get("visual") or {}).get("block")) for s in (spec or {}).get("steps") or [] if isinstance(s, dict))


def implement_app_focus_prompt(use_case: dict, spec: dict, page: dict, columns: list, catalog: dict, examples: list, kind: str = "",
                               note: str = "") -> str:
    framing, data = implement_build_framing(spec), (spec or {}).get("data") or {}
    directives = ([f"- Goal: {framing['goal']}"] if framing.get("goal") else []) + [
        f"- Success measure: {m}" for m in framing.get("success_measures") or []] + (
        [f'- The customer\'s asks for this page, word for word: """{data["notes"]}"""'] if data.get("notes") else [])
    kind = kind or catalog.get("kind") or ""
    records = (page.get("records") or {}).get("title") if isinstance(page.get("records"), dict) else ""
    caps = catalog.get("caps") or {}
    lines = ["# DESIGN THE GUIDED FOCUS OF ONE DECISION PAGE", "",
             "You design the short guided run a business user takes when they open one record of this page. Each step answers one plain "
             "question about the record with one visual block and one motion. The page draws your design with a fixed library, so you "
             "only choose from the lists below and never invent a block, a motion or a column.", "",
             "## USE CASE",
             f"Name: {inspire_plain_text(use_case.get('Name'))}",
             f"Statement: {inspire_plain_text(use_case.get('Statement'))[:600]}",
             f"Solution: {inspire_plain_text(use_case.get('Solution'))[:600]}",
             f"Business value: {inspire_plain_text(use_case.get('Business Value'))[:600]}",
             f"Technique kind: {kind}", "",
             "## THE USER'S DIRECTIVES",
             *(directives or ["(none)"]),
             "The user's explicit input wins over every rule below. When it says what the page is for or how its people work, design for that.", "",
             "## THE PAGE",
             f"Title: {inspire_plain_text(page.get('title'))}",
             f"Question it answers: {inspire_plain_text(page.get('question'))}",
             f"Each record on its list is: {inspire_plain_text(records) or 'a record'}", "",
             "## COLUMNS (bind a block role only to one of these names, and only when its type is the type the role asks for)"]
    lines += [f"- `{c['name']}` ({c['type']}, {c['role']})" for c in columns]
    lines += ["", "## BLOCKS (the roles of each block are the keys of its bind)"]
    lines += [f"- `{b}` (" + ", ".join(f"{r}: {t}" for r, t in (catalog.get("block_roles") or {}).get(b, {}).items()) + f"): use when {why}"
              for b, why in catalog["blocks"].items()]
    lines += ["", "## MOTIONS"] + [f"- `{m}`: use when {why}" for m, why in catalog["motions"].items()]
    lines += ["", "## WORKED EXAMPLES (other kinds of use case; copy the shape of the work, never its content or its column names)"]
    for example in examples:
        lines += [f"Example kind: {example['kind']}", "Example spec: " + json.dumps(example["spec"], ensure_ascii=False, separators=(",", ":"))]
    lines += ["", "## HOW TO WORK, IN THIS ORDER",
              f"1. QUESTIONS FIRST: write the {caps.get('steps', [2, 5])[0]} to {caps.get('steps', [2, 5])[1]} plain-word questions this "
              "user asks about one record, one per step, in the order they would ask them. Put them in `questions`.",
              "2. PICK A BLOCK AND A MOTION: for each question pick the one block that answers it best and the one motion that makes the "
              "answer land, using the use-when lines. Bind each role of the block to a column of the right type. Each step is a "
              "JSON object with id, question, kind, visual {block, bind}, answer_template, terms, motion and ask.",
              f"3. DECIDE LAST: the last step has kind decide. The `decide` object lists 1 to {caps.get('choices', [1, 4])[1]} choices, each with "
              "label, detail and action, and the action is one of: " + ", ".join(catalog.get("actions") or []) + ".", "",
              "## RULES",
              f"- At most {caps.get('question_words', 12)} words per question, {caps.get('answer_template_words', 20)} per answer template, "
              f"{caps.get('ask_words', 12)} per ask line; each step has {caps.get('ask', [2, 3])[0]} to {caps.get('ask', [2, 3])[1]} ask lines.",
              "- Plain business words only: never a column name, a table name, code or SQL in any text the user reads.",
              "- Vary the visual story: do not give every step the same block, and do not copy an example's block order.",
              "- The queue names the open records, ordered by one of the columns above, with an optional cohort column.",
              f"- The spec has version 1, technique_kind {kind}, a tour of 1 to 5 stops, a queue, the steps and the decide object.",
              "- " + NO_EM_DASH_RULE]
    if note:
        lines += ["", "## REDESIGN", "Your last design was not accepted. Fix exactly this and keep what worked:", note]
    lines += ["", "## OUTPUT",
              'Return ONLY a JSON object: {"questions": ["<question>"], "focus_spec": {<the spec>}}']
    return "\n".join(lines) + "\n"


def implement_app_focus_judge_prompt(spec: dict, use_case: dict) -> str:
    steps = [{"id": s.get("id"), "question": s.get("question"), "block": (s.get("visual") or {}).get("block"),
              "answer_template": s.get("answer_template"), "ask": s.get("ask")}
             for s in (spec or {}).get("steps") or [] if isinstance(s, dict)]
    lines = ["# JUDGE A GUIDED FOCUS", "",
             "You are a new user of this page. You see each step for 10 seconds. Score each step from 1 to 5 on this one test: "
             "can you say what you see, why it matters and what to do next? 5 means all three at once, 3 means one is missing, 1 means none.",
             "",
             "## USE CASE",
             f"Name: {inspire_plain_text((use_case or {}).get('Name'))}",
             f"Statement: {inspire_plain_text((use_case or {}).get('Statement'))[:600]}", "",
             "## THE STEPS",
             json.dumps(steps, ensure_ascii=False, indent=1), "",
             "## RULES",
             "- Score every step once, by its id, and give a one-sentence reason for each score below 4 that says what to change.",
             "- " + NO_EM_DASH_RULE, "",
             "## OUTPUT",
             'Return ONLY a JSON object: {"steps": [{"id": "<step id>", "score": <1 to 5>, "reason": "<reason>"}]}']
    return "\n".join(lines) + "\n"


def implement_focus_low_steps(reply: dict, spec: dict) -> list:
    """The judge's reasons for every step scored below 4; a step the judge left out counts as unscored."""
    scored = {str(s.get("id")): s for s in (reply or {}).get("steps") or [] if isinstance(s, dict)}
    low = []
    for step in (spec or {}).get("steps") or []:
        got = scored.get(str(step.get("id")))
        score = got.get("score") if got else None
        if not isinstance(score, (int, float)) or isinstance(score, bool):
            low.append(f"step {step.get('id')} was not scored")
        elif score < IMPLEMENT_FOCUS_JUDGE_PASS:
            low.append(f"step {step.get('id')} scored {int(score)}: {' '.join(str(got.get('reason') or 'no reason given').split())}")
    return low


def implement_focus_rebind(default: dict, placeholders: dict, columns: list):
    """The kind's default spec with its placeholder columns re-bound to this page's columns by role, then by type: (spec, '') or (None, reason)."""
    spec, chosen, used = json.loads(json.dumps(default)), {}, set()

    def pick(placeholder):
        if placeholder in chosen:
            return chosen[placeholder]
        want = placeholders.get(placeholder)
        pool = [c for c in columns if c["type"] == want]
        found = (next((c for c in pool if c["role"] == placeholder), None) or next((c for c in pool if c["name"] not in used), None)
                 or next(iter(pool), None))
        if found is None:
            raise ValueError(f"the page has no {want} column for {placeholder}")
        used.add(found["name"])
        chosen[placeholder] = found["name"]
        return found["name"]

    try:
        for step in spec["steps"]:
            bind = step["visual"]["bind"]
            for role in bind:
                bind[role] = pick(bind[role])
        order = spec["queue"]["order"]
        order["column"] = pick(order["column"])
        if spec["queue"].get("cohort_column"):
            spec["queue"]["cohort_column"] = pick(spec["queue"]["cohort_column"])
    except ValueError as error:
        return None, redact_error(error)
    return spec, ""


def implement_preview_training_cap(spec: dict, trains_model: bool = True):
    data, profiles = (spec or {}).get("data") or {}, ((spec or {}).get("config") or {}).get("profiles") or {}
    window, training = data.get("window") or {}, profiles.get("training") or {}
    if (not trains_model or window.get("start") or window.get("end") or data.get("filters") or training.get("window_days")
            or training.get("sample_entities")):
        return None
    return IMPLEMENT_PREVIEW_TRAINING_FACTOR * int((profiles.get("preview") or {}).get("entity_cap") or IMPLEMENT_PREVIEW_ENTITY_CAP)


def implement_training_sample_checked(spec: dict, cap) -> bool:
    data, config = (spec or {}).get("data") or {}, (spec or {}).get("config") or {}
    return bool(cap) and not str(data.get("notes") or "").strip() and not config.get("widgets")


INSPIRE_FITTED_BY_CONTROL_FAMILIES = ("I",)  # causal impact, uplift and mix models fit a control or pre-period model on their read
INSPIRE_FITTED_FUNCTION_TECHNIQUES = ("Regression Analysis", "Trend Analysis")  # F techniques that fit a slope or trend line to the rows
INSPIRE_FITTING_FAMILIES = frozenset(
    [family for family, spec in GENIE_FAMILY_SPECS.items() if re.search(r"\b(fits?|refits?|trains?)\b", str(spec.get("pattern") or ""))]
    + list(INSPIRE_FITTED_BY_CONTROL_FAMILIES))
INSPIRE_FITTING_TECHNIQUES = frozenset(
    [t for t, family in TECHNIQUE_EXECUTION_FAMILY.items() if family in INSPIRE_FITTING_FAMILIES] + list(INSPIRE_FITTED_FUNCTION_TECHNIQUES))


def implement_fits_a_model(use_case) -> bool:
    """True when the technique fits a model on the rows it reads (its coefficients or slopes come from the data)."""
    return str((use_case or {}).get("Analytics Technique") or "").strip() in INSPIRE_FITTING_TECHNIQUES

def implement_training_read_checked(spec: dict, spec_nb: dict, trains_model) -> bool:
    return bool(trains_model and (spec_nb or {}).get("first_run")
                and not str(((spec or {}).get("data") or {}).get("notes") or "").strip())


def implement_preview_sample_text(outcome) -> str:
    entities = (outcome or {}).get("preview_sample_entities") if (outcome or {}).get("status") == "written" else None
    if not entities:
        return ""
    return (f"the model was checked on a preview sample of {inspire_plural(int(entities), 'entity', 'entities')}, and the scheduled full run trains on every "
            "entity")


def _implement_choice_lines(spec: dict, trains_model: bool = True, impact=None) -> list:
    stake = inspire_stake_words(impact)
    data, config = spec.get("data") or {}, spec.get("config") or {}
    lines = []
    framing = implement_build_framing(spec)
    if framing.get("goal"):
        lines.append(f"- Goal: {framing['goal']}" + (IMPLEMENT_GOAL_SCOPE_NOTE if isinstance(data.get("filters"), list) else ""))
    if framing.get("decision_owner"):
        lines.append(f"- Decision owner: {framing['decision_owner']}")
    for measure in framing.get("success_measures") or []:
        lines.append(f"- Success measure: {measure}")
    for original, chosen in sorted((data.get("tables") or {}).items()):
        lines.append(f"- Read `{chosen}` wherever this instruction reads `{original}`; it has the same role. Check its columns with "
                     f"DESCRIBE TABLE first and map each column the instruction uses to its real name in `{chosen}`.")
    for table in data.get("removed_tables") or []:
        lines.append(f"- Do not read `{table}`: the user removed it from this use case. Build every step from the other tables and "
                     "leave out the features that only it provided.")
    for table in data.get("dropped_tables") or []:
        lines.append(f"- Do not read `{table}`: it is missing or cannot be read right now, so Inspire left it out. Build every step "
                     "from the other tables and leave out the features that only it provided.")
    for item in data.get("filters") or []:
        values = ", ".join(repr(v) for v in item["values"])
        lines.append(f"- Keep only the rows of `{item['table']}` where `{item['column']}` {item['op']} {values}, applied when the "
                     "table is first read, before any join.")
    if isinstance(data.get("filters"), list):
        lines.append(IMPLEMENT_KEPT_SCOPE_RULE if data["filters"] else IMPLEMENT_WHOLE_DATA_RULE)
    formula = implement_asset_vibes(spec.get("outputs"), IMPLEMENT_NOTEBOOK).get("value_formula")
    if formula:
        lines.append(f"- The customer's asks for the {stake} formula, word for word: \"\"\"{formula}\"\"\" They are explicit "
                     f"user directives for `{INSPIRE_VALUE_FORMULA_NAME}` and the value_at_stake it explains, and win over the "
                     "value_at_stake rule above; apply them to that formula alone.")
    for role, ref in sorted((data.get("column_roles") or {}).items()):
        if role == "entity_id":
            table, column = ".".join(ref.split(".")[:3]), ref.split(".")[-1]
            lines.append(f"- Use `{ref}` as the entity id column: the user chose it, so one row of the business output is one "
                         f"`{column}`; when `{table}` holds several rows for one `{column}`, group them into that one row and build "
                         "its values from all of them.")
        elif role != "label" or trains_model:
            lines.append(f"- Use `{ref}` as the {role.replace('_', ' ')} column.")
    limit = implement_act_now_capacity(spec.get("capacity"))
    if limit:
        lines.append(f"- Team capacity: the team acts on at most {inspire_plural(limit, 'row')} in 'Act now' each run. Write each row's tier by the use "
                     f"case's rule and never cap the tiers yourself: inspire_write_result keeps the top {implement_number_text(limit)} by rank in 'Act now' "
                     "and moves the rest to 'Review', and the App says how many the capacity holds back.")
    window = data.get("window") or {}
    if window.get("start") or window.get("end"):
        lines.append(f"- Read history from {window.get('start') or 'the earliest date'} to {window.get('end') or 'the latest date'} only.")
    profiles = config.get("profiles") or {}
    training, full_load = profiles.get("training") or {}, profiles.get("full_load") or {}
    if training and trains_model:
        parts = [f"the last {training['window_days']} days" if training.get("window_days") else "",
                 f"a sample of {training['sample_entities']} entities" if training.get("sample_entities") else "",
                 f"stratified by `{training['stratify_by']}`" if training.get("stratify_by") else ""]
        lines.append("- Training profile: " + ", ".join(p for p in parts if p) + ".")
    if full_load.get("window_days"):
        lines.append(f"- Full-load profile: score with the last {full_load['window_days']} days of data, as_of_date = latest.")
    retrain = profiles.get("retrain") or {}
    if retrain and trains_model:
        rules = [f"every {retrain['every_runs']} full runs" if retrain.get("every_runs") else "",
                 f"when drift exceeds {retrain['drift_threshold']}" if retrain.get("drift_threshold") else ""]
        lines.append("- Retrain the model " + " or ".join(r for r in rules if r) + "; otherwise reuse the last trained model.")
    if config.get("result_table"):
        own = f"use_case_id = '{spec['use_case_id']}'" if spec.get("use_case_id") else "use_case_id is this use case's id"
        lines.append(f"- Write the business output to `{config['result_table']}` (the default of the `result_table` widget), only with "
                     f"inspire_write_result(frame, result_table): each run's rows, where {own}, become the current version of their "
                     "records, earlier versions stay as change history, and rows of other use cases stay.")
    if config.get("ai_endpoint"):
        lines.append(f"- Use the serving endpoint `{config['ai_endpoint']}` (the default of the `ai_endpoint` widget).")
    lines.append(implement_preview_budget_rule(trains_model))
    stale_scope = implement_scope_stale(config.get("widgets"))
    for name, value in sorted((config.get("widgets") or {}).items()):
        if name not in stale_scope:
            lines.append(f"- Default of widget `{name}`: `{value}`.")
    cap = (profiles.get("preview") or {}).get("entity_cap") or IMPLEMENT_PREVIEW_ENTITY_CAP
    if trains_model:
        profile_rule = ("The training profile is the history the model learns from; the full-load profile is every entity scored by "
                        f"a production run. With `preview`, train on the training profile and score at most {inspire_plural(cap, 'entity', 'entities')}, so a run "
                        "finishes in minutes; with `full`, train on the whole training profile and score the whole full-load profile. "
                        "The First run narrows only the records a run scores, never the training profile: read the rows the model "
                        "trains on with `inspire_read_source('<catalog>.<schema>.<table>', purpose='training')`.")
    else:
        profile_rule = ("The full-load profile is every entity a production run covers. With `preview`, cover at most "
                        f"{inspire_plural(cap, 'entity', 'entities')}, so a run finishes in minutes; with `full`, cover the whole full-load profile.")
    lines.append("- Add a dropdown widget `run_profile` with the choices `preview` and `full` and the default `full`, in the Parameters "
                 f"cell. {profile_rule} {IMPLEMENT_PREVIEW_SPREAD_RULE} Both write the same columns.")
    sample = implement_preview_training_cap(spec, trains_model)
    if sample:
        lines.append(f"- Preview training sample: the user set no data window, training profile or row filter, so the training profile "
                     f"is the whole history, and a preview trains on at most {implement_number_text(sample)} of its entities, "
                     f"{IMPLEMENT_PREVIEW_TRAINING_FACTOR} times the {implement_number_text(cap)} it scores. Pass the training rows, one Spark DataFrame with "
                     "every column the model learns from and before any toPandas, through `inspire_training_sample(frame, key)`, which "
                     "the Run controls cell defines, right before the model reads them, with `key` the entity key column or a list of "
                     "key columns. In a preview it keeps the entities with the lowest stable hash of the key, so every preview of the "
                     "same data trains on the same ones, and records how many for the App; in a `full` run it returns every row, so a "
                     "full run trains on all of them. Never cut the training rows of a preview another way. If the customer's asks for "
                     "this notebook, or a widget value the user set above, say how much history or which entities the model trains on, "
                     "they are explicit user directives and win: train on what they say, without inspire_training_sample.")
    if data.get("notes"):
        lines.append(f"- The customer's asks for this notebook, word for word: \"\"\"{data['notes']}\"\"\" They are explicit user "
                     f"directives and win over anything above that conflicts with them; Inspire's checks on the notebook still run, "
                     f"and {IMPLEMENT_ASK_NOT_A_STOP}.")
    return lines


def implement_job_parameters(widget_names, spec: dict, profile: str, session_id="") -> dict:
    config = spec.get("config") or {}
    params = {}
    names = list(widget_names or [])
    for name, value in (config.get("widgets") or {}).items():
        if name in names:
            params[name] = str(value)
    if config.get("result_table") and "result_table" in names:
        params["result_table"] = config["result_table"]
    if config.get("ai_endpoint") and "ai_endpoint" in names:
        params["ai_endpoint"] = config["ai_endpoint"]
    params["run_profile"] = profile if profile in IMPLEMENT_RUN_PROFILES else "preview"
    params[IMPLEMENT_REFRESH_PARAMETER] = IMPLEMENT_REFRESH_DEFAULT
    params[INSPIRE_CHILD_MARKER] = "1"
    if session_id:
        params[INSPIRE_SESSION_WIDGET] = str(session_id)
    return params


_IMPLEMENT_OUTCOME_COUNT = r"(\d{1,3}(?:,\d{3})+|\d+)"
_IMPLEMENT_OUTCOME_RE = re.compile(r"wrote " + _IMPLEMENT_OUTCOME_COUNT + r" (?:rows?|row\(s\)) for as_of_date (\S+) with run_id ([0-9a-fA-F-]{8,})(?:"
                                   + re.escape(INSPIRE_PREVIEW_SAMPLE_TEXT).replace(re.escape("{entities}"), _IMPLEMENT_OUTCOME_COUNT) + ")?")


def parse_use_case_outcome(text) -> dict:
    text = str(text or "")
    match = _IMPLEMENT_OUTCOME_RE.search(text)
    if match:
        skips = inspire_companion_skips(text)
        return {"status": "written", "rows_written": int(match.group(1).replace(",", "")), "as_of_date": match.group(2), "run_id": match.group(3),
                **({"preview_sample_entities": int(match.group(4).replace(",", ""))} if match.group(4) else {}),
                **({"companion_skips": skips} if skips else {})}
    stopped = re.search(r"stopped without writing: (.*)", text)
    if stopped:
        return {"status": "stopped", "stop_reason": stopped.group(1).strip()}
    return {"status": "unknown", "text": text[:500]}


def implement_widget_problems(widgets, values) -> list:
    known = [w for w in widgets or [] if isinstance(w, dict)]
    allowed = {str(w.get("name")): w.get("allowed") for w in known}
    problems = [problem for name, value in sorted((values or {}).items())
                for problem in [genie_widget_value_problem(name, value, allowed.get(name, ""))] if problem]
    merged = {str(w.get("name")): w.get("default") for w in known}
    merged.update(values or {})
    return problems + genie_widget_set_problems(merged)


def implement_hidden_text(text) -> str:
    # The redactor shows a value it hides as the placeholder; Genie reads feedback as text, so the placeholder is named, never sent as a value.
    text = str(text or "")
    return INSPIRE_REDACTED_PATTERN.sub("a value Inspire hid (not a real value)", text)


def implement_placeholder_default(name: str, planned, allowed) -> str:
    # A placeholder is never a value: keep the planned default, else Whole data for Data groups, else the lowest value the range allows.
    planned = str(planned or "").strip()
    if planned and not inspire_is_redacted(planned):
        return planned
    if name == INSPIRE_GROUP_BY:
        return INSPIRE_SETTING_ALL
    low = genie_rule_parts(genie_allowed_rule(allowed))[0]
    return "" if low is None else _genie_number_text(int(low) if float(low).is_integer() else low)


_GENIE_ALLOWED_BOUND_REF_RE = re.compile(r"((?:whole number, )?)at least ([A-Za-z_][A-Za-z0-9_]*)")


def normalize_genie_fill_widgets(result, core_widgets) -> list:
    core = {w["name"]: w.get("allowed") or "" for w in core_widgets or []}
    planned = {str(w.get("name") or ""): w.get("default") for w in core_widgets or [] if isinstance(w, dict)}
    problems = []
    for widget in (result.get("widgets") or []) if isinstance(result, dict) else []:
        if not isinstance(widget, dict):
            continue
        name = str(widget.get("name") or "")
        if inspire_is_redacted(str(widget.get("default") or "")):
            widget["default"] = implement_placeholder_default(name, planned.get(name), core.get(name) or widget.get("allowed"))
            print(f"[PLACEHOLDER-DEFAULT FIRED] widget {name} held the redacted placeholder as its default; Inspire set it to "
                  f"{widget['default'] or 'empty'}", flush=True)
        # REQ-295: a bound that names another widget ("whole number, at least k_min") is read as that widget's default, so the range is a
        # readable form and the repair does not loop on it.
        bound = _GENIE_ALLOWED_BOUND_REF_RE.fullmatch(str(widget.get("allowed") or "").strip())
        other = next((w for w in (result.get("widgets") or []) if isinstance(w, dict) and bound and str(w.get("name") or "") == bound.group(2)), None)
        if other is not None and _GENIE_WIDGET_NUMBER_RE.fullmatch(str(other.get("default") or "").strip()):
            widget["allowed"] = f"{bound.group(1)}at least {str(other['default']).strip()}"
            print(f"[RANGE-BOUND FIRED] widget {name}: 'at least {bound.group(2)}' read as that widget's default {str(other['default']).strip()}",
                  flush=True)
        if name in core:
            widget["allowed"] = core[name]
        elif name in GENIE_OPTIONAL_WIDGETS:
            widget["allowed"] = genie_allowed_text(GENIE_WIDGET_ALLOWED[name])
        elif str(widget.get("type") or "") == "dropdown":
            widget["allowed"] = ""
        elif IMPLEMENT_CHOICE_KINDS.get(name) in ("grouping", "scope"):
            # RC3-03: Inspire's own text choices (group_by, run_scope, scope_*) are not numeric ranges; run_scope takes Inspire's scopes.
            widget["allowed"] = ", ".join(INSPIRE_SCOPES) if name == "run_scope" else ""
        else:
            rule = genie_allowed_rule(widget.get("allowed"))
            if rule is None:
                problems.append(f"widget {name} has an allowed range Inspire cannot read, which is not one of Inspire's range forms "
                                f"({GENIE_ALLOWED_FORMS_TEXT}, or empty for any value): write allowed for {name} as one of those forms "
                                f"that holds its default {widget.get('default')}, in place of the text {widget.get('allowed')}")
            widget["allowed"] = genie_allowed_text(rule)
    return problems


def implement_widget_default_fix(name: str, value, allowed, inspire_default=None):
    if not genie_widget_value_problem(name, value, allowed):
        return None
    if inspire_default is not None and str(inspire_default).strip() and not genie_widget_value_problem(name, inspire_default, allowed):
        return str(inspire_default).strip()
    low, high, whole, low_open, high_open = genie_rule_parts(genie_allowed_rule(allowed))
    text = str("" if value is None else value).strip()
    if not _GENIE_WIDGET_NUMBER_RE.fullmatch(text):
        return None
    number = float(text)
    if low is not None and not low_open and number < low:
        number = _inspire_math.ceil(low) if whole else low
    elif high is not None and not high_open and number > high:
        number = _inspire_math.floor(high) if whole else high
    fixed = _genie_number_text(int(number) if whole and float(number).is_integer() else number)
    return None if genie_widget_value_problem(name, fixed, allowed) else fixed


IMPLEMENT_RESTORABLE_CHOICES = (INSPIRE_GROUP_BY, "run_scope", "currency")


def implement_widget_default_fixes(result, core_widgets, pinned=None) -> list:
    # REQ-349 / REQ-331: a Grouping, scope or measure default that Genie wrote away from the planned choice is set back to the plan, so
    # the guard refuses only a drift Inspire cannot put back. The plan is the pinned choices (the Run page's scope, the Grouping, the measure).
    core = {str(w.get("name") or ""): w.get("default") for w in core_widgets or [] if isinstance(w, dict)}
    planned_choice = pinned if pinned is not None else core
    fixes = []
    for widget in (result.get("widgets") or []) if isinstance(result, dict) else []:
        if not isinstance(widget, dict):
            continue
        name = str(widget.get("name") or "")
        if name in IMPLEMENT_RESTORABLE_CHOICES:
            want = str(planned_choice.get(name) or "").strip()
            held = str(widget.get("default") or "").strip()
            choices = [implement_choice_text(c) for c in widget.get("choices") or []]
            missing = str(widget.get("type") or "") in IMPLEMENT_CHOICE_WIDGET_TYPES and implement_choice_text(want) not in choices
            if want and (implement_choice_text(held) != implement_choice_text(want) or missing):
                fixes.append((widget, held, want))
            continue
        if str(widget.get("type") or "text") == "dropdown":
            continue
        fixed = implement_widget_default_fix(name, widget.get("default"), widget.get("allowed"), core.get(name))
        if fixed is not None:
            fixes.append((widget, str(widget.get("default")).strip(), fixed))
    return fixes


IMPLEMENT_WIDGET_DECLARERS = ("text", "combobox", "dropdown", "multiselect")
IMPLEMENT_CHOICE_WIDGET_TYPES = ("dropdown", "combobox", "multiselect")


def implement_node_span(source: str, node) -> tuple:
    lines = source.split("\n")
    def offset(lineno, col):
        return sum(len(text) + 1 for text in lines[:lineno - 1]) + len(lines[lineno - 1].encode("utf-8")[:col].decode("utf-8", "ignore"))
    return offset(node.lineno, node.col_offset), offset(node.end_lineno, node.end_col_offset)


def implement_widget_literal(node):
    return node.value if isinstance(node, ast.Constant) and isinstance(node.value, str) else None


def implement_widget_declarations(source: str, name: str):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return None
    found = []
    for node in ast.walk(tree):
        if not (isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr in IMPLEMENT_WIDGET_DECLARERS
                and isinstance(node.func.value, ast.Attribute) and node.func.value.attr == "widgets"):
            continue
        args = dict(enumerate(node.args))
        keywords = {keyword.arg: keyword.value for keyword in node.keywords}
        first = args.get(0, keywords.get("name"))
        if isinstance(first, ast.Constant) and first.value == name:
            choices = None if node.func.attr == "text" else args.get(2, keywords.get("choices"))
            found.append((args.get(1, keywords.get("defaultValue")), choices, node.func.attr))
    return found


def implement_widget_default_patch(cells, name: str, old: str, new: str, any_literal: bool = False) -> bool:
    if not new or any(mark in new for mark in "'\"\\\n"):
        return False
    declarations = []
    for index, cell in enumerate(cells or []):
        source = implement_cell_text(cell)
        found = implement_widget_declarations(source, name)
        if found is None:
            if name in source:
                return False
            continue
        declarations += [(index, source, default, choices, kind) for default, choices, kind in found]
    if not declarations or (not any_literal and (len(declarations) != 1 or implement_widget_literal(declarations[0][2]) != old)):
        return False
    edits = {}
    for index, source, default, choices, kind in declarations:
        if implement_widget_literal(default) is None:
            return False
        start, end = implement_node_span(source, default)
        quote = next(mark for mark in source[start:end] if mark in "'\"")
        edits.setdefault(index, []).append((start, end, quote + new + quote))
        if any_literal and kind in IMPLEMENT_CHOICE_WIDGET_TYPES:
            if not isinstance(choices, (ast.List, ast.Tuple)) or any(implement_widget_literal(item) is None for item in choices.elts):
                return False
            if new not in [item.value for item in choices.elts]:
                items = [source[slice(*implement_node_span(source, item))] for item in choices.elts] + [quote + new + quote]
                start, end = implement_node_span(source, choices)
                edits[index].append((start, end, "[" + ", ".join(items) + "]"))
    for index, spans in edits.items():
        source = implement_cell_text(cells[index])
        for start, end, text in sorted(spans, reverse=True):
            source = source[:start] + text + source[end:]
        cells[index]["source"] = source.splitlines(True)
    return True


def validate_genie_fill_result(result, required_widgets) -> list:
    errors = []
    if not isinstance(result, dict) or not result:
        return ["Genie returned no JSON result"]
    names = []
    for widget in result.get("widgets") or []:
        name, kind = str(widget.get("name") or ""), str(widget.get("type") or "")
        if not IMPLEMENT_WIDGET_NAME_RE.match(name):
            errors.append(f"widget name {name!r} is invalid")
        if kind == "dropdown" and str(widget.get("default")) not in [str(c) for c in widget.get("choices") or []]:
            errors.append(f"dropdown widget {name} has default {widget.get('default')!r} outside its choices")
        problem = genie_widget_value_problem(name, widget.get("default"), widget.get("allowed"))
        if problem:
            errors.append(f"the default of widget {problem}")
        names.append(name)
    missing = [n for n in list(required_widgets or []) + ["run_profile"] if n not in names]
    if missing:
        errors.append(f"widgets missing from the result: {', '.join(missing)}")
    cron = str((result.get("schedule") or {}).get("cron") or "")
    cron_problem = implement_cron_problem(cron) if cron else ""
    if cron_problem:
        errors.append(f"suggested schedule '{cron}' is not a valid Quartz cron: {cron_problem}")
    return errors


def genie_fill_stopped(result) -> bool:
    if not isinstance(result, dict):
        return False
    status = str(result.get("status") or "")
    return status == "stopped" or (status == "built" and bool(str(result.get("stop_reason") or "").strip()))


def implement_table_refs(text) -> list:
    refs = []
    for match in _IMPLEMENT_TABLE_REF_RE.finditer(str(text or "")):
        groups = [g for g in match.groups() if g is not None]
        name = ".".join(groups[:3])
        if name.lower() not in {r.lower() for r in refs}:
            refs.append(name)
    return refs


def implement_join_lines(lines) -> list:
    items = [str(line) for line in lines or []]
    return [line if index == len(items) - 1 or line[-1:] in ("\n", " ", "\t", "\r") else line + "\n"
            for index, line in enumerate(items)]


def _implement_normalize_sql_lines(obj):
    if isinstance(obj, dict):
        for key, value in obj.items():
            if key in ("queryLines", "sql") and isinstance(value, list):
                obj[key] = implement_join_lines(value)
            else:
                _implement_normalize_sql_lines(value)
    elif isinstance(obj, list):
        for value in obj:
            _implement_normalize_sql_lines(value)
    return obj


def _implement_sql_texts(obj) -> list:
    texts = []
    if isinstance(obj, dict):
        for key, value in obj.items():
            if key in ("queryLines", "sql") and isinstance(value, list):
                texts.append("".join(str(v) for v in value))
            elif key in ("query", "sql") and isinstance(value, str):
                texts.append(value)
            else:
                texts.extend(_implement_sql_texts(value))
    elif isinstance(obj, list):
        for value in obj:
            texts.extend(_implement_sql_texts(value))
    return texts


_IMPLEMENT_METADATA_NAMESPACES = ("system.information_schema.", "information_schema.")
_IMPLEMENT_GENERATOR_FUNCTIONS = frozenset({"range", "explode", "explode_outer", "posexplode", "posexplode_outer", "inline", "inline_outer",
                                            "stack", "json_tuple", "variant_explode", "variant_explode_outer", "generate_series", "unnest"})
_IMPLEMENT_OUTSIDE_FUNCTIONS = frozenset({"read_files", "cloud_files", "read_kafka", "read_kinesis", "read_pubsub", "read_pulsar",
                                          "read_state_metadata", "read_statestore", "remote_query", "http_request", "secret", "try_secret"})
_IMPLEMENT_OUTSIDE_FUNCTION_RE = re.compile(r"\b(" + "|".join(sorted(_IMPLEMENT_OUTSIDE_FUNCTIONS)) + r"|identifier)\s*\(", re.I)
_IMPLEMENT_PATH_TEXT_RE = re.compile(r"^\s*(?:/|[a-z][a-z0-9+.-]*:)", re.I)


def _implement_table_function_ref(function) -> str:
    from sqlglot import exp
    name = str(function.name if isinstance(function, exp.Anonymous) else function.sql_name()).lower()
    args = [a.this if isinstance(a, exp.Kwarg) else a for a in function.expressions]
    texts = [str(a.this) for a in args if isinstance(a, exp.Literal) and a.is_string]
    if name == "identifier":
        return texts[0].replace("`", "").strip() if len(texts) == 1 and len(args) == 1 else "identifier(...)"
    if name in _IMPLEMENT_GENERATOR_FUNCTIONS and not any(_IMPLEMENT_PATH_TEXT_RE.match(t) for t in texts):
        return ""
    return f"{name}(...)"


def _implement_parsed_table_refs(text) -> list:
    import sqlglot
    from sqlglot import exp
    try:
        trees = [t for t in sqlglot.parse(str(text or ""), read="databricks") if t is not None]
    except sqlglot.errors.SqlglotError:
        return [f"{m}(...)" for m in dict.fromkeys(m.lower() for m in _IMPLEMENT_OUTSIDE_FUNCTION_RE.findall(str(text or "")))]
    refs = []

    def add(name):
        if name and name.lower() not in {r.lower() for r in refs}:
            refs.append(name)
    for tree in trees:
        ctes = {str(c.alias_or_name).lower() for c in tree.find_all(exp.CTE)}
        for table in tree.find_all(exp.Table, exp.Lateral):
            if isinstance(table.this, exp.Func):
                add(_implement_table_function_ref(table.this))
                continue
            if isinstance(table, exp.Lateral):
                continue
            if not isinstance(table.this, exp.Identifier):
                continue
            parts = [p for p in (table.catalog, table.db, table.name) if p]
            if len(parts) == 1 and parts[0].lower() in ctes:
                continue
            add(".".join(parts))
        for function in tree.find_all(exp.Anonymous):
            name = str(function.name or "").lower()
            if not isinstance(function.parent, (exp.Table, exp.Lateral)) and name in _IMPLEMENT_OUTSIDE_FUNCTIONS:
                add(f"{name}(...)")
    return refs


def _implement_unknown_tables(texts, allowed) -> list:
    allowed_lower = {_implement_plain_table(t).lower() for t in allowed or []}
    roots = {implement_use_case_root(t) for t in allowed_lower}
    tails = {".".join(t.split(".")[-n:]) for t in allowed_lower | roots for n in (1, 2)}
    unknown = []
    for text in texts:
        for ref in implement_table_refs(text) + _implement_parsed_table_refs(text):
            low = ref.lower()
            known = low in allowed_lower or (low.count(".") < 2 and low in tails) or implement_use_case_table(low, allowed_lower)
            if not known and low not in {u.lower() for u in unknown} and not low.startswith(_IMPLEMENT_METADATA_NAMESPACES):
                unknown.append(ref)
    return unknown


_IMPLEMENT_FLAG_COUNT_RE = re.compile(r"\b(?:count_if|count|sum|avg)\s*\([^)]*\bdata_quality_flag\b"
                                      r"|\bfilter\s*\(\s*where\b[^)]*\bdata_quality_flag\b", re.I)
_IMPLEMENT_OK_LITERAL_RE = re.compile(r"""['"]ok['"]""", re.I)


def _implement_flag_count_problems(texts, where: str) -> list:
    if any(_IMPLEMENT_FLAG_COUNT_RE.search(str(t)) and not _IMPLEMENT_OK_LITERAL_RE.search(str(t)) for t in texts or ()):
        return [f"{where} counts data_quality_flag without comparing it to 'ok': the notebook writes 'ok' on every row that "
                f"passed its checks, so only a value other than 'ok' marks a flagged row"]
    return []


_IMPLEMENT_RUN_MEANING_RE = re.compile(r"\brun_id\b|\bas_of_date\b|\bchange_source`?\s*=\s*'run'", re.I)
_IMPLEMENT_IS_CURRENT_RE = re.compile(r"(\bnot\s+)?(?:`?\w+`?\.)?`?\bis_current\b`?(?:\s*(=|<>|!=)\s*(true|false|1|0)\b)?", re.I)


def _implement_scope_text(text: str, at: int) -> str:
    start, end, depth = 0, len(text), 0
    for index in range(at - 1, -1, -1):
        if text[index] == ")":
            depth += 1
        elif text[index] == "(":
            if not depth:
                start = index + 1
                break
            depth -= 1
    depth = 0
    for index in range(at, len(text)):
        if text[index] == "(":
            depth += 1
        elif text[index] == ")":
            if not depth:
                end = index
                break
            depth -= 1
    own, depth = [], 0
    for char in text[start:end]:
        if char == "(":
            depth += 1
        elif char == ")":
            depth -= 1
        elif not depth:
            own.append(char)
    return "".join(own)


def _implement_reads_current(scope: str) -> bool:
    for match in _IMPLEMENT_IS_CURRENT_RE.finditer(scope):
        negated, operator, value = match.groups()
        held = True if not operator else ((operator == "=") == (value.lower() in ("true", "1")))
        if held != bool(negated):
            return True
    return False


def implement_run_version_problems(texts, where: str, run_versions) -> list:
    if not run_versions:
        return []
    log = _implement_plain_table(run_versions.get("log")).lower()
    versioned = {_implement_plain_table(t).lower(): t for t in [run_versions.get("table")] + list(run_versions.get("views") or []) if t}
    for text in texts or ():
        plain = re.sub(r"--[^\n]*|/\*.*?\*/", " ", str(text or ""), flags=re.S)
        if log in {ref.lower() for ref in implement_table_refs(plain)} or not _IMPLEMENT_RUN_MEANING_RE.search(plain):
            continue
        for match in _IMPLEMENT_TABLE_REF_RE.finditer(plain):
            name = ".".join([g for g in match.groups() if g is not None][:3]).lower()
            if name in versioned and not _implement_reads_current(_implement_scope_text(plain, match.end())):
                return [f"{where} reads the versions of {versioned[name]} run by run, but a run writes a new version of a record only "
                        f"when its values change: read the current rows with is_current, or count and compare runs from "
                        f"{run_versions['log']}, which lists every record of every run"]
    return []


_IMPLEMENT_G_SPEC = r"(?:.?[<>=^])?[+\- ]?z?#?0?\d*[,_]?(?:\.\d+)?[gG]"
_IMPLEMENT_G_SPEC_RE = re.compile(_IMPLEMENT_G_SPEC)
_IMPLEMENT_BRACE_G_RE = re.compile(r"\{[^{}]*:" + _IMPLEMENT_G_SPEC + r"\}")
_IMPLEMENT_PERCENT_G_RE = re.compile(r"%[-+ #0]*\d*(?:\.\d+)?[gG]")
_IMPLEMENT_ZERO_STRIP = "strips zeros from a number's text with rstrip, which turns 120 into '12'"
IMPLEMENT_SUMMARY_RULE = ("the summary step passes its facts to inspire_write_summary(facts, result_table, run_id, as_of_date), which "
                          "runs the ai_query that writes the summary, and never calls ai_query for the summary itself")
_IMPLEMENT_G_FORMAT = "writes a number with Python's 'g' format, which turns 1060 into 1.06e+03"


def _implement_text_constant(node) -> str:
    return node.value if isinstance(node, ast.Constant) and isinstance(node.value, str) else None


def _implement_number_text_spots(tree, skip) -> list:
    spots = []
    skip = set(skip) | {id(part) for node in ast.walk(tree) if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
                        and node.func.id == "float" and len(node.args) == 1 for part in ast.walk(node.args[0])}
    for node in ast.walk(tree):
        if id(node) in skip:
            continue
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == "rstrip" and node.args \
                and "0" in (_implement_text_constant(node.args[0]) or ""):
            spots.append((node.lineno, _IMPLEMENT_ZERO_STRIP))
        elif isinstance(node, ast.FormattedValue) and isinstance(node.format_spec, ast.JoinedStr) \
                and all(_implement_text_constant(v) is not None for v in node.format_spec.values) \
                and _IMPLEMENT_G_SPEC_RE.fullmatch("".join(v.value for v in node.format_spec.values)):
            spots.append((node.lineno, _IMPLEMENT_G_FORMAT))
        elif isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == "format" and len(node.args) > 1 \
                and _IMPLEMENT_G_SPEC_RE.fullmatch(_implement_text_constant(node.args[1]) or "-"):
            spots.append((node.lineno, _IMPLEMENT_G_FORMAT))
        elif isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == "format" \
                and _IMPLEMENT_BRACE_G_RE.search(_implement_text_constant(node.func.value) or ""):
            spots.append((node.lineno, _IMPLEMENT_G_FORMAT))
        elif isinstance(node, ast.BinOp) and isinstance(node.op, ast.Mod) \
                and _IMPLEMENT_PERCENT_G_RE.search(_implement_text_constant(node.left) or ""):
            spots.append((node.lineno, _IMPLEMENT_G_FORMAT))
    return sorted(set(spots))


def implement_number_text_problems(cells, required: bool = True) -> list:
    defined, spots, calls = {}, [], 0
    for label, source in cells:
        tree = _implement_cell_tree(source)
        if tree is None:
            continue
        skip = set()
        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef):
                names = [node.name]
            elif isinstance(node, ast.Assign):
                names = [target.id for target in node.targets if isinstance(target, ast.Name)]
            else:
                continue
            for name in names:
                if name in GENIE_NUMBER_HELPERS:
                    skip.update(id(n) for n in ast.walk(node))
                    labels = defined.setdefault(name, [])
                    if label not in labels:
                        labels.append(label)
        calls += sum(1 for n in ast.walk(tree) if id(n) not in skip and isinstance(n, ast.Call)
                     and isinstance(n.func, ast.Name) and n.func.id in GENIE_NUMBER_FUNCTIONS)
        spots += [f"{label} line {line} {what}" for line, what in _implement_number_text_spots(tree, skip)]
    problems = []
    if defined:
        where = "; ".join(f"{name} in {', '.join(labels)}" for name, labels in defined.items())
        problems.append(f"the notebook defines {where}, which Inspire's '{GENIE_NUMBER_HELPERS_TITLE}' cell already defines: "
                        f"delete those definitions and call Inspire's {', '.join(GENIE_NUMBER_HELPERS)}")
    if required and not calls:
        problems.append(f"no cell calls {' or '.join(GENIE_NUMBER_FUNCTIONS)}; write every number in top_reasons, "
                        "recommended_action, ai_facts and the summary facts with them")
    if spots:
        problems.append("; ".join(spots) + f"; write numbers as text only with {' or '.join(GENIE_NUMBER_FUNCTIONS)}")
    return problems


_IMPLEMENT_DENIAL_MARK_RE = re.compile(r"PERMISSION_DENIED|INSUFFICIENT_PERMISSIONS|PermissionDenied|PermissionError|Forbidden"
                                       r"|does not have|permission|privilege|CREATE[ _]MODEL", re.IGNORECASE)


def _implement_parse_cell(source):
    # REQ-396: the one parser for a Genie cell. IPython magic lines are blanked, so line numbers stay the cell's own.
    lines = str(source or "").splitlines()
    return ast.parse("\n".join("" if line.lstrip().startswith(("%", "!")) else line for line in lines))


def _implement_cell_tree(source):
    try:
        return _implement_parse_cell(source)
    except SyntaxError:
        return None


IMPLEMENT_NON_PYTHON_CELL_RE = re.compile(r"^%(sql|md|markdown|scala|r)\b")


def implement_unparseable_cell_problems(cells) -> list:
    # REQ-396: every check that reads a cell's tree skips a cell that does not parse, so a broken Python cell passed the gate. The
    # gate names the line and sends the cell back to Genie. SQL, Markdown, Scala and R cells are not Python and are not parsed.
    problems = []
    for label, source in cells or []:
        text = str(source or "")
        first = next((line.strip() for line in text.splitlines() if line.strip()), "")
        if IMPLEMENT_NON_PYTHON_CELL_RE.match(first):
            continue
        try:
            _implement_parse_cell(text)
        except SyntaxError as error:
            problems.append(f"{label} line {error.lineno or 1} does not parse as Python ({error.msg}), so Inspire cannot check the rest "
                            "of the cell: fix the syntax at that line")
    return problems


def _implement_mentions_denial(node) -> bool:
    for part in ast.walk(node):
        if isinstance(part, ast.Constant) and isinstance(part.value, str):
            text = part.value
        elif isinstance(part, ast.Name):
            text = part.id
        elif isinstance(part, ast.Attribute):
            text = part.attr
        else:
            continue
        if _IMPLEMENT_DENIAL_MARK_RE.search(text):
            return True
    return False


def _implement_raises(body) -> bool:
    return any(isinstance(node, ast.Raise) for statement in body for node in ast.walk(statement))


def implement_training_read_problems(cells, required: bool = True) -> list:
    if not required:
        return []
    for _label, source in cells:
        tree = _implement_cell_tree(source)
        for node in ast.walk(tree) if tree is not None else ():
            if (isinstance(node, ast.Call) and _implement_called_name(node) == "inspire_read_source"
                    and any(k.arg == "purpose" and isinstance(k.value, ast.Constant) and k.value.value == INSPIRE_READ_PURPOSES[1]
                            for k in node.keywords)):
                return []
    return [f"no cell reads training rows with inspire_read_source(..., purpose='training'), so the model learns only from the records "
            f"the First run scores: {GENIE_TRAINING_READ_RULE}"]


def implement_training_sample_problems(cells, required: bool = True) -> list:
    defined, calls = [], 0
    for label, source in cells:
        tree = _implement_cell_tree(source)
        if tree is None:
            continue
        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef) and node.name == "inspire_training_sample" and label not in defined:
                defined.append(label)
            elif isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == "inspire_training_sample":
                calls += 1
    problems = []
    if defined:
        problems.append(f"{', '.join(defined)} define{'s' if len(defined) == 1 else ''} inspire_training_sample, which Inspire's Run "
                        "controls cell defines: delete that definition and call Inspire's")
    if required and not calls:
        problems.append("no cell calls inspire_training_sample: the user set no data window, training profile, row filter, widget "
                        "value or asks for this notebook, so a preview trains on the sample it keeps, as the Implementation Choices "
                        "say: pass the training rows through inspire_training_sample(frame, key) right before the model reads them")
    return problems


IMPLEMENT_GROUP_PARTITIONS = ("partitionBy", "groupBy", "groupby", "repartition")


def _implement_names_group(node) -> bool:
    return any((isinstance(part, ast.Constant) and part.value == INSPIRE_GROUP_COLUMN)
               or (isinstance(part, ast.Name) and part.id == "INSPIRE_GROUP_COLUMN") for part in ast.walk(node))


def _implement_scopes(tree) -> dict:
    # REQ-396: the functions around each call, outermost first, so group_by is checked where the call can see it.
    owners = {}
    for function in (node for node in ast.walk(tree) if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))):
        for part in ast.walk(function):
            if isinstance(part, ast.Call):
                owners.setdefault(id(part), []).append(function)
    return owners


def _implement_binds_name(scope, name: str) -> bool:
    args = scope.args
    if any(arg.arg == name for arg in args.posonlyargs + args.args + args.kwonlyargs):
        return True
    return any(isinstance(part, ast.Name) and part.id == name and isinstance(part.ctx, ast.Store) for part in ast.walk(scope))


def _implement_binds_at_module(tree, name: str) -> bool:
    return any(isinstance(part, ast.Name) and part.id == name and isinstance(part.ctx, ast.Store)
               for node in tree.body if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef))
               for part in ast.walk(node))


def implement_grouping_problems(cells, grouping) -> list:
    if not (grouping or {}).get("applies"):
        return []
    defined, calls, unread, unset, partitioned = [], 0, [], [], False
    module_sets = any(_implement_binds_at_module(tree, INSPIRE_GROUP_BY)
                      for tree in (_implement_cell_tree(source) for _label, source in cells or []) if tree is not None)
    for label, source in cells or []:
        tree = _implement_cell_tree(source)
        if tree is None:
            continue
        owners = _implement_scopes(tree)
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == IMPLEMENT_GROUP_FUNCTION:
                if label not in defined:
                    defined.append(label)
            elif isinstance(node, ast.Call) and _implement_called_name(node) == IMPLEMENT_GROUP_FUNCTION:
                calls += 1
                given = next((k.value for k in node.keywords if k.arg == INSPIRE_GROUP_BY), node.args[1] if len(node.args) > 1 else None)
                if not (isinstance(given, ast.Name) and given.id == INSPIRE_GROUP_BY):
                    unread.append(f"{label} line {node.lineno}")
                elif not (module_sets or any(_implement_binds_name(scope, INSPIRE_GROUP_BY) for scope in owners.get(id(node), []))):
                    unset.append(f"{label} line {node.lineno}")
            elif (isinstance(node, ast.Call) and _implement_called_name(node) in IMPLEMENT_GROUP_PARTITIONS
                  and any(_implement_names_group(part) for part in list(node.args) + [k.value for k in node.keywords])):
                partitioned = True
    problems = []
    if defined:
        problems.append(f"{', '.join(defined)} define{'s' if len(defined) == 1 else ''} {IMPLEMENT_GROUP_FUNCTION}, which Inspire's "
                        "Run controls cell defines: delete that definition and call Inspire's")
    if not calls:
        problems.append(f"no cell calls {IMPLEMENT_GROUP_FUNCTION}, but this use case compares each record with its own group: pass "
                        f"the records through `records = {IMPLEMENT_GROUP_FUNCTION}(records, group_by={INSPIRE_GROUP_BY})` right before "
                        f"the step that works out what is normal, then partition that step by {INSPIRE_GROUP_COLUMN}, as the Grouping "
                        "rule says")
    if unread:
        problems.append(f"{', '.join(unread)} call{'s' if len(unread) == 1 else ''} {IMPLEMENT_GROUP_FUNCTION} without the "
                        f"{INSPIRE_GROUP_BY} variable: pass {INSPIRE_GROUP_BY}={INSPIRE_GROUP_BY}, the variable the Parameters cell reads "
                        f"from the {INSPIRE_GROUP_BY} widget, so a Grouping an owner changes on the Run page applies with no rebuild; inside "
                        f"the function that makes the call, read the widget into the variable first: `{INSPIRE_GROUP_BY} = "
                        f"dbutils.widgets.get(\"{INSPIRE_GROUP_BY}\")`")
    if unset:
        problems.append(f"{', '.join(unset)} call{'s' if len(unset) == 1 else ''} {IMPLEMENT_GROUP_FUNCTION} with the {INSPIRE_GROUP_BY} "
                        f"variable, but the function around the call never sets it: inside that function read the {INSPIRE_GROUP_BY} "
                        f"widget into the variable, `{INSPIRE_GROUP_BY} = dbutils.widgets.get(\"{INSPIRE_GROUP_BY}\")`, then pass "
                        f"{INSPIRE_GROUP_BY}={INSPIRE_GROUP_BY}; a variable set in another function is not visible there")
    if calls and not partitioned:
        problems.append(f"no baseline, statistic, threshold, rank or model is partitioned by {INSPIRE_GROUP_COLUMN}, so every record "
                        "is still compared with every other record: partition the step that works out what is normal with "
                        f'Window.partitionBy("{INSPIRE_GROUP_COLUMN}"), groupBy("{INSPIRE_GROUP_COLUMN}") or a pandas '
                        f'groupby("{INSPIRE_GROUP_COLUMN}")')
    return problems


IMPLEMENT_GROUP_ID_RE = re.compile(r"(?i)(?:^|_)(?:id|key|uuid|guid|sk|nk|hash)$")
IMPLEMENT_GROUP_TYPES = ("string", "varchar", "char", "boolean")
IMPLEMENT_GROUP_KEY_TYPES = ("int", "integer", "bigint", "smallint", "tinyint", "long", "short", "byte", "string", "varchar", "char")
IMPLEMENT_GROUP_SEGMENT_TYPES = tuple(dict.fromkeys(IMPLEMENT_GROUP_TYPES + IMPLEMENT_GROUP_KEY_TYPES + ("date", "timestamp", "timestamp_ntz", "decimal")))
IMPLEMENT_GROUP_CANDIDATES = 12
IMPLEMENT_GROUP_PROFILED = 6
IMPLEMENT_GROUP_STATS_ROWS_RE = re.compile(r"(?i)\b([0-9]+)\s+rows\b")
IMPLEMENT_GROUP_PROOF_SUFFIX = "_inspire_group_proof"
IMPLEMENT_GROUP_PROOF_PARTS = ("", "summary", "run_log", "assumptions", "stage")
IMPLEMENT_GROUP_REBUILD = ("the Grouping names {columns}, which the built notebook does not read, so Genie rebuilds the notebook to read "
                           "it; a Grouping from the columns the notebook reads changes on the Run page with no rebuild")
IMPLEMENT_GROUP_REPAIR = ("\n\nInspire ran the notebook again with another Grouping after your last attempt, and the groups did not follow "
                          "the setting: {problems}. Read the group_by widget into the variable group_by, pass it as "
                          "inspire_group_records(records, group_by=group_by) before the step that works out what is normal, partition "
                          "that step by inspire_group, then run it again.")


def implement_grouping_words(text) -> set:
    words = set()
    for word in [w for w in re.split(r"[^a-z0-9]+", str(text or "").lower()) if w]:
        words.add(word)
        if word.endswith("ies"):
            words.add(word[:-3] + "y")
        elif word.endswith("s"):
            words.add(word[:-1])
    return words


def implement_grouping_relevance(name, words) -> int:
    return sum(1 for token in re.split(r"[^a-z0-9]+", str(name).split(".")[-1].lower()) if len(token) >= 3 and token in words)


def implement_grouping_candidates(columns, roles, main_table, free_text_tokens=(), primary=(), time_column="", text="") -> list:
    main = str(main_table or "").replace("`", "").lower()
    own = {role: str(ref).replace("`", "").split(".")[-1].lower() for role, ref in (roles or {}).items()
           if ".".join(str(ref).replace("`", "").split(".")[:3]).lower() == main}
    skip = {own.get(role) for role in ("entity_id", "event_date", "measure", "label")} | {str(p).lower() for p in primary or ()}
    skip |= {str(time_column).lower()} if time_column else set()
    segment, texts, keys, seen = [], [], [], set()
    for column in columns or []:
        name, kind = str(column.get("column_name") or ""), str(column.get("data_type") or "").lower()
        if not name or name.lower() in skip or name in seen or deep_column_is_pii(name, column.get("tags")):
            continue
        seen.add(name)
        if name.lower() == own.get("segment") and re.split(r"[<(\s]", kind.strip())[0] in IMPLEMENT_GROUP_SEGMENT_TYPES:
            segment.append(name)
        elif (kind.startswith(IMPLEMENT_GROUP_TYPES) and not IMPLEMENT_GROUP_ID_RE.search(name)
              and not any(token in name.lower() for token in free_text_tokens)):
            texts.append(name)
        elif (re.sub(r"\(.*$", "", kind).strip() in IMPLEMENT_GROUP_KEY_TYPES and IMPLEMENT_GROUP_ID_RE.search(name)
              and not INSPIRE_TIME_NAME.search(name)):
            keys.append(name)
    fair = [lane[at] for at in range(max(len(texts), len(keys))) for lane in (texts, keys) if at < len(lane)]
    words = implement_grouping_words(text)
    ranked = sorted(enumerate(fair), key=lambda pair: (-implement_grouping_relevance(pair[1], words), pair[0]))
    return (segment + [name for _, name in ranked])[:IMPLEMENT_GROUP_CANDIDATES]


def implement_grouping_joins(columns, joins, tables) -> dict:
    mains = {str(t or "").replace("`", "").strip().lower() for t in tables or ()} - {""}
    found = {}
    for column in columns or ():
        short, _, name = str(column).strip().rpartition(".")
        if not short or not name:
            continue
        for join in joins or ():
            ref = str((join or {}).get("ref_table") or "").replace("`", "").strip().lower()
            if (str(join.get("table") or "").replace("`", "").strip().lower() in mains and ref.split(".")[-1] == short.lower()
                    and str(join.get("column") or "").strip() and str(join.get("ref_column") or "").strip()):
                found[str(column).strip()] = {"table": ref, "key": str(join["column"]).strip(), "ref_column": str(join["ref_column"]).strip()}
                break
    return found


def implement_grouping_unchecked_text(columns) -> str:
    return (f"Data groups: {', '.join(columns)} could not be checked for one value in this data, after one retry, so the build goes on "
            "without that check. If it holds one value, its groups make one group; the run checks it again before it scores any record, "
            "and stops with the reason.")


IMPLEMENT_PEER_KIND = "peer_benchmarking"
IMPLEMENT_PEER_TECHNIQUE = "peer benchmarking"
IMPLEMENT_PEER_ENTITY_REFUSED = ("{column} is the entity key of this peer comparison, so each {column} would be its own group with no peers "
                                 "to compare it with; choose columns that group the entities with peers, or all")


def implement_peer_entity(technique, kind, entity_key) -> str:
    """The entity key of a peer comparison, which no Grouping may name or recommend: each entity alone is its own group, with no peers."""
    peer = str(kind or "").strip() == IMPLEMENT_PEER_KIND or " ".join(str(technique or "").split()).lower() == IMPLEMENT_PEER_TECHNIQUE
    return str(entity_key or "").replace("`", "").split(".")[-1].strip() if peer else ""


def implement_grouping_plan(technique, candidates, chosen, time_column="", recommended=(), recommended_by="Inspire", kind="", one_value=(),
                            entity_key="") -> dict:
    text = str(chosen or "").strip()
    mode, picked = inspire_group_by_mode(text)
    one_model = inspire_grouping_fits_one_model(technique, kind)
    if mode == INSPIRE_GROUP_CUSTOM:
        return {"applies": False, "problem": f"{INSPIRE_GROUP_BY} is '{text}': {INSPIRE_CUSTOM_SQL_REFUSED}"}
    if mode == "mixed":
        return {"applies": False, "problem": f"{INSPIRE_GROUP_BY} is '{text}'; {INSPIRE_SETTING_ALL} stands alone"}
    if one_model and mode == "columns":
        return {"applies": False, "one_model": True, "problem": f"{INSPIRE_GROUP_BY} is '{text}': {INSPIRE_ONE_MODEL_REFUSED}"}
    if one_model:
        recommended = ()
    entity = implement_peer_entity(technique, kind, entity_key)
    if entity and entity.lower() in {name.lower() for name in picked}:
        return {"applies": False, "problem": f"{INSPIRE_GROUP_BY} is '{text}': {IMPLEMENT_PEER_ENTITY_REFUSED.format(column=entity)}"}
    if entity:
        candidates = [c for c in candidates or () if str(c).lower() != entity.lower()]
        recommended = [c for c in recommended or () if str(c).lower() != entity.lower()]
    single = {str(name).lower() for name in one_value or ()}
    held = [name for name in picked if name.lower() in single]
    if held and len(held) == len(picked):
        return {"applies": False, "one_model": one_model, "problem": f"{INSPIRE_GROUP_BY} is '{text}': " + inspire_one_value_words(held)}
    recommended = [name for name in recommended or () if name.lower() not in single]
    named = [] if mode == "columns" else list(candidates or [])
    for name in list(picked) + list(recommended or ()):
        if name.lower() not in {c.lower() for c in named}:
            named.append(name)
    applies = bool(text) or ((inspire_grouping_applies(technique) or one_model) and bool(named))
    default = text or (", ".join(recommended) if recommended else INSPIRE_SETTING_ALL)
    return {"applies": applies, "columns": named if applies else [], "default": default if applies else "",
            "recommended": list(recommended or []), "time_column": str(time_column or "") if applies else "",
            "chosen_by": "person" if text else str(recommended_by or "Inspire") if recommended else "default", "one_model": one_model}


def _implement_described(rows) -> dict:
    found = {}
    for row in rows or []:
        values = [str("" if value is None else value).strip() for value in dict(row).values()]
        if len(values) >= 2 and values[0]:
            found.setdefault(values[0].lower(), values[1])
    return found


def implement_grouping_stats_profile(column: str, table_rows, column_rows):
    records = IMPLEMENT_GROUP_STATS_ROWS_RE.search(_implement_described(table_rows).get("statistics", ""))
    groups = _implement_described(column_rows).get("distinct_count", "")
    if not records or not groups.isdigit():
        return None
    return {"column": str(column), "groups": int(groups), "records": int(records.group(1))}


def implement_grouping_proof_table(result_table: str, part: str = "") -> str:
    proof = str(result_table) + IMPLEMENT_GROUP_PROOF_SUFFIX
    if part == "summary":
        return inspire_ai_summary_table(proof)
    if part == "run_log":
        return inspire_run_log_table(proof)
    if part == "assumptions":
        return inspire_assumptions_table(proof)
    if part == "stage":
        return f"{proof}_inspire_stage"
    if part:
        raise ValueError("the grouping proof has no table by that name")
    return proof


def implement_grouping_proof_problems(record, asked: str, run_id) -> list:
    mode, columns = inspire_group_by_mode(asked)
    if mode == INSPIRE_GROUP_CUSTOM:
        asked = inspire_group_by_plain(asked)
        mode, columns = inspire_group_by_mode(asked)
    if not isinstance(record, dict):
        return [f"run {run_id} ran with the Grouping {asked}, but no step called {IMPLEMENT_GROUP_FUNCTION}, so the run recorded no "
                "grouping"]
    got = record.get("group_by")
    shown = INSPIRE_SETTING_ALL if got == INSPIRE_SETTING_ALL else ", ".join(got) if isinstance(got, (list, tuple)) else str(got or "")
    groups = int(record.get("groups") or 0)
    if mode == INSPIRE_SETTING_ALL:
        right = record.get("mode") == INSPIRE_SETTING_ALL and groups == 1
    else:
        held = [str(c) for c in got or []] if isinstance(got, (list, tuple)) else []
        right = (record.get("mode") == "columns" and len(held) == len(columns) and groups >= 1
                 and all(inspire_group_column_of(column, {held[at].lower(): held[at]}) for at, column in enumerate(columns)))
    if right:
        return []
    return [f"run {run_id} ran with the Grouping {asked}, but its records were grouped by {shown or 'nothing'} into "
            f"{inspire_plural(groups, 'group')}"]


IMPLEMENT_INSTALL_LINE_RE = re.compile(r"^\s*[%!]\s*(?:pip3?|conda|uv|apt(?:-get)?|npm)\b|\bpip3?\s+install\b|-m\s+pip\b|"
                                       r"[\"']pip[\"']\s*,\s*[\"']install[\"']|\bdbutils\.library\.install", re.M)


def implement_install_problems(cells) -> list:
    problems = []
    shipped = ", ".join(f"{name} {version}" for name, version in GENIE_ENV_PACKAGE_VERSIONS.items())
    for label, source in cells:
        found = IMPLEMENT_INSTALL_LINE_RE.search(str(source or ""))
        if found:
            line = str(source)[:found.start()].count("\n") + 1
            problems.append(f"{label} line {line} installs a package; the notebook runs on what serverless environment "
                            f"{GENIE_NOTEBOOK_ENV_VERSION} ships ({shipped}) and installs nothing, so remove that line")
    return problems


def implement_denial_catch_problems(cells) -> list:
    problems = []
    for label, source in cells:
        tree = _implement_cell_tree(source)
        if tree is None:
            continue
        for handler in (node for node in ast.walk(tree) if isinstance(node, ast.ExceptHandler)):
            carries_on = handler.type is not None and _implement_mentions_denial(handler.type) and not _implement_raises(handler.body)
            for node in ast.walk(handler):
                if isinstance(node, ast.If) and _implement_mentions_denial(node.test) and not _implement_raises(node.body):
                    carries_on = True
                elif isinstance(node, ast.IfExp) and _implement_mentions_denial(node.test):
                    carries_on = True
            if carries_on:
                problems.append(f"{label} line {handler.lineno} catches a permission error and carries on; a denied privilege "
                                "must fail the run, so remove that handling and let the error stop the notebook")
    return problems


_IMPLEMENT_AI_QUERY_CALL_RE = re.compile(r"\bai_query\s*\(", re.I)


def _implement_called_name(node) -> str:
    if isinstance(node.func, ast.Name):
        return node.func.id
    return node.func.attr if isinstance(node.func, ast.Attribute) else ""


IMPLEMENT_RANK_FUNCTION = "rank_rows"


def _implement_binds(node, name: str) -> bool:
    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
        return node.name == name
    if isinstance(node, (ast.Assign, ast.AnnAssign)):
        targets = node.targets if isinstance(node, ast.Assign) else [node.target]
        return any(isinstance(target, ast.Name) and target.id == name for target in targets)
    if isinstance(node, ast.ImportFrom):
        return any((alias.asname or alias.name) == name for alias in node.names)
    return False


def _implement_cell_name_uses(tree, name: str):
    binds, calls = [], []
    stack = [(node, False, None, False) for node in tree.body]
    while stack:
        node, deferred, owner, in_class = stack.pop()
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)):
            stack += [(part, deferred, owner, in_class) for part in list(getattr(node, "decorator_list", [])) + node.args.defaults
                      + [part for part in node.args.kw_defaults if part is not None]]
            if not isinstance(node, ast.Lambda) and not deferred and not in_class and node.name == name:
                binds.append(node.lineno)
            inner = None if in_class else owner if deferred else getattr(node, "name", owner)
            stack += [(part, True, inner, False) for part in (node.body if isinstance(node.body, list) else [node.body])]
            continue
        if isinstance(node, ast.ClassDef):
            stack += [(part, deferred, owner, in_class) for part in node.decorator_list + node.bases + [k.value for k in node.keywords]]
            stack += [(part, deferred, owner, True) for part in node.body]
            continue
        if not deferred and not in_class and _implement_binds(node, name):
            binds.append(node.lineno)
        if (isinstance(node, ast.Assign) and isinstance(node.value, ast.Lambda) and not deferred and not in_class
                and any(isinstance(target, ast.Name) for target in node.targets)):
            label = next(target.id for target in node.targets if isinstance(target, ast.Name))
            stack.append((node.value, False, label, False))
            continue
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
            calls.append((node.lineno, node.func.id, deferred, owner))
        stack += [(child, deferred, owner, in_class) for child in ast.iter_child_nodes(node)]
    return binds, calls


def implement_rank_rows_problems(cells) -> list:
    name, defined, calls = IMPLEMENT_RANK_FUNCTION, None, []
    for position, (label, source) in enumerate(cells or []):
        tree = _implement_cell_tree(source)
        if tree is None:
            continue
        binds, found = _implement_cell_name_uses(tree, name)
        if binds and defined is None:
            defined = (position, min(binds), label)
        calls += [(position, line, label, called, deferred, owner) for line, called, deferred, owner in found]
    reach, grown = {owner for _p, _l, _c, called, deferred, owner in calls if called == name and deferred and owner}, True
    while grown:
        more = {owner for _p, _l, _c, called, deferred, owner in calls if called in reach and deferred and owner} - reach
        reach, grown = reach | more, bool(more)
    early = []
    for position, line, label, called, deferred, _owner in calls:
        if called == name and (defined is None or (position, line) < defined[:2] and not (deferred and position == defined[0])):
            early.append((position, line, f"{label} line {line} calls {name}" + (", but no cell defines it" if defined is None else
                                                                                f" above its definition in {defined[2]} line {defined[1]}")))
        elif called in reach and not deferred and defined is not None and (position, line) < defined[:2]:
            early.append((position, line, f"{label} line {line} calls {called}, which runs {name}, above the definition of {name} in "
                                          f"{defined[2]} line {defined[1]}"))
    if not early:
        return []
    return [f"{min(early)[2]}, so the run stops with a NameError: no Inspire cell provides {name}, so define it yourself at the top "
            "level of a cell above the first cell that calls it, as the rank rule says"]


def _implement_source_name_re(table: str):
    parts = [p.strip().strip("`") for p in str(table or "").split(".") if p.strip().strip("`")]
    return scope_read_pattern(parts) if len(parts) == 3 else None


IMPLEMENT_SOURCE_READ_OUTSIDE = " outside inspire_read_source, so the First run scope does not narrow that read: "
IMPLEMENT_UNNAMED_READ = "reads a table through a name the gate cannot see"


def _implement_read_tables(sources) -> list:
    """(table, read pattern, exact-name pattern) once for every source table of the build and every table scoped on the Launch page."""
    out, seen = [], set()
    for table in list(sources or ()) + [scope["table"] for scope in INSPIRE_TABLE_SCOPES.values()]:
        pattern = _implement_source_name_re(table)
        if pattern is None or str(table).lower() in seen:
            continue
        seen.add(str(table).lower())
        parts = [p.strip().strip("`") for p in str(table).split(".")]
        exact = re.compile("|".join(scope_name_regex(parts[i:]) for i in (0, 1, 2)), re.IGNORECASE)
        out.append((table, pattern, exact))
    return out


def _implement_table_call_spots(label, node, tables) -> list:
    """spark.table(...) and spark.read.table(...): a literal name must be one of the source tables, any other argument is a name the gate cannot see."""
    arg = node.args[0]
    if not (isinstance(arg, ast.Constant) and isinstance(arg.value, str)):
        return [(label, node.lineno, IMPLEMENT_UNNAMED_READ)]
    name = arg.value.strip()
    return [(label, node.lineno, f"names {table}") for table, _pattern, exact in tables if exact.fullmatch(name)]


def _implement_assigned_texts(tree) -> dict:
    """Each name the cell assigns a text literal to, with the texts it is assigned, one by one or unpacked from a tuple of literals."""
    out = {}

    def add(target, value):
        if isinstance(target, ast.Name) and isinstance(value, ast.Constant) and isinstance(value.value, str):
            out.setdefault(target.id, []).append(value.value)

    for node in ast.walk(tree):
        if not isinstance(node, ast.Assign):
            continue
        for target in node.targets:
            if isinstance(target, ast.Tuple) and isinstance(node.value, ast.Tuple) and len(target.elts) == len(node.value.elts):
                for name, value in zip(target.elts, node.value.elts):
                    add(name, value)
            else:
                add(target, node.value)
    return out


def _implement_view_names(tree) -> set:
    """Every name the cell makes a DataFrame view under: the variable or the literal its createOrReplaceTempView call names."""
    names = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and _implement_called_name(node) in ("createOrReplaceTempView", "createTempView", "createGlobalTempView") and node.args:
            arg = node.args[0]
            if isinstance(arg, ast.Name):
                names.add(arg.id)
            elif isinstance(arg, ast.Constant) and isinstance(arg.value, str):
                names.add(arg.value)
    return names


def _implement_names_source_table(text, tables) -> bool:
    name = str(text or "").replace("`", "").strip().lower()
    for table, _pattern, _exact in tables:
        parts = [p.strip().strip("`").lower() for p in str(table).split(".")]
        if name in {".".join(parts), ".".join(parts[1:]), parts[2]}:
            return True
    return False


def _implement_temp_view_read(expr, views, assigned, tables) -> bool:
    """A FROM or JOIN placeholder that names a view the cell made and no source table: the view's rows come from reads the gate
    checked (inspire_read_source), so the template reads no source table the gate cannot see."""
    if not isinstance(expr, ast.Name):
        return False
    texts = assigned.get(expr.id, [])
    if any(_implement_names_source_table(text, tables) for text in texts):
        return False
    return expr.id in views or any(text in views for text in texts)


def _implement_sql_call_spots(label, query, tables=(), tree=None) -> list:
    """A SQL text built in code. A FROM or JOIN name the gate cannot see is a spot: a placeholder that is not a view the cell made
    from a checked read, a placeholder with text around it, or text still being built that ends at the keyword. The text of an
    f-string is judged as one template (its placeholders are the names), never by its parts alone."""
    spots = []
    views = _implement_view_names(tree) if tree is not None else set()
    assigned = _implement_assigned_texts(tree) if tree is not None else {}
    in_template = {id(piece) for node in ast.walk(query) if isinstance(node, ast.JoinedStr) for piece in node.values}
    for part in ast.walk(query):
        if (isinstance(part, ast.Constant) and isinstance(part.value, str) and id(part) not in in_template
                and re.search(r"\b(?:FROM|JOIN)\s*$|\b(?:FROM|JOIN)\s+[`\w.]*\.\s*$", part.value, re.I)):
            spots.append((label, part.lineno, IMPLEMENT_UNNAMED_READ))
        if isinstance(part, ast.JoinedStr):
            pieces, fields = [], {}
            for index, piece in enumerate(part.values):
                if isinstance(piece, ast.Constant) and isinstance(piece.value, str):
                    pieces.append(piece.value)
                else:
                    pieces.append("{#%d}" % index)
                    fields[index] = getattr(piece, "value", None)
            for match in re.finditer(r"\b(?:FROM|JOIN)\s+([`\w.]*)\{#(\d+)\}([`\w.]*)", "".join(pieces), re.I):
                expr = fields.get(int(match.group(2)))
                if match.group(1) or match.group(3) or not _implement_temp_view_read(expr, views, assigned, tables):
                    spots.append((label, part.lineno, IMPLEMENT_UNNAMED_READ))
    return spots


def genie_joined_keys_rule(joins) -> str:
    """REQ-373: the Genie rule that names the person's join keys for the tables of a use case. Empty when the use case has no joined pair."""
    if not joins:
        return ""
    keys = "; ".join(f"{child}.{column} = {parent}.{parent_column}" for child, column, parent, parent_column in joins)
    return ("Join the tables of this use case only on the keys the person linked: " + keys + ". Read the first table of each pair as the "
            "source and join its partner with a LEFT join on those keys. A join on other keys is refused.")


def implement_join_key_problems(cells, joins) -> list:
    """REQ-373: a build joins two tables the person linked only on the person's keys. A cell that names both tables in a JOIN, and has
    no equality on the linked key columns, is refused with the keys the person linked."""
    problems = []
    for child, column, parent, parent_column in joins or ():
        child_name, parent_name = child.split(".")[-1], parent.split(".")[-1]
        qualified = lambda name: rf"(?:`?\w+`?\.)?`?{re.escape(name)}`?"
        key = re.compile(rf"{qualified(column)}\s*=\s*{qualified(parent_column)}|{qualified(parent_column)}\s*=\s*{qualified(column)}", re.I)
        for label, source in cells or []:
            text = str(source or "")
            names = all(re.search(rf"\b{re.escape(name)}\b", text, re.I) for name in (child_name, parent_name))
            if names and re.search(r"\bJOIN\b", text, re.I) and not key.search(text):
                problems.append(f"{label} joins {child} and {parent} on other keys: the person linked {column} = {parent_column}, "
                                "so the join must use those keys")
    return problems

IMPLEMENT_GOAL_SCOPE_NOTE = (" (the scope below is the only row filter: a row condition this goal names, which the scope does not list, "
                             "is superseded and does not apply)")
IMPLEMENT_KEPT_SCOPE_RULE = ("- The person's scope is the only row filter: apply exactly the filters listed above and any TABLE SCOPE line. "
                             "A row condition in the Goal, the statement or the Databricks AI instruction that neither lists is superseded "
                             "and must not be applied.")
IMPLEMENT_WHOLE_DATA_RULE = ("- The person chose Whole data: apart from any TABLE SCOPE line, read every row of each table. A row condition in "
                             "the Goal, the statement or the Databricks AI instruction (for example one payment method or one segment) is "
                             "superseded and must not be applied.")
IMPLEMENT_ROW_FILTER_CALLS = ("filter", "where")
_IMPLEMENT_SQL_CLAUSE_END = re.compile(r"\b(GROUP\s+BY|ORDER\s+BY|HAVING|LIMIT|UNION)\b", re.I)
_IMPLEMENT_SQL_EQUALITY = re.compile(r"(?:`?\w+`?\.)?`?([A-Za-z_]\w*)`?\s*(?:=|!=|<>)\s*(?:'([^']*)'|(-?\d+(?:\.\d+)?)(?!\w))")
_IMPLEMENT_SQL_IN = re.compile(r"(?:`?\w+`?\.)?`?([A-Za-z_]\w*)`?\s+(?:NOT\s+)?IN\s*\(([^)]*)\)", re.I)


def implement_allowed_row_filters(data, scopes=None):
    """REQ-389: the row conditions the person's chosen scope keeps, by column (lower case). A column filtered by = or in keeps those
    values (a list); a column filtered any other way keeps any value (None). None when the spec has no Data step, so no check runs."""
    if not isinstance(data, dict) or not isinstance(data.get("filters"), list):
        return None
    rows = list(data["filters"])
    for scope in (scopes or {}).values():
        rows += list((scope or {}).get("rows") or [])
    values_of, anything = {}, set()
    for row in rows:
        column = str((row or {}).get("column") or "").strip().lower()
        if not column:
            continue
        op, values = str(row.get("op") or "").strip().lower(), [str(v) for v in row.get("values") or []]
        if op in ("=", "in") and values:
            values_of.setdefault(column, set()).update(values)
        else:
            anything.add(column)
    return {column: None if column in anything else sorted(values_of.get(column, ())) for column in set(values_of) | anything}


def _implement_outside_lambdas(node):
    stack = [node]
    while stack:
        part = stack.pop()
        if isinstance(part, ast.Lambda):
            continue
        yield part
        stack.extend(ast.iter_child_nodes(part))


def _implement_column_of(node):
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        return node.attr
    if isinstance(node, ast.Subscript) and isinstance(node.slice, ast.Constant) and isinstance(node.slice.value, str):
        return node.slice.value
    if (isinstance(node, ast.Call) and _implement_called_name(node) in ("col", "column") and node.args
            and isinstance(node.args[0], ast.Constant) and isinstance(node.args[0].value, str)):
        return node.args[0].value
    return None


def _implement_literal_of(node):
    if isinstance(node, ast.Constant) and isinstance(node.value, (str, int, float)) and not isinstance(node.value, bool):
        return [str(node.value)]
    if isinstance(node, (ast.Tuple, ast.List, ast.Set)):
        parts = [_implement_literal_of(item) for item in node.elts]
        return [value for part in parts for value in part] if all(parts) else None
    return None


def _implement_compare_rows(node):
    rows = []
    for part in _implement_outside_lambdas(node):
        if not (isinstance(part, ast.Compare) and len(part.ops) == 1 and isinstance(part.ops[0], (ast.Eq, ast.NotEq, ast.In, ast.NotIn))):
            continue
        for column_side, literal_side in ((part.left, part.comparators[0]), (part.comparators[0], part.left)):
            column, values = _implement_column_of(column_side), _implement_literal_of(literal_side)
            if column and values is not None:
                rows.append((part.lineno, column, values))
                break
    return rows


def _implement_sql_row_conditions(text, line):
    """(line, column, values) for each equality or IN row condition in SQL text: after its WHERE when it has one, up to GROUP BY and the like."""
    text = str(text or "")
    if re.search(r"\bWHERE\b", text, re.I):
        text = re.split(r"\bWHERE\b", text, maxsplit=1, flags=re.I)[1]
    text = _IMPLEMENT_SQL_CLAUSE_END.split(text, maxsplit=1)[0]
    found = [(line, match.group(1), [match.group(2) if match.group(2) is not None else match.group(3)])
             for match in _IMPLEMENT_SQL_EQUALITY.finditer(text)]
    found += [(line, match.group(1), [value.strip().strip("'") for value in match.group(2).split(",") if value.strip()])
              for match in _IMPLEMENT_SQL_IN.finditer(text)]
    return found


def _implement_row_conditions(tree):
    found = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, (ast.Attribute, ast.Name)) and _implement_called_name(node) in IMPLEMENT_ROW_FILTER_CALLS:
            if isinstance(node.func, ast.Name) and node.func.id == "filter":
                continue
            for arg in list(node.args) + [keyword.value for keyword in node.keywords]:
                if isinstance(arg, ast.Constant) and isinstance(arg.value, str):
                    found += _implement_sql_row_conditions(arg.value, arg.lineno)
                else:
                    found += _implement_compare_rows(arg)
        elif isinstance(node, ast.Subscript):
            found += _implement_compare_rows(node.slice)
        elif isinstance(node, ast.Constant) and isinstance(node.value, str) and re.search(r"\bWHERE\b", node.value, re.I):
            found += _implement_sql_row_conditions(node.value, node.lineno)
    return found


def _implement_scope_violation(column, values, allowed, columns=None) -> str:
    """Why a row condition on `column` to `values` is outside the scope the person chose, or "" when the scope keeps it."""
    if columns is not None and column.lower() not in columns:
        return ""
    kept = allowed.get(column.lower(), "absent")
    if kept == "absent":
        return f"the scope the person chose does not keep `{column}`"
    if kept is not None and not set(values) <= set(kept):
        return f"the scope the person chose keeps `{column}` to {', '.join(repr(v) for v in kept)}"
    return ""


def _implement_and_operands(node):
    """(operands, joiner) of a chain of `and` or `&` conditions; a single condition is its own operand with no joiner."""
    if isinstance(node, ast.BoolOp) and isinstance(node.op, ast.And):
        return [leaf for part in node.values for leaf in _implement_and_operands(part)[0]], " and "
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.BitAnd):
        return _implement_and_operands(node.left)[0] + _implement_and_operands(node.right)[0], " & "
    return [node], None


def implement_drop_scope_filters(source, allowed, columns=None) -> tuple:
    """c24_rc7mvp: (new source, [(line, column)]) with every row condition that the person's scope does not keep taken out of a cell:
    a `.filter(...)`/`.where(...)` call that holds only such conditions is replaced by the frame it reads, `df[condition]` by `df`, such
    conditions inside an `and`/`&` chain are dropped and the rest kept, and a SQL `WHERE` condition becomes `1 = 1`. A condition inside
    an `or`, a `not` or a lambda is left for the check to name. A result that no longer compiles is never returned."""
    source = str(source or "")
    tree = _implement_cell_tree(source) if allowed is not None else None
    if tree is None:
        return source, []

    def breaks(node):
        return [(line, column) for line, column, values in _implement_compare_rows(node)
                if isinstance(node, ast.Compare) and _implement_scope_violation(column, values, allowed, columns)]

    def text(node):
        return source[slice(*implement_node_span(source, node))]

    def reshape(condition):
        """None when the condition holds nothing to drop, else (replacement text or None when nothing is left, dropped conditions)."""
        operands, joiner = _implement_and_operands(condition)
        gone = [(leaf, breaks(leaf)) for leaf in operands]
        if not any(found for _leaf, found in gone):
            return None
        dropped = [item for _leaf, found in gone for item in found]
        kept = [leaf for leaf, found in gone if not found]
        if not kept:
            return None, dropped
        return (text(kept[0]) if len(kept) == 1 else joiner.join(f"({text(leaf)})" for leaf in kept)), dropped

    edits, dropped = [], []
    for node in ast.walk(tree):
        if (isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr in IMPLEMENT_ROW_FILTER_CALLS
                and len(node.args) == 1 and not node.keywords and not isinstance(node.args[0], ast.Constant)):
            changed, receiver, target = reshape(node.args[0]), node.func.value, node
        elif isinstance(node, ast.Subscript) and isinstance(node.slice, (ast.Compare, ast.BoolOp, ast.BinOp)):
            changed, receiver, target = reshape(node.slice), node.value, node
        elif isinstance(node, ast.Constant) and isinstance(node.value, str) and re.search(r"\bWHERE\b", node.value, re.I):
            start, end = implement_node_span(source, node)
            literal = source[start:end]
            head, where, tail = re.split(r"(\bWHERE\b)", literal, maxsplit=1, flags=re.I) if re.search(r"\bWHERE\b", literal, re.I) else (literal, "", "")
            body, rest = (tail, "")
            clause = _IMPLEMENT_SQL_CLAUSE_END.search(tail)
            if clause:
                body, rest = tail[:clause.start()], tail[clause.start():]
            found = []

            def drop_sql(match, found=found):
                values = ([match.group(2) if match.group(2) is not None else match.group(3)] if match.re is _IMPLEMENT_SQL_EQUALITY
                          else [v.strip().strip("'") for v in match.group(2).split(",") if v.strip()])
                if _implement_scope_violation(match.group(1), values, allowed, columns):
                    found.append((node.lineno, match.group(1)))
                    return "1 = 1"
                return match.group(0)

            body = _IMPLEMENT_SQL_IN.sub(drop_sql, _IMPLEMENT_SQL_EQUALITY.sub(drop_sql, body))
            if found:
                edits.append((start, end, head + where + body + rest, found))
            continue
        else:
            continue
        if changed is None:
            continue
        replacement, found = changed
        if replacement is None:
            if isinstance(node, ast.Call) and not isinstance(receiver, (ast.Name, ast.Attribute, ast.Call, ast.Subscript)):
                continue
            edits.append((*implement_node_span(source, target), text(receiver), found))
        else:
            edits.append((*implement_node_span(source, node.args[0] if isinstance(node, ast.Call) else node.slice), replacement, found))
    edits.sort(key=lambda e: (e[0], -(e[1] - e[0])))
    taken, last_end = [], -1
    for edit in edits:
        if edit[0] >= last_end:
            taken.append(edit)
            last_end = edit[1]
    fixed = source
    for start, end, replacement, found in reversed(taken):
        fixed = fixed[:start] + replacement + fixed[end:]
        dropped = found + dropped
    try:
        ast.parse(fixed, "<cell>")
    except (SyntaxError, ValueError):
        return source, []
    return fixed, dropped


def implement_row_filter_problems(cells, allowed, columns=None) -> list:
    """REQ-389: a build cell filters rows only on the row conditions the person's chosen scope keeps. A cell that filters a column the
    scope does not keep, or a value it does not keep, is refused with the column and the values it filters to. allowed is
    implement_allowed_row_filters(...): None means no Data step, so no check runs.
    FX-93: columns is the lower-case set of real columns of the tables the build reads. A name that is no column of them (a model
    keyword such as n_estimators, a local variable, a dict key) is never a row condition. None (schema unreadable) keeps every name."""
    if allowed is None:
        return []
    problems = []
    for label, source in cells or []:
        tree = _implement_cell_tree(source)
        if tree is None:
            continue
        for line, column, values in _implement_row_conditions(tree):
            reason = _implement_scope_violation(column, values, allowed, columns)
            if not reason:
                continue
            shown = ", ".join(repr(value) for value in values)
            problems.append(f"{label} line {line} filters `{column}` to {shown}, but {reason}: read the rows the scope names and "
                            "remove this row condition")
    return list(dict.fromkeys(problems))


def implement_source_read_problems(cells, sources) -> list:
    tables = _implement_read_tables(sources)
    if not tables:
        return []
    spots = []
    for label, source in cells or []:
        tree = _implement_cell_tree(source)
        if tree is None:
            continue
        allowed = set()
        for node in ast.walk(tree):
            if isinstance(node, ast.Call) and _implement_called_name(node) in ("inspire_read_source", "print"):
                allowed.update(id(part) for part in ast.walk(node))
            if isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant):
                allowed.add(id(node.value))
        for node in ast.walk(tree):
            if id(node) in allowed:
                continue
            if isinstance(node, ast.Constant) and isinstance(node.value, str):
                spots += [(label, node.lineno, f"names {table}") for table, pattern, _exact in tables if pattern.search(node.value)]
            elif isinstance(node, ast.Call) and _implement_called_name(node) == "table" and node.args:
                spots += _implement_table_call_spots(label, node, tables)
            elif isinstance(node, ast.Call) and _implement_called_name(node) == "sql" and node.args:
                spots += _implement_sql_call_spots(label, node.args[0], tables, tree)
    if not spots:
        return []
    named = list(dict.fromkeys(f"{label} line {line} {what}" for label, line, what in spots))
    return [f"{'; '.join(named[:5])}{IMPLEMENT_SOURCE_READ_OUTSIDE}{GENIE_SOURCE_READ_RULE}"]


def implement_source_read_block(problems) -> str:
    for problem in problems or []:
        if IMPLEMENT_SOURCE_READ_OUTSIDE in problem:
            spots = problem.split(IMPLEMENT_SOURCE_READ_OUTSIDE)[0].replace(" names ", " reads ")
            return (f"{spots} without inspire_read_source, so that read skips the First run scope and the check of what you may "
                    "read, and the MVP is not published: Genie did not fix it in its build rounds")
    return ""


def implement_summary_call_problems(cells) -> list:
    trees = [(label, tree) for label, tree in ((label, _implement_cell_tree(source)) for label, source in cells) if tree is not None
             and tree.body]
    if not trees or any(isinstance(node, ast.Call) and _implement_called_name(node) == "inspire_write_summary"
                        for _label, tree in trees for node in ast.walk(tree)):
        return []
    spots = []
    for label, tree in trees:
        for function in (node for node in ast.walk(tree) if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
                         and re.search(r"summar", node.name, re.I)):
            spots += [f"{label} line {part.lineno}" for part in ast.walk(function) if isinstance(part, ast.Constant)
                      and isinstance(part.value, str) and _IMPLEMENT_AI_QUERY_CALL_RE.search(part.value)]
    spots = list(dict.fromkeys(spots))
    return ["no cell calls inspire_write_summary, so the run writes no AI summary for the App"
            + (f", and {', '.join(spots)} call{'s' if len(spots) == 1 else ''} ai_query to write the summary itself" if spots else "")
            + f": {IMPLEMENT_SUMMARY_RULE}"]


def _implement_falls_through(body) -> bool:
    if not body:
        return True
    last = body[-1]
    if isinstance(last, (ast.Return, ast.Raise)):
        return False
    if isinstance(last, ast.If):
        return _implement_falls_through(last.body) or _implement_falls_through(last.orelse)
    if isinstance(last, (ast.With, ast.AsyncWith)):
        return _implement_falls_through(last.body)
    if isinstance(last, ast.Try) or type(last).__name__ == "TryStar":
        if last.finalbody and not _implement_falls_through(last.finalbody):
            return False
        return (_implement_falls_through(last.body + last.orelse) if last.orelse else _implement_falls_through(last.body)) or any(
            _implement_falls_through(handler.body) for handler in last.handlers)
    if isinstance(last, ast.While) and isinstance(last.test, ast.Constant) and last.test.value is True:
        return any(isinstance(node, ast.Break) for node in ast.walk(last))
    return True


def _implement_own_returns(function) -> list:
    found, todo = [], list(function.body)
    while todo:
        node = todo.pop()
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda, ast.ClassDef)):
            continue
        if isinstance(node, ast.Return):
            found.append(node)
        todo.extend(ast.iter_child_nodes(node))
    return sorted(found, key=lambda node: node.lineno)


def _implement_is_notebook_exit(node) -> bool:
    if not isinstance(node, ast.Call) or not isinstance(node.func, ast.Attribute) or node.func.attr != "exit":
        return False
    owner = node.func.value
    return ((isinstance(owner, ast.Attribute) and owner.attr == "notebook")
            or (isinstance(owner, ast.Name) and owner.id == "sys"))


def implement_outcome_contract_problems(cells, need_entry: bool = False) -> list:
    trees = [(label, _implement_cell_tree(source)) for label, source in cells]
    parsed = [(label, tree) for label, tree in trees if tree is not None]
    problems = [f"{label} line {node.lineno} calls {ast.unparse(node.func)}, which ends the run before inspire_main() returns its "
                "outcome, so Inspire cannot tell what it wrote: never end the notebook yourself, return the outcome from "
                "run_use_case() instead"
                for label, tree in parsed for node in ast.walk(tree) if _implement_is_notebook_exit(node)]
    defined = [(label, node) for label, tree in parsed for node in tree.body
               if isinstance(node, ast.FunctionDef) and node.name == "run_use_case"]
    if not defined:
        if need_entry and len(parsed) == len(trees):
            problems.append("no cell defines run_use_case() at its top level, so inspire_main() has nothing to run and the run says "
                            f"nothing about what it wrote: define it with no arguments and return {IMPLEMENT_OUTCOME_SHAPE}")
        return problems
    label, function = defined[-1]
    where = f"run_use_case() in {label}"
    required = len(function.args.posonlyargs + function.args.args) - len(function.args.defaults)
    required += sum(1 for default in function.args.kw_defaults if default is None)
    if required > 0:
        problems.append(f"{where} needs {inspire_plural(required, 'argument')}, but inspire_main() calls it with none: read every "
                        "value it needs from the widgets or compute it inside")
    for node in _implement_own_returns(function):
        value = node.value
        if value is None or (isinstance(value, ast.Constant) and value.value is None):
            problems.append(f"{where} line {node.lineno} returns nothing, so that path gives no outcome: return "
                            f"{IMPLEMENT_OUTCOME_SHAPE}")
        elif isinstance(value, ast.Constant) or isinstance(value, (ast.List, ast.Tuple, ast.Set, ast.JoinedStr)):
            problems.append(f"{where} line {node.lineno} returns {ast.unparse(value)[:80]}, not the outcome dict: return "
                            f"{IMPLEMENT_OUTCOME_SHAPE}")
        elif isinstance(value, ast.Dict):
            keys = {key.value for key in value.keys if isinstance(key, ast.Constant)}
            if None not in value.keys and "status" not in keys:
                problems.append(f"{where} line {node.lineno} returns a dict with no 'status', so it is not an outcome: return "
                                f"{IMPLEMENT_OUTCOME_SHAPE}")
    if _implement_falls_through(function.body):
        problems.append(f"{where} can reach its end without a return, so that path gives no outcome: end every path with a return "
                        f"of {IMPLEMENT_OUTCOME_SHAPE}")
    return problems


_IMPLEMENT_LOOP_WRAPPERS = ("sorted", "list", "set", "tuple", "enumerate")
_IMPLEMENT_BUILD_CALLS = ("append", "extend", "update", "concat", "add")


def _implement_loop_kind(node) -> str:
    while isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id in _IMPLEMENT_LOOP_WRAPPERS and node.args:
        node = node.args[0]
    if isinstance(node, ast.Subscript):
        node = node.value
    if not (isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)):
        return ""
    if node.func.attr == "groupby":
        return "the groups of a groupby"
    return "the unique values of a column" if node.func.attr == "unique" else ""


def _implement_loop_builds(body) -> bool:
    for statement in body:
        for node in ast.walk(statement):
            if isinstance(node, (ast.Assign, ast.AugAssign, ast.AnnAssign)):
                return True
            if isinstance(node, ast.Call) and _implement_called_name(node) in _IMPLEMENT_BUILD_CALLS:
                return True
    return False


def implement_entity_loop_spots(cells) -> list:
    spots = []
    for label, source in cells:
        tree = _implement_cell_tree(source)
        if tree is None:
            continue
        found = []
        for node in ast.walk(tree):
            if isinstance(node, (ast.For, ast.AsyncFor)) and _implement_loop_builds(node.body):
                loops = [node.iter]
            elif isinstance(node, (ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp)):
                loops = [generator.iter for generator in node.generators]
            else:
                continue
            for loop in loops:
                kind = _implement_loop_kind(loop)
                if kind:
                    found.append((loop.lineno, f"{label} line {loop.lineno} loops over {kind}"))
        spots += [spot for _line, spot in sorted(found)]
    return list(dict.fromkeys(spots))


def implement_cell_title(cell) -> str:
    metadata = cell.get("metadata") if isinstance(cell, dict) else None
    return str(((metadata or {}).get("application/vnd.databricks.v1+cell") or {}).get("title") or "")


def implement_cell_text(cell) -> str:
    source = cell.get("source") if isinstance(cell, dict) else None
    return "".join(source) if isinstance(source, list) else str(source or "")


def _implement_same_code(expected: str, actual: str) -> bool:
    try:
        return ast.dump(ast.parse(expected)) == ast.dump(ast.parse(actual))
    except SyntaxError:
        return expected.strip() == actual.strip()


def implement_restore_owned_cells(cells, instruction: dict, controls: dict, helpers: dict = None) -> tuple:
    restored, changes = list(cells or []), []
    for owned, place in ((instruction, "kept"), (controls, "last"), (helpers, "before_last")):
        if owned is None:
            continue
        title = implement_cell_title(owned)
        found = [i for i, cell in enumerate(restored) if implement_cell_title(cell) == title]
        if not found:
            change = "deleted"
        elif len(found) > 1:
            change = "copied"
        elif not _implement_same_code(implement_cell_text(owned), implement_cell_text(restored[found[0]])):
            change = "edited"
        elif place == "last" and found[0] != len(restored) - 1:
            change = "moved"
        elif place == "before_last" and found[0] != len(restored) - 2:
            change = "moved"
        else:
            continue
        changes.append(f"{change} the '{title}' cell")
        for index in reversed(found):
            del restored[index]
        if place == "last":
            position = len(restored)
        elif place == "before_last":
            position = len(restored) - 1
        else:
            position = found[0] if found else 1
        restored.insert(min(position, len(restored)), owned)
    return restored, changes


def check_dashboard_definition(serialized, allowed_tables, decision: str = IMPLEMENT_DECISION_DATASET, run_versions=None, scopes=None) -> tuple:
    allowed_tables = list(allowed_tables or []) + scope_views_refs(scopes)
    errors = []
    try:
        dashboard = json.loads(serialized) if isinstance(serialized, str) else dict(serialized or {})
    except (ValueError, TypeError) as e:
        return {}, [f"dashboard.lvdash.json is not valid JSON: {redact_error(e)}"]
    shape = inspire_shell_facts.object_shape_problems(dashboard, "dashboard.lvdash.json", lists=("datasets", "pages"))
    shape = shape or [p for index, page in enumerate(dashboard.get("pages") or [])
                      for p in inspire_shell_facts.object_shape_problems(page, f"dashboard page {index + 1}", lists=("layout",))]
    if shape:
        return {}, shape
    _implement_normalize_sql_lines(dashboard.get("datasets") or [])
    datasets = dashboard.get("datasets") or []
    errors += scope_dataset_sql(datasets, "the dashboard", scopes)
    names = {str(d.get("name")) for d in datasets if isinstance(d, dict)}
    if not datasets:
        errors.append("the dashboard has no datasets")
    if decision and decision not in names:
        errors.append(f"the dashboard has no dataset named {decision}, the decision list of its first page")
    pages = dashboard.get("pages") or []
    if not pages:
        errors.append("the dashboard has no pages")
    elif decision and decision in names and not any(
            ((q.get("query") or {}).get("datasetName")) == decision
            for item in ([p for p in pages if p.get("pageType") != "PAGE_TYPE_GLOBAL_FILTERS"] or pages)[0].get("layout") or []
            for q in ((item.get("widget") or {}).get("queries") or [])):
        errors.append(f"the first page shows no widget over the {decision} dataset; it must be the decision list")
    errors += implement_dashboard_problems(dashboard)
    for rule in IMPLEMENT_DASHBOARD_RULES:
        errors += rule(dashboard)
    sql = ["".join(d.get("queryLines") or []) if isinstance(d.get("queryLines"), list) else str(d.get("query") or "") for d in datasets]
    for text in sql:
        if _IMPLEMENT_WRITE_SQL_RE.search(text):
            errors.append("a dashboard dataset writes data; datasets may only read")
    errors += _implement_flag_count_problems(sql, "a dashboard dataset")
    errors += implement_run_version_problems(sql, "a dashboard dataset", run_versions)
    unknown = _implement_unknown_tables(sql, allowed_tables)
    if unknown:
        errors.append(f"the dashboard reads tables outside this use case: {', '.join(unknown)}")
    return dashboard, errors


def implement_decision_list_problems(decision_rows, truth_rows, top_k: int = IMPLEMENT_DECISION_TOP_K,
                                     dataset: str = IMPLEMENT_DECISION_DATASET) -> list:
    decision = [{str(k).lower(): v for k, v in dict(r).items()} for r in decision_rows or []]
    truth = [{str(k).lower(): v for k, v in dict(r).items()} for r in truth_rows or []]
    if not truth:
        return []
    if not decision:
        return [f"the {dataset} dataset returned no rows, but the business output table has {inspire_plural(len(truth), 'current row')} "
                f"(WHERE {INSPIRE_CURRENT_ROWS}); show every current row ordered by rank, whatever its priority_tier"]
    columns = set(decision[0])
    if "priority_tier" not in columns or not ({"entity_id", "entity_label"} & columns):
        return [f"the {dataset} dataset must return priority_tier and entity_label (or entity_id), "
                f"so each row can be checked against the business output table"]
    ids = [t.get("entity_id") for t in truth]
    key = ("entity_id" if "entity_id" in columns and all(v not in (None, "") for v in ids) and len(set(map(str, ids))) == len(ids)
           else "entity_label")
    stored = {(str(t.get(key)), str(t.get("priority_tier"))) for t in truth}
    stored_keys = {name for name, _tier in stored}
    shown = {(str(d.get(key)), str(d.get("priority_tier"))) for d in decision}
    shown_keys = {name for name, _tier in shown}
    problems = []
    relabeled = [f"{name} shows {tier!r} but the table holds {' or '.join(sorted(repr(t) for n, t in stored if n == name))}"
                 for name, tier in sorted(shown) if name in stored_keys and (name, tier) not in stored]
    if relabeled:
        problems.append(f"the {dataset} dataset changes priority tiers ({'; '.join(relabeled[:5])}); show each "
                        "row's priority_tier exactly as the business output table stores it")
    missing = list(dict.fromkeys(str(t.get(key)) for t in truth[:max(1, int(top_k))] if str(t.get(key)) not in shown_keys))
    if missing:
        problems.append(f"the {dataset} dataset leaves out top-ranked current rows "
                        f"({', '.join(missing[:5])}); list every row WHERE {INSPIRE_CURRENT_ROWS} ordered by rank, never only some "
                        "tiers and never the newest as_of_date instead")
    return problems


def implement_latest_run_filter(result_table: str) -> str:
    return INSPIRE_CURRENT_ROWS


def _implement_positive_tier_counts(tier_counts: dict) -> dict:
    counts = {}
    for tier, rows in (tier_counts or {}).items():
        rows = int(rows or 0)
        if rows > 0:
            counts[str(tier)] = rows
    return counts


def implement_reached_no_action_tier(tier_counts: dict) -> bool:
    counts = _implement_positive_tier_counts(tier_counts)
    return bool(counts) and not any(counts.get(tier) for tier in IMPLEMENT_ACTION_TIERS)


def implement_nothing_to_act_explained(reason) -> bool:
    text = " ".join(str(reason or "").split())
    return bool(text) and not text.startswith((INSPIRE_NOTHING_TO_ACT_FLAGGED, INSPIRE_NOTHING_TO_ACT_EMPTY,
                                                INSPIRE_NOTHING_TO_ACT_UNTESTED))


IMPLEMENT_NO_METHOD = "no method"
IMPLEMENT_CANNED_REASONS = (INSPIRE_NOTHING_TO_ACT_FLAGGED, INSPIRE_NOTHING_TO_ACT_EMPTY, INSPIRE_NOTHING_TO_ACT_UNTESTED,
                            INSPIRE_NOTHING_TO_ACT_UNACCEPTED)


def implement_share_text(part, whole) -> str:
    share = 100.0 * float(part or 0) / float(whole) if whole else 0.0
    return "under 1%" if 0 < share < 1 else f"{round(share)}%"


def implement_tier_mix_warning(tier_counts: dict, run_url: str = "", profile: dict = None, methods: dict = None,
                               reason: str = "") -> str:
    if not implement_reached_no_action_tier(tier_counts):
        return ""
    counts = _implement_positive_tier_counts(tier_counts)
    mix = ", ".join(f"{implement_number_text(rows)} {tier}" for tier, rows in sorted(counts.items(), key=lambda item: (-item[1], item[0])))
    reason = " ".join(str(reason or "").split())
    canned = next((text for text in IMPLEMENT_CANNED_REASONS if reason.startswith(text)), "")
    facts = ([f"the run's reason: {canned.rstrip('.')}"] if canned
             else ["the run gave a reason of its own in nothing_to_act, which the App shows"] if reason else [])
    named = (methods or {}).get("methods") or []
    if named:
        kinds = int(methods.get("kinds") or len(named))
        if kinds == 1:
            fact = ("no row names its method in column method" if named[0][0] == IMPLEMENT_NO_METHOD
                    else "every row comes from one method in column method")
        else:
            fact = (f"its rows come from {implement_number_text(kinds)} methods in column method, the largest on "
                    f"{implement_share_text(named[0][1], sum(counts.values()))} of them")
        facts.append(fact + ("" if methods.get("versioned_rows") else ", with no registered model"))
    if profile:
        rows, valued, distinct = (int(profile.get(key) or 0) for key in ("rows", "valued", "distinct"))
        if not valued:
            facts.append("column value is empty on every row")
        elif distinct == 1:
            facts.append("every row has the same value in column value")
        else:
            span = profile.get("span")
            facts.append(f"column value holds {implement_number_text(distinct)} distinct values" + (f" spanning {implement_number_text(span)}" if span else ""))
        flagged, kinds = int(profile.get("flagged") or 0), int(profile.get("flag_kinds") or 0)
        facts.append(f"{implement_number_text(flagged)} of {inspire_plural(rows, 'row')} ({implement_share_text(flagged, rows)}) "
                     f"{'carries' if flagged == 1 else 'carry'} a data_quality_flag other than ok, in "
                     f"{inspire_plural(kinds, 'kind')}" if flagged else "no row is flagged")
    return (f"Decision list: no row of the latest run reached {' or '.join(IMPLEMENT_ACTION_TIERS)} ({mix}), so it has nobody "
            "to act on yet" + "".join(f"; {fact}" for fact in facts) + (f"; run: {run_url}" if run_url else ""))


def implement_ai_check_problems(checks, summary) -> list:
    if not isinstance(checks, dict):
        return []
    problems = [f"the AI step of the run failed: {inspire_redact_text(checks['error'], set(), '')}"] if checks.get("error") else []
    records, flagged, missing = (int(checks.get(name) or 0) for name in ("records", "flagged", "missing"))
    kinds = checks.get("kinds") if isinstance(checks.get("kinds"), dict) else {}
    if flagged:
        named = ", ".join(f"{implement_number_text(n)} {kind}" for kind, n in sorted(kinds.items(), key=lambda item: (-int(item[1] or 0), item[0])))
        problems.append(f"{implement_number_text(flagged)} of the {inspire_plural(records, 'record')} flagged 'Act now' or 'Review' with facts failed Inspire's AI checks after "
                        f"one repair round, so {'it is' if flagged == 1 else 'they are'} flagged in {INSPIRE_AI_CHECK} and show{'s' if flagged == 1 else ''} no AI reasoning"
                        + (f" ({named})" if named else ""))
    if missing:
        problems.append(f"{inspire_plural(missing, 'record', 'records')} flagged 'Act now' or 'Review' with facts "
                        f"{'holds' if missing == 1 else 'hold'} neither AI reasoning nor a flag")
    if checks.get("one_level"):
        problems.append(inspire_ai_one_level_text(records, checks["one_level"]))
    if not str(summary or "").strip():
        problems.append(f"the run wrote no AI summary, so the App has no AI summary for it: {IMPLEMENT_SUMMARY_RULE}")
    return problems


def implement_ai_check_findings(checks, summary) -> dict:
    problems = implement_ai_check_problems(checks, summary)
    fixable = bool(problems) and not checks.get("error") and bool(
        int(checks.get("flagged") or 0) or checks.get("one_level") or not str(summary or "").strip())
    return {"problems": problems, "fixable": fixable}


def implement_gate(kind: str, problems, feedback: str, event: str, failure: str, fixable: bool = True) -> dict:
    return {"kind": kind, "problems": list(problems), "feedback": feedback, "event": event, "failure": failure, "fixable": bool(fixable)}


def implement_gated_outcome(outcome: dict, gates, rounds: int) -> dict:
    found, left = dict(outcome), []
    for gate in gates or []:
        if gate["kind"] == "ai":
            found["ai_problems"] = list(gate["problems"])
            if gate["fixable"]:
                found["ai_fixable"] = True
        elif gate["kind"] == "notebook":
            left += gate["problems"]
    if left:
        found["gate_problems"] = left
    if left or found.get("ai_fixable"):
        found["gate_rounds"] = int(rounds)
    return found


def implement_run_controls_warning(path: str, error) -> str:
    return (f"Notebook: Inspire could not bring the Run controls of {path} up to date, because {error}, so its runs may not carry "
            f"forward what people did in the App; {IMPLEMENT_REBUILD_ACTION}")


_IMPLEMENT_OWN_WORDS = {}


def implement_own_words() -> str:
    words = _redact_code_words()
    if _IMPLEMENT_OWN_WORDS.get("words") is not words:
        _IMPLEMENT_OWN_WORDS.update(words=words, text="\n".join(sorted(words)))
    return _IMPLEMENT_OWN_WORDS["text"]


def implement_unfixed_text(text: str, rounds: int) -> str:
    if rounds:
        return implement_rounds_note(text, rounds, "fix this")
    return f"{text}; {IMPLEMENT_REBUILD_ACTION}"


