def implement_written_key_problems(outcome: dict, uc_id: str, counts: dict, result_table: str) -> list:
    problems = []
    as_of = str(outcome.get("as_of_date") or "")
    if not _IMPLEMENT_CALENDAR_DATE_RE.fullmatch(as_of):
        problems.append(f"run_use_case() returned as_of_date {as_of or '(empty)'}, which is not a calendar date (YYYY-MM-DD): "
                        "resolve the as-of date to a date, and when the source tables hold dates as keys into a date table, "
                        "join that table to read the date")
    rows, run_id = int(counts.get("row_count") or 0), outcome.get("run_id")
    if not rows:
        if not int(outcome.get("rows_written") or 0):
            return problems
        return problems + [f"the business output table {result_table} holds no row with run_id {run_id}, although run_use_case() "
                           f"said it wrote {inspire_plural(outcome.get('rows_written'), 'row')}: write each of those rows with the "
                           "run_id the outcome returns"]
    undated = rows - int(counts.get("dated_rows") or 0)
    if undated:
        problems.append(f"of the {inspire_plural(rows, 'row')} of run {run_id}, {inspire_plural(undated, 'has', 'have')} no as_of_date, so the change history cannot say which "
                        "run date such a row belongs to: write the resolved as-of date on every row")
    foreign = rows - int(counts.get("own_rows") or 0)
    if foreign:
        problems.append(f"of the {inspire_plural(rows, 'row')} of run {run_id}, {inspire_plural(foreign, 'carries', 'carry')} a use_case_id other than {uc_id}")
    loose = rows - int(counts["current_rows"] or 0)
    if loose:
        problems.append(f"of the {inspire_plural(rows, 'row')} of run {run_id}, {inspire_plural(loose, 'is', 'are')} not the current version of the record in {result_table}, "
                        "so no output would show such a row: write the business output only with inspire_write_result(frame, "
                        "result_table) from the Run controls cell, never with your own write")
    return problems


def _implement_text_arrays(obj):
    if isinstance(obj, dict):
        for key, value in obj.items():
            if key in ("question", "sql", "content", "instruction", "comment", "usage_guidance") and isinstance(value, str):
                obj[key] = [value]
            else:
                _implement_text_arrays(value)
    elif isinstance(obj, list):
        for value in obj:
            _implement_text_arrays(value)
    return obj


def _implement_join_spec_problems(join: dict) -> list:
    lines = [str(line).strip() for line in join.get("sql") or [] if str(line).strip()]
    if len(lines) == 2 and not lines[0].startswith("--") and lines[1] in IMPLEMENT_JOIN_TAGS:
        return []
    names = " to ".join(str((join.get(side) or {}).get("alias") or (join.get(side) or {}).get("identifier") or "?")
                        for side in ("left", "right"))
    return [f"the join spec {names} has sql {json.dumps(join.get('sql'))}; it must be exactly two items, the join condition and then "
            f"the relationship tag that matches the key's cardinality, one of {', '.join(IMPLEMENT_JOIN_TAGS)}"]


GENIE_SPACE_SECTIONS = ("config", "data_sources", "instructions", "benchmarks")


GENIE_SPACE_OBJECTS = ("config", "instructions", "data_sources", "benchmarks")
GENIE_SPACE_INNER_OBJECTS = (("instructions", "sql_snippets"),)


def normalize_genie_space(definition, allowed_tables, run_versions=None) -> tuple:
    errors = []
    try:
        data = json.loads(definition) if isinstance(definition, str) else dict(definition or {})
    except (ValueError, TypeError) as e:
        return "", "", {}, [f"genie_space.json is not valid JSON: {redact_error(e)}"]
    if not isinstance(data, dict):
        return "", "", {}, ["genie_space.json is not a JSON object"]
    space = data.get("serialized_space") if isinstance(data.get("serialized_space"), dict) else data
    if isinstance(data.get("serialized_space"), str):
        try:
            space = json.loads(data["serialized_space"])
        except ValueError as e:
            return "", "", {}, [f"serialized_space is not valid JSON: {redact_error(e)}"]
    where = "genie_space.json" if space is data else "the serialized_space of genie_space.json"
    shape = inspire_shell_facts.object_shape_problems(space, where, objects=GENIE_SPACE_OBJECTS)
    if not shape:
        shape = [p for key, inner in GENIE_SPACE_INNER_OBJECTS if isinstance(space.get(key), dict)
                 for p in inspire_shell_facts.object_shape_problems(space[key], f"{where} {key}", objects=(inner,))]
    if shape:
        return "", "", {}, shape
    title, description = str(data.get("title") or "").strip(), str(data.get("description") or "").strip()
    if not title:
        errors.append("the Genie Agent has no title")
    if space is not data:
        for key in [k for k in GENIE_SPACE_SECTIONS if k in data]:
            if key in space:
                errors.append(f"genie_space.json has {key} both at its top level and in serialized_space; keep only the one in "
                              "serialized_space")
            else:
                space[key] = data[key]
    space = _implement_normalize_sql_lines(_implement_text_arrays(json.loads(json.dumps(space))))
    space["version"] = 2

    question_ids, instruction_ids = set(), set()

    def ids(items, used):
        for item in items:
            if not re.fullmatch(r"[0-9a-f]{32}", str(item.get("id") or "")) or item["id"] in used:
                item["id"] = uuid.uuid4().hex
            used.add(item["id"])
        return items

    config = space.setdefault("config", {})
    config["sample_questions"] = ids([q if isinstance(q.get("question"), list) else dict(q, question=[str(q.get("question") or "")])
                                      for q in config.get("sample_questions") or [] if isinstance(q, dict)], question_ids)
    if isinstance(space.get("benchmarks"), dict) and "questions" in space["benchmarks"]:
        space["benchmarks"]["questions"] = ids([q for q in space["benchmarks"].get("questions") or [] if isinstance(q, dict)],
                                               question_ids)
    instructions = space.setdefault("instructions", {})
    texts = [i for i in instructions.get("text_instructions") or [] if isinstance(i, dict)]
    if len(texts) > 1:
        merged = "\n\n".join("".join(str(part) for part in (item.get("content") if isinstance(item.get("content"), list)
                                                            else [item.get("content") or ""])).strip() for item in texts)
        texts = [{"id": texts[0].get("id"), "content": merged.splitlines(keepends=True)}]
    if "text_instructions" in instructions:
        instructions["text_instructions"] = ids(texts, instruction_ids)
    for key in ("example_question_sqls", "join_specs"):
        if key in instructions:
            instructions[key] = ids([i for i in instructions.get(key) or [] if isinstance(i, dict)], instruction_ids)
    for join in instructions.get("join_specs") or []:
        errors += _implement_join_spec_problems(join)
    for key, items in list((instructions.get("sql_snippets") or {}).items()):
        instructions["sql_snippets"][key] = ids([i for i in items or [] if isinstance(i, dict)], instruction_ids)
    sources = space.setdefault("data_sources", {})
    tables = [t for t in sources.get("tables") or [] if isinstance(t, dict)]
    if not tables:
        errors.append("the Genie Agent has no tables")
    allowed_lower = {_implement_plain_table(t).lower() for t in allowed_tables or []}
    for kind, key in (("table", "tables"), ("metric view", "metric_views")):
        if key not in sources:
            continue
        items = [s for s in sources.get(key) or [] if isinstance(s, dict)]
        for item in items:
            name = _implement_plain_table(item.get("identifier"))
            if not name:
                errors.append(f"a {kind} of the Genie Agent has no identifier: name it as catalog.schema.name")
            elif not implement_use_case_table(name, allowed_lower):
                errors.append(f"the Genie Agent uses {kind} {name}, which is outside this use case")
        sources[key] = items
    if not config["sample_questions"]:
        errors.append("the Genie Agent has no sample questions, so it cannot be smoke-tested")
    sql = _implement_sql_texts(instructions)
    if any(_IMPLEMENT_WRITE_SQL_RE.search(text) for text in sql):
        errors.append("an example SQL of the Genie Agent writes data")
    errors += _implement_flag_count_problems(sql, "an example SQL of the Genie Agent")
    errors += implement_run_version_problems(sql, "an example SQL of the Genie Agent", run_versions)
    unknown = _implement_unknown_tables(sql, allowed_tables)
    if unknown:
        errors.append(f"the Genie Agent's SQL reads tables outside this use case: {', '.join(unknown)}")
    genie_sorted_tables(space)
    return title, description, space, errors


def implement_genie_question_problems(definition, sample_questions, user_questions) -> tuple:
    def key(text):
        return " ".join(str(text or "").split()).casefold()

    asked = [" ".join(str(q).split()) for q in user_questions or [] if str(q).strip()]
    present = {key(q) for q in sample_questions or []}
    errors = [f"the space leaves out the user's question {q!r}: include it word for word as a sample question, with an example SQL "
              "that answers it" for q in asked if key(q) not in present]
    try:
        data = json.loads(definition) if isinstance(definition, str) else dict(definition or {})
    except (ValueError, TypeError):
        data = {}
    raw = data.get("question_notes") if isinstance(data, dict) else None
    if raw is None or raw == []:
        return [], errors
    if not isinstance(raw, list):
        return [], errors + ['question_notes must be a list of {"question": ..., "note": ...} objects']
    own = {key(q): q for q in asked}
    notes, noted = [], set()
    for item in raw:
        question = " ".join(str(item.get("question") or "").split()) if isinstance(item, dict) else ""
        note = " ".join(str(item.get("note") or "").split()) if isinstance(item, dict) else ""
        if not question:
            errors.append('each question_notes entry needs a "question" and a "note"')
        elif key(question) not in own:
            errors.append(f"question_notes covers {question!r}, which is not one of the user's questions: rewrite that question so it "
                          "asks about what the business output table holds, and leave it out of question_notes")
        elif not note:
            errors.append(f"the note for the user's question {question!r} is empty: say in one sentence what its answer shows instead")
        elif key(question) not in noted:
            noted.add(key(question))
            notes.append({"question": own[key(question)], "note": note[:500]})
    return notes, errors


def implement_question_note_warning(note: dict) -> str:
    return (f"Genie Agent: your question {note['question']!r} asks about something the results do not hold, so the space "
            f"answers it with what they hold: {note['note']}")


IMPLEMENT_QUESTION_NO_ROWS = "its example SQL returned no rows on the real tables"
IMPLEMENT_QUESTION_NO_PROOF = "the Genie Agent has no example SQL for it that returns rows, so nothing proves it has an answer"


def implement_user_questions(outputs, names) -> dict:
    outputs = outputs or {}
    said = [_implement_genie_fold(text) for name in names for text in implement_vibed_assets(outputs, name).values()]
    if "app" in names:
        said.append(_implement_genie_fold(outputs.get("app_purpose")))
    return {"asked": {_implement_genie_fold(q) for q in outputs.get("genie_questions") or [] if str(q).strip()},
            "said": [text for text in said if text]}


def implement_user_asked(question, user) -> bool:
    key = _implement_genie_fold(question)
    return bool(key) and (key in user["asked"] or any(key in text for text in user["said"]))


def implement_question_reason(proof: dict) -> str:
    return f"its example SQL failed: {proof['error']}" if proof.get("error") else IMPLEMENT_QUESTION_NO_ROWS


def implement_question_proven(proof: dict) -> bool:
    return bool(proof.get("rows")) and not proof.get("error")


def implement_question_problem(proof: dict, advice: str = "") -> str:
    if proof.get("error"):
        return f"the example SQL for {proof['question']!r} failed: {proof['error']}"
    return f"the example SQL for {proof['question']!r} returned no rows on the real tables{advice}"


def implement_genie_question_triage(proofs, user, final: bool, held: str = "") -> tuple:
    unproven = [p for p in proofs if not implement_question_proven(p) and not implement_user_asked(p["question"], user)]
    if not final:
        advice = (f", so that sample question promises an answer the data does not hold: ask about what the rows hold now{held}, and "
                  "test that its example SQL returns rows")
        return [], [implement_question_problem(p, advice) for p in unproven]
    if not unproven or len(unproven) < len(proofs):
        return unproven, []
    return unproven, [implement_question_problem(p) for p in unproven]


def implement_drop_genie_questions(space: dict, dropped) -> None:
    keys = {_implement_genie_fold(p["question"]) for p in dropped}
    config, told = space.setdefault("config", {}), space.setdefault("instructions", {})
    config["sample_questions"] = [q for q in config.get("sample_questions") or []
                                  if _implement_genie_fold("".join(q.get("question") or [])) not in keys]
    if "example_question_sqls" in told:
        told["example_question_sqls"] = [e for e in told.get("example_question_sqls") or []
                                         if _implement_genie_fold("".join(e.get("question") or [])) not in keys]


def implement_dropped_questions_text(pairs) -> str:
    return "; ".join(f"{question!r} ({reason})" for question, reason in pairs)


def implement_tier_mix_text(counts) -> str:
    if not counts:
        return ""
    tiers = list(INSPIRE_PRIORITY_TIERS) + sorted(t for t in counts if t not in INSPIRE_PRIORITY_TIERS)
    return " (the latest run has " + ", ".join(f"{inspire_plural(counts.get(t, 0), 'row')} at {t}" for t in tiers) + ")"


def implement_unproven_question_warning(where: str, question: str, reason: str) -> str:
    return (f"{where}: your question {question!r} stays as you asked it, but {reason}, so its answer may say there is no data; "
            "ask it about what the results hold")


def implement_app_genie_questions(asked, proofs, own, user, cap: int = IMPLEMENT_APP_GENIE_SUGGESTIONS) -> tuple:
    proven = {_implement_genie_fold(p["question"]): p["question"] for p in proofs or [] if implement_question_proven(p)}
    reasons = {_implement_genie_fold(p["question"]): implement_question_reason(p) for p in proofs or []
               if not implement_question_proven(p)}
    kept, dropped, unproven, seen = [], [], [], set()
    for question in asked or []:
        text = " ".join(question.split()) if isinstance(question, str) else ""
        key = _implement_genie_fold(text)
        if not key or key in seen:
            continue
        seen.add(key)
        if key in proven:
            kept.append(text)
        elif implement_user_asked(text, user):
            kept.append(text)
            unproven.append((text, reasons.get(key) or IMPLEMENT_QUESTION_NO_PROOF))
        else:
            dropped.append((text, reasons.get(key) or IMPLEMENT_QUESTION_NO_PROOF))
    for question in own or [p["question"] for p in proofs or []]:
        key = _implement_genie_fold(question)
        if len(kept) >= cap:
            break
        if key in proven and key not in seen:
            seen.add(key)
            kept.append(proven[key])
    return kept, dropped, unproven


_IMPLEMENT_SQL_QUOTED_RE = re.compile(r"'(?:[^'\\]|\\.)*'|\"(?:[^\"\\]|\\.)*\"|--[^\n]*|/\*.*?\*/", re.S)
_IMPLEMENT_NAME_TOKEN = r"(?:`[^`]+`|[A-Za-z_]\w*)"
_IMPLEMENT_DOTTED_RE = re.compile(r"(?<![\w`.])" + _IMPLEMENT_NAME_TOKEN + r"(?:\s*\.\s*" + _IMPLEMENT_NAME_TOKEN + r")+(?![\w`(])")
_IMPLEMENT_ALIAS_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")


def _implement_genie_fold(text) -> str:
    return " ".join(str(text or "").split()).casefold()


def _implement_genie_words(value) -> str:
    return " ".join("".join(str(v) for v in value).split() if isinstance(value, list) else str(value or "").split())


def implement_sql_column_refs(sql) -> list:
    plain = _IMPLEMENT_SQL_QUOTED_RE.sub(" ", str(sql or ""))
    return [tuple(part.strip("`") for part in re.findall(_IMPLEMENT_NAME_TOKEN, match.group(0)))
            for match in _IMPLEMENT_DOTTED_RE.finditer(plain)]


def implement_genie_aliases(identifiers) -> dict:
    names = {}
    for identifier in identifiers or []:
        if identifier:
            names.setdefault(_implement_plain_table(identifier).lower(), _implement_plain_table(identifier))
    aliases = {}
    for key in sorted(names):
        parts = names[key].split(".")
        taken = {a.lower() for a in aliases.values()}
        aliases[key] = parts[-1] if parts[-1].lower() not in taken else f"{parts[-2]}_{parts[-1]}"
    return aliases


def implement_genie_column_flags(name: str, data_type, free_text_tokens=()) -> tuple:
    family = _metadata_type_family(data_type)
    if DEEP_PII_NAME_RE.search(str(name or "")) or family not in ("string", "numeric", "temporal", "boolean"):
        return False, False
    words = {_singular_token(t) for t in _name_tokens(name)}
    free = (bool(words & {_singular_token(t) for t in tuple(free_text_tokens) + IMPLEMENT_GENIE_FREE_TEXT_TOKENS})
            or str(name or "").lower() in INSPIRE_AI_NAMES + (INSPIRE_AI_FACTS, INSPIRE_VALUE_FORMULA))
    return not free, family == "string" and not free and not _is_key_like_column(name)


def implement_genie_synonyms(values, column: str, others=()) -> list:
    blocked = {_implement_genie_fold(n) for name in (column, *others) for n in (name, str(name).replace("_", " "))}
    out, seen = [], set()
    for value in values if isinstance(values, list) else [values] if isinstance(values, str) else []:
        text = " ".join(str(value or "").split())
        key = text.casefold()
        if text and len(text) <= IMPLEMENT_GENIE_SYNONYM_CHARS and key not in blocked and key not in seen:
            seen.add(key)
            out.append(text)
    return out[:IMPLEMENT_GENIE_MAX_SYNONYMS]


def _implement_genie_column_configs(table: dict, known: dict, everything: bool, free_text_tokens, budget: list, hidden=()) -> list:
    identifier, problems, configs = _implement_plain_table(table.get("identifier")), [], {}
    for config in table.get("column_configs") or []:
        name = str((config or {}).get("column_name") or "").strip().strip("`") if isinstance(config, dict) else ""
        if name.lower() not in known:
            problems.append(f"the Genie Agent configures column {name or '(no name)'} of {identifier}, which {identifier} does not have; "
                            f"configure only its real columns: {', '.join(n for n, _t, _c in list(known.values())[:40])}")
        else:
            configs.setdefault(name.lower(), config)
    for key, (name, _kind, _comment) in known.items():
        if key not in configs and (everything or DEEP_PII_NAME_RE.search(name)):
            configs[key] = {}
    out, undescribed = [], []
    for key, config in configs.items():
        name, kind, comment = known[key]
        example_values, entity = implement_genie_column_flags(name, kind, free_text_tokens)
        if "*" in hidden or key in hidden:
            example_values = entity = False
        entity = entity and budget[0] > 0
        budget[0] -= int(entity)
        entry = {"column_name": name}
        description = _implement_genie_words(config.get("description")) or " ".join(str(comment or "").split())
        if description:
            entry["description"] = [description]
        else:
            undescribed.append(name)
        synonyms = implement_genie_synonyms(config.get("synonyms"), name, [n for k, (n, _t, _c) in known.items() if k != key])
        if synonyms:
            entry["synonyms"] = synonyms
        entry["enable_format_assistance"], entry["enable_entity_matching"] = example_values, entity
        out.append(entry)
    if everything and undescribed:
        problems.append(f"describe every column of the business output table {identifier} in business terms, in its column_configs: "
                        f"{', '.join(sorted(undescribed))} {'has' if len(undescribed) == 1 else 'have'} no description")
    table["column_configs"] = sorted(out, key=lambda c: c["column_name"])
    return problems


def _implement_genie_join_problems(instructions: dict, tables: dict, real: dict, aliases: dict, inputs: list) -> list:
    problems, joined = [], set()
    for join in instructions.get("join_specs") or []:
        sides, before = {}, len(problems)
        for side in ("left", "right"):
            ref = join.get(side) if isinstance(join.get(side), dict) else {}
            identifier = _implement_plain_table(ref.get("identifier"))
            if identifier.lower() not in tables:
                problems.append(f"a join spec joins {identifier or '(no table)'}, which is not a table of the Genie Agent")
                continue
            alias = str(ref.get("alias") or "").strip().strip("`") or aliases[identifier.lower()]
            join[side] = {"identifier": tables[identifier.lower()], "alias": alias}
            sides[alias.lower()] = identifier.lower()
        lines = [str(line) for line in join.get("sql") or []]
        if len(sides) != 2:
            if len(problems) == before:
                problems.append("each join spec joins two tables of the Genie Agent with two different aliases")
            continue
        joined.update(sides.values())
        if len(lines) != 2:
            continue
        names = " to ".join(join[side]["alias"] for side in ("left", "right"))
        refs = implement_sql_column_refs(lines[0])
        if not refs:
            problems.append(f"the join spec {names} names no column: write its condition as `alias`.`column` = `alias`.`column`")
        for parts in refs:
            owner = sides.get(parts[0].lower())
            if owner is None or len(parts) != 2:
                problems.append(f"the join spec {names} reads {'.'.join(parts)}: qualify each column with the alias of its left or right "
                                f"table ({', '.join(join[side]['alias'] for side in ('left', 'right'))})")
            elif parts[1].lower() not in real[owner]:
                problems.append(f"the join spec {names} reads {parts[1]}, which {tables[owner]} does not have")
    lonely = [tables[t] for t in inputs if t not in joined]
    if lonely and len(inputs) > 1:
        problems.append(f"{', '.join(lonely)} {'joins' if len(lonely) == 1 else 'join'} no other table of the Genie Agent: add a join "
                        "spec for each, on the keys the notebook joins them by")
    return problems


def _implement_genie_snippet_problems(instructions: dict, real: dict, alias_tables: dict) -> list:
    snippets = instructions.get("sql_snippets")
    if snippets is None:
        return []
    if not isinstance(snippets, dict):
        return ["instructions.sql_snippets must be an object with filters, expressions and measures"]
    problems = []
    for kind in list(snippets):
        if kind not in IMPLEMENT_GENIE_SNIPPET_KINDS:
            problems.append(f"sql_snippets.{kind} is not one of {', '.join(IMPLEMENT_GENIE_SNIPPET_KINDS)}")
            continue
        named = set()
        for item in snippets[kind] or []:
            sql = "".join(item.get("sql") or []).strip()
            alias = str(item.get("alias") or "").strip()
            label = f"the {kind[:-1]} {_implement_genie_words(item.get('display_name')) or alias or sql[:60]!r}"
            if kind == "filters":
                item.pop("alias", None)
            elif not _IMPLEMENT_ALIAS_RE.match(alias) or alias.lower() in named:
                problems.append(f"{label} needs its own alias, a name of letters, digits and underscores")
            named.add(alias.lower())
            if not _implement_genie_words(item.get("display_name")):
                if kind == "filters":
                    problems.append(f"{label} needs a display_name")
                else:
                    item["display_name"] = alias.replace("_", " ")
            plain = _IMPLEMENT_SQL_QUOTED_RE.sub(" ", sql)
            if not sql or ";" in plain or re.search(r"\b(SELECT|FROM)\b", plain, re.I) or _IMPLEMENT_WRITE_SQL_RE.search(plain):
                problems.append(f"{label} must be one SQL expression over `table`.`column` names, never a query or a statement")
                continue
            readers, refs = set(), implement_sql_column_refs(sql)
            for parts in refs:
                owner = alias_tables.get(parts[0].lower())
                if owner is None or len(parts) < 2:
                    problems.append(f"{label} reads {'.'.join(parts)}: name each column as `table`.`column` with one of "
                                    f"{', '.join(sorted(alias_tables))}")
                elif parts[1].lower() not in real[owner]:
                    problems.append(f"{label} reads {parts[1]}, which {owner} does not have")
                else:
                    readers.add(owner)
            if not refs and kind == "measures" and len(set(alias_tables.values())) == 1 and implement_genie_measure_shape(sql)[:2] == ("count", "1"):
                pass
            elif not refs:
                problems.append(f"{label} names no column: name each column as `table`.`column`"
                                + (", and count rows as COUNT(`table`.`key column`) so Genie knows which table it counts"
                                   if implement_genie_measure_shape(sql)[:2] == ("count", "1") else ""))
            elif len(readers) > 1:
                problems.append(f"{label} reads more than one table; a SQL expression reads one table, so write logic across tables "
                                "as an example SQL")
            item["synonyms"] = implement_genie_synonyms(item.get("synonyms"), alias or "")
            if not item["synonyms"]:
                item.pop("synonyms")
    return problems


def _implement_genie_benchmark_problems(space: dict, asked: set, tables: list) -> list:
    benchmarks = space.get("benchmarks") if isinstance(space.get("benchmarks"), dict) else {}
    problems, kept, seen = [], 0, set()
    for item in benchmarks.get("questions") or []:
        question = _implement_genie_words(item.get("question"))
        answers = [a for a in item.get("answer") or [] if isinstance(a, dict) and str(a.get("format") or "").upper() == "SQL"]
        sql = "".join(str(line) for line in (answers[0].get("content") or [])).strip() if len(answers) == 1 else ""
        if not question or len(answers) != 1 or not sql:
            problems.append(f"the benchmark {question or '(no question)'!r} needs exactly one answer of format SQL with its gold query")
        elif _implement_genie_fold(question) in asked:
            problems.append(f"the benchmark {question!r} repeats a sample question or an example SQL question; a benchmark asks what "
                            "the examples do not answer word for word")
        elif _implement_genie_fold(question) in seen:
            problems.append(f"the benchmark {question!r} is asked twice")
        elif _IMPLEMENT_WRITE_SQL_RE.search(sql):
            problems.append(f"the benchmark SQL for {question!r} writes data")
        elif _implement_unknown_tables([sql], tables):
            problems.append(f"the benchmark SQL for {question!r} reads tables outside the Genie Agent: "
                            f"{', '.join(_implement_unknown_tables([sql], tables))}")
        else:
            seen.add(_implement_genie_fold(question))
            item["answer"] = [{"format": "SQL", "content": implement_join_lines(answers[0].get("content") or [])}]
            kept += 1
    if kept < IMPLEMENT_GENIE_MIN_BENCHMARKS:
        problems.append(f"the Genie Agent has {inspire_plural(kept, 'benchmark question')} with a gold SQL answer; write at least "
                        f"{IMPLEMENT_GENIE_MIN_BENCHMARKS}, each a question a decision owner asks that the examples do not answer word "
                        "for word, with one answer of format SQL")
    return problems


def _implement_join_kind(lines) -> str:
    tag = str(lines[1]).strip() if len(lines) == 2 else ""
    return tag[len("--rt=FROM_RELATIONSHIP_TYPE_"):-2] if tag in IMPLEMENT_JOIN_TAGS else ""


def implement_genie_many_sides(instructions, result_table: str) -> list:
    result, many = _implement_plain_table(result_table).lower(), []
    for join in (instructions or {}).get("join_specs") or []:
        if not isinstance(join, dict):
            continue
        sides = [_implement_plain_table((join.get(side) if isinstance(join.get(side), dict) else {}).get("identifier"))
                 for side in ("left", "right")]
        kind = _implement_join_kind([str(line) for line in join.get("sql") or []])
        for mine, other, fans in ((0, 1, ("ONE_TO_MANY", "MANY_TO_MANY")), (1, 0, ("MANY_TO_ONE", "MANY_TO_MANY"))):
            if (sides[mine].lower() == result and sides[other] and sides[other].lower() != result and kind in fans
                    and sides[other].lower() not in {m.lower() for m in many}):
                many.append(sides[other])
    return many


def implement_genie_grain_fact(result_table: str, many) -> str:
    result, names = _implement_plain_table(result_table), [f"`{_implement_plain_table(m)}`" for m in many]
    them = names[0] if len(names) == 1 else "that table"
    return (f"Each row of `{result}` holds one value per entity for its run, so each of its measures belongs to an entity once. "
            f"{', '.join(names)} {'holds' if len(names) == 1 else 'each hold'} many rows per entity, so a join from `{result}` to "
            f"{them} repeats an entity's measures once per matched row: never SUM or AVG a measure of `{result}` over that join. "
            f"It repeats the entity's row too, so never COUNT(*) or COUNT a column of `{result}` over that join: count the entities "
            f"once with COUNT(DISTINCT `{INSPIRE_HISTORY_NAMES[0]}`). "
            f"When a question splits those measures by a column of {them}, first aggregate {them} to one row per entity (such as "
            f"each entity's most common value of that column, or each value's share of the entity's rows), join that to `{result}`, "
            f"and add each entity's measure once, or attribute it by that share. A count of the rows of {them} comes from {them} "
            "alone.")


def implement_fanout_sums(sql: str, result_table: str, many, real: dict) -> tuple:
    import sqlglot
    from sqlglot import exp
    real = real or {}
    result = _implement_plain_table(result_table).lower()
    fanned = {_implement_plain_table(m).lower(): _implement_plain_table(m) for m in many or ()}
    known = sorted({result, *fanned, *real}, key=len, reverse=True)
    reasons = implement_reasons_view(result).lower()
    try:
        trees = [t for t in sqlglot.parse(str(sql or ""), read="databricks") if t is not None]
    except sqlglot.errors.SqlglotError:
        return [], [], []
    summed, spread, counted = [], {}, []
    for tree in trees:
        ctes = {str(c.alias_or_name).lower(): c.this for c in tree.find_all(exp.CTE)}
        carried_by = {}

        def owner(node):
            if not isinstance(node, exp.Table) or not node.name or (not node.db and node.name.lower() in ctes):
                return ""
            plain = ".".join(p for p in (node.catalog, node.db, node.name) if p).lower()
            return next((k for k in known if k == plain or k.endswith("." + plain)), "")

        def body(node):
            if isinstance(node, exp.Subquery):
                return node.this
            if isinstance(node, exp.Table) and not node.db and node.name.lower() in ctes:
                return ctes[node.name.lower()]
            return None

        def terms(node):
            if isinstance(node, (exp.And, exp.Paren, exp.Where)):
                for part in ([node.this] if isinstance(node, (exp.Paren, exp.Where)) else [node.left, node.right]):
                    yield from terms(part)
            elif node is not None:
                yield node

        def pinned(select, keys) -> set:
            conditions = [t for c in [select.args.get("where")] + [j.args.get("on") for j in select.args.get("joins") or []]
                          for t in terms(c)]

            def named(node, alias, name, bare=False):
                return (isinstance(node, exp.Column) and node.name.lower() == name
                        and ((node.table or "").lower() == alias or (bare and not node.table)))

            def pinned_at(alias):
                position = any(isinstance(t, exp.EQ) and any(named(a, alias, "reason_position", True) and isinstance(b, exp.Literal)
                                                             for a, b in ((t.left, t.right), (t.right, t.left))) for t in conditions)
                current = any(named(t, alias, "is_current") or (isinstance(t, exp.EQ) and any(
                    named(a, alias, "is_current") and isinstance(b, exp.Boolean) and b.this is True
                    for a, b in ((t.left, t.right), (t.right, t.left)))) for t in conditions)
                return position and current

            return {a for a, k in keys.items() if k == reasons and pinned_at(a)}

        def scope(select):
            start = select.args.get("from_") or select.args.get("from")
            sources = ([start.this] if start else []) + [j.this for j in select.args.get("joins") or []
                                                        if str(j.args.get("kind") or "").upper() not in ("SEMI", "ANTI")]
            keys = {str(s.alias_or_name).lower(): owner(s) for s in sources}
            derived = {str(s.alias_or_name).lower(): carried(body(s)) for s in sources if body(s) is not None}
            mine = {a for a, k in keys.items() if k == result}
            once = pinned(select, keys)
            joined = {k: fanned[k] for a, k in keys.items() if k in fanned and a not in once}
            fans_at = {a for a, k in keys.items() if k in fanned and a not in once}
            for lateral in select.args.get("laterals") or []:
                if isinstance(lateral.this, (exp.Explode, exp.Inline)):
                    joined[lateral.this.sql(dialect="databricks").lower()] = lateral.this.sql(dialect="databricks")
                    named = lateral.args.get("alias")
                    fans_at |= {str(named.name).lower()} | {str(c.name).lower() for c in named.columns} if named else set()
            for item in select.expressions:
                for found in item.find_all(exp.Explode, exp.Inline):
                    if found.find_ancestor(exp.Select) is select:
                        joined[found.sql(dialect="databricks").lower()] = found.sql(dialect="databricks")
            return keys, mine, joined if mine else {}, derived, fans_at

        def reads(column, keys, mine, joined, derived, fans_at) -> dict:
            name = column.name.lower()
            if column.table:
                alias = column.table.lower()
                return dict(joined) if alias in mine else dict(derived.get(alias, {}).get(name, {}))
            if joined and len(keys) == 1 and mine and name not in fans_at:
                return dict(joined)
            if (joined and all(keys.values()) and name in real.get(result, {})
                    and not any(name in real.get(k, {}) for k in set(keys.values()) - {result})):
                return dict(joined)
            holders = [d[name] for d in derived.values() if name in d]
            tabled = any(name in real.get(k, {}) for k in keys.values() if k)
            return dict(holders[0]) if len(holders) == 1 and not tabled else {}

        def carried(node, depth=0) -> dict:
            if node is None or depth > 24:
                return {}
            if id(node) in carried_by:
                return carried_by[id(node)]
            carried_by[id(node)] = {}
            if isinstance(node, exp.Subquery):
                out = carried(node.this, depth + 1)
            elif isinstance(node, exp.SetOperation):
                out = {**carried(node.left, depth + 1), **carried(node.right, depth + 1)}
            elif isinstance(node, exp.Select):
                keys, mine, joined, derived, fans_at = scope(node)
                out = {}
                for item in node.expressions:
                    star = isinstance(item, exp.Star) or (isinstance(item, exp.Column) and isinstance(item.this, exp.Star))
                    if star:
                        qualifier = item.table.lower() if isinstance(item, exp.Column) else ""
                        if joined and (not qualifier or qualifier in mine):
                            out.update({n: dict(joined) for n in real.get(result, {})})
                        for alias, inner in derived.items():
                            if not qualifier or qualifier == alias:
                                out.update(inner)
                        continue
                    if item.find(exp.AggFunc):
                        continue
                    fans = {}
                    for column in item.find_all(exp.Column):
                        if column.find_ancestor(exp.Select) is node:
                            fans.update(reads(column, keys, mine, joined, derived, fans_at))
                    if fans:
                        out[str(item.alias_or_name).lower()] = fans
                group = node.args.get("group")
                if out and (group or node.args.get("distinct")):
                    grain = group.expressions if group else node.expressions
                    still = any(g.find(exp.Explode, exp.Inline) or any((c.table or c.name).lower() in fans_at for c in g.find_all(exp.Column))
                                for g in grain)
                    out = out if still else {}
            else:
                out = {}
            carried_by[id(node)] = out
            return out

        def listed(select) -> list:
            picked, group = list(select.expressions), select.args.get("group")
            exprs = [picked[int(g.name) - 1] if isinstance(g, exp.Literal) and g.is_int and 0 < int(g.name) <= len(picked) else g
                     for g in (group.expressions if group else picked)]
            return [c for e in exprs for c in ([e] if isinstance(e, (exp.Column, exp.Star)) else e.find_all(exp.Column))
                    if isinstance(c, exp.Star) or not any(isinstance(a, exp.AggFunc) for a in iter_ancestors(c, e))]

        def iter_ancestors(node, top):
            while node is not None and node is not top:
                node = node.parent
                yield node

        def deep_sources(select) -> dict:
            start = select.args.get("from_") or select.args.get("from")
            sources = ([start.this] if start else []) + [j.this for j in select.args.get("joins") or []]
            return {str(s.alias_or_name).lower(): body(s) for s in sources if body(s) is not None}

        def many_rows(node, depth=0) -> bool:
            if node is None or depth > 24:
                return False
            if isinstance(node, exp.Subquery):
                return many_rows(node.this, depth + 1)
            if isinstance(node, exp.SetOperation):
                return many_rows(node.left, depth + 1) or many_rows(node.right, depth + 1)
            return isinstance(node, exp.Select) and many_grain(node, depth)

        def many_grain(select, depth=0) -> bool:
            keys, _mine, _joined, _derived, fans_at = scope(select)
            deep = {a for a, b in deep_sources(select).items() if many_rows(b, depth + 1)}
            tables = {k for k in keys.values() if k in fanned}

            def many(column):
                if isinstance(column, exp.Star):
                    return bool(tables or deep)
                alias, name = (column.table or "").lower(), column.name.lower()
                if isinstance(column.this, exp.Star):
                    return alias in fans_at or alias in deep
                if alias:
                    return alias in fans_at or alias in deep
                return name in fans_at or (any(name in real.get(k, {}) for k in tables) and name not in real.get(result, {}))

            return any(many(c) for c in listed(select))

        def per_record(select, mine) -> bool:
            group = select.args.get("group")
            return bool(group) and any(isinstance(g, exp.Column) and g.name.lower() in (INSPIRE_HISTORY_NAMES[0], "entity_id")
                                       and (not g.table or g.table.lower() in mine) for g in group.expressions)

        for select in tree.find_all(exp.Select):
            keys, mine, joined, derived, fans_at = scope(select)
            if not joined and not any(derived.values()):
                continue
            for agg in select.find_all(exp.Sum, exp.Avg, exp.Count, exp.CountIf):
                if agg.find_ancestor(exp.Select) is not select:
                    continue
                counts = isinstance(agg, (exp.Count, exp.CountIf))
                if counts and (isinstance(agg.this, exp.Distinct) or per_record(select, mine) or many_grain(select)):
                    continue
                columns = [c for c in agg.find_all(exp.Column) if c.find_ancestor(exp.Select) is select]
                if counts and not columns and any(many_rows(b) for b in deep_sources(select).values()):
                    continue
                if counts and not columns:
                    rows = dict(joined)
                    for inner in derived.values():
                        for fans in inner.values():
                            rows.update(fans)
                    if rows:
                        counted.append(f"COUNT({agg.this.sql(dialect='databricks') if agg.this else '*'})")
                        spread.update(rows)
                    continue
                for column in columns:
                    fans = reads(column, keys, mine, joined, derived, fans_at)
                    if fans:
                        (counted if counts else summed).append(column.name)
                        spread.update(fans)
    return list(dict.fromkeys(summed)), [spread[k] for k in sorted(spread)], list(dict.fromkeys(counted))


def implement_genie_fanout_problems(space: dict, result_table: str, many, real: dict) -> list:
    if not many:
        return []
    instructions = space.get("instructions") if isinstance(space.get("instructions"), dict) else {}
    queries = [(f"the example SQL for {_implement_genie_words(e.get('question'))!r}", "".join(str(l) for l in e.get("sql") or []))
               for e in instructions.get("example_question_sqls") or [] if isinstance(e, dict)]
    queries += [(f"the benchmark SQL for {_implement_genie_words(q.get('question'))!r}",
                 "".join(str(l) for a in q.get("answer") or [] if isinstance(a, dict) for l in a.get("content") or []))
                for q in (space.get("benchmarks") or {}).get("questions") or [] if isinstance(q, dict)]
    problems, key = [], INSPIRE_HISTORY_NAMES[0]
    for label, sql in queries:
        summed, spread, counted = implement_fanout_sums(sql, result_table, many, real)
        names = ", ".join(spread)
        if summed:
            problems.append(f"{label} adds up {', '.join(summed)} of the business output table "
                            f"{_implement_plain_table(result_table)} over a join to {names}, which holds many rows per entity, so each "
                            f"entity's value is counted once per matched row: aggregate {names} to one row per entity in a subquery "
                            "first, then join that and add each entity's value once")
        if counted:
            problems.append(f"{label} counts {', '.join(counted)} of the business output table "
                            f"{_implement_plain_table(result_table)} over a join to {names}, which holds many rows per entity, so each "
                            f"entity is counted once per matched row: count the entities with COUNT(DISTINCT {key}), or count after a "
                            f"subquery that first aggregates {names} to one row per entity")
    return problems


def implement_page_many_sides(result_table: str, artifacts=None) -> list:
    space = ((artifacts or {}).get("genie_space") or {}).get("serialized_space")
    joined = implement_genie_many_sides(space.get("instructions"), result_table) if isinstance(space, dict) else []
    out = []
    for table in [implement_reasons_view(result_table), inspire_run_log_table(result_table)] + joined:
        if table.lower() not in {t.lower() for t in out}:
            out.append(table)
    return out


def implement_table_leaf(table) -> str:
    return _implement_plain_table(table).split(".")[-1]


def _implement_names_table(text, table) -> bool:
    return inspire_shell_facts.names_table(text, implement_table_leaf(table))


def implement_page_fanning(page: dict, many) -> dict:
    return inspire_shell_facts.fanning_datasets(page, [implement_table_leaf(m) for m in many or ()])


def implement_page_fanout_problems(page: dict, result_table: str, many, real=None, records: str = "records") -> list:
    fanning = implement_page_fanning(page, many)
    if not fanning:
        return []
    result, key = _implement_plain_table(result_table), INSPIRE_HISTORY_NAMES[0]
    measures = [(f"dataset {name}", name, text) for name, text in fanning.items()]
    measures += [(f"KPI {k.get('id')}", str(k.get("dataset")), str(k.get("expression") or "").strip())
                 for k in page.get("kpis") or [] if isinstance(k, dict)]
    measures += [(f"chart {c.get('id')} measure {index + 1}", str(c.get("dataset")), str(y.get("expression") or "").strip())
                 for c in page.get("charts") or [] if isinstance(c, dict)
                 for index, y in enumerate(c.get("y") or []) if isinstance(y, dict)]
    problems, flagged = [], set()
    for label, name, text in measures:
        if name not in fanning or name in flagged or not text:
            continue
        sql = text if label.startswith("dataset ") else f"SELECT {text} FROM ({fanning[name]}) AS d"
        summed, spread, counted = implement_fanout_sums(sql, result_table, many, real)
        names = ", ".join(spread)
        if summed or counted:
            flagged |= {name} if label.startswith("dataset ") else set()
        if summed:
            problems.append(f"{label} adds up {', '.join(summed)} of the business output table {result} over dataset {name}, which "
                            f"joins it to {names}, many rows per record, so each record's value is counted once per row: add each "
                            f"record's value once, from the {records} dataset, from COUNT(DISTINCT {key}) for a count of records, or "
                            f"from a subquery that first aggregates {names} to one row per record, and read a measure of {names} "
                            "from it alone")
        if counted:
            problems.append(f"{label} counts {', '.join(counted)} of the business output table {result} over dataset {name}, which "
                            f"joins it to {names}, many rows per record, so each record is counted once per row: count the records "
                            f"with COUNT(DISTINCT {key}), from the {records} dataset, or from a subquery that first aggregates {names} "
                            "to one row per record")
    if problems:
        print(f"[PAGE-FANOUT FIRED] page={page.get('id')} problems={len(problems)}", flush=True)
    return problems


def implement_genie_answer_facts(result_table: str, columns: dict) -> list:
    names = {str(name).lower() for name in columns or {}}
    facts = [f"Every number you give names the rows it counts, such as the latest run of `{result_table}` only, every run, or a "
             "filter, so a number that counts other rows than the App's KPIs is never read as the same number."]
    if {"recommended_action", "rank"} <= names:
        facts.append(f"When asked what to do, what to do next or which action to take, answer with the `recommended_action` of the "
                     f"top rows of the latest run of `{result_table}` by `rank`, naming each row and its action; never answer that the "
                     "data holds no recommendation.")
    return facts


def implement_scope_fact(result_table: str, columns) -> str:
    """What the App counts as open work, for the Genie Agent. Empty when the result table has no data_quality_flag."""
    named = {str(c).lower() for c in columns or {}}
    if "data_quality_flag" not in named:
        return ""
    held = "held_back = FALSE and " if "held_back" in named else ""
    held_group = "the records held back (held_back = TRUE, kept off the to fix list on purpose), " if "held_back" in named else ""
    status = "action_status is 'New' or 'In progress' (NULL counts as New) and " if "action_status" in named else ""
    snoozed = "snooze_until is empty or on or before CURRENT_DATE() and " if "snooze_until" in named else ""
    snoozed_group = "the records snoozed until a later date, " if "snooze_until" in named else ""
    closed_group = "the records already done, dismissed or could not be fixed (action_status Done, Dismissed or Could not fix), " if "action_status" in named else ""
    return (f"Open work in `{_implement_plain_table(result_table)}` is the current rows (is_current = TRUE and change_source <> 'delete') "
            f"with {status}{held}{snoozed}data_quality_flag = 'ok'. Answer how many records need action, and which ones, from those rows only. "
            "Any count of records, candidates, duplicates or groups that does not name one group is the open work count, so "
            "answer it with that number first and say that it is the records that need action. "
            "When the question asks for the total of all flagged candidates, give the open count first, then the total as "
            "'N flagged, M still open'. "
            "When a question asks about all candidates, name each group separately in plain words: the open records, "
            f"{held_group}{snoozed_group}{closed_group}and the records that could not be checked (data_quality_flag is not 'ok'; say the reason the flag gives). "
            "Never count a record that could not be checked as open work.")


def implement_run_scope_fact(scope, run_tables=None) -> str:
    """What a First-run build's Genie Agent is told about the rows it reads: the sample the latest run covered, in the words the run
    log recorded (the text of inspire_scope_record), and the records each source table gave that run. Empty for a full-data run or
    when no run log names a First run."""
    if not isinstance(scope, dict) or scope.get("scope") in (None, "", INSPIRE_SCOPES[0]):
        return ""
    text = " ".join(str(scope.get("text") or "").split())
    if not text:
        return ""
    counted = [f"{inspire_plural(int(t['rows']), 'record')} of {t['table']}" for t in run_tables or []
               if isinstance(t, dict) and t.get("table") and t.get("rows") is not None]
    read = f", which read {' and '.join(counted)}" if counted else ""
    return (f"This table is a First run sample, not every record: the latest run covered {text}{read}. "
            "Every count, total, average and list in the answer covers those records only. Say so in the answer and give the number "
            "of records it covers. Never extrapolate a count from the sample to the whole table.")


def implement_build_run_scope(spark, result_table: str, use_case_id: str, run_id) -> tuple:
    """The First-run record and the per-table row counts that the run this build used (run_id, the run the build's outcome names)
    wrote to the run log, as (None, []) when that run is not logged or covered all the records. A later run never stands in for it."""
    if run_id is None or not str(run_id).strip():
        return None, []
    sql = (f"SELECT run_segments, run_tables FROM {inspire_table_name(inspire_ai_summary_table(result_table))} "
           f"WHERE use_case_id = {inspire_sql_literal(use_case_id)} AND CAST(run_id AS STRING) = {inspire_sql_literal(str(run_id))} LIMIT 1")
    try:
        rows = inspire_rows(spark.sql(sql))
    except Exception as error:
        if "TABLE_OR_VIEW_NOT_FOUND" in str(error) or "cannot be found" in str(error):
            return None, []
        raise
    if not rows:
        return None, []
    segments = json.loads(rows[0].get("run_segments") or "[]")
    scope = next((s for s in segments if isinstance(s, dict) and "scope" in s and "text" in s), None)
    tables = [t for t in json.loads(rows[0].get("run_tables") or "[]") if isinstance(t, dict)]
    return scope, tables


def implement_genie_space_grounding(space: dict, columns: dict, result_table: str, allowed=(), free_text_tokens=(),
                                    latest_filter: str = "", held: str = "", kept: str = "", guarded=None,
                                    run_scope: str = "") -> list:
    hidden = {_implement_plain_table(t).lower(): implement_protected_columns(p) for t, p in (guarded or {}).items()}
    problems = []
    sources = space.setdefault("data_sources", {})
    instructions = space.setdefault("instructions", {})
    result, reasons = _implement_plain_table(result_table).lower(), implement_reasons_view(result_table).lower()
    tables = {_implement_plain_table(t.get("identifier")).lower(): _implement_plain_table(t.get("identifier"))
              for t in sources.get("tables") or [] if isinstance(t, dict)}
    if result not in tables:
        problems.append(f"the Genie Agent must hold the business output table {_implement_plain_table(result_table)}, the first of its tables")
    real = {}
    for key, identifier in tables.items():
        found = (columns or {}).get(key) or []
        if not found:
            problems.append("the columns of a table could not be read, so the Genie Agent cannot be checked against them")
        real[key] = {str(name).lower(): (str(name), kind, comment) for name, kind, comment in found}
    aliases = implement_genie_aliases(list(allowed or ()) + list(tables.values()))
    budget = [IMPLEMENT_GENIE_MAX_ENTITY_COLUMNS]
    for table in sorted((t for t in sources.get("tables") or [] if isinstance(t, dict)),
                        key=lambda t: _implement_plain_table(t.get("identifier")).lower() != result):
        key = _implement_plain_table(table.get("identifier")).lower()
        if isinstance(table.get("description"), str):
            table["description"] = [table["description"]]
        if real.get(key):
            problems += _implement_genie_column_configs(table, real[key], key == result, free_text_tokens, budget, hidden.get(key) or ())
    companions = {inspire_shell_facts.companion(result, suffix) for suffix in implement_kind_suffixes()} | {_implement_plain_table(inspire_run_log_table(result_table)).lower()}
    problems += _implement_genie_join_problems(instructions, tables, real, {k: aliases[k] for k in tables},
                                               [t for t in tables if t not in (result, reasons) and t not in companions])
    problems += _implement_genie_snippet_problems(instructions, real, {aliases[k].lower(): k for k in tables})
    samples = ["".join(q.get("question") or []) for q in (space.get("config") or {}).get("sample_questions") or []]
    examples = {_implement_genie_fold("".join(e.get("question") or [])) for e in instructions.get("example_question_sqls") or []}
    unanswered = [q for q in samples if _implement_genie_fold(q) not in examples]
    if unanswered:
        problems.append(f"the sample {'question' if len(unanswered) == 1 else 'questions'} {', '.join(repr(q) for q in unanswered[:5])} "
                        f"{'has' if len(unanswered) == 1 else 'have'} no example SQL: give each sample "
                        "question an example question SQL with the same question that answers it")
    problems += _implement_genie_benchmark_problems(space, examples | {_implement_genie_fold(q) for q in samples}, list(tables.values()))
    many = implement_genie_many_sides(instructions, tables[result]) if result in tables else []
    problems += implement_genie_fanout_problems(space, tables[result], many, real) if many else []
    facts = ([f"The latest run of `{tables[result]}` is its rows where {latest_filter}; answer about the current results from those "
              "rows only, and read earlier runs only when a question asks about the past."] if latest_filter and result in tables else [])
    facts += [implement_genie_grain_fact(tables[result], many)] if many else []
    facts += implement_genie_answer_facts(tables[result], real.get(result) or {}) if result in tables else []
    lead = [run_scope] if run_scope and result in tables else []
    for fact in lead + facts + [f for f in (held, implement_scope_fact(result_table, columns), kept) if f and result in tables]:
        texts = instructions.get("text_instructions") or []
        if not texts:
            instructions["text_instructions"] = [{"id": uuid.uuid4().hex, "content": [fact]}]
        elif fact not in "".join(texts[0].get("content") or []):
            present = "".join(texts[0].get("content") or [])
            joined = fact + "\n\n" + present.lstrip() if fact in lead else present.rstrip() + "\n\n" + fact
            texts[0]["content"] = joined.splitlines(keepends=True)
    return problems


def _implement_genie_key_columns(condition: str, sides: dict):
    keys = {alias: [] for alias in sides}
    for part in re.split(r"\s+AND\s+", _IMPLEMENT_SQL_QUOTED_RE.sub(" ", condition).strip(), flags=re.I):
        match = re.fullmatch(r"\(?\s*(" + _IMPLEMENT_NAME_TOKEN + r"\s*\.\s*" + _IMPLEMENT_NAME_TOKEN + r")\s*=\s*("
                             + _IMPLEMENT_NAME_TOKEN + r"\s*\.\s*" + _IMPLEMENT_NAME_TOKEN + r")\s*\)?", part.strip())
        refs = [implement_sql_column_refs(group)[0] for group in match.groups()] if match else []
        if len(refs) != 2 or {r[0].lower() for r in refs} != set(sides):
            return None
        for alias, column in refs:
            keys[alias.lower()].append(column)
    return keys


def implement_result_repeats_sql(result_table: str, columns, suffix: str = "") -> str:
    keys = ", ".join(f"`{c}`" for c in columns)
    present = " AND ".join(f"`{c}` IS NOT NULL" for c in columns)
    return f"SELECT 1 AS repeated FROM {inspire_table_name(result_table, suffix)} WHERE {present} GROUP BY {keys} HAVING COUNT(*) > 1"


def implement_genie_space_checks(space: dict, aliases: dict, result_table: str, parts=None) -> list:
    """The checks of a space. `parts`, when given, is filled in step with the checks: the part (benchmark, snippet, join spec) a check
    stands for and that can be left out when its SQL cannot run, else None."""
    checks = []
    parts = parts if parts is not None else []

    def add(check, drop=None):
        checks.append(check)
        parts.append(drop)

    instructions = space.get("instructions") or {}
    for example in instructions.get("example_question_sqls") or []:
        question = "".join(example.get("question") or [])
        add({"label": f"the example SQL for {question!r}", "sql": "".join(example.get("sql") or []), "raw_json": True})
    for item in (space.get("benchmarks") or {}).get("questions") or []:
        question = "".join(item.get("question") or [])
        sql = "".join("".join(a.get("content") or []) for a in item.get("answer") or [] if isinstance(a, dict))
        add({"label": f"the benchmark SQL for {question!r}", "sql": sql, "limit": 0}, ("benchmarks", item))
    by_alias = {alias.lower(): table for table, alias in aliases.items()}
    for kind, items in (instructions.get("sql_snippets") or {}).items():
        for item in items or []:
            sql = "".join(item.get("sql") or []).strip()
            owner = next((by_alias[p[0].lower()] for p in implement_sql_column_refs(sql) if p[0].lower() in by_alias), None)
            if not owner:
                continue
            source = f"{inspire_table_name(owner)} AS `{aliases[owner]}`"
            label = f"the {kind[:-1]} {_implement_genie_words(item.get('display_name')) or item.get('alias')!r}"
            add({"label": label, "limit": 0, "sql": (f"SELECT 1 AS matched FROM {source} WHERE {sql} LIMIT 0" if kind == "filters"
                                                     else f"SELECT {sql} AS inspire_check FROM {source} LIMIT 0")}, ("snippets", kind, item))
    owned = {_implement_plain_table(result_table).lower(): "", implement_reasons_view(result_table).lower(): "_reasons"}
    for join in instructions.get("join_specs") or []:
        lines = [str(line) for line in join.get("sql") or []]
        left, right = join.get("left") or {}, join.get("right") or {}
        if len(lines) != 2 or not left.get("alias") or not right.get("alias"):
            continue
        names = f"{left['alias']} to {right['alias']}"
        pair = (f"{inspire_table_name(left['identifier'])} AS `{left['alias']}` JOIN {inspire_table_name(right['identifier'])} "
                f"AS `{right['alias']}`")
        add({"label": f"the join spec {names}", "limit": 0, "sql": f"SELECT 1 AS joined FROM {pair} ON {lines[0].strip()} LIMIT 0"},
            ("join_specs", join))
        keys = _implement_genie_key_columns(lines[0], {left["alias"].lower(): "left", right["alias"].lower(): "right"})
        kind = _implement_join_kind(lines)
        unique = {"MANY_TO_ONE": (right,), "ONE_TO_MANY": (left,), "ONE_TO_ONE": (left, right)}.get(kind, ())
        for ref in unique if keys else ():
            suffix = owned.get(_implement_plain_table(ref["identifier"]).lower())
            if suffix is None:
                continue
            columns = keys[ref["alias"].lower()]
            add({"label": f"the join spec {names}", "expect": "none", "sql": implement_result_repeats_sql(result_table, columns, suffix),
                           "problem": (f"the join spec {names} is tagged {kind}, so each {', '.join(columns)} of {ref['identifier']} "
                                       "must be on one row, but some repeat across its rows and runs: choose the tag that matches the "
                                       "key's cardinality")}, ("of", join))
    return checks


