def implement_output_vibes(outputs, name: str) -> str:
    return str((outputs or {}).get(f"{name}_vibes") or "").strip()


def implement_asset_scope(asset: str, impact=None) -> str:
    if asset.startswith("app:page:"):
        return f"the page {asset[len('app:page:'):]} of the {IMPLEMENT_OUTPUT_LABELS['app']} alone"
    if asset.startswith("dashboard:"):
        return f"the chart {asset.split(':', 1)[1]} of the dashboard alone (the chart, KPI, table, filter or records list with that id)"
    return f"this {implement_asset_label(asset, impact)}"


def implement_asset_heading(asset: str, impact=None, titles=None) -> str:
    label = implement_person_label(asset, impact, titles)
    return label[:1].upper() + label[1:]


def implement_numbered_asks(asks) -> str:
    return "".join(f"{number}. {ask}\n" for number, ask in enumerate(asks or [], 1))


def implement_asset_asks_text(asset: str, text: str, asks=None, apply: str = "", again=None) -> str:
    if not str(text or "").strip():
        return ""
    label = implement_asset_label(asset)
    label = label if label[:2].isupper() else label[:1].lower() + label[1:]
    return (f"The user's asks for the {label}, word for word: \"\"\"{text}\"\"\""
            + (f"\nInspire split them into these asks{apply}:\n{implement_numbered_asks(asks).rstrip()}" if asks else "")
            + (f"\nThe last run missed these asks, so follow each one closely:\n{implement_numbered_asks(again).rstrip()}"
               if again else ""))


def implement_rebuild_text(name: str, rebuild) -> str:
    if not rebuild:
        return ""
    label, scopes = IMPLEMENT_OUTPUT_LABELS[name], [implement_asset_scope(p) for p in rebuild.get("parts") or []]
    lines = [f"This time Inspire rebuilds only part of this {label}"
             + (f": {'; '.join(scopes)}" if scopes else ", for the asks below") + "."]
    lines.append(f"The {rebuild['file']} in your working folder is the {label} as it is now: start from it, change only what the "
                 "parts and asks named here need, and keep everything else in it as it is."
                 if rebuild.get("based") else
                 f"Inspire has no saved copy of the {label} as it is now, so write it whole and change only what the parts and asks "
                 "named here need.")
    for asset, again in (rebuild.get("again") or {}).items():
        lines.append(f"For {implement_asset_scope(asset)}, try again on only these asks, which the last build missed:\n"
                     + implement_numbered_asks(again).rstrip())
        kept = (rebuild.get("kept") or {}).get(asset)
        if kept:
            lines.append("These asks of it are already done; keep them as they are:\n" + implement_numbered_asks(kept).rstrip())
    return "\n".join(lines) + "\n"


def implement_held_text(held, assets) -> str:
    holding = [(ask, reason[len(IMPLEMENT_VIBES_NO_DATA):] if reason.startswith(IMPLEMENT_VIBES_NO_DATA) else reason)
               for asset, found in (held or {}).items() if asset in assets for ask, reason in found.items()]
    if not holding:
        return ""
    return ("Inspire holds these of the customer's asks and tells the customer why, because the source data holds nothing they need "
            "or Inspire could not check that it does: "
            + "; ".join(f"{n}. {a} ({r})" for n, (a, r) in enumerate(holding, 1)) + ". Never build them and never stand in for them "
            "with other columns or fixed numbers; build every other ask.")


def implement_vibes_block(outputs, name: str, where: str, asks=None, rebuild=None, held=None) -> str:
    assets = implement_vibed_assets(outputs, name)
    if not assets and not rebuild:
        return ""
    parts = []
    for asset, text in assets.items():
        listed = (asks or {}).get(asset)
        retried = asset in ((rebuild or {}).get("again") or {})
        parts.append(f"The customer's asks for {implement_asset_scope(asset)}, word for word:\n\"\"\"\n{text}\n\"\"\"\n"
                     + (f"Inspire split them into these asks and checks each one in what you write:\n{implement_numbered_asks(listed)}"
                        if listed and not retried else ""))
    holding = implement_held_text(held, assets)
    return (f"{USER_DIRECTIVE_SUPREMACY_PREAMBLE}{''.join(parts)}{implement_rebuild_text(name, rebuild)}"
            + (f"{holding}\n" if holding else "") +
            f"These asks are explicit user directives: where they conflict with any guideline, rule, default "
            f"or example in this prompt, the customer's asks win, without exception. {IMPLEMENT_VIBES_EXPERT} Inspire's checks still run "
            f"on what you write and "
            f"decide what ships: every query must run and pass them, nothing may write data or read a table this prompt does not "
            f"name, Inspire reads the input tables through their metadata only, and the business output table rules above still hold.\n"
            f"If an ask cannot be done within those checks, do every other ask and list each one you could not do in {where}, as "
            f'[{{"ask": "<the ask, word for word>", "reason": "<one sentence on why>"}}]; leave it out when you did every ask.\n')


def implement_vibes_not_done(data, outputs, name: str) -> tuple:
    value = data.pop(IMPLEMENT_VIBES_NOT_DONE, None) if isinstance(data, dict) else None
    if not implement_vibed_assets(outputs, name) or value is None or value == []:
        return [], []
    if not isinstance(value, list):
        return [], [f'{IMPLEMENT_VIBES_NOT_DONE} must be a list of {{"ask": ..., "reason": ...}} objects']
    warnings, errors = [], []
    for item in value:
        item = item if isinstance(item, dict) else {}
        ask, reason = (" ".join(str(item.get(key) or "").split()) for key in ("ask", "reason"))
        warning = f"{IMPLEMENT_OUTPUT_LABELS[name]} vibe not done: {ask[:300]}: {reason[:500]}"
        if not ask or not reason:
            errors.append(f'each {IMPLEMENT_VIBES_NOT_DONE} entry needs an "ask" and a "reason"')
        elif warning not in warnings:
            warnings.append(warning)
    return warnings, sorted(set(errors))


