def implement_vibes_split_prompt(asset: str, text: str, earlier=(), impact=None) -> str:
    return ("You turn what a customer asked for one part of a use case build into a numbered list of concrete asks. The customer's "
            "words are explicit user directives: keep every ask they make, in their own words, and never drop, merge away, soften "
            "or add one.\n\n"
            f"The part: {implement_asset_label(asset, impact)} ({implement_asset_scope(asset, impact)}).\n"
            f"The customer's words, word for word:\n\"\"\"\n{text}\n\"\"\"\n\n"
            "Each ask is one thing a reader can look for in the built part. When an ask names something a reader can find exactly, "
            "add a check: {\"kind\": \"chart_type\", \"value\": \"bar\"} for a chart type (bar, horizontal_bar, stacked_bar, "
            "grouped_bar, line, area, stacked_area, pareto, scatter, donut, pie or heatmap, or the customer's own words for a type "
            "that is "
            "none of "
            "these, for example \"3d globe\"), {\"kind\": \"column\", \"value\": \"<column name>\"} for a "
            "column it shows, {\"kind\": \"filter\", \"value\": \"<column or filter name>\"} for a filter, {\"kind\": \"page\", "
            "\"value\": \"<page title or id>\"} for a page, {\"kind\": \"sort\", \"value\": \"<column>\", \"direction\": \"asc\" or "
            "\"desc\"} for an order, {\"kind\": \"threshold\", \"value\": <number>} for a number it uses, or {\"kind\": \"text\", "
            "\"value\": \"<exact words>\"} for words it shows, {\"kind\": \"block\", \"value\": {\"kind\": \"text, image or html\", "
            "\"place\": \"top, bottom, before, after or beside\", \"of\": \"<the element it sits by>\", \"width\": \"full, wide, half "
            "or narrow\", \"align\": \"left, center or right\"}} with only the parts the ask names for a content block on an App page, "
            "{\"kind\": \"image\", \"value\": \"<what the picture must show and its look, never where it sits>\"} for a picture, "
            "with where it sits on the page in a block check, {\"kind\": \"color\", \"value\": \"<color, hue or palette name>\"} for a "
            "color, {\"kind\": \"column_filter\", "
            "\"value\": \"<column name, or all>\"} for a filter on a table's own columns, {\"kind\": \"schedule\", \"value\": \"<time "
            "of day, HH:MM in 24 hours>\"} for when an alert or job runs, {\"kind\": \"recipient\", \"value\": \"<email or "
            "destination name>\"} for who an alert goes to, {\"kind\": \"clears\", \"value\": \"on or off\"} for whether an alert sends "
            "one more email when it returns to OK, or {\"kind\": \"result\", \"value\": {\"column\": \"<result column>\", "
            "\"min\": <number>, \"max\": <number>, \"values\": [\"...\"]}} with only the parts the ask names for what the notebook's "
            "results must hold. An ask that names more than one such thing has \"check\" as a list of them; otherwise \"check\" is "
            "null. An ask about all or every column, chart, table or filter is checked on each of them: a filter on all columns "
            "of a table is {\"kind\": \"column_filter\", \"value\": \"all\"}, and any other check it asks of every chart or table "
            "has \"all\": true.\n"
            "Mark an ask that asks to keep something as it already is with \"keep\": true, for example \"keep the region filter\"; "
            "every other ask asks for a change and has \"keep\": false. When an ask names one element of the part by its title, a "
            "table, chart, page, tile, block or filter, put that element as the customer names it in \"where\", for example \"the "
            "Top accounts table\" for \"the filter on the Top accounts table lists Act now\", and never leave it out when the ask "
            "names one; an element named only as a position, as in \"next to the Top accounts table\", goes in a block check's "
            "\"of\" and never in \"where\"; otherwise \"where\" is \"\".\n"
            "Set \"draws\" to what the ask asks the part to draw from its data: \"chart\" for a chart or graph, \"table\" for a "
            "table or list of rows, \"kpi\" for a number tile, \"data\" for any other value read from the data, such as a rainfall "
            "amount or a count; otherwise \"draws\" is \"\".\n"
            + (f"Inspire split this part's earlier words into these asks:\n{implement_numbered_asks(earlier)}When an ask in the "
               "customer's words above is still one of them, write it exactly as it is listed there.\n" if earlier else "")
            + "Reply with one JSON object and nothing else: {\"asks\": [{\"ask\": \"...\", \"check\": null, \"keep\": false, "
            "\"where\": \"\", \"draws\": \"\"}]}")


IMPLEMENT_VIBE_ROUTE_SCHEMA = {"type": "object", "properties": {
    "routes": {"type": "array", "items": {"type": "object", "properties": {"ask": {"type": "integer"}, "asset": {"type": "string"},
                                                                          "words": {"type": "string"}},
                                          "required": ["ask", "asset", "words"]}}}, "required": ["routes"]}
IMPLEMENT_ROUTER_ATTEMPTS = 3
IMPLEMENT_ROUTER_BACKOFF_S = 2.0
IMPLEMENT_NOT_DECIDED = "not_decided"
_IMPLEMENT_ASK_MARK_RE = re.compile(r"^\s*(?:[-*\u2022]|\d{1,3}[.)])\s+")
_IMPLEMENT_ASK_SPLIT_RE = re.compile(r"(?<=[.!?])\s+(?=[A-Z0-9\"'(])")


def implement_vibe_asks(text) -> list:
    asks = []
    for line in str(text or "").splitlines():
        for sentence in _IMPLEMENT_ASK_SPLIT_RE.split(_IMPLEMENT_ASK_MARK_RE.sub("", line).strip()):
            ask = " ".join(sentence.split())
            if ask and ask.lower() not in {a.lower() for a in asks}:
                asks.append(ask)
    return asks


def implement_not_decided_text(reason: str, version) -> str:
    return (f"Inspire did not decide which part each ask of your vibe changes, because {reason}, so it built nothing of v{version}: "
            f"{IMPLEMENT_SEND_VIBE_AGAIN}")


def implement_not_decided_entries(asks, reason: str, version) -> list:
    evidence = implement_not_decided_text(reason, version)[:1500]
    return [{"n": n, "kind": IMPLEMENT_NOT_DECIDED, "requirement": ask, "part": "", "where": "", "status": IMPLEMENT_NOT_DECIDED,
             **implement_checklist_texts(evidence), "rounds": 0, "tried": [], "checks": [], "published_anyway": None}
            for n, ask in enumerate(asks, 1)]


IMPLEMENT_VIBE_NOTEBOOK_TARGET = "the analysis notebook that computes the results (columns, model, time windows, scoring)"


def implement_vibe_targets(asset_status, outputs) -> dict:
    status, ticked, targets = asset_status or {}, outputs or {}, {}
    impact = implement_notebook_impact(status)
    parts = sorted(asset for asset in status if implement_part(asset))
    for asset in [*IMPLEMENT_OUTPUTS, IMPLEMENT_NOTEBOOK, *parts]:
        entry = status.get(asset) if isinstance(status.get(asset), dict) else {}
        owner, built = implement_asset_owner(asset), entry.get("state") in IMPLEMENT_PART_STATES[:2]
        if (owner != IMPLEMENT_NOTEBOOK and not ticked.get(owner)) or (asset in parts and not built):
            continue
        if asset == IMPLEMENT_NOTEBOOK:
            targets[asset] = IMPLEMENT_VIBE_NOTEBOOK_TARGET
            continue
        name = (implement_part_what(asset, impact) if owner == IMPLEMENT_NOTEBOOK
                else " ".join(str(entry.get("name") or entry.get("title") or "").split())[:120] if built else "")
        label = implement_person_label(asset, impact, implement_asset_titles(status))
        targets[asset] = label + (f" ({name})" if name and name not in label else "")
    return targets


def implement_vibe_route_prompt(asks: list, targets: dict, first: bool = False) -> str:
    listed = "".join(f"- {asset}: {label}\n" for asset, label in targets.items())
    unticked = [IMPLEMENT_OUTPUT_LABELS[name] for name in IMPLEMENT_OUTPUTS if name not in targets]
    parts = ("Nothing is built for this use case yet: Inspire builds these parts now, each with the asks you send it" if first
             else "The parts Inspire built for this use case, or builds in this version")
    return (f"{USER_DIRECTIVE_SUPREMACY_PREAMBLE}"
            "You send what a customer asked for their use case MVP to the parts of it that each ask changes. The customer's words are "
            "explicit user directives: keep every ask, in their own words, and never drop, soften, merge away or add one.\n\n"
            f"{parts}, by id:\n{listed}"
            + (f"Not ticked for this use case, so Inspire does not build them: {', '.join(unticked)}.\n" if unticked else "")
            + f"\nThe customer's asks, word for word, by number:\n{implement_numbered_asks(asks)}\n"
            "Give every ask, by its number, to the part it changes, by id. Each ask is one of two kinds. A part "
            "ask is about one part's look or behavior (a filter, a chart, a page, the wording, the layout, a Genie question, or an "
            "alert's timing or recipients): it goes to that part alone, so Inspire rebuilds only that part. Pick a chart or page id "
            "when one is listed and the ask is about that one chart or page alone, and the whole dashboard, App, Genie Agent or alert "
            "otherwise. A core ask changes the analysis itself (the output columns, the entity each row is about, the score or the "
            "model, the time windows, the thresholds or tiers the notebook computes, or the data it reads): it goes to the notebook, "
            "so Inspire rebuilds the notebook and every part after it; when the ai_reasoning or value_formula id is listed "
            "and a core ask is about that alone, it goes to that id instead. Never send a part ask to the notebook. A chart, graph, "
            "plot or KPI tile is a part ask even when it groups, ranks or limits what it draws, as in \"for the top 10 clerks\": the part "
            "draws that in its own query, and the notebook never filters, ranks or cuts its rows for it. An ask that needs "
            "both gets one route to the notebook and one to that part, each with the words of the ask that part does: a new column "
            "shown as an App filter goes to the notebook and to the App. Every ask gets at least one route and never two routes to "
            "the same part, because Genie tries every ask before anyone may say it cannot be done: an ask that no part listed is "
            "about, for example one for a part that is not ticked, goes to the notebook.\n"
            "Reply with one JSON object and nothing else: {\"routes\": [{\"ask\": <its number>, \"asset\": \"<id>\", \"words\": \"<the "
            "words of that ask this part does, word for word, or the whole ask>\"}]}")


def implement_route_number(value):
    if isinstance(value, bool):
        return None
    if isinstance(value, float) and value.is_integer():
        return int(value)
    if isinstance(value, str) and value.strip().isdigit():
        return int(value.strip())
    return value if isinstance(value, int) else None


class ImplementVibeRouteError(ValueError):
    pass


def implement_vibe_routes(parsed, targets: dict, asks: list) -> tuple:
    if not isinstance(parsed, dict):
        raise ImplementVibeRouteError("the model replied with no JSON object")
    if not asks:
        raise ImplementVibeRouteError("the vibe holds no ask")
    routes, fallback, placed, problems, sent = {}, [], {}, [], []
    for item in parsed.get("routes") or []:
        item = item if isinstance(item, dict) else {}
        number, named = implement_route_number(item.get("ask")), " ".join(str(item.get("asset") or "").split())
        shown = inspire_redact_text(named, set(), "")
        if number is None or not 1 <= number <= len(asks):
            said = inspire_redact_text(str(item.get("ask")), set(), "")[:20]
            problems.append(f"sent ask {said}, which the vibe does not have, to {shown or 'no part'}")
            continue
        ask = asks[number - 1]
        if named in placed.setdefault(number, []):
            problems.append(f"sent ask {number} ('{ask[:200]}') to {shown or 'no part'} twice")
            continue
        placed[number].append(named)
        words = " ".join(str(item.get("words") or "").split())
        words, asset = (words if words and words.lower() in ask.lower() else ask), named
        if asset not in targets:
            reason = (f"it names the {IMPLEMENT_OUTPUT_LABELS[asset]}, which is not ticked for this use case"
                      if asset in IMPLEMENT_OUTPUT_LABELS and asset != IMPLEMENT_NOTEBOOK else f"it names {shown or 'no part'}, which Inspire did not build for this use case")
            owner = implement_asset_owner(asset)
            asset = owner if owner in targets else IMPLEMENT_NOTEBOOK
            fallback.append({"ask": ask[:500], "reason": reason, "asset": asset})
        sent.append((number, asset, words))
    problems += [f"sent ask {n} ('{asks[n - 1][:200]}') to no part" for n in range(1, len(asks) + 1) if n not in placed]
    if problems:
        raise ImplementVibeRouteError("the router " + "; ".join(problems))
    for _number, asset, words in implement_vibe_drawn_routes(sent, asks, targets, fallback):
        if words.lower() not in routes.get(asset, "").lower():
            routes[asset] = f"{routes[asset]}\n{words}" if asset in routes else words
    return routes, fallback


IMPLEMENT_VIBE_DRAWERS = ("app", "dashboard")
_IMPLEMENT_VIBE_DRAWN_RE = re.compile(r"(?i)\b(?:charts?|graphs?|plots?|kpis?|kpi\s+tiles?|number\s+tiles?)\b")
_IMPLEMENT_VIBE_ROW_LIMIT_RE = re.compile(r"(?i)(?:\b(?:for|of|across|among|in|to|with)\s+)?(?:\bthe\s+)?(?:\bonly\s+)?\b(?:top|bottom|first|last|"
                                          r"highest|lowest|largest|smallest|best|worst)\s+\d+\b(?:\s+(?!and\b|or\b|by\b)[\w'-]+)?")


def implement_vibe_drawer(targets: dict) -> str:
    return next((a for a in IMPLEMENT_VIBE_DRAWERS if a in targets),
                next((a for a in targets if implement_asset_owner(a) in IMPLEMENT_VIBE_DRAWERS), ""))


def implement_vibe_drawn_kind(ask) -> str:
    """The drawn part the ask names, in plain words: the word the route check matched (chart, graph, plot, KPI, number tile)."""
    match = _IMPLEMENT_VIBE_DRAWN_RE.search(str(ask or ""))
    kind = " ".join(match.group(0).lower().split()) if match else "chart"
    kind = re.sub(r"\b(\w+?)s\b", r"\1", kind)
    return re.sub(r"\bkpi\b", "KPI", kind)


def implement_vibe_drawn_routes(said: list, asks: list, targets: dict, fallback: list) -> list:
    drawer, out = implement_vibe_drawer(targets), []
    for number in dict.fromkeys(n for n, _a, _w in said):
        ask, mine = asks[number - 1], [(a, w) for n, a, w in said if n == number]
        if not drawer or not _IMPLEMENT_VIBE_DRAWN_RE.search(ask) or any(implement_asset_owner(a) in ("genie_space", "alert")
                                                                        for a, _w in mine):
            out += [(number, a, w) for a, w in mine]
            continue
        fixed = []
        for asset, words in mine:
            kept = words if asset != IMPLEMENT_NOTEBOOK else " ".join(_IMPLEMENT_VIBE_ROW_LIMIT_RE.sub(" ", words).split()).strip(" ,;:-")
            if re.search(r"\w", kept):
                fixed.append((asset, kept))
        drawn = [a for a, _w in fixed if implement_asset_owner(a) in IMPLEMENT_VIBE_DRAWERS]
        if not drawn:
            fixed.append((drawer, ask))
        if fixed != mine:
            shown = (targets or {}).get(drawn[0] if drawn else drawer) or implement_person_label(drawn[0] if drawn else drawer)
            fallback.append({"ask": ask[:500], "asset": drawn[0] if drawn else drawer,
                             "reason": f"it asks for a {implement_vibe_drawn_kind(ask)}, which the {shown} draws in its own query, so the notebook keeps every row"})
            logger.info(f"[VIBE-ROUTE FIRED] ask {number} draws a chart: sent to the {shown}, and the notebook keeps every row")
        out += [(number, a, w) for a, w in fixed]
    return out


def implement_vibe_fallback_line(item: dict, titles=None) -> str:
    return (f"'{item['ask']}' went to the {implement_person_label(item['asset'], None, titles)}, because {item['reason']}, so Genie tries it there "
            f"with up to {IMPLEMENT_MAX_GENIE_ROUNDS} rounds")


IMPLEMENT_VIBE_REBUILD_NOTE = "this ask changes the analysis, so Inspire rebuilds the notebook and every part after it"
IMPLEMENT_VIBE_CORE_NOTES = {IMPLEMENT_NOTEBOOK: IMPLEMENT_VIBE_REBUILD_NOTE,
                             "ai_reasoning": "this ask changes the AI reasoning, so Inspire runs the notebook again",
                             "value_formula": IMPLEMENT_VIBE_REBUILD_NOTE}


def implement_vibe_sent_lines(routes: dict, fallback: list, first: bool, impact=None, titles=None) -> list:
    return [f"sent to {implement_asset_heading(asset, impact, titles)}: {words}"
            + (f"; {IMPLEMENT_VIBE_CORE_NOTES[asset]}" if asset in IMPLEMENT_VIBE_CORE_NOTES and not first else "")
            for asset, words in routes.items()] + [implement_vibe_fallback_line(item, titles) for item in fallback]


IMPLEMENT_VIBE_UNDO = "Undo this earlier ask on the {label}, so the {label} is as it was before that ask: "


def implement_removed_asks(previous_spec, spec) -> dict:
    after_out, rolling = (spec or {}).get("outputs") or {}, set((spec or {}).get("rollback_outputs") or {})

    def texts(version):
        outputs = (version or {}).get("outputs") or {}
        return dict({IMPLEMENT_NOTEBOOK: str(((version or {}).get("data") or {}).get("notes") or "")},
                    **{name: implement_output_vibes(outputs, name) for name in IMPLEMENT_OUTPUTS}, **implement_asset_vibes(outputs))

    before, after, removed = texts(previous_spec), texts(spec), {}
    for asset, text in before.items():
        owner = implement_asset_owner(asset)
        if owner in rolling or (owner != IMPLEMENT_NOTEBOOK and not after_out.get(owner)):
            continue
        kept = {a.lower() for a in implement_vibe_asks(after.get(asset))}
        gone = [a for a in implement_vibe_asks(text) if a.lower() not in kept and not implement_vibe_undoes(a)]
        if gone:
            removed[asset] = gone
    return removed


def implement_vibe_undoes(ask) -> bool:
    head = IMPLEMENT_VIBE_UNDO.split("{label}", 1)[0]
    return str(ask or "").strip().lower().startswith(head.lower())


def implement_undo_routes(removed: dict, impact=None, titles=None) -> dict:
    return {asset: "\n".join(f"{IMPLEMENT_VIBE_UNDO.format(label=implement_person_label(asset, impact, titles))}'{ask}'" for ask in asks)
            for asset, asks in (removed or {}).items() if asks}


IMPLEMENT_VIBE_GLOBAL_GROUPING_RE = re.compile(r"(?i)\b(?:global\s+grouping|no\s+grouping|grouping\s*(?:is\s+|:\s*|=\s*)all)\b")
IMPLEMENT_VIBE_NAMED_GROUPING_RE = re.compile(r"(?i)(?:^\s*group(?:ed|ing)?\s+by\s+|\bgrouping\s*(?:is\s+|:\s*|=\s*|by\s+))"
                                              r"([A-Za-z_]\w*(?:\s*,\s*[A-Za-z_]\w*)*)")


def implement_vibe_grouping(asks) -> list:
    """The Groupings a vibe names, one per ask that names one: "Global grouping", "no grouping" and "grouping all" mean all, and "grouping
    is X" or a leading "group by X" name columns. A chart's own "grouped by region" names no Grouping and is left alone."""
    named = []
    for ask in asks or []:
        text = " ".join(str(ask or "").split())
        if IMPLEMENT_VIBE_GLOBAL_GROUPING_RE.search(text):
            value = INSPIRE_SETTING_ALL
        else:
            found = IMPLEMENT_VIBE_NAMED_GROUPING_RE.search(text)
            value = ", ".join(part.strip() for part in found.group(1).split(",")) if found else ""
        if value and value not in named:
            named.append(value)
    return named


def implement_apply_vibe_grouping(spec: dict, grouping: str) -> dict:
    """The Grouping a vibe names becomes the planned Grouping, so the widget default Genie writes and every run's proof follow it."""
    config = dict(spec.get("config") or {})
    return dict(spec, config=dict(config, widgets=dict(config.get("widgets") or {}, **{INSPIRE_GROUP_BY: grouping})))


def implement_grouping_of(spec) -> str:
    return str(((spec or {}).get("config") or {}).get("widgets", {}).get(INSPIRE_GROUP_BY) or "").strip()


def implement_keep_grouping(previous_spec, spec) -> dict:
    """A rebuild whose spec names no Grouping keeps the one the built version planned, so a vibe about another measure never re-plans the
    groups. A Grouping the vibe names is left to the vibe router, which applies it."""
    held = implement_grouping_of(previous_spec)
    if not held or implement_grouping_of(spec) or implement_vibe_grouping(implement_vibe_asks((spec or {}).get("vibes"))):
        return spec
    return implement_apply_vibe_grouping(spec, held)


def implement_grouping_default_problem(named: str, widgets) -> str:
    """The reason the built notebook's group_by default is not the Grouping the vibe names, or '' when it is the same."""
    held = next((str(w.get("default") or "").strip() for w in widgets or [] if isinstance(w, dict) and w.get("name") == INSPIRE_GROUP_BY), "")
    if not named or implement_choice_text(held) == implement_choice_text(named):
        return ""
    return f"the Grouping is {held or 'not set'}, not {named}"


def implement_grouping_check(asset_status: dict, spec: dict, widgets) -> str:
    """Records a vibe Grouping the built notebook does not hold as a missed notebook ask, and returns the reason ('' when met)."""
    asks = [ask for ask in implement_vibe_asks((spec or {}).get("vibes")) if implement_vibe_grouping([ask])]
    named = implement_vibe_grouping(asks)
    problem = implement_grouping_default_problem(named[0], widgets) if named else ""
    if not problem:
        return ""
    record = asset_status.get(IMPLEMENT_NOTEBOOK) if isinstance(asset_status.get(IMPLEMENT_NOTEBOOK), dict) else {}
    record["vibes_checks"] = [check for check in record.get("vibes_checks") or [] if check.get("ask") != asks[0]] + [
        {"ask": asks[0], "status": "missing", "evidence": problem}]
    asset_status[IMPLEMENT_NOTEBOOK] = record
    return problem


def implement_apply_vibe_routes(spec: dict, routes: dict, impact=None, titles=None) -> tuple:
    outputs, data, retry, changed, errors = (dict(spec["outputs"]), dict(spec.get("data") or {}), list(spec.get("retry_outputs") or []),
                                             {}, [])
    for asset, words in routes.items():
        notebook, key = asset == IMPLEMENT_NOTEBOOK, f"{asset}_vibes"
        held = str((data.get("notes") if notebook else spec["outputs"].get(key)) or "").strip()
        merged = held if words.lower() in held.lower() else (f"{held}\n{words}" if held else words)
        if len(merged) > IMPLEMENT_VIBES_MAX_CHARS:
            errors.append(f"the {implement_person_label(asset, impact, titles)} would hold {inspire_plural(len(merged), 'character')} of asks with this vibe, and at "
                          f"most {implement_number_text(IMPLEMENT_VIBES_MAX_CHARS)} are allowed: remove some of its earlier asks from its list on the Build page "
                          "first")
        if notebook:
            data["notes"] = merged
        else:
            outputs[key] = changed[key] = merged
        if asset not in retry and (not notebook or merged == held):
            retry.append(asset)
    return dict(spec, outputs=outputs, data=data, retry_outputs=retry), changed, errors


def implement_side_outputs(spec: dict, routes: dict, asset_status, assets) -> tuple:
    owners = [owner for owner in dict.fromkeys(implement_asset_owner(asset) for asset in routes)
              if owner in IMPLEMENT_OUTPUTS and (assets or {}).get(owner)]
    if spec.get("vibe_previous") != "keep":
        return [], []
    side, in_place = [], []
    for owner in owners:
        shared = ((asset_status or {}).get(owner) or {}).get("merged_into") or implement_merge_target(spec["outputs"], owner)
        hosted = owner == "app" and implement_app_hosted(spec["outputs"])
        (in_place if owner in IMPLEMENT_IN_PLACE_OUTPUTS or shared or hosted else side).append(owner)
    return side, in_place


def implement_side_name(name: str, version: int, limit: int, separator: str) -> str:
    base = re.sub(rf"{re.escape(separator)}v[0-9]+$", "", " ".join(str(name or "").split()) if separator == " " else str(name or "").strip())
    suffix = f"{separator}v{int(version)}"
    return f"{base[:limit - len(suffix)].rstrip(' -')}{suffix}"


def implement_side_names(outputs: dict, name: str, version: int, default_title: str) -> dict:
    if name == "app":
        return {"app_name": implement_side_name(outputs.get("app_name"), version, 30, "-")}
    key = f"{name}_name"
    return {key: implement_side_name(outputs.get(key) or default_title, version, 200, " ")}


def implement_in_place_note(name: str, version, hosted: bool = False) -> str:
    why = ("a second alert would email the same people twice" if name in IMPLEMENT_IN_PLACE_OUTPUTS else
           "a page inside Inspire has one live version" if hosted else
           f"other use cases share this {IMPLEMENT_MERGE_LABELS.get(name, IMPLEMENT_OUTPUT_LABELS[name])}, and it holds one part per use case")
    return (f"{IMPLEMENT_OUTPUT_LABELS[name]}: changed in place, because {why}; its Versions can roll it back"
            + (f" to v{version}" if version else ""))


def implement_kept_assets(asset_status) -> list:
    entry = (asset_status or {}).get("kept")
    listed = entry.get("assets") if isinstance(entry, dict) else None
    return [dict(item) for item in listed or [] if isinstance(item, dict) and item.get("output") in IMPLEMENT_OUTPUTS and item.get("id")]


def implement_patched_spec(stored, changed_outputs: dict, notes=None):
    if isinstance(stored, str):
        try:
            stored = json.loads(stored)
        except ValueError:
            return stored
    if (not changed_outputs and notes is None) or not isinstance(stored, dict):
        return stored
    patched = dict(stored, outputs=dict(stored.get("outputs") or {}, **changed_outputs))
    return dict(patched, data=dict(stored.get("data") or {}, notes=notes)) if notes is not None else patched


def implement_vibes_check(check):
    value = check.get("value") if isinstance(check, dict) else None
    if not isinstance(check, dict) or check.get("kind") not in IMPLEMENT_VIBES_CHECK_KINDS or isinstance(value, bool):
        return None
    if isinstance(value, dict) and check["kind"] in ("block", "result"):
        return check if any(v not in (None, "", []) for v in value.values()) else None
    return check if isinstance(value, (str, int, float)) and str(value).strip() else None


def implement_vibes_checks_of(ask) -> list:
    check = ask.get("check") if isinstance(ask, dict) else None
    return [c for c in (check if isinstance(check, list) else [check]) if isinstance(c, dict)]


def implement_vibes_check_name(check: dict) -> str:
    value = check.get("value")
    shown = ", ".join(f"{k} {v}" for k, v in value.items() if v not in (None, "", [])) if isinstance(value, dict) else str(value)
    return f"{check['kind']}: {shown}"[:200]


def implement_vibes_asks(parsed) -> list:
    asks = []
    for item in (parsed or {}).get("asks") or [] if isinstance(parsed, dict) else []:
        ask = " ".join(str((item or {}).get("ask") or "").split())[:500] if isinstance(item, dict) else ""
        check = item.get("check") if isinstance(item, dict) else None
        listed = [c for c in map(implement_vibes_check, check if isinstance(check, list) else [check]) if c][:IMPLEMENT_VIBES_MAX_CHECKS]
        check = (listed[0] if len(listed) == 1 else listed) if listed else None
        where = " ".join(item["where"].split())[:200] if isinstance(item, dict) and isinstance(item.get("where"), str) else ""
        draws = str(item.get("draws") or "").strip().lower() if isinstance(item, dict) else ""
        if ask and implement_ask_identity("", where, ask) not in {implement_ask_identity("", a["where"], a["ask"]) for a in asks}:
            asks.append(dict({"ask": ask, "check": check, "keep": isinstance(item, dict) and item.get("keep") is True, "where": where},
                             **({"draws": draws} if draws in IMPLEMENT_VIBES_DRAWS else {})))
    if not asks:
        raise ValueError("the model split the vibes into no ask")
    return asks


def implement_vibes_text(target) -> str:
    return target if isinstance(target, str) else json.dumps(target, ensure_ascii=False, sort_keys=True, default=str)


class _ImplementHtmlText(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.parts, self.skip = [], 0

    def handle_starttag(self, tag, attrs):
        if tag in ("style", "script"):
            self.skip += 1
        alt = dict(attrs).get("alt") if tag == "img" else ""
        if alt:
            self.parts.append(f"[image: {alt}]")

    def handle_endtag(self, tag):
        if tag in ("style", "script") and self.skip:
            self.skip -= 1

    def handle_data(self, data):
        if not self.skip and data.strip():
            self.parts.append(" ".join(data.split()))


def implement_html_text(html) -> str:
    scan = _ImplementHtmlText()
    scan.feed(str(html or ""))
    scan.close()
    return " ".join(scan.parts)


def implement_block_place_text(block: dict) -> str:
    place = block.get("place") if isinstance(block.get("place"), dict) else {}
    where, named = str(place.get("where") or "bottom"), str(place.get("of") or "")
    return f"at the page {where}" if where in ("top", "bottom") or not named else f"{where} {named}"


def implement_page_blocks_seen(page) -> dict:
    seen = {}
    for block in (page.get("blocks") or [] if isinstance(page, dict) else []):
        if not isinstance(block, dict) or not block.get("id"):
            continue
        ident, kind, content = str(block["id"]), str(block.get("kind") or ""), block.get("content")
        image = content if kind == "image" and isinstance(content, dict) else {}
        shown = {"kind": kind, "place": implement_block_place_text(block), "align": str(block.get("align") or "left"),
                 "width": str(block.get("width") or "full"),
                 "text": implement_html_text(content) if kind == "html" else str(content or "") if kind == "text" else "",
                 "alt": str(image.get("alt") or ""), "caption": str(image.get("caption") or "")}
        _implement_seen_put(seen, ident, f"{ident} {kind} block", f"{kind} block", shown,
                            f"{kind} block {ident}, {shown['place']}, {shown['width']} width, aligned {shown['align']}",
                            shown["text"].splitlines(), f"image: {shown['alt']}" if shown["alt"] else "",
                            f"caption: {shown['caption']}" if shown["caption"] else "", kind="block")
    return seen


def implement_page_widgets(page) -> dict:
    widgets = {}
    for group in ("kpis", "charts", "tables", "filters", "blocks"):
        for item in (page or {}).get(group) or [] if isinstance(page, dict) else []:
            if isinstance(item, dict) and item.get("id"):
                widgets[str(item["id"])] = item
    if isinstance(page, dict) and isinstance(page.get("records"), dict):
        widgets["records"] = page["records"]
    return widgets


def implement_vibes_target(asset: str, artifact) -> tuple:
    if asset.startswith("app:page:"):
        page, built = asset[len("app:page:"):], str((artifact or {}).get("id") or "") if isinstance(artifact, dict) else ""
        if built != page:
            return None, (f"this use case builds the App page {built or 'that has no id'}, so the page {page} is not one Inspire "
                          "builds here; open the use case that owns that page and give it these vibes")
        return artifact, ""
    if asset.startswith("dashboard:"):
        widget, found = asset.split(":", 1)[1], implement_page_widgets(artifact)
        if widget not in found:
            return None, f"the built dashboard has no widget {widget}; its widgets are {', '.join(found) or 'none'}"
        return found[widget], ""
    return artifact, ""


IMPLEMENT_VIBES_CODE_KEYS = frozenset({"sql", "query", "expression", "condition_sql", "check_sql", "datasets", "sql_snippets", "answer"})
IMPLEMENT_VIBES_ALREADY = "already there in the version before, so nothing needed to change for it: "
IMPLEMENT_VIBES_CARRIED = "the version before recorded this ask met, and the check quoted only what it already showed: "
IMPLEMENT_VIBES_GENERIC_WORDS = frozenset({"the", "a", "an", "this", "that", "its", "of", "on", "in", "table", "chart", "page", "list",
                                           "tile", "kpi", "widget", "section", "panel"})


def implement_vibes_shown(node):
    if isinstance(node, dict):
        return {key: implement_vibes_shown(value) for key, value in node.items() if key not in IMPLEMENT_VIBES_CODE_KEYS}
    if isinstance(node, list):
        return [implement_vibes_shown(value) for value in node]
    return node


def _implement_seen_lines(*values) -> list:
    lines = []
    for value in values:
        for item in value if isinstance(value, list) else [value]:
            text = "".join(str(part) for part in item) if isinstance(item, list) else item
            text = " ".join(text.split()) if isinstance(text, str) else ""
            if text and text not in lines:
                lines.append(text)
    return lines


def _implement_column_label(holder: dict, column: str) -> str:
    for key in ("columns", "detail"):
        for entry in holder.get(key) or []:
            if isinstance(entry, dict) and entry.get("column") == column:
                return str(entry.get("label") or column)
            if entry == column:
                return column
    return str((holder.get("label_title") if column == holder.get("label") else "") or column.replace("_", " "))


def _implement_holder_filters(holder: dict, records: bool, shell_sql) -> list:
    if shell_sql is not None:
        found = shell_sql.list_column_filters({"records": holder}) if records else shell_sql.table_column_filters(holder)
        return [f["column"] for f in found]
    entries = holder.get("column_filters")
    return [column for entry in (entries if isinstance(entries, list) else [])
            for column in [entry.get("column") if isinstance(entry, dict) else entry]
            if isinstance(column, str) and column and not (isinstance(entry, dict) and entry.get("off") is True)]


def implement_column_filters(node, shell_sql=None) -> list:
    if not isinstance(node, dict):
        return []
    holders = [(node, "id" not in node)] if "columns" in node else []
    holders += [(node["records"], True)] if isinstance(node.get("records"), dict) else []
    holders += [(t, False) for t in node.get("tables") or [] if isinstance(t, dict)]
    return [{"id": f"{holder.get('id') or 'records'}:{column}", "column": column, "label": _implement_column_label(holder, column),
             "choices": list(INSPIRE_PRIORITY_TIERS) if column == holder.get("tier") else []}
            for holder, records in holders for column in _implement_holder_filters(holder, records, shell_sql)]


def _implement_seen_columns(holder: dict, shell_sql=None) -> list:
    lines = [entry.get("label") or entry.get("column") if isinstance(entry, dict) else entry
             for key in ("columns", "detail") for entry in holder.get(key) or []]
    return lines + [f"column filter: {found['label']}" + (f": {', '.join(found['choices'])}" if found["choices"] else "")
                    for found in implement_column_filters(holder, shell_sql)]


def _implement_seen_filter(found: dict, tier: str = "") -> str:
    choices = [str(c) for key in ("options", "choices", "values") for c in found.get(key) or [] if isinstance(c, (str, int, float))]
    if not choices and tier and (found.get("columns") or {}).get("records") == tier:
        choices = list(INSPIRE_PRIORITY_TIERS)
    label = str(found.get("label") or found.get("id") or "")
    return f"{label}: {', '.join(choices)}" if choices and label else label


def _implement_seen_put(seen: dict, key, name: str, title, node, *values, kind: str = "") -> None:
    lines = _implement_seen_lines(*values)
    if lines:
        seen[str(key)] = {"name": name, "aliases": [name, str(title or ""), str(key)], "lines": lines, "node": implement_vibes_shown(node),
                          "kind": kind}


def implement_page_seen(page, shell_sql=None) -> dict:
    seen = {}
    if not isinstance(page, dict):
        return seen
    title = page.get("title") or page.get("id") or ""
    _implement_seen_put(seen, "page", f"{title} page", title, {k: page[k] for k in ("id", "title", "question", "story") if k in page},
                        page.get("title"), page.get("question"), page.get("story"), kind="page")
    filters = [f for f in page.get("filters") or [] if isinstance(f, dict)]
    queries = {str(d["name"]): str(d.get("sql") or "") for d in page.get("datasets") or [] if isinstance(d, dict) and d.get("name")}
    tier = (page.get("records") or {}).get("tier") if isinstance(page.get("records"), dict) else ""
    seen_filters = [_implement_seen_filter(f, str(tier or "")) for f in filters]
    _implement_seen_put(seen, "filters", "page filter bar", "filter bar", {"filters": filters}, seen_filters, kind="filter")
    if "filters" in seen:
        seen["filters"]["aliases"] += [f"{f.get('label') or f.get('id')} filter" for f in filters]
    for group, kind, word in (("kpis", "kpi", "KPI"), ("charts", "chart", "chart"), ("tables", "table", "table")):
        for item in page.get(group) or []:
            if isinstance(item, dict) and item.get("id"):
                shown = item.get("title") or item.get("label") or item["id"]
                axes = [axis.get("label") for axis in [item.get("x"), *(item.get("y") or [])] if isinstance(axis, dict)]
                types = implement_chart_type_words(item) if kind == "chart" else []
                _implement_seen_put(seen, item["id"], f"{shown} {types[0]} chart" if types else f"{shown} {word}", shown, item,
                                    item.get("title"), item.get("label"), item.get("caption"), item.get("hint"), axes,
                                    _implement_seen_columns(item, shell_sql), kind=kind)
                if types and str(item["id"]) in seen:
                    seen[str(item["id"])]["aliases"] += [f"{shown} {word}"] + [f"{t} chart" for t in types]
                if kind == "kpi" and str(item["id"]) in seen:
                    seen[str(item["id"])]["uses"] = implement_vibes_value_columns(item, queries)
    records = page.get("records")
    if isinstance(records, dict):
        shown = records.get("title") or "records"
        _implement_seen_put(seen, "records", f"{shown} table", shown, records, records.get("title"), records.get("hint"),
                            records.get("label_title"), _implement_seen_columns(records, shell_sql), kind="table")
    genie = page.get("genie") if isinstance(page.get("genie"), dict) else None
    asked = [q for q in page.get("questions") or [] if isinstance(q, str)][:IMPLEMENT_APP_GENIE_SUGGESTIONS] if genie else []
    _implement_seen_put(seen, "genie", "Ask Genie panel", "Ask Genie", {"genie": genie, "genie_note": page.get("genie_note"),
                                                                        "questions": asked},
                        f"Ask Genie: {genie.get('title') or ''}".strip() if genie else page.get("genie_note"), asked, kind="genie")
    for key, element in implement_page_blocks_seen(page).items():
        seen[key if key not in seen else f"block {key}"] = element
    return seen


def implement_genie_seen(artifact) -> dict:
    seen = {}
    if not isinstance(artifact, dict):
        return seen
    space = artifact.get("serialized_space") if isinstance(artifact.get("serialized_space"), dict) else {}
    config = space.get("config") if isinstance(space.get("config"), dict) else {}
    told = space.get("instructions") if isinstance(space.get("instructions"), dict) else {}
    questions = [q for q in config.get("sample_questions") or [] if isinstance(q, dict)]
    _implement_seen_put(seen, "space", "Genie Agent title and description", artifact.get("title"),
                        {"title": artifact.get("title"), "description": artifact.get("description")}, artifact.get("title"),
                        artifact.get("description"))
    _implement_seen_put(seen, "questions", "sample questions", "questions", {"sample_questions": questions},
                        [q.get("question") for q in questions])
    _implement_seen_put(seen, "instructions", "instructions", "instructions", told,
                        [i.get("content") for i in told.get("text_instructions") or [] if isinstance(i, dict)],
                        [e.get("question") for e in told.get("example_question_sqls") or [] if isinstance(e, dict)])
    return seen


def implement_alert_seen(artifact) -> dict:
    seen = {}
    if isinstance(artifact, dict):
        name, trigger = artifact.get("name"), artifact.get("trigger")
        _implement_seen_put(seen, "alert", "alert text", "alert", {k: artifact.get(k) for k in ("name", "trigger", "condition_text")},
                            f"Alert name: {name}" if name else "", f"Fires when {trigger}" if trigger else "", artifact.get("condition_text"))
        _implement_seen_put(seen, "schedule", "alert schedule", "schedule", {"schedule": artifact.get("schedule")},
                            artifact.get("schedule") or [])
        _implement_seen_put(seen, "recipients", "alert recipients", "recipients",
                            {k: artifact.get(k) for k in ("recipients", "destinations")},
                            [f"Sent to {r}" for r in artifact.get("recipients") or []]
                            + [f"Sent to the destination {d}" for d in artifact.get("destinations") or []])
        if isinstance(artifact.get("clears"), bool):
            _implement_seen_put(seen, "clears", "email when it clears", "clears", {"clears": artifact["clears"]},
                                [IMPLEMENT_CLEARS_SHOWN[artifact["clears"]]])
    return seen


def implement_rows_seen(rows) -> dict:
    seen = {}
    for index, row in enumerate(rows if isinstance(rows, list) else [], 1):
        if isinstance(row, dict):
            key = str(row.get("record_key") or index)
            _implement_seen_put(seen, key, f"record {key}", key, row, [str(v) for k, v in row.items() if k != "record_key" and v is not None],
                                kind="record")
    return seen


def implement_vibes_seen(asset: str, artifact, shell_sql=None) -> dict:
    if asset in IMPLEMENT_ASSET_LABELS:
        return implement_rows_seen(artifact)
    if asset == IMPLEMENT_NOTEBOOK:
        seen = {}
        if isinstance(artifact, str):
            _implement_seen_put(seen, IMPLEMENT_NOTEBOOK, "notebook", IMPLEMENT_NOTEBOOK, artifact, artifact.splitlines(), kind="notebook")
        return seen
    if asset == "genie_space":
        return implement_genie_seen(artifact)
    if asset == "alert":
        return implement_alert_seen(artifact)
    target = implement_vibes_target(asset, artifact)[0]
    if not asset.startswith("dashboard:") or target is None:
        return implement_page_seen(target, shell_sql)
    widget, page = asset.split(":", 1)[1], implement_page_seen(artifact, shell_sql)
    if widget in page:
        return {widget: page[widget]}
    return implement_page_seen({"filters": [f for f in artifact.get("filters") or [] if isinstance(f, dict) and str(f.get("id")) == widget]}, shell_sql)


def implement_vibes_seen_text(seen: dict) -> str:
    return "\n".join(f"[{key}] {element['name']}:\n" + "\n".join(f"- {line}" for line in element["lines"])
                     for key, element in (seen or {}).items())


def _implement_vibes_token(word: str) -> str:
    return word[:-1] if len(word) > 3 and word.endswith("s") and not word.endswith("ss") else word


def _implement_vibes_tokens(text) -> frozenset:
    words = (_implement_vibes_token(t) for t in re.split(r"[^a-z0-9]+", str(text or "").lower()) if t)
    return frozenset(w for w in words if w not in IMPLEMENT_VIBES_GENERIC_WORDS)


def implement_vibes_name_kind(name) -> str:
    words = [_implement_vibes_token(w) for w in re.split(r"[^a-z0-9]+", str(name or "").lower()) if w]
    return next((IMPLEMENT_VIBES_NAME_KINDS[w] for w in reversed(words) if w in IMPLEMENT_VIBES_NAME_KINDS), "")


def implement_vibes_elements(seen: dict, name) -> list:
    if str(name or "") in seen:
        return [[str(name)]]
    kinds = IMPLEMENT_VIBES_KIND_POOLS.get(implement_vibes_name_kind(name))
    wanted = _implement_vibes_tokens(name) - set(IMPLEMENT_VIBES_NAME_KINDS)
    if not wanted:
        pool = [key for key, element in seen.items() if kinds and element.get("kind") in kinds]
        return [pool] if pool else []
    names = {key: [_implement_vibes_tokens(alias) - set(IMPLEMENT_VIBES_NAME_KINDS) for alias in element["aliases"]]
             for key, element in seen.items()}
    closeness = {key: (bool(kinds) and seen[key].get("kind") not in kinds,
                       min(len(t ^ wanted) for t in tokens if t and (t <= wanted or wanted <= t)))
                 for key, tokens in names.items() if any(t and (t <= wanted or wanted <= t) for t in tokens)}
    closeness = {key: rank for key, rank in closeness.items() if not rank[0]} or closeness
    return [[key for key, rank in closeness.items() if rank == ranked] for ranked in sorted(set(closeness.values()))]


def implement_vibes_closest(seen: dict, name) -> list:
    ranked = implement_vibes_elements(seen, name)
    kinds = IMPLEMENT_VIBES_KIND_POOLS.get(implement_vibes_name_kind(name))
    first = ranked[0] if ranked else []
    return first if str(name or "") in seen or not kinds or all(seen[key].get("kind") in kinds for key in first) else []


def implement_vibes_element(seen: dict, name) -> str:
    found = implement_vibes_closest(seen, name)
    return found[0] if len(found) == 1 else ""


def _implement_vibes_anchored(text: str, phrase: str) -> bool:
    spots = [m.start() for m in re.finditer(re.escape(phrase), text, re.I)]
    return bool(spots) and all(IMPLEMENT_VIBES_ANCHOR_RE.search(text[:spot]) for spot in spots)


def _implement_vibes_names_part(phrase: str) -> bool:
    words = {_implement_vibes_token(w) for w in re.split(r"[^a-z0-9]+", phrase.lower()) if w}
    return words - IMPLEMENT_VIBES_GENERIC_WORDS - set(IMPLEMENT_VIBES_NAME_KINDS) <= IMPLEMENT_VIBES_PART_WORDS


def implement_vibes_named(ask: dict) -> str:
    text, where = (" ".join(str((ask or {}).get(key) or "").split()) for key in ("ask", "where"))
    phrases = ([where] if where else []) + [m.group(0) for m in IMPLEMENT_VIBES_NAMED_RE.finditer(text)]
    return next((p for p in phrases if not _implement_vibes_anchored(text, p) and not _implement_vibes_names_part(p)), "")


def implement_vibes_draws(ask: dict) -> str:
    said = str((ask or {}).get("draws") or "").strip().lower()
    if said in IMPLEMENT_VIBES_DRAWS:
        return said
    kinds = {c.get("kind") for c in implement_vibes_checks_of(ask)}
    if "chart_type" in kinds:
        return "chart"
    if kinds & {"block", "image", "color"}:
        return ""
    text = " ".join(str((ask or {}).get("ask") or "").split())
    for found in IMPLEMENT_VIBES_NAMED_RE.finditer(text):
        if _implement_vibes_anchored(text, found.group(0)):
            text = text.replace(found.group(0), " ")
    if re.search(r"(?i)\b(?:charts?|graphs?|plots?)\b", text):
        return "chart"
    return "table" if "column_filter" in kinds else ""


def implement_vibes_quantified(ask: dict) -> str:
    found = IMPLEMENT_VIBES_QUANTIFIED_RE.search(str((ask or {}).get("ask") or ""))
    return _implement_vibes_token(found.group(1).lower()) if found else ""


def implement_vibes_listed(ask: dict) -> list:
    listed, noun = implement_vibes_checks_of(ask), implement_vibes_quantified(ask)
    kinds = {c.get("kind") for c in listed}
    if noun == "column" and "column_filter" not in kinds and re.search(r"(?i)\bfilter", str(ask.get("ask") or "")):
        listed.append({"kind": "column_filter", "value": "all"})
    marked = {"chart": ("chart_type",), "table": ("column", "sort", "column_filter")}.get(noun, ())
    return [dict(c, all=True) if c.get("kind") in marked else c for c in listed]


def implement_vibes_page_like(seen: dict) -> bool:
    return any(element.get("kind") in IMPLEMENT_VIBES_PAGE_KINDS for element in (seen or {}).values())


def implement_vibes_scope(seen: dict, ask: dict, label: str, drawn: bool = True) -> tuple:
    phrase = implement_vibes_named(ask)
    keys = implement_vibes_closest(seen, phrase) if phrase else []
    if phrase and not keys and implement_vibes_name_kind(phrase) in ("chart", "table", "kpi", "block", "filter"):
        return [], f"the built {label} has no {phrase.removeprefix('the ').removeprefix('The ')}"
    keys = None if not keys or all(seen[key].get("kind") == "page" for key in keys) else keys
    draws = implement_vibes_draws(ask) if drawn and implement_vibes_page_like(seen) else ""
    if not draws:
        return keys, ""
    bound = [key for key in (keys if keys is not None else list(seen)) if seen[key].get("kind") in IMPLEMENT_VIBES_DRAWS[draws]]
    if bound:
        return bound, ""
    word = IMPLEMENT_VIBES_DRAWS_WORDS[draws]
    if keys is not None:
        return [], (f"the {' or '.join(seen[key]['name'] for key in keys)} on the {label} draws nothing from the data, so it is not "
                    f"the {word} the ask asks for")
    return [], f"the built {label} has no {word}, so nothing on it draws what the ask asks for"


def implement_vibes_scope_name(seen: dict, keys) -> str:
    return " or the ".join(seen[key]["name"] for key in keys or [])


def implement_definition_shape(value, drop=()):
    if isinstance(value, dict):
        shaped = {str(k): implement_definition_shape(v, drop) for k, v in value.items() if k not in drop}
        return {k: v for k, v in shaped.items() if v not in (None, "", [], {})}
    if isinstance(value, (list, tuple)):
        return [implement_definition_shape(v, drop) for v in value]
    return " ".join(value.split()) if isinstance(value, str) else value


def _implement_page_element_label(group: str, node: dict) -> str:
    if group == "page":
        return "page header"
    named = " ".join(str(node.get("title") or node.get("label") or node.get("id") or "").split())
    if group == "records":
        return f"{named or 'records'} table"
    return f"{named} {(str(node.get('kind') or '') + ' block').strip() if group == 'blocks' else IMPLEMENT_PAGE_GROUP_WORDS[group]}"


def _implement_page_items(page, group: str) -> list:
    return [item for item in (page.get(group) if isinstance(page, dict) else None) or [] if isinstance(item, dict) and item.get("id")]


def implement_page_elements(page, records_dataset: str) -> dict:
    page = page if isinstance(page, dict) else {}
    queries = {str(d["name"]): implement_definition_shape(d.get("sql")) for d in page.get("datasets") or []
               if isinstance(d, dict) and d.get("name")}

    def element(group, ident, node, uses, order=0):
        return {"group": group, "id": ident, "node": node, "label": _implement_page_element_label(group, node), "order": order,
                "definition": implement_definition_shape(node), "datasets": {str(u): queries.get(str(u)) for u in uses}}

    found = {"page": element("page", "page", {k: v for k, v in page.items() if k not in IMPLEMENT_PAGE_INSPIRE_KEYS}, ())}
    for group in IMPLEMENT_PAGE_ELEMENT_GROUPS:
        for order, item in enumerate(_implement_page_items(page, group)):
            columns = item.get("columns")
            uses = list(columns) if group == "filters" and isinstance(columns, dict) else [item["dataset"]] if item.get("dataset") else []
            found[f"{group}:{item['id']}"] = element(group, str(item["id"]), item, uses, order)
    if isinstance(page.get("records"), dict):
        found["records"] = element("records", "records", page["records"], (records_dataset,))
    return found


def implement_genie_space_elements(artifact) -> dict:
    artifact = artifact if isinstance(artifact, dict) else {}
    space = artifact.get("serialized_space") if isinstance(artifact.get("serialized_space"), dict) else {}
    config = space.get("config") if isinstance(space.get("config"), dict) else {}
    told = space.get("instructions") if isinstance(space.get("instructions"), dict) else {}
    nodes = {"space": {"title": artifact.get("title"), "description": artifact.get("description")},
             "questions": {"sample_questions": config.get("sample_questions"), "example_question_sqls": told.get("example_question_sqls"),
                           "question_notes": artifact.get("question_notes")},
             "instructions": {"text_instructions": told.get("text_instructions")},
             "data": dict({k: v for k, v in told.items() if k not in ("text_instructions", "example_question_sqls")},
                          data_sources=space.get("data_sources"))}
    return {key: {"group": key, "id": key, "node": node, "label": IMPLEMENT_GENIE_SPACE_PARTS[key], "order": 0,
                  "definition": implement_definition_shape(node, ("id",)), "datasets": {}} for key, node in nodes.items()}


def implement_output_elements(name: str, artifact, records_dataset: str) -> dict:
    return implement_genie_space_elements(artifact) if name == "genie_space" else implement_page_elements(artifact, records_dataset)


def _implement_page_target_keys(seen_key: str, elements: dict) -> set:
    if seen_key == "filters":
        return {key for key, element in elements.items() if element["group"] == "filters"}
    if seen_key in ("page", "records"):
        return {seen_key}
    block = seen_key.startswith("block ")
    ident = seen_key[len("block "):] if block else seen_key
    return {f"{group}:{ident}" for group in (("blocks",) if block else IMPLEMENT_PAGE_ELEMENT_GROUPS) if f"{group}:{ident}" in elements}


def implement_vibes_added_group(ask):
    text = " ".join(str((ask or {}).get("ask") or "").split())
    if not IMPLEMENT_VIBES_ADD_RE.match(text):
        return ""
    found = IMPLEMENT_VIBES_ADDED_RE.match(text)
    kind, draws = implement_vibes_name_kind(found.group(1)) if found else "", str((ask or {}).get("draws") or "").strip().lower()
    if not kind and draws in IMPLEMENT_VIBES_KIND_GROUPS and not IMPLEMENT_VIBES_ADDED_PARTS_RE.search(text):
        kind = draws
    return IMPLEMENT_VIBES_KIND_GROUPS.get(kind or implement_vibes_name_kind((ask or {}).get("where")))


def implement_vibes_ask_names(ask) -> list:
    where = " ".join(str((ask or {}).get("where") or "").split())
    if where:
        return [where]
    text = " ".join(str((ask or {}).get("ask") or "").split())
    found = [(m.group(0), m.start()) for m in IMPLEMENT_VIBES_NAMED_RE.finditer(text)]
    found += [(m.group(1), m.start()) for m in IMPLEMENT_VIBES_QUOTED_RE.finditer(text)]
    found += [(m.group(0), m.start()) for m in IMPLEMENT_VIBES_ID_RE.finditer(text)]
    placed = {phrase for phrase, start in found
              if IMPLEMENT_VIBES_ANCHOR_RE.search(re.sub(r"(?i)(?:\s*\bthe)?[\s\"“‘']*$", "", text[:start]))}
    return [p for p in dict.fromkeys(phrase for phrase, _start in found)
            if p not in placed and _implement_vibes_tokens(p) and not _implement_vibes_names_part(p)]


def implement_vibes_ask_keys(seens, ask) -> tuple:
    names, keys = implement_vibes_ask_names(ask), set()
    adds = bool(IMPLEMENT_VIBES_ADD_RE.match(" ".join(str((ask or {}).get("ask") or "").split())))
    for named in names:
        page_named = implement_vibes_name_kind(named) == "page"
        found = {(n, key) for n, seen in enumerate(seens) for ranked in implement_vibes_elements(seen, named) for key in ranked
                 if not page_named or seen[key].get("kind") == "page"}
        kinds = IMPLEMENT_VIBES_KIND_POOLS.get(implement_vibes_name_kind(named))
        if adds and kinds and any(seens[n][key].get("kind") in kinds for n, key in found):
            found = {(n, key) for n, key in found if seens[n][key].get("kind") in kinds}
        keys |= {key for _n, key in found}
    return keys, names


def implement_untargeted_targets(name: str, asks, prior, new, records_dataset: str, shell_sql=None):
    asks = [(asset, ask) for asset, ask in asks or [] if isinstance(ask, dict)]
    if not asks:
        return None
    elements = {**implement_output_elements(name, prior, records_dataset), **implement_output_elements(name, new, records_dataset)}
    seens = ([implement_genie_seen(prior), implement_genie_seen(new)] if name == "genie_space"
             else [implement_page_seen(prior, shell_sql), implement_page_seen(new, shell_sql)])
    keys, adds, groups, allow = set(), False, set(), {}
    for asset, ask in asks:
        if ask.get("keep"):
            continue
        if asset.startswith("dashboard:"):
            found = _implement_page_target_keys(asset.split(":", 1)[1], elements)
            if not found:
                return None
            keys |= found
            continue
        where = " ".join(str(ask.get("where") or "").split())
        if where and not _implement_vibes_tokens(where):
            return None
        named, names = implement_vibes_ask_keys(seens, ask)
        group = implement_vibes_added_group(ask)
        if not names and not group:
            return None
        page_named = any(implement_vibes_name_kind(n) == "page" for n in names)
        if name != "genie_space" and ("page" in named or page_named):
            return None
        if name == "genie_space":
            if not named:
                return None
            keys |= {part for key in named for part in IMPLEMENT_GENIE_SPACE_COUPLED.get(key, ())}
            continue
        keys |= {found for key in named for found in _implement_page_target_keys(key, elements)}
        if not named and group:
            allow[group] = allow.get(group, 0) + 1
        else:
            adds = adds or not named
        groups |= {IMPLEMENT_ADDED_BY_CHECK[c["kind"]] for c in implement_vibes_checks_of(ask) if c.get("kind") in IMPLEMENT_ADDED_BY_CHECK}
    return {"keys": keys, "adds": adds, "groups": groups, "allow": allow}


def _implement_shown_value(value) -> str:
    if value is None:
        return "none"
    text = json.dumps(value, ensure_ascii=False, sort_keys=True, default=str) if isinstance(value, (dict, list)) else str(value)
    return text if len(text) <= 60 else text[:57] + "..."


def implement_element_change_text(old: dict, now: dict) -> str:
    before, after = old["definition"], now["definition"]
    said = [f"its {field} from {_implement_shown_value(before.get(field))} to {_implement_shown_value(after.get(field))}"
            for field in sorted(set(before) | set(after)) if before.get(field) != after.get(field)]
    said += [f"the query of its dataset {dataset}" for dataset in sorted(set(old["datasets"]) | set(now["datasets"]))
             if _implement_dataset_moved(old["datasets"].get(dataset), now["datasets"].get(dataset))]
    return f"changed the {old['label']}: " + "; ".join(said[:5])


def _implement_prior_datasets(prior) -> set:
    return {str(d["name"]) for d in (prior.get("datasets") if isinstance(prior, dict) else None) or [] if isinstance(d, dict) and d.get("name")}


def _implement_without_new_wiring(element, known: set):
    columns = element["node"].get("columns") if element and element["group"] == "filters" else None
    if not isinstance(columns, dict) or set(columns) <= known:
        return element
    node = dict(element["node"], columns={k: v for k, v in columns.items() if k in known})
    return dict(element, node=node, definition=implement_definition_shape(node),
                datasets={k: v for k, v in element["datasets"].items() if k in known})


IMPLEMENT_SQL_FROM_RE = re.compile(r"(?i)\bfrom\b")
IMPLEMENT_SQL_DISTINCT_RE = re.compile(r"(?i)\bdistinct\b")


def _implement_select_items(select: str) -> list:
    items, depth, current = [], 0, []
    for char in select:
        depth += (char == "(") - (char == ")")
        if char == "," and depth == 0:
            items.append(" ".join("".join(current).split()).lower())
            current = []
        else:
            current.append(char)
    items.append(" ".join("".join(current).split()).lower())
    return [item for item in items if item]


def implement_query_widened(old, new) -> bool:
    old, new = " ".join(str(old or "").split()), " ".join(str(new or "").split())
    if not old or not new or old == new or old.lower().startswith("with") or new.lower().startswith("with"):
        return False
    old_from, new_from = IMPLEMENT_SQL_FROM_RE.search(old), IMPLEMENT_SQL_FROM_RE.search(new)
    if not old_from or not new_from or old[old_from.start():] != new[new_from.start():]:
        return False
    old_select, new_select = old[:old_from.start()], new[:new_from.start()]
    if not old_select.lower().startswith("select ") or not new_select.lower().startswith("select "):
        return False
    if IMPLEMENT_SQL_DISTINCT_RE.search(old_select) or IMPLEMENT_SQL_DISTINCT_RE.search(new_select):
        return False
    old_items = _implement_select_items(old_select[len("select "):])
    new_items = _implement_select_items(new_select[len("select "):])
    if len(new_items) <= len(old_items):
        return False
    return all(item in new_items for item in old_items)


def _implement_dataset_moved(before, after) -> bool:
    return before != after and not implement_query_widened(before, after)


def _implement_reads_changed(old: dict, now: dict) -> bool:
    return old["definition"] != now["definition"] or any(
        _implement_dataset_moved(old["datasets"].get(dataset), now["datasets"].get(dataset))
        for dataset in set(old["datasets"]) | set(now["datasets"]))


def implement_untargeted_changes(name: str, prior, new, targets, records_dataset: str) -> list:
    if targets is None:
        return []
    before = implement_output_elements(name, prior, records_dataset)
    after = implement_output_elements(name, new, records_dataset)
    known = _implement_prior_datasets(prior)
    free = [key for key in list(before) + [k for k in after if k not in before] if key not in targets["keys"]]
    changes, allowed = [], dict(targets.get("allow") or {})
    for key in free:
        old, now = before.get(key), _implement_without_new_wiring(after.get(key), known)
        if old is None:
            if targets["adds"] or now["group"] in targets["groups"]:
                continue
            if allowed.get(now["group"], 0) > 0:
                allowed[now["group"]] -= 1
                continue
            changes.append({"key": key, "change": "added", "label": now["label"], "what": f"added the {now['label']}"})
        elif now is None:
            changes.append({"key": key, "change": "removed", "label": old["label"], "what": f"removed the {old['label']}"})
        elif _implement_reads_changed(old, now):
            changes.append({"key": key, "change": "changed", "label": old["label"], "what": implement_element_change_text(old, now)})
    changed = {change["key"] for change in changes}
    for group in (IMPLEMENT_PAGE_ELEMENT_GROUPS if name != "genie_space" else ()):
        stays = [key for key in free if key in before and key in after and before[key]["group"] == group]
        placed = sorted(stays, key=lambda key: after[key]["order"])
        changes += [{"key": key, "change": "moved", "label": before[key]["label"], "what": f"moved the {before[key]['label']}"}
                    for key, now in zip(stays, placed) if key != now and key not in changed]
    return changes


def _implement_put(holder: dict, key: str, value) -> None:
    if value is None:
        holder.pop(key, None)
    else:
        holder[key] = json.loads(json.dumps(value, default=str))


def _implement_put_genie_part(artifact: dict, element: dict) -> None:
    node, space = element["node"], artifact.setdefault("serialized_space", {})
    told = space.setdefault("instructions", {})
    if element["id"] == "space":
        for key in ("title", "description"):
            _implement_put(artifact, key, node.get(key))
    elif element["id"] == "questions":
        _implement_put(space.setdefault("config", {}), "sample_questions", node.get("sample_questions"))
        _implement_put(told, "example_question_sqls", node.get("example_question_sqls"))
        _implement_put(artifact, "question_notes", node.get("question_notes"))
    elif element["id"] == "instructions":
        _implement_put(told, "text_instructions", node.get("text_instructions"))
    else:
        for key in [k for k in told if k not in ("text_instructions", "example_question_sqls")]:
            told.pop(key)
        for key, value in node.items():
            _implement_put(space if key == "data_sources" else told, key, value)


def _implement_put_page_element(page: dict, prior: dict, element: dict) -> None:
    group, node = element["group"], json.loads(json.dumps(element["node"], default=str))
    if group == "page":
        for key in [k for k in page if k not in IMPLEMENT_PAGE_INSPIRE_KEYS]:
            page.pop(key)
        page.update(node)
        return
    if group == "records":
        page["records"] = node
        return
    items = list(page.get(group) or [])
    ids = [str(item.get("id")) if isinstance(item, dict) else None for item in items]
    if element["id"] in ids:
        items[ids.index(element["id"])] = node
    else:
        earlier = [str(item["id"]) for item in _implement_page_items(prior, group)[:element["order"]]]
        items.insert(max([ids.index(e) + 1 for e in earlier if e in ids], default=0), node)
    page[group] = items


def _implement_drop_page_element(page: dict, element: dict) -> None:
    if element["group"] in IMPLEMENT_PAGE_ELEMENT_GROUPS:
        page[element["group"]] = [item for item in page.get(element["group"]) or []
                                  if not (isinstance(item, dict) and str(item.get("id")) == element["id"])]


def _implement_put_dataset(page: dict, dataset: dict) -> None:
    rows = list(page.get("datasets") or [])
    names = [d.get("name") if isinstance(d, dict) else None for d in rows]
    copy = json.loads(json.dumps(dataset, default=str))
    if dataset.get("name") in names:
        rows[names.index(dataset.get("name"))] = copy
    else:
        rows.append(copy)
    page["datasets"] = rows


def _implement_page_reorder(page: dict, group: str, order: list) -> None:
    items = list(page.get(group) or [])
    slots = [n for n, item in enumerate(items) if isinstance(item, dict) and str(item.get("id")) in order]
    by_id = {str(items[n]["id"]): items[n] for n in slots}
    for n, ident in zip(slots, [i for i in order if i in by_id]):
        items[n] = by_id[ident]
    page[group] = items


def _implement_keep_new_wiring(page: dict, element, known: set) -> None:
    columns = element["node"].get("columns") if element and element["group"] == "filters" else None
    if not isinstance(columns, dict):
        return
    for item in page.get("filters") or []:
        if isinstance(item, dict) and str(item.get("id")) == element["id"]:
            kept = item.get("columns") if isinstance(item.get("columns"), dict) else {}
            item["columns"] = dict(kept, **{k: v for k, v in columns.items() if k not in known})


def implement_restore_untargeted(name: str, prior, new, changes, targets, records_dataset: str) -> tuple:
    merged = json.loads(json.dumps(new, default=str))
    if name == "genie_space":
        before = implement_genie_space_elements(prior)
        for change in changes:
            _implement_put_genie_part(merged, before[change["key"]])
        return merged, list(changes), []
    before = implement_output_elements(name, prior, records_dataset)
    after = implement_output_elements(name, new, records_dataset)
    queries = {str(d["name"]): d for d in prior.get("datasets") or [] if isinstance(d, dict) and d.get("name")}

    def readers(dataset):
        return sorted({side[key]["label"] for side in (before, after) for key in targets["keys"]
                       if key in side and dataset in side[key]["datasets"]})

    restored, blocked, dropped = [], [], []
    for change in [c for c in changes if c["change"] != "moved"]:
        if change["change"] == "added":
            _implement_drop_page_element(merged, after[change["key"]])
            dropped.append(after[change["key"]])
            restored.append(change)
            continue
        old = before[change["key"]]
        current = {str(d["name"]): implement_definition_shape(d.get("sql")) for d in merged.get("datasets") or []
                   if isinstance(d, dict) and d.get("name")}
        differ = [dataset for dataset, query in old["datasets"].items() if _implement_dataset_moved(query, current.get(dataset))]
        clash = {dataset: readers(dataset) for dataset in differ if readers(dataset)}
        if clash:
            reason = "; ".join(f"its dataset {dataset} {'is gone' if dataset not in current else 'reads differently'} for the asks of "
                               f"the {', the '.join(who)}" for dataset, who in clash.items())
            blocked.append(dict(change, reason=reason, was={"element": old["node"], "datasets": [queries[d] for d in clash if d in queries]}))
            continue
        for dataset in differ:
            if dataset in queries:
                _implement_put_dataset(merged, queries[dataset])
        _implement_put_page_element(merged, prior, old)
        _implement_keep_new_wiring(merged, after.get(change["key"]), _implement_prior_datasets(prior))
        restored.append(change)
    moved = [c for c in changes if c["change"] == "moved"]
    stuck = {c["key"] for c in blocked}
    for group in dict.fromkeys(before[c["key"]]["group"] for c in moved):
        _implement_page_reorder(merged, group, [element["id"] for key, element in before.items()
                                                if element["group"] == group and key not in targets["keys"] and key not in stuck])
    restored += moved
    left = {dataset for element in implement_page_elements(merged, records_dataset).values() for dataset in element["datasets"]}
    gone = {dataset for element in dropped for dataset in element["datasets"]} - left - set(queries) - {records_dataset}
    if gone:
        merged["datasets"] = [d for d in merged.get("datasets") or [] if not (isinstance(d, dict) and str(d.get("name")) in gone)]
    return merged, restored, blocked


def implement_untargeted_repair(name: str, blocked: list) -> str:
    listed = "".join(f"- the {item['label']}: you {item['what']}, and Inspire could not put it back because {item['reason']}. As it "
                     f"was: {json.dumps(item.get('was'), ensure_ascii=False, default=str)[:2000]}\n" for item in blocked)
    return (f"\n\nInspire keeps every part of the {IMPLEMENT_OUTPUT_LABELS[name]} that no ask targets exactly as it was, and puts back "
            f"what you change in them. You changed these, and putting them back would undo an ask:\n{listed}Keep each of them as it "
            "was, with the dataset it reads; when an ask needs a dataset that another element also reads, give the ask a dataset of "
            "its own instead of changing the shared one. Change only what the asks name. Your files from that attempt are in your "
            "working folder: change them rather than starting over, and write them again.")


def implement_untargeted_missed(name: str, blocked: list) -> str:
    return (f"the {IMPLEMENT_OUTPUT_LABELS[name]} changed what no ask targets, and Inspire could not put it back: "
            + "; ".join(f"the {item['label']} ({item['reason']})" for item in blocked))


def _implement_untargeted_entry(name: str, item: dict, built: str, version, fixed: bool, rounds: int) -> dict:
    evidence = (f"Genie {item['what']}; Inspire put it back as {built} built it" if fixed else
                f"Genie {item['what']}, and Inspire could not put it back because {item['reason']}")
    return {"requirement": f"Keep the {item['label']} as {built} built it: no ask of v{version} targets it", "part": name,
            "where": f"the {item['label']}", "status": "met" if fixed else "not_met",
            "kind": IMPLEMENT_SELF_FIX_KIND if fixed else IMPLEMENT_UNREQUESTED_KIND, **implement_checklist_texts(evidence[:1500]), "rounds": rounds,
            "tried": [], "checks": [], "published_anyway": None}


def implement_untargeted_entries(found, version) -> list:
    entries = []
    for name, record in (found or {}).items():
        built = f"v{record['version']}" if record.get("version") else "the version before"
        entries += [_implement_untargeted_entry(name, item, built, version, True, 0) for item in record.get("restored") or []]
        entries += [_implement_untargeted_entry(name, item, built, version, False, int(record.get("rounds") or 0))
                    for item in record.get("blocked") or []]
    return entries


IMPLEMENT_AS_IS_RE = re.compile(r"^(?:rebuild|recreate|keep|leave)\b.*\bas(?: it)? (?:is|was)(?: now)?[.!]?$", re.IGNORECASE)


def implement_vibes_as_is_ask(ask) -> dict:
    """An ask to rebuild or keep the part as it is changes nothing, so it is a keep ask with no element or check to name. The split
    can mark it as a change with a page check, which turns the untargeted restore off and lets Genie rewrite every element."""
    text = " ".join(str(ask.get("ask") or "").split()) if isinstance(ask, dict) else ""
    if not isinstance(ask, dict) or ask.get("keep") or not IMPLEMENT_AS_IS_RE.match(text):
        return ask
    return dict(ask, keep=True, check=None, where="")


def implement_vibes_keeps_rest(ask) -> bool:
    return isinstance(ask, dict) and bool(ask.get("keep")) and not " ".join(str(ask.get("where") or "").split())


def implement_as_is_only(asks) -> bool:
    """True when every ask of a part keeps it as it is (REQ-204): the last published copy is reused with no Genie round."""
    return bool(asks) and all(
        isinstance(ask, dict) and ask.get("keep") and ask.get("check") is None and not " ".join(str(ask.get("where") or "").split())
        and IMPLEMENT_AS_IS_RE.match(" ".join(str(ask.get("ask") or "").split())) for ask in asks)


def implement_vibes_rest_kept(name: str, asks, prior, new, label: str, shell_sql=None):
    records = "" if name == "genie_space" else shell_sql.RECORDS_DATASET if shell_sql is not None else None
    if name not in IMPLEMENT_UNTARGETED_OUTPUTS or records is None or not isinstance(prior, dict) or not isinstance(new, dict):
        return None
    targets = implement_untargeted_targets(name, asks, prior, new, records, shell_sql)
    if targets is None:
        return None
    changes = implement_untargeted_changes(name, prior, new, targets, records)
    if not changes:
        return "done", f"nothing on the built {label} that the other asks did not name changed from the version before"
    more = f", and {inspire_plural(len(changes) - 1, 'other change')} no ask names" if len(changes) > 1 else ""
    return "missing", (f"the {changes[0]['label']} is not as the version before built it, and no other ask names it: Genie "
                       f"{changes[0]['what']}{more}")[:500]


def _implement_vibes_said_word(text: str, word: str) -> bool:
    return bool(word) and re.search(rf"(?<!\w){re.escape(word.lower())}(?!\w)", text) is not None


def implement_vibes_cited_keys(seens, text) -> set:
    said = " ".join(str(text or "").split()).lower()
    return {key for seen in seens for key, element in (seen or {}).items()
            if _implement_vibes_said_word(said, key) or any(_implement_vibes_said_word(said, " ".join(str(alias).split()))
                                                            for alias in element["aliases"]
                                                            if _implement_vibes_tokens(alias) - set(IMPLEMENT_VIBES_NAME_KINDS))}


def implement_vibes_targeted_keys(seens, asks) -> set:
    prior, new = [seen or {} for seen in (list(seens) + [{}, {}])[:2]]
    keys, allow = set(), {}
    for asset, ask in asks or []:
        if not isinstance(ask, dict) or ask.get("keep"):
            continue
        if str(asset).startswith("dashboard:"):
            keys.add(str(asset).split(":", 1)[1])
            continue
        named, _names = implement_vibes_ask_keys(seens, ask)
        group = implement_vibes_added_group(ask)
        keys |= named
        if not named and group:
            allow[group] = allow.get(group, 0) + 1
    for key in [k for k in new if k not in prior and k not in keys]:
        group = IMPLEMENT_VIBES_KIND_GROUPS.get(new[key].get("kind"))
        if allow.get(group, 0) > 0:
            allow[group] -= 1
            keys.add(key)
    return keys


def implement_vibes_cites_only_elements(seens, where, evidence) -> bool:
    where = " ".join(str(where or "").split())
    if where and not any(where in (seen or {}) for seen in seens):
        return False
    mapped = True
    for part in re.split(r"[.;:!?](?:\s+|$)|,\s+|\s+(?:and|but|while|whereas|plus)\s+", " ".join(str(evidence or "").split())):
        part = re.sub(r"(?i)^(?:and|but|so|while|plus|then)\s+", "", part.strip())
        if not part or re.search(r"(?i)\basks?\b", part):
            continue
        if not IMPLEMENT_VIBES_CONTINUES_RE.match(part):
            mapped = bool(implement_vibes_cited_keys(seens, part))
        if not mapped and IMPLEMENT_VIBES_CHANGE_WORDS_RE.search(part):
            return False
    return True


def implement_vibes_rest_cited(verdict, cited_text: str, asks, seen: dict, earlier, label: str) -> tuple:
    if not verdict or verdict[0] != "missing" or earlier is None:
        return verdict
    seens = [earlier, seen or {}]
    cited = implement_vibes_cited_keys(seens, f"{cited_text} {verdict[1]}")
    targeted = implement_vibes_targeted_keys(seens, asks)
    if not cited or not cited <= targeted or not implement_vibes_cites_only_elements(seens, cited_text, verdict[1]):
        return verdict
    named = " and the ".join(sorted({(seen or {}).get(key, earlier.get(key, {})).get("name") or key for key in cited}))
    return "done", (f"the only change the check names on the built {label} is the {named}, which another ask targets, so "
                    f"everything else is kept: {verdict[1]}")[:500]


def implement_guarded_outputs(previous, current, plan) -> list:
    if not previous or plan.get("refill"):
        return []
    before, outputs, again = previous.get("outputs") or {}, current.get("outputs") or {}, current.get("retry_asks") or {}
    refresh, restyle = set(plan.get("refresh") or ()), set(plan.get("restyle") or ())
    return [name for name in IMPLEMENT_UNTARGETED_OUTPUTS if name in refresh and name not in restyle
            and (implement_vibed_assets(outputs, name) or any(again[a] for a in again if implement_asset_owner(a) == name))
            and implement_merge_target(before, name) == implement_merge_target(outputs, name)
            and all(before.get(o) == outputs.get(o) for o in IMPLEMENT_OUTPUT_OPTIONS[name] if not o.endswith("_vibes"))]


def _implement_vibes_shows(element: dict) -> str:
    return " ".join(" ".join(element["lines"]).split()).lower()


def _implement_vibes_quoted(evidence) -> str:
    quoted = re.sub(r"^(?:[-*]\s+)+", "", " ".join(str(evidence or "").split()))
    return quoted[1:-1].strip() if len(quoted) > 1 and quoted[0] == quoted[-1] and quoted[0] in "\"'" else quoted


def _implement_vibes_quote(text: str, start: int, end: int) -> str:
    return " ".join(text[max(0, start - 60):end + 60].split())


IMPLEMENT_CHART_TYPE_WORDS = {"column": "bar", "vertical_bar": "bar", "stacked_column": "stacked_bar", "doughnut": "donut",
                              "heat_map": "heatmap", "scatterplot": "scatter", "grouped_column": "grouped_bar",
                              "clustered_bar": "grouped_bar", "clustered_column": "grouped_bar", "side_by_side_bar": "grouped_bar"}
IMPLEMENT_CHART_ORDERS = ("value_desc", "value_asc", "x_asc")
IMPLEMENT_VIBES_PAGE_NODE_KEYS = ("records", "tables", "charts", "kpis", "filters", "blocks", "columns", "detail", "x", "y")
IMPLEMENT_VIBES_RECORD_COLUMNS = ("rank", "label", "sublabel", "tier", "reasons", "action")
IMPLEMENT_VIBES_SQL_FILTER_RE = re.compile(r"(?is)\b(?:where|having|qualify)\b(.*?)(?=\b(?:group\s+by|order\s+by|limit|window|union|intersect|"
                                           r"except|having|qualify)\b|[);]|$)")


def implement_chart_type_name(value) -> str:
    words = "_".join(re.sub(r"(?i)\b(?:charts?|graphs?|plots?|diagrams?)\b", " ", str(value or "")).lower().split())
    return IMPLEMENT_CHART_TYPE_WORDS.get(words, words)


def implement_chart_kind_problem(value, chart_types, label: str) -> str:
    return f"the {label} cannot draw a {value} chart: it draws {', '.join(chart_types)} charts"


def implement_drawable_chart_types(types) -> tuple:
    types = tuple(types)
    if "bar" not in types or "grouped_bar" in types:
        return types
    at = types.index("stacked_bar") + 1 if "stacked_bar" in types else len(types)
    return types[:at] + ("grouped_bar",) + types[at:]


def implement_chart_kinds(chart: dict) -> set:
    kind = str(chart.get("type") or "").lower()
    series = isinstance(chart.get("series"), dict) and bool(chart["series"].get("column"))
    many = series or (isinstance(chart.get("y"), list) and len(chart["y"]) > 1)
    kinds = {kind, {"stacked_bar": "bar", "stacked_area": "area", "pie": "donut"}.get(kind, kind)}
    return kinds | ({"grouped_bar"} if kind == "bar" and many else set())


def implement_chart_type_words(chart: dict) -> list:
    if not str(chart.get("type") or "").strip():
        return []
    kinds = implement_chart_kinds(chart)
    words = [str(chart["type"]).lower()] + sorted(kinds - {str(chart["type"]).lower()})
    words += sorted(word for word, normal in IMPLEMENT_CHART_TYPE_WORDS.items() if normal in kinds)
    return list(dict.fromkeys(w.replace("_", " ") for w in words if w))


def implement_chart_order(chart: dict) -> str:
    x = chart.get("x") if isinstance(chart.get("x"), dict) else {}
    if chart.get("type") in ("scatter", "heatmap", "donut", "pie"):
        return ""
    if x.get("kind") == "time":
        return "x_asc"
    order = "value_desc" if chart.get("type") == "pareto" else chart.get("sort", "value_desc")
    return order if order in IMPLEMENT_CHART_ORDERS else ""


def _implement_vibes_chart_order(chart: dict) -> str:
    order = implement_chart_order(chart)
    if not order:
        return ""
    x = chart.get("x") if isinstance(chart.get("x"), dict) else {"column": chart.get("x")}
    if order == "x_asc":
        return " ".join(f"{order} by {x.get('column') or ''} {x.get('label') or ''}".split())
    ys = chart.get("y") if isinstance(chart.get("y"), list) else [chart.get("y")]
    named = " ".join(f"{y.get('label') or ''} {y.get('expression') or ''}" if isinstance(y, dict) else str(y or "") for y in ys)
    return " ".join(f"{order} by {named}".split())


def implement_vibes_page_node(node) -> bool:
    return isinstance(node, dict) and any(key in node for key in IMPLEMENT_VIBES_PAGE_NODE_KEYS)


def _implement_vibes_column_holders(node: dict) -> list:
    holders = [node] if any(key in node for key in ("columns", "detail", "x", "y")) else []
    holders += [node["records"]] if isinstance(node.get("records"), dict) else []
    return holders + [item for group in ("tables", "charts") for item in node.get(group) or [] if isinstance(item, dict)]


def _implement_vibes_holder_columns(holder: dict) -> list:
    found = [(e.get("column"), e.get("label")) if isinstance(e, dict) else (e, e) for key in ("columns", "detail") for e in holder.get(key) or []]
    axes = [holder.get("x"), *(holder["y"] if isinstance(holder.get("y"), list) else [holder.get("y")])]
    found += [(axis.get("column"), axis.get("label")) if isinstance(axis, dict) else (axis, axis) for axis in axes if axis]
    found += [((holder.get("series") or {}).get("column"), "")] if isinstance(holder.get("series"), dict) else []
    if holder.get("key") and holder.get("rank"):
        found += [(holder.get(key), holder.get("label_title") if key == "label" else "") for key in IMPLEMENT_VIBES_RECORD_COLUMNS]
    return [(str(column), str(shown or column)) for column, shown in found if isinstance(column, str) and column]


def _implement_vibes_column_words(text) -> str:
    # RC6-D-03: case, underscores, spaces and camelCase are one spelling (paymentMethod = payment_method = Payment Method).
    return " ".join(re.sub(r"[_\s]+", " ", re.sub(r"(?<=[a-z0-9])(?=[A-Z])", " ", str(text))).split()).lower()


def implement_vibes_value_columns(item: dict, queries: dict) -> list:
    sql = _INSPIRE_KIND_QUOTED_RE.sub(" ", queries.get(str(item.get("dataset")), ""))
    filters = " ".join(found.group(1) for found in IMPLEMENT_VIBES_SQL_FILTER_RE.finditer(sql))
    return implement_kind_columns(f"{item.get('expression') or ''} {filters}")


def implement_vibes_column_used(check: dict, seen) -> str:
    wanted = _implement_vibes_column_words(check.get("value"))
    return next((f"the {element['name']} works out its number from the column {column}" for element in (seen or {}).values()
                 for column in element.get("uses") or [] if wanted and _implement_vibes_column_words(column) == wanted), "")


def _implement_vibes_titled(holder: dict, wanted: str) -> bool:
    title = holder.get("title")
    if not (wanted and ("x" in holder or "y" in holder) and isinstance(title, str) and f" {wanted} " in f" {_implement_vibes_column_words(title)} "):
        return False
    measured = {w for c, s in _implement_vibes_holder_columns(holder) for w in re.split(r"[^a-z0-9]+", _implement_vibes_column_words(f"{c} {s}")) if w}
    asked = {w for w in re.split(r"[^a-z0-9]+", wanted) if w} - IMPLEMENT_VIBES_GENERIC_WORDS - {"total", "sum", "count"}
    return bool(asked & measured)


def implement_vibes_column_fact(check: dict, node: dict, label: str) -> tuple:
    plain = _implement_vibes_column_words
    wanted = plain(check.get("value"))
    holders = [h for h in _implement_vibes_column_holders(node) if _implement_vibes_holder_columns(h) or _implement_vibes_titled(h, wanted)]
    named = lambda h: str(h.get("title") or h.get("label") or h.get("id") or "table")
    shows = {id(h): next((f"{named(h)} shows the column {c} ({s})" for c, s in _implement_vibes_holder_columns(h)
                          if wanted in (plain(c), plain(s))), "")
             or (f"{named(h)} is the chart titled {h.get('title')}, which shows {check.get('value')}" if _implement_vibes_titled(h, wanted) else "")
             for h in holders}
    if check.get("all") is True:
        tables = [h for h in holders if "columns" in h or "detail" in h]
        lacking = [named(h) for h in tables if not shows[id(h)]]
        if not tables:
            return "missing", f"the built {label} has no table, so no table shows the column {check.get('value')}"
        if not lacking:
            return "done", "; ".join(shows[id(h)] for h in tables)[:500]
        return "missing", f"not every table on the built {label} shows the column {check.get('value')}: {', '.join(lacking)} does not"
    hit = next((shows[id(h)] for h in holders if shows[id(h)]), "")
    return ("done", hit) if hit else ("missing", f"the built {label} names no column {check.get('value')}")


def implement_served_rows(shell, headers: dict, page: dict) -> list:
    """The rows the served App's decision list returns for its first read (no filters). Tables have no served read here."""
    if not page.get("records"):
        return []
    return list((shell.records(headers, {"page": page["id"]}) or {}).get("rows") or [])


def implement_served_page(meta: dict, problem, rows=None) -> dict:
    """What the served App shows of one page: its page filters, its column filters per holder ("records" for the list, the table
    id for each table), and the columns the served decision list shows ("shown": None when it returned no rows, so the spec judges)."""
    def entries(items):
        return {str(item["column"]): {"label": str(item.get("label") or ""), "problem": "" if item.get("lazy") else problem(item)}
                for item in items if isinstance(item, dict) and item.get("column")}
    columns = meta.get("columns") or {}
    held = {"records": entries(columns.get("list") or [])}
    held.update({str(table): entries(items or []) for table, items in (columns.get("tables") or {}).items()})
    return {"filters": {str(f["id"]): {"label": str(f.get("label") or ""), "problem": problem(f)} for f in meta.get("filters") or []},
            "columns": held, "shown": sorted({str(key) for row in rows for key in row}) if rows else None}


def _implement_vibes_served_filter(value: str, page: dict, label: str, served: dict) -> tuple:
    word = re.compile(rf"(?i)(?<![A-Za-z0-9_]){re.escape(value)}(?![A-Za-z0-9_])")
    if str(page.get("id")) not in served:
        return "missing", (f"{IMPLEMENT_VIBES_UNCHECKED}: the filters of the served {label} were not read, so the filter on {value} "
                           "could not be checked")
    shown = (served[str(page.get("id"))] or {}).get("filters") or {}
    listed = [(fid, entry) for fid, entry in shown.items() if word.search(f"{fid} {entry.get('label') or ''}")]
    if not listed:
        return "missing", f"the served {label} has no filter on {value}; its served filters are " + (", ".join(shown) or "none")
    fid, entry = listed[0]
    if entry.get("problem"):
        return "missing", f"the served {label} has the filter {fid} on {value}, but {entry['problem']}"
    return "done", f"filter {fid} on {value}: the served {label} lists it with its options"


def implement_vibes_fact(check, target, label: str, chart_types=(), seen=None, shell_sql=None, served=None) -> tuple:
    if not isinstance(check, dict) or target is None:
        return None
    kind, value, target = check.get("kind"), str(check.get("value")).strip(), implement_vibes_shown(target)
    text = implement_vibes_text(target)
    word = re.compile(rf"(?i)(?<![A-Za-z0-9_]){re.escape(value)}(?![A-Za-z0-9_])")
    if kind == "text":
        for source in (" ".join(shown.split()) for shown in ([" ".join(e["lines"]) for e in seen.values()] if seen is not None
                                                              else [text])):
            found = re.search(re.escape(" ".join(value.split())), source, re.I)
            if found:
                return "done", _implement_vibes_quote(source, found.start(), found.end())
        return "missing", f"the built {label} never shows the words '{value}'"
    shaped = implement_vibes_page_node(target)
    if kind == "column":
        if shaped:
            return implement_vibes_column_fact(check, target, label)
        found, used = word.search(text), implement_vibes_column_used(check, seen)
        if found:
            return "done", _implement_vibes_quote(text, found.start(), found.end())
        spelled = re.compile(rf"(?<![a-z0-9]){re.escape(_implement_vibes_column_words(value))}(?![a-z0-9])")
        if spelled.search(_implement_vibes_column_words(text)):
            return "done", f"the built {label} writes the column {value}"
        return ("done", used) if used else ("missing", f"the built {label} names no column {value}")
    if kind == "threshold":
        try:
            wanted = float(value)
        except ValueError:
            return None
        source = (" ".join(" ".join(e["lines"]) for e in (seen if seen is not None else implement_page_seen(target, shell_sql)).values()) if shaped
                  else text)
        for found in re.finditer(r"-?\d+(?:\.\d+)?", source):
            if float(found.group(0)) == wanted:
                return "done", _implement_vibes_quote(source, found.start(), found.end())
        return "missing", f"the built {label} uses no {value}"
    if not isinstance(target, dict):
        return None
    if kind == "chart_type":
        normal = implement_chart_type_name(value)
        charts = [target] if "type" in target and "x" in target else [c for c in target.get("charts") or [] if isinstance(c, dict)]
        if not chart_types:
            return None
        if normal not in chart_types:
            return "missing", implement_chart_kind_problem(value, chart_types, label)
        if not charts:
            return "missing", f"the built {label} has no chart, so it has no {normal} chart"
        names = inspire_shell_facts.chart_names({"charts": charts})  # REQ-237: person copy names a chart by its title, never its id
        listed = ", ".join(f"{c.get('type')} {names[str(c.get('id'))]}" for c in charts)
        if check.get("all") is True and len(charts) > 1:
            wrong = [c for c in charts if normal not in implement_chart_kinds(c)]
            return (("missing", f"not every chart on the built {label} is a {normal} chart; its charts are {listed}") if wrong
                    else ("done", f"each of its {inspire_plural(len(charts), 'chart')} is a {normal} chart: {listed}"))
        hit = next((c for c in charts if normal in implement_chart_kinds(c)), None)
        if hit:
            return "done", f"{names[str(hit.get('id'))]}: type {hit.get('type')}"
        return "missing", f"the built {label} has no {normal} chart; its charts are {listed}"
    if kind == "filter" and served is not None and shaped:
        return _implement_vibes_served_filter(value, target, label, served)
    if kind == "filter":
        filters = [target] if "columns" in target and "type" in target else [f for f in target.get("filters") or [] if isinstance(f, dict)]
        filters += implement_column_filters(target, shell_sql)
        if not filters and not any(key in target for key in ("filters", "column_filters", "columns", "detail")):
            return None
        hit = next((f for f in filters if word.search(implement_vibes_text(f))), None)
        if hit:
            return "done", f"filter {hit.get('id')}: {implement_vibes_text(hit)[:200]}"
        return "missing", (f"the built {label} has no filter on {value}; its filters are "
                           + (", ".join(str(f.get("id")) for f in filters) or "none"))
    if kind == "page":
        if "title" not in target or "id" not in target or not any(key in target for key in ("question", "records", "charts", "kpis")):
            return None
        shown = f"{target.get('id')} {target.get('title')} {target.get('question') or ''}"
        if word.search(shown):
            return "done", f"page {target.get('id')}: {target.get('title')}"
        return "missing", f"the built {label} is the page {target.get('id')} ({target.get('title')}), not {value}"
    if kind != "sort":
        return None
    orders = []

    def walk(node, path):
        if isinstance(node, dict):
            chart = all(key in node for key in ("type", "x", "y"))
            if chart and _implement_vibes_chart_order(node):
                orders.append((f"{path}sort", _implement_vibes_chart_order(node)))
            for key, inner in node.items():
                if key in ("sort", "order_by", "rank") and isinstance(inner, (str, int, float)) and not (chart and key == "sort"):
                    orders.append((f"{path}{key}", str(inner)))
                if key == "sort" and isinstance(inner, dict) and inner.get("key") and not chart:
                    orders.append((f"{path}sort", _implement_vibes_sort_text(node, inner, shell_sql)))
                walk(inner, f"{path}{node.get('id') or key}.")
        elif isinstance(node, list):
            for inner in node:
                walk(inner, path)

    walk(target, "")
    if not orders:
        return ("missing", f"the built {label} sets no order, so it never orders by {value}") if shaped else None
    direction, wanted = str(check.get("direction") or "").lower(), {t for t in re.split(r"[^a-z0-9]+", value.lower()) if t}

    def fits(order: str) -> bool:
        tokens = set(re.split(r"[^a-z0-9]+", order.lower()))
        return wanted <= tokens and (direction not in ("asc", "desc") or direction in tokens or order.lower() == value.lower())

    hit = next(((p, v) for p, v in orders if fits(v)), None)
    if hit:
        return "done", f"{hit[0]}: {hit[1]}"
    return "missing", f"the built {label} orders by " + ", ".join(f"{p} {v}" for p, v in orders) + f", never by {value}"


def _implement_vibes_sort_text(node: dict, sort: dict, shell_sql=None) -> str:
    shown = dict(_implement_vibes_holder_columns(node))
    if shell_sql is not None:
        shown.update({column: entry[0] for column, entry in shell_sql.list_shown(node).items()})
    return " ".join([str(sort["key"]), str(shown.get(sort["key"]) or ""), str(sort.get("dir") or "asc")]).replace("  ", " ")


def _implement_vibes_blocks(node) -> list:
    return [b for b in (node.get("blocks") or [] if isinstance(node, dict) else []) if isinstance(b, dict) and b.get("id")]


def _implement_block_shown(block: dict) -> str:
    return (f"block {block['id']}: {block.get('kind')} {implement_block_place_text(block)}, {block.get('width') or 'full'} width, "
            f"aligned {block.get('align') or 'left'}")


def implement_block_gate(value, blocks: list, label: str):
    asked = value if isinstance(value, dict) else {"kind": value}
    wanted = {k: str(v).strip().lower() for k, v in asked.items() if k in ("kind", "place", "of", "width", "align") and str(v or "").strip()}
    if not wanted:
        return None

    def holds(block: dict) -> bool:
        place = block.get("place") if isinstance(block.get("place"), dict) else {}
        held = {"kind": block.get("kind"), "place": place.get("where") or "bottom", "of": place.get("of") or "",
                "width": block.get("width") or "full", "align": block.get("align") or "left"}
        # RC6-D-03: `of` names the block a place is before or after; at the top or bottom the page itself is meant, so it is not compared.
        return all(str(held[k]).lower() == v for k, v in wanted.items() if not (k == "of" and wanted.get("place") in ("top", "bottom")))

    hit = next((b for b in blocks if holds(b)), None)
    if hit:
        return True, _implement_block_shown(hit)
    return False, (f"no block on the built {label} is {', '.join(f'{k} {v}' for k, v in wanted.items())}; its blocks are "
                   + ("; ".join(_implement_block_shown(b) for b in blocks) or "none"))


def implement_color_gate(value, node, label: str, look=None, blocks=None):
    wanted = str(value or "").strip().lower()
    if not wanted or not isinstance(node, dict):
        return None
    held = {"hue": node.get("hue"), **{k: (look or {}).get(k) for k in ("palette", "theme")}}
    hit = next((f"{k} {v}" for k, v in held.items() if v and str(v).lower() == wanted), None)
    hit = hit or next((f"block {b['id']}" for b in _implement_vibes_blocks(node)
                       if b.get("kind") == "html" and (blocks is None or str(b["id"]) in blocks)
                       and wanted in str(b.get("content") or "").lower()), None)
    if hit:
        return True, f"the built {label} shows {wanted}: {hit}"
    shown = ", ".join(f"{k} {v}" for k, v in held.items() if v)
    return False, f"the built {label} shows no {wanted}" + (f"; it sets {shown}" if shown else "")


def _implement_column_filter_verdict(wanted: str, title: str, filters: list, shown: list, served_shown=None) -> tuple:
    by_column = {f["column"]: f for f in filters}
    if wanted == "all":
        lacking = [column for column in shown if column not in by_column]
        unseen = [column for column in shown if served_shown is not None and column not in served_shown]
        if shown and not lacking and not unseen:
            return True, (f"the {title} table has a column filter on "
                          f"{'its one column' if len(shown) == 1 else 'each of its ' + inspire_plural(len(shown), 'column')}: "
                          + ", ".join(str(by_column[column]["label"]) for column in shown))
        if not shown:
            return False, f"the {title} table shows no column to filter"
        parts = ([f"the {title} table has no column filter on " + ", ".join(lacking)] if lacking else [])
        if unseen:
            parts.append(f"the served {title} table does not show " + ", ".join(unseen))
        return False, "; ".join(parts)
    hit = next((f for f in filters if wanted in (str(f["column"]).lower(), str(f["label"]).lower())), None)
    return (True, f"the {title} table has a column filter on {hit['label']}") if hit else (False, "")


def _implement_served_holder_filters(served_columns: dict) -> list:
    """The column filters the served App shows on one holder: the working ones, as the spec gate's filter entries."""
    return [{"column": column, "label": entry.get("label") or column} for column, entry in (served_columns or {}).items()
            if not entry.get("problem")]


def implement_column_filter_gate(value, node, label: str, shell_sql, table="", every: bool = False, served=None):
    """served: the served App's page entry (implement_served_page), or None to judge the spec. Its column filters and the columns its
    decision list shows decide the verdict; a holder whose shown columns come from the spec says so in its evidence."""
    if shell_sql is None or not isinstance(node, dict):
        return None
    columns = (served or {}).get("columns") or {}
    def filters_of(ident, spec):
        return spec if served is None else _implement_served_holder_filters(columns.get(ident))
    holders = []
    if isinstance(node.get("records"), dict):
        holders.append(("records", node["records"].get("title") or "records", filters_of("records", shell_sql.list_column_filters(node)),
                        shell_sql.list_shown(node["records"]), (served or {}).get("shown")))
    for held in node.get("tables") or []:
        if isinstance(held, dict) and held.get("id"):
            holders.append((held["id"], held.get("title") or held["id"], filters_of(held["id"], shell_sql.table_column_filters(held)),
                            shell_sql.table_shown(held), None))
    picked = [table] if isinstance(table, str) and table else list(table or [])
    holders = [h for h in holders if h[0] in picked] if picked else holders
    if not holders:
        return None
    wanted = str(value or "").strip().lower()
    verdicts = [_implement_column_filter_verdict(wanted, title, filters, shown, served_shown) for _ident, title, filters, shown, served_shown
                in holders]
    if served is not None:
        verdicts = [(v[0], f"{v[1]} (shown columns from the spec, not the served App)" if v[1] and served_shown is None and wanted == "all"
                     else v[1]) for v, (_i, _t, _f, _s, served_shown) in zip(verdicts, holders)]
    if every:
        if all(v[0] for v in verdicts):
            return True, "; ".join(v[1] for v in verdicts)[:500]
    elif any(v[0] for v in verdicts):
        return next(v for v in verdicts if v[0])
    return False, (f"no table on the built {label} has a column filter on {value}; "
                   + "; ".join(v[1] or f"the {title} table filters " + (", ".join(str(f["label"]) for f in filters) or "nothing")
                               for v, (_ident, title, filters, _shown, _served) in zip(verdicts, holders)))


def implement_schedule_gate(value, node, label: str):
    lines = node.get("schedule") if isinstance(node, dict) else None
    found = re.fullmatch(r"\s*(\d{1,2})(?:[:.](\d{2}))?\s*(am|pm|a\.m\.|p\.m\.)?\s*", str(value or "").lower())
    if not isinstance(lines, list) or not found:
        return None
    hour, minute, half = int(found.group(1)), int(found.group(2) or 0), (found.group(3) or "")[:1]
    hour = hour % 12 + (12 if half == "p" else 0) if half else hour
    if hour > 23 or minute > 59:
        return None
    at = f"at {hour:02d}:{minute:02d}"
    hit = next((line for line in lines if str(line).startswith("Runs ") and at in str(line)), None)
    if hit:
        return True, hit
    return False, f"the built {label} shows '{lines[-1] if lines else 'no schedule'}', not a run {at}"


def implement_clears_gate(value, node, label: str):
    wanted = implement_clears_wanted(value)
    if not isinstance(node, dict) or not isinstance(node.get("clears"), bool) or wanted is None:
        return None
    held = node["clears"]
    return ((True, IMPLEMENT_CLEARS_SHOWN[held]) if held == wanted
            else (False, f"the built {label} {IMPLEMENT_CLEARS_SHOWN[held][0].lower()}{IMPLEMENT_CLEARS_SHOWN[held][1:]}, not what was asked"))


def implement_recipient_gate(value, node, label: str):
    if not isinstance(node, dict) or not any(k in node for k in ("recipients", "destinations")):
        return None
    wanted, held = str(value or "").strip().lower(), [str(r) for r in list(node.get("recipients") or []) + list(node.get("destinations") or [])]
    hit = next((r for r in held if r.lower() == wanted), None)
    return (True, f"Sent to {hit}") if hit else (False, f"the built {label} is sent to {', '.join(held) or 'no one'}, not {value}")


def implement_result_fact_text(column: str, held: dict) -> str:
    if not held.get("exists"):
        return f"column {column}: the result table has no such column"
    text = (f"column {column}: {inspire_plural(held.get('rows'), 'row')} in the latest run, {held.get('non_null')} not empty, "
            f"{held.get('distinct')} distinct")
    if int(held.get("distinct") or 0) == 1:
        return text + ", every value the same"
    low, high = implement_decimal(held.get("low")), implement_decimal(held.get("high"))
    if low is not None and high is not None:
        return text + f", spanning {implement_number_text(float(high) - float(low))}"
    try:
        days = (inspire_parse_time(str(held.get("high"))[:10]) - inspire_parse_time(str(held.get("low"))[:10])).days
    except (TypeError, ValueError):
        return text
    return text + f", over {days} day{'' if days == 1 else 's'}"


def implement_result_gate(value, facts, label: str):
    asked = value if isinstance(value, dict) else {"column": value}
    column = str(asked.get("column") or "").strip()
    held = (facts or {}).get(column.lower()) if column else None
    if held is None:
        return None
    text = implement_result_fact_text(column, held)
    if not held.get("exists") or not held.get("non_null"):
        return False, text + ("" if not held.get("exists") else ": every value is empty")
    low, high = implement_decimal(asked.get("min")), implement_decimal(asked.get("max"))
    least, most = implement_decimal(held.get("low")), implement_decimal(held.get("high"))
    if low is not None and (least is None or least < low):
        return False, f"{text}: some values are below {asked['min']}"
    if high is not None and (most is None or most > high):
        return False, f"{text}: some values are above {asked['max']}"
    values = {str(v).lower() for v in held.get("values") or []}
    absent = [str(v) for v in asked.get("values") or [] if str(v).lower() not in values]
    if absent:
        return False, f"{text}: it never holds {', '.join(absent)}"
    return True, text


def implement_vibes_gate(check: dict, target, named: str, label: str, tools: dict):
    kind, value = check["kind"], check.get("value")
    tool = {"result": "facts", "column_filter": "shell_sql"}.get(kind)
    failed = (tools.get("unchecked") or {}).get(tool) if tool and tools.get(tool) is None else ""
    if failed:
        return False, f"{IMPLEMENT_VIBES_UNCHECKED}: {failed}"[:500]
    if kind == "result":
        return implement_result_gate(value, tools.get("facts"), label)
    if not isinstance(target, dict):
        return None
    scope = ([named] if named else None) if isinstance(named, str) or named is None else list(named)
    blocks = _implement_vibes_blocks(target)
    picked = None if scope is None else [str(b["id"]) for b in blocks if str(b["id"]) in {k.removeprefix("block ") for k in scope}]
    if kind == "block":
        if not any(k in target for k in ("blocks", "charts", "records", "kpis")):
            return None
        return implement_block_gate(value, [b for b in blocks if str(b["id"]) in picked] if picked else blocks, label)
    if kind == "color":
        return implement_color_gate(value, target, label, tools.get("look"), picked)
    if kind == "column_filter":
        tables = (["records"] if isinstance(target.get("records"), dict) else []) + [t.get("id") for t in target.get("tables") or []
                                                                                  if isinstance(t, dict)]
        named_tables = [k for k in scope or [] if k in tables]
        if scope is not None and not named_tables:
            return False, f"the {' or the '.join(scope)} on the built {label} is not a table, so it has no column filters"
        if tools.get("served") is not None and "id" in target:
            if str(target["id"]) not in tools["served"]:
                return False, (f"{IMPLEMENT_VIBES_UNCHECKED}: the column filters of the served {label} were not read, so the column "
                               f"filter on {value} could not be checked")
            served = tools["served"][str(target["id"])] or {}
            return implement_column_filter_gate(value, target, label, tools.get("shell_sql"), named_tables, check.get("all") is True, served)
        return implement_column_filter_gate(value, target, label, tools.get("shell_sql"), named_tables, check.get("all") is True)
    if kind == "schedule":
        return implement_schedule_gate(value, target, label)
    if kind == "recipient":
        return implement_recipient_gate(value, target, label)
    if kind == "clears":
        return implement_clears_gate(value, target, label)
    return None


def implement_ask_identity(asset, where, ask) -> str:
    shown = lambda text: " ".join(str(text or "").split()).lower()
    return hashlib.sha256("\n".join((str(asset or ""), shown(where), shown(ask))).encode("utf-8")).hexdigest()[:16]


def implement_vibes_met(record, asset) -> set:
    return {implement_ask_identity(asset, c.get("where"), c.get("ask")) for c in (record or {}).get("vibes_checks") or []
            if isinstance(c, dict)
            and c.get("status") == "done" and not str(c.get("evidence") or "").startswith(IMPLEMENT_VIBES_ALREADY + IMPLEMENT_VIBES_CARRIED)}


def genie_code_model_key(name) -> str:
    return re.sub(r"[^a-z0-9]", "", str(name or "").lower())


def is_genie_code_model(name) -> bool:
    return genie_code_model_key(name).endswith(genie_code_model_key(GENIE_CODE_MODEL))


def is_genie_code_unfit_model(name) -> bool:
    return bool(re.search(GENIE_CODE_UNFIT_MODEL_PATTERN, str(name or ""), re.IGNORECASE))


def genie_code_ranked_models(slugs) -> list:
    """Every listed model Databricks AI can drive, in the family and version order the model roster uses, newest first within a
    family. gpt-oss models are left out: they reject the parallel_tool_calls setting Databricks AI sends."""
    listed = [s for s in dict.fromkeys(str(s or "").strip() for s in slugs or []) if s and not is_genie_code_unfit_model(s)]
    routes, seen, ranked = [_UnityGatewayRoute(s) for s in listed], set(), []
    for family_pat, exclude_pat, *_rest in LLM_FAMILY_SPECS:
        for name, _version in _family_endpoints(routes, family_pat, exclude_pat, seen):
            seen.add(name)
            ranked.append(name)
    return ranked + [s for s in listed if s not in seen]


def genie_code_model_candidates(slugs) -> list:
    """GENIE_CODE_MODEL first, then every model Unity Gateway lists, in the family and version order the model roster uses."""
    return [GENIE_CODE_MODEL] + genie_code_ranked_models(s for s in slugs or [] if not is_genie_code_model(s))


class GenieCodeRoute:
    """The Unity Gateway path Databricks AI calls and the model it asks for there, with what that path supports."""

    def __init__(self, model: str, gateway: dict):
        self.model = str(model or "")
        self.route = gateway["route"]
        self.base = gateway["base"]
        self.web_search = bool(gateway["web_search"])
        self.schema_in_prompt = bool(gateway["schema_in_prompt"])
        self.relayed = bool(gateway.get("relayed"))

    def __eq__(self, other):
        return isinstance(other, GenieCodeRoute) and (self.model, self.base) == (other.model, other.base)

    def __hash__(self):
        return hash((self.model, self.base))

    def __repr__(self):
        return f"GenieCodeRoute({self.model!r} through {self.base})"

    def said(self) -> str:
        return f"{self.model} through the {self.route}"


GENIE_CODE_DEFAULT_ROUTE = GenieCodeRoute(GENIE_CODE_MODEL, GENIE_CODE_GATEWAYS[0])


def genie_code_route_discovery(call, logger, skip=()) -> dict:
    """The first Databricks AI route that answers one short request: the Codex route's models (GENIE_CODE_MODEL first, then the
    listed ones), then the Claude models the Anthropic route lists, called through the MLflow responses path. A route that
    only timed out is used only when no route answered. route is None when nothing answers; tried says why, in plain words."""
    refused, waiting, listed = [], [], {}
    for gateway in GENIE_CODE_GATEWAYS:
        models = unity_gateway_models(call, gateway["models"], logger)
        listed[gateway["route"]] = len(models)
        names = genie_code_model_candidates(models) if gateway["first"] else genie_code_ranked_models(models)
        for model in names:
            route = GenieCodeRoute(model, gateway)
            if route in skip:
                continue
            try:
                call("POST", f"{gateway['base']}/responses", dict(GENIE_CODE_MODEL_CHECK, model=model))
            except Exception as error:
                why = (GENIE_CODE_MODEL_DENIED if implement_is_permission_denied(error) else GENIE_CODE_MODEL_MISSING
                       if implement_is_not_found(error) else redact_error(error, max_chars=200))
                (waiting if implement_transient(error) else refused).append((route, why))
                logger.info(f"[GENIE_CODE_ROUTE] {route.said()} did not answer the check: {why}")
                continue
            return {"route": route, "refused": refused, "waiting": waiting, "listed": listed}
    if waiting:
        route = waiting[0][0]
        logger.warning(f"[GENIE_CODE_ROUTE] no route answered the check and {route.said()} only timed out or was busy, so Genie "
                       f"Code uses it")
        return {"route": route, "refused": refused, "waiting": waiting, "listed": listed}
    return {"route": None, "refused": refused, "waiting": waiting, "listed": listed}


def genie_code_route_tried(found: dict) -> str:
    refused = found.get("refused") or []
    tried = f"{inspire_plural(len(refused), 'model')}: " + "; ".join(f"{route.said()}: {why}" for route, why in refused)
    empty = [name for name, count in (found.get("listed") or {}).items() if not count]
    return tried + (f"; the {' and the '.join(empty)} {'lists' if len(empty) == 1 else 'list'} no model" if empty else "")


def genie_code_route_note(found: dict) -> str:
    """The sentence that tells the user Databricks AI builds with a model other than its first choice, and why."""
    route = found.get("route")
    if route is None or route == GENIE_CODE_DEFAULT_ROUTE:
        return ""
    first = dict(found.get("refused", []) + found.get("waiting", [])).get(GENIE_CODE_DEFAULT_ROUTE, "")
    return GENIE_CODE_OTHER_MODEL.format(model=route.said() if route.schema_in_prompt else route.model, first=GENIE_CODE_MODEL,
                                         why=first)


def genie_code_route_verdict(found: dict) -> dict:
    """What a buildability check records: whether Inspire can build with Databricks AI, through which route, and the plain reason
    and admin fix when it cannot."""
    route = found.get("route")
    if route is None:
        return {"available": False, "route": "", "base": "", "model": "",
                "reason": GENIE_CODE_NO_MODEL.format(tried=genie_code_route_tried(found), choices=GENIE_CODE_NO_MODEL_CHOICES),
                "fix": GENIE_CODE_ADMIN_FIX[:1].upper() + GENIE_CODE_ADMIN_FIX[1:] + "."}
    return {"available": True, "route": route.route, "base": route.base, "model": route.model,
            "reason": genie_code_route_note(found), "fix": ""}


def implement_vision_endpoints() -> list:
    chain = TECHNICAL_CONTEXT["runtime"].get("model_fallback_chain") or [{"type": "thinker", "size": "large"}]
    roster = _bucket_cascade(chain[0].get("type", "thinker"), chain[0].get("size", "large")) or sorted(
        [m for m in TECHNICAL_CONTEXT["models"] if _model_is_selectable(m)], key=lambda m: m.get("order", 999))
    names = [n for n in dict.fromkeys(str(m.get("llm_endpoint_name") or "") for m in LLM_ENDPOINT_HEALTH.demoted_last(roster)) if n]
    genie = [n for n in names if is_genie_code_model(n)][:1]
    return genie + [n for n in names if n not in genie]


def implement_vision_verdict(reply) -> tuple:
    content = ((((reply or {}).get("choices") or [{}])[0] or {}).get("message") or {}).get("content")
    text = content if isinstance(content, str) else "".join(str(part.get("text") or "") for part in content or []
                                                           if isinstance(part, dict) and part.get("type") == "text")
    cleaned = clean_json_response(text, want=dict) if text else ""
    try:
        parsed = json.loads(cleaned) if cleaned else None
    except ValueError:
        parsed = None
    if not isinstance(parsed, dict) or not all(isinstance(parsed.get(key), bool) for key in ("subject", "look")):
        raise ValueError(f"it gave no verdict: {inspire_redact_text(' '.join(str(text).split()), set(), '')[:200]}")
    return parsed["subject"] and parsed["look"], " ".join(str(parsed.get("reason") or "").split())[:400]


IMPLEMENT_VISION_PASSING = re.compile(r"(?i)time[ds]? ?out|timeout|temporarily|unavailable|deadline|too many requests|rate limit|"
                                      r"request_limit_exceeded|resource_exhausted|internal_error|internal server error|\b5\d\d\b")
IMPLEMENT_VISION_REFUSAL = re.compile(r"(?i)\b4\d\d\b|bad_request|invalid_parameter|not_found|does not exist|permission_denied|"
                                      r"unauthenticated|unauthorized|forbidden|(cannot|can't|can not|unable to|not able to|does not|doesn't|"
                                      r"do not|don't)\s+(read|see|view|open|process|support|accept|handle)\w*\s+(the\s+|any\s+)?"
                                      r"(images?|pictures?|image input)|images?\s+(input\s+)?(is|are)\s+not\s+supported")


def implement_vision_refused(error) -> bool:
    status = getattr(error, "status_code", None)
    if isinstance(status, int):
        return 400 <= status < 500 and status not in (408, 429)
    text = f"{getattr(error, 'error_code', '') or ''} {error}"
    return not IMPLEMENT_VISION_PASSING.search(text) and bool(IMPLEMENT_VISION_REFUSAL.search(text))


def implement_vibes_tried(found: dict, tried: dict, round_no: int) -> dict:
    for asset, checks in (found.get("checks") or {}).items():
        held = tried.setdefault(asset, {"asks": {}})
        for check in checks:
            if check["status"] != "done":
                held["asks"].setdefault(implement_ask_identity(asset, check.get("where"), check["ask"]), []).append(
                    f"round {round_no}: {check['evidence']}"[:300])
    return found


def implement_held_vibes(spec: dict) -> dict:
    outputs, notes = spec.get("outputs") or {}, str((spec.get("data") or {}).get("notes") or "")
    held = dict({IMPLEMENT_NOTEBOOK: notes} if notes.strip() else {}, **implement_asset_vibes(outputs, IMPLEMENT_NOTEBOOK))
    for name in IMPLEMENT_OUTPUTS:
        if outputs.get(name):
            held.update(implement_vibed_assets(outputs, name))
    return held


def implement_checklist_part(asset: str) -> str:
    return asset if asset in IMPLEMENT_ASSET_LABELS else implement_asset_owner(asset)


def implement_person_text(text, pages) -> str:
    # REQ-237: person copy names each App page and chart by its name (title, position among shared titles, or plain words). The check
    # keeps the ids for matching and Genie reads them, so only the person-facing text is rendered here.
    return inspire_shell_facts.plain_check_text(str(text), pages or [])


def implement_person_evidence(evidence, asset: str, pages=()) -> str:
    # One check record, two renderings (REQ-237). The evidence names an App page and its charts by id: that is the verdict sent back to
    # Genie, which reads exact names (D-NAMES). The person's checklist reads the same evidence with the names from implement_person_text.
    text = str(evidence or "")
    if not asset.startswith("app:page:"):
        return text
    page_id = asset[len("app:page:"):]
    pages = [p for p in pages or [] if isinstance(p, dict)]
    page = next((p for p in pages if str(p.get("id")) == page_id), None)
    if page is None:
        return implement_person_text(text, pages)
    title, spot = " ".join(str(page.get("title") or "").split()), inspire_shell_facts.page_names(pages)[page_id]
    text = inspire_shell_facts.plain_chart_text(text, page)
    if title:
        text = text.replace(f"the page {page_id} ({title})", spot).replace(f"page {page_id}: {title}", spot)
    return implement_person_text(text, pages)


def implement_checklist_where(asset: str, named: str = "", pages=(), titles=None) -> str:
    part = implement_part(asset) if asset not in IMPLEMENT_ASSET_LABELS else None
    spot = (inspire_shell_facts.page_names(pages).get(asset[len("app:page:"):]) or inspire_shell_facts.page_spot((titles or {}).get(asset) or "")
            if asset.startswith("app:page:") else
            (f"chart {titles[asset]}" if (titles or {}).get(asset) else "dashboard chart") if part and part[0] == "dashboard" else "")
    return ", ".join(p for p in (spot, named) if p)


_IMPLEMENT_VIBES_TAKES_OUT_RE = re.compile(r"(?i)^\s*(?:remove|take\s+out|delete|drop|hide|get\s+rid\s+of)\b")


def implement_vibes_taken_out(ask: dict, seen: dict, earlier, label: str):
    text = str((ask or {}).get("ask") or "")
    undone = text.split(": ", 1)[1].strip(" '\"") if implement_vibe_undoes(text) and ": " in text else ""
    if not _IMPLEMENT_VIBES_TAKES_OUT_RE.match(text) and not (undone and not _IMPLEMENT_VIBES_TAKES_OUT_RE.match(undone)):
        return False, None
    where = " ".join(str(ask.get("where") or "").split()) or implement_vibes_named({"ask": undone or text})
    now = implement_vibes_closest(seen, where) if where else []
    before = implement_vibes_closest(earlier or {}, where) if where else []
    if now:
        return True, ("missing", f"the built {label} still has the {implement_vibes_scope_name(seen, now)}, which the ask takes out")
    if before:
        return True, ("done", f"the built {label} no longer has the {implement_vibes_scope_name(earlier, before)}")
    if not where:
        return True, None
    return True, ("done", f"the built {label} has nothing matching {where}, so there is nothing left to take out")


def implement_vibes_checked(ask: dict, asset: str, target, seen: dict, built_before, earlier, label: str, chart_types=(),
                            shell_sql=None, served=None) -> tuple:
    check = ask.get("check")
    if (isinstance(check, dict) and check.get("kind") == "chart_type" and chart_types
            and implement_chart_type_name(check.get("value")) not in chart_types):
        return "missing", implement_chart_kind_problem(check.get("value"), chart_types, label)
    keys, problem = implement_vibes_scope(seen, ask, label)
    if problem:
        return "missing", problem
    settled = bool(ask.get("keep") or ask.get("asked_before") or earlier is None)
    if keys is not None:
        if (served is not None and isinstance(check, dict) and check.get("kind") == "filter" and "filters" in keys
                and implement_vibes_page_node(target)):
            return _implement_vibes_served_filter(str(check.get("value")).strip(), target, label, served)
        every = isinstance(check, dict) and check.get("all") is True
        scoped = lambda key: f"{seen[key]['name']} on the {label}"
        facts = [(key, fact) for key in keys
                 for fact in [implement_vibes_fact(check, seen[key]["node"], scoped(key), chart_types, {key: seen[key]}, shell_sql)] if fact]
        if not facts:
            return None
        done, missed = [(k, f) for k, f in facts if f[0] == "done"], [f for _k, f in facts if f[0] != "done"]
        if not done or (every and missed):
            return missed[0]
        joined = "; ".join(f[1] for _k, f in done)[:500] if every else done[0][1][1]
        if settled:
            return "done", joined
        shown_before = lambda key: key in earlier and (implement_vibes_fact(check, earlier[key]["node"], scoped(key), chart_types,
                                                                            {key: earlier[key]}, shell_sql) or ("",))[0] == "done"
        fresh = [f for k, f in done if not shown_before(k)]
        if not fresh:
            return "done", implement_vibes_already(joined)
        return ("done", joined) if every else fresh[0]
    fact = implement_vibes_fact(check, target, label, chart_types, seen, shell_sql, served)
    if not fact or fact[0] != "done" or settled:
        return fact
    for key, element in seen.items():
        here = implement_vibes_fact(ask["check"], element["node"], label, chart_types, {key: element}, shell_sql)
        before = earlier.get(key)
        again = implement_vibes_fact(ask["check"], before["node"], label, chart_types, {key: before}, shell_sql) if before else None
        if here and here[0] == "done" and not (again and again[0] == "done"):
            return here
    again = implement_vibes_fact(ask["check"], implement_vibes_target(asset, built_before)[0], label, chart_types, earlier, shell_sql)
    return ("done", implement_vibes_already(fact[1])) if again and again[0] == "done" else fact


def implement_vibes_already(evidence) -> str:
    text = str(evidence or "")
    return (text if text.startswith(IMPLEMENT_VIBES_ALREADY) else f"{IMPLEMENT_VIBES_ALREADY}{text}")[:500]


def implement_vibes_judge_prompt(asset: str, asks: list, seen: dict, reported=(), earlier=None) -> str:
    return implement_vibes_round_prompt([{"asset": asset, "asks": asks, "seen": seen, "earlier": earlier, "reported": reported}])


def implement_vibes_sources_text(sources) -> str:
    return "\n".join(f"{table}: {', '.join(columns) or 'columns not read'}" for table, columns in (sources or {}).items())


def implement_vibes_held_terms(sources, use_case=None, more=()) -> frozenset:
    if not sources or not all(sources.values()):
        return frozenset()
    names = [name for table, columns in sources.items() for name in [table, *columns]] + [str(m) for m in more or ()]
    names += [value for key, value in (use_case or {}).items() if isinstance(value, str) and not str(key).startswith("_")]
    return frozenset(_implement_vibes_token(w) for name in names for w in re.split(r"[^a-z0-9]+", str(name).lower()) if w)


def _implement_vibes_subject_terms(text) -> list:
    words = [_implement_vibes_token(w) for w in re.split(r"[^a-z0-9]+", str(text or "").lower()) if len(w) > 2 and not w.isdigit()]
    return [w for w in words if w not in IMPLEMENT_MEASURE_GENERIC_WORDS and w not in IMPLEMENT_VIBES_GENERIC_WORDS
            and w not in IMPLEMENT_VIBES_NAME_KINDS]


def implement_vibes_absent_terms(ask, held, holders=()) -> list:
    if not held:
        return []
    text = ask.get("ask") if isinstance(ask, dict) else ask
    phrases = [" ".join(implement_vibes_phrase_words(p, shown=True)) for p in implement_vibes_checkable(ask)
               if len(implement_vibes_phrase_words(p)) > 1 and not implement_vibes_phrase_held(implement_vibes_phrase_words(p), holders)
               ] if holders and isinstance(ask, dict) else []
    return list(dict.fromkeys([w for w in _implement_vibes_subject_terms(text) if w not in held] + phrases))


def implement_vibes_phrase_words(phrase, shown: bool = False) -> list:
    skipped = IMPLEMENT_VIBES_PRESENTATION_WORDS | IMPLEMENT_VIBES_GENERIC_WORDS | set(IMPLEMENT_VIBES_NAME_KINDS)
    pairs = [(_implement_vibes_token(t), t) for t in re.split(r"[^a-z0-9]+", str(phrase or "").lower()) if t and not t.isdigit()]
    pairs = [(token, word) for token, word in pairs if token not in skipped]
    while pairs and pairs[0][0] in IMPLEMENT_VIBES_PHRASE_MODIFIERS:
        pairs.pop(0)
    while pairs and pairs[-1][0] in IMPLEMENT_VIBES_PHRASE_MODIFIERS:
        pairs.pop()
    return [word if shown else token for token, word in pairs]


def implement_vibes_phrase_holders(sources, comments=None) -> tuple:
    if not sources or not all(sources.values()):
        return ()
    holders = []
    for table, columns in sources.items():
        about, described = (comments or {}).get(table) or ("", {})
        owner = _implement_identifier_terms(str(table).rsplit(".", 1)[-1]) | set(_implement_vibes_tokens(about))
        for column in columns:
            own = _implement_identifier_terms(str(column)) | set(_implement_vibes_tokens(described.get(column)))
            holders.append((frozenset(owner | own), frozenset(own)))
    return tuple(holders)


def _implement_vibes_piece(piece: str, word: str) -> bool:
    return piece == word or (len(piece) >= 3 and word.startswith(piece)) or _implement_vibes_abbreviates(piece, word)


def _implement_vibes_compound(term: str, words) -> bool:
    if len(words) == 1:
        return _implement_vibes_piece(term, words[0])
    return any(_implement_vibes_piece(term[:cut], words[0]) and _implement_vibes_compound(term[cut:], words[1:])
               for cut in range(1, len(term)))


def implement_vibes_phrase_held(words, holders) -> bool:
    for whole, attribute in holders or ():
        for start in range(len(words) - 1, -1, -1):
            covered = (_implement_vibes_known(words[-1], attribute) if start == len(words) - 1
                       else any(_implement_vibes_compound(term, words[start:]) for term in attribute))
            if covered and all(_implement_vibes_known(w, whole) for w in words[:start]):
                return True
    return False


def _implement_vibes_phrases(ask, pattern, listed: bool = False) -> list:
    text = IMPLEMENT_VIBES_QUOTED_RE.sub(" ", str((ask or {}).get("ask") or ""))
    phrases = []
    for found in pattern.finditer(text):
        for piece in IMPLEMENT_VIBES_LIST_SPLIT_RE.split(found.group(1)) if listed else [found.group(1)]:
            words, stopped = [], False
            for word in piece.split():
                plain = word.lower().strip("'’-")
                owner = re.search(r"['’]s$", plain) is not None
                plain = re.sub(r"['’]s$", "", plain)
                if not words and plain in IMPLEMENT_VIBES_PHRASE_LEADS:
                    continue
                if plain in IMPLEMENT_VIBES_PHRASE_STOPS or plain.endswith("est"):
                    stopped = True
                    break
                if owner and not listed:
                    words = []
                    continue
                words.append(plain)
                if len(words) == IMPLEMENT_VIBES_PHRASE_WORDS:
                    break
            if words:
                phrases.append(" ".join(words))
            if stopped:
                break
    return list(dict.fromkeys(phrases))


def implement_vibes_groupings(ask) -> list:
    return _implement_vibes_phrases(ask, IMPLEMENT_VIBES_GROUPING_RE)


def implement_vibes_measures(ask) -> list:
    return _implement_vibes_phrases(ask, IMPLEMENT_VIBES_MEASURE_RE)


def implement_vibes_attributes(ask) -> list:
    parts = set(IMPLEMENT_VIBES_NAME_KINDS) | IMPLEMENT_VIBES_GENERIC_WORDS
    return [phrase for phrase in _implement_vibes_phrases(ask, IMPLEMENT_VIBES_ATTRIBUTE_RE, listed=True)
            if not {_implement_vibes_token(w) for w in phrase.split()} & parts]


def _implement_vibes_abbreviates(short: str, term: str) -> bool:
    letters = iter(term)
    return (3 <= len(short) < len(term) and short[0] == term[0] and sum(c in "aeiou" for c in short[1:]) <= 1
            and all(c in letters for c in short))


def _implement_vibes_known(term: str, vocabulary) -> bool:
    least = max(4, (len(term) + 1) // 2)
    return term in vocabulary or any(
        (len(word) >= 4 and (word.startswith(term) or term.startswith(word) or (len(term) >= 4 and term in word)
                             or len(os.path.commonprefix([term, word])) >= least))
        or _implement_vibes_abbreviates(word, term) or _implement_vibes_abbreviates(word[:4], term)
        for word in vocabulary)


def implement_vibes_checkable(ask) -> list:
    if not isinstance(ask, dict) or ask.get("keep") or ask.get("unsplit"):
        return []
    text = str(ask.get("ask") or "")
    if _IMPLEMENT_VIBES_TAKES_OUT_RE.match(text) or implement_vibe_undoes(text):
        return []
    kinds = {check.get("kind") for check in implement_vibes_checks_of(ask)}
    if ask.get("draws") not in IMPLEMENT_VIBES_DRAWS and not kinds & IMPLEMENT_VIBES_GROUPING_KINDS:
        return []
    phrases = implement_vibes_measures(ask)
    phrases += [g for g in implement_vibes_groupings(ask) if g not in phrases]
    if ask.get("draws") == "table" or "column" in kinds:
        phrases += [a for a in implement_vibes_attributes(ask) if a not in phrases]
    return [phrase for phrase in phrases if (_implement_vibes_subject_terms(phrase) or len(implement_vibes_phrase_words(phrase)) > 1)
            and not set(re.split(r"[^a-z0-9]+", phrase)) & IMPLEMENT_VIBES_DERIVED_WORDS]


def implement_vibes_unfound(ask, vocabulary, holders=()) -> list:
    if not vocabulary:
        return []
    missing = []
    for phrase in implement_vibes_checkable(ask):
        words = implement_vibes_phrase_words(phrase)
        if holders and len(words) > 1:
            if not implement_vibes_phrase_held(words, holders):
                missing.append(" ".join(implement_vibes_phrase_words(phrase, shown=True)))
            continue
        terms = _implement_vibes_subject_terms(phrase)
        if terms and not any(_implement_vibes_known(t, vocabulary) for t in terms):
            named = phrase.split()
            while len(named) > 1 and named[0] in IMPLEMENT_MEASURE_GENERIC_WORDS:
                named = named[1:]
            missing.append(" ".join(named))
    return missing


def implement_vibes_unfound_text(missing, tables) -> str:
    listed = list(tables or ())
    shown = ", ".join(listed[:IMPLEMENT_VIBES_TABLES_SHOWN]) + (f" and {len(listed) - IMPLEMENT_VIBES_TABLES_SHOWN} more"
                                                                if len(listed) > IMPLEMENT_VIBES_TABLES_SHOWN else "")
    return (f"{IMPLEMENT_VIBES_NO_DATA}no column of the tables this use case reads holds {' or '.join(missing)}; Inspire checked the "
            f"column names and descriptions of {shown}")[:500]


def _implement_identifier_terms(name: str) -> set:
    return {_implement_vibes_token(w) for w in re.split(r"[^a-z0-9]+", re.sub(r"([a-z])([A-Z])", r"\1_\2", name).lower()) if w}


def implement_invented_measures(code, absent) -> list:
    if not absent or not isinstance(code, str):
        return []
    wanted, found = set(absent), []
    for line in code.splitlines():
        text = " ".join(line.split())
        if not text or text.startswith(("#", "--")) or not re.search(r"(?<![=!<>])=(?!=)|\bAS\s+`?\w|withColumn\(|\.alias\(", text, re.I):
            continue
        names = [n for n in dict.fromkeys(re.findall(r"[A-Za-z_]\w*", text)) if _implement_identifier_terms(n) & wanted]
        constants = [n for n in names if n.isupper() and "_" in n]
        literal = [v for v in re.findall(r"(?<![\w.])\d+(?:\.\d+)?(?![\w.])", text) if float(v) not in (0.0, 1.0)]
        if names and (constants or literal):
            found.append({"name": names[0], "line": text[:200], "terms": sorted(_implement_identifier_terms(names[0]) & wanted)})
    return found


def implement_invented_text(invented) -> str:
    return "; ".join(f"{item['name']} ({item['line']})" for item in invented or [])


def implement_vibes_round_prompt(parts) -> str:
    many, notebook = len(parts) > 1, [part["asset"] == IMPLEMENT_NOTEBOOK for part in parts]
    code = ("" if all(notebook) else " Queries, SQL and code are never shown to a person, so they never count"
            + (", except in the notebook, whose cells are what a person reads there." if any(notebook) else "."))
    lines = [f"You check whether {'built parts' if many else 'a built part'} of a use case {'do' if many else 'does'} what the customer "
             "asked, ask by ask. The customer's asks are explicit user directives, so judge each one as the customer wrote it, never "
             "against a rule or default of your own."]
    numbered, reported, compared = [], [], False
    for index, part in enumerate(parts, 1):
        name, prefix = (f"Part {index}", f"(part {index}) ") if many else ("The part", "")
        lines += ["", f"{name}: {implement_asset_label(part['asset'], part.get('impact'))} "
                      f"({implement_asset_scope(part['asset'], part.get('impact'))}).",
                  IMPLEMENT_VIBES_UNBUILT.format(name=name.lower()) if part.get("unbuilt") else
                  f"What a person sees in {name.lower()} as Inspire built it now, by element id:\n<<<\n"
                  f"{implement_vibes_seen_text(part['seen'])[:IMPLEMENT_VIBES_ARTIFACT_CHARS]}\n>>>"]
        if part.get("sources"):
            lines.append(f"The source data this use case reads, by table and its columns:\n<<<\n"
                         f"{implement_vibes_sources_text(part['sources'])[:IMPLEMENT_VIBES_SOURCE_CHARS]}\n>>>")
        if any((part.get("described") or {}).values()):
            lines.append("How those tables and their columns are described:\n<<<\n"
                         + "\n".join(f"{t}: {'; '.join(n)}" for t, n in part["described"].items() if n)[:IMPLEMENT_VIBES_SOURCE_CHARS]
                         + "\n>>>")
        if part.get("earlier") is not None:
            compared = True
            lines.append(f"What a person saw in it in the version before, by element id:\n<<<\n"
                         f"{implement_vibes_seen_text(part['earlier'])[:IMPLEMENT_VIBES_ARTIFACT_CHARS]}\n>>>")
        numbered += [prefix + ask["ask"] + (" [asks to keep it as it is]" if ask.get("keep") else "")
                     + (" [asked in an earlier version]" if ask.get("asked_before") and not ask.get("keep") else "")
                     + (f" [names {ask['where']}]" if ask.get("where") else "") for ask in part["asks"]]
        reported += [f"- {prefix}{line}" for line in part.get("reported") or ()]
    lines += ["", "The asks:", implement_numbered_asks(numbered).rstrip()]
    if reported:
        lines += ["", "The builder said it could not do these asks:", *reported]
    lines += ["", "For each ask, \"done\" only when the part as built now shows it to a person: \"evidence\" copied character for "
              "character from one line above, without the \"- \" that starts it, and \"where\" the id of the element that line is "
              "under." + code,
              *(["An ask to change or add something is done only by words this version shows that the version before did not; an "
                 "ask to keep something, or one asked in an earlier version, is done when it is still shown."] if compared else []),
              *([IMPLEMENT_VIBES_KEEP_REST] if any(implement_vibes_keeps_rest(a) for part in parts for a in part["asks"]) else []),
              "When an ask names an element (a table, chart, page or filter), it is done only on that element: something added to "
              "another element, for example to the page filter bar when the ask names a table, leaves it missing.",
              "An ask for a chart, a table, a number or any value from the data is done only by a chart, table or KPI that draws "
              "from the data: the words of a text or html block are written by hand and draw no data, and a filter's label shows no "
              "value, so they never make such an ask done. An ask about all or every column, chart or table is done only when each "
              "one shows it.",
              "The person is an expert and a rule or default of Inspire never makes an ask wrong to want, so the verdict is \"done\" "
              "or \"missing\", or \"no_data\" only when the ask needs a real-world quantity that no table or column of the source "
              "data holds: a value made up from other columns or fixed numbers is never that quantity, so it never makes the ask "
              "done. For \"no_data\", \"evidence\" says in one plain sentence which data is missing and what data would make the ask "
              "possible.",
              "Otherwise \"missing\", with \"evidence\" one plain sentence on what the part lacks, or the reason the builder gave, "
              "and \"where\" \"\".",
              'Reply with one JSON object and nothing else: {"checks": [{"n": 1, "status": "done", "evidence": "...", '
              '"where": "<element id>"}]}']
    return "\n".join(lines)


def implement_vibes_every_kept(noun: str, seen: dict, earlier, label: str) -> tuple:
    if earlier is None:
        return "missing", f"the ask keeps every {noun}, and Inspire has no version before to compare each {noun} with"
    kind = IMPLEMENT_VIBES_QUANTIFIED_KINDS[noun]
    if noun == "column":
        listed = lambda found: {f"{e['name']}: {shown}" for e in found.values() if e.get("kind") == kind
                                for holder in _implement_vibes_column_holders(e["node"]) for _c, shown in _implement_vibes_holder_columns(holder)}
    else:
        listed = lambda found: ({line for e in found.values() if e.get("kind") == kind for line in e["lines"]} if kind == "filter"
                                else {e["name"] for e in found.values() if e.get("kind") == kind})
    before, now = listed(earlier), listed(seen)
    gone = sorted(before - now)
    if gone:
        return "missing", f"the ask keeps every {noun}, and the built {label} no longer shows " + "; ".join(gone)[:400]
    return "done", (f"{'the one ' + noun if len(before) == 1 else 'each of the ' + inspire_plural(len(before), noun)} "
                    f"of the version before is still on the built {label}: "
                    + "; ".join(sorted(before)))[:500]


def implement_vibes_placed(ask: dict, evidence: str, where: str, seen: dict, earlier, label: str) -> tuple:
    quoted = _implement_vibes_quoted(evidence)
    holders = [key for key, element in seen.items() if quoted and quoted.lower() in _implement_vibes_shows(element)]
    if not holders:
        return "missing", (f"the check gave no words of the built {label} that show this ask"
                           + (f" (it quoted '{quoted[:200]}', which the built {label} does not hold)" if quoted else ""))
    place = implement_vibes_element(seen, where) if where else ""
    if where and not place:
        return "missing", f"the check placed it on {where[:200]}, which the built {label} does not have"
    if place and place not in holders:
        return "missing", f"the check quoted '{quoted[:200]}', which the {seen[place]['name']} does not show"
    named, problem = implement_vibes_scope(seen, ask, label, drawn=False)
    allowed, drawn_problem = implement_vibes_scope(seen, ask, label) if not problem else (None, "")
    if problem or drawn_problem:
        return "missing", problem or drawn_problem
    if not place:
        pool = [key for key in holders if allowed is None or key in allowed] or holders
        fresh = [key for key in pool if not ((earlier or {}).get(key) and quoted.lower() in _implement_vibes_shows(earlier[key]))]
        place = (fresh or pool)[0]
    if named is not None and place not in named:
        return "missing", f"it was added to the {seen[place]['name']}, not to the {implement_vibes_scope_name(seen, named)}"
    if allowed is not None and place not in allowed:
        return "missing", (f"the check quoted '{quoted[:200]}' from the {seen[place]['name']}, which draws nothing from the data, so "
                           f"it is not the {IMPLEMENT_VIBES_DRAWS_WORDS[implement_vibes_draws(ask)]} the ask asks for")
    noun, before = implement_vibes_quantified(ask), (earlier or {}).get(place)
    if not ask.get("keep") and before and quoted.lower() in _implement_vibes_shows(before):
        if not ask.get("asked_before"):
            return "missing", (f"the check quoted '{quoted[:200]}', which the version before already showed, so nothing shows this ask "
                               "was met")
        if not noun:
            return "done", implement_vibes_already(f"{IMPLEMENT_VIBES_CARRIED}{quoted}")
    if noun:
        return implement_vibes_every_kept(noun, seen, earlier, label) if ask.get("keep") else (
            "missing", f"the ask asks this of every {noun}, and the check quoted one line, which shows one; Inspire proves an ask "
                       f"about every {noun} only with a check on each {noun}")
    return "done", quoted[:500]


def implement_vibes_answers(parsed) -> dict:
    answers = {}
    for item in (parsed or {}).get("checks") or [] if isinstance(parsed, dict) else []:
        number = int(item["n"]) if isinstance(item, dict) and str(item.get("n")).isdigit() else None
        status = str(item.get("status") or "").lower() if number else ""
        evidence = " ".join(str(item.get("evidence") or "").split()) if number else ""
        if number and number not in answers and status in IMPLEMENT_VIBES_STATUSES and evidence:
            answers[number] = {"n": number, "status": status, "evidence": evidence, "where": " ".join(str(item.get("where") or "").split())}
    return answers


def implement_vibes_judged(parsed, asks: list, seen: dict, label: str, earlier=None, numbers=None, held=frozenset(),
                           holders=()) -> dict:
    numbers, found = list(numbers or range(1, len(asks) + 1)), {}
    asked, answers = dict(zip(numbers, asks)), implement_vibes_answers(parsed)
    for number in numbers:
        item = answers.get(number)
        if item is None:
            continue
        status, evidence = item["status"], item["evidence"]
        if status == "done":
            found[number] = implement_vibes_placed(asked[number], evidence, item["where"], seen, earlier, label)
        elif status == "no_data":
            found[number] = ("missing", ((IMPLEMENT_VIBES_NO_DATA if implement_vibes_absent_terms(asked[number], held, holders) else "")
                                         + evidence)[:500])
        else:
            found[number] = (status, evidence[:500])
    return {n: found.get(n, ("missing", IMPLEMENT_VIBES_NO_ANSWER)) for n in numbers}


def implement_vibes_said(ask: str, reported) -> str:
    lead = f"{ask}:".lower()
    return next((str(line)[len(lead):].strip() for line in reported or () if str(line).lower().startswith(lead)), "")


def implement_vibes_seed(asset_status) -> dict:
    seed = {}
    for asset, entry in (asset_status or {}).items():
        split = entry.get("vibes_split") if isinstance(entry, dict) else None
        if (isinstance(split, dict) and isinstance(split.get("text"), str) and isinstance(split.get("asks"), list)
                and not any(isinstance(a, dict) and a.get("unsplit") for a in split["asks"])):
            try:
                asks = implement_vibes_asks({"asks": split["asks"]})
            except ValueError:
                continue
            marked = all(isinstance(a, dict) and isinstance(a.get("keep"), bool) for a in split["asks"])
            seed[(asset, split["text"])] = asks if marked else [dict(a, keep=None) for a in asks]
    return seed


def implement_rounds_note(text, rounds: int = 0, what: str = "do it") -> str:
    if not rounds or str(text).startswith((IMPLEMENT_VIBES_UNCHECKED, IMPLEMENT_VIBES_NO_DATA)):
        return str(text)
    return f"Genie could not {what} in {inspire_plural(rounds, 'build round')}: {text}"


_IMPLEMENT_PLAIN_NO_COLUMN_RE = re.compile(r"^the built (?P<label>.+?) names no column (?P<value>.+?)\.?$")
_IMPLEMENT_PLAIN_NO_BLOCK_RE = re.compile(r"^no block on the built (?P<label>.+?) is (?P<want>kind .+?)(?:; its blocks are .*)?\.?$")
_IMPLEMENT_PLAIN_BLOCK_NOUNS = {"text": "note", "html": "formatted note", "image": "picture"}


def implement_plain_reason(text) -> str:
    """RC6-D-02: the reason a person reads for an unmet ask. The check keeps its exact text for Genie; two internal forms (a column the
    built part never names, a block that is not where it was asked) become one plain sentence with no field names."""
    text = str(text or "")
    found = _IMPLEMENT_PLAIN_NO_COLUMN_RE.match(text)
    if found:
        return f"The built {found['label']} does not show a {_implement_vibes_column_words(found['value'])} column."
    found = _IMPLEMENT_PLAIN_NO_BLOCK_RE.match(text)
    if found:
        asked = dict(part.strip().split(" ", 1) for part in found["want"].split(", ") if " " in part.strip())
        noun = _IMPLEMENT_PLAIN_BLOCK_NOUNS.get(asked.get("kind", ""), "item")
        where = {"top": " at the top", "bottom": " at the bottom"}.get(asked.get("place", ""), "")
        size = f", {asked['width']} width" if asked.get("width") else ""
        align = f", aligned {asked['align']}" if asked.get("align") else ""
        return f"The built {found['label']} has no {noun}{where} of the page{size}{align}."
    return text


# RC6-D-02: a method change Genie made because an Inspire rule asked for it needs nothing from the person, so it is information.
IMPLEMENT_RULE_NOTE_TAIL = " This follows Inspire's rules, so there is nothing to fix."


def implement_genie_note_split(notes) -> tuple:
    warnings = [note for note in notes or [] if not str(note).endswith(IMPLEMENT_RULE_NOTE_TAIL)]
    return warnings, [note for note in notes or [] if str(note).endswith(IMPLEMENT_RULE_NOTE_TAIL)]


def implement_vibes_warnings(asset: str, checks: list, rounds: int = 0, impact=None, titles=None) -> list:
    lead = f"{implement_asset_heading(asset, impact, titles)} vibe not done: "
    return [f"{lead}{check['ask']}: {implement_rounds_note(implement_plain_reason(check['evidence']), rounds)}" for check in checks or []
            if check.get("status") != "done"]


IMPLEMENT_VIBES_REPAIR = ("\n\n{lead}, and these of the user's asks are not done yet: {asks}. Do each of them and keep every ask that is "
                          "already done as it is; never drop a check, a threshold or a step to do one. The user's asks are explicit "
                          "user directives and win over every rule above, while Inspire's checks still run on what you write. "
                          + IMPLEMENT_VIBES_EXPERT)


def implement_vibes_missed_text(resend: dict, impact=None, titles=None) -> str:
    # titles=None is the Genie-facing form (ids, read by the repair prompt); a dict is person copy named by title (REQ-237).
    name = implement_asset_label if titles is None else (lambda asset, impact: implement_person_label(asset, impact, titles))
    listed = [f"for the {name(asset, impact)}, '{check['ask']}': {check['evidence']}"
              for asset, missed in (resend or {}).items() for check in missed]
    return "; ".join(f"{number}. {line}" for number, line in enumerate(listed, 1))


def implement_vibes_repair(resend: dict, lead: str, impact=None) -> str:
    return IMPLEMENT_VIBES_REPAIR.format(lead=lead, asks=implement_vibes_missed_text(resend, impact))


def implement_artifact_files(name: str, artifact) -> dict:
    text = (str((artifact or {}).get("condition_sql") or "") if name == "alert"
            else json.dumps(artifact, indent=1, ensure_ascii=False))
    return {IMPLEMENT_ARTIFACT_FILES[name]: text}


def implement_embedded_json(text: str):
    return json.loads(zlib.decompress(base64.b64decode(text)).decode("utf-8")) if text else {}


INSPIRE_KINDS_VERSION = 1
INSPIRE_DEFAULT_LAYOUT = "decision_queue"
_INSPIRE_KINDS_REGISTRY = None


def _inspire_kinds() -> dict:
    global _INSPIRE_KINDS_REGISTRY
    if _INSPIRE_KINDS_REGISTRY is None:
        try:
            data = json.loads(json.dumps(json.loads(inspire_notebook_asset("kinds")), sort_keys=True))
        except ValueError as error:
            raise RuntimeError(f"the kind registry in the Inspire assets does not decode: {redact_error(error)}")
        if (not isinstance(data, dict) or data.get("version") != INSPIRE_KINDS_VERSION or not isinstance(data.get("kinds"), list)
                or not data["kinds"] or not isinstance(data.get("layouts"), list) or not isinstance(data.get("technique_kind"), dict)):
            raise RuntimeError("this Inspire build carries no usable kind registry; write it with `python3 agent/app_shell/embed.py write`")
        _INSPIRE_KINDS_REGISTRY = data
    return _INSPIRE_KINDS_REGISTRY


INSPIRE_TECHNIQUE_RECORDS_LOADER = INSPIRE_TECHNIQUE_RECORDS_LOADER or (lambda: _inspire_kinds()["technique_records"])


def _inspire_kind(kind_id):
    return next((kind for kind in _inspire_kinds()["kinds"] if kind["id"] == kind_id), None)


def _inspire_layout(layout_id):
    return next((layout for layout in _inspire_kinds()["layouts"] if layout["id"] == layout_id), None)


def _inspire_kind_for_technique(technique):
    mapping = _inspire_kinds()["technique_kind"]
    key = _technique_registry_key(technique, mapping)
    return _inspire_kind(mapping[key]) if key is not None else None


def _inspire_resolve_kind(value, technique=None):
    key = _inspire_kind_key(value).strip("`'\"* ")
    for name in (key, re.sub(r"^\d+\s*[.:)]?\s*", "", key)) if key else ():
        for kind in _inspire_kinds()["kinds"]:
            if name and name in {_inspire_kind_key(kind.get(field)) for field in ("id", "label", "num")}:
                return kind["id"]
    kind = _inspire_kind_for_technique(technique) if technique is not None else None
    return kind["id"] if kind else None


def implement_kinds_text(files: dict) -> str:
    return files.get(IMPLEMENT_APP_KINDS_FILE) or json.dumps(_inspire_kinds(), indent=1, ensure_ascii=False) + "\n"


INSPIRE_COMPANION_MEANINGS = {
    "__transitions": ("one row per move from a step to the next: cases = cases that made it, median_hours and p90_hours = hours "
                      "between the two steps, rework = cases among them that went back to a step they had left"),
    "__cases": "one row per open case at the step it waits in: age_hours = hours in that step, breach_risk = 0 to 1 chance it misses its target time",
    "__geo": ("one row per entity: lat and lon in decimal degrees, region_code = ISO 3166-1 alpha-2 country code when the data holds "
              "countries, else its own area code, metric = the measure the map shows"),
    "__nodes": "one row per node: label to show, community = its group, centrality = 0 to 1 weight in the network, metric = the measure ranked",
    "__edges": "one row per link: src and dst = node values of the nodes table, weight = how strong the link is",
    "__plan": ("one row per plan line: entity = the entity_id of that line's row in the result table, so people can accept or "
               "override each line in the App; delta = recommended_value minus current_value"),
    "__constraints": ("one row per limit the plan obeys: limit = its bound, used = how much of it the plan uses, slack = limit minus "
                      "used, shadow_price = the gain one more unit of the limit would bring"),
    "__series": ("one row per series per period, over every period the run reads before the as-of date and every forecast period after "
                 "it: actual is NULL and is_future true on a forecast period, lower and upper bound the forecast, backtest_mase = the "
                 "series' backtest error against a naive forecast"),
    "__scenarios": ("one row per scenario: lever_values = a JSON map of each lever of the scenario model to its value in the scenario, "
                    "outcome = the outcome it gives, with p10, p50 and p90 its range, prob_target = 0 to 1 chance of reaching the target"),
    "__sensitivity": "one row per lever: low and high = the outcome at the lever's low and high value, delta = high minus low",
    "__scenario_model": ("one row per driver of the outcome model, named as in lever_values: coefficient = how much the outcome moves "
                         "per unit of that driver"),
    "__segments": ("one row per segment: label to show, size = its members, value = the measure the segments are ranked by, profile = "
                   "a short text of what sets it apart"),
    "__assign": ("one row per member: entity = its entity_id in the result table, segment = the segment_id it belongs to, x and y = "
                 "its place in a 2D projection of the members"),
    "__migration": ("one row per pair of segments: count = the members that moved from from_segment to to_segment since the previous "
                    "assignment"),
    "__recs": ("one row per entity and recommended item: entity = its entity_id in the result table, rank = 1 for its best item, score "
               "= the method's score, reason = why, in one short sentence"),
    "__variance": ("one row per unit per period, over every period the run reads before the as-of date, the history before the scored "
                   "window included: variance = actual minus plan, tolerance = the variance the use case accepts"),
    "__bridge": ("one row per step of the walk, in the order of step from 1: the first row holds the starting total, such as the plan, "
                 "the last row the ending total, such as the actual, and each row between what one driver adds or takes away, with "
                 "step_type 'driver'"),
    "__peers": ("one row per unit and metric: peer_group = the peers it is compared with, peer_median = their median, gap = the unit's "
                "value minus that median"),
    "__effect": ("one row per intervention and metric: effect = the estimated lift, which lower and upper bound, p_value = its test, "
                 "incremental_value = the value of the lift, cost = what the intervention cost, roi = incremental_value over cost"),
    "__effect_series": ("one row per period, over every period the run reads before the as-of date, the periods before the "
                        "intervention included: actual against the counterfactual without the intervention, which lower and upper "
                        "bound"),
    "__signal": ("one row per series per period, over every period the run reads before the as-of date, the history before the scored "
                 "window included: series = what the signal is measured for, such as a check, an account or a site, value = its "
                 "measured level, expected = the level the other periods expect, lower and upper = the band a normal value falls in, "
                 "is_anomaly = value outside that band, rule = the check or rule behind it"),
    "__score_bins": "one row per score bin of the run's rows: count = the rows in the bin, cutoff = the score at the bin's lower edge",
    "__lift": ("one row per decile of the run's rows ranked by score, best first: captured_share = 0 to 1 share of the outcome caught "
               "down to that decile, cost_at_cutoff = what acting on the rows down to it costs"),
}
GENIE_COMPANION_RULE = ("Companion tables, which the use case's App page draws next to the decision list: after inspire_write_result, "
                        "write each one below with `inspire_write_companion(frame, result_table, suffix, columns)`, which the Run "
                        "controls cell defines and which refuses a frame that misses a listed column or holds no rows. Pass the "
                        "`result_table` widget value, the suffix and the listed columns, keep extra columns the page filters by, such "
                        "as the segment columns, and print the rows it returns. Only an explicit user directive, such as the user's "
                        "Implementation Choices, wins over this rule.")


INSPIRE_COMPANION_DATA_NEEDS = {"__geo": "geo", "__nodes": "links", "__edges": "links", "__transitions": "steps",
                                "__cases": "steps", "__series": "dates", "__effect_series": "dates", "__variance": "dates",
                                "__signal": "dates", "__scenarios": "levers", "__sensitivity": "levers", "__scenario_model": "levers"}
INSPIRE_COMPANION_PERIOD_SUFFIXES = frozenset(suffix for suffix, need in INSPIRE_COMPANION_DATA_NEEDS.items() if need == "dates")
INSPIRE_COMPANION_SKIP_TEXT = "The {suffix} table cannot be filled from this data: "
_INSPIRE_COMPANION_SKIP_RE = re.compile(re.escape(INSPIRE_COMPANION_SKIP_TEXT).replace(r"\{suffix\}", r"(__[a-z][a-z_]{0,40})")
                                        + r"(.+)")
INSPIRE_COMPANION_DATA_TEXT = {
    "geo": "a geographic column, such as a latitude and a longitude, a postal code or a city",
    "links": "two key columns that link one entity to another",
    "steps": "a step or status column and a date",
    "dates": "a date or timestamp column",
}
INSPIRE_SCENARIO_PAGE_LEVERS = 2


def inspire_scenario_measures_needed() -> int:
    return max(int(TECHNICAL_CONTEXT["runtime"]["signal_min_levers"]), INSPIRE_SCENARIO_PAGE_LEVERS) + 1


def inspire_companion_data_text(need: str) -> str:
    if need != "levers":
        return INSPIRE_COMPANION_DATA_TEXT[need]
    needed = inspire_scenario_measures_needed()
    return f"{needed} numeric measure columns, {needed - 1} levers to change and an outcome they move"


def inspire_kind_companions(use_case) -> dict:
    kind = inspire_use_case_kind(use_case if isinstance(use_case, dict) else {}) or {}
    suffixes = ((_inspire_kinds().get("contracts") or {}).get(kind.get("contract")) or {}).get("suffixes") or {}
    return {str(suffix): [str(c) for c in columns] for suffix, columns in suffixes.items()}


def inspire_companion_line(result_table: str, suffix: str, columns) -> str:
    return (f"{inspire_shell_facts.companion(result_table, suffix)}: {', '.join(columns)}"
            + (f"; {INSPIRE_COMPANION_MEANINGS[suffix]}" if suffix in INSPIRE_COMPANION_MEANINGS else ""))


def inspire_companion_skips(text) -> dict:
    return {match.group(1): " ".join(match.group(2).split()) for match in _INSPIRE_COMPANION_SKIP_RE.finditer(str(text or ""))}


def genie_companion_lines(spec: dict) -> list:
    companions = spec.get("companions") or {}
    if not companions:
        return []
    return [GENIE_COMPANION_RULE] + [f"* {inspire_companion_line(spec['result_table'], suffix, columns)}"
                                     for suffix, columns in companions.items()]


INSPIRE_KIND_QUEUE_CONTRACT = "decision_queue"
INSPIRE_KIND_DECISION_SOURCE = "decision"
INSPIRE_KIND_SQL_WORDS = frozenset({"and", "as", "between", "case", "distinct", "else", "end", "false", "in", "is", "like", "not", "null",
                                    "or", "then", "true", "when"})
_INSPIRE_KIND_WORD_RE = re.compile(r"\b([A-Za-z_][A-Za-z0-9_]*)\b(?!\s*\()")
_INSPIRE_KIND_QUOTED_RE = re.compile(r"'(?:[^'\\]|\\.)*'")
_INSPIRE_KIND_TABLE_RE = re.compile(r"\{result_table\}(__[a-z_]+)?")


def implement_kind_layout(use_case: dict) -> tuple:
    uc = use_case or {}
    kind = inspire_use_case_kind(uc)
    named = str(uc.get("app_layout") or "").strip()
    known = {layout["id"] for layout in _inspire_kinds()["layouts"]}
    return kind, named if named in known else str((kind or {}).get("layout") or "")


def implement_kind_suffixes() -> set:
    return {suffix for contract in _inspire_kinds()["contracts"].values() for suffix in contract["suffixes"]}


def implement_kind_companion_tables(use_case: dict) -> dict:
    result_table = str((use_case or {}).get("result_table") or "").strip()
    kind = inspire_use_case_kind(use_case if isinstance(use_case, dict) else {}) or {}
    if not result_table or kind.get("contract") in (None, INSPIRE_KIND_QUEUE_CONTRACT):
        return {}
    return {inspire_shell_facts.companion(result_table, suffix): columns for suffix, columns in inspire_kind_companions(use_case).items()}


def implement_kind_tags(use_case: dict) -> dict:
    kind, layout = implement_kind_layout(use_case)
    return {"dbx_inspire_ai_kind": kind["id"], "dbx_inspire_ai_layout": layout} if kind else {}


def implement_schema_once(read):
    seen = {}

    def once(table):
        key = str(table).lower()
        if key not in seen:
            try:
                seen[key] = read(table)
            except Exception as error:
                seen[key] = redact_error(error, table)[:300]
        return seen[key]

    return once


def implement_kind_spec(use_case: dict, result_table: str, read):
    kind, _layout = implement_kind_layout(use_case)
    contract = (kind or {}).get("contract")
    if not kind or contract in (None, INSPIRE_KIND_QUEUE_CONTRACT) or not str(result_table or "").strip():
        return None
    layout = kind.get("decision_layout") or kind["layout"]
    label = (_inspire_layout(layout) or {}).get("label") or layout
    companions = {inspire_shell_facts.companion(result_table, suffix): (suffix, columns) for suffix, columns in inspire_kind_companions(use_case).items()}
    schemas = {table: read(table) for table in companions}
    missing = implement_layout_missing({table: columns for table, (_suffix, columns) in companions.items()}, schemas)
    tables = {}
    for table, (suffix, columns) in companions.items():
        if table not in missing:
            have = {str(name).lower(): str(data_type).lower() for name, data_type in schemas[table]}
            tables[suffix] = {"table": table, "columns": {column: have[column.lower()] for column in columns}}
    return {"kind": kind, "layout": layout, "label": label, "result_table": result_table, "tables": tables, "missing": missing}


def implement_kind_columns(expression) -> list:
    plain = _INSPIRE_KIND_QUOTED_RE.sub(" ", str(expression or ""))
    return list(dict.fromkeys(word for word in _INSPIRE_KIND_WORD_RE.findall(plain) if word.lower() not in INSPIRE_KIND_SQL_WORDS))


_INSPIRE_KIND_ROW_COUNT_RE = re.compile(r"\bcount\s*\(\s*(?:\*|1)\s*\)", re.I)


def implement_kind_row_count(expression: str, key: str) -> str:
    counted = _INSPIRE_KIND_ROW_COUNT_RE.sub(f"count({key})", str(expression or "")) if key else ""
    return counted if implement_kind_columns(counted) else ""


def implement_kind_measures(kind_spec: dict, aliases: dict) -> tuple:
    owners = [(info["table"], list(info["columns"])) for info in kind_spec["tables"].values()]
    owners.append((kind_spec["result_table"], [name for name, _type in INSPIRE_CORE_COLUMNS]))
    kept, dropped = [], []
    for expression in kind_spec["kind"]["genie"]["measures"]:
        columns = set(implement_kind_columns(expression))
        owner, have = next(((table, have) for table, have in owners if columns <= set(have) and (columns or have)), (None, []))
        alias = aliases.get(_implement_plain_table(owner).lower()) if owner else None
        name = re.sub(r"[^a-z0-9]+", "_", expression.lower()).strip("_")[:60]
        sql = expression if columns else implement_kind_row_count(expression, have[0] if have else "")
        if not alias or not sql or name in {m["alias"] for m in kept}:
            dropped += [] if alias and sql else [expression]
            continue
        kept.append({"alias": name, "display_name": f"{kind_spec['kind']['label']}: {expression}",
                     "sql": [implement_kind_bound(sql, alias)]})
    return kept, dropped


def implement_kind_bound(expression: str, alias: str) -> str:
    bound = lambda match: match.group(1) if match.group(1).lower() in INSPIRE_KIND_SQL_WORDS else f"`{alias}`.`{match.group(1)}`"
    parts = re.split(f"({_INSPIRE_KIND_QUOTED_RE.pattern})", str(expression))
    return "".join(part if index % 2 else _INSPIRE_KIND_WORD_RE.sub(bound, part) for index, part in enumerate(parts))


def implement_genie_kind_space(definition: dict, kind_spec: dict, allowed) -> tuple:
    data = json.loads(json.dumps(definition))
    raw = data.get("serialized_space")
    space = json.loads(raw) if isinstance(raw, str) else raw if isinstance(raw, dict) else data
    if isinstance(raw, str):
        data["serialized_space"] = space
    sources = space.setdefault("data_sources", {})
    tables = sources.setdefault("tables", []) if isinstance(sources, dict) else None
    added = []
    if isinstance(tables, list):
        listed = {_implement_plain_table(t.get("identifier")).lower() for t in tables if isinstance(t, dict)}
        for suffix, info in kind_spec["tables"].items():
            if info["table"].lower() not in listed:
                tables.append({"identifier": info["table"], "description": [
                    f"{kind_spec['label']}: the {suffix.strip('_')} rows the use case writes each run, with "
                    f"{', '.join(info['columns'])}"]})
                added.append(info["table"])
    genie_sorted_tables(space)
    measures, dropped = implement_kind_measures(kind_spec, implement_genie_aliases(list(allowed or ()) + added))
    instructions = space.setdefault("instructions", {})
    snippets = instructions.setdefault("sql_snippets", {}) if isinstance(instructions, dict) else None
    if isinstance(snippets, dict):
        current = [m for m in snippets.get("measures") or [] if isinstance(m, dict)]
        have = {str(m.get("alias") or "").lower() for m in current}
        measures = [m for m in measures if m["alias"] not in have]
        snippets["measures"] = current + measures
    else:
        measures = []
    return data, added, [m["alias"] for m in measures], dropped


def _implement_genie_word_stem(word: str) -> str:
    word = _IMPLEMENT_GENIE_ARABIC_ARTICLE.sub("", word)
    return word[:-1] if len(word) > 3 and word[-1] in "sx" else word


def _implement_genie_name_words(value) -> set:
    text = unicodedata.normalize("NFKD", _implement_genie_words(value).casefold())
    text = "".join(c for c in text if not unicodedata.combining(c)).translate(_IMPLEMENT_GENIE_ARABIC_FOLD)
    return {_implement_genie_word_stem(word) for word in re.findall(r"[^\W_]+", text)}


def implement_genie_kpi_page_words(page) -> dict:
    page = page if isinstance(page, dict) else {}
    kpis = [k for k in page.get("kpis") or [] if isinstance(k, dict)]
    stop = {_implement_genie_word_stem(w) for w in IMPLEMENT_GENIE_KPI_STOP_WORDS}
    labels = [_implement_genie_name_words(k.get("label")) for k in kpis]
    shared = {w for w in set().union(*labels) if sum(w in label for label in labels) > 1} if labels else set()
    records = page.get("records") if isinstance(page.get("records"), dict) else {}
    noun = _implement_genie_name_words(records.get("title")) | shared
    out = {}
    for kpi, label in zip(kpis, labels):
        filters = [f for f in page.get("filters") or [] if isinstance(f, dict) and kpi.get("dataset") in (f.get("columns") or {})]
        generic = noun | set().union(*[_implement_genie_name_words(f.get("label")) for f in filters]) | stop
        words = {w for w in label if len(w) > 2 or any(unicodedata.east_asian_width(c) == "W" for c in w)} - stop
        out[id(kpi)] = {"label": words, "key": (words - generic) or words}
    return out


def implement_genie_kpi_claimed(words: set, kpi: dict, page_words=None) -> str:
    known = (page_words or {}).get(id(kpi)) or implement_genie_kpi_page_words({"kpis": [kpi]})[id(kpi)]
    label, key = known["label"], known["key"]
    if not label:
        return ""
    if label <= words or (len(key) > 1 and key <= words):
        return "label"
    family = {_implement_genie_word_stem(w) for w in IMPLEMENT_GENIE_KPI_RECORD_WORDS}
    hits = len(key & words)
    if (label & family and words & family) or (hits > 1 and 2 * hits >= len(key)):
        return "records"
    return "near" if hits and 2 * hits >= len(key) else ""


def _implement_genie_sql_text(value) -> str:
    return "".join(str(line) for line in value) if isinstance(value, list) else str(value or "")


def implement_genie_kpi_claims(space, page) -> list:
    instructions = space.get("instructions") if isinstance(space, dict) else None
    kpis = [k for k in ((page or {}).get("kpis") or []) if isinstance(k, dict) and str(k.get("label") or "").strip()
            and str(k.get("expression") or "").strip()]
    if not isinstance(instructions, dict) or not kpis:
        return []

    page_words = implement_genie_kpi_page_words(page)
    rank = {"near": 1, "records": 2, "label": 3}

    def claimed(*values, near=False):
        found = {}
        for value in values:
            for kpi in kpis:
                how = implement_genie_kpi_claimed(_implement_genie_name_words(value), kpi, page_words)
                if how and (near or how != "near") and rank[how] > rank.get(found.get(id(kpi), (None, ""))[1], 0):
                    found[id(kpi)] = (kpi, how)
        return list(found.values())

    out = []
    snippets = instructions.get("sql_snippets") if isinstance(instructions.get("sql_snippets"), dict) else {}
    for kind in IMPLEMENT_GENIE_SNIPPET_KINDS:
        items = snippets.get(kind) if isinstance(snippets.get(kind), list) else []
        for item in (i for i in items if isinstance(i, dict)):
            synonyms = [(s, claimed(s, near=True)) for s in (item.get("synonyms") if isinstance(item.get("synonyms"), list) else [])]
            named = claimed(item.get("alias"), item.get("display_name"))
            if named or any(found for _s, found in synonyms):
                out.append({"kind": kind, "item": item, "named": named, "synonyms": synonyms})
    examples = instructions.get("example_question_sqls") if isinstance(instructions.get("example_question_sqls"), list) else []
    for example in (e for e in examples if isinstance(e, dict)):
        named = claimed(example.get("question"))
        if named:
            out.append({"kind": "example_question_sqls", "item": example, "named": named, "synonyms": []})
    return out


def _implement_genie_plain(node) -> str:
    from sqlglot import exp
    node = node.copy()
    for column in node.find_all(exp.Column):
        for part in ("table", "db", "catalog"):
            column.set(part, None)
    for ident in node.find_all(exp.Identifier):
        ident.set("this", str(ident.this).lower())
        ident.set("quoted", False)
    return " ".join(node.sql(dialect="databricks").split())


def _implement_genie_conditions(node) -> frozenset:
    import sqlglot
    from sqlglot import exp
    if node is None:
        return frozenset()
    flat = lambda n: list(n.unnest().flatten()) if isinstance(n.unnest(), exp.And) else [n.unnest()]
    current = {_implement_genie_plain(p) for p in flat(sqlglot.parse_one(INSPIRE_CURRENT_ROWS, read="databricks"))}
    current |= {_implement_genie_plain(sqlglot.parse_one("is_current = TRUE", read="databricks"))}
    return frozenset(p for p in (_implement_genie_plain(n) for n in flat(node)) if p not in current)


def _implement_genie_shape(tree) -> tuple:
    from sqlglot import exp
    empty = lambda n: (n is None or isinstance(n, exp.Null) or (isinstance(n, exp.Cast) and empty(n.this))
                       or (isinstance(n, exp.Literal) and not n.is_string and n.name in ("0", "0.0")))
    one = lambda n: isinstance(n, exp.Literal) and not n.is_string and n.name in ("1", "1.0")
    tree = tree.unnest()
    if isinstance(tree, exp.Count):
        distinct = isinstance(tree.this, exp.Distinct) and len(tree.this.expressions) == 1
        inner = tree.this.expressions[0] if distinct else tree.this
        if distinct and isinstance(inner, exp.If) and empty(inner.args.get("false")):
            return ("count", "1", _implement_genie_conditions(inner.this))
        if inner is None or isinstance(inner, exp.Star) or one(inner) or (
                distinct and isinstance(inner, exp.Column) and inner.name.lower() in (INSPIRE_HISTORY_NAMES[0], "entity_id")):
            return ("count", "1", frozenset())
    if isinstance(tree, exp.CountIf):
        return ("count", "1", _implement_genie_conditions(tree.this))
    if isinstance(tree, exp.Sum):
        inner, picked = tree.this.unnest(), None
        if isinstance(inner, exp.If) and empty(inner.args.get("false")):
            picked = (inner.this, inner.args.get("true"))
        elif isinstance(inner, exp.Case) and not inner.this and len(inner.args.get("ifs") or []) == 1 and empty(inner.args.get("default")):
            picked = (inner.args["ifs"][0].this, inner.args["ifs"][0].args.get("true"))
        if picked and one(picked[1]):
            return ("count", "1", _implement_genie_conditions(picked[0]))
        if picked:
            return ("sum", _implement_genie_plain(picked[1]), _implement_genie_conditions(picked[0]))
        return ("sum", _implement_genie_plain(inner), frozenset())
    return ("raw", _implement_genie_plain(tree), frozenset())


def implement_genie_measure_shape(sql, kind: str = "measures") -> tuple:
    import sqlglot
    try:
        tree = sqlglot.parse_one(str(sql or "").strip(), read="databricks")
    except sqlglot.errors.SqlglotError:
        tree = None
    if tree is None:
        return ("unread", " ".join(str(sql or "").split()), frozenset())
    if kind == "filters":
        return ("filter", "", _implement_genie_conditions(tree))
    return ("raw", _implement_genie_plain(tree), frozenset()) if kind == "expressions" else _implement_genie_shape(tree)


def implement_genie_kpi_fits(shape: tuple, kpi_shape: tuple, how: str) -> bool:
    if shape[0] == "filter" and kpi_shape[0] == "raw":
        return True
    if how == "label" and shape[0] != "filter":
        return tuple(shape[:2]) == tuple(kpi_shape[:2]) and shape[2] >= kpi_shape[2]
    return shape[0] in ("count", "sum", "filter") and kpi_shape[0] in ("count", "sum") and shape[2] >= kpi_shape[2]


def _implement_genie_example_counts(sql: str, kpi_shape: tuple, how: str) -> bool:
    import sqlglot
    from sqlglot import exp
    try:
        trees = [t for t in sqlglot.parse(str(sql or ""), read="databricks") if t is not None]
    except sqlglot.errors.SqlglotError:
        return False
    for tree in trees:
        narrowed = frozenset().union(*[_implement_genie_conditions(w.this) for w in tree.find_all(exp.Where)])
        for agg in tree.find_all(exp.Count, exp.CountIf, exp.Sum):
            kind, value, conditions = _implement_genie_shape(agg)
            if implement_genie_kpi_fits((kind, value, conditions | narrowed), kpi_shape, how):
                return True
    return False


def implement_genie_kpi_reads_result(page, kpi) -> bool:
    import sqlglot
    from sqlglot import exp
    result = _implement_plain_table((page or {}).get("result_table")).lower()
    sql = next((d.get("sql") for d in (page or {}).get("datasets") or [] if isinstance(d, dict) and d.get("name") == kpi.get("dataset")), "")
    try:
        tree = sqlglot.parse_one(str(sql or ""), read="databricks")
    except sqlglot.errors.SqlglotError:
        return False
    base = tree.find(exp.From) if tree is not None else None
    table = base.find(exp.Table) if base is not None else None
    return bool(result and table is not None and _implement_plain_table(".".join(p.name for p in table.parts)).lower() == result)


def _implement_genie_kpi_rewrite(kind: str, target: tuple, alias) -> str:
    if not alias or kind == "expressions" or target[0] not in ("count", "sum", "filter") or not target[2]:
        return ""
    allowed = {name for name, _type in INSPIRE_CORE_COLUMNS} | {INSPIRE_HISTORY_NAMES[0]}
    if not {c.lower() for c in implement_kind_columns(" ".join(sorted(target[2])) + " " + target[1])} <= allowed:
        return ""
    conditions = " AND ".join([INSPIRE_CURRENT_ROWS] + sorted(target[2]))
    sql = (conditions if target[0] == "filter" else f"COUNT_IF({conditions})" if target[0] == "count"
           else f"SUM(IF({conditions}, {target[1]}, 0D))")
    return implement_kind_bound(sql, alias)


def implement_genie_kpi_collisions(space, page) -> bool:
    claims = implement_genie_kpi_claims(space, page)
    if not claims:
        return False
    shapes = {id(k): implement_genie_measure_shape(k["expression"]) for k in page.get("kpis") or [] if isinstance(k, dict)}
    tables = [t.get("identifier") for t in ((space.get("data_sources") or {}).get("tables") or []) if isinstance(t, dict)]
    result = _implement_plain_table(page.get("result_table")).lower()
    alias = implement_genie_aliases(tables).get(result) if result else None
    instructions, dropped = space["instructions"], set()
    fired = lambda what, kpi, action: print(f"[GENIE-KPI-COLLISION FIRED] {what} kpi={kpi['label']!r} action={action}: its SQL "
                                            f"counts another population than the KPI", flush=True)
    judged = lambda found: [(kpi, how) for kpi, how in found if shapes[id(kpi)][0] in ("count", "sum")
                            or (how == "label" and shapes[id(kpi)][0] == "raw")]
    for claim in claims:
        kind, item, named = claim["kind"], claim["item"], judged(claim["named"])
        claim["synonyms"] = [(synonym, judged(found)) for synonym, found in claim["synonyms"]]
        if kind == "example_question_sqls" and not named:
            continue
        if kind == "example_question_sqls":
            sql = _implement_genie_sql_text(item.get("sql"))
            if not any(_implement_genie_example_counts(sql, shapes[id(kpi)], how) for kpi, how in named):
                dropped.add(id(item))
                fired(f"example={_implement_genie_words(item.get('question'))!r}", named[0][0], "dropped")
            continue
        what = f"{kind[:-1]}={str(item.get('alias') or item.get('display_name') or '')!r}"
        shape = implement_genie_measure_shape(_implement_genie_sql_text(item.get("sql")), kind)
        own = lambda kpi, how: kind != "expressions" and implement_genie_kpi_fits(shape, shapes[id(kpi)], how)
        if named and not any(own(kpi, how) for kpi, how in named):
            kpi, how = named[0]
            target = (shapes[id(kpi)] if how == "label" and kind == "measures"
                      else (shape[0], shape[1], shape[2] | shapes[id(kpi)][2]) if shapes[id(kpi)][0] in ("count", "sum") else ("raw",))
            rewritten = (_implement_genie_kpi_rewrite(kind, target, alias)
                         if len(named) == 1 and implement_genie_kpi_reads_result(page, kpi) else "")
            fired(what, kpi, "rewritten to the KPI's own records" if rewritten else "dropped")
            if not rewritten:
                dropped.add(id(item))
                continue
            item["sql"] = [rewritten]
            shape = implement_genie_measure_shape(rewritten, kind)
        wrong = [(synonym, found) for synonym, found in claim["synonyms"] if found and not any(own(kpi, how) for kpi, how in found)]
        if wrong:
            keep = [s for s in item.get("synonyms") or [] if s not in {synonym for synonym, _found in wrong}]
            if keep:
                item["synonyms"] = keep
            else:
                item.pop("synonyms", None)
            for synonym, found in wrong:
                fired(what, found[0][0], f"synonym {synonym!r} removed")
    snippets = instructions.get("sql_snippets") if isinstance(instructions.get("sql_snippets"), dict) else {}
    for kind in [k for k in IMPLEMENT_GENIE_SNIPPET_KINDS if isinstance(snippets.get(k), list)]:
        snippets[kind] = [i for i in snippets[kind] if id(i) not in dropped]
    if isinstance(instructions.get("example_question_sqls"), list):
        gone = [e for e in instructions["example_question_sqls"] if id(e) in dropped]
        instructions["example_question_sqls"] = [e for e in instructions["example_question_sqls"] if id(e) not in dropped]
        implement_genie_drop_unproven_samples(space, gone)
    return True


def implement_genie_drop_unproven_samples(space: dict, gone: list) -> None:
    questions = ["".join(e.get("question") or []) for e in gone if isinstance(e, dict)]
    if not questions:
        return
    config = space.setdefault("config", {})
    before = [q for q in config.get("sample_questions") or [] if isinstance(q, dict)]
    implement_drop_genie_questions(space, [{"question": q} for q in questions])
    kept = config.get("sample_questions") or []
    shown = {_implement_genie_fold("".join(q.get("question") or [])) for q in kept}
    spare = [e for e in (space.get("instructions") or {}).get("example_question_sqls") or []
             if _implement_genie_fold("".join(e.get("question") or [])) not in shown]
    for example in spare[:len(before) - len(kept)]:
        kept.append({"id": uuid.uuid4().hex, "question": ["".join(example.get("question") or [])]})
    config["sample_questions"] = kept
    for question in questions:
        print(f"[GENIE-KPI-COLLISION FIRED] example={question!r} action=sample question removed with its SQL", flush=True)


def implement_genie_kpi_block(uc_id: str, page, shell_sql=None, values=None) -> str:
    page = page if isinstance(page, dict) else {}
    plain = lambda text: re.sub(r"\n\s*\n", "\n", str(text or "").strip().rstrip(";").strip())
    datasets = {str(d.get("name")): plain(d.get("sql")) for d in page.get("datasets") or [] if isinstance(d, dict)}
    lines = []
    for kpi in page.get("kpis") or []:
        if not isinstance(kpi, dict):
            continue
        label = " ".join(str(kpi.get("label") or kpi.get("id") or "").split())
        expression, source = plain(kpi.get("expression")), datasets.get(str(kpi.get("dataset")), "")
        by = ""
        if expression and source and shell_sql is None:
            raise RuntimeError("a KPI's Genie query is the App's own query, so it needs the App shell, which is not loaded")
        if kpi.get("format") == "currency" and expression and source:
            expression, source, by = shell_sql.genie_money_query(page, kpi)
        elif source:
            source = shell_sql.future_source(page, str(kpi.get("dataset")), source)
        if not (label and expression and source):
            continue
        where = shell_sql.kpi_where(page, str(kpi.get("dataset")), values)
        templates = shell_sql.filter_templates(page, str(kpi.get("dataset")))
        filtered = [f"{' '.join(str(f.get('label') or f.get('id') or '').split())} ({f['columns'][kpi['dataset']]})"
                    for f in page.get("filters") or [] if isinstance(f, dict) and isinstance(f.get("columns"), dict)
                    and f["columns"].get(kpi["dataset"])]
        splits = list(dict.fromkeys(f["columns"][kpi["dataset"]] for f in page.get("filters") or [] if isinstance(f, dict)
                                    and f.get("type") not in IMPLEMENT_GENIE_RANGE_FILTERS and isinstance(f.get("columns"), dict)
                                    and f["columns"].get(kpi["dataset"])))
        select, group = (f"{by}, ", f" GROUP BY {by}") if by else ("", "")
        lines.append(f"- When asked for {label}, use exactly: SELECT {select}{expression} AS value FROM (\n{source}\n) AS d{where}{group}"
                     + (f"\n  The page narrows it with its filters on {', '.join(filtered)}." if filtered else "")
                     + (f"\n  A question that names values for a filter narrows the query the same way, adding: "
                        + "; ".join(f"{name}: {clause}" for name, clause in templates) + "." if templates else "")
                     + (f"\n  The query returns one row per currency; give each currency its own total, never amounts of different currencies added together." if by else "")
                     + (f"\n  Split it by {', '.join(f'`{c}`' for c in splits)} the way the page does, from this same query: SELECT "
                        f"d.`{splits[0]}`, {expression} AS value FROM (the query above) AS d GROUP BY d.`{splits[0]}`. A part's share "
                        f"is its value over this query's total. Take the split column from this query only, never by joining another "
                        f"table to it or to the result table, so the parts add up to the {label} the page shows." if splits else ""))
    if not lines:
        return ""
    result = _implement_plain_table(page.get("result_table"))
    if result:
        lines.append(f"- When asked how many records there are, count each record once: COUNT(DISTINCT {INSPIRE_HISTORY_NAMES[0]}) of "
                     f"the current rows of `{result}`, never COUNT(*) over a join. That counts every record the run scored; a question "
                     "about the records one of the KPIs above counts, such as the failed, flagged or queued ones, takes that KPI's "
                     "query, never this count.")
    return (IMPLEMENT_GENIE_KPI_HEAD.format(uc=uc_id) + ". These queries outrank any SQL expression, filter or example of this space "
            "that counts or sums the same records another way, and a question that names what a KPI counts in other words, such as "
            "exceptions, breaks or failures for a count of failing records, takes that KPI's query. Answer a question about one of these "
            "KPIs with its query as written, never with a count or a sum of every row:\n" + "\n".join(lines))


def implement_genie_default_values(spark, page, shell_sql) -> dict:
    """The App's default filter window for this page, from the same bounds the App check reads on each sync, so the Genie block
    carries the window the App shows by default."""
    bounds = {}
    for f in page.get("filters") or []:
        if f.get("type") != "date_range":
            continue
        sql, _params = shell_sql.bounds_query(page, f["id"])
        row = (inspire_rows(spark.sql(sql)) or [{}])[0]
        bounds[f["id"]] = tuple(None if row.get(k) is None else str(row[k])[:10] for k in ("low", "high"))
    return shell_sql.default_values(page, bounds)


def implement_genie_page_kpis(space, uc_id: str, page, shell_sql=None, values=None) -> tuple:
    out = json.loads(json.dumps(space if isinstance(space, dict) else {}))
    before = json.dumps(out, sort_keys=True)
    collided = implement_genie_kpi_collisions(out, page) and json.dumps(out, sort_keys=True) != before
    block = implement_genie_kpi_block(uc_id, page, shell_sql, values)
    instructions = out.get("instructions")
    if not isinstance(instructions, dict):
        if not block or "instructions" in out:
            return out, collided
        instructions = out["instructions"] = {}
    current = (instructions.get("text_instructions") or [None])[0]
    content = _implement_genie_text((current or {}).get("content")).strip()
    head = re.escape(IMPLEMENT_GENIE_KPI_HEAD.format(uc=uc_id))
    kept = re.sub(rf"(?:\n\n)?{head}.*?(?=\n\n|\Z)", "", content, flags=re.S).strip()
    text = f"{kept}\n\n{block}".strip() if block else kept
    if text == content:
        return out, collided
    if text:
        entry = dict(current if isinstance(current, dict) else {}, content=text.splitlines(keepends=True))
        if not re.fullmatch(r"[0-9a-f]{32}", str(entry.get("id") or "")):
            entry["id"] = uuid.uuid4().hex
        instructions["text_instructions"] = [entry]
    else:
        instructions.pop("text_instructions", None)
    return out, True


def implement_kind_genie_brief(kind_spec) -> str:
    if not kind_spec or not kind_spec["tables"]:
        return ""
    kind = kind_spec["kind"]
    tables = "; ".join(f"`{info['table']}` ({', '.join(info['columns'])})" for info in kind_spec["tables"].values())
    return (f"- This is a {kind['label']} use case: {kind['question']} Its run also writes these tables, which Inspire adds to the "
            f"space after the business output table: {tables}. Word the sample questions the user did not word from these question "
            f"forms, with each placeholder in braces filled in with this use case's own words, and answer each from these tables or "
            f"the business output table: " + "; ".join(kind["genie"]["questions"])
            + ". Inspire adds the kind's measures to the SQL expressions itself.\n")


def implement_kind_alert(kind_spec) -> tuple:
    if not kind_spec:
        return "", ""
    result_table, rules, texts = kind_spec["result_table"], [], []
    present = {info["table"].lower() for info in kind_spec["tables"].values()}
    for alert in kind_spec["kind"]["alerts"]:
        needed = {inspire_shell_facts.companion(result_table, suffix).lower() for suffix in _INSPIRE_KIND_TABLE_RE.findall(alert.get("sql") or "") if suffix}
        if not alert.get("sql") or not needed or not needed <= present:
            continue
        sql = _INSPIRE_KIND_TABLE_RE.sub(lambda m: inspire_table_name(result_table, m.group(1) or ""), alert["sql"])
        rules.append(f"coalesce({sql.replace('{threshold}', str(alert['threshold']))}, false)")
        texts.append(_INSPIRE_KIND_TABLE_RE.sub(lambda m: inspire_shell_facts.companion(result_table, m.group(1) or ""), alert["rule"]).replace(
            "{threshold}", _genie_number_text(alert["threshold"])))
    return ("SELECT " + " OR ".join(rules) + " AS triggered", " or ".join(texts)) if rules else ("", "")


def implement_app_shell_payload(text: str) -> dict:
    try:
        data = implement_embedded_json(text)
    except (ValueError, zlib.error) as error:
        raise RuntimeError(f"the App shell in the Inspire assets does not decode: {redact_error(error)}")
    files = data.get("files") if isinstance(data, dict) else None
    binary = data.get("binary", {}) if isinstance(data, dict) else None
    if (not isinstance(files, dict) or data.get("version") != IMPLEMENT_APP_SHELL_VERSION or not isinstance(data.get("example"), dict)
            or any(f"{name}.py" not in files for name in IMPLEMENT_APP_SHELL_MODULES) or "static/index.html" not in files
            or not isinstance(binary, dict) or not all(isinstance(value, str) for value in binary.values())):
        raise RuntimeError("this Inspire build carries no usable App shell; write it with `python3 agent/app_shell/embed.py write`")
    try:
        decoded = {name: base64.b64decode(value, validate=True) for name, value in binary.items()}
    except ValueError as error:
        raise RuntimeError(f"the App shell in the Inspire assets does not decode: {redact_error(error)}")
    files = dict(files, **decoded)
    files[IMPLEMENT_APP_KINDS_FILE] = implement_kinds_text(files)
    return dict({key: value for key, value in data.items() if key != "binary"}, files=files)


def implement_artifact_text(work: str, name: str) -> str:
    if name not in IMPLEMENT_ARTIFACT_FILES:
        return ""
    try:
        with open(os.path.join(work, IMPLEMENT_ARTIFACT_FILES[name]), encoding="utf-8") as handle:
            return handle.read(1_000_000)
    except (OSError, UnicodeDecodeError):
        return ""


def implement_write_files(root: str, files: dict):
    for relative, text in files.items():
        target = os.path.join(root, relative)
        os.makedirs(os.path.dirname(target), exist_ok=True)
        if isinstance(text, bytes):
            with open(target, "wb") as handle:
                handle.write(text)
            continue
        with open(target, "w", encoding="utf-8") as handle:
            handle.write(text)


def implement_shell_module(text: str, name: str):
    """REQ-414 part B: a server module of the packed App shell, executed into a module object (shell_facts, shell_build)."""
    import types
    module = types.ModuleType(name)
    try:
        files = (json.loads(zlib.decompress(base64.b64decode(text)).decode("utf-8")).get("files") or {}) if text else {}
    except (ValueError, zlib.error):
        files = {}
    if files.get(f"{name}.py"):
        exec(compile(files[f"{name}.py"], f"{name}.py", "exec"), module.__dict__)
    return module


def implement_shell_facts_module(text: str):
    return implement_shell_module(text, "shell_facts")


def implement_shell_facts_snippet(source: str) -> str:
    if "\'\'\'" in source or source.rstrip().endswith("\\"):
        raise RuntimeError("shell_facts.py holds a triple quote or ends in a backslash, so the Run controls cannot carry it")
    return ("import types as _inspire_types\n"
            "inspire_shell_facts = _inspire_types.ModuleType(\"shell_facts\")\n"
            f"exec(compile(r\'\'\'{source}\'\'\', \"shell_facts.py\", \"exec\"), inspire_shell_facts.__dict__)")


def implement_page_rules(outputs: dict, name: str, label: str, kinds=(), not_drawn=None, dashboard: bool = False) -> dict:
    outputs = outputs if isinstance(outputs, dict) else {}
    return {"vibes": "\n".join(implement_vibed_assets(outputs, name).values()) if outputs else "", "label": label,
            "kinds": list(kinds or ()), "not_drawn": dict(not_drawn or {}),
            "requested": [str(r) for r in outputs.get("dashboard_filters") or []], "dashboard": bool(dashboard)}


def implement_app_check_files(files: dict, event_date: bool, kinds=(), many=(), layout: str = "", asked: bool = True,
                              rules: dict = None) -> dict:
    rules = dict(rules or implement_page_rules({}, "", "App"), kinds=list(kinds or ()))
    script = ("import json, os, sys\n"
              "here = os.path.dirname(os.path.abspath(__file__))\n"
              "sys.path.insert(0, here)\n"
              "import shell_facts\n"
              "import shell_sql\n"
              "try:\n"
              f"    with open(os.path.join(os.path.dirname(here), {IMPLEMENT_APP_PAGE_FILE!r}), encoding='utf-8') as handle:\n"
              "        page = json.load(handle)\n"
              "except (OSError, ValueError) as error:\n"
              f"    print({IMPLEMENT_APP_PAGE_FILE!r} + ' cannot be read: ' + str(error))\n"
              "    sys.exit(1)\n"
              + (f"if isinstance(page, dict):\n"
                 f"    page['layout'] = {layout!r}\n"
                 f"    shell_sql.place_items(page)\n" if layout else "")
              + f"many = {[implement_table_leaf(m) for m in many or ()]!r}\n"
              "fanning = shell_facts.fanning_datasets(page, many) if many and not shell_sql.shape_problems(page) else {}\n"
              "problems = shell_sql.spec_problems(page) + shell_sql.decision_problems(page) if isinstance(page, dict) else "
              "shell_sql.spec_problems(page)\n"
              f"problems = problems or shell_sql.quality_problems(page, {bool(event_date)}, fanning)\n"
              + ("" if asked else "problems = problems or [shell_sql.unasked_part_problem(page, word, item) "
                                  "for _group, word, item in shell_sql.asked_section_items(page)]\n")
              + f"rules = json.loads({json.dumps(rules)!r})\n"
              f"rules['not_drawn'] = {{' '.join(str(i.get('kind') or '').split()).lower(): ' '.join(str(i.get('reason') or '').split()) "
              f"for i in (page.get({IMPLEMENT_CHARTS_NOT_DRAWN!r}) if isinstance(page, dict) else None) or [] "
              "if isinstance(i, dict) and str(i.get('reason') or '').strip()}\n"
              "problems = problems or shell_sql.rule_problems(page, rules)[0]\n"
              "print('\\n'.join(problems) or 'no problems')\n"
              "sys.exit(1 if problems else 0)\n")
    return {f"{IMPLEMENT_APP_CHECK_DIR}/shell_sql.py": files["shell_sql.py"], f"{IMPLEMENT_APP_CHECK_DIR}/shell_facts.py": files["shell_facts.py"],
            f"{IMPLEMENT_APP_CHECK_DIR}/shell_redact.py": REDACT_SOURCE,
            f"{IMPLEMENT_APP_CHECK_DIR}/{IMPLEMENT_APP_KINDS_FILE}": implement_kinds_text(files),
            f"{IMPLEMENT_APP_CHECK_DIR}/{IMPLEMENT_APP_CHECK_SCRIPT}": script}


_IMPLEMENT_APP_SHELL_LOAD = threading.Lock()


def implement_app_shell_modules(folder: str, files: dict) -> dict:
    import importlib
    implement_write_files(folder, dict({f"{name}.py": files[f"{name}.py"] for name in IMPLEMENT_APP_SHELL_MODULES},
                                       **{IMPLEMENT_APP_KINDS_FILE: implement_kinds_text(files)}))
    with _IMPLEMENT_APP_SHELL_LOAD:
        held = {name: sys.modules.pop(name) for name in IMPLEMENT_APP_SHELL_MODULES if name in sys.modules}
        sys.path.insert(0, folder)
        importlib.invalidate_caches()
        bytecode, sys.dont_write_bytecode = sys.dont_write_bytecode, True
        try:
            return {name: importlib.import_module(name) for name in IMPLEMENT_APP_SHELL_MODULES}
        finally:
            sys.dont_write_bytecode = bytecode
            sys.path.remove(folder)
            for name in IMPLEMENT_APP_SHELL_MODULES:
                sys.modules.pop(name, None)
            sys.modules.update(held)


def implement_app_page_id(uc_id: str) -> str:
    ident = re.sub(r"[^a-z0-9]+", "_", str(uc_id or "").lower()).strip("_")[:60]
    return ident if re.match(r"^[a-z_]", ident) else f"p_{ident}"


def implement_alert_reads_setting(asset_status) -> bool:
    live = (asset_status or {}).get("alert") if isinstance(asset_status, dict) else None
    return isinstance(live, dict) and live.get("state") in IMPLEMENT_LIVE_ALERT_STATES and live.get("threshold_setting") is True


def implement_settle_alert_setting(asset_status) -> None:
    held = (asset_status or {}).get("settings") if isinstance(asset_status, dict) else None
    if isinstance(held, list):
        live = implement_alert_reads_setting(asset_status)
        asset_status["settings"] = [dict(s, reads_setting=live) if isinstance(s, dict) and s.get("source") == "alert" else s for s in held]


def implement_page_settings(asset_status, outputs=None) -> list:
    held = (asset_status or {}).get("settings") if isinstance(asset_status, dict) else None
    out = []
    for item in held or []:
        if not isinstance(item, dict) or item.get("source") not in ("widget", "alert"):
            continue
        if item["source"] == "alert" and outputs is not None:
            if not outputs.get("alert"):
                continue
            item = dict(item, default=str(implement_alert_threshold(outputs)), reads_setting=implement_alert_reads_setting(asset_status))
        out.append(dict(item))
    return out


def implement_kind_brief(use_case: dict, layout: str, tables: dict) -> str:
    kind = inspire_use_case_kind(use_case or {})
    if not kind and not tables and (layout or INSPIRE_DEFAULT_LAYOUT) == INSPIRE_DEFAULT_LAYOUT:
        return ""
    lines = [f"Kind: {kind['label']} ({kind['id']}), the question it answers: {kind['question']}"] if kind else []
    lines.append(f"Technique: {(use_case or {}).get('Analytics Technique') or 'not set'}; App layout: {layout or 'decision_queue'}")
    lines += [f"Companion table `{table}`, with the columns {', '.join(columns)}" for table, columns in (tables or {}).items()]
    return "\n".join(lines) + "\n"


def implement_app_layout(use_case: dict, asks: str = "") -> tuple:
    enabled = {layout["id"]: layout for layout in _inspire_kinds()["layouts"] if layout.get("enabled") is True}
    words = " ".join(str(asks or "").split()).lower()
    named = [ident for ident, layout in enabled.items() if ("_" in ident and ident in words)
             or f"{str(layout.get('label') or ident).lower()} layout" in words]
    if len(named) == 1:
        return named[0], "the user asked for it"
    kind = inspire_use_case_kind(use_case or {})
    stored = str((use_case or {}).get("app_layout") or "")
    decision = (kind or {}).get("decision_layout")
    if decision in enabled and stored in ("", str((kind or {}).get("layout") or "")):
        return decision, f"the {(kind or {}).get('label')} kind draws its decision list"
    for ident, why in ((stored, "the use case names it"),
                       ((kind or {}).get("layout"), f"the {(kind or {}).get('label')} kind draws it")):
        if ident and ident in enabled:
            return ident, why
    return INSPIRE_DEFAULT_LAYOUT, "no layout of the use case's kind is served yet"


def implement_layout_tables(result_table: str, layout: str) -> dict:
    table = str(result_table or "").strip()
    contract = (_inspire_kinds()["contracts"].get((_inspire_layout(layout) or {}).get("contract")) or {}).get("suffixes") or {}
    return {inspire_shell_facts.companion(table, suffix): list(columns) for suffix, columns in contract.items()} if table else {}


def implement_layout_missing(tables: dict, schemas: dict) -> dict:
    out = {}
    for table, columns in tables.items():
        schema = schemas.get(table)
        if isinstance(schema, str):
            out[table] = f"cannot be read: {schema}"
        elif not schema:
            out[table] = "does not exist"
        else:
            have = {str(name).lower() for name, _type in schema}
            gone = [c for c in columns if c.lower() not in have]
            if gone:
                out[table] = f"has no column {', '.join(gone)}"
    return out


def implement_companion_skipped(missing: dict, result_table: str, skips) -> dict:
    said = {inspire_shell_facts.companion(result_table, suffix): why for suffix, why in (skips or {}).items()}
    return {table: f"{why} (the run printed: {said[table]})" if table in said else why for table, why in missing.items()}


def implement_page_asks(outputs, name: str) -> list:
    texts = list(implement_vibed_assets(outputs, name).values())
    if name == "app" and (outputs or {}).get("app_purpose"):
        texts.append(str(outputs["app_purpose"]))
    return [c.strip() for text in texts for c in re.split(r"[.;:,\n]+", str(text or "")) if c.strip()]


def implement_part_ask(item: dict, word: str, asks) -> str:
    drop = set(IMPLEMENT_VIBES_NAME_KINDS)
    if word == "chart":
        types = implement_chart_type_words(item)
        drop |= _implement_vibes_tokens(" ".join(types))
        axes = [a for a in [item.get("x"), *(item.get("y") or [])] if isinstance(a, dict)]
        names = [n for a in axes for n in (a.get("label"), a.get("column"), re.sub(r"[A-Za-z_]+\s*\(", " ", str(a.get("expression") or "")))]
    else:
        names = [item.get("title"), item.get("id")]
    names = [t for t in (_implement_vibes_tokens(n) - drop for n in names if n) if t]
    for clause in asks or []:
        tokens = _implement_vibes_tokens(clause)
        named = (any(_implement_vibes_tokens(t) and _implement_vibes_tokens(t) <= tokens for t in types) if word == "chart"
                 else any(IMPLEMENT_VIBES_NAME_KINDS.get(_implement_vibes_token(w)) == "table"
                          for w in re.split(r"[^a-z0-9]+", clause.lower()) if w))
        if named and any(t <= tokens for t in names):
            return clause
    return ""


def implement_unasked_part_problems(page: dict, shell_sql, asks) -> list:
    return [shell_sql.unasked_part_problem(page, word, item) for _group, word, item in shell_sql.asked_section_items(page)
            if not implement_part_ask(item, word, asks)]


def implement_drop_misfits(page: dict, shell_sql, asks) -> list:
    layout = shell_sql.page_layout(page)
    if layout == shell_sql.DEFAULT_LAYOUT:
        return []
    unasked = {id(item) for _group, word, item in shell_sql.asked_section_items(page) if not implement_part_ask(item, word, asks)}
    notes = []
    for group, word in (("charts", "chart"), ("tables", "table")):
        if not isinstance(page.get(group), list):
            continue
        kept = []
        for item in page[group]:
            if isinstance(item, dict) and (id(item) in unasked or not shell_sql.item_sections(page, group, item)):
                why = ("no ask for this page names it" if id(item) in unasked
                       else f"no section of a {layout} page draws a {item.get('type') or word}")
                notes.append(f"{word} {item.get('id')} was left out because {why}, and Inspire sets the {layout} layout from the use "
                             f"case's kind; ask for it by its type and what it shows to add it in the {group} section")
                continue
            kept.append(item)
        page[group] = kept
    return notes


def implement_money_brief(money) -> str:
    if not isinstance(money, dict):
        return ""
    if money.get("off"):
        return "- money is off for this use case: write no money amount, KPI or chart.\n"
    parts = []
    if money.get("statuses"):
        parts.append("keep only rows whose status is one of " + ", ".join(repr(s) for s in money["statuses"]) + ", each written as a quoted literal in the dataset SQL")
    parts.append("losses only: each loss is netted at zero, as GREATEST(-effect, 0)" if money.get("rule", "losses") == "losses" else "net: the signed effect, gains and losses netted")
    if money.get("per") == "group":
        parts.append("each group (" + str(money.get("group_column")) + ") counts once, with its largest row")
    if "rate_table" in money:
        parts.append("convert with the rate table, joined on the currency, the base currency and the row date, and the latest loaded row when a date has more than one rate")
    if "rate_column" in money:
        parts.append(f"convert each row into {money.get('base')}: the row's amount times the rate in {money.get('rate_column')} on that same row, "
                     f"where the row's currency is in {money.get('currency_column')}; each row is converted with its own rate, never one rate for all rows")
    return "- money rules the dataset SQL must keep: " + "; ".join(parts) + ".\n"


def implement_drivers_brief(name: str, layout: str, result_table: str, shell_sql, outputs: dict) -> str:
    """The Drivers bullet of the App prompt. Drivers are required on the decision queue and on the dashboard. On the other App
    layouts they are optional, so the prompt asks for a Drivers chart only on the output table, if one fits."""
    if name != "dashboard" and layout != shell_sql.DEFAULT_LAYOUT:
        label = (shell_sql.layouts().get(layout) or {}).get("label") or layout
        return (f"- Drivers: optional on the {label} layout, so Inspire asks for none. Set \"{shell_sql.DRIVER}\": true only on a chart "
                f"whose dataset reads `{result_table}` directly and shows what drives its result; otherwise leave \"{shell_sql.DRIVER}\" out.\n")
    return (f"- Drivers: set \"{shell_sql.DRIVER}\": true on at least {shell_sql.DRIVERS_MIN} chart that shows what drives this "
        f"use case's result, such as the segment or the category of cause where the listed records concentrate, or the "
        f"measure that moves their score. A Drivers chart reads a dataset over `{result_table}` and groups its rows by a "
        f"column that dataset really selects; for a Drivers chart, a pareto or any chart that shows where records concentrate, "
        f"{shell_sql.CATEGORY_GROUPING}, since each bar of such text is one record. Inspire runs each such chart and sends "
        f"back one whose bars are nearly one record each. Only when the customer's asks for this "
        f"{IMPLEMENT_OUTPUT_LABELS[name]} ask for a chart grouped by reason, draw it and set the top-level field "
        f"{shell_sql.REASON_CHARTS} to the words of those asks that say so, word for word; otherwise leave "
        f"{shell_sql.REASON_CHARTS} out"
        + ("; the dashboard draws the Drivers charts in its own Drivers section below the other charts" if outputs.get("dashboard")
           else "") + ".\n")


def implement_skipped_companions_left_out(missing, result_table: str, skips, layout: str) -> dict:
    # REQ-396: a companion the run printed an honest reason for (The __x table cannot be filled from this data: why) is left out of the
    # preview gate, unless the layout cannot be drawn without it (implement_blocking_companions). The publish step already leaves a
    # view whose table is missing out and names the reason (_implement_app_layout), so the gate and the App agree, and Genie is not
    # sent back to write a table the data cannot fill.
    said = {inspire_shell_facts.companion(result_table, suffix) for suffix in (skips or {})}
    blocking = implement_blocking_companions(missing, result_table, layout)
    return {table: why for table, why in (missing or {}).items() if table not in said or table in blocking}


def implement_blocking_companions(missing, result_table: str, layout: str) -> set:
    # REQ-264: the companion tables a layout's table sections read (the App fit check requires a table for each, declared as
    # required_companions in the kinds registry). When one is missing, no page of the layout can pass the check, so the layout is not
    # drawn and the page keeps its decision list.
    needed = {inspire_shell_facts.companion(result_table, suffix) for suffix in (_inspire_layout(layout) or {}).get("required_companions") or []}
    return needed & set(missing or {})


def implement_layout_brief(layout: str, tables: dict, shell_sql, asked: bool = False) -> str:
    spec = shell_sql.layouts().get(layout) or {}
    if not spec or layout == shell_sql.DEFAULT_LAYOUT:
        return ""
    lows = spec.get("min_items") or {}
    parts = []
    for section in shell_sql.layout_sections(layout, asked=asked):
        entry = shell_sql.SECTIONS.get(section) or {}
        if section not in shell_sql.SECTIONS:
            continue
        kinds = entry.get("charts")
        fits = ("charts of type " + " or ".join(kinds) if kinds else "any chart" if "charts" in entry and kinds is None else "")
        fits = " or ".join(f for f in (fits, "tables" if entry.get("tables") else "") if f)
        need = f", at least {lows[section]} {'rows at the default filters' if entry.get('unit') == 'rows' else 'items'}" if section in lows else ""
        parts.append(f"{section} ({shell_sql.section_words(section)}{'; put ' + fits + ' here' if fits else ''}{need})")
    if not shell_sql.layout_decides(layout):
        listed = (f"This layout has no decision list, so leave out the {shell_sql.RECORDS_DATASET} dataset and the records section, "
                  f"and the rules below about them do not apply. ")
    elif tables:
        listed = (f"People decide each row of the {shell_sql.RECORDS_DATASET} dataset, so it selects record_key from the current rows "
                  f"of the result table and joins each companion table it reads to them, as the example does. ")
    else:
        listed = ""
    return (f"The page uses the {spec.get('label') or layout} layout: Inspire sets layout to \"{layout}\", and the App draws these "
            f"sections in this order: {'; '.join(parts)}. "
            + (f"The {' and '.join(shell_sql.ASKED_SECTIONS)} sections come after the {spec.get('label') or layout} parts and hold "
               f"only the charts and tables the customer asks for that no other section draws, so an asked line, bar or table "
               f"goes there and the {layout} layout stays. " if asked else "")
            + f"Every chart and extra table names its section, one of these; a KPI may "
            f"name an objective section when the layout has one. "
            + (f"Read the companion tables this use case's run writes: "
               + "; ".join(f"`{t}` ({', '.join(c)})" for t, c in tables.items()) + ". " if tables else "")
            + listed
            + ("Only when the customer's asks for this App ask for fewer rows than a section's minimum, show what they ask for and "
               "set the top-level field fewer_rows to the words of those asks that say so, word for word; otherwise leave fewer_rows "
               "out. " if any((shell_sql.SECTIONS.get(s) or {}).get("unit") == "rows" for s in lows) else "")
            + "Where the rules below differ for this layout, this layout wins, and the user's asks win over both.\n")


def implement_deployed_choices(pages, uc_id: str) -> list:
    for page in pages or ():
        records = page.get("records") if isinstance(page, dict) else None
        if isinstance(page, dict) and str(page.get("use_case_id") or "") == str(uc_id) and isinstance(records, dict) and records.get("choices"):
            return [dict(c) for c in records["choices"] if isinstance(c, dict)]
    return []


def implement_page_grouping(settings, page, shell_sql=None) -> dict:
    item = next((s for s in settings or [] if isinstance(s, dict) and s.get("name") == INSPIRE_GROUP_BY and s.get("source") == "widget"), None)
    mode, named = inspire_group_by_mode(str((item or {}).get("default") or ""))
    return shell_sql.page_grouping(page, named) if mode == "columns" and shell_sql is not None else {}


def implement_app_page(page, uc_id: str, use_case: dict, result_table: str = "", settings=None, guide=None, review: str = "",
                       layout: str = "", choices=None, undo: str = "", group=None, shell_sql=None) -> dict:
    if not isinstance(page, dict):
        raise RuntimeError(f"{IMPLEMENT_APP_PAGE_FILE} must hold one JSON object")
    out = dict(page, id=implement_app_page_id(uc_id), use_case_id=uc_id)
    out["use_case_name_tag"] = inspire_usecase_name_tag((use_case if isinstance(use_case, dict) else {}).get("Name"))
    note = scope_data_note()
    if note:
        out["question"] = " ".join(part for part in (str(out.get("question") or "").strip(), note) if part)
    if layout:
        out["layout"] = layout
    kind = inspire_use_case_kind(use_case if isinstance(use_case, dict) else {})
    if kind:
        out["kind"] = kind["id"]
        out["kind_question"] = str(kind.get("question") or "")
    if choices and isinstance(out.get("records"), dict) and not out["records"].get("choices"):
        out["records"] = dict(out["records"], choices=[dict(choice) for choice in choices])
    if undo and isinstance(out.get("records"), dict) and not out["records"].get("undo"):
        out["records"] = dict(out["records"], undo=str(undo))
    if group and isinstance(out.get("records"), dict) and not out["records"].get("group"):
        out["records"] = dict(out["records"], group=dict(group))
    for key in ("result_table", "genie", "genie_note", "settings", "runbook", "review", "run_scopes", "grouping"):
        out.pop(key, None)
    if settings:
        out["settings"] = list(settings)
        if any(isinstance(s, dict) and s.get("name") == "run_scope" for s in settings):
            out["run_scopes"] = True
    if guide:
        out["runbook"] = dict(guide)
    if result_table:
        out["result_table"] = result_table
    if review:
        out["review"] = review
    for key, column in (("domain", "Business Domain"), ("subdomain", "Subdomain"), ("sponsor", "Sponsor")):
        value = " ".join(str((use_case or {}).get(column) or "").split())
        if value:
            out[key] = value[:80]
    out.pop("promised", None)
    promised = implement_promised(use_case)
    if promised:
        out["promised"] = promised
    out.pop("similar_by", None)
    grouping = implement_page_grouping(settings, out, shell_sql)
    if grouping:
        out["grouping"] = grouping
    grouping = [f.get("id") for f in out.get("filters") or [] if isinstance(f, dict) and f.get("type") == "multi_select"
                and IMPLEMENT_RECORDS_DATASET in (f.get("columns") or {})]
    if grouping:
        out["similar_by"] = list(dict.fromkeys(grouping))[:IMPLEMENT_SIMILAR_BY]
    return out


def implement_promised(use_case: dict) -> dict:
    value = " ".join(inspire_ident_words(inspire_placeholder_words((use_case or {}).get("Business Value"))).split())[:IMPLEMENT_PROMISED_CHARS]
    raw = (use_case or {}).get("Financial Benefits")
    if isinstance(raw, str):
        try:
            raw = json.loads(raw) if raw.strip().startswith("[") else [raw]
        except ValueError:
            raw = [raw]
    kpis = (use_case or {}).get("KPIs")
    lines = [" ".join(inspire_ident_words(inspire_placeholder_words(kpi_without_stale_baselines(b, kpis))).split())[:IMPLEMENT_PROMISED_BENEFIT_CHARS]
             for b in raw or [] if str(b or "").strip()]
    estimate = " ".join(inspire_ident_words((use_case or {}).get("value_estimate_text")).split())[:IMPLEMENT_PROMISED_CHARS]
    out = {"value": value, "benefits": lines[:IMPLEMENT_PROMISED_BENEFITS]}
    return dict(out, estimate=estimate) if estimate else out if value or lines else {}


def implement_choices_rule(shell_sql) -> str:
    low, high = shell_sql.CHOICE_COUNT
    shown = ", ".join(c["label"] for c in shell_sql.DEFAULT_CHOICES)
    example = json.dumps([{"id": "reprice", "label": "Reprice", "status": shell_sql.IN_PROGRESS},
                          {"id": "keep", "label": "Keep the price", "status": shell_sql.DONE},
                          {"id": "wrong", "label": "Wrong flag", "status": shell_sql.DISMISSED, "reasons": ["Data error", "Seasonal"]}])
    return (f"- records may take \"choices\", the statuses a person picks for a record, each with its own Work tab: {low} to {high} "
            f"objects {{\"id\", \"label\", \"status\", \"reasons\"}}, for example {example}. Write them only when the user or the use "
            f"case names its own statuses; without them the App offers {shown}. id is 1 to 40 lowercase letters, digits, - or _, each "
            f"id once, never {', '.join(shell_sql.CHOICE_TABS)}; label is at most {shell_sql.CHOICE_LABEL_CHARS} characters and each label "
            f"once; status is one of {', '.join(shell_sql.ACTION_STATUSES)}, the stored status the choice counts as; at least one choice "
            f"has an open status ({', '.join(shell_sql.OPEN_STATUSES)}) and one the {shell_sql.DONE} status; a {shell_sql.DISMISSED} "
            f"choice carries reasons, the list a person picks why from. Keep every choice id this page already had, since records "
            f"carry it.\n")


def implement_app_page_problems(page: dict, shell_sql, allowed, event_date: bool, run_versions=None, many=None, real=None,
                                 stored=None, drivers_optional=False, written_only=False) -> list:
    problems = shell_sql.spec_problems(page, stored) + shell_sql.decision_problems(page)
    if problems:
        return problems
    result = _implement_plain_table(page.get("result_table") or "")
    if drivers_optional:
        implement_settle_drivers(page, shell_sql)
    many = implement_page_many_sides(result) if many is None and result else many
    problems = (shell_sql.quality_problems(page, event_date, implement_page_fanning(page, many) if many else ())
                + implement_driver_problems(page, shell_sql))
    problems += implement_page_fanout_problems(page, result, many, real, shell_sql.RECORDS_DATASET) if result and many else []
    texts = [str(d.get("sql") or "") for d in page["datasets"]]
    # REQ-250: the result table's companions (and their live, candidate and versioned forms) are the use case's, through implement_use_case_table.
    # FX-71 (REQ-264): with written_only the contract companions count only when the run wrote them (they are in allowed then); one the run has not written is named as that.
    reads = implement_written_reads(allowed, result) if written_only else implement_use_case_reads(allowed, result)
    unknown = _implement_unknown_tables(texts, reads)
    unwritten = [u for u in unknown if implement_use_case_table(u, implement_app_result_reads(result))] if written_only else []
    unknown = [u for u in unknown if u not in unwritten]
    if unwritten:
        problems.append(f"the datasets read tables the run has not written: {', '.join(unwritten)}; read only the tables the run wrote")
    if unknown:
        problems.append(f"the datasets read tables outside this use case: {', '.join(unknown)}")
    expressions = ([str(k.get("expression") or "") for k in page.get("kpis") or []]
                   + [str(y.get("expression") or "") for c in page.get("charts") or [] for y in c.get("y") or []])
    return (problems + _implement_flag_count_problems(texts + expressions, "the page")
            + implement_run_version_problems(texts, "a dataset of the page", run_versions))


IMPLEMENT_PROBLEM_NUMBER = re.compile(r"(?<![\w.])\d+(?:[.,]\d+)*(?!\w)")
IMPLEMENT_PROBLEM_WORSE = tuple((direction, re.compile(pattern.replace("N", r"(?P<n>\d+(?:[.,]\d+)*)"), re.I)) for direction, pattern in (
    ("higher", r"\btook N s\b"), ("higher", r"\bN (?:failed|failures?|errors?)\b"), ("higher", r"\bgap of N\b"),
    ("lower", r"\breturned N\b"), ("lower", r"\bN segment filters? offers?\b")))


def implement_problem_shape(problem) -> str:
    return IMPLEMENT_PROBLEM_NUMBER.sub("#", " ".join(str(problem or "").split()))


def implement_problem_kept(problem, held) -> bool:
    text = " ".join(str(problem or "").split())
    shape, numbers = implement_problem_shape(text), list(IMPLEMENT_PROBLEM_NUMBER.finditer(text))
    directions = {found.start("n"): direction for direction, pattern in IMPLEMENT_PROBLEM_WORSE for found in pattern.finditer(text)}
    value = lambda found: float(found.group(0).replace(",", ""))

    def no_worse(old) -> bool:
        old = " ".join(str(old or "").split())
        if implement_problem_shape(old) != shape:
            return False
        for new, before in zip(numbers, IMPLEMENT_PROBLEM_NUMBER.finditer(old)):
            now, then, direction = value(new), value(before), directions.get(new.start())
            if now != then and (direction is None or (now > then) == (direction == "higher")):
                return False
        return True

    return any(no_worse(old) for old in held or [])


def implement_put_back_checked(page: dict, merged, shell_sql, event_date: bool, label: str, prior=None):
    if merged is page or not isinstance(merged, dict):
        return merged
    check = lambda p: shell_sql.spec_problems(p) or shell_sql.quality_problems(p, event_date)
    seen = set(check(page)) | (set(check(prior)) if isinstance(prior, dict) else set())
    problems = [p for p in check(merged) if p not in seen]
    if problems:
        raise RuntimeError(f"{IMPLEMENT_APP_PAGE_FILE} passed its checks, but once Inspire put back the parts of the {label} no ask "
                           "targets, it no longer fits: " + "; ".join(problems) + ". Keep every part no ask names as it was, and "
                           "make what the asks add fit around it, for example by wiring a new dataset into the page filters")
    return merged


def implement_off_table_drivers(page: dict, shell_sql) -> list:
    result = _implement_plain_table(page.get("result_table") or "").lower()
    if not result:
        return []
    sql = {str(d.get("name")): str(d.get("sql") or "") for d in page.get("datasets") or [] if isinstance(d, dict)}
    return [c for c in shell_sql.driver_charts(page) if c.get("dataset") in sql
            and result not in {ref.lower() for ref in implement_table_refs(sql[c["dataset"]])}]


def implement_driver_problems(page: dict, shell_sql) -> list:
    return [f"Drivers chart {c.get('id')} reads dataset {c.get('dataset')}, which does not read the business output table "
            f"`{page['result_table']}`: a Drivers chart shows what drives the use case's results, so it groups that table's rows"
            for c in implement_off_table_drivers(page, shell_sql)]


def implement_settle_drivers(page: dict, shell_sql) -> list:
    """On the App's layouts other than the decision queue a Drivers chart is optional, so a chart marked as a driver that does not
    read the business output table loses its mark. No Genie round can fix a rule the layout does not ask for (REQ-181)."""
    if shell_sql.page_layout(page) == shell_sql.DEFAULT_LAYOUT:
        return []
    notes = []
    for chart in implement_off_table_drivers(page, shell_sql):
        chart[shell_sql.DRIVER] = False
        notes.append(f"Drivers chart {chart.get('id')} reads dataset {chart.get('dataset')}, not the business output table, so it is not "
                     "marked as a driver")
        print(f"[DRIVER-FIRED] {notes[-1]}", flush=True)
    return notes


def implement_repair_drivers(page: dict, shell_sql, most: int = 2) -> list:
    """c24_rc7mvp: a Dashboard is never failed for its Drivers section. A Drivers mark on a chart that does not read the business output
    table is cleared; a page left with no Drivers chart marks the (at most `most`) charts that break that table down by a category,
    the way the Drivers section reads. With no such chart the page publishes without the section (the build tells the person)."""
    notes = []
    for chart in implement_off_table_drivers(page, shell_sql):
        chart[shell_sql.DRIVER] = False
        notes.append(f"Drivers chart {chart.get('id')} reads dataset {chart.get('dataset')}, not the business output table, so it is not "
                     "marked as a driver")
    if shell_sql.driver_charts(page):
        return notes
    result = _implement_plain_table(page.get("result_table") or "").lower()
    sql = {str(d.get("name")): str(d.get("sql") or "") for d in page.get("datasets") or [] if isinstance(d, dict)}
    marked = []
    for chart in page.get("charts") or []:
        if len(marked) >= most:
            break
        if not isinstance(chart, dict) or not shell_sql.category_x(chart):
            continue
        if result and result not in {ref.lower() for ref in implement_table_refs(sql.get(str(chart.get("dataset")), ""))}:
            continue
        chart[shell_sql.DRIVER] = True
        marked.append(chart)
        notes.append(f"chart {chart.get('id')} breaks the output table down by {shell_sql.category_x(chart)}, so it is marked as a driver")
    for note in notes:
        print(f"[DRIVER-FIRED] {note}", flush=True)
    return notes


def implement_chart_left_out_text(title: str, message: str, word: str = "chart") -> str:
    missing = re.search(r"name `([^`]+)` cannot be resolved", str(message))
    why = (f"it reads the column `{missing.group(1)}`, which the table does not have" if missing
           else "it draws a date as a height or a size, which this kind of chart cannot show" if re.search(r"\bis a date, so a\b", str(message))
           else "its query could not run")
    return f'the {word} "{title}" was left out because {why}; the rest of the page is built'


IMPLEMENT_PART_GROUPS = {"chart": "charts", "kpi": "kpis", "table": "tables"}


def implement_genie_left_out_text(label: str, message: str) -> str:
    """c29_partial: the plain warning of one Genie Agent part (a benchmark, SQL snippet or join spec) that is left out of the space."""
    missing = re.search(r"name `([^`]+)` cannot be resolved", str(message))
    why = f"it reads the column `{missing.group(1)}`, which the table does not have" if missing else "its SQL could not run"
    return f"Genie Agent: {label} was left out because {why}; the rest of the Genie Agent is built"


def implement_genie_drop_part(space: dict, drop: tuple) -> None:
    """Remove one part (by identity) that a space check named: ("benchmarks", item), ("snippets", kind, item) or ("join_specs", item)."""
    instructions = space.setdefault("instructions", {})
    if drop[0] == "benchmarks":
        questions = (space.get("benchmarks") or {}).get("questions") or []
        space["benchmarks"]["questions"] = [q for q in questions if q is not drop[1]]
    elif drop[0] == "snippets":
        snippets = instructions.get("sql_snippets") or {}
        snippets[drop[1]] = [s for s in snippets.get(drop[1]) or [] if s is not drop[2]]
    else:
        instructions["join_specs"] = [j for j in instructions.get("join_specs") or [] if j is not drop[1]]


def implement_genie_table_left_out_text(table: str, message: str, counts: dict) -> str:
    """c29_partial2: the plain warning of one input table of the Genie Agent that cannot be read and is left out with what names it."""
    detail = str(message).split("could not be read:", 1)[-1].strip()[:300]
    kinds = ", ".join(f"{n} {word}" for word, n in counts.items() if n)
    gone = f"; the {kinds} that use it were left out too" if kinds else ""
    return f"Genie Agent: the table {table} was left out because it could not be read ({detail}){gone}; the rest of the Genie Agent is built"


def implement_genie_drop_tables(space: dict, gone, aliases: dict) -> dict:
    """c29_partial2: remove the tables `gone` (plain, lower case) from the space and every join spec, SQL snippet, example SQL and
    benchmark that names one, in place; returns how many of each went. `aliases` maps a plain table to the name its snippets use."""
    named = {aliases[t].lower() for t in gone if t in aliases}

    def names(sql) -> bool:
        return bool({_implement_plain_table(r).lower() for r in implement_table_refs(sql)} & set(gone))

    def by_alias(sql) -> bool:
        return names(sql) or any(p[0].lower() in named for p in implement_sql_column_refs(sql))

    def table_of(ref) -> bool:
        return _implement_plain_table((ref or {}).get("identifier")).lower() in gone

    counts = {"join specs": 0, "SQL snippets": 0, "example SQLs": 0, "benchmarks": 0}
    data = space.setdefault("data_sources", {})
    data["tables"] = [t for t in data.get("tables") or [] if _implement_plain_table(t.get("identifier")).lower() not in gone]
    instructions = space.setdefault("instructions", {})
    joins = instructions.get("join_specs") or []
    instructions["join_specs"] = [j for j in joins if not (table_of(j.get("left")) or table_of(j.get("right")))]
    counts["join specs"] = len(joins) - len(instructions["join_specs"])
    examples = instructions.get("example_question_sqls") or []
    instructions["example_question_sqls"] = [e for e in examples if not names("".join(e.get("sql") or []))]
    counts["example SQLs"] = len(examples) - len(instructions["example_question_sqls"])
    snippets = instructions.get("sql_snippets") or {}
    for kind, items in list(snippets.items()):
        kept = [s for s in items or [] if not by_alias("".join(s.get("sql") or []))]
        counts["SQL snippets"] += len(items or []) - len(kept)
        snippets[kind] = kept
    benchmarks = (space.get("benchmarks") or {}).get("questions") or []
    kept = [q for q in benchmarks if not names("".join("".join(a.get("content") or []) for a in q.get("answer") or [] if isinstance(a, dict)))]
    counts["benchmarks"] = len(benchmarks) - len(kept)
    if "benchmarks" in space:
        space["benchmarks"]["questions"] = kept
    return counts


def implement_app_read_tables(page: dict, allowed) -> list:
    by_name = {_implement_plain_table(t).lower(): t for t in allowed or []}
    out = []
    for dataset in page.get("datasets") or []:
        for ref in implement_table_refs(str(dataset.get("sql") or "")):
            table = by_name.get(ref.lower())
            if table and table not in out:
                out.append(table)
    return out


def implement_app_read_list(page: dict, pages, allowed, genie: bool, user_app: bool) -> list:
    # What the App reads directly, for its record and its service principal's grants. A user-authorization App's Genie space names only
    # the App's scope views (scope_space_sql rewrites it), so the use case's sources are not direct reads of the App: listing them told
    # viewers the App reads a source table directly (REQ-301). A service-principal App keeps its Genie grants on every source.
    read = implement_app_read_tables(page, allowed)
    read += [t for t in implement_money_rate_tables(page) if t not in read]
    if genie and not user_app:
        read += [t for t in allowed if t not in read]
    read += [t for t in implement_app_page_reads(pages, page["id"]) if t not in read]
    return read


def implement_money_rate_tables(page: dict) -> list:
    money = page.get("money") if isinstance(page.get("money"), dict) else {}
    table = str((money.get("rate_table") or {}).get("table") or "").strip()
    return [table] if table and not money.get("off") else []


def implement_cluster_columns(page: dict, table_schema) -> list:
    kinds = {str(name).lower(): (str(name), " ".join(str(kind or "").split()).lower()) for name, kind in table_schema or []}
    staked = kinds.get(inspire_shell_facts.MONEY_COLUMN, ("", ""))
    if staked[0] and staked[1].split("(")[0] in IMPLEMENT_APP_CLUSTER_TYPES:
        return [staked[0]]
    wanted = ["as_of_date"] + [str(column) for f in (page or {}).get("filters") or [] if isinstance(f, dict)
                               for column in ((f.get("columns") or {}).values() if isinstance(f.get("columns"), dict) else ())]
    out = []
    for column in wanted:
        name, kind = kinds.get(column.lower(), ("", ""))
        if name and kind.split("(")[0] in IMPLEMENT_APP_CLUSTER_TYPES and name not in out:
            out.append(name)
    return out[:IMPLEMENT_APP_CLUSTER_COLUMNS]


def implement_cluster_detail_sql(result_table: str) -> str:
    return f"DESCRIBE DETAIL {inspire_table_name(result_table)}"


def implement_cluster_sql(result_table: str, columns) -> str:
    return f"ALTER TABLE {inspire_table_name(result_table)} CLUSTER BY ({', '.join(inspire_column(c) for c in columns)})"


def implement_recluster_sql(result_table: str) -> str:
    return f"OPTIMIZE {inspire_table_name(result_table)} FULL"


def implement_type_leaves(kind) -> int:
    text = " ".join(str(kind or "").split())
    if not text.lower().startswith("struct<") or not text.endswith(">"):
        return 1
    body, depth, start, fields = text[7:-1], 0, 0, []
    for index, char in enumerate(body):
        if char in "<(":
            depth += 1
        elif char in ">)":
            depth -= 1
        elif char == "," and depth == 0:
            fields.append(body[start:index])
            start = index + 1
    fields.append(body[start:])
    return sum(implement_type_leaves(field.split(":", 1)[1]) for field in fields if ":" in field) or 1


def implement_stats_type(kind) -> bool:
    base = " ".join(str(kind or "").split()).lower().split("(")[0].split("<")[0].strip()
    return base in IMPLEMENT_APP_CLUSTER_TYPES or base == "struct"


def implement_stats_columns(table_schema, properties) -> list:
    properties = {str(key): str(value) for key, value in (properties or {}).items()} if isinstance(properties, dict) else {}
    names = [str(name) for name, _kind in table_schema or []]
    listed = properties.get("delta.dataSkippingStatsColumns", "").strip()
    if listed:
        chosen = {part.strip().strip("`").split(".")[0].lower() for part in listed.split(",") if part.strip()}
        return [name for name in names if name.lower() in chosen]
    try:
        limit = int(properties.get("delta.dataSkippingNumIndexedCols", IMPLEMENT_STATS_INDEXED_DEFAULT))
    except ValueError:
        limit = IMPLEMENT_STATS_INDEXED_DEFAULT
    out, used = [], 0
    for name, kind in table_schema or []:
        if 0 <= limit <= used:
            break
        if implement_stats_type(kind):
            out.append(str(name))
        used += implement_type_leaves(kind)
    return out


def implement_stats_columns_sql(result_table: str, columns) -> str:
    listed = ",".join(inspire_column(c) for c in columns)
    return f"ALTER TABLE {inspire_table_name(result_table)} SET TBLPROPERTIES ('delta.dataSkippingStatsColumns' = {inspire_sql_literal(listed)})"


def implement_stats_compute_sql(result_table: str) -> str:
    return f"ANALYZE TABLE {inspire_table_name(result_table)} COMPUTE DELTA STATISTICS"


def implement_app_choices(outputs, experience_default=IMPLEMENT_APP_EXPERIENCE_DEFAULT) -> tuple:
    outputs = outputs if isinstance(outputs, dict) else {}
    errors = []
    raw_access = outputs.get("app_access")
    text = _implement_text_value(raw_access)
    access = (text or "").lower()
    if access not in IMPLEMENT_APP_ACCESS:
        errors.append(f"choose who the App reads its data as: 'user' (each person sees only the rows and columns their Unity Catalog "
                      f"grants allow) or 'sp' (everyone sees the same data, read as the App itself)"
                      + (f", not {_implement_shown(raw_access)}" if text != "" else ""))
        access = ""
    look = dict(IMPLEMENT_APP_LOOK)
    for key, value in _implement_mapping(outputs.get("app_look"), "outputs.app_look", errors).items():
        choice = _implement_text_value(value)
        choice = None if choice is None else choice.lower()
        if key not in IMPLEMENT_APP_LOOK_CHOICES:
            errors.append(f"the App look has no setting {_implement_shown(key)}; it sets only {', '.join(IMPLEMENT_APP_LOOK_CHOICES)}")
        elif choice is None or (choice and choice not in IMPLEMENT_APP_LOOK_CHOICES[key]):
            errors.append(f"the App {key} {_implement_shown(value)} is not one Inspire offers; pick one of "
                          f"{', '.join(IMPLEMENT_APP_LOOK_CHOICES[key])}")
        elif choice:
            look[key] = choice
    options = dict(IMPLEMENT_APP_OPTIONS, experience=experience_default)
    for key, value in _implement_mapping(outputs.get("app_options"), "outputs.app_options", errors).items():
        if key == "experience":
            if value is not None and value not in IMPLEMENT_APP_EXPERIENCES:
                errors.append(f"the App experience {_implement_shown(value)} is not one Inspire offers; pick one of {', '.join(IMPLEMENT_APP_EXPERIENCES)}")
            elif value is not None:
                options[key] = value
        elif key not in IMPLEMENT_APP_OPTIONS:
            errors.append(f"the App has no option {_implement_shown(key)}; its options are {', '.join(IMPLEMENT_APP_OPTIONS)}")
        elif value is not None and not isinstance(value, bool):
            errors.append(f"the App option {key} must be true or false, not {_implement_shown(value)}")
        elif value is not None:
            options[key] = value
    if access == "user":
        options.update(dict.fromkeys(IMPLEMENT_APP_USER_OFF, False))
    if not options["modify"]:
        options["replace_edits"] = False
    raw_backend = outputs.get("app_backend")
    backend = _implement_text_value(raw_backend)
    backend = IMPLEMENT_APP_BACKENDS[-1] if backend == "" else None if backend is None else backend.lower()
    if backend not in IMPLEMENT_APP_BACKENDS:
        errors.append(f"choose where the App reads its data: 'lakebase' (its pages load instantly) or 'delta' (Delta tables, its pages "
                      f"take a few seconds to load), not {_implement_shown(raw_backend)}")
        backend = IMPLEMENT_APP_BACKENDS[-1]
    raw_placement = outputs.get("app_placement")
    placement = _implement_text_value(raw_placement)
    placement = None if placement is None else placement.lower()
    if placement is None or (placement and placement not in IMPLEMENT_APP_PLACEMENTS):
        listed = [f"'{name}' ({IMPLEMENT_APP_PLACEMENT_WORDS[name]})" for name in IMPLEMENT_APP_PLACEMENTS]
        errors.append(f"choose how Inspire organizes Apps: {', '.join(listed[:-1])} or {listed[-1]}, not {_implement_shown(raw_placement)}")
        placement = ""
    picked, raw_charts = [], outputs.get("app_charts")
    if raw_charts is not None and not isinstance(raw_charts, list):
        errors.append(f"the App charts must be a list of the kinds of chart the App draws, from {', '.join(IMPLEMENT_APP_CHART_KINDS)}")
    for raw in raw_charts if isinstance(raw_charts, list) else []:
        kind = (_implement_text_value(raw) or "").lower()
        if kind not in IMPLEMENT_APP_CHART_KINDS:
            errors.append(f"the App has no kind of chart {_implement_shown(raw)}; its kinds are {', '.join(IMPLEMENT_APP_CHART_KINDS)}")
        elif kind not in picked:
            picked.append(kind)
    if picked and len(picked) < IMPLEMENT_APP_CHARTS_MIN:
        errors.append(f"pick at least {IMPLEMENT_APP_CHARTS_MIN} kinds of chart for the App, not {implement_number_text(len(picked))}")
    pages = dict(IMPLEMENT_APP_PAGES)
    for key, value in _implement_mapping(outputs.get("app_pages"), "outputs.app_pages", errors).items():
        if key not in IMPLEMENT_APP_PAGES:
            errors.append(f"the App has no page {_implement_shown(key)} to turn on or off; Things to fix and Ask Genie are always on, "
                          f"and only {', '.join(IMPLEMENT_APP_PAGES)} can be turned off")
        elif value is not None and not isinstance(value, bool):
            errors.append(f"the App page {key} must be true or false, not {_implement_shown(value)}")
        elif value is not None:
            pages[key] = value
    return {"app_access": access, "app_look": look, "app_options": options, "app_backend": backend,
            "app_charts": [k for k in IMPLEMENT_APP_CHART_KINDS if k in picked], "app_pages": pages, "app_placement": placement}, errors


def implement_app_chart_kinds(outputs, shell_sql, event_date: bool) -> tuple:
    outputs = outputs if isinstance(outputs, dict) else {}
    if not outputs.get("app"):
        return [], False, []
    picked = [k for k in outputs.get("app_charts") or [] if k in shell_sql.CHART_KIND_TYPES]
    kinds = [k for k in picked or shell_sql.CHART_PICK if event_date or k != "trend"]
    notes = [f"{IMPLEMENT_OUTPUT_LABELS['app']}: no {shell_sql.CHART_KIND_LABELS[k].lower()} chart, which you picked, because the input tables carry no date to "
             f"draw it over; the App draws the other kinds. Pick another kind of chart in App look" for k in picked if k not in kinds]
    return kinds, bool(picked), notes


def implement_charts_not_drawn(data, kinds, picked: bool) -> tuple:
    value = data.pop(IMPLEMENT_CHARTS_NOT_DRAWN, None) if isinstance(data, dict) else None
    if value is None or value == []:
        return {}, []
    if not picked:
        return {}, [f"{IMPLEMENT_CHARTS_NOT_DRAWN} is only for kinds of chart the user picked: draw every kind the rules name and "
                    f"leave {IMPLEMENT_CHARTS_NOT_DRAWN} out"]
    if not isinstance(value, list):
        return {}, [f'{IMPLEMENT_CHARTS_NOT_DRAWN} must be a list of {{"kind": ..., "reason": ...}} objects']
    out, errors = {}, []
    for item in value:
        item = item if isinstance(item, dict) else {}
        kind = " ".join(str(item.get("kind") or "").split()).lower()
        reason = " ".join(str(item.get("reason") or "").split())
        if kind not in kinds or not reason:
            errors.append(f'each {IMPLEMENT_CHARTS_NOT_DRAWN} entry needs a "kind", one of {", ".join(kinds)}, and a "reason"')
        else:
            out[kind] = reason[:500]
    return out, sorted(set(errors))


def implement_current_app_options(options: dict) -> dict:
    return {k: v for k, v in options.items() if k not in IMPLEMENT_APP_RETIRED_OPTIONS}


def implement_stored_spec(spec):
    outputs = spec.get("outputs") if isinstance(spec, dict) else None
    if not isinstance(outputs, dict) or not isinstance(outputs.get("app_options"), dict):
        return spec
    return dict(spec, outputs=dict(outputs, app_options=implement_current_app_options(outputs["app_options"])))


def implement_app_held_settings(settings):
    if not isinstance(settings, dict) or not isinstance(settings.get("options"), dict):
        return settings
    return dict(settings, options=implement_current_app_options(settings["options"]))


def implement_run_owners(context: dict) -> list:
    return implement_owners({"created_by": context.get("requested_by"), "spec_json": context.get("spec")})


def implement_app_use_case_owners(held, page_ids, page_id: str, owners) -> dict:
    recorded = (held or {}).get("use_case_owners") if isinstance((held or {}).get("use_case_owners"), dict) else {}
    named = {ident: list(owners) if ident == page_id else recorded.get(ident) for ident in page_ids}
    return {ident: names for ident, names in named.items() if isinstance(names, list) and names}


def implement_app_user_scopes(outputs) -> list:
    outputs = outputs if isinstance(outputs, dict) else {}
    if outputs.get("app_access") == "sp":
        return list(IMPLEMENT_APP_VIEWER_SCOPES)
    if outputs.get("app_access") != "user":
        return []
    return list(IMPLEMENT_APP_EDIT_SCOPES if (outputs.get("app_options") or {}).get("modify") else IMPLEMENT_APP_READ_SCOPES)


def implement_app_jobs(jobs) -> dict:
    out = {}
    for page_id, job_id in (jobs.items() if isinstance(jobs, dict) else ()):
        text = "" if isinstance(job_id, bool) or job_id is None else str(job_id).strip()
        if re.fullmatch(r"[0-9]+", text):
            out[str(page_id)] = text
    return out


def implement_app_kept_jobs(held, page_ids, page_id: str = "", job_id=None) -> dict:
    ids = [str(p) for p in page_ids]
    jobs = {p: j for p, j in implement_app_jobs((held or {}).get("jobs")).items() if p in ids}
    jobs.update({p: j for p, j in implement_app_jobs({page_id: job_id}).items() if p in ids})
    return jobs


def implement_app_job_resource(page_id: str, job_id: str) -> dict:
    name = f"job-{str(page_id).replace('_', '-')}"
    if len(name) > IMPLEMENT_APP_RESOURCE_CHARS:
        digest = hashlib.sha256(str(page_id).encode()).hexdigest()[:6]
        name = f"{name[:IMPLEMENT_APP_RESOURCE_CHARS - len(digest) - 1].rstrip('-')}-{digest}"
    return {"name": name, "job": {"id": str(job_id), "permission": IMPLEMENT_APP_JOB_PERMISSION}}


def _implement_holds_job(resource, wanted: dict) -> bool:
    job = resource.get("job") if isinstance(resource, dict) else None
    return (isinstance(job, dict) and resource.get("name") == wanted["name"] and str(job.get("id")) == wanted["job"]["id"]
            and str(job.get("permission") or "").upper() == IMPLEMENT_APP_JOB_PERMISSION)


def implement_app_missing_jobs(resources, jobs) -> list:
    held = list(resources or [])
    return [job_id for page_id, job_id in implement_app_jobs(jobs).items()
            if not any(_implement_holds_job(r, implement_app_job_resource(page_id, job_id)) for r in held)]


def implement_app_resources(resources, jobs, postgres: bool = False, warehouse: str = "") -> list:
    out = list(resources or [])
    if warehouse and implement_app_warehouse_of(out) != warehouse:
        at = next((i for i, r in enumerate(out) if isinstance(r, dict) and isinstance(r.get("sql_warehouse"), dict)), None)
        if at is None:
            out.insert(0, {"name": IMPLEMENT_APP_WAREHOUSE_RESOURCE, "sql_warehouse": {"id": warehouse, "permission": "CAN_USE"}})
        else:
            out[at] = dict(out[at], sql_warehouse=dict(out[at]["sql_warehouse"], id=warehouse))
    for page_id, job_id in implement_app_jobs(jobs).items():
        wanted = implement_app_job_resource(page_id, job_id)
        names = [r.get("name") if isinstance(r, dict) else None for r in out]
        if wanted["name"] not in names:
            out.append(wanted)
        elif not _implement_holds_job(out[names.index(wanted["name"])], wanted):
            out[names.index(wanted["name"])] = wanted
    if postgres and not implement_app_holds_postgres(out):
        out = [r for r in out if not (isinstance(r, dict) and r.get("name") == IMPLEMENT_LAKEBASE_RESOURCE)]
        out.append(implement_app_postgres_resource())
    return out


def implement_app_postgres_resource() -> dict:
    return {"name": IMPLEMENT_LAKEBASE_RESOURCE, "postgres": {"branch": IMPLEMENT_LAKEBASE_BRANCH,
                                                              "database": IMPLEMENT_LAKEBASE_DATABASE_RESOURCE,
                                                              "permission": "CAN_CONNECT_AND_CREATE"}}


IMPLEMENT_APP_YAML = "app.yaml"
IMPLEMENT_APP_WAREHOUSE_RESOURCE = "sql-warehouse"
IMPLEMENT_APP_POSTGRES_ENV = ("PGAPPNAME", "PGDATABASE", "PGHOST", "PGPORT", "PGSSLMODE", "PGUSER")
IMPLEMENT_LAKEBASE_APP_ENV = {"name": "LAKEBASE_ENDPOINT", "valueFrom": IMPLEMENT_LAKEBASE_RESOURCE}
IMPLEMENT_APP_ENV_ENTRY = re.compile(r"^[ ]*-[ ]*name:[ ]*([A-Za-z_][A-Za-z0-9_]*)[ ]*\n[ ]*(value|valueFrom):[ ]*(\S[^\n]*?)[ ]*$", re.M)


def implement_app_yaml_env(text) -> list:
    return [{"name": name, kind: value.strip("'\"")} for name, kind, value in IMPLEMENT_APP_ENV_ENTRY.findall(str(text or ""))]


def implement_app_yaml(text, lakebase: bool) -> str:
    text = str(text or "")
    if not lakebase or IMPLEMENT_LAKEBASE_APP_ENV in implement_app_yaml_env(text):
        return text
    if not re.search(r"^env:[ ]*$", text, re.M):
        text = text.rstrip("\n") + "\nenv:\n"
    return (text.rstrip("\n") + f"\n  - name: {IMPLEMENT_LAKEBASE_APP_ENV['name']}\n"
            f"    valueFrom: {IMPLEMENT_LAKEBASE_APP_ENV['valueFrom']}\n")


def implement_app_runtime_env(text, resolved: dict, injected: dict) -> dict:
    env = dict(injected or {})
    for entry in implement_app_yaml_env(text):
        if "value" in entry:
            env[entry["name"]] = entry["value"]
        elif entry["valueFrom"] in (resolved or {}):
            env[entry["name"]] = resolved[entry["valueFrom"]]
    return env


def implement_app_holds_postgres(resources) -> bool:
    wanted = implement_app_postgres_resource()["postgres"]
    return any(isinstance(r, dict) and isinstance(r.get("postgres"), dict) and r.get("name") == IMPLEMENT_LAKEBASE_RESOURCE
               and all(str(r["postgres"].get(k) or "") == v for k, v in wanted.items() if k != "permission")
               for r in resources or [])


class ImplementLakebaseUnavailable(Exception):
    pass


class ImplementAppCheckStopped(RuntimeError):
    pass


IMPLEMENT_LAKEBASE_PROJECT_FIX = "run the Inspire installer again, which gives it Can Manage on that project"
IMPLEMENT_LAKEBASE_CALLS = {
    "projects": ("list the Lakebase projects of this workspace", "no permission to use Lakebase in this workspace",
                 "ask a workspace admin to let it use Lakebase"),
    "project": (f"read the Lakebase project {IMPLEMENT_LAKEBASE_PROJECT}", "no Can Use or Can Manage on that project",
                IMPLEMENT_LAKEBASE_PROJECT_FIX),
    "create_project": (f"create the Lakebase project {IMPLEMENT_LAKEBASE_PROJECT}", "no right to create Lakebase projects in this workspace",
                       "run the Inspire installer again, which creates the project and gives it Can Manage on it"),
    "endpoint": (f"read the database endpoint of the Lakebase project {IMPLEMENT_LAKEBASE_PROJECT}", "no Can Use or Can Manage on that project",
                 IMPLEMENT_LAKEBASE_PROJECT_FIX),
    "catalog": (f"read the catalog {IMPLEMENT_LAKEBASE_CATALOG}", "no USE CATALOG on it",
                f"run the Inspire installer again as an owner of the catalog {IMPLEMENT_LAKEBASE_CATALOG}, which grants it ALL PRIVILEGES on it"),
    "create_catalog": (f"create the catalog {IMPLEMENT_LAKEBASE_CATALOG}", "no CREATE CATALOG on the metastore",
                       f"run the Inspire installer again as someone with CREATE CATALOG on the metastore, which creates the catalog "
                       f"{IMPLEMENT_LAKEBASE_CATALOG} on the Lakebase project {IMPLEMENT_LAKEBASE_PROJECT} and grants it ALL PRIVILEGES on it"),
}


def implement_lakebase_refused(call: str, builder: str = "") -> str:
    what, missing, fix = IMPLEMENT_LAKEBASE_CALLS[call]
    who = f"the identity Inspire runs as ({builder})" if builder else "the identity Inspire runs as"
    return f"Databricks refused to {what}, because {who} has {missing}; {fix}"


def implement_lakebase_unavailable(error) -> str:
    code = str(getattr(error, "error_code", "") or "")
    if implement_is_not_found(error) or code in ("FEATURE_DISABLED", "NOT_IMPLEMENTED"):
        return "Lakebase is not available in this workspace"
    return f"Lakebase did not answer: {redact_error(error)[:300]}"


def implement_lakebase_schema_statement(synced: str, builder: str = "") -> str:
    # PERMISSION_DIALOG: the GRANT the Permission Required dialog copies (REQ-131, REQ-260); the prose above never shows it
    catalog = str(synced).split(".")[0]
    return f"GRANT ALL PRIVILEGES ON CATALOG {inspire_quote_identifier(catalog)} TO {inspire_quote_principal(builder)}" if builder else ""


def implement_lakebase_schema_denied(synced: str, builder: str = "") -> str:
    catalog, schema = str(synced).split(".")[:2]
    ask = ("ask your data owner to grant the identity ALL PRIVILEGES on that catalog: the exact command is in Permission Required" if builder else
           "ask your data owner to give the identity Inspire runs as ALL PRIVILEGES on that catalog")
    return (f"the identity Inspire runs as cannot add tables to the Lakebase schema {catalog}.{schema}; run the Inspire installer "
            f"again as an owner of the catalog {catalog}, or {ask}")


def implement_lakebase_ident(name: str) -> str:
    name = str(name)
    return name if re.fullmatch(r"[a-z_][a-z0-9_]*", name) else '"' + name.replace('"', '""') + '"'


def implement_audience_grant_why(name: str) -> str:
    # REQ-226: who runs the grants and who receives them, in plain words. The grants go to the audience group itself: a
    # user-authorization App reads its views with the opener's own access, so each person in the group needs the grant.
    return (f"These commands give {name} read access to the Data Filters view that the App "
            "reads with each person's own access.")


# REQ-408: the one rule for the read grants a Permission Required dialog names (the Python mirror of backend/lib/grantScope.js, the same
# fixture). A read grant on a table collapses to its schema; USE CATALOG and USE SCHEMA are named once; a whole-catalog pick asks at catalog
# level. Write grants, warehouse steps and Lakebase (double-quoted Postgres) statements pass through exactly.
INSPIRE_GRANT_LINE = re.compile(r"^GRANT\s+(.+?)\s+ON\s+(CATALOG|SCHEMA|TABLE)\s+(.+?)\s+TO\s+(.+?);?$", re.I)
INSPIRE_UC_NAME_PART = re.compile(r"^(?:`[^`.]+`|[A-Za-z0-9_-]+)$")
INSPIRE_UC_NAME_SHAPE = {"CATALOG": 1, "SCHEMA": 2, "TABLE": 3}
INSPIRE_READ_PRIVILEGES = ("SELECT", "READ_METADATA")


def inspire_coarse_grants(statements, whole_catalogs=()) -> list:
    whole = {str(c or "").replace("`", "").strip().lower() for c in whole_catalogs or () if str(c or "").replace("`", "").strip()}
    out = {}
    for raw in statements or []:
        statement = str(raw or "").strip()
        if not statement:
            continue
        hit = INSPIRE_GRANT_LINE.match(statement)
        privilege = re.sub(r"\s+", "_", hit.group(1).strip().upper()) if hit else ""
        level = hit.group(2).upper() if hit else ""
        parts = None
        if hit:
            words = [w.strip() for w in hit.group(3).split(".")]
            if len(words) == INSPIRE_UC_NAME_SHAPE[level] and all(INSPIRE_UC_NAME_PART.match(w) for w in words):
                parts = [w.replace("`", "") for w in words]
        is_read = ((privilege in INSPIRE_READ_PRIVILEGES and level == "TABLE") or (privilege == "USE_SCHEMA" and level == "SCHEMA")
                   or (privilege in INSPIRE_READ_PRIVILEGES and level == "SCHEMA") or (privilege == "USE_CATALOG" and level == "CATALOG"))
        if not hit or not parts or not is_read:
            out.setdefault(f"raw|{statement}", statement)
            continue
        principal = hit.group(4).strip()
        who = principal.replace("`", "").strip().lower()
        catalog, schema = parts[0], (parts[1] if len(parts) > 1 else "")
        use_catalog = f"{who}|USE_CATALOG|{catalog.lower()}"
        if privilege == "USE_CATALOG":
            out.setdefault(use_catalog, f"GRANT USE CATALOG ON CATALOG `{catalog}` TO {principal}")
            continue
        if catalog.lower() in whole:
            out.setdefault(use_catalog, f"GRANT USE CATALOG ON CATALOG `{catalog}` TO {principal}")
            if privilege in INSPIRE_READ_PRIVILEGES:
                out.setdefault(f"{who}|{privilege}|catalog|{catalog.lower()}", f"GRANT {privilege.replace('_', ' ')} ON CATALOG `{catalog}` TO {principal}")
            continue
        if privilege == "USE_SCHEMA":
            out.setdefault(f"{who}|USE_SCHEMA|{catalog.lower()}.{schema.lower()}", f"GRANT USE SCHEMA ON SCHEMA `{catalog}`.`{schema}` TO {principal}")
            continue
        out.setdefault(f"{who}|{privilege}|schema|{catalog.lower()}.{schema.lower()}",
                       f"GRANT {privilege.replace('_', ' ')} ON SCHEMA `{catalog}`.`{schema}` TO {principal}")
    return list(out.values())


def implement_permission_entry(principal: str, statements, why: str, exact: bool = False) -> dict:
    # The Permission Required entry the Build page raises: the fields the App's permission payload already carries. REQ-408: the read
    # grants are asked at schema level here, the one choke point every notebook dialog entry passes. `exact` keeps table-level grants:
    # a viewer of a user-authorization App gets its views only, and a schema grant would open the source tables beside them.
    named = [s for s in statements if s]
    return {"statements": named if exact else inspire_coarse_grants(named), "instructions": [], "principal": principal, "why": why}


def implement_list_permission(permissions: list, principal: str, denied, why: str, exact: bool = False) -> None:
    # One Permission Required entry per principal and reason. A pass replaces the entry an earlier pass wrote for it, and drops it when this
    # pass runs clean, so the list shows only the refusals that still stand (REQ-268).
    permissions[:] = [p for p in permissions if (p.get("principal"), p.get("why")) != (principal, why)]
    if denied:
        permissions.append(implement_permission_entry(principal, denied, why, exact))


def implement_lakebase_role(name: str) -> str:
    return '"' + str(name).replace('"', '""') + '"'


class ImplementLakebasePermission(ImplementLakebaseUnavailable):
    def __init__(self, said: str, statement: str):
        super().__init__(said)
        self.statement = statement


IMPLEMENT_LAKEBASE_REFUSAL_RE = re.compile(r"(?:permission denied for|must be owner of) (database|schema|table|relation|sequence|view) "
                                           r"([^\s\"]+)", re.IGNORECASE)
IMPLEMENT_LAKEBASE_REFUSAL_SCOPE = {"schema": "SCHEMA", "database": "DATABASE", "sequence": "SEQUENCE"}


def implement_lakebase_refusal(error, builder: str = ""):
    """A Postgres permission refusal as the one statement its owner runs, or None when the error is not a permission refusal. With no
    identity to grant to, the statement is empty: a GRANT to a placeholder role is not one the owner can run."""
    if isinstance(error, ImplementLakebasePermission):
        return ImplementLakebasePermission(redact_error(error), error.statement)
    hit = IMPLEMENT_LAKEBASE_REFUSAL_RE.search(redact_error(error))
    if not hit:
        return None
    kind, name = hit.group(1).lower(), hit.group(2).rstrip(".")
    who = f"the identity Inspire runs as ({builder})" if builder else "the identity Inspire runs as"
    role = implement_lakebase_role(builder) if builder else ""
    if kind == "database":
        grant = f"GRANT CREATE ON DATABASE {implement_lakebase_ident(name)} TO {role}" if builder else ""
        return ImplementLakebasePermission(f"{who} cannot create objects in the database {name}, which only its owner or a "
                                           "databricks_superuser can grant", grant)
    target = ".".join(implement_lakebase_ident(part) for part in name.split("."))
    scope = IMPLEMENT_LAKEBASE_REFUSAL_SCOPE.get(kind, "TABLE")
    grant = f"GRANT ALL PRIVILEGES ON {scope} {target} TO {role}" if builder else ""
    return ImplementLakebasePermission(f"{who} has no rights on the Lakebase {kind} {name}", grant)


def implement_lakebase_permission_entry(error, builder: str = ""):
    """The Permission Required entry for a Lakebase permission refusal (its exact GRANT), or None when the error is not one."""
    refusal = implement_lakebase_refusal(error, builder)
    if not isinstance(refusal, ImplementLakebasePermission) or not refusal.statement:
        return None
    return {**implement_permission_entry(builder, [refusal.statement],
                                      f"Optional: pages load faster with Lakebase. Until then the App reads Delta tables: {refusal.args[0]}."), "optional": True}


def implement_lakebase_column(name: str, text: str) -> dict:
    text = " ".join(str(text or "").split())
    head = re.split(r"[<(\s]", text.lower(), maxsplit=1)[0]
    return {"name": str(name), "type": IMPLEMENT_LAKEBASE_TYPES.get(head, head.upper()), "type_text": text.upper()}


def implement_lakebase_schema(app_name: str) -> str:
    return re.sub(r"[^a-z0-9_]", "_", str(app_name or "").lower())[:63]


def implement_lakebase_copies(pages, row: str, shell_sql, columns, logs=None, histories=None) -> list:
    out = []
    for page in pages:
        result_table = ".".join(inspire_table_parts(page["result_table"]))
        out.append({"page": page["id"], "dataset": "", "role": "current", "key": inspire_companion(result_table, "__lb"), "result_table": result_table,
                    "suffix": "__lb", "view": inspire_companion(result_table, "__lb"),
                    "body": f"SELECT * FROM {inspire_table_name(result_table)} WHERE {INSPIRE_CURRENT_ROWS}"})
        if (logs or {}).get(result_table) == inspire_run_log_table(result_table):
            out.append({"page": page["id"], "dataset": "", "role": "changes", "key": inspire_companion(result_table, "__lb_changes"),
                        "result_table": result_table, "suffix": "__lb_changes", "view": inspire_companion(result_table, "__lb_changes"),
                        "body": f"SELECT * FROM {inspire_table_name(inspire_run_log_table(result_table))} WHERE run_id = (SELECT run_id "
                                f"FROM {inspire_table_name(inspire_run_log_table(result_table))} GROUP BY run_id ORDER BY MIN(ran_at) DESC "
                                "LIMIT 1)"})
        for dataset in page.get("datasets") or []:
            suffix = f"__lb_{dataset['name']}"
            out.append({"page": page["id"], "dataset": dataset["name"], "key": inspire_companion(result_table, suffix), "result_table": result_table,
                        "suffix": suffix, "view": inspire_companion(result_table, suffix), "body": str(dataset["sql"])})
        for name in dict.fromkeys(k["dataset"] for k in page.get("kpis") or [] if k.get("compare")):
            body = shell_sql.previous_rows(page, name, (columns or {}).get(result_table.lower()),
                                           (histories or {}).get(result_table.lower()))
            if body:
                suffix = f"__lbp_{name}"
                out.append({"page": page["id"], "dataset": name, "previous": True, "key": inspire_companion(result_table, suffix),
                            "result_table": result_table, "suffix": suffix, "view": inspire_companion(result_table, suffix), "body": body})
    for copy in out:
        copy["sql"] = implement_lakebase_view_sql(copy["result_table"], copy["suffix"], copy["body"], row)
    return out


def implement_lakebase_view_sql(result_table: str, suffix: str, body: str, row: str, exclude=()) -> str:
    keep = f"d.* EXCEPT ({', '.join(inspire_quote_identifier(c) for c in exclude)})" if exclude else "d.*"
    return inspire_owned_view_sql(inspire_companion(result_table, suffix), f"SELECT {keep}, monotonically_increasing_id() AS "
            f"`{row}` FROM ({str(body).strip().rstrip(';')}) AS d")


def implement_lakebase_mapping_copy(result_table: str, map_name: str, row: str) -> dict:
    suffix = "__lbm_" + hashlib.sha256(str(map_name).lower().encode()).hexdigest()[:8]
    body = f"SELECT * FROM {inspire_table_name(map_name)}"
    return {"page": "m" + suffix[-8:], "dataset": "", "role": "mapping", "key": inspire_companion(result_table, suffix), "result_table": result_table,
            "suffix": suffix, "view": inspire_companion(result_table, suffix), "body": body, "sql": implement_lakebase_view_sql(result_table, suffix, body, row)}


def implement_lakebase_enforced(copies: list, plans: dict, row: str) -> list:
    out, mappings = [], {}
    for copy in copies:
        plan = plans.get(copy["result_table"].lower()) or {}
        if not plan.get("enforced"):
            continue
        entries = []
        for one in plan.get("enforce") or []:
            mapping = implement_lakebase_mapping_copy(copy["result_table"], one["map"], row)
            mappings.setdefault(mapping["key"], mapping)
            entries.append(dict(one, mapping=mapping["key"]))
        out.append(dict(copy, enforced=True, masked=list(plan.get("masked") or []), enforce=entries or None))
    return out + list(mappings.values())


def implement_lakebase_masked_datasets(copies: list) -> list:
    out = []
    for copy in copies:
        if not copy.get("enforced") or copy.get("role") == "mapping" or not copy.get("dataset"):
            continue
        body = str(copy.get("body") or "")
        named = [c for c in copy.get("masked") or [] if re.search(rf"(?<![A-Za-z0-9_]){re.escape(c)}(?![A-Za-z0-9_])", body, re.I)]
        if named:
            out.append(dict(copy, reads_masked=named))
    return out


def implement_lakebase_app_entries(copies: list) -> list:
    by_key = {copy["key"]: copy for copy in copies}
    out = []
    for copy in copies:
        if not copy.get("enforced") or copy.get("role") == "mapping":
            continue
        enforce = copy["enforce"]
        view_enforce = None if enforce is None else [
            {"column": one["column"], "map": by_key[one["mapping"]]["pg"], "key": one["key"], "principal": one["principal"]}
            for one in enforce]
        out.append({"key": copy["key"], "pg": copy["app_pg"], "base": copy["pg"], "columns": copy["columns"], "enforce": view_enforce})
    return out


def implement_lakebase_plan_notes(plans: dict) -> list:
    return [f"{IMPLEMENT_OUTPUT_LABELS['app']}: {table} uses Standard pages, not Fast pages, because {plan['reason']}"
            + (f". Inspire asks the next build: {plan['ask']}" if plan.get("ask") else "")
            for table, plan in sorted(plans.items()) if not plan.get("enforced")]


def implement_lakebase_pg_table(copy: dict, columns: list) -> str:
    digest = hashlib.sha256(json.dumps([[c["name"], c["type_text"]] for c in columns]).encode()).hexdigest()[:8]
    base = (f"{copy['page']}__{'p' if copy.get('previous') else 'd'}_{copy['dataset']}" if copy["dataset"] else
            f"{copy['page']}__c" if copy.get("role") == "changes" else f"{copy['page']}__t")
    return f"{re.sub(r'[^a-z0-9_]', '_', base.lower())[:54]}_{digest}"


def implement_lakebase_type_problems(copy: dict, columns: list) -> list:
    bad = [c["name"] for c in columns if c["type"] in IMPLEMENT_LAKEBASE_UNSUPPORTED]
    what = f"dataset {copy['dataset']} of page {copy['page']}" if copy["dataset"] else copy["key"]
    return [f"{what} has columns Lakebase cannot hold: {', '.join(bad)}"] if bad else []


def implement_lakebase_backend(pipeline_id: str, copies: list, indexed=None) -> dict:
    tables, datasets, previous, roles = {}, {}, {}, {"current": {}, "changes": {}}
    apps = {entry["key"]: entry for entry in implement_lakebase_app_entries(copies)}
    for copy in copies:
        if copy.get("role") == "mapping":
            continue
        base = dict({"pg": copy["pg"], "columns": copy["columns"]}, **(indexed or {}).get(copy["key"], {}))
        entry = apps.get(copy["key"])
        tables[copy["key"]] = dict(base, pg=entry["pg"], base=entry["base"], enforce=entry["enforce"]) if entry else base
        if copy["dataset"]:
            (previous if copy.get("previous") else datasets).setdefault(copy["page"], {})[copy["dataset"]] = copy["key"]
        elif copy.get("role") in roles:
            roles[copy["role"]][copy["result_table"]] = copy["key"]
    out = {"kind": IMPLEMENT_APP_BACKENDS[0], "pipeline_id": pipeline_id, "tables": tables, "datasets": datasets, "previous": previous, **roles}
    if apps:
        out["enforced"] = True
    return out


def implement_lakebase_choice_columns(copy: dict, page: dict, shell_sql) -> list:
    if not copy.get("dataset"):
        return []
    read = [(f.get("columns") or {}).get(copy["dataset"]) for f in page.get("filters") or []]
    if not copy.get("previous"):
        found = []
        for types in ({c["name"]: c["type"] for c in copy.get("columns") or []}, None):
            found += shell_sql.list_column_filters(page, types) if copy["dataset"] == shell_sql.RECORDS_DATASET else []
            for table in page.get("tables") or []:
                if table.get("dataset") == copy["dataset"]:
                    found += shell_sql.table_column_filters(table, types)
        read += [f["column"] for f in found if f["type"] == "multi_select"]
    return list(dict.fromkeys(c for c in read if c))


def implement_lakebase_index_columns(copies: list, pages, shell_sql) -> list:
    by_page = {page["id"]: page for page in pages or []}
    out = []
    for copy in copies:
        names = {c["name"] for c in copy.get("columns") or []}
        records = (by_page.get(copy["page"]) or {}).get("records") or {}
        if copy.get("role") == "current":
            wanted = [("record_key",), (inspire_shell_facts.MONEY_COLUMN,)]
        elif copy.get("role") == "changes":
            wanted = [("record_key",)]
        elif copy["dataset"] == "records":
            tie = "record_key" if "record_key" in names else records.get("key")
            sorts = [records.get(k) for k in ("rank", "label", "tier")] + [c.get("column") for c in records.get("columns") or []]
            wanted = [(tie,)] + [(c, tie) if c != tie else (c,) for c in dict.fromkeys(s for s in sorts if s)]
        else:
            wanted = []
        chosen = implement_lakebase_choice_columns(copy, by_page.get(copy["page"]) or {}, shell_sql)
        wanted += [(c,) for c in chosen if not any(w and w[0] == c for w in wanted)]
        out += [(copy, columns) for columns in wanted if all(c and c in names for c in columns)]
    return out


def implement_lakebase_index_form(column: dict) -> str:
    kind = str(column.get("type") or "").upper()
    return "plain" if kind in IMPLEMENT_LAKEBASE_INDEX_BOUNDED else "prefix" if kind in IMPLEMENT_LAKEBASE_INDEX_TEXT else ""


def implement_lakebase_index_texts(wanted: list) -> dict:
    out = {}
    for copy, columns in wanted:
        held = {c["name"]: c for c in copy.get("columns") or []}
        names = out.setdefault(copy["key"], (copy, []))[1]
        names += [c for c in columns if implement_lakebase_index_form(held[c]) == "prefix" and c not in names]
    return {key: (copy, names) for key, (copy, names) in out.items() if names}


def implement_lakebase_index_plan(wanted: list, lengths: dict) -> tuple:
    planned, skipped, seen = [], [], set()
    for copy, columns in wanted:
        held, kept = {c["name"]: c for c in copy.get("columns") or []}, []
        for name in columns:
            form, measured = implement_lakebase_index_form(held[name]), lengths.get(copy["key"], {})
            longest = int((measured or {}).get(name) or 0)
            why = ("" if form == "plain" else
                   f"its type {held[name]['type']} has no bounded size, so an index on it could fail a later sync" if not form else
                   "Inspire could not read how long its values are" if measured is None else
                   f"it holds values of up to {longest:,} bytes, so it is free text, not a short category"
                   if longest > IMPLEMENT_LAKEBASE_INDEX_PREFIX else "")
            if why:
                if (copy["key"], name) not in seen:
                    seen.add((copy["key"], name))
                    skipped.append((copy, name, why))
                break
            kept.append((name, form))
        if kept and (copy["key"], tuple(kept)) not in seen:
            seen.add((copy["key"], tuple(kept)))
            planned.append((copy, kept))
    return planned, skipped


def implement_lakebase_index_name(copy: dict, kept: list) -> str:
    parts = [name if form == "plain" else f"left({name},{IMPLEMENT_LAKEBASE_INDEX_PREFIX})" for name, form in kept]
    return "ix_" + hashlib.sha256(f"{copy['pg']}|{'|'.join(parts)}".encode()).hexdigest()[:16]


def implement_lakebase_index_sql(copy: dict, kept: list):
    from psycopg import sql
    schema, table = copy["pg"].split(".", 1)
    keys = [sql.Identifier(name) if form == "plain" else
            sql.SQL("(left({}, {}))").format(sql.Identifier(name), sql.Literal(IMPLEMENT_LAKEBASE_INDEX_PREFIX)) for name, form in kept]
    return sql.SQL("CREATE INDEX IF NOT EXISTS {} ON {}.{} ({})").format(
        sql.Identifier(implement_lakebase_index_name(copy, kept)), sql.Identifier(schema), sql.Identifier(table), sql.SQL(", ").join(keys))


def implement_lakebase_length_sql(copy: dict, names: list):
    from psycopg import sql
    schema, table = copy["pg"].split(".", 1)
    return sql.SQL("SELECT {} FROM {}.{}").format(sql.SQL(", ").join(sql.SQL("MAX(OCTET_LENGTH({}))").format(sql.Identifier(n)) for n in names),
                                                 sql.Identifier(schema), sql.Identifier(table))


def implement_lakebase_index_key(name: str, form: str) -> str:
    return name if form == "plain" else f"{name} (its first {IMPLEMENT_LAKEBASE_INDEX_PREFIX} characters)"


def implement_lakebase_byte_ordered(collname, provider, collcollate, datcollate, datprovider) -> bool:
    if str(collname or "default") == "default":
        return str(datprovider or "c") != "i" and str(datcollate or "").lower() in IMPLEMENT_LAKEBASE_BYTE_ORDER
    if str(provider or "") == "i":
        return False
    return (str(collname).lower() in IMPLEMENT_LAKEBASE_BYTE_ORDER
            or (str(provider or "") == "c" and str(collcollate or "").lower() in IMPLEMENT_LAKEBASE_BYTE_ORDER))


def implement_lakebase_indexed(planned: list, held, ordered=()) -> dict:
    out = {}
    for copy, kept in planned:
        if (copy["pg"].split(".", 1)[0], implement_lakebase_index_name(copy, kept)) not in held:
            continue
        (name, form), entry = kept[0], out.setdefault(copy["key"], {})
        if form == "plain" and name not in entry.setdefault("indexed", []):
            entry["indexed"].append(name)
        elif form == "prefix":
            entry.setdefault("prefixed", {})[name] = IMPLEMENT_LAKEBASE_INDEX_PREFIX
            if (copy["pg"], name) in ordered and name not in entry.setdefault("prefix_ordered", []):
                entry["prefix_ordered"].append(name)
    for entry in out.values():
        for name in ("indexed", "prefix_ordered"):
            if not entry.get(name, True):
                entry.pop(name)
    return out


def implement_lakebase_pg_names(backend) -> set:
    if not isinstance(backend, dict) or backend.get("kind") != IMPLEMENT_APP_BACKENDS[0]:
        return set()
    return {str(entry.get("pg") or "") for entry in (backend.get("tables") or {}).values() if isinstance(entry, dict)} - {""}


def implement_app_access_of(outputs: dict, host: dict):
    held = (host.get("settings") or {}) if host.get("merged") else {}
    return held.get("auth") if host.get("merged") else (outputs or {}).get("app_access")


def implement_app_wanted_backend(outputs: dict, host: dict) -> tuple:
    held = (host.get("settings") or {}) if host.get("merged") else {}
    backend = held.get("backend") if host.get("merged") else {"kind": (outputs or {}).get("app_backend")}
    kind = (backend or {}).get("kind") if (backend or {}).get("kind") in IMPLEMENT_APP_BACKENDS else IMPLEMENT_APP_BACKENDS[-1]
    access = implement_app_access_of(outputs, host)
    if kind == IMPLEMENT_APP_BACKENDS[0] and access not in IMPLEMENT_APP_ACCESS:
        return IMPLEMENT_APP_BACKENDS[-1], f"{IMPLEMENT_OUTPUT_LABELS['app']}: it reads Delta tables, because its access is not one Inspire knows"
    return kind, ""


IMPLEMENT_APP_SPEED_LABELS = {"first": "the decision list's first records", "filter": "a filter change"}
IMPLEMENT_APP_SPEED_STEP = "App speed"


def implement_app_speed_seen(speeds) -> list:
    return [(page, seen) for page, seen in sorted((speeds or {}).items()) if page != "_error" and isinstance(seen, dict)]


def implement_app_speed_problems(speeds, backend: str) -> list:
    if not isinstance(speeds, dict):
        return [f"{IMPLEMENT_OUTPUT_LABELS['app']}: on {backend}, the speed check did not run, so Inspire cannot show the App answers within its targets"]
    out = [f"{IMPLEMENT_OUTPUT_LABELS['app']}: on {backend}, the speed check could not run: {speeds['_error']}"] if speeds.get("_error") else []
    for _page, seen in implement_app_speed_seen(speeds):
        for name in IMPLEMENT_APP_SPEED_TARGETS:
            spent, target = seen.get(name), IMPLEMENT_APP_SPEED_TARGETS[name]
            label = IMPLEMENT_APP_SPEED_LABELS[name] + (f" ({seen.get('filter_on')}, 2 values)" if name == "filter" else "")
            if isinstance(spent, (int, float)) and spent > target:
                out.append(f"{IMPLEMENT_OUTPUT_LABELS['app']}: on {backend}, {label} took {spent:.1f} s on the real tables at the default filters, over the "
                           f"{target:.0f} s target")
    return out


def implement_app_speed_text(speeds, backend: str) -> str:
    shown = []
    for page, seen in implement_app_speed_seen(speeds):
        parts = [f"{IMPLEMENT_APP_SPEED_LABELS[name]} {seen[name]:.1f} s (target {IMPLEMENT_APP_SPEED_TARGETS[name]:.0f} s)"
                 for name in IMPLEMENT_APP_SPEED_TARGETS if isinstance(seen.get(name), (int, float))]
        reads = len(((seen.get("runs") or {}).get("first")) or [])
        if parts:
            shown.append(f"{page}: " + ", ".join(parts) + (f", the middle of {reads} reads with no cache" if reads > 1 else ""))
    return f"App speed on {backend}: " + "; ".join(shown) if shown else ""


def implement_lakebase_size(rows: int, size: int, total: int, capacity: float) -> str:
    shown = int(size * rows / total) if total else int(size)
    rows_cap, bytes_cap = int(IMPLEMENT_LAKEBASE_ROWS_PER_CU * capacity), int(IMPLEMENT_LAKEBASE_BYTES_PER_CU * capacity)
    if rows <= rows_cap and shown <= bytes_cap:
        return ""
    return (f"{IMPLEMENT_OUTPUT_LABELS['app']}: it reads Delta tables, not Lakebase: the current records in its result table number {rows:,} ({shown / 1e9:.1f} GB), and Lakebase "
            f"at its {inspire_plural(capacity, 'capacity unit')} answers the App's first records within {IMPLEMENT_APP_SPEED_TARGETS['first']:.0f} s and a "
            f"filter change within {IMPLEMENT_APP_SPEED_TARGETS['filter']:.0f} s for at most {rows_cap:,} records ({bytes_cap / 1e9:.1f} GB). "
            f"Raise the Lakebase capacity of the {IMPLEMENT_LAKEBASE_PROJECT} project, or keep the App on Delta tables")


IMPLEMENT_LAKEBASE_QUOTA_RE = re.compile(r"QUOTA_EXCEEDED|estimated count: \d+, limit: \d+", re.IGNORECASE)
IMPLEMENT_LAKEBASE_QUOTA_STEP = ("The metastore already holds as many catalogs as Databricks allows: a metastore admin drops the catalogs no one "
                                 "uses, or asks Databricks support to raise the limit, and runs the Inspire workspace installer again. Then")


def implement_lakebase_fallback(reason: str, statement: str = "") -> str:
    said = inspire_redact_text(" ".join(str(reason).split()), set(), "")[:600].rstrip(". ")
    if statement:
        return (f"{IMPLEMENT_OUTPUT_LABELS['app']}: it reads Delta tables, so its pages take a few seconds to load, because Inspire could not set up Lakebase: {said}. "
                f"Ask the Lakebase project owner to grant the access listed under Permission Required, then {inspire_rebuild_action('the App')} to switch it to Lakebase")
    rebuild = (f"{IMPLEMENT_LAKEBASE_QUOTA_STEP} {inspire_rebuild_action('the App')}" if IMPLEMENT_LAKEBASE_QUOTA_RE.search(str(reason))
               else inspire_rebuild_action("the App", first=True))
    return (f"{IMPLEMENT_OUTPUT_LABELS['app']}: it reads Delta tables, so its pages take a few seconds to load, because Inspire could not set up Lakebase: "
            f"{said}. {rebuild}, to switch it to Lakebase")


IMPLEMENT_NAV_MODE_BY_CONTRACT = {"plan": "plan", "forecast": "forecast", "scenario": "scenarios"}
IMPLEMENT_NAV_MODE_BY_LAYOUT = {"dashboard": "explore", "agent_chat": "ask"}
IMPLEMENT_NAV_LABELS = {"queue": ("Work", "Performance"), "plan": ("Plan", "Performance"), "forecast": ("Review", "Accuracy"),
                        "scenarios": ("Scenarios", "Performance"), "explore": ("Explore", "Usage"), "ask": ("Ask", "Answer quality")}
IMPLEMENT_NAV_REMOVE_RE = re.compile(r"^(?:please\s+)?(?:remove|drop|hide|take out|delete|get rid of)\s+(?:the\s+)?(.+?)"
                                     r"(?:\s+(?:page|screen|tab|section|view))?"
                                     r"(?:\s+(?:from|in|on|of)\s+(?:this\s+|our\s+|the\s+)?(?:app|dashboard|page|screen|tab|section|view)s?)?\s*[.!]*$", re.IGNORECASE)
IMPLEMENT_LAYOUT_CORE = ("todo", "kpis")
IMPLEMENT_NAV_STAYS = f"{{label}} is the {IMPLEMENT_OUTPUT_LABELS['app']}'s main part, so it stays in every {IMPLEMENT_OUTPUT_LABELS['app']}: remove a page, tab or Runs instead"


def implement_app_mode(layout_id) -> str:
    layout = _inspire_layout(layout_id) or {}
    return IMPLEMENT_NAV_MODE_BY_LAYOUT.get(layout_id) or IMPLEMENT_NAV_MODE_BY_CONTRACT.get(layout.get("contract"), "queue")


def implement_app_removals(asks_text, layout_id) -> tuple:
    layout = _inspire_layout(layout_id) or {}
    work, performance = IMPLEMENT_NAV_LABELS[implement_app_mode(layout_id)]
    items = {"work": work, "performance": performance, "runs": "Runs", "dashboard": "Dashboard", "settings": "Settings"}
    by_label = {label.lower(): key for key, label in items.items()}
    kept = set(layout.get("min_items") or {}) | set(IMPLEMENT_LAYOUT_CORE)
    sections = {name.replace("_", " "): name for name in layout.get("sections") or [] if name not in kept}
    ids, removed_sections, notes = [], [], []
    for ask in implement_vibe_asks(asks_text):
        match = IMPLEMENT_NAV_REMOVE_RE.match(ask)
        if not match:
            continue
        said = " ".join(match.group(1).split())
        base = re.sub(r"\s+(?:chart|table|tile)$", "", said.lower())
        key = by_label.get(said.lower())
        section = sections.get(said.lower()) or sections.get(base)
        if key in ("performance", "runs"):
            if key not in ids:
                ids.append(key)
        elif key:
            notes.append(IMPLEMENT_NAV_STAYS.format(label=items[key]))
        elif section:
            if section not in removed_sections:
                removed_sections.append(section)
        elif said.lower().replace(" ", "_") in kept or said.lower() in {k.replace("_", " ") for k in kept}:
            notes.append(f"{said} is required by the {layout.get('label') or IMPLEMENT_OUTPUT_LABELS['app']} layout, so it stays")
        else:
            names = list(items.values()) + [name.replace("_", " ") for name in sections.values()]
            notes.append(f"the App has no nav item or section named {said}: it has {', '.join(names)}")
    return ids, [items[key] for key in ids], removed_sections, notes


def implement_removed_section_uses(page, removed) -> list:
    items = [item for key in ("charts", "tables") for item in (page.get(key) or []) if isinstance(item, dict)] if isinstance(page, dict) else []
    return sorted({str(item.get("section")) for item in items if item.get("section") in removed})


