def implement_paths_overlap(first, second) -> bool:
    a, b = (os.path.normpath(canonical_workspace_path(path)) if str(path or "").strip() else "" for path in (first, second))
    return bool(a and b) and (a == b or a.startswith(b.rstrip("/") + "/") or b.startswith(a.rstrip("/") + "/"))


