def implement_app_page_tables(files, wanted) -> set:
    out = set()
    for name, text in (files or {}).items():
        if not (str(name).startswith(f"{IMPLEMENT_APP_PAGES_DIR}/") and str(name).endswith(".json")):
            continue
        try:
            page = json.loads(text)
        except (TypeError, ValueError):
            continue
        if isinstance(page, dict) and page.get("result_table") and wanted(page):
            out.add(str(page["result_table"]))
    return out


