IMPLEMENT_DEFAULT_RANGE = "default_range"


def implement_default_ranges(meta: dict) -> dict:
    """The default date range of each date filter the App check read: {filter id: {"low", "high"}} as ISO dates, for the publish to
    store in the page spec, so the App's first load never waits on a scan of the table's dates."""
    return {str(f["id"]): {"low": str(f["low"])[:10], "high": str(f["high"])[:10]} for f in meta.get("filters") or []
            if f.get("type") == "date_range" and f.get("low") is not None and f.get("high") is not None}


def implement_app_default_ranges(files: dict, pages_dir: str, ranges: dict) -> dict:
    """The files with each page's stored default date range written into its page spec. A page the check did not read keeps its spec."""
    out = dict(files)
    for ident, found in (ranges or {}).items():
        name = f"{pages_dir}/{ident}.json"
        if found and name in out:
            page = json.loads(out[name])
            page[IMPLEMENT_DEFAULT_RANGE] = found
            out[name] = json.dumps(page, indent=2, ensure_ascii=False) + "\n"
    return out


IMPLEMENT_APP_STATIC = "static"


def implement_image_kind(data: bytes) -> str:
    head = bytes(data[:16])
    if head.startswith(b"\x89PNG\r\n\x1a\n"):
        return "png"
    if head.startswith(b"\xff\xd8\xff"):
        return "jpg"
    if head[:6] in (b"GIF87a", b"GIF89a"):
        return "gif"
    if head[:4] == b"RIFF" and head[8:12] == b"WEBP":
        return "webp"
    return ""


def implement_image_problem(data: bytes, limit: int, media_type: str = "") -> str:
    if not data:
        return "is empty"
    if len(data) > limit:
        return f"is larger than {limit // (1024 * 1024)} MB"
    if implement_image_kind(data):
        return ""
    start = bytes(data[:4096]).lstrip(b"\xef\xbb\xbf \t\r\n").lower()
    if "svg" in str(media_type or "").lower() or (start.startswith((b"<svg", b"<?xml", b"<!--")) and b"<svg" in start):
        return "is an SVG image, which can carry code, so the App does not take it: pick a PNG, JPEG, GIF or WebP image"
    return "is not a PNG, JPEG, GIF or WebP image" + (f" (its server calls it {str(media_type)[:60]})" if media_type else "")


def implement_block_file(data: bytes, shell_sql) -> str:
    return f"{shell_sql.BLOCK_FOLDER}/{hashlib.sha256(data).hexdigest()}.{implement_image_kind(data)}"


IMPLEMENT_IMAGE_INTERNET = "is an internet address, which Inspire never reads at run time"


def implement_image_source(url: str, shell_sql) -> tuple:
    text = str(url or "").strip()
    if shell_sql.IMAGE_PATH.match(text) and ".." not in text.split("/"):
        return ("volume" if text.startswith("/Volumes/") else "workspace"), text
    return ("internet" if re.match(r"(?i)^https?://", text) else ""), text


def implement_read_image(path: str, limit: int) -> bytes:
    return read_user_file_bytes(path, limit=limit)


def implement_checked_image(url: str, shell_sql) -> tuple:
    kind, path = implement_image_source(url, shell_sql)
    if kind == "internet":
        return None, IMPLEMENT_IMAGE_INTERNET
    if not kind:
        return None, "is not the /Workspace/... or /Volumes/... path of an image"
    limit = shell_sql.CAPS["image_bytes"]
    try:
        data = implement_read_image(path, limit)
    except Exception as error:
        return None, f"could not be read: {redact_error(error)[:300]}"
    problem = implement_image_problem(data, limit)
    return (None, problem) if problem else (data, "")


def implement_left_out_image(block: dict, url: str, problem: str) -> str:
    return (f"{IMPLEMENT_OUTPUT_LABELS['app']}: block {block.get('id')} shows its alt text and a note in place of its image, because the image "
            f"{inspire_redact_text(url, set(), '')[:200]} {problem}; put the image in the workspace or a Unity Catalog volume "
            f"and name that path in the block")

def implement_block_images(page, read, shell_sql, holder: str = "App") -> list:
    out, copy = [], f"the {holder}'s copy" if holder else "Inspire's copy"
    for block in shell_sql.image_blocks(page):
        content, picked = block["content"], str(block["content"].get("file") or "")
        item = {"block": str(block.get("id")), "file": picked, "alt": str(content.get("alt") or ""),
                "caption": str(content.get("caption") or ""), "url": str(content.get("url") or ""),
                "media_type": shell_sql.IMAGE_TYPES.get(picked.rsplit(".", 1)[-1], "")}
        if not shell_sql.BLOCK_FILE.match(picked):
            out.append(dict(item, bytes=None, error="the block has no image Inspire copied" + (f" into the {holder}" if holder else "")))
            continue
        try:
            data = read(picked)
        except Exception as error:
            out.append(dict(item, bytes=None, error=f"{copy} could not be read: {redact_error(error)[:300]}"))
            continue
        if implement_block_file(data, shell_sql) != picked:
            out.append(dict(item, bytes=None, error=f"{copy} is not the image Inspire checked"))
            continue
        out.append(dict(item, bytes=data, error=""))
    return out


