def implement_alert_query(shell_sql, result_table: str, outputs: dict, condition_sql: str = "", use_case_id: str = "",
                          threshold_from: str = "", columns=(), history: dict = None, scopes: bool = False) -> dict:
    tiers = ", ".join(inspire_sql_literal(t) for t in IMPLEMENT_ALERT_TIER_SETS[outputs.get("alert_tiers") or "act_now"])
    limit = shell_sql.threshold_setting_sql(result_table, threshold_from, implement_alert_threshold(outputs)) if threshold_from else ""
    return shell_sql.alert_query(f"COUNT_IF(priority_tier IN ({tiers}))", outputs.get("alert_operator") or ">=",
                                 implement_alert_threshold(outputs), outputs.get("alert_threshold_basis") or "fixed",
                                 source=shell_sql.records_sql(result_table), table=result_table, columns=columns, name="tier_rows",
                                 extra=IMPLEMENT_ALERT_RUN_COLUMNS, condition=condition_sql,
                                 hold=implement_not_reliable_sql(result_table, use_case_id) if use_case_id else "", threshold_sql=limit,
                                 history=history, scopes=scopes,
                                 scope_sql=shell_sql.scope_line_sql(result_table, use_case_id) if scopes and use_case_id else "")


