def implement_job_cadence(schedule: dict, current=None) -> dict:
    schedule = schedule or {}
    cron = str(schedule.get("cron") or getattr(current, "quartz_cron_expression", None) or "").strip()
    return {"cron": cron, "timezone": str(schedule.get("timezone") or "UTC"), "enabled": bool(cron and schedule.get("enabled"))}


IMPLEMENT_CRON_DAYS = {"SUN": "Sunday", "MON": "Monday", "TUE": "Tuesday", "WED": "Wednesday", "THU": "Thursday", "FRI": "Friday",
                       "SAT": "Saturday", "1": "Sunday", "2": "Monday", "3": "Tuesday", "4": "Wednesday", "5": "Thursday", "6": "Friday",
                       "7": "Saturday"}


def implement_cron_words(cron) -> str:
    fields = [part for part in re.split(f"[{IMPLEMENT_SPEC_SPACE}]+", str(cron or "").upper()) if part]
    if len(fields) not in (6, 7) or not all(re.fullmatch(r"[0-9]+", part) for part in fields[:3]) or fields[4] != "*" or (
            fields[6:] and fields[6] != "*"):
        return f"on the schedule {cron}"
    second, minute, hour, day, week = int(fields[0]), int(fields[1]), int(fields[2]), fields[3], fields[5]
    at = f"at {hour:02d}:{minute:02d}" + (f":{second:02d}" if second else "")
    if week in ("*", "?") and day in ("*", "?"):
        return f"{at} every day"
    if week in ("*", "?") and re.fullmatch(r"[0-9]+", day):
        return f"{at} on day {int(day)} of every month"
    spans = [item.split("-") for item in week.split(",")]
    if day not in ("*", "?") or not all(len(span) <= 2 and all(p in IMPLEMENT_CRON_DAYS for p in span) for span in spans):
        return f"on the schedule {cron}"
    named = [" to ".join(IMPLEMENT_CRON_DAYS[p] for p in span) for span in spans]
    return f"{at} every " + (", ".join(named[:-1]) + " and " + named[-1] if len(named) > 1 else named[0])


def implement_alert_shown(name: str, outputs: dict, cadence: dict, clears: bool = True) -> dict:
    cron, zone = cadence.get("cron"), cadence.get("timezone") or "UTC"
    runs = ([f"Runs {implement_cron_words(cron)} ({zone})" if cadence.get("enabled") else
             f"Its schedule, {implement_cron_words(cron)} ({zone}), is paused"] if cron else [])
    return {"name": name, "trigger": implement_alert_trigger_text(outputs), "schedule": [f"Checked {implement_alert_cadence_text(cadence)}",
                                                                                        *runs],
            "recipients": list(outputs.get("alert_recipients") or []),
            "destinations": [str(d.get("name") or d.get("id")) for d in outputs.get("alert_destinations") or [] if isinstance(d, dict)],
            "clears": bool(clears)}


def implement_alert_cadence_text(cadence: dict) -> str:
    cron, zone = cadence.get("cron"), cadence.get("timezone") or "UTC"
    if cron and cadence.get("enabled"):
        return f"after each scheduled run of the job ({implement_cron_words(cron)}, {zone}), once its notebook task has written the results"
    if cron:
        return f"after each run of the job; its schedule ({implement_cron_words(cron)}, {zone}) is paused, so only when someone runs the job"
    return "after each run of the job; the job has no schedule, so only when someone runs it"


def implement_alert_threshold_reason(outputs: dict) -> str:
    tiers = " and ".join(IMPLEMENT_ALERT_TIER_SETS[outputs.get("alert_tiers") or "act_now"])
    fixed = f"{tiers} rows are {_implement_alert_rule_text(outputs)}"
    if outputs.get("alert_threshold_basis") != "baseline":
        return f"{fixed}, the number set in the wizard."
    sign = "plus" if IMPLEMENT_ALERT_BASELINE_DIRECTIONS[outputs.get("alert_operator") or ">="] == "+" else "minus"
    return (f"the mean {sign} {IMPLEMENT_ALERT_BASELINE_SIGMAS} standard deviations of the {tiers} rows of up to "
            f"{IMPLEMENT_ALERT_BASELINE_RUNS} earlier runs, worked out again at every check. The mean and standard deviation use "
            f"every earlier run, so the line moves smoothly as runs are added; a percentile of so few runs is one of the top runs "
            f"and jumps when a run enters or leaves. With fewer than {IMPLEMENT_ALERT_BASELINE_MIN_RUNS} earlier runs the alert "
            f"uses the number set in the wizard ({fixed}), because a mean of so few runs swings with a single run.")


IMPLEMENT_ALERT_SETTING_NOTE = (" Owners of the App change this threshold in its Settings without a rebuild: the alert compares with "
                                "the value they saved last, and the alert_threshold column of each check shows the value it used.")


def implement_alert_texts(shell_alerts, uc_id: str, use_case: dict, outputs: dict, dashboard_url: str = "", genie_url: str = "",
                          cadence: dict = None, from_settings: bool = False, app_url: str = "", notify_on_ok: bool = True,
                          scoped: bool = False) -> tuple:
    trigger = implement_alert_trigger_text(outputs)
    name = " ".join(f"{uc_id} {use_case.get('Name') or ''}".split())
    tiers = " and ".join(IMPLEMENT_ALERT_TIER_SETS[outputs.get("alert_tiers") or "act_now"])
    flagged = ("open the Run health page of the dashboard first" if dashboard_url else
               "look at the rows whose data_quality_flag is not 'ok' first")
    first = [shell_alerts.runbook_rows_step(tiers, dashboard_url), "Read each row's top reasons before you act on it.",
             f"If far more rows fired than usual, {flagged}: flagged rows point to a data problem, not a business one."]
    statement = shell_alerts.cut_text(inspire_plain_text(use_case.get("Statement")), shell_alerts.RUNBOOK_PART_LIMIT)
    more = ["Quiet when not reliable: it never fires on a run Inspire marks not reliable yet, such as one whose model or rule missed its "
            "acceptance check or one that stopped on too little data.", f"Why it matters: {statement}" if statement else ""]
    more += [shell_alerts.cut_text(line, shell_alerts.RUNBOOK_PART_LIMIT) for line in inspire_kind_about(use_case)]
    threshold = implement_alert_threshold_reason(outputs) + (IMPLEMENT_ALERT_SETTING_NOTE if from_settings else "")
    guide = shell_alerts.use_case_guide(use_case, dashboard_url, genie_url, app_url)
    return (shell_alerts.cut_text(f"{name}: {trigger}", shell_alerts.SUMMARY_LIMIT),
            shell_alerts.runbook(trigger, threshold, implement_alert_cadence_text(cadence or {}), guide, notify_on_ok, first, more, scoped))


