def implement_digest_body(shell: dict, uc_id: str, use_case: dict, query: str, warehouse: str, subscribers: list, cadence: dict,
                          app_url: str, hosted_id: str = "", inspire_url: str = "", impact=None) -> dict:
    alerts, sql = shell["shell_alerts"], shell["shell_sql"]
    name = " ".join(f"{uc_id} {(use_case or {}).get('Name') or ''}".split())
    impact = impact or sql.impact_of(None)
    stake = sql.stake_words(impact)
    lines = [f"What it is: the impact of {name} this week, sent every Monday.",
             f"Estimated: the {stake} on the records still open and flagged Act now or Review.",
             f"Reported: the {sql.stake_noun(impact)} people entered when they marked a record fixed.",
             f"Measured: the {stake} on a record when it was fixed, less what a later run still finds on it, once a later run no "
             "longer flags it or the record left the list.",
             "The three amounts are never added together.",
             "Latest run: whether the last run gives a list to act on, and if not, why: Not reliable yet or Nothing to act on yet, "
             "with the reason.",
             f"Acted on this week: the {stake} on the records people marked fixed or could not fix this week, when they did.",
             "Wrong recommendations: the share of closed records people marked not an issue.",
             f"Held back, when the use case holds records back: {sql.HELD_MEANING} Its row compares the share of flagged records that "
             "left the list among those shown to people and among those held back.",
             implement_digest_page_line(app_url, hosted_id, inspire_url),
             IMPLEMENT_DIGEST_RESULT]
    emails = [s["user_name"] for s in subscribers if s.get("user_name")]
    destinations = [s["destination_id"] for s in subscribers if s.get("destination_id")]
    return alerts.alert_body(f"{name} weekly impact", query, warehouse, f"{name}: the impact this week", "\n".join(line for line in lines if line),
                             {"name": sql.DIGEST_SEND, "display": sql.DIGEST_SEND}, "GREATER_THAN_OR_EQUAL", 1.0,
                             alerts.alert_subscriptions(emails, destinations), IMPLEMENT_DIGEST_CRON, (cadence or {}).get("timezone") or "UTC",
                             False, False, IMPLEMENT_ALERT_RETRIGGER_S)


