IMPLEMENT_ALL_USERS = "account users"
IMPLEMENT_READ_NEEDS = (("USE CATALOG", "catalog", ("catalog",)), ("USE SCHEMA", "schema", ("catalog", "schema")),
                        ("SELECT", "table", ("catalog", "schema", "table")))
IMPLEMENT_TRAVERSE_PRIVILEGES = tuple(privilege for privilege, level, _ in IMPLEMENT_READ_NEEDS if level != "table")
IMPLEMENT_MODIFY_NEED = ("MODIFY", "table", ("catalog", "schema", "table"))
IMPLEMENT_ABAC_READ_NEED = ("READ METADATA", "table", ("catalog", "schema", "table"))
IMPLEMENT_SOURCE_NEEDS = (*IMPLEMENT_READ_NEEDS, IMPLEMENT_ABAC_READ_NEED)
# READ METADATA is not in ALL PRIVILEGES, and BROWSE and MANAGE do not confer it (Unity Catalog privileges doc).
IMPLEMENT_NOT_IN_ALL_PRIVILEGES = ("READ METADATA",)
IMPLEMENT_BUILT_IN_CATALOGS = ("samples",)
IMPLEMENT_OWN_SCHEMA_NEEDS = (("USE SCHEMA", "schema", ("catalog", "schema")), ("SELECT", "table", ("catalog", "schema", "table")),
                              ("MODIFY", "table", ("catalog", "schema", "table")))
IMPLEMENT_OWN_SCHEMA_REFUSED = "people cannot read or change the tables this use case adds to its own schema in this App"


def implement_is_own_schema(schema, use_case_id, business_name, session_id, inspire_database) -> bool:
    catalog, _schema = parse_two_level_name(inspire_database) if inspire_database else (None, None)
    if not catalog or not schema or len(schema) != 2 or str(schema[0]).lower() != str(catalog).lower():
        return False
    name = str(schema[1]).lower()
    sid = str(session_id).strip() if session_id is not None else ""
    clash = re.fullmatch(rf"(.+){re.escape(USE_CASE_SCHEMA_CLASH_MARK)}([0-9]+)", name)
    tails = ["", f"_{sid[-USE_CASE_SCHEMA_OLD_SID_DIGITS:]}", f"_{sid}"]
    if clash and int(clash.group(2)) > 1:
        tails.append(f"{USE_CASE_SCHEMA_CLASH_MARK}{int(clash.group(2))}")
    try:
        return any(name == inspire_use_case_schema_name(use_case_id, business_name or "", session_id, tail) for tail in tails)
    except ValueError:
        return False
IMPLEMENT_FEEDBACK_REFUSED = "people cannot report issues about this use case from the App"
IMPLEMENT_SCENARIOS_REFUSED = "people cannot save, share or choose scenarios in this App"


IMPLEMENT_PLANS_REFUSED = "people cannot save plan versions, forecast overrides or their reasons in this App"


