def _implement_privilege(value) -> str:
    return " ".join(str(value or "").strip().upper().replace("_", " ").split())


def implement_access_plan(table: str, rows, principal: str = "", needs=IMPLEMENT_READ_NEEDS, groups=(), aliases=(), refused=()) -> dict:
    parts = _implement_table_parts(table)
    who = str(principal or "").strip()
    if not parts:
        return {"grants": [], "gaps": [], "me": ""}
    objects = {"catalog": inspire_quote_identifier(parts[0]), "schema": f"{inspire_quote_identifier(parts[0])}.{inspire_quote_identifier(parts[1])}",
               "table": ".".join(inspire_quote_identifier(p) for p in parts)}
    need = lambda privilege, level: {"privilege": privilege, "level": level, "object": objects[level]}
    if rows is None:
        return {"grants": [need(p, level) for p, level, _ in needs] if who else [], "gaps": [], "me": ""}
    facts = [{"level": str(r.get("level") or "").lower(), "privilege": _implement_privilege(r.get("privilege")),
              "principal": str(r.get("principal") or "").strip(), "mine": str(r.get("mine")).lower() == "true"} for r in rows]
    me = next((str(r.get("me")).strip() for r in rows if r.get("me")), "")
    holders = {IMPLEMENT_ALL_USERS} | ({who.lower()} if who else set()) | {str(g).strip().lower() for g in groups or () if str(g).strip()}
    table_exists = any(f["level"] == "table" and f["privilege"] == "OWNER" for f in facts)
    # AUTO-3: an owner is also known by the account user id Unity Catalog reports for her, so the person's id (aliases) counts too.
    own_ids = {str(v).strip().lower() for v in [who, *(aliases or ())] if str(v or "").strip()}
    plan = {"grants": [], "gaps": [], "me": me}
    for privilege, level, levels in needs:
        owns = bool(who) and any(f["level"] == level and f["privilege"] == "OWNER" and f["principal"].lower() in own_ids
                                 for f in facts)
        covers = (privilege,) if privilege in IMPLEMENT_NOT_IN_ALL_PRIVILEGES else (privilege, "ALL PRIVILEGES")
        granted = any(f["level"] in levels and f["privilege"] in covers and f["principal"].lower() in holders
                      for f in facts)
        # A refused need (the live check said no) is never treated as held, whatever the grant rows say.
        if privilege not in refused and (owns or granted):
            continue
        manages = any(f["mine"] and f["level"] in levels and f["privilege"] in ("OWNER", "MANAGE") for f in facts)
        if manages or (level == "table" and not table_exists):
            if who:
                plan["grants"].append(need(privilege, level))
            continue
        owner = next((f["principal"] for f in facts if f["level"] == level and f["privilege"] == "OWNER"), "")
        plan["gaps"].append(dict(need(privilege, level), owner=owner))
    return plan


def implement_and_list(items) -> str:
    items = [str(i) for i in items or ()]
    return items[0] if len(items) == 1 else f"{', '.join(items[:-1])} and {items[-1]}" if items else ""


