    _KIND_ACTION_RE = re.compile(r"\b(?:actions?|assigns?|assigned|escalat\w*|queues?|action list|playbooks?|follow[- ]ups?|reforecast\w*|"
                                 r"re-?plans?|reallocat\w*|corrective|root[- ]cause owner)\b")

    def _use_case_name_issues(self, use_case) -> list:
        name = " ".join(str((use_case or {}).get("Name") or "").split())
        words = [w for w in (w.strip(".,;:!?()\"'") for w in name.split(" ")) if w] if name else []
        if not words:
            return ["missing"]
        issues = []
        first = words[0].lower()
        if first not in USE_CASE_NAME_OWNER_VERBS:
            issues.append(f"verb:{first}")
        if not USE_CASE_NAME_MIN_WORDS <= len(words) <= USE_CASE_NAME_MAX_WORDS:
            issues.append(f"words:{len(words)}")
        if USE_CASE_NAME_TAIL_RE.search(name):
            issues.append("deliverable_tail")
        if USE_CASE_NAME_LEVER_RE.search(name):
            issues.append("value_lever")
        if re.search(r"\busing\b", name, re.IGNORECASE):
            issues.append("using")
        spoken = " " + " ".join(re.findall(r"[a-z0-9]+", name.lower())) + " "
        own = str(use_case.get("Analytics Technique") or "").strip()
        labels = {self._technique_label(key) for key, _l, _a, _m in self._TECHNIQUE_FAMILIES} | ({own} if own else set())
        for label in sorted(labels):
            phrase = " ".join(re.findall(r"[a-z0-9]+", label.lower()))
            if phrase and f" {phrase} " in spoken:
                issues.append(f"technique:{label}")
        small = {"a", "an", "and", "as", "at", "by", "for", "from", "in", "into", "of", "on", "or", "per", "the", "to", "vs", "with"}
        for word in words[1:]:
            core = word.strip("'\"-")
            if core[:1].isalpha() and core[:1].islower() and core.lower() not in small:
                issues.append(f"case:{core}")
                break
        return issues

    @classmethod
    def _explainer_names_owner_tolerance_action(cls, use_case) -> bool:
        owner = str(use_case.get("Beneficiary") or use_case.get("Sponsor") or "").strip()
        text = " ".join(str(use_case.get(field) or "") for field in ("Statement", "Solution", "High Level Design")).lower()
        return (bool(owner) and owner.upper() not in ("N/A", "UNKNOWN", "NONE")
                and bool(cls._KIND_TOLERANCE_RE.search(text)) and bool(cls._KIND_ACTION_RE.search(text)))

    @staticmethod
    def _assumed_inputs_named_settings(solution, invented_input_re, invented_nouns, cols) -> list:
        names = []
        for sentence in re.split(r"(?<=[.;])\s+|\n", str(solution or "")):
            low = sentence.lower()
            if not any(m.group(2) in invented_nouns for m in invented_input_re.finditer(low)):
                continue
            named = [n for n in re.findall(r"`([A-Za-z_][A-Za-z0-9_]*)`", sentence) if n.lower() not in cols]
            if not re.search(r"\bsettings?\b", low) or not named:
                return []
            names.extend(named)
        return list(dict.fromkeys(names))

