    _KIND_REGION_GROUPED = frozenset({"segmentation", "peer_benchmarking"})
    _KW_PATTERN_CACHE = {}

    @classmethod
    def _kw_regex(cls, kw):
        pat = cls._KW_PATTERN_CACHE.get(kw)
        if pat is None:
            pat = re.compile(r"(?<![a-z0-9])" + re.escape(kw) + (r"(?![a-z0-9])" if len(kw) <= 4 else ""))
            cls._KW_PATTERN_CACHE[kw] = pat
        return pat

    @classmethod
    def _technique_family(cls, technique) -> str:
        label = " ".join(str(technique if technique is not None else "").lower().split())
        if not label:
            return ""
        if label in cls._GATE_CATCHALL_TECHNIQUES:
            return "catch_all"
        for key, _label, aliases, _methods in cls._TECHNIQUE_FAMILIES:
            if any(cls._kw_regex(kw).search(label) for kw in aliases):
                return key
        for key, _label, _aliases, methods in cls._TECHNIQUE_FAMILIES:
            if any(cls._kw_regex(kw).search(label) for kw in methods):
                return key
        for key, family_label, _aliases, _methods in cls._TECHNIQUE_FAMILIES:
            if label == family_label.lower():
                return key
        return label

    _AI_TEXT_FUNCTION_RE = re.compile(r"\b(ai_classify|ai_extract|ai_analyze_sentiment|ai_summarize|ai_parse_document|"
                                      r"ai_translate|ai_mask|ai_fix_grammar)\b", re.I)
    _MODEL_TRAINING_RE = re.compile(r"\b(train|trains|trained|training|retrain|retrains|fit|fits|fitted|mlflow)\b", re.I)
    _AI_TEXT_GUIDANCE_TECHNIQUE = {"ai_analyze_sentiment": "Sentiment Analysis", "ai_extract": "Extraction"}

    @classmethod
    def _model_training_mentioned(cls, text) -> bool:
        low = str(text or "").lower()
        if cls._MODEL_TRAINING_RE.search(low):
            return True
        return any(TECHNIQUE_EXECUTION_FAMILY.get(label) in INSPIRE_MODEL_FAMILIES + ("E",)
                   and any(not kw.startswith("ai_") and cls._kw_regex(kw).search(low) for kw in methods)
                   for _key, label, _aliases, methods in cls._TECHNIQUE_FAMILIES)

    def _uc_ai_text_function(self, uc: dict, assessment: dict = None):
        uc = uc if isinstance(uc, dict) else {}
        a = assessment if isinstance(assessment, dict) else (
            uc.get("elite_assessment") if isinstance(uc.get("elite_assessment"), dict) else {})
        text = " ".join(str(a.get("build_path") or "").split()) or " ".join(
            " ".join(str(uc.get(field) or "") for field in ("Solution", "High Level Design")).split())
        if not text or self._model_training_mentioned(text):
            return None
        match = self._AI_TEXT_FUNCTION_RE.search(text)
        if match:
            return match.group(1).lower()
        if re.search(r"\bai_query\b", text, re.I):
            names = {str(c).replace("`", "").split(".")[-1].lower(): "" for c in a.get("signal_columns") or []}
            if names and self._column_signals(names)["text_cols"]:
                return "ai_query"
        return None

    def _uc_execution_family(self, uc: dict, context: str = "") -> str:
        uc = uc if isinstance(uc, dict) else {}
        family = _execution_family(uc.get("Analytics Technique"), self.logger, context or f"Use case {uc.get('No', 'UNKNOWN')}")
        if family in INSPIRE_MODEL_FAMILIES and self._uc_ai_text_function(uc):
            return "G"
        return family

    def _uc_guidance_technique(self, uc: dict) -> str:
        technique = _technique_registry_key((uc or {}).get("Analytics Technique"))
        if TECHNIQUE_EXECUTION_FAMILY.get(technique) not in INSPIRE_MODEL_FAMILIES:
            return technique
        function = self._uc_ai_text_function(uc)
        return self._AI_TEXT_GUIDANCE_TECHNIQUE.get(function, "Document Processing") if function else technique

    @classmethod
    def _technique_label(cls, family) -> str:
        for key, label, _aliases, _methods in cls._TECHNIQUE_FAMILIES:
            if key == family:
                return label
        return str(family or "")

    @classmethod
    def _signature_family(cls, family) -> str:
        return "supervised" if family in cls._SUPERVISED_FAMILIES else family

    @classmethod
    def _technique_mentions(cls, text, methods_only=False) -> dict:
        low = str(text or "").lower()
        found = {}
        if not low.strip():
            return found
        for key, _label, aliases, methods in cls._TECHNIQUE_FAMILIES:
            for kw in (methods if methods_only else aliases + methods):
                m = cls._kw_regex(kw).search(low)
                if m and (key not in found or m.start() < found[key]):
                    found[key] = m.start()
        return found

    @staticmethod
    def _iter_schema_rows(full_schema_details):
        for row in full_schema_details or []:
            try:
                if isinstance(row, dict):
                    c = row.get("table_catalog") or row.get("catalog") or ""
                    s = row.get("table_schema") or row.get("schema") or ""
                    t = row.get("table_name") or row.get("table") or ""
                    col = row.get("column_name") or row.get("column") or ""
                    dtype = row.get("data_type") or row.get("type") or ""
                    cmt = row.get("comment") or ""
                elif isinstance(row, (tuple, list)) and len(row) >= 4:
                    c, s, t, col = row[0], row[1], row[2], row[3]
                    dtype = row[4] if len(row) > 4 else ""
                    cmt = row[5] if len(row) > 5 else ""
                else:
                    continue
            except Exception:
                continue
            c, s, t, col = (str(x if x is not None else "").replace("`", "").strip() for x in (c, s, t, col))
            if c and s and t and col:
                yield (c, s, t, col, str(dtype or ""), str(cmt or ""))

    @staticmethod
    def _normalize_table_ref(ref) -> str:
        r = re.sub(r"\s*\.\s*", ".", str(ref if ref is not None else "").replace("`", "").strip())
        if r.lower().startswith("/volumes"):
            return r
        return r.lower()

    @classmethod
    def _uc_table_refs(cls, uc) -> list:
        raw = str((uc or {}).get("Tables Involved") or "")
        out = []
        for part in re.split(r"[,;\n]", raw):
            ref = cls._normalize_table_ref(part)
            if ref and ref not in out:
                out.append(ref)
        return out

    def _honesty(self) -> dict:
        ph = getattr(self, "processing_honesty", None)
        if not isinstance(ph, dict):
            ph = {}
            self.processing_honesty = ph
        return ph

    def _gate_schema_index(self, full_schema_details=None) -> dict:
        cache = getattr(self, "_gate_schema_cache", None)
        if full_schema_details is None:
            if cache is not None:
                return cache
            try:
                sm = getattr(self, "storage_manager", None)
                full_schema_details = sm.load_schema_details("all_columns_for_sql") if sm is not None else []
            except Exception as e:
                self.logger.warning(f"[JOIN_PATH] schema unavailable for gate index: {redact_error(e)}")
                full_schema_details = []
        rows = full_schema_details or []
        key = (id(rows), len(rows), repr(rows[0])[:200] if rows else None, repr(rows[-1])[:200] if rows else None)
        if cache is not None and cache.get("key") == key:
            return cache
        tables, originals = {}, {}
        for (c, s, t, col, dtype, _cmt) in self._iter_schema_rows(rows):
            fqn = f"{c}.{s}.{t}".lower()
            tables.setdefault(fqn, {})[col.lower()] = dtype.upper()
            originals.setdefault(fqn, (c, s, t))
        index = {"key": key, "tables": tables, "originals": originals, "join_graph": None}
        if tables:
            self._gate_schema_cache = index
        return index

    @classmethod
    def _role_tokens(cls, text) -> list:
        raw = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", str(text or ""))
        out = []
        for tok in re.split(r"[^a-z0-9]+", raw.lower()):
            if not tok:
                continue
            out.append(tok)
            if tok in cls._ROLE_COMPOUND_DENY:
                continue
            for part in cls._ROLE_COMPOUND_SUFFIXES:
                if tok != part and tok.endswith(part) and len(tok) - len(part) >= 2:
                    out.extend((tok[:-len(part)], part))
                    break
        return out

    @classmethod
    def _measure_role(cls, toks) -> str:
        if toks & cls._ROLE_SPEC_SIDE_TOKENS and "limit" in toks:
            return "spec_limit"
        if "limit" in toks and toks & cls._ROLE_CREDIT_TOKENS:
            return "score_limit"
        for role, vocab in cls._MEASURE_ROLE_TOKENS:
            if not toks & vocab:
                continue
            if role == "price" and toks & (cls._ROLE_PRICE_TOTAL_TOKENS | {"amount", "amt"}):
                return "money"
            return role
        if toks & cls._ROLE_TARGET_TOKENS and toks & (cls._ROLE_WEAK_MONEY_TOKENS | cls._ROLE_WEAK_QUANTITY_TOKENS):
            return "budget_target"
        if toks & cls._ROLE_WEAK_MONEY_TOKENS:
            return "money"
        if toks & cls._ROLE_WEAK_QUANTITY_TOKENS:
            return "quantity"
        return ""

    @classmethod
    def _unit_charge_column(cls, name, dtype) -> bool:
        low = str(name or "").lower()
        family = _metadata_type_family(dtype) if dtype else ""
        if family not in ("numeric", "") or _is_key_like_column(name):
            return False
        if low.startswith(cls._ROLE_FLAG_PREFIXES) or low.endswith(cls._ROLE_FLAG_SUFFIXES):
            return False
        toks = set(cls._role_tokens(name))
        toks |= {tok[:-1] for tok in toks if len(tok) > 3 and tok.endswith("s")}
        if toks & cls._ROLE_AGGREGATE_TOKENS:
            return False
        return bool(toks & cls._ROLE_UNIT_CHARGE_TOKENS) or ("rate" in toks and bool(toks & cls._ROLE_UNIT_RATE_TOKENS))

    @classmethod
    def _unit_count_quantity(cls, signature, anchor, local) -> list:
        wanted = set((signature or {}).get("roles_all") or [])
        if not {"price", "quantity"} <= wanted or local.get("quantity") or not local.get("event_time"):
            return []
        if not any(cls._unit_charge_column(str(col).rsplit(".", 1)[-1], "") for col in local.get("price") or []):
            return []
        return [f"{anchor}.COUNT(*)"]

    @classmethod
    def _primary_column_role(cls, name, dtype, comment, geo_context) -> tuple:
        low = str(name or "").lower()
        family = _metadata_type_family(dtype) if dtype else ""
        toks = set(cls._role_tokens(name))
        key_like = _is_key_like_column(name)
        is_flag = family == "boolean" or (not key_like and (
            low.startswith(cls._ROLE_FLAG_PREFIXES) or low.endswith(cls._ROLE_FLAG_SUFFIXES)))
        measure_ok = family in ("numeric", "") and not key_like and not is_flag
        if not key_like and not is_flag:
            if toks & {"latitude", "lat"} and family in ("numeric", "string", ""):
                return "latitude", False
            if (toks & {"longitude", "lon", "lng"} and family in ("numeric", "string", "")) or (
                    "long" in toks and family in ("numeric", "")):
                return "longitude", False
        if family in ("string", "") and not key_like and any(tok in low for tok in cls._TEXT_NAME_TOKENS):
            return "free_text", False
        if is_flag:
            if "channel" in toks or toks & cls._ROLE_TREATMENT_TOKENS:
                return "treatment", False
            return "status_activity", False
        any_measure_token = any(toks & vocab for _, vocab in cls._MEASURE_ROLE_TOKENS)
        if family == "temporal":
            return "event_time", False
        if toks & cls._ROLE_TIME_TOKENS and not toks & cls._ROLE_DURATION_TOKENS and not (
                toks & cls._ROLE_APPROVER_VERBS and "by" in toks):
            if key_like or family == "" or (family == "numeric" and not any_measure_token) or (
                    family == "string" and toks & cls._ROLE_STRING_DATE_TOKENS):
                return "event_time", False
        if toks & cls._ROLE_APPROVER_TOKENS or (toks & cls._ROLE_APPROVER_VERBS and "by" in toks):
            return "approver_creator", False
        measure = cls._measure_role(toks) if measure_ok else ""
        if measure:
            return measure, False
        if key_like and toks & cls._ROLE_CASE_TOKENS:
            return "case_id", False
        if toks & cls._ROLE_REGION_TOKENS or ("state" in toks and geo_context):
            return "region_code", False
        if "state" in toks and not key_like and family != "numeric":
            return "status_activity", True
        if toks & cls._ROLE_TREATMENT_TOKENS:
            return "treatment", False
        if toks & cls._ROLE_STATUS_TOKENS and (not key_like or toks & cls._ROLE_STATUS_KEY_TOKENS):
            return "status_activity", False
        if family == "string" and not key_like and toks & {"score", "rating", "grade", "fico"}:
            return "score_limit", False
        if measure_ok and toks & cls._ROLE_TARGET_TOKENS:
            return "", True
        if comment:
            ctoks = set(cls._role_tokens(comment))
            if family in ("string", "") and not key_like and (
                    ctoks & {"comment", "comments", "notes", "narrative"} or {"free", "text"} <= ctoks):
                return "free_text", False
            if ctoks & {"date", "timestamp", "datetime"} and not any_measure_token and family != "boolean":
                return "event_time", False
            cmeasure = cls._measure_role(ctoks) if measure_ok else ""
            if cmeasure:
                return cmeasure, False
            if key_like and ctoks & cls._ROLE_CASE_TOKENS:
                return "case_id", False
            if not key_like and ctoks & cls._ROLE_STATUS_TOKENS:
                return "status_activity", False
        if measure_ok and family == "numeric":
            return "", True
        return "", False

    @classmethod
    def _edge_pair_columns(cls, names, fks=None, exclude=()) -> list:
        lower = {str(n).lower(): n for n in names}
        skip = {str(n).lower() for n in exclude}
        found = []
        for low, orig in lower.items():
            if low in skip:
                continue
            for a, b in cls._ROLE_EDGE_PREFIX_PAIRS:
                partners = set()
                if low.startswith(a):
                    partners.add(b + low[len(a):])
                if "_" + a in low:
                    partners.add(low.replace("_" + a, "_" + b, 1))
                for p in partners:
                    if p != low and p in lower and p not in skip:
                        for col in (orig, lower[p]):
                            if col not in found:
                                found.append(col)
        by_ref = {}
        for col, ref in (fks or {}).items():
            low = str(col).lower()
            if low in lower and low not in skip and ref:
                by_ref.setdefault(str(ref).lower(), []).append(lower[low])
        for cols in by_ref.values():
            if len(cols) >= 2:
                for col in cols:
                    if col not in found:
                        found.append(col)
        return found

    @classmethod
    def _column_roles(cls, cols, comments=None, fks=None, llm_roles=None) -> tuple:
        names = list(cols or {})
        comments = comments or {}
        llm_roles = {str(k).lower(): str(v or "") for k, v in (llm_roles or {}).items()}
        all_toks = set()
        for n in names:
            all_toks.update(cls._role_tokens(n))
        geo_context = bool(all_toks & cls._ROLE_GEO_CONTEXT_TOKENS)
        roles = {r: [] for r in cls._ROLE_IDS}
        ambiguous = []
        primary = {}
        for n in names:
            role, unsure = cls._primary_column_role(n, (cols or {}).get(n), comments.get(n), geo_context)
            guess = llm_roles.get(str(n).lower(), "") if unsure else ""
            if guess in roles and guess != "edge_pair":
                role, unsure = guess, False
            elif guess == "none":
                role, unsure = "", False
            if unsure:
                ambiguous.append(n)
            if role:
                primary[n] = role
                roles[role].append(n)
        for n in names:
            dtype = (cols or {}).get(n)
            family = _metadata_type_family(dtype) if dtype else ""
            if family in ("string", "", "boolean") and not _is_key_like_column(n):
                toks = set(cls._role_tokens(n))
                if toks & cls._ROLE_LABEL_TOKENS or (family == "boolean" and toks & cls._ROLE_FLAG_LABEL_TOKENS):
                    roles["label_column"].append(n)
                if toks & cls._ROLE_ACTION_TOKENS:
                    roles["action_target"].append(n)
                if toks & cls._ROLE_ENTITY_TOKENS:
                    roles["entity_name"].append(n)
        for n in names:
            if primary.get(n) != "price" and cls._unit_charge_column(n, (cols or {}).get(n)):
                roles["price"].append(n)
        if not roles["latitude"]:
            for n in list(roles["longitude"]):
                if not set(cls._role_tokens(n)) & {"longitude", "lon", "lng"}:
                    roles["longitude"].remove(n)
                    primary.pop(n, None)
        exclude = [n for n, r in primary.items() if r in cls._ROLE_EDGE_EXCLUDED]
        roles["edge_pair"] = cls._edge_pair_columns(names, fks, exclude)
        return roles, ambiguous

    @classmethod
    def _column_signals(cls, cols, comments=None, fks=None, llm_roles=None) -> dict:
        names = list(cols or {})
        types = {n: str((cols or {}).get(n) or "").upper() for n in names}
        numeric = [n for n in names if types[n].startswith(cls._NUMERIC_TYPE_PREFIXES) or cls._NUMERIC_NAME_RE.search(n)]
        dates = [n for n in names if types[n].startswith(("DATE", "TIMESTAMP")) or cls._DATE_NAME_RE.search(n)]
        roles, ambiguous = cls._column_roles(cols, comments, fks, llm_roles)
        return {
            "typed": any(t and not t.startswith(("STRING", "VARCHAR", "CHAR", "TEXT")) for t in types.values()),
            "has_date": bool(dates),
            "has_numeric": bool(numeric),
            "numeric_cols": numeric,
            "id_cols": [n for n in names if _is_key_like_column(n) or "_id_" in n or "_sk_" in n],
            "text_cols": [n for n in names if (not types[n] or types[n].startswith(("STRING", "VARCHAR", "CHAR", "TEXT")))
                          and not _is_key_like_column(n) and any(tok in n for tok in cls._TEXT_NAME_TOKENS)],
            "geo_cols": [n for n in names if any(tok in n for tok in cls._GEO_NAME_TOKENS)],
            "stage_cols": [n for n in names if any(tok in n for tok in cls._STAGE_NAME_TOKENS)],
            "roles": roles,
            "role_ambiguous": ambiguous,
        }

    def _deep_calculate_shortlist(self, use_cases, details) -> None:
        """REQ-573 R13.1, R13.2: deep calculation on the post-Selection shortlist; adds uc["Deep Calculation"], never reorders or
        drops a use case, never raises."""
        deep = getattr(self, "deep_evidence", None)
        if deep is None or not TECHNICAL_CONTEXT["runtime"].get("discover_deep_calc", True):
            return
        try:
            if not hasattr(self, "deep_cards"):
                self.deep_cards = []
            by_no = {uc.get("No"): uc for uc in use_cases or []}

            def attach(card):
                self.deep_cards.append(card)
                if card["No"] in by_no:
                    by_no[card["No"]]["Deep Calculation"] = card

            planned = inspire_deep_scan_plan(use_cases, self._kind_metadata_from_details(details)[0])
            for item in planned["unplanned"]:
                attach({"No": item["No"], "status": item["reason"], "currencies": [], "overlap": [], "readiness": None,
                        "sensitivity": None})
            out = deep.deep_calculate(planned["plans"], attach, datetime.date.today())
            counts = {}
            for item in out.get("skipped") or []:
                counts[item["reason"]] = counts.get(item["reason"], 0) + 1
            ok = sum(1 for card in out.get("cards") or [] if card.get("status") == "ok")
            self.logger.info(f"[DEEP-CALC FIRED] {len(planned['plans'])} tables, {len(planned['plans'])} scans, {ok} cards ok, "
                             f"{len(planned['unplanned'])} without a pool KPI, skipped by reason {counts or 'none'}")
        except SparkWorkCancelled:
            raise
        except Exception as error:
            self.logger.warning(f"[DEEP-CALC] the shortlist calculation stopped: {redact_error(error, max_chars=200)}")

    def _kind_metadata_from_details(self, details) -> tuple:
        metadata, graph = {}, {}
        for row in details or []:
            fqn = ".".join(str(x) for x in row[:3]).lower()
            entry = metadata.setdefault(fqn, {"columns": {}})
            entry["columns"][str(row[3])] = {"type": str(row[4] or ""), "comment": str(row[5] or "") if len(row) > 5 else ""}
        loader = getattr(self, "data_loader", None)
        inferred = getattr(loader, "_inferred_fk", None) or {}
        for rels in list((getattr(loader, "foreign_key_graph", None) or {}).values()):
            for rel in rels or []:
                if len(rel) < 8:
                    continue
                child = ".".join(str(x) for x in rel[:3]).lower()
                link = (str(rel[3]), ".".join(str(x) for x in rel[4:7]).lower(), str(rel[7]),
                        "inferred" if rel in inferred else "declared")
                if child in metadata and link not in graph.get(child, []):
                    graph.setdefault(child, []).append(link)
        return metadata, graph

    def _start_loss_pools(self, details) -> None:
        """REQ-573 R10.4: the loss-pool enumerator starts in a daemon thread and returns at once; generation never waits on it."""
        self.loss_pools, self.loss_pool_skipped, self.loss_pool_coverage = [], [], []
        state = self._loss_pool_state = {"status": "off", "thread": None, "result": None}
        try:
            deep = getattr(self, "deep_evidence", None)
            if deep is None or TECHNICAL_CONTEXT["runtime"].get("discover_loss_pools", True) is not True:
                return
            metadata, _graph = self._kind_metadata_from_details(details)

            def work():
                try:
                    state["result"] = DeepEvidence.measure_loss_pools(deep, inspire_loss_pool_plan(metadata))
                    state["status"] = "ok"
                except BaseException as error:
                    state["status"] = "failed"
                    self.logger.warning(f"[LOSS-POOLS] the enumerator failed and generation goes on without it: {redact_error(error, max_chars=200)}")

            state["status"] = "pending"
            state["thread"] = threading.Thread(target=work, name="LossPoolEnumerator", daemon=True)
            state["thread"].start()
        except Exception as error:
            state["status"] = "failed"
            self.logger.warning(f"[LOSS-POOLS] the enumerator could not start: {redact_error(error, max_chars=200)}")

    def _rank_domains(self, loss_status):
        """REQ-573 R9.2: ranks the table domains by the measured loss pools and stores self.domain_ranking (results_json.domain_ranking).
        No domain graph or any error: no ranking, a warning, never a raise."""
        self.domain_ranking = None
        try:
            table_domains = getattr(self, "table_domains", None)
            if not isinstance(table_domains, dict) or not table_domains:
                return None
            ranking = inspire_domain_ranking(table_domains, getattr(self, "loss_pools", None) or [],
                                             getattr(self, "domain_choices", None) or {}, loss_status)
            self.domain_ranking = ranking
            self.logger.info(
                f"[DOMAIN-RANK FIRED] {len(ranking['domains'])} domains, deepened {ranking['deepened']}, suggested {ranking['suggested']}, "
                f"{len(ranking['pairs'])} pairs, excluded {ranking['excluded']}, ranking currency {ranking['ranking_currency']}, "
                f"{sum(1 for d in ranking['domains'] if d['score'] is None)} unknown")
            return ranking
        except Exception as error:
            self.domain_ranking = None
            self.logger.warning(f"[DOMAIN-RANK] the domain ranking failed and the run goes on: {redact_error(error, max_chars=200)}")
            return None

    def _loss_pools_collect(self, wait_seconds) -> dict:
        """Waits at most wait_seconds for the enumerator. pending = not done, the pools are unknown (never an empty answer)."""
        try:
            state = getattr(self, "_loss_pool_state", None) or {"status": "off", "thread": None, "result": None}
            thread = state.get("thread")
            if thread is not None and state["status"] == "pending":
                thread.join(max(0.0, float(wait_seconds or 0)))
            status = state["status"]
            result = state.get("result") if status == "ok" else None
            self.loss_pools = list((result or {}).get("pools") or [])
            self.loss_pool_skipped = list((result or {}).get("skipped") or [])
            return {"status": status, "pools": self.loss_pools, "skipped": self.loss_pool_skipped}
        except Exception as error:
            self.loss_pools, self.loss_pool_skipped = [], []
            self.logger.warning(f"[LOSS-POOLS] collecting the pools failed: {redact_error(error, max_chars=200)}")
            return {"status": "failed", "pools": [], "skipped": []}

    def _loss_pool_candidates(self, pools, use_cases) -> tuple:
        """REQ-573 R10.5: every material pool gets a use case or a recorded reason. One batched call covers the uncovered pools."""
        use_cases = list(use_cases or [])
        coverage = inspire_loss_pool_coverage(pools, use_cases)
        self.loss_pool_coverage = coverage
        by_id = {pool.get("pool_id"): pool for pool in pools or []}
        asked = [row for row in coverage if row["reason"] == "uncovered"]
        if not asked:
            return [], coverage
        share = self._ai_gate().share_measures
        shown = []
        for row in asked:
            pool = by_id[row["pool_id"]]
            item = {key: pool.get(key) for key in ("pool_id", "table", "money_column", "split_column", "loss_kind", "flow", "currency", "unit")}
            if share:
                item.update({key: pool.get(key) for key in ("split_values", "amount", "rows", "share")})
            shown.append(item)
        used = {str(uc.get("No")) for uc in use_cases}
        techniques = sorted(set(TECHNIQUE_EXECUTION_FAMILY) - set(TECHNIQUE_CATCH_ALL))
        new, reasons = [], {}
        try:
            raw = self.ai_agent.run_worker(
                step_name="LossPoolCandidates", worker_prompt_path="LOSS_POOL_CANDIDATE_PROMPT",
                prompt_vars={"business_name": getattr(self, "business_name", ""),
                             "generation_instructions_section": self._get_generation_instruction_for_prompt("LOSS_POOL_CANDIDATE_PROMPT")
                             if hasattr(self, "parsed_generation_instructions") else "",
                             "pools_json": json.dumps(shown, ensure_ascii=False, default=str),
                             "techniques": ", ".join(techniques)},
                response_schema=None)
            cleaned = clean_json_response(raw, want=dict) if raw else ""
            answer = json.loads(cleaned) if cleaned else {}
            answer = answer if isinstance(answer, dict) else {}
            for item in answer.get("candidates") or []:
                pool = by_id.get(item.get("pool_id")) if isinstance(item, dict) else None
                if pool is None or pool["pool_id"] in reasons or not str(item.get("Name") or "").strip():
                    continue
                number = 1
                while f"LP-U{number:02d}" in used:
                    number += 1
                no = f"LP-U{number:02d}"
                used.add(no)
                technique = str(item.get("Analytics Technique") or "").strip()
                uc = {"No": no, "Name": str(item["Name"]).strip(), "usecase": str(item["Name"]).strip(),
                      "type": "Risk", "Analytics Technique": technique if technique in techniques else "Pareto Analysis",
                      "Tables Involved": pool["table"], "Primary Table": pool["table"], "loss_pool_id": pool["pool_id"]}
                for field in ("Statement", "Solution", "Business Value", "Beneficiary", "Sponsor"):
                    uc[field] = str(item.get(field) or "").strip()
                new.append(uc)
                reasons[pool["pool_id"]] = ("candidate", no)
            for item in answer.get("declined") or []:
                pool_id = item.get("pool_id") if isinstance(item, dict) else None
                if pool_id in by_id and pool_id not in reasons:
                    reasons[pool_id] = ("declined", str(item.get("reason") or "").strip() or "declined_without_reason")
        except SparkWorkCancelled:
            raise
        except Exception as error:
            failed = f"candidate_generation_failed: {redact_error(error, max_chars=200)}"
            reasons = {row["pool_id"]: ("declined", failed) for row in asked}
            new = []
            self.logger.warning(f"[LOSS-POOLS] {failed}")
        for row in coverage:
            if row["reason"] != "uncovered":
                continue
            kind, value = reasons.get(row["pool_id"], ("declined", "no_candidate_returned"))
            row["candidates"], row["reason"] = ([value], None) if kind == "candidate" else ([], value)
        return new, coverage

    def _table_role_signals(self, fqn, entry, fk_graph, llm_roles=None) -> dict:
        columns = (entry or {}).get("columns") or {}
        cols = {name: (info or {}).get("type") or "" for name, info in columns.items()}
        comments = {name: (info or {}).get("comment") or "" for name, info in columns.items()}
        fks = {str(link[0]): str(link[1]) for link in (fk_graph or {}).get(fqn, []) if len(link) >= 2}
        return self._column_signals(cols, comments, fks, (llm_roles or {}).get(fqn))

    def _label_ambiguous_column_roles(self, metadata, fk_graph) -> dict:
        pending = []
        for fqn, entry in (metadata or {}).items():
            columns = (entry or {}).get("columns") or {}
            for col in self._table_role_signals(fqn, entry, fk_graph)["role_ambiguous"]:
                info = columns.get(col) or {}
                pending.append((fqn, col, str(info.get("type") or ""), " ".join(str(info.get("comment") or "").split())[:80]))
        if not pending:
            return {}
        sent = pending[:self._ROLE_LABEL_MAX_COLUMNS]
        roles = [r for r in _inspire_kinds()["roles"] if r["id"] != "edge_pair"]
        valid = {r["id"] for r in roles} | {"none"}
        prompt = (
            "You label database columns with the analytic role each one plays. The rules could not place these columns.\n"
            "Pick exactly one role per column from the list, or none when no role fits. Judge from the column name, type "
            "and comment only; never guess from a single letter.\n\nROLES:\n"
            + "\n".join(f"- {r['id']}: {r['description']}" for r in roles)
            + "\n- none: no role above fits\n\nOUTPUT (STRICT JSON): "
              "{\"columns\": [{\"column\": \"<table.column exactly as given>\", \"role\": \"<role id or none>\"}]}\n\n"
              "COLUMNS (table.column | type | comment):\n"
            + "\n".join(f"{fqn}.{col} | {dtype} | {comment}".rstrip(" |") for fqn, col, dtype, comment in sent)
        )
        schema = {"name": "column_roles", "schema": {
            "type": "object",
            "properties": {"columns": {"type": "array", "items": {
                "type": "object",
                "properties": {"column": {"type": "string"}, "role": {"type": "string", "enum": sorted(valid)}},
                "required": ["column", "role"]}}},
            "required": ["columns"]}}
        try:
            response = self.ai_agent._call_ai_query(prompt=prompt, prompt_name="label_column_roles", response_schema=schema,
                                                    display_name="Column_Role_Labeler")
            cleaned = clean_json_response(response, want=dict) if response else ""
            parsed = json.loads(cleaned) if cleaned else {}
        except Exception as error:
            self.logger.warning(f"[COLUMN-ROLES FIRED] the labeling call failed; the rule-based roles stand: "
                                f"{redact_error(error, max_chars=200)}")
            return {}
        known = {(fqn, col.lower()): col for fqn, col, _t, _c in sent}
        labels = {}
        for item in (parsed.get("columns") if isinstance(parsed, dict) else None) or []:
            if not isinstance(item, dict):
                continue
            table, _dot, col = str(item.get("column") or "").strip().lower().rpartition(".")
            role = str(item.get("role") or "").strip().lower()
            if (table, col) in known and role in valid:
                labels.setdefault(table, {})[known[(table, col)]] = role
        labeled = sum(len(v) for v in labels.values())
        self.logger.info(f"[COLUMN-ROLES FIRED] {implement_number_text(labeled)} of {inspire_plural(len(sent), 'ambiguous column')} labeled in one call"
                         + (f"; {len(pending) - len(sent)} more kept their rule-based role" if len(pending) > len(sent) else ""))
        return labels

    @classmethod
    def _distinct_moments(cls, columns) -> int:
        stems = set()
        for col in columns or []:
            toks = set(cls._role_tokens(str(col).rsplit(".", 1)[-1])) - cls._ROLE_TIME_TOKENS - cls._KIND_MOMENT_NOISE
            stems.add(frozenset(t[:-2] if t.endswith("ed") and len(t) > 4 else t for t in toks))
        return len(stems)

    def _event_log_grain(self, fqn, cols, roles):
        steps = [c for c in roles.get("status_activity") or [] if not str(cols.get(c) or "").upper().startswith("BOOLEAN")
                 and not c.lower().startswith(self._ROLE_FLAG_PREFIXES) and not c.lower().endswith(self._ROLE_FLAG_SUFFIXES)]
        if not steps or not roles.get("event_time"):
            return None
        primary_key = getattr(getattr(self, "data_loader", None), "get_primary_key", None)
        parts = str(fqn).split(".")
        declared = (primary_key(*parts) if callable(primary_key) and len(parts) == 3 else None) or ()
        own = [c for c in cols if _is_own_row_key(fqn, c, declared, list(cols))]
        case_ids = list(roles.get("case_id") or [])
        keys = case_ids or [c for c in cols if _is_key_like_column(c)]
        cases = [] if set(own) & set(case_ids) else [c for c in keys if c not in own]
        milestones = self._distinct_moments([c for c in roles["event_time"]
                                             if not set(self._role_tokens(c)) & self._ROLE_LAST_CHANGE_TOKENS])
        return {"cases": cases, "milestones": milestones} if cases or (keys and milestones >= 2) else None

    def _process_log_tables(self, tables, cols_by) -> dict:
        found = {}
        for table in tables or []:
            fqn = str(table).replace("`", "").lower()
            cols = cols_by.get(fqn) or {}
            grain = self._event_log_grain(fqn, cols, self._column_signals(cols)["roles"])
            if grain:
                found[fqn] = grain
        return found

    @staticmethod
    def _one_row_per_case(profile, log, rt) -> str:
        if log.get("milestones", 0) >= 2 or not log.get("cases"):
            return ""
        columns = {str(name).lower(): info for name, info in ((profile or {}).get("columns") or {}).items() if isinstance(info, dict)}
        rows = int((profile or {}).get("rows") or 0)
        seen = min(rows, int(rt["deep_sample_rows"])) if (profile or {}).get("sampled") else rows
        for column in log["cases"]:
            info = columns.get(column) or {}
            if info.get("null_share") is None or info.get("distinct") is None:
                return ""
            filled = seen * (1.0 - float(info["null_share"]))
            if filled < rt["deep_min_signal_rows"] or int(info["distinct"]) < DEEP_RECORD_UNIQUE_SHARE * filled:
                return ""
        return log["cases"][0]

    @classmethod
    def _kind_signature_met(cls, signature, roles, local) -> bool:
        mins = {str(r): int(n) for r, n in ((signature or {}).get("min_counts") or {}).items()}
        for role in (signature or {}).get("roles_all") or []:
            if not roles.get(role):
                return False
        for role, n in mins.items():
            have = local.get(role, [])
            if n > 1 and (cls._distinct_moments(have) if role == "event_time" else len(have)) < n:
                return False
        wanted = (signature or {}).get("roles_any") or []
        return not wanted or any(roles.get(r) for r in wanted)

    @classmethod
    def _kind_join_scopes(cls, own, fk_graph) -> dict:
        refs_of, referrers_of = {}, {}
        for child, links in (fk_graph or {}).items():
            for link in links or []:
                parent = str(link[1]) if len(link) >= 2 else ""
                if child in own and parent in own and parent != child:
                    refs_of.setdefault(child, set()).add(parent)
                    referrers_of.setdefault(parent, set()).add(child)
        scopes = {}
        for anchor in own:
            refs = sorted(refs_of.get(anchor, ()))
            merged = {}
            for table in [anchor] + refs:
                for role, cols in own[table].items():
                    if table == anchor or role not in cls._KIND_LOCAL_ROLES:
                        merged.setdefault(role, []).extend(cols)
            widened = {role: list(cols) for role, cols in merged.items()}
            for table in sorted(referrers_of.get(anchor, set()) - set(refs)):
                for role in cls._KIND_BORROWED_ROLES:
                    if own[table].get(role):
                        widened.setdefault(role, []).extend(own[table][role])
            scopes[anchor] = (refs, merged, widened)
        return scopes

    def detect_supported_kinds(self, metadata, fk_graph, llm_roles=None, log=True) -> list:
        registry = _inspire_kinds()
        own, named = {}, {}
        for fqn, entry in (metadata or {}).items():
            roles = self._table_role_signals(fqn, entry, fk_graph, llm_roles)["roles"]
            own[fqn] = {role: [f"{fqn}.{c}" for c in cols] for role, cols in roles.items() if cols}
            named[fqn] = ({name: (info or {}).get("type") or "" for name, info in ((entry or {}).get("columns") or {}).items()}, roles)
        scopes = self._kind_join_scopes(own, fk_graph)
        found, refused_no_label = [], set()
        for kind in registry["kinds"]:
            sig = kind.get("signature") or {}
            wanted_all = list(sig.get("roles_all") or [])
            wanted_any = list(sig.get("roles_any") or [])
            timed = "event_time" in set(wanted_all) | set(sig.get("min_counts") or {})
            best = None
            for anchor, (refs, merged, widened) in scopes.items():
                merged = merged if timed else widened
                local = own[anchor]
                counted = self._unit_count_quantity(sig, anchor, local)
                if counted:
                    local, merged = dict(local, quantity=counted), dict(merged, quantity=counted)
                if not any(local.get(r) for r in (wanted_all or wanted_any)):
                    continue
                if sig.get("fk_pattern") == "edge_pair" and not local.get("edge_pair"):
                    continue
                grouped = (list(local.get("region_code") or []) if sig.get("fk_pattern") == "fact_to_dim" and not refs
                           and kind["id"] in self._KIND_REGION_GROUPED else [])
                if sig.get("fk_pattern") == "fact_to_dim" and not refs and not grouped:
                    continue
                if not self._kind_signature_met(sig, merged, local):
                    # REQ-414: no label, no AI-native kind.
                    if kind.get("ai_native") and not merged.get("label_column") and self._kind_signature_met(
                            dict(sig, roles_all=[r for r in wanted_all if r != "label_column"]), merged, local):
                        refused_no_label.add(kind["id"])
                    continue
                if sig.get("grain") == "event_log" and not self._event_log_grain(anchor, *named[anchor]):
                    continue
                share = sum(1 for r in wanted_any if merged.get(r)) / len(wanted_any) if wanted_any else 1.0
                strength = round(0.25 * (not grouped) + 0.25 + 0.25 * self._kind_signature_met(sig, local, local) + 0.25 * share, 2)
                if best is None or strength > best[0]:
                    best = (strength, anchor, merged, grouped)
            if best is None:
                continue
            strength, anchor, merged, grouped = best
            mins = sig.get("min_counts") or {}
            columns = {r: merged[r][:max(2 if r == "edge_pair" else 1, int(mins.get(r, 1)))] for r in wanted_all + wanted_any if merged.get(r)}
            if grouped:
                columns["region_code"] = grouped[:1]
            tables = sorted({c.rsplit(".", 1)[0] for cols in columns.values() for c in cols} | {anchor})
            found.append({"kind": kind["id"], "num": kind.get("num"), "label": kind.get("label"), "family": kind.get("family"),
                          "layout": kind.get("layout"), "informational": bool(kind.get("informational")), "anchor": anchor,
                          "tables": tables, "columns": columns, "strength": strength,
                          "signal": "strong" if strength >= 0.8 else "medium" if strength >= 0.6 else "weak"})
        if log and refused_no_label:
            self.logger.info(f"[AI-KIND-GATE FIRED] no label, no kind: {', '.join(sorted(refused_no_label))} refused, "
                             "no label column in these tables to score the AI result against")
        if log:
            counted = [k["kind"] for k in found if any(str(c).endswith(".COUNT(*)") for c in k["columns"].get("quantity", []))]
            self.logger.info(f"[KIND-DETECT FIRED] {inspire_plural(len(found), 'kind')}: "
                             + (", ".join(f"{k['kind']}({k['strength']})" for k in found) or "none")
                             + (f"; priced by a per-unit charge and counted by rows: {', '.join(counted)}" if counted else ""))
        return found

    def _detect_kinds_for_generation(self, business_details) -> list:
        metadata, graph = self._kind_metadata_from_details(business_details)
        self._kind_metadata, self._kind_fk_graph = metadata, graph
        self._kind_llm_roles = self._label_ambiguous_column_roles(metadata, graph)
        self.detected_kinds = self.detect_supported_kinds(metadata, graph, self._kind_llm_roles)
        return self.detected_kinds

    def _kinds_checklist_section(self, tables=None) -> str:
        try:
            return self._kinds_checklist_lines(tables)
        except Exception as error:
            self.logger.warning(f"[KIND-DETECT FIRED] the kind checklist is left out of this prompt: {redact_error(error)}")
            return ""

    def _kinds_checklist_lines(self, tables) -> str:
        detected = list(getattr(self, "detected_kinds", None) or [])
        metadata = getattr(self, "_kind_metadata", None)
        if tables is not None and metadata:
            wanted = {str(table).lower() for table in tables}
            detected = self.detect_supported_kinds({fqn: entry for fqn, entry in metadata.items() if fqn in wanted},
                                                   getattr(self, "_kind_fk_graph", None) or {},
                                                   getattr(self, "_kind_llm_roles", None), log=False)
        asked, excluded = self._user_kind_directives()
        covered = getattr(self, "_kinds_covered_by_pass1", None)
        if covered is not None:
            detected = sorted(detected, key=lambda kind: kind["kind"] in covered)
        lines, shown = [], set()
        for kind in detected:
            if kind["kind"] in excluded:
                continue
            shown.add(kind["kind"])
            by_table = {}
            for role, columns in kind["columns"].items():
                for column in columns:
                    table, name = column.split(".", 2)[-1].rsplit(".", 1)
                    by_table.setdefault(table, []).append(f"{role} {name}")
            evidence = "; ".join(f"`{table}` ({', '.join(items)})" for table, items in by_table.items())
            fallback = ai_function_fallback_sentence(next((k.get("ai_functions") for k in _inspire_kinds()["kinds"] if k["id"] == kind["kind"]), None))
            build = inspire_shell_build.choose_path(kind["kind"], (TECHNICAL_CONTEXT.get("ai_function_status") or {}).get("supervisor_agents"),
                                                    (TECHNICAL_CONTEXT.get("ai_function_status") or {}).get("vector_search"))
            lines.append(f"- `{kind['kind']}` {kind['label']}: {evidence}"
                         + (" (the user asked for this kind)" if kind["kind"] in asked else "")
                         + ("" if covered is None else " (Pass 1 already has one)" if kind["kind"] in covered
                            else " (no use case of this kind yet)")
                         + (f" {fallback}" if fallback else "")
                         + (f" Build path: {build}. {inspire_shell_build.fallback_sentence(build)}".rstrip() if build != "none" else ""))
        for kind in _inspire_kinds()["kinds"]:
            if kind["id"] in asked and kind["id"] not in shown:
                lines.append(f"- `{kind['id']}` {kind['label']}: the user asked for this kind; no column shows its signal in "
                             f"these tables, so propose it only where the schema supports it")
        if not lines:
            return ""
        return ("##### 1c. Kinds this data supports (a checklist, not a quota)\n"
                "Each line names a kind of use case these tables support and the columns that show its signal. For each kind, "
                "propose a use case of that kind when one is worth funding, or skip the kind: skipping is a correct answer. "
                "Never weaken a use case to fit a kind, and a user directive always wins over this list. Write the kind id in "
                "the `Use Case Kind` column.\n"
                + ("" if covered is None else
                   "Pass 1 already proposed the kinds marked so. The kinds marked no use case of this kind yet are the gaps: "
                   "look at each of them first and propose its best use case when one is worth funding.\n")
                + "\n".join(lines) + "\n")

    def _mark_pass1_kind_gaps(self, use_cases) -> set:
        catalog = self._kind_catalog()
        if not catalog:
            return None
        covered = {self._uc_kind_id(uc, catalog) for uc in use_cases or [] if isinstance(uc, dict)} - {""}
        _asked, excluded = self._user_kind_directives(catalog)
        strengths = self._detected_kind_strengths(catalog)
        gaps = sorted(set(strengths) - covered - set(excluded), key=lambda kind_id: (-strengths[kind_id], kind_id))
        self.logger.info(f"[KIND-GAP FIRED] Pass 1 covered {inspire_plural(len(set(strengths) & covered), 'detected kind')} of "
                         f"{implement_number_text(len(strengths))}; Pass 2 is shown the gaps first: {inspire_listing(gaps, ', ') or 'none'}")
        return covered

    def _resolve_use_case_kind(self, value, technique) -> tuple:
        try:
            written = _inspire_resolve_kind(value)
            kind_id = written or _inspire_resolve_kind(None, technique)
        except RuntimeError:
            return "", "none"
        return (kind_id, "written" if written else "technique") if kind_id else ("", "none")

    @classmethod
    def _grounded_column_mentions(cls, text, col_names) -> set:
        raw = str(text or "")
        low = raw.lower()
        names = {str(c).lower() for c in (col_names or ()) if c}
        found = set()
        if not names or not low.strip():
            return found
        for tok in re.findall(r"`([A-Za-z_][A-Za-z0-9_.]*)`", raw):
            last = tok.rsplit(".", 1)[-1].lower()
            if last in names and tok.upper() not in cls._GATE_SQL_KEYWORDS:
                found.add(last)
        for name in names:
            if len(name) >= 3 and name not in found and re.search(r"(?<![a-z0-9_])" + re.escape(name) + r"(?![a-z0-9_])", low):
                found.add(name)
        return found

    @staticmethod
    def _add_gate_flag(uc, flag):
        flags = uc.get("gate_flags")
        if not isinstance(flags, list):
            flags = []
            uc["gate_flags"] = flags
        if flag not in flags:
            flags.append(flag)

    @staticmethod
    def _gate_reason_key(reason) -> str:
        parts = [p.strip() for p in str(reason or "").split(":")]
        key = parts[0]
        if len(parts) > 1 and re.match(r"R\d+_", parts[1]):
            key += ":" + parts[1]
        return key

    def _record_gate_ledger(self, gate, n_in, n_out, dropped=None, flagged=0, below_bar=None) -> dict:
        by_reason = {}
        for item in dropped or []:
            if isinstance(item, dict):
                reason = item.get("reason")
            elif isinstance(item, (tuple, list)) and len(item) > 1:
                reason = item[1]
            else:
                reason = item
            k = self._gate_reason_key(reason)
            by_reason[k] = by_reason.get(k, 0) + 1
        below_by_reason = {}
        for uc in below_bar or []:
            k = self._gate_reason_key(uc.get("below_bar_gate"))
            below_by_reason[k] = below_by_reason.get(k, 0) + 1
        entry = {"in": int(n_in), "out": int(n_out), "dropped": int(n_in) - int(n_out),
                 "by_reason": by_reason, "flagged": int(flagged)}
        if below_by_reason:
            entry["below_bar"] = sum(below_by_reason.values())
            entry["below_bar_by_reason"] = below_by_reason
        self._honesty().setdefault("gate_ledger", {})[gate] = entry
        self.logger.info(f"[GATE_LEDGER] {gate}: in={n_in} out={n_out} dropped={entry['dropped']} "
                         f"by_reason={by_reason} flagged={flagged}"
                         + (f" below_bar={entry['below_bar']} below_bar_by_reason={below_by_reason}" if below_by_reason else ""))
        return entry

    _BELOW_BAR_REMOVED_RULES = frozenset({"R13"})
    _BELOW_BAR_RULE_TEXTS = {
        "R1": "it reads only technical tables",
        "R2": "its technique does not fit the columns of its tables",
        "R4": "its tables have no join path",
        "R7": "its business value quotes figures the data does not back",
        "R9": "it relies on simulated inputs",
        "R11": "it forms cohorts on a biographical attribute",
        "R14": "its tables have too few columns for its technique",
        "R14_NO_EVENT_LOG": "its tables keep each case's current status, not the steps each case went through",
        "R14_CASE_UNIQUE_PER_ROW": "its case id {detail} holds one row per case, so its table keeps only the current step of each case",
        "R19": "its title is too generic to name a decision",
        "R20": "its main table {detail} has no rows yet",
        "R21": "its join matches too few rows ({detail})",
        "R22": "the columns it needs hold too few values ({detail})",
        "R24": "its label column holds a single value ({detail})",
        "R25": "its title breaks the name rules",
        "T3": "its main table already holds what its technique would build ({detail})",
        "R5_REFERENCE_AS_FACT": "it reads a reference table as if it recorded events",
        "R8_TARGET_LEAKAGE": "it uses the value it predicts as one of its inputs ({detail})",
        "R9_ASSUMPTION_SETTING": "it rests on an assumed setting ({detail})",
        "R9_ASSUMED_PARAMETER": "it rests on an assumed figure ({detail})",
        "R10_REFERENCE_SCALE": "it sizes its result on a reference table",
        "R13_THIN_GROUNDING": "few of the columns it names are in its tables",
        "R13_SOLUTION_UNDER_GROUNDED": "few of the columns it names are in its tables",
        "R13_INVENTED_COLUMN": "it names columns its tables do not have ({detail})",
        "R22_MOSTLY_NULL_SIGNAL": "a column it needs is mostly empty ({detail})",
        "R23_THIN_TIME_COVERAGE": "its history is too short ({detail})",
        "R24_CONSTANT_COLUMN": "a column it needs holds a single value ({detail})",
        "R18_TECHNIQUE_LABEL_DRIFT": "its technique label does not match the method its design names",
        "R19_GENERIC_TITLE": "its title is too generic to name a decision",
        "R20_NAME_STYLE": "its name does not follow the naming rules",
        "R26_VERB_SHARE": "its name starts with a verb too many other names in the batch start with",
        "T2_RESTATES_COLUMN": "the answer it promises is already in a column ({detail})",
        "T4_NO_OWNER": "it names no one who would act on it",
        "T4_NO_MEASURABLE_OUTCOME": "it names no measurable outcome it would move",
        "T4_ONE_OFF": "it answers a one-off question, not a decision made again and again",
        "T4_TOO_FEW_ITEMS": "it leaves too few items to act on each cycle ({detail})",
        "T4_NO_PER_ITEM_ACTION": "it names no action to take on each item",
        "D5_COMPANION_DATA": "its kind ({detail}) needs data its tables do not have",
        "D5_KIND_TECHNIQUE_MISMATCH": "its technique is not one its kind ({detail}) uses",
    }

    @staticmethod
    def _gate_detail_text(detail) -> str:
        """FX-87 (REQ-485): `a_b=10,c_d=10` reads '2 columns, such as a b, hold only 10 values each'; any other detail loses its underscores."""
        text = str(detail or "").strip()
        if not re.fullmatch(r"[A-Za-z][\w.]*=\d+(?:\s*,\s*[A-Za-z][\w.]*=\d+)*", text):
            return text.replace("_", " ")
        pairs = [part.strip().split("=") for part in text.split(",")]
        counts = sorted({n for _c, n in pairs})
        each = f"only {counts[0]} values" + (" each" if len(pairs) > 1 else "") if len(counts) == 1 else "too few values"
        first = pairs[0][0].replace("_", " ")
        return f"{first} holds {each}" if len(pairs) == 1 else f"{inspire_plural(len(pairs), 'column')}, such as {first}, hold {each}"

    @classmethod
    def _gate_code_text(cls, code) -> str:
        text = str(code or "").strip()
        key, _sep, detail = re.sub(r"^Q\d_", "", text).partition(":")
        if key not in cls._BELOW_BAR_RULE_TEXTS:
            return ""
        return cls._BELOW_BAR_RULE_TEXTS[key].format(detail=cls._gate_detail_text(detail)).replace(" ()", "")

    @classmethod
    def _gate_rule(cls, reason) -> str:
        match = re.search(r"(?:^|[_:])([RT]\d+)_", str(reason or ""))
        return match.group(1) if match else ""

    @classmethod
    def _below_bar_gate_text(cls, gate, reason) -> str:
        code = str(reason or "").strip()
        label = inspire_gate_label(gate)
        exact = cls._gate_code_text(code)
        if exact:
            return exact
        rule = cls._gate_rule(code)
        detail = code.split(":", 1)[1].strip() if code.startswith(("Q3_R", "Q5_T")) and ":" in code else ""
        sub, _sep, rest = detail.partition(":")
        if sub in cls._BELOW_BAR_RULE_TEXTS:
            rule, detail = sub, rest
        if rule in ("R20",):
            detail = detail.split(":")[0]
        text = cls._BELOW_BAR_RULE_TEXTS.get(rule, "").format(detail=cls._gate_detail_text(detail) if "=" in detail else detail).replace(" ()", "")
        return text if text else f"failed the {label}"

    def _keep_below_bar(self, gate, before: list, kept: list, dropped: list) -> tuple:
        """A gate's quality drops stay in the portfolio below the bar: each one keeps `below_bar_gate` (the
        gate code) and `below_bar_reason` (plain words) and is never selected. Rules in
        _BELOW_BAR_REMOVED_RULES (ungrounded designs) stay removed. Returns (kept, removed, below)."""
        removed, below = [], []
        for uc, reason in dropped or []:
            if self._gate_rule(reason) in self._BELOW_BAR_REMOVED_RULES:
                removed.append((uc, reason))
                continue
            below.append(uc)
            if not uc.get("below_bar_gate"):
                uc["below_bar_gate"] = str(reason)
                uc["below_bar_reason"] = self._below_bar_gate_text(gate, reason)
        if below:
            self.logger.info(f"[BELOW-BAR FIRED] {gate}: {inspire_plural(len(below), 'use case stays', 'use cases stay')} below the bar "
                             f"with {'its' if len(below) == 1 else 'their'} reason instead of being dropped"
                             + (f"; {len(removed)} removed as ungrounded" if removed else ""))
        keep = {id(uc) for uc in kept} | {id(uc) for uc in below}
        return [uc for uc in before if id(uc) in keep], removed, below

    def _record_gate_exception(self, gate, err, use_cases, mark=True):
        import traceback as _tb
        frames = _tb.extract_tb(err.__traceback__)[-3:] if getattr(err, "__traceback__", None) else []
        where = " <- ".join(f"{f.name}:{f.lineno}" for f in reversed(frames)) or "unknown"
        message = redact_error(err)
        ucs = use_cases or []
        if mark:
            for uc in ucs:
                tags = uc.get("gate_unverified")
                if not isinstance(tags, list):
                    tags = []
                    uc["gate_unverified"] = tags
                if gate not in tags:
                    tags.append(gate)
        self.logger.warning(
            f"[GATE_UNVERIFIED FIRED] {gate} raised {type(err).__name__}: {message} (at {where}); "
            f"{inspire_plural(len(ucs), 'UC')} kept" + (" and marked gate_unverified" if mark else ""))
        self._honesty().setdefault("gate_exceptions", []).append(
            {"gate": gate, "error": f"{type(err).__name__}: {message}", "where": where,
             "ucs": len(ucs), "marked": bool(mark)})
        try:
            NEXT_ACTIONS.add("GATE_UNVERIFIED", severity="HIGH", phase=gate.split("_")[0], step=gate,
                             evidence=f"{gate} raised {type(err).__name__}: {message}; {inspire_plural(len(ucs), 'UC')} unverified")
        except Exception:
            pass

    def _uc_dedup_signature(self, uc: dict) -> tuple:
        """Shared duplicate-decision signature for G2, Q2 and Phase L L9:
        (verb family, decision-object tokens, sorted lowercase tables, technique family).
        Synonym and nominalized verbs, plurals and reordered words collide; a different decision
        object, table set or technique family does not."""
        uc = uc if isinstance(uc, dict) else {}
        text = str(uc.get("Name") or uc.get("usecase") or uc.get("use_case") or "").strip()
        if not text:
            text = re.split(r"[.;\n]", str(uc.get("Statement") or ""), maxsplit=1)[0]
        verb, objects = self._decision_object_key(text)
        return (verb, objects,
                tuple(sorted(set(self._uc_table_refs(uc)))),
                self._signature_family(self._technique_family(uc.get("Analytics Technique"))))

    def _decision_object_key(self, text) -> tuple:
        clause = re.split(r"\s+(?:to|so that|in order to)\s+", str(text or "").lower(), maxsplit=1)[0]
        tokens = re.findall(r"[a-z0-9]+", clause)
        verbs = self._DEDUP_VERB_FAMILIES
        verb_idx = 0 if tokens and tokens[0] in verbs else None
        if verb_idx is None:
            nominal = [i for i, tok in enumerate(tokens) if tok in verbs and tok.endswith(("ion", "ing", "sis"))]
            plain = [i for i, tok in enumerate(tokens) if tok in verbs]
            verb_idx = (nominal or plain or [None])[0]
        objects = set()
        for i, tok in enumerate(tokens):
            if i == verb_idx or tok in self._DEDUP_STOPWORDS:
                continue
            if len(tok) > 4 and tok.endswith("ies"):
                tok = tok[:-3] + "y"
            elif len(tok) > 3 and tok.endswith("s") and not tok.endswith("ss"):
                tok = tok[:-1]
            objects.add(tok)
        return (verbs[tokens[verb_idx]] if verb_idx is not None else "", tuple(sorted(objects)))

    _ELITE_ACTION_CLUSTERS = {
        "REDUCE": "MOVE_KPI", "INCREASE": "MOVE_KPI", "OPTIMIZE": "MOVE_KPI",
        "PREDICT": "PREDICT", "DETECT": "DETECT", "RECOMMEND": "RECOMMEND",
        "ALLOCATE": "ALLOCATE", "CLASSIFY": "CLASSIFY", "PRIORITIZE": "PRIORITIZE",
        "ASSESS": "ASSESS", "ANALYZE": "ANALYZE", "TRACK": "TRACK", "SIMULATE": "SIMULATE",
    }
    _ELITE_DECISION_FILLERS = frozenset({
        "which", "what", "how", "when", "who", "whom", "where", "whether", "much", "many",
        "receive", "receives", "enter", "enters", "get", "gets", "take", "takes", "give", "gives",
        "weekly", "monthly", "daily", "quarterly", "annual", "annually", "week", "month", "day",
        "quarter", "year", "cycle", "ahead", "time", "window", "season", "seasonal", "period",
        "next", "upcoming", "current", "high", "low", "top", "bottom", "best", "worst",
    })
    _ELITE_GENERIC_TOKENS = frozenset({
        "revenue", "sales", "cost", "costs", "margin", "margins", "profit", "profits",
        "profitability", "spend", "spending", "price", "prices", "pricing", "value", "rate",
        "rates", "loss", "losses", "roi", "kpi", "performance", "efficiency", "growth", "budget",
        "cash", "dollar", "dollars", "amount", "amounts", "money",
    })

    def _norm_identity_text(self, text) -> str:
        return " ".join(re.findall(r"[a-z0-9]+", str(text if text is not None else "").lower()))

    def _elite_assessment_dict(self, uc: dict) -> dict:
        a = (uc or {}).get("elite_assessment")
        return a if isinstance(a, dict) else {}

    def _elite_table_tokens(self, uc: dict) -> set:
        a = self._elite_assessment_dict(uc)
        refs = list(self._uc_table_refs(uc))
        for extra in (a.get("tables_involved"), a.get("primary_table"), uc.get("Primary Table")):
            for part in re.split(r"[,;\n]", str(extra if extra is not None else "")):
                ref = self._normalize_table_ref(part)
                if ref and ref not in refs:
                    refs.append(ref)
        tokens = set()
        for ref in refs:
            name = ref.split(".")[-1]
            for tok in re.split(r"[^a-z0-9]+", name.lower()):
                if len(tok) >= 2:
                    tokens.add(tok)
        return tokens

    def _elite_object_tokens(self, text, table_tokens) -> set:
        out = set()
        for tok in re.findall(r"[a-z0-9]+", str(text if text is not None else "").lower()):
            if len(tok) > 4 and tok.endswith("ies"):
                tok = tok[:-3] + "y"
            elif len(tok) > 3 and tok.endswith("s") and not tok.endswith("ss"):
                tok = tok[:-1]
            if (len(tok) < 3 or tok in self._DEDUP_STOPWORDS or tok in self._ELITE_DECISION_FILLERS
                    or tok in self._ELITE_GENERIC_TOKENS or tok in self._DEDUP_VERB_FAMILIES
                    or tok in table_tokens):
                continue
            out.add(tok)
        return out

    def _elite_decision_identity(self, uc: dict) -> dict:
        a = self._elite_assessment_dict(uc)
        title = str(uc.get("usecase") or uc.get("use_case") or uc.get("Name") or "")
        verb, _objects = self._decision_object_key(title)
        tables = self._elite_table_tokens(uc)
        return {
            "owner": self._norm_identity_text(a.get("decision_owner")),
            "action": self._ELITE_ACTION_CLUSTERS.get(verb, ""),
            "title": self._norm_identity_text(title),
            "objects": self._elite_object_tokens(title + " " + str(a.get("decision") or ""), tables),
            "kpi": self._elite_object_tokens(a.get("kpi"), tables),
            "technique": self._technique_family(uc.get("Analytics Technique")),
            "primary_table": self._norm_identity_text(self._uc_primary_table(uc)),
        }

    def _are_elite_decision_twins(self, a: dict, b: dict) -> bool:
        if not a["owner"] or a["owner"] != b["owner"]:
            return False
        if not a["action"] or a["action"] != b["action"]:
            return False
        if a["primary_table"] == b["primary_table"] and a["technique"] == b["technique"]:
            return False
        if not (a["objects"] & b["objects"]):
            return False
        if a["kpi"] and b["kpi"] and not (a["kpi"] & b["kpi"]):
            return False
        return True

    def _elite_twin_keys(self, uc: dict) -> set:
        keys = set()
        family = self._signature_family(self._technique_family(uc.get("Analytics Technique")))
        title = " ".join(re.findall(r"[a-z0-9]+", str(uc.get("usecase") or uc.get("use_case") or "").lower()))
        if title:
            keys.add(("title", title))
        for text in (uc.get("usecase") or uc.get("use_case"), uc.get("Name")):
            verb, objects = self._decision_object_key(text)
            if verb and objects:
                keys.add(("decision", verb, objects, family))
        return keys

    @staticmethod
    def _uc_title(uc) -> str:
        uc = uc if isinstance(uc, dict) else {}
        return str(uc.get("Name") or uc.get("usecase") or uc.get("use_case") or "").strip()

    def _collapse_elite_decision_twins(self, elite: list) -> tuple:
        n = len(elite)
        parent = list(range(n))

        def _root(i):
            while parent[i] != i:
                parent[i] = parent[parent[i]]
                i = parent[i]
            return i

        def _union(i, j):
            parent[_root(i)] = _root(j)

        owner = {}
        for idx, uc in enumerate(elite):
            for key in self._elite_twin_keys(uc):
                if key in owner:
                    _union(idx, owner[key])
                else:
                    owner[key] = idx
        ids = [self._elite_decision_identity(uc) for uc in elite]
        for i in range(n):
            for j in range(i + 1, n):
                if _root(i) != _root(j) and self._are_elite_decision_twins(ids[i], ids[j]):
                    _union(i, j)
        groups = {}
        for idx in range(n):
            groups.setdefault(_root(idx), []).append(idx)
        kept, twins = [], {}
        for members in groups.values():
            ranked = sorted(members, key=lambda i: (self._final_rank_key(elite[i]), i))
            winner = elite[ranked[0]]
            kept.append(ranked[0])
            collapsed = winner.setdefault("decision_twins_collapsed", [])
            for loser_idx in ranked[1:]:
                loser = elite[loser_idx]
                self._carry_user_request(winner, loser)
                twins[id(loser)] = winner
                collapsed.append({"No": loser.get("No", "UNKNOWN"), "Name": self._uc_title(loser),
                                  "elite_score": loser.get("elite_score")})
        kept_set = set(kept)
        return [uc for idx, uc in enumerate(elite) if idx in kept_set], twins

    def _dedup_by_signature(self, use_cases: list, reason: str, rank=None) -> tuple:
        if not use_cases:
            return use_cases, []

        def _evidence_rank(uc):
            design = str(uc.get("Solution") or "") + " " + str(uc.get("High Level Design") or "")
            return (self._score_rank_part(uc.get("Inspire Score"))
                    + (-len(set(re.findall(r"`([A-Za-z_][A-Za-z0-9_.]*)`", design))),))

        rank_key = rank or _evidence_rank
        groups = {}
        for idx, uc in enumerate(use_cases):
            groups.setdefault(self._uc_dedup_signature(uc), []).append((idx, uc))
        winners, merge_log = set(), []
        for sig, members in groups.items():
            ranked = sorted(members, key=lambda item: (rank_key(item[1]), item[0]))
            winners.add(ranked[0][0])
            for _idx, loser in ranked[1:]:
                self._carry_user_request(ranked[0][1], loser)
                merge_log.append({"kept": ranked[0][1].get("No", "UNK"), "dropped": loser.get("No", "UNK"),
                                  "reason": reason, "tables": list(sig[2]), "technique": sig[3]})
        return [uc for idx, uc in enumerate(use_cases) if idx in winners], merge_log

    @staticmethod
    def _is_join_identifier(col) -> bool:
        c = str(col or "").strip().lower()
        return bool(c) and c not in _GENERIC_KEY_NAMES and c not in _CODE_NAMES and _is_key_like_column(c)

    def _join_graph(self) -> dict:
        index = self._gate_schema_index()
        loader = getattr(self, "data_loader", None)
        universe = set(index["originals"].values())
        for tup in (getattr(loader, "all_table_tuples", None) or []):
            try:
                c, s, t = tuple(tup)[:3]
                universe.add((str(c), str(s), str(t)))
            except Exception:
                continue
        relations = []
        if loader is not None and hasattr(loader, "get_foreign_key_relations"):
            try:
                relations = list(loader.get_foreign_key_relations(universe) or [])
            except Exception as e:
                self.logger.warning(f"[JOIN_PATH] foreign keys unavailable ({redact_error(e)}); "
                                    f"join paths use shared identifier columns only")
        fingerprint = (id(loader), len(relations), len(universe), len(index["tables"]))
        cached = index.get("join_graph")
        if cached is not None and cached["fingerprint"] == fingerprint:
            return cached
        provenance = {}
        if relations and hasattr(loader, "get_table_relations"):
            for source_table in sorted({tuple(str(x) for x in tuple(rel)[:3]) for rel in relations}):
                try:
                    for rel, source, _confidence in loader.get_table_relations(*source_table) or []:
                        provenance[tuple(str(x).lower() for x in tuple(rel)[:8])] = source
                except Exception as e:
                    self.logger.debug(f"[JOIN_PATH] FK provenance unavailable for {'.'.join(source_table)}: "
                                      f"{redact_error(e)}")
        fk = {"declared": {}, "inferred": {}}
        for rel in relations:
            try:
                rel = tuple(rel)
                src = f"{rel[0]}.{rel[1]}.{rel[2]}".lower()
                ref = f"{rel[4]}.{rel[5]}.{rel[6]}".lower()
                edge = f"{src}.{str(rel[3]).lower()} -> {ref}.{str(rel[7]).lower()}"
                rel_key = tuple(str(x).lower() for x in rel[:8])
            except Exception:
                continue
            if src == ref:
                continue
            tier = "declared" if provenance.get(rel_key) == "declared" else "inferred"
            fk[tier].setdefault(src, []).append((ref, edge))
            fk[tier].setdefault(ref, []).append((src, edge))
        id_cols = {}
        for fqn, cols in index["tables"].items():
            for col in cols:
                if self._is_join_identifier(col):
                    id_cols.setdefault(col, set()).add(fqn)
        limit = max(5, len(index["tables"]) // 2)
        shared = {col: tabs for col, tabs in id_cols.items() if 2 <= len(tabs) <= limit}
        shared_by_table = {}
        for col in sorted(shared):
            for fqn in shared[col]:
                shared_by_table.setdefault(fqn, []).append(col)
        graph = {"fingerprint": fingerprint, "fk": fk, "shared": shared, "shared_by_table": shared_by_table,
                 "allowed": set(index["tables"]) | {".".join(u).lower() for u in universe}}
        index["join_graph"] = graph
        return graph

    @staticmethod
    def _join_path_bfs(graph, refs, tier, max_hops=4):
        from collections import deque
        root, targets = refs[0], set(refs[1:])
        fk_tiers = ("declared",) if tier == "declared" else ("declared", "inferred")
        parents, depth = {root: None}, {root: 0}
        queue = deque([root])
        while queue:
            node = queue.popleft()
            if depth[node] >= max_hops:
                continue
            nbrs = []
            for t in fk_tiers:
                nbrs.extend(sorted(graph["fk"][t].get(node, ())))
            if tier == "shared_column":
                for col in graph["shared_by_table"].get(node, ()):
                    for other in sorted(graph["shared"][col]):
                        if other != node:
                            nbrs.append((other, f"{node}.{col} = {other}.{col}"))
            for nbr, edge in nbrs:
                if nbr in parents or (nbr not in graph["allowed"] and nbr not in targets):
                    continue
                parents[nbr] = (node, edge)
                depth[nbr] = depth[node] + 1
                queue.append(nbr)
        if not targets.issubset(parents):
            return None
        path = []
        for target in refs[1:]:
            chain, cur = [], target
            while parents[cur] is not None:
                prev, edge = parents[cur]
                chain.append(edge)
                cur = prev
            for edge in reversed(chain):
                if edge not in path:
                    path.append(edge)
        return path

    @staticmethod
    def _join_path_tables(path) -> list:
        tables = []
        for edge in path or []:
            for side in re.split(r"\s*(?:->|=)\s*", str(edge)):
                table = side.strip().rsplit(".", 1)[0].lower()
                if table.count(".") == 2 and table not in tables:
                    tables.append(table)
        return tables

    def _find_join_path(self, tables: list) -> dict:
        """Join-path contract for Q3 R4 and elite verification. BFS over
        `data_loader.get_foreign_key_relations` for every table in the schema universe, through
        intermediate tables present in the schema (max 4 hops per table), preferring declared
        edges, then naming-inferred edges, then identical identifier-like columns shared by two
        tables. Returns {"connected", "path", "strength"}; strength is "declared" | "inferred" |
        "shared_column" | "none". Declared vs inferred is the provenance
        `data_loader.get_table_relations` records; an edge without recorded provenance counts as
        inferred. Safe without a data loader."""
        refs = []
        for t in tables or []:
            ref = self._normalize_table_ref(t)
            if ref and not ref.lower().startswith("/volumes") and ref not in refs:
                refs.append(ref)
        if len(refs) < 2:
            return {"connected": True, "path": [], "strength": "none"}
        graph = self._join_graph()
        for tier in ("declared", "inferred", "shared_column"):
            path = self._join_path_bfs(graph, refs, tier)
            if path is not None:
                return {"connected": True, "path": path, "strength": tier}
        return {"connected": False, "path": [], "strength": "none"}

    def _phaseG_validate_schema_completeness(self, use_cases: list) -> list:
        """Phase G2: drop UCs missing any required field."""
        required = ("Name", "Statement", "Solution", "Tables Involved", "Analytics Technique")
        kept = []
        dropped = 0
        for uc in use_cases:
            missing = [f for f in required if not str(uc.get(f) or "").strip()]
            if missing:
                dropped += 1
                self.logger.info(f"G schema-completeness: dropping UC {uc.get('No','UNK')} (empty {missing})")
                try:
                    NEXT_ACTIONS.add("UC_SCHEMA_INCOMPLETE", severity="HIGH",
                                     phase="G2", step="validate_schema_completeness",
                                     evidence=f"UC {uc.get('No','UNK')} empty: {missing}")
                except Exception:
                    pass
                continue
            kept.append(uc)
        if dropped:
            self.logger.warning(f"G2 schema-completeness: dropped {dropped} incomplete UCs")
        return kept

    def _phaseG_validate_name_uniqueness(self, use_cases: list) -> list:
        """Phase G2: drop exact decision duplicates via the shared `_uc_dedup_signature`; the same
        name on different tables or with a different technique family is not a duplicate."""
        if not use_cases:
            return use_cases
        kept, merged = self._dedup_by_signature(use_cases, "G2_DUPLICATE_DECISION")
        if merged:
            self.logger.info(f"G2 name-uniqueness: dropped {inspire_plural(len(merged), 'duplicate decision')}: "
                             + ", ".join(f"{m['dropped']}->{m['kept']}" for m in merged[:10]))
        return kept

    def _phaseG_validate_no_catchall_technique(self, use_cases: list) -> list:
        """Phase G2 / Rule 12: a catch-all technique label is replaced by the technique family whose
        concrete method the UC's own Solution / High Level Design names; UCs that name no concrete
        method are dropped."""
        kept, dropped, relabelled = [], 0, 0
        order = [key for key, _l, _a, _m in self._TECHNIQUE_FAMILIES]
        for uc in use_cases:
            t = " ".join(str(uc.get("Analytics Technique") or "").lower().split())
            if t not in self._GATE_CATCHALL_TECHNIQUES:
                kept.append(uc)
                continue
            design = str(uc.get("Solution") or "") + "\n" + str(uc.get("High Level Design") or "")
            found = self._technique_mentions(design, methods_only=True)
            if found:
                family = min(found, key=lambda k: (found[k], order.index(k)))
                uc["Analytics Technique"] = self._technique_label(family)
                relabelled += 1
                try:
                    NEXT_ACTIONS.add("UC_CATCHALL_TECHNIQUE", severity="INFO",
                                     phase="G2", step="validate_no_catchall_technique",
                                     evidence=f"UC {uc.get('No','UNK')} technique '{t}' relabelled to "
                                              f"'{uc['Analytics Technique']}' from its own design text")
                except Exception:
                    pass
                kept.append(uc)
                continue
            dropped += 1
            self.logger.info(f"G2 catch-all: dropping UC {uc.get('No','UNK')} with technique='{t}' and no concrete method")
            try:
                NEXT_ACTIONS.add("UC_CATCHALL_TECHNIQUE", severity="HIGH",
                                 phase="G2", step="validate_no_catchall_technique",
                                 evidence=f"UC {uc.get('No','UNK')} technique={t}; design names no concrete method")
            except Exception:
                pass
        if relabelled:
            self.logger.info(f"G2 catch-all: relabelled {inspire_plural(relabelled, 'UC from the method its', 'UCs from the method their')} design names")
        if dropped:
            self.logger.warning(f"G2 catch-all: dropped {dropped} UCs with umbrella technique names")
        return kept

    _R13_SNAKE_RE = re.compile(r"[a-z][a-z0-9]*(?:_[a-z0-9]+)+")
    _R13_BACKTICKED_RE = re.compile(r"`([A-Za-z_][A-Za-z0-9_.]*)`(?!\s*\()")
    _R13_QUALIFIED_RE = re.compile(r"(?<![\w.`])([A-Za-z_]\w*(?:\.[A-Za-z_]\w*){0,2}\.[a-z][a-z0-9]*(?:_[a-z0-9]+)+)(?![\w`(])")
    _R13_CUED_RES = (re.compile(r"(?i)\b(?:columns?|fields?)\s+([a-z][a-z0-9]*(?:_[a-z0-9]+)+)\b"),
                     re.compile(r"(?i)(?<![\w`.])([a-z][a-z0-9]*(?:_[a-z0-9]+)+)\s+(?:columns?|fields?)\b"))
    _R13_DERIVED_NOUNS = (r"(?:share|ratio|rate|count|number|sum|total|average|mean|percentage|percent|fraction|proportion|"
                          r"difference|gap|flag|score|indicator)")
    _R13_DEFINED_BEFORE_RE = re.compile(
        r"(?i)(?:\b(?:compute[sd]?|computing|calculate[sd]?|calculating|derive[sd]?|deriving|define[sd]?|defining|create[sd]?|"
        r"creating|build|builds|building|engineer(?:s|ed|ing)?|output(?:s|ted|ting)?|produce[sd]?|producing|return(?:s|ed|ing)?|"
        r"write[sd]?|writing|wrote|store[sd]?|storing|label(?:l?ed|s)?|predict(?:s|ed|ing)?|forecast(?:s|ed|ing)?|estimate[sd]?|"
        r"estimating|score[sd]?|scoring|into|called|named|settings?|parameters?|thresholds?|widgets?)\s+"
        r"(?:(?:a|an|the|new|derived|computed|calculated|per|each|its|their|one)\s+|[\w-]+-level\s+){0,3}"
        r"(?:(?:column|field|feature|metric|measure|kpi|flag|score|indicator|variable|ratio|rate|alias|output|target|label|setting|"
        r"parameter|threshold)s?\s+)?(?:called\s+|named\s+)?|\)\s*as\s+)`?$")
    _R13_DEFINED_SQL_AS_RE = re.compile(r"[\w`)\]]\s+AS\s+`?$")
    _R13_DEFINED_AFTER_RE = re.compile(
        r"(?i)^`?\s*(?::=|=(?!=)|\(\s*(?:the\s+)?" + _R13_DERIVED_NOUNS + r"\b|,?\s*(?:which\s+is\s+|is\s+|being\s+)?"
        r"(?:defined|computed|calculated|derived|built|engineered|created|measured)\s+(?:as|from|by|over|using|on|with)\b|"
        r"\(\s*[^()\n]*?\w\s*[/*+]\s*\w[^()\n]*\)|,?\s*(?:i\.e\.,?\s*|is\s+|being\s+|means\s+)?(?:the|a|an)\s+" + _R13_DERIVED_NOUNS + r"\s+of\b|\s+as\s+(?:the\s+)?" + _R13_DERIVED_NOUNS + r"\s+of\b|"
        r"\s+(?:metric|kpi|feature|score|flag|indicator|ratio|measure|setting|parameter|threshold|widget)s?\b)")
    _R13_REPAIR_FIELDS = ("Solution", "High Level Design", "high_level_design", "Statement", "Business Value", "Columns Involved")

    @classmethod
    def _r13_defined(cls, name, text) -> bool:
        for match in re.finditer(r"(?<![\w.])`?" + re.escape(name) + r"(?![\w])", text, re.I):
            before, after = text[max(0, match.start() - 120):match.start()], text[match.end():match.end() + 80]
            if cls._R13_DEFINED_BEFORE_RE.search(before) or cls._R13_DEFINED_SQL_AS_RE.search(before) or cls._R13_DEFINED_AFTER_RE.match(after):
                return True
        return False

    @classmethod
    def _r13_owner_tables(cls, prefix, tables) -> list:
        prefix = prefix.lower()
        return [t for t in tables if t == prefix or t.endswith("." + prefix)]

    @classmethod
    def _invented_column_mentions(cls, uc, tables, fields=("Solution", "High Level Design", "high_level_design")) -> tuple:
        design = "\n".join(str(uc.get(f) or "") for f in fields).replace("`.`", ".")
        defining = "\n".join(str(uc.get(f) or "") for f in dict.fromkeys(
            tuple(fields) + ("Solution", "High Level Design", "high_level_design", "Statement", "Business Value")))
        leaves = {t.rsplit(".", 1)[-1] for t in tables}
        columns = {c for cols in tables.values() for c in cols}
        mentions = [(m.group(1), True, False) for m in cls._R13_BACKTICKED_RE.finditer(design)]
        mentions += [(m.group(1), False, False) for m in cls._R13_QUALIFIED_RE.finditer(design)]
        mentions += [(m.group(1), False, True) for r in cls._R13_CUED_RES for m in r.finditer(design)]
        invented, unknown, seen = [], [], set()
        for name, backticked, cued in mentions:
            low = name.lower()
            if low in seen or name.upper() in cls._GATE_SQL_KEYWORDS or low.startswith("ai_") or low in tables or low in leaves:
                continue
            seen.add(low)
            if "." in low:
                prefix, column = low.rsplit(".", 1)
                owners = cls._r13_owner_tables(prefix, tables)
                if any(column in tables[t] for t in owners) or column in columns and not owners or cls._r13_defined(column, defining):
                    continue
                if not owners:
                    unknown += [name] if backticked else []
                    continue
                invented.append({"name": name, "column": column, "prefix": name.rsplit(".", 1)[0], "table": owners[0]})
            elif not backticked and not cued:
                continue
            elif low in columns or cls._r13_defined(name, defining):
                continue
            elif cued or cls._R13_SNAKE_RE.fullmatch(name):
                invented.append({"name": name, "column": low, "prefix": "", "table": ""})
            else:
                unknown.append(name)
        return invented, unknown

    @classmethod
    def _r13_obvious_column(cls, column, candidates) -> str:
        import difflib
        terms = lambda name: frozenset(_implement_vibes_token(w) for w in re.split(r"[^a-z0-9]+", name.lower()) if w)
        same = sorted({c for c in candidates if terms(c) == terms(column)})
        if len(same) == 1:
            return same[0]
        ranked = sorted(((difflib.SequenceMatcher(None, column, c).ratio(), c) for c in set(candidates)), reverse=True)
        if ranked and ranked[0][0] >= 0.9 and (len(ranked) == 1 or ranked[1][0] < 0.9):
            return ranked[0][1]
        return ""

    def _r13_repair_invented(self, uc, tables, cited) -> list:
        invented, _unknown = self._invented_column_mentions(uc, tables)
        left = []
        for item in invented:
            column, prefix, owner = item["column"], item["prefix"], item["table"]
            fixed, pattern, swap = "", None, ""
            if owner:
                fixed = self._r13_obvious_column(column, tables.get(owner, {}))
                holders = [t for t in cited if column in tables.get(t, {})]
                if not fixed and len(holders) == 1:
                    depth = len(prefix.split("."))
                    swap = ".".join(holders[0].split(".")[-depth:])
                    pattern = re.compile(r"(?i)(?<![\w.])(`?)" + re.escape(prefix).replace(r"\.", r"`?\.`?") + r"(`?\.`?"
                                         + re.escape(column) + r")(?![\w])")
            else:
                fixed = self._r13_obvious_column(column, {c for t in cited for c in tables.get(t, {})})
            if not fixed and not swap:
                left.append(item["name"])
                continue
            for field in self._R13_REPAIR_FIELDS:
                if isinstance(uc.get(field), str):
                    uc[field] = (pattern.sub(lambda m: m.group(1) + (m.group(1) + "." + m.group(1)).join(swap.split(".")) + m.group(2),
                                             uc[field]) if swap else
                                 re.sub(r"(?i)(?<![A-Za-z0-9_])" + re.escape(column) + r"(?![A-Za-z0-9_])", fixed, uc[field]))
            target = f"{swap}.{column}" if swap else fixed
            self.logger.warning(f"[R13-INVENTED-COLUMN FIRED] Q3 R13 repairs {uc.get('No', 'UNK')}: it named `{item['name']}`, which no "
                                f"table in scope has, so Inspire wrote the real column `{target}` in its place")
        return left

    _R13_JUDGE_SCHEMA = {"name": "invented_columns", "schema": {
        "type": "object",
        "properties": {"checks": {"type": "array", "items": {
            "type": "object",
            "properties": {"use_case": {"type": "string"}, "name": {"type": "string"},
                           "verdict": {"type": "string", "enum": ["invented_source_column", "derived"]},
                           "reason": {"type": "string"}},
            "required": ["use_case", "name", "verdict", "reason"]}}},
        "required": ["checks"]}}
    _R13_JUDGE_BATCH = 20

    @staticmethod
    def _r13_judge_prompt(pending) -> str:
        blocks = []
        for uc, names, columns in pending:
            design = "\n".join(str(uc.get(f) or "") for f in ("Solution", "High Level Design", "high_level_design", "Statement",
                                                               "Business Value") if str(uc.get(f) or "").strip())
            blocks.append(f"### {uc.get('No', 'UNK')}: {uc.get('Name') or uc.get('Use Case') or ''}\n"
                          f"Real columns of its tables: {', '.join(sorted(columns))[:3000]}\n"
                          f"Names to judge: {', '.join(names)}\n\n{design[:4000]}")
        return ("You check use case designs against the real columns of the tables they read.\n"
                "Each use case below names identifiers that no table in scope has. For every name to judge, decide:\n"
                "- invented_source_column: the text reads it as a column already stored in a source table (it is read, "
                "joined, filtered or grouped on as if it exists), so the design depends on data that is not there.\n"
                "- derived: the use case itself computes, defines, outputs or configures it (a metric, ratio, flag, alias, "
                "feature, score, model output, result column, parameter or setting), even when the wording is unusual.\n"
                "Judge from the use case text and the real columns only. Answer for every name, with a short reason.\n\n"
                "OUTPUT (STRICT JSON): {\"checks\": [{\"use_case\": \"<id>\", \"name\": \"<name exactly as given>\", "
                "\"verdict\": \"invented_source_column\" or \"derived\", \"reason\": \"<short reason>\"}]}\n\n"
                + "\n\n".join(blocks))

    def _r13_judge_invented(self, pending) -> dict:
        verdicts = {}
        for start in range(0, len(pending), self._R13_JUDGE_BATCH):
            batch = pending[start:start + self._R13_JUDGE_BATCH]
            asked = {(str(uc.get("No", "UNK")), n.lower()) for uc, names, _c in batch for n in names}
            answers = {}

            def ask(skip_cache):
                parsed = self._implement_llm_object("q3_r13_invented_columns", "Q3_R13_Invented_Columns",
                                                    self._r13_judge_prompt(batch), self._R13_JUDGE_SCHEMA, skip_cache=skip_cache)
                for item in parsed.get("checks") or []:
                    key = (str(item.get("use_case") or "").strip(), str(item.get("name") or "").strip().strip("`").lower())
                    if key in asked and item.get("verdict") in ("invented_source_column", "derived"):
                        answers[key] = (item["verdict"], " ".join(str(item.get("reason") or "").split())[:200])

            def give_up(problem, left):
                for key in sorted(left):
                    self.logger.warning(f"[R13-JUDGE-UNCHECKED FIRED] Q3 R13 keeps {key[0]}: the invented-column check failed again, "
                                        f"so `{key[1]}` could not be confirmed as an invented source column: {problem}")

            self._llm_ask_twice(
                ask, lambda: asked - set(answers),
                lambda problem, _left: self.logger.warning(f"[R13-JUDGE-RETRY FIRED] Q3 R13: the invented-column check failed, so "
                                                           f"Inspire asks it once more without the cache: {problem}"),
                give_up, unanswered=lambda left: f"no usable answer for {inspire_plural(len(left), 'name')}")
            verdicts.update(answers)
        return verdicts

    def _phaseE0_catalog_drift_check(self, session_id):
        """Phase E0 (Gap 4): at Generate entry, flag tracked UCs whose cited tables no longer exist.
        Metadata only: one parameterized information_schema query per referenced catalog. Tables in
        a catalog whose information_schema cannot be read are unverifiable, not drifted."""
        if not self._tracking_table_name:
            return []
        sid = inspire_session_number(session_id)
        try:
            uc_rows = execute_sql(
                self.spark,
                f"SELECT id, use_case, tables_involved FROM {self._tracking_table_name} WHERE session_id = {sid}",
                self.logger)
        except Exception as e:
            self.logger.warning(f"E0 drift check: failed to read UCs: {redact_error(e)}")
            return []
        refs_by_uc, wanted = [], {}
        for r in uc_rows:
            refs = [t for t in self._uc_table_refs({"Tables Involved": getattr(r, "tables_involved", "") or ""})
                    if t.count(".") == 2 and not t.lower().startswith("/volumes")]
            refs_by_uc.append((r, refs))
            for t in refs:
                cat, sch, _tbl = t.split(".")
                wanted.setdefault(cat, set()).add(sch)
        existing = {}
        for cat in sorted(wanted):
            if "`" in cat:
                existing[cat] = None
                continue
            schemas = sorted(wanted[cat])
            args = {f"s{i}": s for i, s in enumerate(schemas)}
            markers = ", ".join(f":s{i}" for i in range(len(schemas)))
            try:
                rows = execute_sql(
                    self.spark,
                    f"SELECT table_schema, table_name FROM {inspire_quote_identifier(cat)}.information_schema.tables "
                    f"WHERE table_schema IN ({markers})",
                    self.logger, args=args)
                existing[cat] = {f"{str(x['table_schema']).lower()}.{str(x['table_name']).lower()}" for x in rows}
            except Exception as e:
                existing[cat] = None
                self.logger.warning(f"E0 drift check: cannot read {cat}.information_schema "
                                    f"({redact_error(e)}); its tables are unverifiable, not reported as drift")
        drifted, unverifiable = [], 0
        for r, refs in refs_by_uc:
            missing = []
            for t in refs:
                cat, sch, tbl = t.split(".")
                known = existing.get(cat)
                if known is None:
                    unverifiable += 1
                elif f"{sch}.{tbl}" not in known:
                    missing.append(t)
            if missing:
                drifted.append({"id": r.id, "table": missing[0], "missing": missing})
                try:
                    NEXT_ACTIONS.add(
                        "UC_STALE_CATALOG_DRIFT", severity="HIGH",
                        phase="E0", step="catalog_drift_check",
                        evidence=f"UC {r.id} references {', '.join(missing[:5])} which is no longer in schema",
                        suggested_user_action="Rerun Discover to refresh UCs."
                    )
                except Exception:
                    pass
        if drifted:
            self.logger.warning(f"E0 CATALOG DRIFT: {inspire_plural(len(drifted), 'UC references', 'UCs reference')} tables no longer in schema"
                                + (f"; {inspire_plural(unverifiable, 'table reference')} unverifiable" if unverifiable else ""))
        elif unverifiable:
            self.logger.warning(f"E0 CATALOG DRIFT: no drift among verifiable tables; "
                                f"{inspire_plural(unverifiable, 'table reference')} unverifiable")
        else:
            self.logger.info("E0 CATALOG DRIFT: no drift detected")
        return drifted

    def _gate_ledger_drops(self, prefix: str) -> dict:
        ledger = self._honesty().get("gate_ledger") or {}
        return {gate: int(entry.get("dropped") or 0) for gate, entry in ledger.items()
                if str(gate).startswith(prefix) and isinstance(entry, dict) and entry.get("dropped")}

    def _phaseG_run_quality_gates(self, use_cases: list, full_schema_details: list) -> list:
        """Run G2 deterministic quality gates. Idempotent. A gate that raises is logged with a short
        traceback and the UCs it should have checked are kept but marked `gate_unverified`."""
        if not use_cases:
            return use_cases
        before = len(use_cases)
        steps = (
            ("G2_schema_completeness", lambda ucs: self._phaseG_validate_schema_completeness(ucs)),
            ("G2_name_uniqueness", lambda ucs: self._phaseG_validate_name_uniqueness(ucs)),
            ("G2_catchall_technique", lambda ucs: self._phaseG_validate_no_catchall_technique(ucs)),
        )
        for gate, run_gate in steps:
            n_in = len(use_cases)
            try:
                use_cases = run_gate(use_cases)
            except Exception as gate_err:
                self._record_gate_exception(gate, gate_err, use_cases)
                continue
            self._record_gate_ledger(gate, n_in, len(use_cases))
        self.logger.info(f"Phase G gates: {before} -> {inspire_plural(len(use_cases), 'use case')}")
        return use_cases

    def _phaseQ1_validate_grounding(self, use_cases: list, full_schema_details: list) -> tuple:
        """Phase Q1 GROUNDING (deterministic, metadata only). Returns (kept, dropped).

        Every table in Tables Involved must resolve to the schema universe: the schema rows, the
        business tables and every discovered table (technical and reference tables stay joinable).
        Backticks, separators and case are normalized, and a schema.table or bare table name that
        resolves to exactly one table is rewritten to its fully qualified name. Fails closed: with
        no table universe at all, every UC is dropped as unverifiable and none is reported grounded.
        """
        if not use_cases:
            return use_cases, []
        available = set()
        for (c, s, t, _col, _dtype, _cmt) in self._iter_schema_rows(full_schema_details):
            available.add(f"{c}.{s}.{t}".lower())
        for t in (getattr(self, "global_table_names", None) or ()):
            ref = self._normalize_table_ref(t)
            if ref.count(".") == 2:
                available.add(ref)
        # Extend with the FULL discovered table universe (includes tables
        # filtered as TECHNICAL / not-elected for UC generation — such tables
        # are NOT forgotten; they remain joinable/referenceable). A UC that
        # joins against a reference/technical table is valid as long as that
        # table actually exists in the passed schema. Per user 2026-04-19.
        for tup in (getattr(getattr(self, "data_loader", None), "all_table_tuples", None) or []):
            try:
                available.add(".".join(str(x) for x in tuple(tup)[:3]).lower())
            except Exception:
                continue
        # D-180A: a metric view is never a use case's table, so it does not ground one.
        available.difference_update(self._metric_views_by_fqn())
        if not available:
            self.logger.error(
                f"[Q1 FAIL_CLOSED FIRED] grounding cannot be checked: the schema universe has 0 tables; "
                f"{inspire_plural(len(use_cases), 'UC')} dropped as unverifiable, none reported grounded")
            self._honesty()["q1_grounding_unchecked"] = True
            try:
                NEXT_ACTIONS.add("UC_NOT_GROUNDED", severity="BLOCKING", phase="Q1", step="fail_closed",
                                 evidence=f"No schema available to ground {inspire_plural(len(use_cases), 'UC')}",
                                 suggested_user_action="Check catalog permissions and table selection, then rerun.")
            except Exception:
                pass
            return [], [(uc, "Q1_UNCHECKABLE:NO_SCHEMA") for uc in use_cases]
        by_suffix = {}
        for fqn in available:
            parts = fqn.split(".")
            if len(parts) == 3:
                by_suffix.setdefault(f"{parts[1]}.{parts[2]}", set()).add(fqn)
                by_suffix.setdefault(parts[2], set()).add(fqn)
        kept, dropped = [], []
        for uc in use_cases:
            refs = self._uc_table_refs(uc)
            if not refs:
                dropped.append((uc, "EMPTY_TABLES_INVOLVED"))
                continue
            real_refs = self._drop_metric_views(refs)
            if not real_refs:
                dropped.append((uc, "METRIC_VIEW_ONLY: a metric view is not a table, so the use case has no table to read"))
                continue
            if len(real_refs) != len(refs):
                self.logger.info(f"[METRIC-VIEW DROPPED FIRED] {uc.get('No', 'UNK')}: a metric view is left out of Tables Involved")
            refs = real_refs
            resolved, missing = [], []
            for ref in refs:
                # Volume paths (ai_parse_document use cases) pass through
                if ref.lower().startswith("/volumes"):
                    resolved.append(ref)
                elif ref in available:
                    resolved.append(ref)
                elif ref.count(".") < 2 and len(by_suffix.get(ref, ())) == 1:
                    resolved.append(next(iter(by_suffix[ref])))
                else:
                    missing.append(ref)
            if missing:
                dropped.append((uc, f"UC_NOT_GROUNDED: missing {missing[:3]}"))
                continue
            if getattr(getattr(self, "data_loader", None), "_person_relations", None):
                # REQ-373: a joined dataset is named once: two spellings of one table in Tables Involved list it once.
                resolved = list(dict.fromkeys(resolved))
            raw_parts = [p.strip().lower() for p in str(uc.get("Tables Involved") or "").split(",") if p.strip()]
            if raw_parts != [r.lower() for r in resolved]:
                uc["Tables Involved"] = ", ".join(resolved)
            kept.append(uc)
        if dropped:
            self.logger.warning(
                f"Q1 GROUNDING: dropped {implement_number_text(len(dropped))} of {inspire_plural(len(use_cases), 'use case')} "
                f"with ungrounded tables"
            )
            for uc, reason in dropped[:5]:
                self.logger.info(f"  dropped {uc.get('No', 'UNK')}: {reason}")
        else:
            self.logger.info(
                f"Q1 GROUNDING: all {inspire_plural(len(use_cases), 'use case')} grounded"
            )
        return kept, dropped

    def _metric_views_by_fqn(self) -> dict:
        """This run's metric views keyed by lower-case catalog.schema.name. A metric view is never a table of a use case."""
        evidence = getattr(self, "discovery_evidence", None) or {}
        return {str(v.get("fqn") or "").replace("`", "").strip().lower(): v for v in evidence.get("metric_views") or [] if isinstance(v, dict)}

    def _drop_metric_views(self, refs) -> list:
        """D-180A: a metric view is never a use case's table, so it is left out of the refs. Its definition source is never
        named in its place: the source may be gone, and only a table the grounded universe holds may be a use case's table."""
        views = self._metric_views_by_fqn()
        return [ref for ref in refs or [] if str(ref).replace("`", "").strip().lower() not in views]

    def _phaseQ2_canonical_dedup(self, use_cases: list) -> tuple:
        """Phase Q2 canonical dedup (deterministic). UCs that share `_uc_dedup_signature` are
        reduced to one twin: the higher score when one exists, then more backticked design
        evidence, then generation order. Returns (kept, merge_log)."""
        if not use_cases:
            return use_cases, []
        kept, merge_log = self._dedup_by_signature(use_cases, "EXACT_CANONICAL_DUPLICATE")
        if merge_log:
            rate = len(merge_log) / max(1, len(use_cases))
            level = "warning" if rate > 0.05 else "info"
            getattr(self.logger, level)(
                f"Q2 DEDUP: dropped {len(merge_log)} of {len(use_cases)} "
                f"as canonical duplicates (rate {rate*100:.1f}%)"
            )
            if rate > 0.05:
                self.logger.warning(
                    "Q2 DEDUP_RATE_HIGH (>5%): indicates prompt regression; "
                    "investigate which technique/tables cluster is over-represented"
                )
        else:
            self.logger.info(
                f"Q2 DEDUP: all {inspire_plural(len(use_cases), 'use case')} have distinct signatures"
            )
        return kept, merge_log

    def _q3_deep_evidence_reason(self, uc: dict, tables: list, family: str, design_text: str, cols: dict, event_tables=None):
        evidence = getattr(self, "discovery_evidence", None) or {}
        profiles = evidence.get("profiles") or {}
        if not profiles or not tables:
            return None
        rt = TECHNICAL_CONTEXT["runtime"]
        primary = profiles.get(str(tables[0]).replace("`", "").lower())
        if primary is not None and primary.get("rows") == 0:
            return f"Q3_R20_EMPTY_PRIMARY_TABLE:{tables[0]}"
        design_low = str(design_text or "").lower()
        table_set = {str(t).replace("`", "").lower() for t in tables}
        for match in evidence.get("join_matches") or []:
            if match.get("rate") is None or match["rate"] >= rt["deep_min_join_match"]:
                continue
            if match["child_table"] in table_set and match["parent_table"] in table_set \
                    and match["child_column"].lower() in design_low and match["parent_column"].lower() in design_low:
                return (f"Q3_R21_JOIN_MATCH_TOO_LOW:{match['child_table']}.{match['child_column']}->"
                        f"{match['parent_table']}.{match['parent_column']}={match['rate']}")
        grounded = [str(c).lower() for c in (self._grounded_column_mentions(design_text, cols) or [])]
        shares, filled = {}, {}
        for table in table_set:
            profile = profiles.get(table) or {}
            for column, info in (profile.get("columns") or {}).items():
                if column.lower() in grounded and info.get("null_share") is not None:
                    shares[column.lower()] = max(shares.get(column.lower(), 0.0), info["null_share"])
                    rows_filled = int(round((profile.get("rows") or 0) * (1.0 - info["null_share"])))
                    filled[column.lower()] = max(filled.get(column.lower(), 0), rows_filled)
        empty = sorted(c for c, n in filled.items() if n < rt["deep_min_signal_rows"])
        if filled and len(empty) == len(filled):
            return f"Q3_R22_KEY_SIGNAL_EMPTY:{','.join(f'{c}={filled[c]}' for c in empty[:5])}"
        for column in sorted(c for c, share in shares.items() if share >= rt["deep_mostly_null_share"]):
            self._add_gate_flag(uc, f"Q3_R22_MOSTLY_NULL_SIGNAL:{column}")
        if event_tables:
            singles = {table: self._one_row_per_case(profiles.get(table), log, rt) for table, log in event_tables.items()}
            if all(singles.values()):
                table = sorted(singles)[0]
                return f"Q3_R14_DATA_FIT_SCALE:R14_CASE_UNIQUE_PER_ROW:{table}.{singles[table]}"
        if family == "classification":
            title_stems = {token[:5] for token in re.split(r"[^a-z0-9]+", str(uc.get("Name") or "").lower()) if len(token) >= 3}
            labels, constant = {}, set()
            for table in table_set:
                for column, info in ((profiles.get(table) or {}).get("columns") or {}).items():
                    low = column.lower()
                    if low not in grounded or info.get("type_family") not in ("string", "boolean") or info.get("distinct") is None:
                        continue
                    if info["distinct"] <= 1:
                        constant.add(low)
                    stems = {token[:5] for token in re.split(r"[^a-z0-9]+", low) if len(token) >= 3}
                    if stems and stems <= title_stems:
                        labels[low] = max(labels.get(low, 0), info["distinct"])
            if labels and all(count <= 1 for count in labels.values()):
                return f"Q3_R24_SINGLE_CLASS_LABEL:{','.join(sorted(labels)[:5])}"
            for column in sorted(constant):
                self._add_gate_flag(uc, f"Q3_R24_CONSTANT_COLUMN:{column}")
        if family in self._TEMPORAL_FAMILIES and primary is not None:
            spans = []
            for info in (primary.get("columns") or {}).values():
                lo, hi = info.get("min"), info.get("max")
                if lo and hi:
                    try:
                        spans.append((inspire_parse_time(str(hi)[:19]) - inspire_parse_time(str(lo)[:19])).days)
                    except ValueError:
                        continue
            if spans and max(spans) < 60:
                self._add_gate_flag(uc, f"Q3_R23_THIN_TIME_COVERAGE:{max(spans)}_days")
        return None

    def _phaseQ3_validate_relevance(self, use_cases: list, full_schema_details: list) -> tuple:
        """Phase Q3 RELEVANCE (deterministic; metadata, plus aggregate evidence when Discovery Type
        is Deep). Returns (kept, dropped).

        Deep only: R20 drops an empty primary table, R21 drops a cited join whose measured match
        rate is below deep_min_join_match, R22 drops when every grounded signal column has fewer
        than deep_min_signal_rows non-null rows and flags mostly-null signal columns, R14 drops process
        mining and sequence analysis when every event table they cite holds one row per case id, R23 flags
        temporal analysis on less than 60 days of data, R24 drops a classification whose label
        columns (categorical columns named in the title) hold a single value and flags other
        constant categorical columns.

        Drops: R1 only technical tables (the agent's own table classification), R2 technique
        structurally unsupported by the cited tables' columns (numeric needs are waived when the
        cited columns carry no informative types), R4 no join path (`_find_join_path`), R7 three or
        more invented figures in Business Value, R9 invented data inputs outside simulation, R11
        cohorts formed on a biographical attribute, R13 no real column named in Solution / High
        Level Design, a single one beside unknown names, or a source column no table in scope has that
        no real column obviously replaces and one LLM check confirms is not computed by the use case
        (a failed check keeps the use case), R14 technique-specific structural
        prerequisites (process mining and sequence analysis need a table with a case id, a step and
        either many rows per case or two milestone times, unless the Generation Instructions ask for them).
        Flags (`gate_flags`): R5 temporal analysis of one reference table, R8 target listed among
        its own inputs, R9 assumed configuration parameter, R10 row-hungry technique on one
        reference table, R13 single real column. R6 is NEXT_ACTIONS only.
        """
        if not use_cases:
            return use_cases, []
        index = self._gate_schema_index(full_schema_details)
        cols_by = index["tables"]
        cat_map = {self._normalize_table_ref(k): str(v or "").upper()
                   for k, v in (getattr(self, "data_category_map", None) or {}).items()}
        business = {self._normalize_table_ref(t) for t in (getattr(self, "global_table_names", None) or ())}
        numeric_claim_re = NUMERIC_CLAIM_RE
        invented_input_re = re.compile(
            r"\b(simulated|assumed|synthetic|hypothetical|placeholder|made[-\s]?up|"
            r"fictitious|imaginary|invented|fabricated|mock)\s+([a-z][a-z_-]{2,30})\b")
        invented_nouns = {"capacity", "cost", "volume", "demand", "revenue", "price", "budget", "rate",
                          "ground", "truth", "label", "target", "score"}
        config_nouns = {"constraint", "threshold", "weight", "parameter", "baseline", "benchmark"}
        biographic = r"(?:`?\w*birth\w*`?|dob|date of birth|ages?\b|age_\w+)"
        biographic_anchor_res = (
            re.compile(r"\bcohorts?\s+(?:\w+\s+){0,2}?(?:by|on|based on|formed by|defined by|grouped by|using|from)\s+"
                       r"(?:\S+\s+){0,2}?" + biographic),
            re.compile(r"\b" + biographic + r"[^.]{0,20}\bcohorts?\b"),
        )
        event_anchor_re = re.compile(r"\b(?:signup|sign-up|sign_up|acquisition|acquired|first|onboard|created|creation|"
                                     r"registration|registered|join|enrol|start|activation|activated|install|"
                                     r"subscri|opened)")
        feature_cue_re = re.compile(r"\b(?:features?|inputs?|predictors?|using|based on|from|with)\b")
        subject_patterns = (
            r"\bper[\s-]+([a-z][a-z_-]{2,20})\b",
            r"\bper\s+each\s+([a-z][a-z_-]{2,20})\b",
            r"\btargeted\s+([a-z][a-z_-]{2,20})\b",
            r"\beach\s+([a-z][a-z_-]{2,20})\s+(incentive|targeting|scheduling|assignment|prioritization|routing|intervention)\b",
            r"\b([a-z][a-z_-]{2,20})\s+(incentive|targeting|scheduling|assignment|prioritization|routing|intervention)\s+(plan|strategy|recommendation|program)\b",
        )
        rule_ids = {"R5": "UC_DATA_FIT_WEAK", "R6": "UC_ACTION_SUBJECT_SUSPECT", "R7": "UC_BV_UNGROUNDED_NUMBER",
                    "R10": "UC_DATA_FIT_WEAK", "R13": "UC_SOLUTION_UNDER_GROUNDED", "R13_INVENTED": "UC_COLUMN_UNGROUNDED",
                    "R14": "UC_DATA_FIT_WEAK"}

        def _note(rule, severity, uc_no, evidence):
            try:
                NEXT_ACTIONS.add(rule_ids.get(rule, "UC_NOT_RELEVANT"), severity=severity, phase="Q3", step=rule,
                                 evidence=f"UC {uc_no}: {evidence}")
            except Exception:
                pass

        def _is_technical(fqn):
            category = cat_map.get(fqn)
            if category:
                return category == "TECHNICAL"
            if fqn in business:
                return False
            return bool(set(re.split(r"[^a-z0-9]+", fqn.rsplit(".", 1)[-1])) & self._TECHNICAL_TABLE_TOKENS)

        def _subject_has_id_column(subject, col_names):
            s = (subject or "").strip().lower()
            if not s:
                return True
            sn = s.rstrip("s")
            for c in col_names:
                if s in c or sn in c:
                    if _is_key_like_column(c) or c in (s, sn):
                        return True
            return False

        def _r13_grounding(uc, grounded, unknown):
            if grounded >= 2:
                return None
            if not grounded or unknown:
                return f"Q3_R13_SOLUTION_UNDER_GROUNDED:{grounded}"
            self._add_gate_flag(uc, "Q3_R13_THIN_GROUNDING")
            return None

        kept, dropped, deferred = [], [], []
        for uc in use_cases:
            uc_no = uc.get("No", "UNK")
            refs = self._uc_table_refs(uc)
            tabs = [t for t in refs if not t.lower().startswith("/volumes")]
            if not tabs:
                kept.append(uc)
                continue
            cols = {}
            for t in tabs:
                cols.update(cols_by.get(t, {}))
            sig = self._column_signals(cols)
            tech = str(uc.get("Analytics Technique") or "").strip()
            family = self._technique_family(tech)
            sol = str(uc.get("Solution") or "")
            hld = str(uc.get("High Level Design") or uc.get("high_level_design") or "")
            stmt = str(uc.get("Statement") or "")
            bv = str(uc.get("Business Value") or "")
            sol_low = sol.lower()
            reason = None
            clusters_text = family == "clustering" and bool(sig["text_cols"]) and (
                "text_topic" in self._technique_mentions(sol + "\n" + hld)
                or bool(self._grounded_column_mentions(sol + "\n" + hld, sig["text_cols"])))

            if all(_is_technical(t) for t in tabs):
                reason = "UC_NOT_RELEVANT:R1_TECHNICAL_ONLY"

            if reason is None:
                numeric_ok = sig["has_numeric"] or not sig["typed"]
                supported = {
                    "forecasting": sig["has_date"] and numeric_ok,
                    "trend": sig["has_date"] and numeric_ok,
                    "cohort": sig["has_date"],
                    "survival": sig["has_date"],
                    "funnel": bool(sig["stage_cols"]),
                    "anomaly": numeric_ok or sig["has_date"],
                    "regression": numeric_ok,
                    "clustering": numeric_ok or clusters_text,
                    "predictive": numeric_ok,
                    "causal_impact": sig["has_date"],
                    "spc": sig["has_date"] and numeric_ok,
                    "process_mining": sig["has_date"],
                    "sequence": sig["has_date"],
                    "lifetime_value": sig["has_date"] and numeric_ok,
                }.get(family, True)
                if not supported:
                    reason = f"UC_NOT_RELEVANT:R2_TECHNIQUE_DATA_MISMATCH:{tech}"

            if reason is None and len(tabs) >= 2 and not self._find_join_path(tabs)["connected"]:
                reason = "Q3_R4_JOIN_PATH_UNEXECUTABLE"

            if reason is None and family in self._TEMPORAL_FAMILIES and len(tabs) == 1 and cat_map.get(tabs[0]) == "REFERENCE":
                self._add_gate_flag(uc, "Q3_R5_REFERENCE_AS_FACT")
                _note("R5", "INFO", uc_no, f"{tech} on REFERENCE-only table {tabs[0]}")

            if reason is None:
                blob_lower = (stmt + " " + sol + " " + bv).lower()
                found_subject = None
                for pat in subject_patterns:
                    m = re.search(pat, blob_lower)
                    if m:
                        candidate = m.group(1).strip("-_").rstrip("s")
                        if candidate and len(candidate) >= 3:
                            found_subject = candidate
                            break
                if found_subject and not _subject_has_id_column(found_subject, set(cols)):
                    _note("R6", "INFO", uc_no, f"text suggests per-{found_subject} action; verify cited tables "
                                               f"expose a {found_subject}-identifying column")

            if reason is None:
                claims = len(numeric_claim_re.findall(bv.lower()))
                if claims and not re.search(r"[\[(]\s*ESTIMATE\s*:|DEPENDS ON", bv.upper()) and not self._grounded_column_mentions(bv, cols):
                    if claims >= 3:
                        reason = f"Q3_R7_BV_UNGROUNDED_QUANTITIES:{claims}"
                    else:
                        _note("R7", "INFO", uc_no, f"Business Value states {inspire_plural(claims, 'figure')} without a column "
                                                   f"or \"depends on\" note")

            if reason is None and family not in self._TEMPORAL_FAMILIES:
                m = re.search(r"\b(?:predict|predicting|classify|classifying|estimate|estimating)\s+`?([a-z_][a-z0-9_]*)`?", sol_low)
                if m and m.group(1) in cols:
                    target = m.group(1)
                    for sentence in re.split(r"[.;\n]", sol_low):
                        cue = feature_cue_re.search(sentence)
                        if cue and f"`{target}`" in sentence[cue.end():]:
                            self._add_gate_flag(uc, f"Q3_R8_TARGET_LEAKAGE:{target}")
                            _note("R8", "INFO", uc_no, f"predicts `{target}` while listing `{target}` as an input")
                            break

            if reason is None and family != "simulation":
                m = invented_input_re.search(sol_low)
                kind = inspire_use_case_kind(uc) if m and m.group(2) in invented_nouns else None
                settings = (self._assumed_inputs_named_settings(sol, invented_input_re, invented_nouns, cols)
                            if kind and kind["family"] in self._KIND_SETTING_ASSUMPTION_FAMILIES else [])
                if settings:
                    for name in settings:
                        self._add_gate_flag(uc, f"Q3_R9_ASSUMPTION_SETTING:{name}")
                    self.logger.info(f"[KIND-GATE FIRED] Q3 R9 keeps {uc_no} ({kind['id']}): each assumed input is a setting "
                                     f"the owner edits in the {IMPLEMENT_OUTPUT_LABELS['app']}: {', '.join(settings)}")
                elif m and m.group(2) in invented_nouns:
                    reason = f"Q3_R9_SIMULATED_INPUT:{m.group(1)}_{m.group(2)}"
                elif m and m.group(2) in config_nouns:
                    self._add_gate_flag(uc, f"Q3_R9_ASSUMED_PARAMETER:{m.group(2)}")

            if reason is None and family in self._MODEL_FAMILIES and len(tabs) == 1 and cat_map.get(tabs[0]) == "REFERENCE":
                self._add_gate_flag(uc, "Q3_R10_REFERENCE_SCALE")
                _note("R10", "INFO", uc_no, f"{tech} on REFERENCE-scale table {tabs[0]}")

            if reason is None and family == "cohort":
                for sentence in re.split(r"[.;\n]", sol_low):
                    if any(r.search(sentence) for r in biographic_anchor_res) and not event_anchor_re.search(sentence):
                        reason = "Q3_R11_COHORT_BIOGRAPHICAL_ANCHOR"
                        break

            r13_pending = None
            if reason is None and not any(t.lower().startswith("/volumes") for t in refs):
                invented = self._r13_repair_invented(uc, cols_by, tabs)
                unknown = self._invented_column_mentions(uc, cols_by)[1]
                sol, hld = str(uc.get("Solution") or ""), str(uc.get("High Level Design") or uc.get("high_level_design") or "")
                grounded = len(self._grounded_column_mentions(sol + "\n" + hld, cols))
                if invented and (grounded >= 2 or (grounded and not unknown)):
                    r13_pending = (invented, grounded, unknown, set(cols))
                else:
                    reason = _r13_grounding(uc, grounded, unknown)

            event_tables = None
            if reason is None and family in self._EVENT_LOG_FAMILIES:
                if self._user_asks_for_technique(family):
                    self.logger.info(f"[EVENT-LOG-FIT FIRED] Q3 R14 skipped for {uc_no}: the Generation Instructions ask for {tech}")
                else:
                    event_tables = self._process_log_tables(tabs, cols_by)

            if reason is None:
                n_cols = len(cols)
                r14 = None
                if family in self._SUPERVISED_FAMILIES and n_cols < 3:
                    r14 = f"R14_CLASSIFICATION_UNDER_FEATURED:{n_cols}_cols"
                elif family == "clustering" and not clusters_text and len(sig["numeric_cols"]) < 3 and n_cols < 3:
                    r14 = f"R14_CLUSTERING_UNDER_FEATURED:{n_cols}_cols"
                elif family == "association" and not sig["id_cols"]:
                    r14 = "R14_BASKET_NO_GROUPING_ID"
                elif family == "ranking" and n_cols < 2:
                    r14 = "R14_RANKING_NEEDS_DIM_AND_MEASURE"
                elif family == "correlation" and len(sig["numeric_cols"]) < 2 and n_cols < 2:
                    r14 = "R14_CORRELATION_UNDER_COLUMNED"
                elif family == "recommendation" and n_cols < 3:
                    r14 = "R14_RECO_UNDER_COLUMNED"
                elif family in self._TEXT_FAMILIES and not sig["text_cols"]:
                    r14 = "R14_TEXT_NO_TEXT_COLUMN"
                elif family == "network" and len(sig["id_cols"]) < 2:
                    r14 = "R14_NETWORK_NEEDS_TWO_IDS"
                elif family == "geospatial" and not sig["geo_cols"]:
                    r14 = "R14_GEO_NO_GEOGRAPHIC_COLUMN"
                elif event_tables is not None and not event_tables:
                    r14 = "R14_NO_EVENT_LOG"
                if r14:
                    reason = f"Q3_R14_DATA_FIT_SCALE:{r14}"

            if reason is None:
                reason = self._q3_deep_evidence_reason(uc, tabs, family, sol + "\n" + hld, cols, event_tables)
                self._ai_gate().register(reason)

            if reason is None:
                kept.append(uc)
                if r13_pending:
                    deferred.append((uc, r13_pending))
            else:
                dropped.append((uc, reason))
                rule = re.search(r"R\d+", reason)
                _note(rule.group(0) if rule else "R0", "HIGH", uc_no, reason)

        verdicts = self._r13_judge_invented([(uc, p[0], p[3]) for uc, p in deferred]) if deferred else {}
        for uc, (invented, grounded, unknown, _cols) in deferred:
            uc_no = uc.get("No", "UNK")
            judged = {n: verdicts.get((str(uc_no), n.lower())) for n in invented}
            confirmed = [n for n, v in judged.items() if v and v[0] == "invented_source_column"]
            derived = [n for n, v in judged.items() if v and v[0] == "derived"]
            if derived:
                self.logger.info(f"[R13-JUDGE-DERIVED FIRED] Q3 R13 keeps {uc_no}: the check reads "
                                 f"{', '.join(f'`{n}` ({judged[n][1]})' for n in derived[:10])} as computed by the use case")
            if confirmed:
                reason = (f"Q3_R13_SOLUTION_UNDER_GROUNDED:{grounded}" if grounded < 2
                          else f"Q3_R13_INVENTED_COLUMN:{','.join(confirmed[:3])}")
                self.logger.warning(f"[R13-INVENTED-COLUMN FIRED] Q3 R13 drops {uc_no}: it names "
                                    f"{inspire_plural(len(confirmed), 'source column')} no table in scope has and no real column "
                                    f"obviously matches: {', '.join(f'`{n}` ({judged[n][1]})' for n in confirmed[:10])}")
                _note("R13_INVENTED", "HIGH", uc_no, f"names source columns no table in scope has: {', '.join(confirmed[:10])}")
            else:
                reason = _r13_grounding(uc, grounded, unknown)
            if reason:
                kept = [k for k in kept if k is not uc]
                dropped.append((uc, reason))
                _note("R13", "HIGH", uc_no, reason)

        if dropped:
            self.logger.warning(f"Q3 RELEVANCE failed for {implement_number_text(len(dropped))} of {inspire_plural(len(use_cases), 'UC')}; the Q3 gate ledger "
                                f"says which stay below the bar and which are removed")
            for uc, reason in dropped[:10]:
                self.logger.info(f"  failed {uc.get('No','UNK')}: {reason}")
        else:
            self.logger.info(f"Q3 RELEVANCE: all {inspire_plural(len(use_cases), 'UC')} pass")
        return kept, dropped

    def _phaseQ4_detect_operational_patterns(self, full_schema_details: list) -> set:
        """Phase Q4 TIER-1 detector. Returns set of patterns the schema
        STRUCTURALLY supports. Industry-agnostic: type + structure only,
        no English keyword matching."""
        patterns = set()
        if not full_schema_details:
            return patterns
        # Aggregate columns per table
        by_table = {}
        for (c, s, t, col, dtype, _cmt) in self._iter_schema_rows(full_schema_details):
            by_table.setdefault(f"{c}.{s}.{t}", []).append({"name": col, "type": dtype.upper()})
        has_date_col_anywhere = False
        has_fact_like = False
        has_dim_like = False
        has_grouping_candidate = False
        has_status_like = False
        for fqn, cols in by_table.items():
            types = {c["type"] for c in cols}
            numeric_count = sum(1 for c in cols if c["type"].startswith(("INT", "BIGINT", "DOUBLE", "FLOAT", "DECIMAL", "SMALLINT", "LONG")))
            date_cols = [c for c in cols if c["type"].startswith(("DATE", "TIMESTAMP"))]
            if date_cols:
                has_date_col_anywhere = True
            # Fact-like: >= 3 numeric columns + some kind of date column
            if numeric_count >= 3 and date_cols:
                has_fact_like = True
            # Dim-like: small to moderate column count, has an id-like column (name ends with _id/_key/id/key)
            if any(c["name"].lower().endswith(("id", "_id", "key", "_key")) for c in cols) and len(cols) >= 3:
                has_dim_like = True
            # Grouping id candidate: a column that could group multiple rows (order_id / transaction_id / session_id pattern)
            if any(any(tok in c["name"].lower() for tok in ("order", "basket", "transaction", "session", "invoice", "visit")) for c in cols):
                has_grouping_candidate = True
            # Status-like: string column with limited cardinality (we can't probe cardinality here — use name heuristic as TIER-1 proxy)
            if any(c["type"].startswith("STRING") and any(tok in c["name"].lower() for tok in ("status", "state", "flag", "category", "type", "kind")) for c in cols):
                has_status_like = True
        if has_date_col_anywhere and has_fact_like:
            patterns.add("TREND_OR_PERIOD")
        if has_dim_like and has_fact_like:
            patterns.add("SUBJECT_360")
            patterns.add("MIX_OR_MARGIN")
        if has_fact_like and has_status_like and has_date_col_anywhere:
            patterns.add("SLA_OR_ANOMALY")
        if has_grouping_candidate:
            patterns.add("BASKET_OR_FUNNEL")
        self.logger.info(f"Q4 detect_operational_patterns: {sorted(patterns) or 'none (thin schema)'}")
        return patterns

    def _phaseQ5_decision_readiness(self, use_cases: list, full_schema_details: list) -> tuple:
        """Phase Q5 decision readiness (deterministic, no LLM). Returns (kept, dropped).

        R15 flags (`uc["decision_verb_flag"] = True`) names that open with an observational verb.
        T2 drops (`Q5_T2_RESTATES_COLUMN`) a use case whose decision filters a flag or status column
        that already holds the answer its name promises, unless it looks ahead.
        T3 drops (`Q5_T3_REBUILDS_OUTPUT`) a use case whose technique would build a value (bounds or a band, an anomaly
        flag, a similarity match, a recommendation, a cluster, a forecast or a prediction) that a column of its main table
        already holds, when its text never uses that column.
        T4 drops (`Q5_T4_*`) a decision use case with no named owner, no measurable outcome it moves, a one-off cadence, fewer things
        to act on per cycle than its layout needs, or one action for all of them. Informational kinds
        and use cases the instructions ask for skip T2 and T4.
        R18 flags (`Q5_R18_TECHNIQUE_LABEL_DRIFT`) a technique label named nowhere in the UC while
        the Solution / High Level Design names another family's specific method; general-purpose
        learners such as XGBoost serve many techniques and are not counted as contradictions.
        R19 drops a generic title only when the Solution / High Level Design names no technique at
        all; otherwise the UC keeps the `Q5_R19_GENERIC_TITLE` gate flag.
        R25 flags (`Q5_R25_NAME_STYLE:<codes>`) a `Name` that breaks the name rules, unless the user set
        a naming rule in the Generation Instructions.
        No score is read: score floors belong after combined scoring. The text-column requirement
        of text techniques is Q3 R14.
        """
        if not use_cases:
            return use_cases, []
        observational = {"map", "analyze", "analyse", "understand", "study", "examine", "investigate", "explore",
                         "measure", "observe", "track", "monitor", "describe", "assess"}
        # R19 generic-title rejection — catches "Increase Customer Value to Grow Revenue" pattern
        # Schema-agnostic: matches generic verb + generic object + preposition structure.
        generic_title_re = re.compile(
            r"^(?:Improve|Increase|Optimi[sz]e|Maximize|Boost|Grow|Drive)\s+"
            r"(?:the\s+)?"
            r"(?:Customer Value|Business Value|Customer Experience|Customer Satisfaction|"
            r"Customer Engagement|Customer Retention|Customer Loyalty|Customer Base|"
            r"Product Sales|Revenue|Profit|Sales|Growth|Performance|Efficiency|Productivity|"
            r"Operations|Margin|Retention|Loyalty|Conversion|Business Outcomes)"
            r"\s+(?:to|by|for|through|with|and)\s+",
            re.IGNORECASE
        )
        # Second check — if name has ANY specific analytical signal (method / phenomenon
        # / specific entity / specific metric), keep it. Signals are universal tokens
        # found in professional analytics language, not domain-specific vocabulary.
        specific_signals = (
            # Methods / techniques
            "clustering", "segment", "prediction", "predict", "forecast", "regression",
            "classification", "pareto", "cohort", "simulation", "monte carlo", "optimization",
            "optimizing", "attribution", "propensity", "anomaly", "ranking", "isolation",
            "kmeans", "k-means", "uplift", "correlation", "survival", "bayesian",
            # Phenomena / patterns
            "erosion", "leakage", "arbitrage", "fraud", "drift", "bottleneck", "volatility",
            "deviation", "spike", "surge", "lapsed", "dormant", "abandonment", "abuse",
            "misuse", "churn", "defection", "underpenetrated", "underserved", "stagnant",
            # Specific metrics / KPIs (composite forms only; single words too generic)
            "return rate", "conversion rate", "retention rate", "basket size", "cross-sell",
            "upsell", "attach rate", "markdown", "mix shift", "share of wallet",
            # Concrete entities / outputs
            "geographic", "pipeline", "territory", "route", "seasonality", "warehouse",
            "queue", "playbook", "action list", "reallocation", "escalation",
        )
        families = {key for key, _l, _a, _m in self._TECHNIQUE_FAMILIES}
        generic_learners = ("xgboost", "lightgbm", "catboost", "random forest", "gradient boost", "decision tree",
                            "neural network", "classifier", "lstm")
        kind_catalog = self._kind_catalog()
        asked_kinds, excluded_kinds = self._user_kind_directives(kind_catalog)
        schema_tables = self._gate_schema_index(full_schema_details)["tables"] if full_schema_details else {}
        kept, dropped, relabelled, retechniqued = [], [], [], []
        naming_rule = str((getattr(self, "parsed_generation_instructions", None) or {}).get("naming_rules") or "").strip()
        name_flags = {}
        verb_over = name_verb_share_flags([str(uc.get("Name") or uc.get("use_case") or "") for uc in use_cases])
        verb_over_ids = {id(uc) for pos, uc in enumerate(use_cases) if pos in verb_over}
        for uc in use_cases:
            name = str(uc.get("Name") or uc.get("use_case") or "").strip()
            tech = str(uc.get("Analytics Technique") or uc.get("analytics_technique") or "").strip()
            sol = str(uc.get("Solution") or uc.get("solution") or "")
            hld = str(uc.get("High Level Design") or uc.get("high_level_design") or "")
            stmt = str(uc.get("Statement") or uc.get("statement") or "")
            design = sol + "\n" + hld
            reason = None
            columns = {}
            for table in self._uc_table_refs(uc):
                columns.update(schema_tables.get(table, {}))
            kind_id, change = self._match_kind_to_technique(uc, kind_catalog, asked_kinds,
                                                            self._column_signals(columns) if columns else None)
            if change:
                (relabelled if change[0] == "relabel" else retechniqued).append(change[1])
            if kind_id in excluded_kinds:
                reason = f"Q5_KIND_EXCLUDED:{kind_id}"
            elif not uc.get("user_request") and not (kind_catalog.get(kind_id) or {}).get("informational"):
                reason = (self._q5_restated_column_miss(name, stmt, design)
                          or self._q5_rebuilt_output_miss(uc, schema_tables)
                          or self._q5_decision_test_miss(uc, name, stmt, design, kind_catalog.get(kind_id))) or None

            words = re.findall(r"[a-z]+", name.lower())
            if words and words[0] in observational:
                kind = inspire_use_case_kind(uc)
                if kind and kind["id"] in self._KIND_EXPLAINERS and self._explainer_names_owner_tolerance_action(uc):
                    self.logger.info(f"[KIND-GATE FIRED] Q5 R15 keeps {uc.get('No', 'UNK')} ({kind['id']}) unflagged: it names "
                                     "an owner, a tolerance and an action")
                else:
                    uc["decision_verb_flag"] = True

            if id(uc) in verb_over_ids and not naming_rule:
                self._add_gate_flag(uc, "Q5_R26_VERB_SHARE")
            name_issues = [] if naming_rule else self._use_case_name_issues(uc)
            if name_issues:
                self._add_gate_flag(uc, "Q5_R25_NAME_STYLE:" + ",".join(name_issues))
                for issue in name_issues:
                    name_flags[issue.split(":")[0]] = name_flags.get(issue.split(":")[0], 0) + 1

            family = self._technique_family(tech)
            named = {self._technique_label(f) for f in self._technique_mentions("\n".join((name, stmt, design)))}
            if family in families and self._technique_label(family) not in named:
                specific_design = design.lower()
                for learner in generic_learners:
                    specific_design = specific_design.replace(learner, " ")
                rivals = {f for f in self._technique_mentions(specific_design, methods_only=True)
                          if self._signature_family(f) != self._signature_family(family)}
                if rivals:
                    self._add_gate_flag(uc, f"Q5_R18_TECHNIQUE_LABEL_DRIFT:{family}")
                try:
                    NEXT_ACTIONS.add("UC_TECHNIQUE_UNEVIDENCED", severity="INFO", phase="Q5", step="R18",
                                     evidence=f"UC {uc.get('No','UNK')}: technique '{tech}' is named nowhere in its design"
                                              + (f"; design names {sorted(rivals)}" if rivals else ""))
                except Exception:
                    pass

            if reason is None and generic_title_re.match(name) and not any(s in name.lower() for s in specific_signals):
                if self._technique_mentions(design):
                    self._add_gate_flag(uc, "Q5_R19_GENERIC_TITLE")
                else:
                    reason = "Q5_R19_GENERIC_TITLE"

            if reason:
                dropped.append((uc, reason))
            else:
                kept.append(uc)
        if retechniqued:
            self.logger.info(f"[KIND-MATCH FIRED] {inspire_plural(len(retechniqued), 'use case')} kept the stated kind and took a "
                             f"technique that kind lists: {inspire_listing(retechniqued)}")
        if relabelled:
            self.logger.info(f"[KIND-MATCH FIRED] {inspire_plural(len(relabelled), 'use case')} relabelled to the kind of "
                             f"the technique each one uses: {inspire_listing(relabelled)}")
        if dropped:
            self.logger.warning(f"Q5 DECISION_READINESS failed for {implement_number_text(len(dropped))} of {inspire_plural(len(use_cases), 'UC')}; the Q5 gate "
                                f"ledger says which stay below the bar and which are removed")
            for uc, reason in dropped[:10]:
                self.logger.info(f"  failed {uc.get('No', uc.get('id','UNK'))}: {reason}")
        else:
            self.logger.info(f"Q5 DECISION_READINESS: all {inspire_plural(len(use_cases), 'UC')} passed")
        if naming_rule:
            self.logger.info(f"[NAME-CHECK FIRED] Q5 R25 skipped: the Generation Instructions set a naming rule ({naming_rule[:120]})")
        elif name_flags:
            flagged = sum(1 for uc in use_cases if any(str(f).startswith("Q5_R25_NAME_STYLE:") for f in (uc.get("gate_flags") or [])))
            self.logger.info(f"[NAME-CHECK FIRED] Q5 R25 flagged {implement_number_text(flagged)} of {inspire_plural(len(use_cases), 'name')}: "
                             + ", ".join(f"{code} {count}" for code, count in sorted(name_flags.items())))
        return kept, dropped

    @staticmethod
    def _kind_companion_gap(kind_id: str, signals) -> str:
        if not signals:
            return ""
        roles = signals.get("roles") or {}
        met = {"geo": bool(signals["geo_cols"] or roles.get("latitude")),
               "links": bool(roles.get("edge_pair")) or len(signals["id_cols"]) >= 2,
               "steps": bool(signals["stage_cols"]) and signals["has_date"],
               "dates": signals["has_date"],
               "levers": sum(1 for n in signals["numeric_cols"] if not _is_key_like_column(n)) >= inspire_scenario_measures_needed()}
        for suffix in inspire_kind_companions({"use_case_kind": kind_id}):
            need = INSPIRE_COMPANION_DATA_NEEDS.get(suffix)
            if need and not met[need]:
                return f"its {suffix} table needs {inspire_companion_data_text(need)}, which its tables do not hold"
        return ""

    @staticmethod
    def _relabel_kind(uc: dict, kind_id: str, stated: str):
        for field in ("Use Case Kind", "kind_family", "app_layout", "kind_label", "kind_family_label", *INSPIRE_KIND_LINE_FIELDS):
            uc.pop(field, None)
        uc["use_case_kind"] = kind_id
        uc["kind_relabelled_from"] = stated

    def _match_kind_to_technique(self, uc: dict, catalog: dict, asked=(), signals=None) -> tuple:
        kind_id = self._uc_stated_kind_id(uc, catalog)
        technique = uc.get("Analytics Technique") or uc.get("analytics_technique")
        family = self._technique_family(technique)
        named = f"{uc.get('No', 'UNK')} \"{self._uc_title(uc)}\""
        if not kind_id:
            stated = inspire_plain_text(uc.get("use_case_kind") or uc.get("Use Case Kind"))
            own_id = self._uc_kind_id(uc, catalog)
            if not stated or not own_id:
                return own_id, ()
            self._relabel_kind(uc, own_id, stated)
            return own_id, ("relabel", f"{named} {stated} -> {own_id} ({stated} is not a kind in the catalog; "
                                       f"{self._technique_label(family)} belongs to {own_id})")
        if not family or family == "catch_all" or uc.get("user_request"):
            return kind_id, ()
        listed = [str(t).strip() for t in catalog[kind_id].get("techniques") or [] if str(t or "").strip()]
        if family not in {self._technique_family(t) for t in listed}:
            text = "\n".join(str(uc.get(field) or "") for field in ("Name", "Statement", "Solution", "High Level Design"))
            mentioned = set(self._technique_mentions(text))
            replacement = next((t for t in listed if self._technique_family(t) in mentioned), "")
            if replacement:
                uc["technique_replaced_from"] = technique
                uc["Analytics Technique"] = replacement
                if "analytics_technique" in uc:
                    uc["analytics_technique"] = replacement
                if self._kind_companion_gap(kind_id, signals):
                    self._add_gate_flag(uc, f"Q5_D5_COMPANION_DATA:{kind_id}")
                return kind_id, ("technique", f"{named} {kind_id}: {technique} -> {replacement}")
            own_id = str((_inspire_kind_for_technique(technique) or {}).get("id") or "")
            if family in mentioned and kind_id not in asked and own_id in catalog and own_id != kind_id:
                self._relabel_kind(uc, own_id, kind_id)
                return own_id, ("relabel", f"{named} {kind_id} -> {own_id} (its design names "
                                           f"{self._technique_label(family)}, none of {', '.join(listed) or 'the techniques'} {kind_id} lists)")
            self._add_gate_flag(uc, f"Q5_D5_KIND_TECHNIQUE_MISMATCH:{kind_id}")
            return kind_id, ()
        gap = self._kind_companion_gap(kind_id, signals)
        if not gap:
            return kind_id, ()
        own_id = str((_inspire_kind_for_technique(technique) or {}).get("id") or "")
        if kind_id in asked or own_id not in catalog or own_id == kind_id or self._kind_companion_gap(own_id, signals):
            self._add_gate_flag(uc, f"Q5_D5_COMPANION_DATA:{kind_id}")
            return kind_id, ()
        self._relabel_kind(uc, own_id, kind_id)
        return own_id, ("relabel", f"{named} {kind_id} -> {own_id} ({gap})")

    _Q5_FLAG_FILTER_RE = re.compile(r"\b((?:is|has|was)_([a-z0-9_]+)|([a-z0-9_]+)_flag)\s*(?:=|==)\s*(?:1|true|'y'|'yes'|'true')\b"
                                    r"|\b(?:filter\w*|where|select\w*)\s+(?:on\s+|by\s+|for\s+)?((?:is|has|was)_([a-z0-9_]+))\b", re.I)
    _Q5_STATUS_FILTER_RE = re.compile(r"\b([a-z0-9_]*(?:status|state)[a-z0-9_]*)\s*(?:=|==|in\s*\(\s*)\s*'([a-z0-9 _-]+)'", re.I)
    _Q5_LOOK_AHEAD_RE = re.compile(r"\b(predict\w*|forecast\w*|will|likely|likelihood|risk\s+of|probabilit\w*|before|early|ahead|"
                                   r"next|propensity|expected|anticipat\w*|prevent\w*|at[- ]risk)\b", re.I)
    _Q5_GENERIC_OWNERS = {"", "n/a", "na", "none", "tbd", "unknown", "stakeholders", "business", "the business", "business users",
                          "users", "management", "everyone", "all", "teams", "various", "various teams", "multiple teams",
                          "leadership", "organization", "the organization", "company", "the company"}
    _Q5_ONE_OFF_RE = re.compile(r"\b(one[- ]time|one[- ]off|ad[- ]hoc|single\s+(?:analysis|study|report|snapshot))\b", re.I)
    _Q5_CADENCE_RE = re.compile(r"\b(hourly|daily|nightly|weekly|bi-?weekly|fortnightly|monthly|quarterly|yearly|annually|"
                                r"real[- ]time|continuous(?:ly)?|streaming|"
                                r"(?:each|every|per)\s+(?:hour|day|night|week|month|quarter|year|shift|morning|cycle|run|batch)|"
                                r"once\s+an?\s+(?:hour|day|week|month|quarter|year))\b", re.I)
    _Q5_TOP_N_RE = re.compile(r"\btop[- ](\d+)\b", re.I)
    _Q5_DIRECTION_RE = re.compile(r"\b(reduc\w*|increas\w*|lower\w*|rais\w*|cut\w*|recover\w*|prevent\w*|avoid\w*|improv\w*|grow\w*|"
                                  r"shorten\w*|sav(?:e|es|ed|ing|ings)|lift\w*|decreas\w*|boost\w*|minimi[sz]\w*|maximi[sz]\w*|"
                                  r"protect\w*|accelerat\w*|captur\w*|retain\w*|eliminat\w*|halv\w*|doubl\w*)\b", re.I)
    _Q5_MEASURE_RE = re.compile(r"\d|%|\b(rates?|ratios?|share|time|days?|hours?|minutes?|weeks?|costs?|revenue|margins?|spend|loss(?:es)?|"
                                r"counts?|number of|volumes?|yield|throughput|backlog|churn|conversion|retention|utili[sz]ation|"
                                r"accuracy|errors?|defects?|returns?|delays?|lead[- ]time|inventory|stock|sales|profit|prices?|"
                                r"demand|turnover|downtime|occupancy|attendance|response|satisfaction|scores?|units?|orders?|"
                                r"claims?|tickets?|visits?|write[- ]offs?|waste|spoilage|fines?|penalt\w+|leakage|arrears|"
                                r"overdue|stockouts?|no[- ]shows?|cancell?ations?|complaints?|incidents?|outages?|amount|dollars?)\b",
                                re.I)
    _Q5_PER_ITEM_RE = re.compile(r"\b(each|per|every|which|rank\w*|scor\w*|prioriti[sz]\w*|flag\w*|list\w*|queue\w*|segment\w*|"
                                 r"tier\w*|individual\w*|by\s+(?:customer|account|item|product|store|site|order|supplier|"
                                 r"employee|patient|asset|route|region|branch|claim|case))\b", re.I)

    def _q5_restated_column_miss(self, name: str, stmt: str, design: str) -> str:
        headline = f"{name}\n{stmt}"
        if self._Q5_LOOK_AHEAD_RE.search(headline):
            return ""
        promised = {w for w in re.findall(r"[a-z]+", headline.lower()) if len(w) >= 3}
        answers = []
        for match in self._Q5_FLAG_FILTER_RE.finditer(design):
            column = match.group(1) or match.group(4)
            meaning = match.group(2) or match.group(3) or match.group(5) or ""
            answers.append((column, meaning))
        for match in self._Q5_STATUS_FILTER_RE.finditer(design):
            answers.append((f"{match.group(1)} = '{match.group(2)}'", match.group(2)))
        for column, meaning in answers:
            words = {w for w in re.findall(r"[a-z]+", meaning.lower()) if len(w) >= 3}
            if words and words <= promised:
                return f"Q5_T2_RESTATES_COLUMN:{column}"
        return ""

    _Q5_EXISTING_OUTPUTS = _RegistryTable(lambda owner: _technique_output_rows(
        owner._TECHNIQUE_FAMILIES, (
            (frozenset({"bound", "band"}), False, True, ("Anomaly Detection", "Forecasting", "Statistical Process Control")),
            (frozenset({"anomaly", "anomalous", "outlier"}), False, False, ("Anomaly Detection", "Statistical Process Control")),
            (frozenset({"similar", "similarity", "nearest"}), False, False,
             ("Recommendation", "Entity Matching", "Clustering")),
            (frozenset({"recommended", "recommendation"}), False, False, ("Recommendation",)),
            (frozenset({"cluster"}), False, False, ("Clustering",)),
            (frozenset({"forecast", "forecasted"}), True, True, ("Forecasting",)),
            (frozenset({"pred", "prediction", "predicted", "prob", "probability", "propensity", "likelihood"}), True, True,
             ("Forecasting", "Classification", "Predictive Modeling", "Regression Analysis", "Survival Analysis",
              "Uplift Modeling", "Lifetime Value")),
        )
    ))
    _Q5_OUTPUT_SUBJECT_NOISE = frozenset({"value", "score", "rate", "level", "flag", "next", "model", "estimated", "expected"})

    def _q5_rebuilt_output_miss(self, uc: dict, schema_tables: dict) -> str:
        primary = self._normalize_table_ref(uc.get("Primary Table") or "")
        if primary not in (schema_tables or {}):
            refs = self._uc_table_refs(uc)
            primary = refs[0] if refs else ""
        columns = (schema_tables or {}).get(primary) or {}
        family = self._technique_family(uc.get("Analytics Technique") or uc.get("analytics_technique"))
        if not columns or not family:
            return ""
        text = "\n".join(str(uc.get(field) or "") for field in ("Name", "Statement", "Solution", "High Level Design")).lower()
        headline = {w for w in re.findall(r"[a-z]+", "\n".join((str(uc.get("Name") or ""), str(uc.get("Statement") or ""))).lower())
                    if len(w) >= 4}
        found = []
        for tokens, needs_subject, numeric_only, families in self._Q5_EXISTING_OUTPUTS:
            if family not in families:
                continue
            for column, dtype in columns.items():
                toks = set(self._role_tokens(column))
                toks |= {tok[:-1] for tok in toks if len(tok) > 3 and tok.endswith("s")}
                if column in found or not toks & tokens:
                    continue
                if numeric_only and dtype and _metadata_type_family(dtype) != "numeric":
                    continue
                if needs_subject:
                    own = {tok for tok in toks - tokens - self._Q5_OUTPUT_SUBJECT_NOISE if len(tok) >= 4}
                    if not any(a.startswith(b) or b.startswith(a) for a in own for b in headline):
                        continue
                found.append(column)
        if not found or any(re.search(rf"(?<![a-z0-9_]){re.escape(column)}(?![a-z0-9_])", text) for column in found):
            return ""
        return "Q5_T3_REBUILDS_OUTPUT:" + ", ".join(found)

    def _kind_min_items(self, kind) -> int:
        floor = int(TECHNICAL_CONTEXT["runtime"]["decision_min_items_per_cycle"])
        if not isinstance(kind, dict):
            return floor
        layouts = {str(layout.get("id")): layout for layout in (_inspire_kinds() or {}).get("layouts") or [] if isinstance(layout, dict)}
        counts = [n for n in ((layouts.get(str(kind.get("decision_layout") or kind.get("layout") or "")) or {}).get("min_items")
                              or {}).values() if isinstance(n, int) and n > 0]
        return max(counts) if counts else floor

    def _q5_decision_test_miss(self, uc: dict, name: str, stmt: str, design: str, kind) -> str:
        elite = uc.get("elite_assessment") if isinstance(uc.get("elite_assessment"), dict) else {}
        owners = [elite.get("decision_owner"), uc.get("Beneficiary") or uc.get("beneficiary"), uc.get("Sponsor") or uc.get("sponsor")]
        if not any(" ".join(str(o or "").split()).casefold() not in self._Q5_GENERIC_OWNERS for o in owners):
            return "Q5_T4_NO_OWNER"
        outcome = "\n".join((name, stmt, str(uc.get("Business Value") or "")))
        if not (self._Q5_DIRECTION_RE.search(outcome) and self._Q5_MEASURE_RE.search(outcome)):
            return "Q5_T4_NO_MEASURABLE_OUTCOME"
        text = "\n".join((name, stmt, design, str(uc.get("Business Value") or ""), str(elite.get("cadence") or "")))
        if self._Q5_ONE_OFF_RE.search(text) and not self._Q5_CADENCE_RE.search(text):
            return "Q5_T4_ONE_OFF"
        minimum = self._kind_min_items(kind)
        tops = [int(n) for n in self._Q5_TOP_N_RE.findall(text)]
        if tops and max(tops) < minimum:
            return f"Q5_T4_TOO_FEW_ITEMS:{max(tops)}<{minimum}"
        if not self._Q5_PER_ITEM_RE.search(text):
            return "Q5_T4_NO_PER_ITEM_ACTION"
        return ""

    def _phaseQ4_validate_recall(self, use_cases: list, detected_patterns: set) -> list:
        """Phase Q4 coverage probe. For every detected pattern not covered by
        any UC, emit UC_RECALL_GAP HIGH. Does not drop UCs."""
        if not use_cases or not detected_patterns:
            return use_cases
        pattern_keywords = {
            "TREND_OR_PERIOD":  ["trend", "period", "month-over", "year-over", "forecast", "seasonal"],
            "SUBJECT_360":      ["360", "profile", "customer segment", "lifetime", "subject"],
            "SLA_OR_ANOMALY":   ["anomal", "sla", "outlier", "breach", "detect"],
            "MIX_OR_MARGIN":    ["mix", "margin", "pareto", "portfolio"],
            "BASKET_OR_FUNNEL": ["basket", "funnel", "bundle", "association", "cohort"],
        }
        covered = set()
        for uc in use_cases:
            blob = " ".join((uc.get(f, "") or "").lower() for f in ("Use Case", "Name", "Statement", "Solution", "Analytics Technique"))
            for p, keys in pattern_keywords.items():
                if any(k in blob for k in keys):
                    covered.add(p)
        missing = detected_patterns - covered
        for p in sorted(missing):
            self.logger.warning(f"Q4 UC_RECALL_GAP: pattern {p} supported by schema but not covered by any UC")
            try:
                NEXT_ACTIONS.add("UC_RECALL_GAP", severity="HIGH",
                                 phase="Q4", step="pattern_coverage",
                                 evidence=f"Pattern {p} supported by schema structure but no UC covers it",
                                 suggested_user_action="Add a UC that exploits this pattern OR declare it out-of-scope via widget 13.")
            except Exception:
                pass
        if not missing:
            self.logger.info(f"Q4 RECALL: all {inspire_plural(len(detected_patterns), 'detected pattern')} covered by at least one UC")
        return use_cases

    def _phaseQ_run_integrity_gates(self, use_cases: list, full_schema_details: list) -> list:
        """Run Q1..Q5 against the consolidated portfolio and return the survivors. Every gate's
        in/out/drop reasons go to processing_honesty["gate_ledger"]. A gate that raises is logged
        with a short traceback and the UCs it should have checked are kept but marked
        `uc["gate_unverified"]`."""
        if not use_cases:
            return use_cases
        kept = use_cases
        q1_dropped, q2_merged, q3_dropped, q5_dropped = [], [], [], []
        n_in = len(kept)
        try:
            kept, q1_dropped = self._phaseQ1_validate_grounding(kept, full_schema_details)
            self._record_gate_ledger("Q1", n_in, len(kept), q1_dropped)
        except Exception as _q1_err:
            self._record_gate_exception("Q1", _q1_err, kept)
        n_in = len(kept)
        try:
            kept, q2_merged = self._phaseQ2_canonical_dedup(kept)
            self._record_gate_ledger("Q2", n_in, len(kept), q2_merged)
        except Exception as _q2_err:
            self._record_gate_exception("Q2", _q2_err, kept)
        n_in = len(kept)
        q3_below, q5_below = [], []
        try:
            before = kept
            kept, q3_dropped = self._phaseQ3_validate_relevance(kept, full_schema_details)
            kept, q3_dropped, q3_below = self._keep_below_bar("Q3", before, kept, q3_dropped)
            self._record_gate_ledger("Q3", n_in, len(kept), q3_dropped, flagged=sum(
                1 for uc in kept if any(str(f).startswith("Q3_") for f in (uc.get("gate_flags") or []))), below_bar=q3_below)
        except Exception as _q3_err:
            self._record_gate_exception("Q3", _q3_err, kept)
        try:
            _patterns = self._phaseQ4_detect_operational_patterns(full_schema_details)
            kept = self._phaseQ4_validate_recall(kept, _patterns)
        except Exception as _q4_err:
            self._record_gate_exception("Q4", _q4_err, kept, mark=False)
        n_in = len(kept)
        try:
            before = kept
            kept, q5_dropped = self._phaseQ5_decision_readiness(kept, full_schema_details)
            kept, q5_dropped, q5_below = self._keep_below_bar("Q5", before, kept, q5_dropped)
            self._record_gate_ledger("Q5", n_in, len(kept), q5_dropped, flagged=sum(
                1 for uc in kept if uc.get("decision_verb_flag")
                or any(str(f).startswith("Q5_") for f in (uc.get("gate_flags") or []))), below_bar=q5_below)
        except Exception as _q5_err:
            self._record_gate_exception("Q5", _q5_err, kept)
        try:
            kept = self._canonicalize_sponsor_beneficiary_roles(kept)
        except Exception as _q6_err:
            self._record_gate_exception("SPONSOR_CANONICAL", _q6_err, kept, mark=False)
        honesty = self._honesty()
        honesty["q1_grounding_dropped"] = len(q1_dropped)
        honesty["q2_dedup_dropped"] = len(q2_merged)
        honesty["q3_relevance_dropped"] = len(q3_dropped)
        honesty["q3_below_bar"] = len(q3_below)
        honesty["q5_decision_dropped"] = len(q5_dropped)
        honesty["q5_below_bar"] = len(q5_below)
        q5_reasons = {}
        for _uc, reason in q5_dropped:
            k = self._gate_reason_key(reason)
            q5_reasons[k] = q5_reasons.get(k, 0) + 1
        honesty["q5_drop_reasons"] = q5_reasons
        honesty["q5_decision_verb_flagged"] = sum(1 for uc in kept if uc.get("decision_verb_flag"))
        return kept

    def _canonicalize_sponsor_beneficiary_roles(self, use_cases: list) -> list:
        """LLM-driven canonicalization of Sponsor and Beneficiary field values.
        Root cause: LLM-generated UCs use inconsistent role labels ('CFO' vs
        'Chief Financial Officer'). Industry-agnostic prompt (no corpus tokens).
        Cached per-run by normalized input. Sentinel: [SPONSOR_CANONICAL FIRED].
        """
        if not use_cases:
            return use_cases
        if not hasattr(self, "_sponsor_role_cache"):
            self._sponsor_role_cache = {}
        def _norm(s):
            return (s or "").strip().lower()
        unique_raw = set()
        for uc in use_cases:
            for field in ("Sponsor", "Beneficiary"):
                v = uc.get(field, "")
                if v and _norm(v):
                    unique_raw.add(str(v).strip())
        to_canonicalize = sorted(r for r in unique_raw if _norm(r) not in self._sponsor_role_cache)
        if to_canonicalize:
            try:
                role_list_str = "\n".join(f"- {r}" for r in to_canonicalize)
                prompt = (
                    "You are a role-name normalizer for a business analytics catalog.\n"
                    "For each input role name below, output its canonical form.\n\n"
                    "RULES (industry-agnostic — must work equally across any business\n"
                    "domain without injecting sector-specific words the input didn't contain):\n"
                    "1. Expand common C-suite abbreviations to their full title:\n"
                    "   CFO -> Chief Financial Officer, CIO -> Chief Information Officer,\n"
                    "   CTO -> Chief Technology Officer, COO -> Chief Operating Officer,\n"
                    "   CMO -> Chief Marketing Officer, CEO -> Chief Executive Officer,\n"
                    "   CDO -> Chief Data Officer, CISO -> Chief Information Security Officer,\n"
                    "   CHRO -> Chief Human Resources Officer, CPO -> Chief Product Officer,\n"
                    "   CRO -> Chief Revenue Officer, CCO -> Chief Customer Officer,\n"
                    "   CSO -> Chief Strategy Officer.\n"
                    "2. Normalize functional-head variants to the single form 'Head of X'\n"
                    "   (so 'VP of Operations', 'Director of Operations', 'Operations Lead'\n"
                    "   all become 'Head of Operations'). Preserve the 'X' verbatim.\n"
                    "3. Never rename in a way that changes meaning (Chief Financial Officer\n"
                    "   is NOT the same as Financial Controller; keep both distinct).\n"
                    "4. If the input is not a recognizable business role (e.g. a person name,\n"
                    "   department name, or free-form description), return it VERBATIM.\n"
                    "5. Do NOT inject industry-specific words the input didn't contain.\n\n"
                    "OUTPUT FORMAT (STRICT JSON):\n"
                    "{\"roles\": [{\"input\": \"<verbatim input>\", \"canonical\": \"<canonical form>\"}]}\n\n"
                    f"INPUT ROLES:\n{role_list_str}"
                )
                schema = {
                    "name": "role_canonicalization",
                    "schema": {
                        "type": "object",
                        "properties": {
                            "roles": {
                                "type": "array",
                                "items": {
                                    "type": "object",
                                    "properties": {
                                        "input": {"type": "string"},
                                        "canonical": {"type": "string"}
                                    },
                                    "required": ["input", "canonical"]
                                }
                            }
                        },
                        "required": ["roles"]
                    }
                }
                resp = self.ai_agent._call_ai_query(
                    prompt=prompt,
                    prompt_name="canonicalize_sponsor_beneficiary_roles",
                    response_schema=schema,
                    display_name="Sponsor_Beneficiary_Canonicalizer"
                )
                cleaned = clean_json_response(resp, want=dict) if resp else ""
                parsed = json.loads(cleaned) if cleaned else {"roles": []}
                for entry in parsed.get("roles", []):
                    _in = entry.get("input", "")
                    _can = entry.get("canonical", "")
                    if _in and _can:
                        self._sponsor_role_cache[_norm(_in)] = str(_can).strip()
                for r in to_canonicalize:
                    self._sponsor_role_cache.setdefault(_norm(r), r)
                self.logger.info(f"[SPONSOR_CANONICAL FIRED] canonicalized_new={len(to_canonicalize)} cache_size={len(self._sponsor_role_cache)}")
            except Exception as _e:
                self.logger.warning(f"Sponsor/Beneficiary canonicalizer LLM step failed non-fatally: {redact_error(_e)}")
                for r in to_canonicalize:
                    self._sponsor_role_cache.setdefault(_norm(r), r)
        updates = 0
        for uc in use_cases:
            for field in ("Sponsor", "Beneficiary"):
                v = uc.get(field, "")
                k = _norm(v)
                if k and k in self._sponsor_role_cache:
                    canon = self._sponsor_role_cache[k]
                    if canon and canon != v:
                        uc[field] = canon
                        updates += 1
        if updates > 0:
            self.logger.info(f"[SPONSOR_CANONICAL FIRED] applied field_updates={updates} unique_roles={len(unique_raw)}")
        return use_cases

    @staticmethod
    def _min_subdomains(domain_use_cases: int) -> int:
        return 1 if domain_use_cases <= 4 else 2

    def _phaseL_final_gate(self, use_cases: list, full_schema_details: list) -> dict:
        """Phase L final gate: 19 advisory binary checks emitted as NEXT_ACTIONS entries. Never
        filters the portfolio. Returns {check_id: {"pass": bool, "severity": str}} and stores the
        same dict on `self.phase_l_results`."""
        results = {}
        def _check(cid: str, passed: bool, severity: str, evidence: str, suggested: str = ""):
            results[cid] = {"pass": bool(passed), "severity": severity}
            if not passed:
                try:
                    NEXT_ACTIONS.add(
                        rule_id=f"L_{cid}", severity=severity, phase="L", step="FinalGate",
                        evidence=evidence[:300], suggested_user_action=suggested[:300] or None,
                    )
                except Exception:
                    pass
        uc_list = use_cases or []
        n = len(uc_list)
        honesty = self._honesty()
        schema_rows = list(self._iter_schema_rows(full_schema_details))
        index = self._gate_schema_index(full_schema_details) if schema_rows else {"tables": {}}
        # L1 first-run-pass: if no UCs, BLOCK
        _check("L1_any_ucs_produced", n > 0, "BLOCKING",
               f"Pipeline produced {inspire_plural(n, 'use case')}", "Re-run with broader schema or lower filters.")
        # L2 domain diversity
        _doms = {str(uc.get("Business Domain") or "").strip() for uc in uc_list if uc.get("Business Domain")}
        _check("L2_domain_diversity", len(_doms) >= 2 or n <= 3, "INFO",
               f"{inspire_plural(len(_doms), 'distinct domain')}", "Expand schema coverage to unlock more domains.")
        # L3 subdomain diversity
        _subs = {str(uc.get("Subdomain") or "").strip() for uc in uc_list if uc.get("Subdomain")}
        _domain_subs = defaultdict(set)
        _domain_sizes = Counter()
        for uc in uc_list:
            _dom = str(uc.get("Business Domain") or "").strip()
            _domain_sizes[_dom] += 1
            if str(uc.get("Subdomain") or "").strip():
                _domain_subs[_dom].add(str(uc.get("Subdomain")).strip())
        _thin = sorted(dom or "(no domain)" for dom, size in _domain_sizes.items() if len(_domain_subs[dom]) < self._min_subdomains(size))
        _check("L3_subdomain_diversity", not _thin, "INFO",
               f"{inspire_plural(len(_subs), 'distinct subdomain')}; domains under the subdomain minimum: {_thin or 'none'}",
               "Encourage subdomain rename in prompt.")
        # L4 priority distribution non-degenerate (not all "Medium")
        _prios = [str(uc.get("Priority") or "").strip() for uc in uc_list]
        _check("L4_priority_nondegenerate", len(set(_prios)) >= 2 or n <= 2, "INFO",
               f"Priority values: {sorted(set(_prios))}", "Loosen priority heuristic in prompt.")
        # L5 every UC has primary table
        _missing_pt = [uc for uc in uc_list if str(uc.get("Primary Table") or "").strip().upper() in ("", "N/A")]
        _check("L5_every_uc_has_primary_table", not _missing_pt, "BLOCKING",
               f"{implement_number_text(len(_missing_pt))}/{inspire_plural(n, 'UC')} missing Primary Table", "Reject UCs without Primary Table at parse time.")
        # L6 every UC has statement
        _missing_st = [uc for uc in uc_list if len(str(uc.get("Statement") or "").strip()) < 20]
        _check("L6_every_uc_has_statement", not _missing_st, "HIGH",
               f"UCs with an empty/short Statement: {implement_number_text(len(_missing_st))}/{implement_number_text(n)}", "Raise statement min-length in parser.")
        # L7 every UC has solution
        _missing_sol = [uc for uc in uc_list if len(str(uc.get("Solution") or "").strip()) < 20]
        _check("L7_every_uc_has_solution", not _missing_sol, "HIGH",
               f"UCs with an empty/short Solution: {implement_number_text(len(_missing_sol))}/{implement_number_text(n)}", "Raise solution min-length in parser.")
        # L8 every UC has technique
        _missing_tech = [uc for uc in uc_list if not str(uc.get("Analytics Technique") or "").strip()]
        _check("L8_every_uc_has_technique", not _missing_tech, "HIGH",
               f"{implement_number_text(len(_missing_tech))}/{inspire_plural(n, 'UC')} missing technique", "Enforce technique whitelist in parser.")
        _sigs = [self._uc_dedup_signature(uc) for uc in uc_list]
        _dup = len(_sigs) - len(set(_sigs))
        _check("L9_no_duplicate_names", _dup == 0, "HIGH",
               f"{inspire_plural(_dup, 'UC duplicates', 'UCs duplicate')} another UC's decision signature (verb, object, tables, technique)",
               "Tighten Q2 canonical dedup or rename one of the colliding UCs.")
        # L10 Q1 grounding did not drop >50%
        q1d = honesty.get("q1_grounding_dropped", 0)
        _check("L10_q1_drop_under_50pct", (q1d * 2) < max(1, n + q1d), "HIGH",
               f"Q1 dropped {implement_number_text(q1d)} vs kept {implement_number_text(n)}", "Inspect prompt for fabricated tables/columns.")
        # L11 Q2 merged reasonable
        q2m = honesty.get("q2_dedup_dropped", 0)
        _check("L11_q2_merge_under_50pct", (q2m * 2) < max(1, n + q2m), "INFO",
               f"Q2 merged {implement_number_text(q2m)} vs kept {implement_number_text(n)}", "Diversify generation seeds.")
        # L12 Q3 relevance drop under 50%
        q3d = honesty.get("q3_relevance_dropped", 0)
        _check("L12_q3_drop_under_50pct", (q3d * 2) < max(1, n + q3d), "HIGH",
               f"Q3 dropped {implement_number_text(q3d)} vs kept {implement_number_text(n)}", "Review the Q3 drop reasons in the gate ledger.")
        # L13 schema detail non-empty
        _check("L13_schema_details_present", bool(full_schema_details), "BLOCKING",
               f"full_schema_details has {inspire_plural(len(full_schema_details or []), 'row')}",
               "Check catalog permissions / table selection.")
        # L14 no UC references unknown table (schema rows are tuples: catalog, schema, table, col, type, desc)
        _table_names = {t.lower() for (_c, _s, t, _col, _dt, _cm) in schema_rows}
        _unknown = []
        for uc in uc_list:
            pt = str(uc.get("Primary Table") or "").strip().lower()
            if pt and pt.split(".")[-1] not in _table_names:
                _unknown.append(pt)
        _check("L14_all_primary_tables_grounded", not _unknown, "BLOCKING",
               f"{inspire_plural(len(_unknown), 'UC references', 'UCs reference')} unknown tables: {list(set(_unknown))[:5]}",
               "Strengthen Q1 grounding.")
        # L15 business_domain != placeholder
        _placeholders = {"", "other", "unknown", "general", "misc", "miscellaneous", "uncategorized", "unassigned"}
        _ph = [uc for uc in uc_list
               if str(uc.get("Business Domain") or "").strip().lower() in _placeholders
               or re.match(r"^domain\d+$", str(uc.get("Business Domain") or "").strip().lower())]
        _check("L15_no_placeholder_domains", not _ph, "HIGH",
               f"UCs with a placeholder domain: {implement_number_text(len(_ph))}/{implement_number_text(n)}",
               "Domain detection fell back; rerun or set the Business Domains widget.")
        q5d = honesty.get("q5_decision_dropped", 0)
        _check("L16_q5_drop_under_50pct", (q5d * 2) < max(1, n + q5d), "HIGH",
               f"Q5 dropped {implement_number_text(q5d)} vs kept {implement_number_text(n)}", "Review the Q5 R18/R19 drop reasons in the gate ledger.")
        # L17 NEXT_ACTIONS has no unexpected BLOCKING beyond L-gates themselves
        try:
            all_blocking = [a for a in NEXT_ACTIONS.snapshot() if a.get("severity") == "BLOCKING"]
            non_L = [a for a in all_blocking if not (a.get("rule_id","") or "").startswith("L_")]
        except Exception:
            non_L = []
        _check("L17_zero_non_L_blocking", not non_L, "INFO",
               f"{inspire_plural(len(non_L), 'BLOCKING entry', 'BLOCKING entries')} outside L-gates",
               "Resolve the BLOCKING NEXT_ACTIONS entries reported in the run log.")
        # L18 multi-table ratio: at least 30% of UCs should span 2+ tables when schema has 2+ tables.
        try:
            _schema_tables = set(_table_names)
            _multi = 0
            for _uc in uc_list:
                _ti = str(_uc.get("Tables Involved", "") or "")
                _n = len([t for t in _ti.split(",") if t.strip()])
                if _n >= 2:
                    _multi += 1
            _ratio = (_multi / n) if n else 0.0
            _passed = (len(_schema_tables) < 2) or (_ratio >= 0.30)
            _check("L18_multi_table_ratio", _passed, "HIGH",
                   f"multi_table_UCs={_multi}/{n} (ratio={_ratio:.2f}); schema_tables={len(_schema_tables)}",
                   "Strengthen prompt FK-exploitation / STRUCTURAL JOIN HEURISTIC language; consider Q6 rebalance pass.")
        except Exception as _mt_err:
            _check("L18_multi_table_ratio", True, "INFO",
                   f"multi-table check skipped: {redact_error(_mt_err)}", "")
        # L19 production_readiness: aggregate Genie-runnable UC check.
        # J1 — Solution has >=2 column citations
        # J2 — Primary Table in known schema (covered by L14)
        # J3 — All backticked cols resolve to known schema cols (not SQL keywords)
        # J4 — Analytics Technique is specific (not umbrella — Rule 12 whitelist)
        # J5 — Result artifact named (result_table OR Solution names output)
        # J7 — Inspire Score set and >0
        # J8 — Beneficiary non-empty and not generic
        import re as _rL
        _generic_bene = {"", "none", "n/a", "team", "everyone", "all", "business"}
        _prod_ready = 0
        _prod_fails = []
        for _uc in uc_list:
            _fails = []
            _sol = str(_uc.get("Solution","") or "")
            _hld = str(_uc.get("High Level Design","") or "")
            _stmt = str(_uc.get("Statement","") or "")
            _bv = str(_uc.get("Business Value","") or "")
            _blob = _sol + " " + _stmt + " " + _bv
            # J1
            _cited_cols = set()
            for _t in self._uc_table_refs(_uc):
                _cited_cols |= set(index["tables"].get(_t, {}))
            if len(self._grounded_column_mentions(_sol + "\n" + _hld, _cited_cols)) < 2:
                _fails.append("J1_solution_<2_cols")
            # J3
            _ungrounded = sum(map(len, self._invented_column_mentions(_uc, index["tables"], ("Solution", "Statement", "Business Value"))))
            if _ungrounded:
                # allow a few — just a smell, not a hard fail. threshold: >=3 ungrounded.
                if _ungrounded >= 3:
                    _fails.append(f"J3_ungrounded_cols:{_ungrounded}")
            # J4
            _tech = " ".join(str(_uc.get("Analytics Technique","") or "").lower().split())
            if _tech in self._GATE_CATCHALL_TECHNIQUES:
                _fails.append("J4_umbrella_technique")
            # J5
            _rt = str(_uc.get("result_table","") or "").strip()
            if not _rt and not _rL.search(r"\b(output|result|target|saves?|writes?|materializes?|persists?)\b", _sol.lower()):
                _fails.append("J5_no_output_named")
            # J6
            if _rL.search(r"\[(MISSING_DATA|PLACEHOLDER|TODO)\s*:", _blob):
                _fails.append("J6_placeholder_tag")
            # J7
            try:
                _is = float(_uc.get("Inspire Score", _uc.get("Priority", 0)) or 0)
            except Exception:
                _is = 0.0
            if _is <= 0:
                _fails.append("J7_no_score")
            # J8
            _bene = str(_uc.get("Beneficiary","") or "").strip().lower()
            if _bene in _generic_bene or len(_bene) < 3:
                _fails.append("J8_generic_beneficiary")
            if not _fails:
                _prod_ready += 1
            else:
                _prod_fails.append((_uc.get("No","?"), _fails))
        _ready_ratio = (_prod_ready / n) if n else 0
        _check("L19_production_readiness", _ready_ratio >= 0.80, "HIGH",
               f"production-ready {implement_number_text(_prod_ready)}/{implement_number_text(n)} ({int(_ready_ratio*100)}%); failing checks per-UC sample: {dict(_prod_fails[:5])}",
               "Review UC_PRODUCTION_READINESS NEXT_ACTIONS entries; tighten prompt/Q3 rules.")
        # emit per-UC summary as INFO (first 20)
        for _uc_no, _fails in _prod_fails[:20]:
            try:
                NEXT_ACTIONS.add("UC_PRODUCTION_READINESS", severity="INFO", phase="L", step="J-checks",
                                 evidence=f"UC {_uc_no}: failed production checks {_fails}")
            except Exception:
                pass
        honesty["phase_L_results"] = {k: v["pass"] for k, v in results.items()}
        honesty["phase_L_fail_count"] = sum(1 for v in results.values() if not v["pass"])
        honesty["phase_L_production_ready_count"] = _prod_ready
        honesty["phase_L_production_ready_ratio"] = round(_ready_ratio, 3)
        self.phase_l_results = results
        return results

    def _rename_placeholder_domains_from_subdomains(self, use_cases: list) -> list:
        """When domain detection fell back to placeholder DomainN names, use the detected subdomains
        to ask the LLM for a single-word umbrella name per placeholder. Honors the
        DOMAIN_FINDER_PROMPT one-word rule and the user's generation instructions, and never renames
        a user-specified domain. Fail-safe: retains the placeholder if the LLM fails or returns an
        invalid name."""
        import re as _re
        if not use_cases:
            return use_cases
        if not discover_step_on("PlaceholderDomainRename"):
            self.logger.info("[FLAGS] PlaceholderDomainRename is off in discover_domain_steps: placeholder domain names are kept")
            return use_cases
        protected = self._protected_domains()
        placeholder_re = _re.compile(r"^Domain\d+$")
        groups = {}
        for uc in use_cases:
            d = (uc.get("Business Domain") or "").strip()
            if placeholder_re.match(d) and d.lower() not in protected:
                groups.setdefault(d, set()).add((uc.get("Subdomain") or "").strip())
        if not groups:
            return use_cases
        self.logger.warning(f"🔁 Placeholder domain rename: found {inspire_plural(len(groups), 'placeholder domain')} after subdomain detection; attempting rename from subdomains")
        banned = {"operations","engagement","management","services","activities","processes","functions","solutions","systems","general"}
        valid_re = _re.compile(r"^[A-Z][a-z]+$")
        industries_str = ", ".join(self.industries) if hasattr(self, "industries") and self.industries else "UNKNOWN_INDUSTRY"
        instructions = self._get_generation_instruction_for_prompt("DOMAIN_FINDER_PROMPT")
        rename_map = {}
        for placeholder, subs in groups.items():
            subs = sorted(s for s in subs if s)
            if not subs:
                continue
            subdomain_list = "\n".join(f"- {s}" for s in subs[:30])
            prompt = (
                "You are naming ONE business domain based on the subdomains assigned to it.\n\n"
                "HARD RULES (any violation is rejected):\n"
                "- EXACTLY ONE WORD. No spaces. No CamelCase. Only the first letter capitalized.\n"
                "- The word must be a concrete business noun (e.g., Revenue, Customers, Risk, Inventory, Suppliers, Franchise, Procurement, Pricing, Fraud, Maintenance, Logistics).\n"
                "- BANNED generic words: Operations, Engagement, Management, Services, Activities, Processes, Functions, Solutions, Systems, General.\n"
                "- Must fit the business context below.\n\n"
                f"Business Name: {self.business_name}\n"
                f"Industries: {industries_str}\n\n"
                "SUBDOMAINS in this domain:\n"
                f"{subdomain_list}\n\n"
                f"{instructions}\n"
                "If these naming rules conflict with an explicit user directive in the instructions above, the user directive wins.\n\n"
                "Reply with ONLY the single-word domain name. No punctuation. No explanation."
            )
            try:
                raw = self._llm_call_retried_once(
                    f"PlaceholderDomainRename_{placeholder}",
                    lambda skip_cache, prompt=prompt, placeholder=placeholder: self.ai_agent._call_ai_query(
                        prompt=prompt,
                        prompt_name="PlaceholderDomainRename",
                        response_schema=None,
                        display_name=f"PlaceholderDomainRename_{placeholder}",
                        skip_cache=skip_cache
                    ))
                if not raw:
                    self.logger.warning(f"  ✗ {placeholder}: empty LLM response; keeping placeholder")
                    continue
                candidate = str(raw).strip().splitlines()[0].strip().strip(".").strip()
                if (
                    candidate
                    and candidate != placeholder
                    and valid_re.match(candidate)
                    and candidate.lower() not in banned
                ):
                    rename_map[placeholder] = protected.get(candidate.lower(), candidate)
                    self.logger.info(f"  ✓ {placeholder} → {rename_map[placeholder]} (from {inspire_plural(len(subs), 'subdomain')})")
                else:
                    self.logger.warning(f"  ✗ {placeholder}: invalid candidate '{candidate}'; keeping placeholder")
            except Exception as e:
                self.logger.warning(f"  ✗ {placeholder}: no name from the rename call ({redact_error(e)}); keeping placeholder")
        # Collision guard: if two placeholders map to same name, first keeps it, others retain placeholder
        seen = set()
        for k in list(rename_map.keys()):
            if rename_map[k] in seen:
                self.logger.warning(f"  ✗ name collision on '{rename_map[k]}'; keeping placeholder for {k}")
                del rename_map[k]
            else:
                seen.add(rename_map[k])
        if rename_map:
            for uc in use_cases:
                d = (uc.get("Business Domain") or "").strip()
                if d in rename_map:
                    uc["Business Domain"] = rename_map[d]
            self.logger.info(f"🏁 Rename complete: {implement_number_text(len(rename_map))} of {inspire_plural(len(groups), 'placeholder domain')} renamed")
        else:
            self.logger.warning(f"⚠️  Rename complete: 0 of {inspire_plural(len(groups), 'placeholder domain')} could be renamed; placeholders retained")
        return use_cases

    def _assign_default_domains(self, use_cases: list) -> list:
        """
        FALLBACK when LLM domain detection fails: group use cases by the catalog.schema of their
        primary table (the grouping batched detection uses) under DomainN placeholders, largest
        group first. `_rename_placeholder_domains_from_subdomains` later names each placeholder from
        its detected subdomains, and Phase L L15 reports any placeholder that survives.
        
        Args:
            use_cases: List of use case dictionaries
            
        Returns:
            List of use case copies with a placeholder 'Business Domain' and an empty 'Subdomain'
        """
        if not use_cases:
            return use_cases
        groups = defaultdict(list)
        for uc in use_cases:
            groups[self._uc_schema_prefix(uc)].append(uc)
        ordered = sorted(groups.items(), key=lambda kv: (-len(kv[1]), kv[0]))
        names = {prefix: f"Domain{i}" for i, (prefix, _ucs) in enumerate(ordered, 1)}
        result = []
        for uc in use_cases:
            uc_copy = uc.copy()
            uc_copy['Business Domain'] = names[self._uc_schema_prefix(uc)]
            uc_copy['Subdomain'] = ''
            self._add_clustering_fallback(uc_copy, 'domain:placeholder')
            result.append(uc_copy)
        self.logger.warning(
            f"[CLUSTERING_FALLBACK FIRED] {inspire_plural(len(result), 'use case')} grouped by source schema into "
            f"{inspire_plural(len(names), 'placeholder domain')}: "
            + ", ".join(f"{names[p]}={p} ({len(g)})" for p, g in ordered[:10])
        )
        try:
            NEXT_ACTIONS.add("CLUSTERING_FALLBACK", severity="HIGH", phase="Clustering", step="domains",
                             evidence=f"{inspire_plural(len(result), 'use case')} placed in {inspire_plural(len(names), 'schema-based placeholder domain')}")
        except Exception:
            pass
        return result

    def _assign_default_subdomains(self, use_cases: list, domain_name: str) -> list:
        """
        FALLBACK when LLM subdomain detection fails: one subdomain per primary table, named from the
        table's own words (exactly 2 words, e.g. store_sales -> "Store Sales").
        
        Args:
            use_cases: List of use case dictionaries
            domain_name: Name of the domain (for logging)
            
        Returns:
            List of use case copies with a table-derived 'Subdomain'
        """
        if not use_cases:
            return use_cases
        result = [uc.copy() for uc in use_cases]
        self._apply_table_subdomains(result, domain_name)
        self.logger.info(
            f"📋 [{domain_name}] Evidence-based subdomain fallback: {inspire_plural(len(result), 'use case')} across "
            f"{inspire_plural(len({uc['Subdomain'] for uc in result}), 'table-derived subdomain')}"
        )
        return result

    def _apply_table_subdomains(self, use_cases: list, domain_name: str):
        for uc in use_cases or []:
            uc['Subdomain'] = self._fallback_subdomain_name(self._uc_primary_table(uc), domain_name)
            self._add_clustering_fallback(uc, 'subdomain:table_evidence')

    @staticmethod
    def _fallback_subdomain_name(table_ref, domain_name="") -> str:
        name = str(table_ref or "").rsplit(".", 1)[-1]
        spaced = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", name)
        technical = {"fact", "fct", "dim", "tbl", "stg", "raw", "vw", "view", "src", "tmp", "temp",
                     "bronze", "silver", "gold", "int"}
        tokens = [t for t in (w.lower() for w in re.findall(r"[A-Za-z]+", spaced)) if len(t) > 1 and t not in technical]
        if len(tokens) >= 2:
            return f"{tokens[0].title()} {tokens[1].title()}"
        if tokens:
            return f"{tokens[0].title()} Analytics"
        base = re.sub(r"[^A-Za-z0-9]+", "", name) or re.sub(r"[^A-Za-z0-9]+", "", str(domain_name or "")) or "Unmapped"
        return f"{base.title()} Analytics"

    def _protected_domains(self) -> dict:
        protected = {}
        for d in (getattr(self, "user_business_domains", None) or []):
            name = str(d or "").strip()
            if name:
                protected.setdefault(name.lower(), name)
        return protected

    @staticmethod
    def _escape_template_braces(text) -> str:
        return str(text if text is not None else "").replace("{", "{{").replace("}", "}}")

    def _uc_primary_table(self, uc) -> str:
        for ref in self._uc_table_refs(uc):
            if not ref.lower().startswith("/volumes"):
                return ref
        return ""

    def _uc_schema_prefix(self, uc) -> str:
        primary = self._uc_primary_table(uc)
        if not primary:
            return "_no_tables_"
        parts = primary.split(".")
        return ".".join(parts[:2]) if len(parts) >= 2 else primary

    @staticmethod
    def _add_clustering_fallback(uc, tag):
        tags = [t for t in str(uc.get("clustering_fallback") or "").split(";") if t]
        if tag not in tags:
            tags.append(tag)
        uc["clustering_fallback"] = ";".join(tags)

    def _fill_by_table_evidence(self, missing, assigned, field, tag) -> list:
        votes = {}
        for uc in assigned or []:
            value = str(uc.get(field) or "").strip()
            table = self._uc_primary_table(uc)
            if value and table:
                votes.setdefault(table, {})
                votes[table][value] = votes[table].get(value, 0) + 1
        still = []
        for uc in missing or []:
            counts = votes.get(self._uc_primary_table(uc))
            if counts:
                uc[field] = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[0][0]
                self._add_clustering_fallback(uc, tag)
            else:
                still.append(uc)
        return still

    def _parse_assignment_csv(self, response, value_field, context, ucs) -> dict:
        if not response or not str(response).strip():
            return {}
        text = clean_csv_response(str(response))
        rows = CSVParser.parse_csv_list(text, logger=self.logger, context=context)
        if not rows:
            return {}
        columns = self._csv_columns(rows[0])
        id_col = self._csv_id_column(columns)
        value_col = columns.get(self._csv_column_key(value_field))
        if id_col is None or value_col is None:
            self.logger.warning(f"[{context}] response has no use case id or '{value_field}' column: {rows[0][:6]}")
            return {}
        header = [str(cell) for cell in rows[0]]
        records, _ = CSVParser.aligned_rows(
            rows[1:], self.logger, context, header=header, required=(header[id_col], header[value_col]),
            anchors={header[id_col]: CSVParser.one_of(str(uc.get('No', '')) for uc in ucs or [])}, text=text)
        mapping = {}
        for row in records:
            uc_id = self._csv_cell_text(row, id_col)
            value = str(row[value_col]).strip() if value_col < len(row) else ""
            if uc_id and value:
                mapping[uc_id] = value
        return mapping

    def _canonicalize_domain_names(self, mapping) -> dict:
        protected = self._protected_domains()
        variants = {}
        for value in mapping.values():
            spellings = variants.setdefault(value.lower(), {})
            spellings[value] = spellings.get(value, 0) + 1
        canonical = {low: protected.get(low) or sorted(sp.items(), key=lambda kv: (-kv[1], kv[0]))[0][0]
                     for low, sp in variants.items()}
        return {k: canonical[v.lower()] for k, v in mapping.items()}

    @staticmethod
    def _discovered_domains_hint(discovered_domains) -> str:
        if not discovered_domains:
            return ""
        return f"\n\n**PREVIOUSLY DISCOVERED DOMAINS (reuse these where appropriate):**\n{', '.join(sorted(discovered_domains))}\n"

    def _domain_finder_vars(self, use_cases_csv, language, extra_context="", violations="") -> dict:
        return {
            "use_cases_csv": use_cases_csv,
            "output_language": language,
            "business_name": self.business_name,
            "industries": ", ".join(self.industries) if hasattr(self, 'industries') and self.industries else "UNKNOWN_INDUSTRY",
            "business_context": self._get_business_context_fallback() + extra_context,
            "previous_violations": violations,
            "generation_instructions_section": self._get_generation_instruction_for_prompt("DOMAIN_FINDER_PROMPT"),
        }

    def _repair_unassigned_domains(self, missing, assigned, fieldnames, language, discovered_domains):
        if not missing:
            return
        import io
        import csv
        repaired = {}
        try:
            buf = io.StringIO()
            w = csv.DictWriter(buf, fieldnames=fieldnames, extrasaction='ignore')
            w.writeheader()
            w.writerows(missing)
            repair_vars = self._domain_finder_vars(
                buf.getvalue(), language,
                extra_context=self._discovered_domains_hint(discovered_domains),
                violations=(f"\n\n**🚨 THESE {len(missing)} USE CASES WERE MISSING FROM THE PREVIOUS ANSWER**: "
                            "assign EVERY one of them, reusing a previously discovered domain whenever one fits."))
            response = self._llm_call_retried_once(
                f"Detect_Domains_Repair_{language}",
                lambda _skip_cache: self.ai_agent.run_worker(
                    step_name=f"Detect_Domains_Repair_{language}",
                    worker_prompt_path="DOMAIN_FINDER_PROMPT",
                    prompt_vars=repair_vars,
                    response_schema=None,
                    skip_cache=True
                ))
            repaired = self._canonicalize_domain_names(
                self._parse_assignment_csv(response, "domain", "Domain detection repair", missing))
        except Exception as e:
            self.logger.warning(f"Domain repair call for {inspire_plural(len(missing), 'use case')} failed: {redact_error(e)}")
        still = []
        for uc in missing:
            domain = repaired.get(str(uc.get('No', '')).strip())
            if domain:
                uc['Business Domain'] = domain
            else:
                still.append(uc)
        from_llm = len(missing) - len(still)
        still = self._fill_by_table_evidence(still, assigned, 'Business Domain', 'domain:table_evidence')
        from_evidence = len(missing) - from_llm - len(still)
        if still:
            for uc, placeholder in zip(still, self._assign_default_domains(still)):
                uc['Business Domain'] = placeholder['Business Domain']
                uc['clustering_fallback'] = placeholder['clustering_fallback']
        self.logger.warning(
            f"[DOMAIN_REPAIR FIRED] {inspire_plural(len(missing), 'use case')} the LLM skipped: {from_llm} re-assigned by a "
            f"targeted call, {from_evidence} from same-table evidence, {implement_number_text(len(still))} placed in placeholder domains"
        )

    def _detect_subdomains_all_domains(self, domain_assignments: list, language: str, path_label: str) -> list:
        domain_usecases_map = defaultdict(list)
        unassigned = []
        for uc in domain_assignments or []:
            domain = str(uc.get('Business Domain') or '').strip()
            if domain:
                domain_usecases_map[domain].append(uc)
            else:
                unassigned.append(uc)
        for uc in self._assign_default_domains(unassigned) if unassigned else []:
            domain_usecases_map[uc['Business Domain']].append(uc)
        num_domains = len(domain_usecases_map)
        if not discover_step_on("SUBDOMAIN_DETECTOR"):
            self.logger.info("[FLAGS] SUBDOMAIN_DETECTOR is off in discover_domain_steps: subdomains come from the primary tables")
            out = []
            for domain_name, domain_ucs in domain_usecases_map.items():
                out.extend(self._assign_default_subdomains(domain_ucs, domain_name))
            return out
        if not num_domains:
            return []
        gc.collect()
        try:
            import psutil, os as _os
            mem_mb = psutil.Process(_os.getpid()).memory_info().rss / (1024 * 1024)
            self.logger.info(f"📊 MEMORY before subdomain detection: {mem_mb:.0f} MB (RSS)")
        except Exception:
            pass
        subdomain_parallelism, reason = calculate_adaptive_parallelism(
            "subdomain_detection", self.max_parallelism,
            num_items=sum(len(v) for v in domain_usecases_map.values()),
            num_domains=num_domains,
            is_llm_operation=True, logger=self.logger
        )
        log_adaptive_parallelism_decision("subdomain_detection", subdomain_parallelism, self.max_parallelism, reason)
        self._plan_progress_batches("SubdomainDetect", num_domains)
        _subdomain_call_budget = self._compute_subdomain_call_budget(num_domains)
        self.logger.info(f"[G34 SUBDOMAIN_BUDGET_ADAPTIVE FIRED] n_domains={num_domains} per_call_budget={_subdomain_call_budget}s ({path_label} path)")
        workers = max(1, min(int(subdomain_parallelism or 1), num_domains))
        total_timeout = _subdomain_call_budget * (self.max_retry_attempts + 1) * (-(-num_domains // workers)) + 120
        results = {}
        if workers >= 2:
            self.logger.info(f"🔄 PARALLEL SUBDOMAIN DETECTION: {workers} workers for {inspire_plural(num_domains, 'domain')} (total timeout: {total_timeout}s)")
            log_print(f"🔄 Subdomain detection: {inspire_plural(num_domains, 'domain')} with {workers} workers")
            try:
                with _SafeExecutorContext(max_workers=workers, thread_name_prefix="SubdomainDetect",
                                          logger=self.logger, name="SubdomainDetection") as executor:
                    future_to_domain = {}
                    for domain_name, domain_use_cases in domain_usecases_map.items():
                        future = executor.submit(
                            self._detect_subdomains_for_domain,
                            domain_name,
                            domain_use_cases,
                            language,
                            _subdomain_call_budget
                        )
                        future_to_domain[future] = domain_name
                    try:
                        for future in executor.completed(future_to_domain, timeout=total_timeout):
                            domain_name = future_to_domain[future]
                            try:
                                results[domain_name] = future.result(timeout=0) or []
                            except Exception as e:
                                self.logger.error(f"❌ Domain '{domain_name}': subdomain detection failed: {redact_error(e)}")
                                results[domain_name] = []
                    except concurrent.futures.TimeoutError:
                        executor.mark_timed_out()
                        timed_out = [d for d in domain_usecases_map if d not in results]
                        self.logger.error(f"⏱️ Subdomain detection timed out after {total_timeout}s; "
                                          f"table-evidence subdomains for: {timed_out}")
                        stuck = [(t.name, t.is_alive()) for t in threading.enumerate()
                                 if 'SubdomainDetect' in t.name or 'LLM_Query' in t.name]
                        self.logger.error(f"🧵 Stuck threads: {stuck}")
                        for d in timed_out:
                            results[d] = []
            except Exception as e:
                self.logger.error(f"❌ Parallel subdomain detection failed: {redact_error(e)}; "
                                  f"finishing the remaining domains sequentially")
        for idx, (domain_name, domain_use_cases) in enumerate(domain_usecases_map.items(), 1):
            if domain_name in results:
                continue
            self.logger.info(f"🔄 [{idx}/{num_domains}] Sequential subdomain detection: '{domain_name}' ({inspire_plural(len(domain_use_cases), 'use case')})")
            try:
                results[domain_name] = self._detect_subdomains_for_domain(
                    domain_name, domain_use_cases, language, timeout_seconds_override=_subdomain_call_budget) or []
            except Exception as e:
                self.logger.error(f"❌ [{idx}/{num_domains}] Domain '{domain_name}' failed: {redact_error(e)}")
                results[domain_name] = []
        final = []
        for domain_name, domain_use_cases in domain_usecases_map.items():
            final.extend(self._complete_subdomain_result(domain_name, domain_use_cases, results.get(domain_name) or []))
        return final

    def _complete_subdomain_result(self, domain_name, domain_use_cases, got) -> list:
        by_id = {}
        for uc in got or []:
            by_id.setdefault(str(uc.get('No', '')).strip(), []).append(uc)
        out, missing = [], []
        for uc in domain_use_cases:
            bucket = by_id.get(str(uc.get('No', '')).strip())
            if bucket:
                out.append(bucket.pop(0))
            else:
                missing.append(uc)
        if missing:
            if got:
                self.logger.warning(f"⚠️ Domain '{domain_name}': {inspire_plural(len(missing), 'use case')} missing from the subdomain "
                                    f"result; table-evidence subdomains assigned")
            out.extend(self._assign_default_subdomains(missing, domain_name))
        return out

    def _ensure_clustering_complete(self, original, result) -> list:
        result = list(result or [])
        counts = {}
        for uc in result:
            key = str(uc.get('No', '')).strip()
            counts[key] = counts.get(key, 0) + 1
        missing = []
        for uc in original or []:
            key = str(uc.get('No', '')).strip()
            if counts.get(key, 0) > 0:
                counts[key] -= 1
            else:
                missing.append(uc)
        if not missing:
            return result
        restored = []
        for uc in missing:
            uc_copy = uc.copy()
            if not str(uc_copy.get('Business Domain') or '').strip():
                uc_copy = self._assign_default_domains([uc_copy])[0]
            if not str(uc_copy.get('Subdomain') or '').strip():
                self._apply_table_subdomains([uc_copy], uc_copy['Business Domain'])
            restored.append(uc_copy)
        self.logger.warning(
            f"[CLUSTERING_COMPLETENESS FIRED] {inspire_plural(len(missing), 'use case was', 'use cases were')} lost during clustering and {'is' if len(missing) == 1 else 'are'} "
            f"restored with evidence-based assignments: {[uc.get('No') for uc in missing][:10]}"
        )
        try:
            NEXT_ACTIONS.add("CLUSTERING_FALLBACK", severity="HIGH", phase="Clustering", step="completeness",
                             evidence=f"restored {inspire_plural(len(missing), 'use case')} lost during clustering")
        except Exception:
            pass
        return result + restored

    @staticmethod
    def _llm_cost_mark() -> tuple:
        return (AIAgent._total_ai_calls, AIAgent._total_input_chars, AIAgent._total_output_chars)

    def _llm_cost_add(self, ledger, stage, mark) -> tuple:
        now = self._llm_cost_mark()
        entry = ledger.setdefault(stage, {"calls": 0, "input_chars": 0, "output_chars": 0})
        entry["calls"] += now[0] - mark[0]
        entry["input_chars"] += now[1] - mark[1]
        entry["output_chars"] += now[2] - mark[2]
        return now

    def _report_clustering_cost(self, ledger):
        self._honesty()["clustering_llm_cost"] = ledger
        self.logger.info(
            f"[CLUSTERING_LLM_COST] total_calls={sum(v['calls'] for v in ledger.values())} | "
            + " | ".join(f"{stage}={v['calls']} calls/~{(v['input_chars'] + v['output_chars']) // 4} tokens"
                         for stage, v in ledger.items())
        )

    @staticmethod
    def _compute_subdomain_call_budget(n_domains: int, floor_seconds: int = 300, per_domain_seconds: int = 60) -> int:
        """v1.0.3 B12: scale-adaptive per-call budget for SUBDOMAIN_DETECTOR_PROMPT.

        At 13-domain scale (tpcds), a 300s floor becomes 780s (13*60), giving the
        attempt-1 timeout ceiling `max(60, 780*0.5+30)=420s` in `_call_ai_query`,
        which comfortably covers the observed 180-350s per-call latency at that
        scale. Small corpora (<=5 domains) stay at the 300s floor unchanged.
        """
        try:
            _n = int(n_domains)
        except (TypeError, ValueError):
            _n = 0
        return max(int(floor_seconds), int(per_domain_seconds) * max(0, _n))

    def _detect_subdomains_for_domain(self, domain_name: str, use_cases: list, language: str,
                                       timeout_seconds_override: int = None) -> list:
        """
        Detect subdomains for a single domain's use cases using LLM.
        This method is designed to be called in parallel for each domain.
        A use case the LLM leaves without a subdomain is a violation that triggers a retry; after
        the last attempt it takes the subdomain of its same-primary-table siblings, else a
        table-derived one.
        
        Args:
            domain_name: Name of the domain
            use_cases: List of use case dictionaries belonging to this domain
            language: Output language
            timeout_seconds_override: v1.0.3 B12 — scale-adaptive per-call budget
                                       from `_compute_subdomain_call_budget(n_domains)`.
                                       Falls back to self.llm_timeout_seconds when None.
            
        Returns:
            List of use cases with updated subdomains
        """
        from collections import defaultdict
        import io
        import csv

        log_prefix = f"[Domain: {domain_name}]"
        self.logger.info(f"{log_prefix} 🚀 Starting subdomain detection for {inspire_plural(len(use_cases), 'use case')} (thread={threading.current_thread().name})...")
        log_print(f"{log_prefix} Subdomain detection started ({inspire_plural(len(use_cases), 'use case')})")

        if not use_cases:
            return use_cases

        try:
            # Convert use cases to CSV for LLM (Business Domain is set, Subdomain will be detected)
            output = io.StringIO()
            fieldnames = ['No', 'Name', 'type', 'Analytics Technique', 'Statement', 'Solution',
                         'Business Value', 'Beneficiary', 'Sponsor',
                         'Tables Involved']
            writer = csv.DictWriter(output, fieldnames=fieldnames, extrasaction='ignore')
            writer.writeheader()
            writer.writerows(use_cases)
            use_cases_csv = output.getvalue()

            # Check context size (uses model-specific limits from TECHNICAL_CONTEXT)
            prompt_template = self.ai_agent.prompt_templates.get("SUBDOMAIN_DETECTOR_PROMPT", "")
            estimated_size = self._prompt_overhead_chars("SUBDOMAIN_DETECTOR_PROMPT", prompt_template) + len(use_cases_csv) + 1000
            MAX_CONTEXT_CHARS = get_max_context_chars(language, "SUBDOMAIN_DETECTOR_PROMPT")

            if estimated_size > MAX_CONTEXT_CHARS:
                self.logger.warning(
                    f"{log_prefix} Subdomain prompt size ({estimated_size:,} chars) exceeds MAX_CONTEXT_CHARS ({MAX_CONTEXT_CHARS:,}). "
                    f"Splitting into smaller batches for subdomain detection."
                )
                # CONTEXT SPLITTING: Split use cases into smaller batches and process each
                return self._detect_subdomains_with_context_splitting(
                    domain_name, use_cases, language, prompt_template, MAX_CONTEXT_CHARS
                )

            max_attempts = self.max_retry_attempts + 1
            prompt_vars = {
                "domain_name": domain_name,
                "use_cases_csv": use_cases_csv,
                "output_language": language,
                "business_name": self.business_name,
                "industries": ", ".join(self.industries) if hasattr(self, 'industries') and self.industries else "UNKNOWN_INDUSTRY",
                "business_context": self._get_business_context_fallback(),
                "previous_violations": "",
                "generation_instructions_section": self._get_generation_instruction_for_prompt("SUBDOMAIN_DETECTOR_PROMPT"),
            }

            for attempt in range(1, max_attempts + 1):
                try:
                    self.logger.debug(f"{log_prefix} Subdomain detection attempt {attempt}/{max_attempts}...")

                    _effective_timeout = timeout_seconds_override if timeout_seconds_override is not None else self.llm_timeout_seconds
                    response_raw = self.ai_agent.run_worker(
                        step_name=f"Detect_Subdomains_{domain_name}_{language}_Attempt{attempt}",
                        worker_prompt_path="SUBDOMAIN_DETECTOR_PROMPT",
                        prompt_vars=prompt_vars,
                        response_schema=None,
                        timeout_override=_effective_timeout,  # v1.0.3 B12: scale-adaptive when override supplied
                        skip_cache=(attempt > 1)  # v0.7.11: retries bypass cache
                    )

                    # Validate response
                    inspire_llm_answer(response_raw, f"{log_prefix} Subdomain detection attempt {attempt}")

                    subdomain_assignment_map = self._parse_assignment_csv(response_raw, "subdomain", "Subdomain detection", use_cases)
                    if not subdomain_assignment_map:
                        self.logger.warning(f"{log_prefix} CSV parsing failed. Raw response (first 500 chars): {str(response_raw)[:500]}")
                        raise ValueError("No valid subdomain assignments found in CSV")

                    # Apply subdomain assignments
                    subdomain_assigned_use_cases = []
                    missing_ids = []
                    for uc in use_cases:
                        uc_copy = uc.copy()
                        uc_id = str(uc_copy.get('No', '')).strip()
                        uc_copy['Subdomain'] = subdomain_assignment_map.get(uc_id, '')
                        if not uc_copy['Subdomain']:
                            missing_ids.append(uc_id)
                        subdomain_assigned_use_cases.append(uc_copy)

                    # Validate subdomain assignments
                    violations = []
                    if missing_ids:
                        violations.append(f"{inspire_plural(len(missing_ids), 'use case')} missing a subdomain assignment: {inspire_listing(missing_ids, ', ')}")

                    # Group by subdomain
                    subdomain_usecases = defaultdict(list)
                    for uc in subdomain_assigned_use_cases:
                        subdomain = uc.get('Subdomain', '').strip()
                        if subdomain:
                            subdomain_usecases[subdomain].append(uc)

                    total_subdomains = len(subdomain_usecases)
                    total_ucs_in_domain = sum(len(ucs) for ucs in subdomain_usecases.values())
                    min_subdomains = self._min_subdomains(total_ucs_in_domain)
                    if total_subdomains < min_subdomains:
                        violations.append(f"Only {inspire_plural(total_subdomains, 'subdomain')}, minimum required: {min_subdomains}")
                    if total_subdomains > 10:
                        violations.append(f"Too many subdomains: {total_subdomains}, maximum allowed: 10")

                    # Validate subdomain naming (must be 2 words)
                    for subdomain in subdomain_usecases.keys():
                        if {"word_count", "empty"} & set(inspire_domain_name_check(subdomain, "subdomain")["problems"]):
                            word_count = len(subdomain.split())
                            violations.append(f"Subdomain '{subdomain}' has {inspire_plural(word_count, 'word')}, must be exactly {inspire_plural(INSPIRE_DOMAIN_RULES['subdomain']['words'], 'word')}")

                    # Validate use cases per subdomain (minimum 2)
                    for subdomain, ucs in subdomain_usecases.items():
                        count = len(ucs)
                        if count < 2:
                            violations.append(f"Subdomain '{subdomain}' has only {inspire_plural(count, 'use case')}, minimum required: 2")

                    # If no violations, success!
                    if not violations:
                        self.logger.debug(f"{log_prefix} ✅ Subdomain detection successful! Created {inspire_plural(total_subdomains, 'subdomain')}")
                        return subdomain_assigned_use_cases
                    else:
                        self.logger.warning(f"{log_prefix} ⚠️ Subdomain detection attempt {attempt} has {inspire_plural(len(violations), 'violation')}")
                        if attempt == max_attempts:
                            self.logger.warning(f"{log_prefix} Max attempts reached. Auto-fixing subdomain violations...")
                            gaps = [uc for uc in subdomain_assigned_use_cases if not uc.get('Subdomain')]
                            if gaps:
                                assigned = [uc for uc in subdomain_assigned_use_cases if uc.get('Subdomain')]
                                rest = self._fill_by_table_evidence(gaps, assigned, 'Subdomain', 'subdomain:table_evidence')
                                self._apply_table_subdomains(rest, domain_name)
                                self.logger.warning(f"{log_prefix} {inspire_plural(len(gaps), 'use case')} without an LLM subdomain assigned from table evidence")
                                subdomain_usecases = defaultdict(list)
                                for uc in subdomain_assigned_use_cases:
                                    subdomain_usecases[uc['Subdomain'].strip()].append(uc)
                            small_subdomains = [sd for sd, ucs in subdomain_usecases.items() if len(ucs) < 2]
                            if small_subdomains and len(subdomain_usecases) > 1:
                                largest_subdomain = max(subdomain_usecases.keys(), key=lambda sd: len(subdomain_usecases[sd]))
                                for small_sd in small_subdomains:
                                    if small_sd == largest_subdomain:
                                        continue
                                    self.logger.warning(f"{log_prefix} Merging subdomain '{small_sd}' ({inspire_plural(len(subdomain_usecases[small_sd]), 'use case')}) into '{largest_subdomain}'")
                                    for uc in subdomain_assigned_use_cases:
                                        if uc.get('Subdomain', '').strip() == small_sd:
                                            uc['Subdomain'] = largest_subdomain
                                    subdomain_usecases[largest_subdomain].extend(subdomain_usecases.pop(small_sd))

                            max_subdomains = 10

                            def _find_best_merge_target(src_sd, candidates, sd_usecases):
                                src_words = set(src_sd.lower().split())
                                best_target = None
                                best_score = -1
                                for cand in candidates:
                                    if cand == src_sd:
                                        continue
                                    cand_words = set(cand.lower().split())
                                    name_overlap = sum(
                                        1 for uc in sd_usecases[cand]
                                        if any(w in uc.get('Name', '').lower() for w in src_words)
                                    )
                                    word_overlap = len(src_words & cand_words)
                                    score = word_overlap * 10 + name_overlap
                                    if score > best_score:
                                        best_score = score
                                        best_target = cand
                                if best_target is None:
                                    best_target = min(
                                        (c for c in candidates if c != src_sd),
                                        key=lambda c: len(sd_usecases[c])
                                    )
                                return best_target

                            while len(subdomain_usecases) > max_subdomains:
                                sorted_sds = sorted(subdomain_usecases.keys(), key=lambda sd: len(subdomain_usecases[sd]))
                                smallest_sd = sorted_sds[0]
                                merge_target = _find_best_merge_target(smallest_sd, list(subdomain_usecases.keys()), subdomain_usecases)
                                self.logger.warning(
                                    f"{log_prefix} Too many subdomains ({implement_number_text(len(subdomain_usecases))}>{max_subdomains}). "
                                    f"Merging '{smallest_sd}' ({inspire_plural(len(subdomain_usecases[smallest_sd]), 'UC')}) into '{merge_target}' ({inspire_plural(len(subdomain_usecases[merge_target]), 'UC')})"
                                )
                                for uc in subdomain_assigned_use_cases:
                                    if uc.get('Subdomain', '').strip() == smallest_sd:
                                        uc['Subdomain'] = merge_target
                                subdomain_usecases[merge_target].extend(subdomain_usecases.pop(smallest_sd))

                            remaining_violations = [v for v in violations if "has only" not in v and "Too many subdomains" not in v and "missing a subdomain" not in v]
                            if remaining_violations:
                                self.logger.warning(f"{log_prefix} Remaining violations after auto-fix: {'; '.join(remaining_violations[:3])}")
                            return subdomain_assigned_use_cases
                        else:
                            # Prepare violation summary for retry
                            violation_summary = "\n\n**🚨 PREVIOUS ATTEMPT VIOLATIONS - YOU MUST FIX THESE 🚨**:\n"
                            violation_summary += "\n".join([f"- {v}" for v in violations])
                            prompt_vars['previous_violations'] = violation_summary
                            continue

                except CascadeRebatchError as cre:
                    self.logger.warning(
                        f"{log_prefix} Subdomain detection cascade rebatch needed after '{cre.failed_model_name}' failed. "
                        f"Switching to context-splitting for model '{cre.target_model_name}' "
                        f"(limit: {cre.target_context_limit_chars:,} chars)"
                    )
                    return self._detect_subdomains_with_context_splitting(
                        domain_name, use_cases, language, prompt_template,
                        cre.target_context_limit_chars, cre.target_model_endpoint
                    )

                except Exception as e:
                    if isinstance(e, TruncatedResponseError) and len(use_cases) > 1:
                        self.logger.warning(f"{redact_error(e)}; splitting the {inspire_plural(len(use_cases), 'use case')} of "
                                            f"{domain_name} into smaller batches")
                        return self._detect_subdomains_with_context_splitting(
                            domain_name, use_cases, language, prompt_template,
                            self._prompt_overhead_chars("SUBDOMAIN_DETECTOR_PROMPT", prompt_template) + 2000 + len(use_cases_csv) // 2
                        )
                    self.logger.warning(f"{log_prefix} Subdomain detection attempt {attempt} failed: {redact_error(e)}")
                    if attempt == max_attempts:
                        self.logger.error(f"{log_prefix} Max attempts reached. Using evidence-based subdomains as fallback...")
                        fallback_use_cases = self._assign_default_subdomains(use_cases, domain_name)
                        self.logger.warning(f"{log_prefix} ✅ Fallback complete: Assigned table-derived subdomains to {inspire_plural(len(fallback_use_cases), 'use case')}")
                        return fallback_use_cases

            self.logger.warning(f"{log_prefix} No subdomain assignments made. Using evidence-based subdomains as fallback...")
            return self._assign_default_subdomains(use_cases, domain_name)

        except Exception as e:
            self.logger.error(f"{log_prefix} Subdomain detection failed with error: {redact_error(e)}. Using evidence-based subdomains as fallback...")
            return self._assign_default_subdomains(use_cases, domain_name)

    def _detect_subdomains_with_context_splitting(self, domain_name: str, use_cases: list, language: str, prompt_template: str, max_context_chars: int, start_from_model: str = None) -> list:
        """
        Handle subdomain detection when context exceeds max size by splitting into batches.
        Processes each batch separately and merges results. Supports cascade rebatching.
        A use case no batch assigns takes the subdomain of its same-primary-table siblings, else a
        table-derived one.
        
        Args:
            domain_name: Name of the domain
            use_cases: List of use case dictionaries
            language: Output language
            prompt_template: The prompt template string
            max_context_chars: Maximum context size in characters
            start_from_model: Optional model endpoint to start cascade from
            
        Returns:
            List of use cases with assigned subdomains
        """
        import io
        import csv
        from collections import defaultdict

        log_prefix = f"[Domain: {domain_name}][Context Split]"

        MAX_CASCADE_RETRIES = 3
        effective_limit = max_context_chars
        effective_start_model = start_from_model
        sample_fieldnames = ['No', 'Name', 'type', 'Analytics Technique', 'Statement', 'Solution',
                            'Business Value', 'Beneficiary', 'Sponsor', 'Tables Involved']

        all_subdomain_assignments = {}
        _sub_lock = threading.Lock()
        remaining_use_cases = list(use_cases)

        for cascade_retry in range(MAX_CASCADE_RETRIES):
            if not remaining_use_cases:
                break

            sample_output = io.StringIO()
            sample_writer = csv.DictWriter(sample_output, fieldnames=sample_fieldnames, extrasaction='ignore')
            sample_writer.writeheader()
            if remaining_use_cases:
                sample_writer.writerow(remaining_use_cases[0])
            avg_use_case_size = max(100, len(sample_output.getvalue()))

            available_chars = effective_limit - self._prompt_overhead_chars("SUBDOMAIN_DETECTOR_PROMPT", prompt_template) - 2000
            batch_size = max(2, available_chars // max(1, avg_use_case_size))

            self.logger.info(
                f"{log_prefix} Splitting {inspire_plural(len(remaining_use_cases), 'use case')} into batches of ~{batch_size} "
                f"(context limit: {effective_limit:,} chars, model: {effective_start_model or 'default cascade'}, "
                f"already assigned: {implement_number_text(len(all_subdomain_assignments))})"
            )

            batches = []
            for i in range(0, len(remaining_use_cases), batch_size):
                batches.append(remaining_use_cases[i:i + batch_size])

            self.logger.info(f"{log_prefix} Created {inspire_plural(len(batches), 'batch', 'batches')} for subdomain detection")

            num_batches = len(batches)
            cascade_rebatch_triggered = False
            cascade_rebatch_error = None

            def _process_subdomain_batch(batch_idx, batch, _start_model=effective_start_model):
                self.logger.info(f"{log_prefix} Processing batch {batch_idx}/{num_batches} ({inspire_plural(len(batch), 'use case')})")
                local_assignments = {}
                try:
                    batch_output = io.StringIO()
                    batch_writer = csv.DictWriter(batch_output, fieldnames=sample_fieldnames, extrasaction='ignore')
                    batch_writer.writeheader()
                    batch_writer.writerows(batch)
                    batch_csv = batch_output.getvalue()

                    max_attempts = self.max_retry_attempts + 1
                    prompt_vars = {
                        "domain_name": domain_name,
                        "use_cases_csv": batch_csv,
                        "output_language": language,
                        "business_name": self.business_name,
                        "industries": ", ".join(self.industries) if hasattr(self, 'industries') and self.industries else "UNKNOWN_INDUSTRY",
                        "business_context": self._get_business_context_fallback(),
                        "previous_violations": "",
                        "generation_instructions_section": self._get_generation_instruction_for_prompt("SUBDOMAIN_DETECTOR_PROMPT"),
                    }

                    for attempt in range(1, max_attempts + 1):
                        try:
                            response_raw = self.ai_agent.run_worker(
                                step_name=f"Detect_Subdomains_{domain_name}_Batch{batch_idx}_{language}_Attempt{attempt}",
                                worker_prompt_path="SUBDOMAIN_DETECTOR_PROMPT",
                                prompt_vars=prompt_vars,
                                response_schema=None,
                                timeout_override=self.llm_timeout_seconds,
                                start_from_model=_start_model,
                                skip_cache=(attempt > 1)  # v0.7.11: retries bypass cache
                            )

                            inspire_llm_answer(response_raw, f"{log_prefix} Batch {batch_idx}")

                            parsed = self._parse_assignment_csv(response_raw, "subdomain", f"Subdomain detection batch {batch_idx}", batch)
                            if not parsed:
                                raise ValueError("No valid subdomain assignments found in CSV")
                            local_assignments.update(parsed)
                            self.logger.info(f"{log_prefix} Batch {batch_idx} completed successfully")
                            break

                        except CascadeRebatchError:
                            raise
                        except Exception as attempt_err:
                            if isinstance(attempt_err, TruncatedResponseError) and len(batch) > 1:
                                half = -(-len(batch) // 2)
                                self.logger.warning(f"{redact_error(attempt_err)}; splitting its {inspire_plural(len(batch), 'use case')} "
                                                    f"into 2 smaller batches")
                                for suffix, piece in (("a", batch[:half]), ("b", batch[half:])):
                                    _process_subdomain_batch(f"{batch_idx}{suffix}", piece, _start_model)
                                break
                            self.logger.warning(f"{log_prefix} Batch {batch_idx} attempt {attempt} failed: {redact_error(attempt_err)}")
                            if attempt == max_attempts:
                                self.logger.error(f"{log_prefix} Batch {batch_idx} failed after {inspire_plural(max_attempts, 'attempt')}")

                except CascadeRebatchError:
                    raise
                except Exception as batch_err:
                    self.logger.error(f"{log_prefix} Batch {batch_idx} processing error: {redact_error(batch_err)}")

                with _sub_lock:
                    all_subdomain_assignments.update(local_assignments)

            batch_workers = min(4, num_batches)
            try:
                if num_batches <= 1:
                    _process_subdomain_batch(1, batches[0]) if batches else None
                else:
                    _sb_total_timeout = self.llm_timeout_seconds * 3 * len(batches) + 120
                    with _SafeExecutorContext(max_workers=batch_workers, thread_name_prefix="sub_batch", logger=self.logger, name="SubdomainBatch") as ctx:
                        sb_futures = [ctx.submit(_process_subdomain_batch, i, b) for i, b in enumerate(batches, 1)]
                        try:
                            for f in ctx.completed(sb_futures, timeout=_sb_total_timeout):
                                try:
                                    f.result(timeout=self.llm_timeout_seconds * 3)
                                except CascadeRebatchError as cre:
                                    cascade_rebatch_triggered = True
                                    cascade_rebatch_error = cre
                                    ctx.mark_timed_out()
                                    for remaining_f in sb_futures:
                                        if not remaining_f.done():
                                            remaining_f.cancel()
                                    break
                                except Exception as exc:
                                    self.logger.error(f"{log_prefix} Subdomain batch task failed: {redact_error(exc)}")
                        except concurrent.futures.TimeoutError:
                            ctx.mark_timed_out()
                            self.logger.error(f"{log_prefix} Subdomain batch timed out globally ({_sb_total_timeout}s)")
            except CascadeRebatchError as cre:
                cascade_rebatch_triggered = True
                cascade_rebatch_error = cre

            if cascade_rebatch_triggered and cascade_rebatch_error:
                effective_limit = cascade_rebatch_error.target_context_limit_chars
                effective_start_model = cascade_rebatch_error.target_model_endpoint
                remaining_use_cases = [
                    uc for uc in remaining_use_cases
                    if str(uc.get('No', '')).strip() not in all_subdomain_assignments
                ]
                self.logger.warning(
                    f"{log_prefix} CASCADE RETRY {cascade_retry + 1}/{MAX_CASCADE_RETRIES}: "
                    f"Rebatching {inspire_plural(len(remaining_use_cases), 'remaining use case')} for model "
                    f"'{cascade_rebatch_error.target_model_name}' (limit: {effective_limit:,} chars, "
                    f"already assigned: {implement_number_text(len(all_subdomain_assignments))})"
                )
                if not remaining_use_cases:
                    self.logger.info(f"{log_prefix} All use cases assigned despite cascade error")
                    break
                continue

            break

        result = []
        for uc in use_cases:
            uc_copy = uc.copy()
            uc_copy['Subdomain'] = all_subdomain_assignments.get(str(uc.get('No', '')).strip(), '')
            result.append(uc_copy)
        gaps = [uc for uc in result if not uc['Subdomain']]
        if gaps:
            rest = self._fill_by_table_evidence(gaps, [uc for uc in result if uc['Subdomain']], 'Subdomain', 'subdomain:table_evidence')
            self._apply_table_subdomains(rest, domain_name)
            self.logger.warning(f"{log_prefix} {inspire_plural(len(gaps), 'use case')} received no LLM subdomain; assigned from table evidence")

        subdomain_counts = defaultdict(int)
        for uc in result:
            subdomain_counts[uc.get('Subdomain', 'Unknown')] += 1

        self.logger.info(f"{log_prefix} Context splitting complete: {inspire_plural(len(result), 'use case')} assigned to {inspire_plural(len(subdomain_counts), 'subdomain')}")
        for subdomain, count in sorted(subdomain_counts.items(), key=lambda x: -x[1]):
            self.logger.debug(f"{log_prefix}   - {subdomain}: {inspire_plural(count, 'use case')}")

        return result

    def _report_table_statistics(self, use_cases: list):
        """
        Reports statistics on table inclusion/exclusion based on generated use cases.
        Compares the tables used in use cases against every discovered table.
        """
        try:
            all_available_tables = set()
            for tup in (getattr(self.data_loader, 'all_table_tuples', None) or []):
                try:
                    all_available_tables.add(".".join(str(x) for x in tuple(tup)[:3]).lower())
                except Exception:
                    continue

            total_available = len(all_available_tables)

            if total_available == 0:
                self.logger.warning("No discovered tables available in the data loader. Skipping table statistics report.")
                return

            tables_used = set()
            for uc in use_cases:
                for table in self._uc_table_refs(uc):
                    if table in all_available_tables:
                        tables_used.add(table)

            total_included = len(tables_used)
            total_excluded = total_available - total_included

            # Calculate percentages
            pct_included = (total_included / total_available * 100) if total_available > 0 else 0
            pct_excluded = (total_excluded / total_available * 100) if total_available > 0 else 0

            log_print("\n" + "="*80)
            log_print("TABLE UTILIZATION REPORT")
            log_print("="*80)
            log_print(f"Total Available Tables: {total_available}")
            log_print(f"Tables Included in Use Cases: {total_included} ({pct_included:.1f}%)")
            log_print(f"Tables Excluded (No Business Value): {total_excluded} ({pct_excluded:.1f}%)")
            log_print("="*80 + "\n")

            # Log it as well
            self.logger.info(f"Table Statistics: {total_included}/{inspire_plural(total_available, 'table')} included ({pct_included:.1f}%), {total_excluded} excluded ({pct_excluded:.1f}%)")

        except Exception as e:
            self.logger.error(f"Failed to generate table statistics report: {redact_error(e)}")

    def _priority_sort_key(self, use_case: dict) -> tuple:
        return self._final_rank_key(use_case)

    def _natural_sort_key(self, use_case: dict) -> tuple:
        """
        Natural sort key for use case IDs to ensure proper ordering.
        
        Handles IDs like: N01-AI01, N01-AI02, ..., N01-AI10, N01-AI11, N01-ST01, etc.
        Standard string sort would incorrectly order: AI1, AI10, AI11, AI2, AI3...
        Natural sort correctly orders: AI1, AI2, AI3, ..., AI10, AI11...
        
        Returns tuple: (domain_num, source_type, sequence_num, original_id)
        Example: "N01-AI05" -> (1, 'AI', 5, 'N01-AI05')
        """
        import re
        use_case_id = str(use_case.get('No') or 'N99-ZZ999').strip()

        # REQ-569: AIx-UCx (and the older Nx-Ux) order by domain number, then use case number
        numbered = inspire_parse_use_case_id(use_case_id)
        if numbered:
            return (numbered[0], 'UC', numbered[1], use_case_id)

        # Parse ID format: N##-XX## (e.g., N01-AI05, N02-ST10)
        match = re.match(r'N(\d+)-([A-Z]+)(\d+)', use_case_id)
        if match:
            domain_num = int(match.group(1))
            source_type = match.group(2)  # AI or ST
            seq_num = int(match.group(3))
            # Sort AI before ST (alphabetically)
            return (domain_num, source_type, seq_num, use_case_id)

        # Fallback: Try to parse older formats like AI-XXX-U## or just extract numbers
        # Pattern: AI-XXX-U## or ST-XXX-U##
        match2 = re.match(r'(AI|ST)-([A-Z0-9_]+)-U(\d+)', use_case_id)
        if match2:
            source_type = match2.group(1)
            seq_num = int(match2.group(3))
            return (99, source_type, seq_num, use_case_id)

        # Final fallback: extract any numbers from the ID for some ordering
        numbers = re.findall(r'\d+', use_case_id)
        if numbers:
            # Use first number as domain, last number as sequence
            return (int(numbers[0]) if len(numbers) > 0 else 99,
                    'ZZ',
                    int(numbers[-1]) if len(numbers) > 0 else 999,
                    use_case_id)

        # No numbers found - sort at the end
        return (999, 'ZZ', 999, use_case_id)

