# --- REQ-573 R10.4, R10.5, R9.3: the SQL loss-pool enumerator (plan, totals, coverage) ---
INSPIRE_LOSS_POOL_MATERIAL_SHARE = 0.01  # a pool is material from this share of the same money column's total, in the same currency
INSPIRE_LOSS_POOL_MAX_VALUES = 200  # more distinct values than this is not a status column
INSPIRE_LOSS_COLUMN_WORDS = {
    "discount": "discounted", "discounts": "discounted", "markdown": "discounted", "markdowns": "discounted",
    "rebate": "discounted", "rebates": "discounted", "penalty": "penalty", "penalties": "penalty", "fine": "penalty",
    "fines": "penalty", "overtime": "overtime", "scrap": "scrap", "waste": "scrap", "wastage": "scrap",
    "writeoff": "written_off", "writeoffs": "written_off", "refund": "refunded", "refunds": "refunded"}
INSPIRE_LOSS_VALUE_WORDS = {
    "cancelled": ("cancelled", "canceled", "cancel", "cancelation", "cancellation", "cncl", "cncld", "cxl", "cxld", "voided"),
    "returned": ("returned", "return", "returns", "rtn", "rtnd", "rma"),
    "refunded": ("refunded", "refund", "refunds", "rfnd", "rfd", "chargeback", "chargebacks"),
    "late": ("late", "overdue", "delayed", "delinquent", "pastdue", "ovd"),
    "discounted": ("discounted", "discount", "markdown", "rebated", "rebate"),
    "written_off": ("writeoff", "writeoffs", "writtenoff", "baddebt"),
    "penalty": ("penalty", "penalties", "penalized", "penalised", "fined")}
INSPIRE_LOSS_VALUE_KIND = {word: kind for kind, words in INSPIRE_LOSS_VALUE_WORDS.items() for word in words}
INSPIRE_LOSS_NEUTRAL_WORDS = frozenset((
    "open opened closed close delivered pending in transit settled done completed complete shipped active inactive new paid approved "
    "processing confirmed booked created posted cleared progress on time ontime received accepted fulfilled success successful ok ready "
    "scheduled draft submitted issued partial partially hold held review unpaid outstanding dispatched picked packed allocated "
    "invoiced billed reserved arrived departed started finished ended running yes no true false").split())
INSPIRE_LOSS_FLOW_WORDS = (("payment", ("payment", "paid", "receipt", "settlement")), ("invoice", ("invoice", "bill", "billing")),
                           ("order", ("order", "booking", "reservation", "sale")))


def _inspire_loss_column_kind(name) -> str:
    tokens = DatabricksInspire._role_tokens(name)
    for token in tokens:
        if token in INSPIRE_LOSS_COLUMN_WORDS:
            return INSPIRE_LOSS_COLUMN_WORDS[token]
    return "written_off" if any(a in ("write", "written") and b == "off" for a, b in zip(tokens, tokens[1:])) else ""


def _inspire_loss_value_kind(value) -> str:
    """The loss kind of one status value: a kind, "neutral" (every word is a known no-loss word) or "" (a word no list knows)."""
    text = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(value or "")).lower()
    tokens = [token for token in re.split(r"[^a-z0-9]+", text) if token]
    if not tokens:
        return ""
    joined = "".join(tokens)
    if joined in INSPIRE_LOSS_VALUE_KIND:
        return INSPIRE_LOSS_VALUE_KIND[joined]
    kinds = {INSPIRE_LOSS_VALUE_KIND[token] for token in tokens if token in INSPIRE_LOSS_VALUE_KIND}
    if len(kinds) == 1:
        return next(iter(kinds))
    return "neutral" if not kinds and all(token in INSPIRE_LOSS_NEUTRAL_WORDS for token in tokens) else ""


def _inspire_loss_flow(table, money_columns) -> str:
    for text in (str(table).split(".")[-1], " ".join(money_columns)):
        tokens = DatabricksInspire._role_tokens(text)
        for flow, words in INSPIRE_LOSS_FLOW_WORDS:
            if any(token.startswith(word) for token in tokens for word in words):
                return flow
    return "other"


def inspire_loss_pool_plan(metadata) -> list:
    """One plan per table: the money columns to split by status, the status columns, the currency column and the loss columns that
    are pools of their own. Pure: metadata is the _kind_metadata_from_details shape."""
    plans = []
    for table, entry in (metadata or {}).items():
        columns = (entry or {}).get("columns") or {}
        cols = {name: (info or {}).get("type") or "" for name, info in columns.items()}
        comments = {name: (info or {}).get("comment") or "" for name, info in columns.items()}
        roles, _ambiguous = DatabricksInspire._column_roles(cols, comments)
        family = {name: _metadata_type_family(dtype) for name, dtype in cols.items()}
        priced = set(roles.get("money", [])) | set(roles.get("cost", [])) | set(roles.get("price", []))
        loss_columns = [{"column": name, "kind": _inspire_loss_column_kind(name), "unit": "money" if name in priced else "quantity"}
                        for name in cols if family[name] == "numeric" and _inspire_loss_column_kind(name)]
        loss_names = {item["column"] for item in loss_columns}
        money = [name for name in dict.fromkeys(list(roles.get("money", [])) + list(roles.get("cost", [])))
                 if family.get(name) == "numeric" and name not in loss_names]
        status = [name for name in dict.fromkeys(list(roles.get("status_activity", [])) + list(roles.get("label_column", [])))
                  if family.get(name) == "string"]
        currency = next((name for name in cols if family[name] == "string"
                         and set(DatabricksInspire._role_tokens(name)) & {"currency", "ccy", "curr"}), None)
        if money or loss_columns:
            plans.append({"table": table, "money_columns": money, "status_columns": [n for n in status if n != currency],
                          "currency_column": currency, "loss_columns": loss_columns, "flow": _inspire_loss_flow(table, money)})
    return plans


def inspire_loss_pool_totals(pools) -> list:
    """Totals per (flow, currency, unit), never across them. An unknown amount is counted, never added as 0."""
    totals = {}
    for pool in pools or []:
        row = totals.setdefault((pool.get("flow"), pool.get("currency"), pool.get("unit")),
                                {"flow": pool.get("flow"), "currency": pool.get("currency"), "unit": pool.get("unit"),
                                 "amount": None, "pools": 0, "unknown_pools": 0})
        row["pools"] += 1
        if pool.get("amount") is None:
            row["unknown_pools"] += 1
        else:
            row["amount"] = (row["amount"] or 0.0) + float(pool["amount"])
    return list(totals.values())


def _inspire_loss_pool_table_key(name) -> str:
    return str(name or "").replace("`", "").strip().lower()


INSPIRE_DOMAIN_AUTO_DEEPEN = 1  # R9.4: domains the ranking deepens on its own
INSPIRE_DOMAIN_SUGGEST = 5  # R9.4: domains it suggests after them (pins come on top)
INSPIRE_DOMAIN_CLOSE_CALL = 0.10  # two measured scores this close (share of the larger) are a close call
INSPIRE_DOMAIN_CHOICE_KEYS = ("pin", "exclude", "launch")


def inspire_domain_choices(generation_instructions, runtime_choices) -> dict:
    """The person's domain choices (REQ-573 R9.4): the runtime lists first, then the "- DOMAIN PIN/EXCLUDE/LAUNCH: " lines of the generation
    instructions (comma-separated). Trimmed, empties dropped, de-duplicated in order."""
    out = {key: [] for key in INSPIRE_DOMAIN_CHOICE_KEYS}
    runtime = runtime_choices if isinstance(runtime_choices, dict) else {}

    def add(key, values):
        for value in values:
            value = str(value).strip()
            if value and value not in out[key]:
                out[key].append(value)

    for key in INSPIRE_DOMAIN_CHOICE_KEYS:
        add(key, runtime.get(key) or [])
    for line in str(generation_instructions or "").split("\n"):
        for key in INSPIRE_DOMAIN_CHOICE_KEYS:
            prefix = f"- DOMAIN {key.upper()}: "
            if line.startswith(prefix):
                add(key, line[len(prefix):].split(","))
    return out


def inspire_domain_ranking(table_domains, pools, choices=None, loss_status="ok") -> dict:
    """SCAN ranks the table domains by measured fixable losses; DEEP picks one, suggests up to five and the pairs (REQ-573 R9.1-R9.5).
    A pool counts once, in the domain whose home holds its table. The score is the largest single (flow, currency) money total in the
    scope's ranking currency, never a sum across flows or currencies. An unknown loss is unknown (score None), never 0. Turnover is
    context only. The person's pins, excludes and launches win. Pure and deterministic under pool order."""
    td = table_domains if isinstance(table_domains, dict) else {}
    domains = td.get("domains") or []
    if not isinstance(domains, list):
        raise ValueError("table_domains['domains'] must be a list")
    skip = bool(td.get("skip_domain_step"))
    ids = [str(d["id"]) for d in domains]
    home_of = {}
    for d in domains:
        for table in d.get("home") or []:
            home_of.setdefault(_inspire_loss_pool_table_key(table), str(d["id"]))
    ordered = sorted((p for p in pools or [] if isinstance(p, dict)), key=lambda p: (
        str(p.get("pool_id")), str(p.get("table")), str(p.get("money_column")), str(p.get("loss_kind")), str(p.get("flow")),
        str(p.get("currency")), str(p.get("unit")), str(p.get("amount"))))
    by_domain = {i: [] for i in ids}
    unattributed = []
    for pool in ordered:
        home = home_of.get(_inspire_loss_pool_table_key(pool.get("table")))
        if home is None:
            unattributed.append(pool.get("pool_id"))
        else:
            by_domain[home].append(pool)

    def measured_money(pool):
        return pool.get("unit") == "money" and pool.get("amount") is not None

    counts = Counter(p.get("currency") for ps in by_domain.values() for p in ps if measured_money(p))
    ranking_currency = min(counts, key=lambda c: (-counts[c], str(c))) if counts else None

    rows = {}
    for d in domains:
        did = str(d["id"])
        dpools = by_domain[did]
        totals = inspire_loss_pool_totals(dpools)
        money_rows = [r for r in totals if r["unit"] == "money" and r["amount"] is not None and r["currency"] == ranking_currency]
        best = min(money_rows, key=lambda r: (-r["amount"], str(r["flow"]))) if money_rows else None
        why = None
        if best is not None:
            kinds = {}
            for p in dpools:
                if measured_money(p) and p.get("flow") == best["flow"] and p.get("currency") == best["currency"]:
                    kinds[p.get("loss_kind")] = kinds.get(p.get("loss_kind"), 0.0) + float(p["amount"])
            why = {"flow": best["flow"], "currency": best["currency"], "amount": best["amount"],
                   "kinds": dict(sorted(kinds.items(), key=lambda kv: str(kv[0]))), "pools": best["pools"],
                   "unknown_pools": best["unknown_pools"]}
        seen, turnover = set(), {}
        for p in dpools:
            share, key = p.get("share"), (p.get("table"), p.get("money_column"), p.get("currency"))
            if p.get("source") == "status_split" and measured_money(p) and isinstance(share, (int, float)) and share > 0 and key not in seen:
                seen.add(key)
                fc = (p.get("flow"), p.get("currency"))
                turnover[fc] = turnover.get(fc, 0.0) + abs(float(p["amount"])) / share
        reasons = []
        if loss_status != "ok":
            reasons.append(f"loss_pools_{loss_status}")
        if not dpools and loss_status == "ok":
            reasons.append("no_loss_pool")
        if any(p.get("amount") is None for p in dpools):
            reasons.append("unknown_pools")
        if any("measure_partly_missing" in (p.get("flags") or []) for p in dpools):
            reasons.append("partly_missing")
        if any(measured_money(p) and p.get("currency") != ranking_currency for p in dpools):
            reasons.append("other_currency")
        if dpools and not any(p.get("unit") == "money" for p in dpools):
            reasons.append("quantity_only")
        rows[did] = {"id": did, "rank": None, "loss_rank": None, "status": "ranked", "pinned": False,
                     "tables": list(d.get("tables") or []), "home": list(d.get("home") or []),
                     "score": best["amount"] if best else None, "currency": best["currency"] if best else None,
                     "flow": best["flow"] if best else None, "why": why,
                     "loss_totals": totals,
                     "turnover": [{"flow": f, "currency": c, "amount": a} for (f, c), a in sorted(turnover.items(), key=lambda kv: (str(kv[0][0]), str(kv[0][1])))],
                     "reason": "", "uncertainty": "high", "uncertainty_reasons": reasons, "_pools": len(dpools)}

    index = {i: n for n, i in enumerate(ids)}
    loss_order = sorted(ids, key=lambda i: (0, -rows[i]["score"], index[i]) if rows[i]["score"] is not None
                        else (1 if rows[i]["_pools"] else 2, 0.0, index[i]))
    for pos, i in enumerate(loss_order, 1):
        rows[i]["loss_rank"] = pos
    measured = [i for i in loss_order if rows[i]["score"] is not None]
    for a, b in zip(measured, measured[1:]):
        hi, lo = rows[a]["score"], rows[b]["score"]
        if hi > 0 and (hi - lo) <= INSPIRE_DOMAIN_CLOSE_CALL * hi:
            for i in (a, b):
                rows[i]["uncertainty_reasons"].append("close_call")

    # the person's choices
    by_id = {i.lower(): i for i in ids}
    unmatched, matched = [], {}
    wanted = choices if isinstance(choices, dict) else {}
    for key in INSPIRE_DOMAIN_CHOICE_KEYS:
        found = []
        for entry in wanted.get(key) or []:
            text = str(entry).strip()
            hit = by_id.get(text.lower()) or home_of.get(_inspire_loss_pool_table_key(text))
            if hit is None:
                if text and text not in unmatched:
                    unmatched.append(text)
            elif hit not in found:
                found.append(hit)
        matched[key] = found
    excluded_ids = set(matched["exclude"])
    conflicts = sorted(i for i in excluded_ids if i in matched["pin"] or i in matched["launch"])
    pinned = [i for i in matched["pin"] if i not in excluded_ids]
    launched = [i for i in matched["launch"] if i not in excluded_ids]

    if skip:  # R9.5: one coherent group, the whole scope is deepened and the person's domain choices do not apply
        excluded_ids, launched, conflicts = set(), [], []
        deepened, suggested, pinned, pairs_in = list(loss_order), [], [], []
    else:
        open_ids = [i for i in loss_order if i not in excluded_ids]
        deepened = launched or open_ids[:INSPIRE_DOMAIN_AUTO_DEEPEN]
        rest = [i for i in open_ids if i not in deepened and i not in pinned]
        suggested = [i for i in pinned if i not in deepened] + rest[:INSPIRE_DOMAIN_SUGGEST]
        pairs_in = td.get("challenger_pairs") or []
    final = deepened + suggested
    final += [i for i in loss_order if i not in final and i not in excluded_ids]
    final_rank = {i: n for n, i in enumerate(final, 1)}
    final += [i for i in loss_order if i in excluded_ids]

    for i in final:
        row = rows[i]
        row["rank"] = final_rank.get(i)
        row["status"] = ("excluded" if i in excluded_ids else "deepened" if i in deepened
                         else "suggested" if i in suggested else "ranked")
        row["pinned"] = i in pinned
        if row["score"] is not None:
            kinds = ", ".join(f"{k} {v:,.2f}" for k, v in row["why"]["kinds"].items())
            row["reason"] = f"{row['score']:,.2f} {row['currency']} in {row['flow']} flows ({kinds})"
        elif row["_pools"]:
            row["reason"] = "unknown: the loss pools have no measured amount in the ranking currency"
        elif loss_status != "ok":
            row["reason"] = f"unknown: the loss pools are {loss_status}"
        else:
            row["reason"] = "unknown: no loss pool was found on its tables"
        if i in pinned:
            row["reason"] += "; pinned by the user"
        if i in launched and i in deepened:
            row["reason"] += "; launched by the user"
        if i in excluded_ids:
            row["reason"] += "; excluded by the user"
        row["uncertainty"] = "high" if row["score"] is None else "medium" if row["uncertainty_reasons"] else "low"
        del row["_pools"]

    pairs = []
    picked = set(deepened) | set(suggested)
    for n, pair in enumerate(pairs_in):
        pd = [str(x) for x in pair.get("domains") or []]
        if len(pd) < 2 or any(x not in rows for x in pd) or any(x in excluded_ids for x in pd) or not picked & set(pd):
            continue
        via = list(pair.get("via") or [])
        pairs.append((sorted(final_rank[x] for x in pd), n, {"domains": pd, "via": via,
                     "reason": f"{' and '.join(pd)} share {', '.join(via) if via else 'a join path'}"}))
    pairs.sort(key=lambda t: (t[0], t[1]))
    return {"skip_domain_step": skip, "whole_scope": skip, "loss_pool_status": loss_status, "ranking_currency": ranking_currency,
            "domains": [rows[i] for i in final], "deepened": deepened, "suggested": suggested,
            "excluded": [i for i in loss_order if i in excluded_ids], "pinned": pinned, "pairs": [p[2] for p in pairs],
            "unattributed_pools": sorted(str(x) for x in unattributed),
            "choices": {"pin": matched["pin"], "exclude": matched["exclude"], "launch": matched["launch"],
                        "unmatched": unmatched, "conflicts": conflicts}}


def inspire_loss_pool_coverage(pools, use_cases) -> list:
    """One row per pool: the use cases that cover it, or the reason it has none. A use case covers a pool through its
    loss_pool_id or a KPI on the pool's table and money column (and, for a status split, filtered to one of its values)."""
    rows = []
    for pool in pools or []:
        values = {str(v).casefold() for v in pool.get("split_values") or []}
        covering = []
        for uc in use_cases or []:
            if not isinstance(uc, dict):
                continue
            hit = uc.get("loss_pool_id") == pool.get("pool_id")
            for kpi in [] if hit else (uc.get("KPIs") or uc.get("kpis") or []):
                if not isinstance(kpi, dict) or _inspire_loss_pool_table_key(kpi.get("table")) != _inspire_loss_pool_table_key(pool.get("table")) \
                        or str(kpi.get("column") or "").casefold() != str(pool.get("money_column") or "").casefold():
                    continue
                wanted = kpi.get("filter_value")
                wanted = wanted if isinstance(wanted, (list, tuple, set)) else [wanted]
                hit = pool.get("source") == "loss_column" or (
                    str(kpi.get("filter_column") or "").casefold() == str(pool.get("split_column") or "").casefold()
                    and any(str(v).casefold() in values for v in wanted if v is not None))
                if hit:
                    break
            if hit and uc.get("No") not in covering:
                covering.append(uc.get("No"))
        reason = None if covering else ("not_material" if pool.get("material") is False else "uncovered")
        rows.append({"pool_id": pool.get("pool_id"), "candidates": covering, "reason": reason})
    return rows
